var app_ptr: ?*App = null;
var process_start_ms: u64 = 0;

const StartupMilestone = enum(u3) { window, chats, messages, auth };

fn logStartupMilestone(a: *App, milestone: StartupMilestone, label: []const u8) void {
    const bit: u8 = @as(u8, 1) << @intFromEnum(milestone);
    if (a.startup_logged & bit != 0) return;
    a.startup_logged |= bit;
    var buffer: [96]u8 = undefined;
    const line = std.fmt.bufPrint(&buffer, "startup-timing: {s} {d} ms", .{ label, win.GetTickCount64() -% process_start_ms }) catch return;
    appendLaunchLog(a, line);
}

fn lit(comptime text: []const u8) [*:0]const u16 {
    return std.unicode.utf8ToUtf16LeStringLiteral(text);
}

fn loword(value: usize) u16 {
    return @truncate(value & 0xffff);
}

fn hiword(value: usize) u16 {
    return @truncate((value >> 16) & 0xffff);
}

fn controlId(id: usize) win.HMENU {
    return winHandle(win.HMENU, id);
}

fn winHandle(comptime Handle: type, value: usize) Handle {
    @setRuntimeSafety(false);
    return @ptrFromInt(value);
}

fn composerButtonProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    const index: usize = @intCast(@as(usize, @bitCast(win.GetWindowLongPtrW(hwnd, win.GWLP_USERDATA))) - 1);
    switch (message) {
        win.WM_ERASEBKGND => {
            if (a.voice_btn) |button| {
                if (button == hwnd) return 1;
            }
            return 1;
        },
        win.WM_MOUSEMOVE => {
            if (!a.btn_hover[index]) {
                a.btn_hover[index] = true;
                _ = win.InvalidateRect(hwnd, null, win.TRUE);
            }
            var track = win.TRACKMOUSEEVENT{ .cbSize = @sizeOf(win.TRACKMOUSEEVENT), .dwFlags = win.TME_LEAVE, .hwndTrack = hwnd, .dwHoverTime = 0 };
            _ = win.TrackMouseEvent(&track);
        },
        win.WM_MOUSELEAVE => {
            a.btn_hover[index] = false;
            _ = win.InvalidateRect(hwnd, null, win.TRUE);
        },
        win.WM_SETFOCUS, win.WM_KILLFOCUS => {
            _ = win.InvalidateRect(hwnd, null, win.TRUE);
        },
        else => {},
    }
    const prev = a.btn_prev_proc[index];
    return win.CallWindowProcW(@ptrFromInt(prev), hwnd, message, wparam, lparam);
}

fn subclassComposerButton(a: *App, hwnd: ?win.HWND, index: usize) void {
    const window = hwnd orelse return;
    _ = win.SetWindowLongPtrW(window, win.GWLP_USERDATA, @intCast(index + 1));
    const prev = win.SetWindowLongPtrW(window, win.GWLP_WNDPROC, @intCast(@intFromPtr(&composerButtonProc)));
    a.btn_prev_proc[index] = @bitCast(prev);
}

fn composeFieldProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    if (message == win.WM_PASTE) {
        pasteComposerText(a);
        return 0;
    }
    return win.CallWindowProcW(@ptrFromInt(a.compose_prev_proc), hwnd, message, wparam, lparam);
}

fn paintRoundedButton(a: *App, shapes: *const smooth.Context, hdc: win.HDC, rect: win.RECT, face: win.COLORREF, text_color: win.COLORREF, font: win.HFONT, frame: ?win.COLORREF, text: []const u16) void {
    const radius = @min(@min(rect.right - rect.left, rect.bottom - rect.top), px(a, theme.radius_field * 2));
    smooth.fillRoundRect(shapes, rect, radius, radius, face);
    if (frame) |frame_color| smooth.strokeRoundRect(shapes, rect, radius, radius, frame_color, 1);
    if (text.len > 0) {
        _ = win.SetBkMode(hdc, win.TRANSPARENT);
        _ = win.SetTextColor(hdc, text_color);
        _ = win.SelectObject(hdc, @ptrCast(font));
        var label_rect = rect;
        _ = text_draw.drawText(hdc, text.ptr, @intCast(text.len), &label_rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
    }
}

fn paintInputField(a: *App, shapes: *const smooth.Context, hdc: win.HDC, control: win.HWND, rect: win.RECT) void {
    if (a.compose != null and control == a.compose.?) {
        const radius = @min(@min(rect.right - rect.left, rect.bottom - rect.top), px(a, theme.radius_field * 2));
        smooth.fillRoundRect(shapes, rect, radius, radius, theme.current.surface_container_high);
        const border: win.RECT = @bitCast(compose_layout.composerBorderRect(@bitCast(rect)));
        smooth.strokeRoundRect(shapes, border, radius, radius, if (win.GetFocus() == control) theme.current.primary else theme.current.outline, 1);
        return;
    }
    paintRoundedButton(a, shapes, hdc, rect, theme.current.surface_container_high, theme.current.on_surface, a.font.?, if (win.GetFocus() == control) theme.current.primary else theme.current.outline, &.{});
}

fn paintPopupInput(shapes: *const smooth.Context, owner: win.HWND, control: ?win.HWND) void {
    if (theme.choice != .amoled) return;
    const edit = control orelse return;
    var rect: win.RECT = undefined;
    _ = win.GetWindowRect(edit, &rect);
    _ = win.MapWindowPoints(null, owner, @ptrCast(&rect), 2);
    _ = win.InflateRect(&rect, 4, 4);
    smooth.fillRoundRect(shapes, rect, 8, 8, theme.current.surface_container_high);
    smooth.strokeRoundRect(shapes, rect, 8, 8, if (win.GetFocus() == edit) theme.current.primary else theme.current.outline, 1);
}

fn buttonLabel(item: *win.DRAWITEMSTRUCT, buffer: []u16) []const u16 {
    const text_len = win.GetWindowTextW(item.hwndItem, buffer.ptr, @intCast(buffer.len));
    return buffer[0..@intCast(text_len)];
}

fn drawPinIcon(a: *App, shapes: *const smooth.Context, left: i32, top: i32, color: win.COLORREF, unpin: bool) void {
    const scale = @as(f32, @floatFromInt(px(a, 24))) / pin_icon.grid_size;
    const width: f32 = @floatFromInt(@max(1, px(a, @intFromFloat(pin_icon.stroke_width))));
    inline for (.{ pin_icon.outline, pin_icon.needle, pin_icon.slash }, 0..) |points, index| {
        if (index != 2 or unpin) {
            var scaled: [points.len][2]f32 = undefined;
            for (points, &scaled) |point, *target| {
                target.* = .{ @as(f32, @floatFromInt(left)) + point[0] * scale, @as(f32, @floatFromInt(top)) + point[1] * scale };
            }
            smooth.strokePolyline(shapes, &scaled, color, width);
        }
    }
}

fn drawMicIcon(a: *App, shapes: *const smooth.Context, hdc: win.HDC, cx: i32, cy: i32, color: win.COLORREF) void {
    const brush = win.CreateSolidBrush(color) orelse return;
    defer _ = win.DeleteObject(brush);
    const pen = win.CreatePen(win.PS_SOLID, @max(1, px(a, smooth_geometry.icon_stroke_width)), color) orelse return;
    defer _ = win.DeleteObject(pen);
    const old_brush = win.SelectObject(hdc, brush);
    const old_pen = win.SelectObject(hdc, pen);
    defer {
        _ = win.SelectObject(hdc, old_brush);
        _ = win.SelectObject(hdc, old_pen);
    }
    const half = px(a, 4);
    const capsule = win.RECT{ .left = cx - half, .top = cy - px(a, 10), .right = cx + half + 1, .bottom = cy + px(a, 3) };
    smooth.fillRoundRect(shapes, capsule, half * 2, half * 2, color);
    smooth.strokeRoundRect(shapes, capsule, half * 2, half * 2, color, @max(1, px(a, smooth_geometry.icon_stroke_width)));
    _ = win.SelectObject(hdc, win.GetStockObject(win.NULL_BRUSH));
    const arc = px(a, 7);
    const cradle = win.RECT{ .left = cx - arc, .top = cy - px(a, 7), .right = cx + arc + 1, .bottom = cy + px(a, 6) };
    const angles = smooth_geometry.counterclockwiseArc(@bitCast(cradle), .{ cx - arc, cy - px(a, 1) }, .{ cx + arc + 1, cy - px(a, 1) });
    smooth.strokeArc(shapes, cradle, angles.start, angles.sweep, color, @max(1, px(a, smooth_geometry.icon_stroke_width)));
    _ = win.MoveToEx(hdc, cx, cy + px(a, 6), null);
    _ = win.LineTo(hdc, cx, cy + px(a, 10));
    _ = win.MoveToEx(hdc, cx - px(a, 4), cy + px(a, 10), null);
    _ = win.LineTo(hdc, cx + px(a, 5), cy + px(a, 10));
}

fn drawVoiceButton(a: *App, item: *win.DRAWITEMSTRUCT) void {
    const width = item.rcItem.right - item.rcItem.left;
    const height = item.rcItem.bottom - item.rcItem.top;
    if (width <= 0 or height <= 0) return;
    const memory = win.CreateCompatibleDC(item.hDC) orelse return;
    defer _ = win.DeleteDC(memory);
    const bitmap = win.CreateCompatibleBitmap(item.hDC, width, height) orelse return;
    defer _ = win.DeleteObject(bitmap);
    const previous = win.SelectObject(memory, @ptrCast(bitmap));
    defer _ = win.SelectObject(memory, previous);
    var buffered = item.*;
    buffered.hDC = memory;
    buffered.rcItem = .{ .left = 0, .top = 0, .right = width, .bottom = height };
    paintVoiceButton(a, &buffered);
    _ = win.BitBlt(item.hDC, item.rcItem.left, item.rcItem.top, width, height, memory, 0, 0, win.SRCCOPY);
}

fn paintVoiceButton(a: *App, item: *win.DRAWITEMSTRUCT) void {
    var shapes = smooth.Context.init(item.hDC);
    defer shapes.deinit();
    const pressed = (item.itemState & win.ODS_SELECTED) != 0;
    const focused = (item.itemState & win.ODS_FOCUS) != 0;
    const hdc = item.hDC;
    _ = win.FillRect(hdc, &item.rcItem, a.brush_raised.?);
    const recording = a.voice_active;
    const face: win.COLORREF = if (theme.choice == .amoled) (if (pressed) theme.amoled_button_pressed else if (a.btn_hover[8]) theme.amoled_button_hover else theme.current.surface_container_high) else if (pressed) theme.current.primary_container else if (a.btn_hover[8]) theme.current.surface_container_highest else theme.current.surface_container_high;
    const foreground = if (theme.choice == .amoled) theme.amoled_button_text else if (pressed) theme.current.on_primary_container else theme.current.on_secondary_container;
    paintRoundedButton(a, &shapes, hdc, item.rcItem, face, foreground, a.font_bold.?, if (recording) theme.current.@"error" else if (focused) theme.current.primary else if (theme.choice == .amoled and a.btn_hover[8]) theme.current.outline_variant else null, &.{});
    const mid_y = @divTrunc(item.rcItem.top + item.rcItem.bottom, 2);
    if (!recording) {
        drawMicIcon(a, &shapes, hdc, @divTrunc(item.rcItem.left + item.rcItem.right, 2), mid_y, foreground);
        return;
    }
    if (!compose_layout.recordingTimerVisible(@bitCast(item.rcItem), @intCast(a.dpi))) {
        drawMicIcon(a, &shapes, hdc, @divTrunc(item.rcItem.left + item.rcItem.right, 2), mid_y, theme.current.@"error");
        return;
    }
    const dot = px(a, 5);
    const dot_x = item.rcItem.left + px(a, 16);
    smooth.fillEllipse(&shapes, .{ .left = dot_x - dot, .top = mid_y - dot, .right = dot_x + dot, .bottom = mid_y + dot }, theme.current.@"error");
    var seconds: u64 = 0;
    var level: u32 = 0;
    if (a.voice_session) |session| {
        seconds = session.elapsedMs() / 1000;
        level = session.levelPercent();
    }
    var text_utf8: [16]u8 = undefined;
    const label = std.fmt.bufPrint(&text_utf8, "{d}:{d:0>2}", .{ seconds / 60, seconds % 60 }) catch "";
    var wide: [16]u16 = undefined;
    for (label, 0..) |ch, i| wide[i] = ch;
    _ = win.SetBkMode(hdc, win.TRANSPARENT);
    _ = win.SetTextColor(hdc, if (theme.choice == .amoled) foreground else theme.current.on_surface);
    _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
    var text_rect = win.RECT{ .left = dot_x + px(a, 12), .top = item.rcItem.top, .right = dot_x + px(a, 62), .bottom = item.rcItem.bottom };
    _ = text_draw.drawText(hdc, &wide, @intCast(label.len), &text_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER);
    const meter_left = text_rect.right + px(a, 4);
    const meter_right = item.rcItem.right - px(a, 38);
    if (meter_right > meter_left) {
        const meter = win.RECT{ .left = meter_left, .top = mid_y - px(a, 3), .right = meter_right, .bottom = mid_y + px(a, 3) };
        if (win.CreateSolidBrush(theme.current.surface)) |track| {
            defer _ = win.DeleteObject(track);
            _ = win.FillRect(hdc, &meter, track);
        }
        var filled = meter;
        filled.right = meter.left + @divTrunc((meter.right - meter.left) * @as(i32, @intCast(level)), 100);
        if (win.CreateSolidBrush(theme.current.primary)) |fill| {
            defer _ = win.DeleteObject(fill);
            _ = win.FillRect(hdc, &filled, fill);
        }
    }
    drawMicIcon(a, &shapes, hdc, item.rcItem.right - px(a, 20), mid_y, theme.current.@"error");
}

fn drawDictationIcon(a: *App, shapes: *const smooth.Context, cx: i32, cy: i32, color: win.COLORREF) void {
    const left = cx - px(a, 12);
    const top = cy - px(a, 12);
    const stroke = @max(1, px(a, smooth_geometry.icon_stroke_width));
    smooth.fillRoundRect(shapes, .{ .left = left + px(a, 4), .top = top + px(a, 2), .right = left + px(a, 10), .bottom = top + px(a, 14) }, px(a, 6), px(a, 6), color);
    smooth.strokeArc(shapes, .{ .left = left + px(a, 1), .top = top + px(a, 5), .right = left + px(a, 13), .bottom = top + px(a, 19) }, 0, 180, color, stroke);
    inline for (.{
        [2][2]f32{ .{ 7, 19 }, .{ 7, 22 } },
        [2][2]f32{ .{ 4, 22 }, .{ 10, 22 } },
        [2][2]f32{ .{ 17, 6 }, .{ 23, 6 } },
        [2][2]f32{ .{ 17, 12 }, .{ 21, 12 } },
        [2][2]f32{ .{ 17, 18 }, .{ 23, 18 } },
    }) |points| {
        var scaled: [2][2]f32 = undefined;
        const scale = @as(f32, @floatFromInt(px(a, 24))) / 24;
        for (points, &scaled) |point, *target| {
            target.* = .{ @as(f32, @floatFromInt(left)) + point[0] * scale, @as(f32, @floatFromInt(top)) + point[1] * scale };
        }
        smooth.strokePolyline(shapes, &scaled, color, @floatFromInt(stroke));
    }
}

fn drawComposerButton(a: *App, screen_item: *win.DRAWITEMSTRUCT) void {
    var client: win.RECT = undefined;
    _ = win.GetClientRect(screen_item.hwndItem, &client);
    var surface = paint_buffer.Buffer.init(screen_item.hDC, client, screen_item.rcItem);
    defer surface.deinit();
    var buffered = screen_item.*;
    buffered.hDC = surface.hdc;
    const item = &buffered;
    var shapes = smooth.Context.init(item.hDC);
    defer shapes.deinit();
    const index: usize = if (item.CtlID == id_dictate) 0 else if (item.CtlID == id_send) 1 else if (item.CtlID == id_emoji) 2 else 9;
    const disabled = (item.itemState & win.ODS_DISABLED) != 0;
    const pressed = !disabled and (item.itemState & win.ODS_SELECTED) != 0;
    const focused = (item.itemState & win.ODS_FOCUS) != 0;
    const dictating = a.last_dictation_state == .recording or a.last_dictation_state == .transcribing;
    _ = win.FillRect(item.hDC, &item.rcItem, a.brush_raised.?);
    const face: win.COLORREF = if (theme.choice == .amoled) (if (index == 1) (if (pressed) theme.amoled_send_pressed else if (!disabled and a.btn_hover[index]) theme.amoled_send_hover else theme.amoled_send) else if (pressed or (index == 0 and dictating)) theme.amoled_button_pressed else if (!disabled and a.btn_hover[index]) theme.amoled_button_hover else theme.current.surface_container_high) else if (index == 1 and !pressed) theme.current.primary else if (pressed or (index == 0 and dictating)) theme.current.primary_container else if (!disabled and a.btn_hover[index]) theme.current.surface_container_highest else theme.current.surface_container_high;
    const foreground = if (disabled) theme.current.on_surface_variant else if (theme.choice == .amoled) theme.amoled_button_text else if (index == 1 and !pressed) theme.current.on_primary else if (pressed or (index == 0 and dictating)) theme.current.on_primary_container else theme.current.on_surface;
    paintRoundedButton(a, &shapes, item.hDC, item.rcItem, face, foreground, a.font_bold.?, if (focused) theme.current.primary else if (theme.choice == .amoled and (!disabled and a.btn_hover[index])) theme.current.outline_variant else null, &.{});
    if (index == 0) {
        drawDictationIcon(a, &shapes, @divTrunc(item.rcItem.left + item.rcItem.right, 2), @divTrunc(item.rcItem.top + item.rcItem.bottom, 2), foreground);
        return;
    }
    const cx: f32 = @floatFromInt(@divTrunc(item.rcItem.left + item.rcItem.right, 2));
    const cy: f32 = @floatFromInt(@divTrunc(item.rcItem.top + item.rcItem.bottom, 2));
    const unit = @as(f32, @floatFromInt(px(a, 24))) / 24;
    const stroke: f32 = @floatFromInt(@max(1, px(a, smooth_geometry.icon_stroke_width)));
    if (index == 9) {
        smooth.strokePolyline(&shapes, &.{ .{ cx - 8 * unit, cy }, .{ cx + 8 * unit, cy } }, foreground, stroke);
        smooth.strokePolyline(&shapes, &.{ .{ cx, cy - 8 * unit }, .{ cx, cy + 8 * unit } }, foreground, stroke);
    } else if (index == 1) {
        smooth.strokePolyline(&shapes, &.{ .{ cx - 7 * unit, cy + 7 * unit }, .{ cx + 7 * unit, cy - 7 * unit }, .{ cx - 5 * unit, cy - 7 * unit } }, foreground, stroke);
        smooth.strokePolyline(&shapes, &.{ .{ cx + 7 * unit, cy - 7 * unit }, .{ cx + 7 * unit, cy + 5 * unit } }, foreground, stroke);
    } else {
        const x: i32 = @intFromFloat(cx);
        const y: i32 = @intFromFloat(cy);
        const radius = px(a, 10);
        const circle = win.RECT{ .left = x - radius, .top = y - radius, .right = x + radius, .bottom = y + radius };
        smooth.strokeArc(&shapes, circle, 0, 360, foreground, @intFromFloat(stroke));
        for ([_]i32{ -1, 1 }) |side| {
            const eye = x + side * px(a, 3);
            smooth.fillEllipse(&shapes, .{ .left = eye - px(a, 1), .top = y - px(a, 4), .right = eye + px(a, 1), .bottom = y - px(a, 2) }, foreground);
        }
        smooth.strokeArc(&shapes, .{ .left = x - px(a, 5), .top = y - px(a, 3), .right = x + px(a, 5), .bottom = y + px(a, 6) }, 20, 140, foreground, @intFromFloat(stroke));
    }
}

fn drawSetupButton(a: *App, item: *win.DRAWITEMSTRUCT) void {
    var shapes = smooth.Context.init(item.hDC);
    defer shapes.deinit();
    const index: usize = switch (item.CtlID) {
        id_slack_save => 3,
        id_slack_cancel => 4,
        id_tg_next => 5,
        id_tg_cancel => 6,
        id_tg_open_page => 7,
        id_include_archived => 10,
        else => return,
    };
    const pressed = (item.itemState & win.ODS_SELECTED) != 0 or (item.CtlID == id_include_archived and a.include_archived);
    const focused = (item.itemState & win.ODS_FOCUS) != 0;
    _ = win.FillRect(item.hDC, &item.rcItem, a.brush_panel.?);
    const face: win.COLORREF = if (theme.choice == .amoled) (if (pressed) theme.amoled_button_pressed else if (a.btn_hover[index]) theme.amoled_button_hover else theme.amoled_button) else if (pressed) theme.current.primary_container else if (a.btn_hover[index]) theme.current.secondary_container else theme.current.surface_container_high;
    const frame: ?win.COLORREF = if (index == 3 or index == 5 or focused) theme.current.primary else if (theme.choice == .amoled) theme.current.outline_variant else null;
    var text_buffer: [32]u16 = undefined;
    paintRoundedButton(a, &shapes, item.hDC, item.rcItem, face, if (!pressed and a.btn_hover[index] and theme.choice == .amoled) theme.current.on_secondary_container else theme.current.on_surface, a.font_bold.?, frame, buttonLabel(item, &text_buffer));
}

fn setFont(hwnd: ?win.HWND, font: ?win.HFONT) void {
    if (hwnd) |window| {
        _ = win.SendMessageW(window, win.WM_SETFONT, if (font) |value| @intFromPtr(value) else 0, 1);
    }
}

const tooltip_info_size = @offsetOf(win.TOOLINFOW, "lParam") + @sizeOf(win.LPARAM);

fn addTooltip(a: *App, tt: win.HWND, tool: ?win.HWND, text: [*:0]const u16) void {
    const target = tool orelse return;
    var info = win.TOOLINFOW{
        .cbSize = tooltip_info_size,
        .uFlags = win.TTF_IDISHWND | win.TTF_SUBCLASS,
        .hwnd = win.GetParent(target),
        .uId = @intFromPtr(target),
        .lpszText = @constCast(text),
    };
    if (win.SendMessageW(tt, win.TTM_ADDTOOLW, 0, @as(win.LPARAM, @bitCast(@intFromPtr(&info)))) == 0) {
        appendLaunchLog(a, "tooltip: TTM_ADDTOOLW failed for window");
    }
}

fn updateChatTooltip(a: *App, coords: win.LPARAM) void {
    const list = a.chats_hwnd orelse return;
    const tt = a.tooltips orelse return;
    const hit: usize = @bitCast(win.SendMessageW(list, win.LB_ITEMFROMPOINT, 0, coords));
    var text: []const u8 = "Chats";
    if (hiword(hit) == 0 and loword(hit) < a.chat_count) {
        const chat = &a.chats[loword(hit)];
        for (a.views.items) |*view| {
            if (messenger_view.accountMatches(messenger_view.providerView(chat.provider), chatViewKey(chat).account, view.key.key())) {
                text = view.labelText();
                break;
            }
        }
    }
    var wide = WideText(255){};
    wide.set(a.allocator, text);
    if (std.mem.eql(u16, wide.slice(), a.chat_tooltip.slice())) return;
    a.chat_tooltip = wide;
    var info = win.TOOLINFOW{
        .cbSize = tooltip_info_size,
        .uFlags = win.TTF_IDISHWND | win.TTF_SUBCLASS,
        .hwnd = win.GetParent(list),
        .uId = @intFromPtr(list),
        .lpszText = @constCast(a.chat_tooltip.ptr()),
    };
    _ = win.SendMessageW(tt, win.TTM_UPDATETIPTEXTW, 0, @bitCast(@intFromPtr(&info)));
}

fn updateTooltipTheme(a: *App) void {
    const tt = a.tooltips orelse return;
    const module = win.LoadLibraryW(lit("uxtheme.dll")) orelse return;
    defer _ = win.FreeLibrary(module);
    const raw = win.GetProcAddress(module, "SetWindowTheme") orelse return;
    const set_window_theme: *const fn (win.HWND, ?[*:0]const u16, ?[*:0]const u16) callconv(.winapi) win.HRESULT = @ptrCast(@alignCast(raw));
    const disable = if (theme.choice == .amoled) lit("") else null;
    _ = set_window_theme(tt, disable, disable);
    _ = win.SendMessageW(tt, win.TTM_SETTIPBKCOLOR, if (theme.choice == .amoled) theme.current.surface_container_high else win.GetSysColor(win.COLOR_INFOBK), 0);
    _ = win.SendMessageW(tt, win.TTM_SETTIPTEXTCOLOR, if (theme.choice == .amoled) theme.current.on_surface else win.GetSysColor(win.COLOR_INFOTEXT), 0);
}

fn createTooltips(a: *App, hwnd: win.HWND) void {
    const tt = win.CreateWindowExW(
        win.WS_EX_TOPMOST,
        lit("tooltips_class32"),
        null,
        win.WS_POPUP | win.TTS_NOPREFIX,
        0,
        0,
        0,
        0,
        hwnd,
        null,
        a.instance,
        null,
    ) orelse return;
    a.tooltips = tt;
    updateTooltipTheme(a);
    _ = win.SendMessageW(tt, 0x400 + 24, 0, 260);
    addTooltip(a, tt, a.include_archived_button, lit("Show archived  Alt+A"));
    addTooltip(a, tt, a.search, lit("Search chats  Ctrl+F or /"));
    addTooltip(a, tt, a.chats_hwnd, lit("Chats  ↑/↓ move · Ctrl+Tab next chat"));
    addTooltip(a, tt, a.canvas, lit("Messages  Alt+J/K select · Ctrl+P play voice · Ctrl+T transcript · Ctrl+R react"));
    addTooltip(a, tt, a.compose, lit("Message box  Enter sends · Shift+Enter new line"));
    addTooltip(a, tt, a.dictate, lit("Dictate  Ctrl+D"));
    addTooltip(a, tt, a.send, lit("Send message  Enter"));
    addTooltip(a, tt, a.emoji_btn, lit("Emoji menu"));
    addTooltip(a, tt, a.voice_btn, lit("Record a voice note  Enter sends · Esc cancels"));
    addTooltip(a, tt, a.attach_btn, lit("Attach photo or file"));
    var attach_info = win.TOOLINFOW{
        .cbSize = tooltip_info_size,
        .uFlags = win.TTF_SUBCLASS,
        .hwnd = hwnd,
        .uId = id_attach,
        .lpszText = @constCast(a.attach_tooltip.ptr()),
    };
    if (win.SendMessageW(tt, win.TTM_ADDTOOLW, 0, @bitCast(@intFromPtr(&attach_info))) == 0) {
        appendLaunchLog(a, "tooltip: TTM_ADDTOOLW failed for attachment rectangle");
    }
    updateAttachButton(a);
}

fn attachUnavailableReason(a: *App) ?[]const u8 {
    if (a.selected_chat >= a.chat_count) return "Select a chat first";
    if (unifiedHub(a) or a.chats[a.selected_chat].provider == .whatsapp) return null;
    if (selectedChatIsSlack(a)) {
        if (slackAccountIsBridge(a, a.chats[a.selected_chat].account.slice())) return "File upload not available over the Slack bridge";
        return null;
    }
    if (selectedChatIsTelegram(a)) return null;
    return "Open a Slack or Telegram chat first";
}

fn updateAttachButton(a: *App) void {
    const button = a.attach_btn orelse return;
    const reason = attachUnavailableReason(a);
    if ((win.IsWindowEnabled(button) != 0) != (reason == null)) {
        _ = win.EnableWindow(button, if (reason == null) win.TRUE else win.FALSE);
        _ = win.InvalidateRect(button, null, win.TRUE);
    }
    const tt = a.tooltips orelse return;
    const owner = a.hwnd orelse return;
    a.attach_tooltip.len = std.unicode.utf8ToUtf16Le(&a.attach_tooltip.buf, reason orelse "Attach photo or file") catch 0;
    a.attach_tooltip.buf[a.attach_tooltip.len] = 0;
    var info = win.TOOLINFOW{
        .cbSize = tooltip_info_size,
        .hwnd = owner,
        .uId = id_attach,
        .rect = if (reason != null) @bitCast(a.compose_geometry.attach) else std.mem.zeroes(win.RECT),
        .lpszText = @constCast(a.attach_tooltip.ptr()),
    };
    _ = win.SendMessageW(tt, win.TTM_NEWTOOLRECTW, 0, @bitCast(@intFromPtr(&info)));
    _ = win.SendMessageW(tt, win.TTM_UPDATETIPTEXTW, 0, @bitCast(@intFromPtr(&info)));
}

fn updateDictateButton(a: *App, state: dictation.State) void {
    a.last_dictation_state = state;
    const button = a.dictate orelse return;
    _ = win.InvalidateRect(button, null, win.TRUE);
}

fn loadRegistryString(allocator: std.mem.Allocator, name: [*:0]const u16) ?[]const u8 {
    var size: win.DWORD = 0;
    if (win.RegGetValueW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), name, win.RRF_RT_REG_SZ, null, null, &size) != win.ERROR_SUCCESS or size < 2 or size > 64 * 1024) return null;
    const wide = allocator.alloc(u16, (size + 1) / 2) catch return null;
    defer allocator.free(wide);
    if (win.RegGetValueW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), name, win.RRF_RT_REG_SZ, null, wide.ptr, &size) != win.ERROR_SUCCESS) return null;
    const char_count = @min(wide.len, size / 2);
    return std.unicode.utf16LeToUtf8Alloc(allocator, std.mem.trimEnd(u16, wide[0..char_count], &.{0})) catch null;
}

fn saveRegistryString(allocator: std.mem.Allocator, name: [*:0]const u16, text: []const u8) bool {
    const wide = std.unicode.utf8ToUtf16LeAllocZ(allocator, text) catch return false;
    defer allocator.free(wide);
    var key: win.HKEY = null;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, null) != win.ERROR_SUCCESS) return false;
    defer _ = win.RegCloseKey(key);
    return win.RegSetValueExW(key, name, 0, win.REG_SZ, @ptrCast(wide.ptr), @intCast((wide.len + 1) * 2)) == win.ERROR_SUCCESS;
}

fn loadTheme() theme.Choice {
    var value: win.DWORD = 0;
    var size: win.DWORD = @sizeOf(win.DWORD);
    const result = win.RegGetValueW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), lit("Theme"), win.RRF_RT_REG_DWORD, null, &value, &size);
    return theme.choiceFromSaved(if (result == win.ERROR_SUCCESS) value else null);
}

const window_rect_names = [_][*:0]const u16{ lit("WindowLeft"), lit("WindowTop"), lit("WindowRight"), lit("WindowBottom") };

fn validWindowRect(rect: win.RECT) bool {
    const width = @as(i64, rect.right) - rect.left;
    const height = @as(i64, rect.bottom) - rect.top;
    return width > 0 and width <= std.math.maxInt(i32) and height > 0 and height <= std.math.maxInt(i32);
}

fn loadWindowRect() ?win.RECT {
    var values: [4]win.DWORD = undefined;
    for (window_rect_names, &values) |name, *value| {
        var size: win.DWORD = @sizeOf(win.DWORD);
        if (win.RegGetValueW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), name, win.RRF_RT_REG_DWORD, null, value, &size) != win.ERROR_SUCCESS) return null;
    }
    const rect: win.RECT = .{ .left = @bitCast(values[0]), .top = @bitCast(values[1]), .right = @bitCast(values[2]), .bottom = @bitCast(values[3]) };
    if (!validWindowRect(rect) or win.MonitorFromRect(&rect, win.MONITOR_DEFAULTTONULL) == null) return null;
    return rect;
}

fn saveWindowRect(hwnd: win.HWND) void {
    var placement: win.WINDOWPLACEMENT = std.mem.zeroes(win.WINDOWPLACEMENT);
    placement.length = @sizeOf(win.WINDOWPLACEMENT);
    if (win.GetWindowPlacement(hwnd, &placement) == 0 or !validWindowRect(placement.rcNormalPosition)) return;
    var key: win.HKEY = null;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, null) != win.ERROR_SUCCESS) return;
    defer _ = win.RegCloseKey(key);
    const rect = placement.rcNormalPosition;
    const values = [_]win.DWORD{ @bitCast(rect.left), @bitCast(rect.top), @bitCast(rect.right), @bitCast(rect.bottom) };
    for (window_rect_names, &values) |name, *value| {
        _ = win.RegSetValueExW(key, name, 0, win.REG_DWORD, @ptrCast(value), @sizeOf(win.DWORD));
    }
}

fn loadFontScale() i32 {
    var value: win.DWORD = 82;
    var size: win.DWORD = @sizeOf(win.DWORD);
    const result = win.RegGetValueW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), lit("FontScale"), win.RRF_RT_REG_DWORD, null, &value, &size);
    if (result != win.ERROR_SUCCESS) return 82;
    return std.math.clamp(@as(i32, @intCast(value)), 60, 160);
}

fn loadDictationLanguage() dictation.Language {
    var value: win.DWORD = 0;
    var size: win.DWORD = @sizeOf(win.DWORD);
    const result = win.RegGetValueW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), lit("DictationLanguage"), win.RRF_RT_REG_DWORD, null, &value, &size);
    if (result != win.ERROR_SUCCESS or value > 2) return .automatic;
    return @enumFromInt(value);
}

fn isChatPinned(a: *const App, key: chat_key.Key) bool {
    for (a.pins[0..a.pin_count]) |*pin| if (chat_key.Key.eql(pin.key(), key)) return true;
    return false;
}

fn addPin(a: *App, key: chat_key.Key) void {
    if (key.id.len == 0 or key.id.len > 190 or a.pin_count >= a.pins.len or isChatPinned(a, key)) return;
    a.pins[a.pin_count].set(key);
    a.pin_count += 1;
}

fn loadPins(a: *App) bool {
    const stored = loadRegistryString(a.allocator, lit("PinnedChats")) orelse return false;
    defer a.allocator.free(stored);
    var lines = std.mem.tokenizeScalar(u8, stored, '\n');
    while (lines.next()) |line| {
        var fields = std.mem.splitScalar(u8, line, '\t');
        const first = fields.next() orelse continue;
        if (std.meta.stringToEnum(transport.Provider, first)) |provider| {
            const account = fields.next() orelse continue;
            const id = fields.next() orelse continue;
            addPin(a, .{ .provider = provider, .account = account, .id = id });
        } else addPin(a, .{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = line });
    }
    return true;
}

fn savePins(a: *App) bool {
    var text = std.ArrayList(u8).empty;
    defer text.deinit(a.allocator);
    for (a.pins[0..a.pin_count]) |*pin| {
        const key = pin.key();
        const line = std.fmt.allocPrint(a.allocator, "{s}\t{s}\t{s}\n", .{ @tagName(key.provider), key.account, key.id }) catch return false;
        defer a.allocator.free(line);
        text.appendSlice(a.allocator, line) catch return false;
    }
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, text.items) catch return false;
    defer a.allocator.free(wide);
    var key: win.HKEY = null;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, null) != win.ERROR_SUCCESS) return false;
    defer _ = win.RegCloseKey(key);
    return win.RegSetValueExW(key, lit("PinnedChats"), 0, win.REG_SZ, @ptrCast(wide.ptr), @intCast((wide.len + 1) * 2)) == win.ERROR_SUCCESS;
}

fn togglePinSelected(a: *App) void {
    if (a.selected_chat >= a.chat_count) {
        setStatus(a, "Select a chat to pin");
        return;
    }
    const key = chat_key.of(&a.chats[a.selected_chat]);
    if (isChatPinned(a, key)) {
        var index: usize = 0;
        while (index < a.pin_count) : (index += 1) {
            if (chat_key.Key.eql(a.pins[index].key(), key)) break;
        }
        if (index < a.pin_count) {
            while (index + 1 < a.pin_count) : (index += 1) a.pins[index] = a.pins[index + 1];
            a.pin_count -= 1;
        }
        if (!savePins(a)) {
            addPin(a, key);
            setStatus(a, "Could not save pin");
            return;
        }
        setStatus(a, "Chat unpinned");
    } else {
        if (a.pin_count >= a.pins.len) {
            setStatus(a, "Pin limit reached (16 chats)");
            return;
        }
        const before = a.pin_count;
        addPin(a, key);
        if (a.pin_count == before) return;
        if (!savePins(a)) {
            a.pin_count -= 1;
            setStatus(a, "Could not save pin");
            return;
        }
        setStatus(a, "Chat pinned to top");
    }
    refreshVisibleChats(a);
}

