fn recreateThemeBrushes(a: *App) bool {
    const bg = win.CreateSolidBrush(theme.current.surface) orelse return false;
    const panel = win.CreateSolidBrush(theme.current.surface_container_low) orelse {
        _ = win.DeleteObject(bg);
        return false;
    };
    const raised = win.CreateSolidBrush(theme.current.surface_container_high) orelse {
        _ = win.DeleteObject(bg);
        _ = win.DeleteObject(panel);
        return false;
    };
    const muted = win.CreateSolidBrush(theme.current.outline) orelse {
        _ = win.DeleteObject(bg);
        _ = win.DeleteObject(panel);
        _ = win.DeleteObject(raised);
        return false;
    };
    if (a.brush_bg) |brush| _ = win.DeleteObject(brush);
    if (a.brush_panel) |brush| _ = win.DeleteObject(brush);
    if (a.brush_raised) |brush| _ = win.DeleteObject(brush);
    if (a.brush_muted) |brush| _ = win.DeleteObject(brush);
    a.brush_bg = bg;
    a.brush_panel = panel;
    a.brush_raised = raised;
    a.brush_muted = muted;
    return true;
}

fn redrawThemeWindow(hwnd: win.HWND, _: win.LPARAM) callconv(.winapi) win.BOOL {
    _ = win.RedrawWindow(hwnd, null, null, win.RDW_INVALIDATE | win.RDW_ERASE | win.RDW_FRAME | win.RDW_ALLCHILDREN | win.RDW_UPDATENOW);
    return win.TRUE;
}

var menu_theme_module: win.HMODULE = null;

fn applyTheme(choice: theme.Choice) void {
    theme.set(choice);
    const module = menu_theme_module orelse blk: {
        const loaded = win.LoadLibraryW(lit("uxtheme.dll")) orelse return;
        menu_theme_module = loaded;
        break :blk loaded;
    };
    if (win.GetProcAddress(module, @ptrFromInt(135))) |raw| {
        const set_preferred_app_mode: *const fn (menu_theme.PreferredAppMode) callconv(.winapi) menu_theme.PreferredAppMode = @ptrCast(@alignCast(raw));
        _ = set_preferred_app_mode(menu_theme.preferredAppMode(choice));
    }
    if (win.GetProcAddress(module, @ptrFromInt(136))) |raw| {
        const flush_menu_themes: *const fn () callconv(.winapi) void = @ptrCast(@alignCast(raw));
        flush_menu_themes();
    }
}

fn changeTheme(a: *App, choice: theme.Choice) bool {
    const previous = theme.choice;
    applyTheme(choice);
    if (!recreateThemeBrushes(a)) {
        applyTheme(previous);
        setStatus(a, "Could not change theme");
        return false;
    }
    saveTheme(choice);
    updateTooltipTheme(a);
    for ([_]?win.HWND{ a.slack_setup_window, a.tg_login_window }) |window| {
        const hwnd = window orelse continue;
        var dark: win.BOOL = if (choice == .amoled) win.TRUE else win.FALSE;
        _ = win.DwmSetWindowAttribute(hwnd, 20, &dark, @sizeOf(win.BOOL));
    }
    setStatus(a, if (choice == .amoled) "Theme: AMOLED black" else "Theme: Green");
    _ = win.EnumThreadWindows(win.GetCurrentThreadId(), redrawThemeWindow, 0);
    return true;
}

fn fieldColor() win.COLORREF {
    return if (theme.choice == .amoled) theme.current.surface else theme.current.surface_container_high;
}

fn saveFontScale(scale: i32) void {
    var key: win.HKEY = null;
    var disposition: win.DWORD = 0;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, &disposition) != win.ERROR_SUCCESS) return;
    defer _ = win.RegCloseKey(key);
    const value: win.DWORD = @intCast(scale);
    _ = win.RegSetValueExW(key, lit("FontScale"), 0, win.REG_DWORD, @ptrCast(&value), @sizeOf(win.DWORD));
}

fn px(a: *const App, v: i32) i32 {
    const dpi: i32 = @intCast(a.dpi);
    return @divTrunc(v * dpi + 48, 96);
}

fn scaledFontHeight(base: i32, scale: i32, dpi: i32) i32 {
    return -@divTrunc(base * scale * dpi + 4800, 9600);
}

fn recreateFonts(a: *App) void {
    const body_weight = @import("font_config.zig").body_weight;
    comptime std.debug.assert(body_weight == win.FW_MEDIUM);
    const dpi: i32 = @intCast(a.dpi);
    const old_font = a.font;
    const old_small = a.font_small;
    const old_bold = a.font_bold;
    const old_underline = a.font_underline;
    const old_emoji = a.font_emoji;
    a.font = win.CreateFontW(scaledFontHeight(17, a.font_scale, dpi), 0, 0, 0, body_weight, 0, 0, 0, win.DEFAULT_CHARSET, win.OUT_DEFAULT_PRECIS, win.CLIP_DEFAULT_PRECIS, win.CLEARTYPE_NATURAL_QUALITY, win.DEFAULT_PITCH, lit("IBM Plex Sans"));
    a.font_small = win.CreateFontW(scaledFontHeight(13, a.font_scale, dpi), 0, 0, 0, body_weight, 0, 0, 0, win.DEFAULT_CHARSET, win.OUT_DEFAULT_PRECIS, win.CLIP_DEFAULT_PRECIS, win.CLEARTYPE_NATURAL_QUALITY, win.DEFAULT_PITCH, lit("IBM Plex Sans"));
    a.font_bold = win.CreateFontW(scaledFontHeight(16, a.font_scale, dpi), 0, 0, 0, win.FW_SEMIBOLD, 0, 0, 0, win.DEFAULT_CHARSET, win.OUT_DEFAULT_PRECIS, win.CLIP_DEFAULT_PRECIS, win.CLEARTYPE_NATURAL_QUALITY, win.DEFAULT_PITCH, lit("IBM Plex Sans"));
    a.font_emoji = win.CreateFontW(scaledFontHeight(16, a.font_scale, dpi), 0, 0, 0, win.FW_NORMAL, 0, 0, 0, win.DEFAULT_CHARSET, win.OUT_DEFAULT_PRECIS, win.CLIP_DEFAULT_PRECIS, win.CLEARTYPE_NATURAL_QUALITY, win.DEFAULT_PITCH, lit("Segoe UI Emoji"));
    a.font_underline = win.CreateFontW(scaledFontHeight(17, a.font_scale, dpi), 0, 0, 0, body_weight, 0, 1, 0, win.DEFAULT_CHARSET, win.OUT_DEFAULT_PRECIS, win.CLIP_DEFAULT_PRECIS, win.CLEARTYPE_NATURAL_QUALITY, win.DEFAULT_PITCH, lit("IBM Plex Sans"));
    setFont(a.include_archived_button, a.font_bold);
    setFont(a.search, a.font);
    setFont(a.chats_hwnd, a.font);
    setFont(a.compose, a.font);
    setFont(a.thread_list, a.font);
    setFont(a.thread_compose, a.font);
    setFont(a.dictate, a.font_bold);
    setFont(a.send, a.font_bold);
    setFont(a.emoji_btn, a.font_emoji);
    setFont(a.status, a.font_small);
    setFont(a.palette_edit, a.font);
    setFont(a.palette_list, a.font);
    setFont(a.emoji_edit, a.font);
    if (old_font) |font| _ = win.DeleteObject(font);
    if (old_small) |font| _ = win.DeleteObject(font);
    if (old_bold) |font| _ = win.DeleteObject(font);
    if (old_underline) |font| _ = win.DeleteObject(font);
    if (old_emoji) |font| _ = win.DeleteObject(font);
    if (a.hwnd) |hwnd| _ = win.InvalidateRect(hwnd, null, win.FALSE);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn changeFontScale(a: *App, delta: i32) void {
    const next = std.math.clamp(a.font_scale + delta, 60, 160);
    if (next == a.font_scale) return;
    a.font_scale = next;
    text_draw.reset();
    recreateFonts(a);
    saveFontScale(next);
    var buffer: [48]u8 = undefined;
    setStatus(a, std.fmt.bufPrint(&buffer, "Font size {d}%", .{next}) catch "Font size changed");
}

fn getString(object: std.json.ObjectMap, key: []const u8) []const u8 {
    const value = object.get(key) orelse return "";
    return switch (value) {
        .string => |text| text,
        else => "",
    };
}

fn getBool(object: std.json.ObjectMap, key: []const u8) bool {
    const value = object.get(key) orelse return false;
    return switch (value) {
        .bool => |flag| flag,
        else => false,
    };
}

fn getInt(object: std.json.ObjectMap, key: []const u8) i64 {
    const value = object.get(key) orelse return 0;
    return switch (value) {
        .integer => |number| number,
        else => 0,
    };
}

const QuoteParts = struct { quote: []const u8, body: []const u8 };

fn splitQuote(display: []const u8, reply: []const u8) ?QuoteParts {
    if (reply.len == 0) return null;
    if (display.len < 2 or !std.mem.startsWith(u8, display, "> ")) return null;
    if (!std.mem.endsWith(u8, display, reply)) return null;
    const separator = display.len - reply.len - 1;
    if (separator < 2 or display[separator] != '\n') return null;
    return .{ .quote = display[2..separator], .body = reply };
}

test "sendBaseText labels voice notes, bare images and captions" {
    var buffer: [48]u8 = undefined;
    try std.testing.expectEqualStrings("Voice message 1:05", sendBaseText(&buffer, "", true, true, 65));
    try std.testing.expectEqualStrings("Image", sendBaseText(&buffer, "", true, false, 0));
    try std.testing.expectEqualStrings("hello", sendBaseText(&buffer, "hello", true, false, 0));
    try std.testing.expectEqualStrings("hi", sendBaseText(&buffer, "hi", false, false, 0));
}

test "splitQuote recovers a normal reply" {
    const parts = splitQuote("> earlier message\nmy reply", "my reply").?;
    try std.testing.expectEqualStrings("earlier message", parts.quote);
    try std.testing.expectEqualStrings("my reply", parts.body);
}

test "splitQuote keeps newlines inside the quoted text" {
    const display = "> first line\nsecond line\nmy reply";
    const parts = splitQuote(display, "my reply").?;
    try std.testing.expectEqualStrings("first line\nsecond line", parts.quote);
    try std.testing.expectEqualStrings("my reply", parts.body);
}

test "splitQuote rejects plain messages and mismatched replies" {
    try std.testing.expect(splitQuote("not a reply", "not a reply") == null);
    try std.testing.expect(splitQuote("just some text", "text") == null);
    try std.testing.expect(splitQuote("> quoted\nreal reply", "other reply") == null);
    try std.testing.expect(splitQuote("> quoted\nreal reply", "") == null);
    try std.testing.expect(splitQuote("> quoted\nreal reply", "reply") == null);
}

fn wacliJobArgs(job: *WacliJob, args: []const []const u8) void {
    job.arg_count = @min(args.len, max_wacli_args);
    for (args[0..job.arg_count], 0..) |argument, index| job.args[index].set(argument);
}

fn wacliPendingGet(a: *App, kind: WacliJobKind) u32 {
    a.wacli_mutex.lockUncancelable(a.io);
    const value = a.wacli_pending[@intFromEnum(kind)];
    a.wacli_mutex.unlock(a.io);
    return value;
}

fn wacliPendingSub(a: *App, kind: WacliJobKind) void {
    a.wacli_mutex.lockUncancelable(a.io);
    if (a.wacli_pending[@intFromEnum(kind)] > 0) a.wacli_pending[@intFromEnum(kind)] -= 1;
    a.wacli_mutex.unlock(a.io);
}

fn jobIsWrite(kind: WacliJobKind) bool {
    return switch (kind) {
        .reaction, .slack_send, .slack_attach, .slack_share => true,
        .hub_send, .hub_read, .hub_archive, .hub_media, .hub_avatar => true,
        else => false,
    };
}

fn wacliEnqueue(a: *App, job: WacliJob, urgent: bool) bool {
    if (verification_fixture and !hubConfigured(a)) return verificationEnqueue(a, job);
    if (hubConfigured(a) and !hubJobReady(a, job)) return false;
    if (job.kind == .hub_media or job.kind == .hub_avatar) {
        if (a.hub_media_thread == null) {
            setStatus(a, "Media worker unavailable; restart Messages");
            return false;
        }
    }
    var queued_job = job;
    if (hubConfigured(a) and (unifiedHub(a) or job.provider == .whatsapp)) queued_job.hub_account = a.hub_account;
    if (jobIsSlack(job.kind) and a.wacli_slack_thread == null) {
        setStatus(a, "Slack worker unavailable; restart Messages");
        return false;
    }
    a.wacli_mutex.lockUncancelable(a.io);
    if (a.wacli_queue_len >= a.wacli_queue.len) {
        if (job.kind == .slack_mark) {
            a.wacli_mutex.unlock(a.io);
            cancelSlackMark(a);
            logSlackFailure(a, job.kind, "QueueFull", 0);
            return false;
        }
        var keep: [wacli_queue_size]bool = [_]bool{false} ** wacli_queue_size;
        for (a.wacli_queue[0..a.wacli_queue_len], 0..) |queued, queued_index| keep[queued_index] = jobIsWrite(queued.kind);
        const victim = outbox.evictionVictim(keep[0..a.wacli_queue_len]) orelse {
            if (!jobIsWrite(job.kind)) a.wacli_refresh_again = true;
            a.wacli_mutex.unlock(a.io);
            if (a.wacli_thread == null or (jobIsSlack(job.kind) and a.wacli_slack_thread == null)) wacliPumpSync(a);
            return false;
        };
        a.wacli_pending[@intFromEnum(a.wacli_queue[victim].kind)] -= 1;
        var shift = victim;
        while (shift + 1 < a.wacli_queue_len) : (shift += 1) a.wacli_queue[shift] = a.wacli_queue[shift + 1];
        a.wacli_queue_len -= 1;
    }
    if (urgent) {
        var insert: usize = 0;
        while (insert < a.wacli_queue_len and
            (a.wacli_queue[insert].kind == .slack_send or a.wacli_queue[insert].kind == .slack_attach or a.wacli_queue[insert].kind == .slack_share or a.wacli_queue[insert].kind == .reaction)) insert += 1;
        var shift = a.wacli_queue_len;
        while (shift > insert) : (shift -= 1) a.wacli_queue[shift] = a.wacli_queue[shift - 1];
        a.wacli_queue[insert] = queued_job;
    } else {
        a.wacli_queue[a.wacli_queue_len] = queued_job;
    }
    a.wacli_queue_len += 1;
    a.wacli_pending[@intFromEnum(job.kind)] += 1;
    a.wacli_cond.broadcast(a.io);
    a.wacli_mutex.unlock(a.io);
    if (a.wacli_thread == null or (jobIsSlack(job.kind) and a.wacli_slack_thread == null)) wacliPumpSync(a);
    return true;
}

fn retryWacliRefreshes(a: *App) void {
    a.wacli_mutex.lockUncancelable(a.io);
    const retry = a.wacli_refresh_again and a.wacli_queue_len == 0;
    if (retry) a.wacli_refresh_again = false;
    a.wacli_mutex.unlock(a.io);
    if (!retry) return;
    refreshGroups(a);
    refreshChats(a);
    refreshMessages(a);
    if (slackConfigured(a)) {
        refreshSlackWorkspace(a);
    }
    enqueueCacheTagProbe(a);
}

fn wacliPumpSync(a: *App) void {
    while (true) {
        a.wacli_mutex.lockUncancelable(a.io);
        const pump_wacli = a.wacli_thread == null;
        const pump_slack = a.wacli_slack_thread == null;
        if (a.wacli_queue_len == 0 or (!pump_wacli and !pump_slack)) {
            a.wacli_mutex.unlock(a.io);
            return;
        }
        const job = if (pump_wacli) wacliTakeJob(a, .wacli) else null;
        const chosen = job orelse (if (pump_slack) wacliTakeJob(a, .slack) else null);
        if (chosen == null) {
            a.wacli_mutex.unlock(a.io);
            return;
        }
        a.wacli_mutex.unlock(a.io);
        wacliRunJob(a, chosen.?);
    }
}

fn wacliShutdown(a: *App) void {
    a.wacli_mutex.lockUncancelable(a.io);
    a.wacli_quit = true;
    a.wacli_cond.broadcast(a.io);
    a.wacli_mutex.unlock(a.io);
    if (a.wacli_thread) |thread| thread.join();
    a.wacli_thread = null;
    if (a.wacli_slack_thread) |thread| thread.join();
    a.wacli_slack_thread = null;
    if (a.hub_media_thread) |thread| thread.join();
    a.hub_media_thread = null;
    for (a.msg_cache[0..a.msg_cache_len]) |*entry| {
        if (entry.data) |data| a.allocator.free(data);
        entry.data = null;
    }
    a.msg_cache_len = 0;
}

fn jobIsSlack(kind: WacliJobKind) bool {
    return switch (kind) {
        .slack_workspace, .slack_users, .slack_history, .slack_replies, .slack_send, .slack_attach, .slack_share, .slack_download, .slack_auth, .slack_mark => true,
        else => false,
    };
}

fn wacliTakeJob(a: *App, lane: WacliLane) ?WacliJob {
    var index: usize = 0;
    while (index < a.wacli_queue_len) : (index += 1) {
        const kind = a.wacli_queue[index].kind;
        const job_lane: WacliLane = if (jobIsSlack(kind)) .slack else if (kind == .hub_media or kind == .hub_avatar) .hub_media else .wacli;
        if (job_lane != lane) continue;
        const job = a.wacli_queue[index];
        var shift = index;
        while (shift + 1 < a.wacli_queue_len) : (shift += 1) a.wacli_queue[shift] = a.wacli_queue[shift + 1];
        a.wacli_queue_len -= 1;
        return job;
    }
    return null;
}

fn wacliWorkerMain(a: *App, lane: WacliLane) void {
    while (true) {
        a.wacli_mutex.lockUncancelable(a.io);
        var job = wacliTakeJob(a, lane);
        while (job == null and !a.wacli_quit) {
            a.wacli_cond.waitUncancelable(a.io, &a.wacli_mutex);
            job = wacliTakeJob(a, lane);
        }
        if (job == null or a.wacli_quit) {
            a.wacli_mutex.unlock(a.io);
            return;
        }
        a.wacli_mutex.unlock(a.io);
        wacliRunJob(a, job.?);
    }
}

fn wacliRunJob(a: *App, job: WacliJob) void {
    if (!hubConfigured(a) and job.kind != .cache_tag and job.provider == .whatsapp and !std.mem.eql(u8, job.account.slice(), a.cache_tag.slice())) {
        wacliPendingSub(a, job.kind);
        return;
    }
    var argv: [max_wacli_args][]const u8 = undefined;
    var count: usize = 0;
    while (count < job.arg_count) : (count += 1) argv[count] = job.args[count].slice();
    const result = a.allocator.create(WacliResult) catch {
        wacliPendingSub(a, job.kind);
        return;
    };
    result.* = .{ .kind = job.kind, .provider = job.provider, .account = job.account, .gen = job.gen, .jid = job.jid, .msg_id = job.msg_id, .extra = job.extra, .started_ms = job.started_ms };
    switch (job.kind) {
        .slack_workspace, .slack_users, .slack_history, .slack_replies, .slack_send, .slack_attach, .slack_share, .slack_download, .slack_auth, .slack_mark => {
            if (unifiedHub(a)) {
                result.extra.set("UnsupportedHubAction");
                wacliPost(a, result);
                return;
            }
            var slack_args: [max_wacli_args][]const u8 = undefined;
            var slack_count: usize = 0;
            while (slack_count < job.arg_count) : (slack_count += 1) slack_args[slack_count] = job.args[slack_count].slice();
            const kind: slack_win.JobKind = switch (job.kind) {
                .slack_workspace => .workspace,
                .slack_users => .users,
                .slack_history => .history,
                .slack_replies => .replies,
                .slack_send => .send_text,
                .slack_attach => .upload_image,
                .slack_share => .share_image,
                .slack_auth => .auth,
                .slack_mark => .mark,
                else => .download,
            };
            slack_win.last_status = 0;
            slack_win.last_error = [_]u8{0} ** 64;
            const context = slackContext(a, job.account.slice(), job.kind == .slack_auth and std.mem.eql(u8, job.extra.slice(), "bridge")) orelse {
                result.extra.set("WorkspaceDisconnected");
                wacliPost(a, result);
                return;
            };
            defer a.allocator.free(context.user_token);
            defer a.allocator.free(context.host);
            defer a.allocator.free(context.media_dir);
            if (runSlackJob(a, job.account.slice(), context, kind, slack_args[0..slack_count])) |data| {
                result.data = data;
                result.ok = true;
            } else |err| {
                result.extra.set(@errorName(err));
            }
            result.http_status = slack_win.last_status;
            result.slack_error.set(std.mem.sliceTo(&slack_win.last_error, 0));
            wacliPost(a, result);
            return;
        },
        else => {},
    }
    if (hubConfigured(a) and (unifiedHub(a) or job.provider == .whatsapp)) {
        runHubJob(a, job, result);
        wacliPost(a, result);
        return;
    }
    const run = child_process.run(a.allocator, a.io, .{
        .argv = argv[0..count],
        .stdout_limit = .limited(8 * 1024 * 1024),
        .stderr_limit = .limited(256 * 1024),
        .create_no_window = true,
    }) catch |err| {
        if (job.kind == .messages) result.extra.set(@errorName(err));
        wacliPost(a, result);
        return;
    };
    defer {
        a.allocator.free(run.stdout);
        a.allocator.free(run.stderr);
    }
    result.ok = switch (run.term) {
        .exited => |code| code == 0,
        else => false,
    };
    if (result.ok) {
        result.data = a.allocator.dupe(u8, run.stdout) catch blk: {
            result.ok = false;
            break :blk &.{};
        };
    }
    if (!result.ok and job.kind == .messages) {
        const stderr_trim = std.mem.trim(u8, run.stderr, " \t\r\n");
        const stderr_line = stderr_trim[0..(std.mem.indexOfScalar(u8, stderr_trim, '\n') orelse stderr_trim.len)];
        if (stderr_line.len > 0) {
            result.extra.set(stderr_line);
        } else {
            var code_buf: [32]u8 = undefined;
            const text = switch (run.term) {
                .exited => |code| std.fmt.bufPrint(&code_buf, "exit code {d}", .{code}) catch "wacli failed",
                else => @tagName(run.term),
            };
            result.extra.set(text);
        }
    }
    wacliPost(a, result);
}

fn wacliPost(a: *App, result: *WacliResult) void {
    const hwnd = a.hwnd orelse {
        wacliDiscard(a, result);
        return;
    };
    if (win.PostMessageW(hwnd, wm_wacli_done, 0, @bitCast(@intFromPtr(result))) == 0) wacliDiscard(a, result);
}

fn wacliDiscard(a: *App, result: *WacliResult) void {
    const kind = result.kind;
    if (result.data.len > 0) a.allocator.free(result.data);
    a.allocator.destroy(result);
    wacliPendingSub(a, kind);
}

fn msgCacheGet(a: *App, key: chat_key.Key) ?[]const u8 {
    const index = chat_key.indexOf(MsgCacheEntry, a.msg_cache[0..a.msg_cache_len], key) orelse return null;
    return a.msg_cache[index].data;
}

fn msgCacheStore(a: *App, key: chat_key.Key, data: []const u8) void {
    if (data.len == 0 or data.len > msg_cache_max_bytes) return;
    const copy = a.allocator.dupe(u8, data) catch return;
    var slot = chat_key.indexOf(MsgCacheEntry, a.msg_cache[0..a.msg_cache_len], key);
    if (slot == null and a.msg_cache_len < a.msg_cache.len) {
        a.msg_cache_len += 1;
        slot = a.msg_cache_len - 1;
    }
    if (slot == null) {
        if (a.msg_cache[0].data) |old| a.allocator.free(old);
        var shift: usize = 0;
        while (shift + 1 < a.msg_cache_len) : (shift += 1) a.msg_cache[shift] = a.msg_cache[shift + 1];
        a.msg_cache[a.msg_cache_len - 1].data = null;
        slot = a.msg_cache_len - 1;
    }
    const entry = &a.msg_cache[slot.?];
    if (entry.data) |old| a.allocator.free(old);
    entry.provider = key.provider;
    entry.account.set(key.account);
    entry.jid.set(key.id);
    entry.data = copy;
    if (a.startup_probe_pending or (!unifiedHub(a) and (key.provider != .whatsapp or !std.mem.eql(u8, key.account, a.cache_tag.slice())))) return;
    if (msgCacheDiskPath(a, key.id)) |path| {
        defer a.allocator.free(path);
        const envelope = chat_cache.envelope(a.allocator, if (unifiedHub(a)) a.cache_tag.slice() else key.account, key.id, data) catch return;
        defer a.allocator.free(envelope);
        _ = writeCacheFileAtomic(a, path, envelope);
    }
}

fn timestampPart(timestamp: []const u8, start: usize, length: usize) ?u16 {
    if (start + length > timestamp.len) return null;
    var value: u16 = 0;
    for (timestamp[start .. start + length]) |character| {
        if (character < '0' or character > '9') return null;
        value = value * 10 + character - '0';
    }
    return value;
}

fn localTimestamp(timestamp: []const u8) ?win.SYSTEMTIME {
    if (timestamp.len < 19) return null;
    var utc = std.mem.zeroes(win.SYSTEMTIME);
    utc.wYear = timestampPart(timestamp, 0, 4) orelse 0;
    utc.wMonth = timestampPart(timestamp, 5, 2) orelse 0;
    utc.wDay = timestampPart(timestamp, 8, 2) orelse 0;
    utc.wHour = timestampPart(timestamp, 11, 2) orelse 0;
    utc.wMinute = timestampPart(timestamp, 14, 2) orelse 0;
    utc.wSecond = timestampPart(timestamp, 17, 2) orelse 0;
    var local = std.mem.zeroes(win.SYSTEMTIME);
    if (utc.wYear > 0 and win.SystemTimeToTzSpecificLocalTime(null, &utc, &local) != 0) return local;
    return null;
}

fn formatTime(target: *WideText(15), allocator: std.mem.Allocator, timestamp: []const u8) void {
    if (timestamp.len < 16) {
        target.set(allocator, "");
        return;
    }
    if (localTimestamp(timestamp)) |local| {
        var buffer: [6]u8 = undefined;
        const rendered = std.fmt.bufPrint(&buffer, "{d:0>2}:{d:0>2}", .{ local.wHour, local.wMinute }) catch timestamp[11..16];
        target.set(allocator, rendered);
        return;
    }
    target.set(allocator, timestamp[11..16]);
}

fn containsIgnoreCase(haystack: []const u8, needle: []const u8) bool {
    if (needle.len == 0) return true;
    if (needle.len > haystack.len) return false;
    var start: usize = 0;
    while (start + needle.len <= haystack.len) : (start += 1) {
        var matched = true;
        for (needle, 0..) |character, index| {
            if (std.ascii.toLower(haystack[start + index]) != std.ascii.toLower(character)) {
                matched = false;
                break;
            }
        }
        if (matched) return true;
    }
    return false;
}

fn groupName(a: *const App, jid: []const u8) ?[]const u8 {
    for (a.groups[0..a.group_count]) |*group| {
        if (std.mem.eql(u8, group.jid.slice(), jid) and group.name.len > 0) return group.name.slice();
    }
    return null;
}

fn refreshGroups(a: *App) void {
    if (wacliPendingGet(a, .groups) > 0) return;
    var job = WacliJob{ .account = a.cache_tag, .kind = .groups };
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "groups", "list", "--limit", "1000" });
    _ = wacliEnqueue(a, job, false);
}

fn refreshContactsIndex(a: *App) void {
    if (unifiedHub(a)) return;
    if (wacliPendingGet(a, .contacts_index) > 0) return;
    var job = WacliJob{ .account = a.cache_tag, .kind = .contacts_index };
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "contacts", "search", "@", "--limit", "10000" });
    _ = wacliEnqueue(a, job, false);
}

fn peopleHubFields(object: std.json.ObjectMap) ?people_index.HubFields {
    const provider = hub.sourceProvider(object) orelse return null;
    return .{ .provider = @tagName(provider), .account = hub.sourceAccount(object, ""), .view_account = hub.viewAccount(object, "") };
}

fn refreshPeopleSearch(a: *App) void {
    const whatsapp_view = messenger_view.includes(activeChatView(a), .whatsapp);
    if (!unifiedHub(a) and !whatsapp_view) return;
    if (whatsapp_view and !a.show_archived) {
        if (a.search) |search| {
            if (win.GetWindowTextLengthW(search) > 0) {
                refilterChats(a);
                if (!messagesAreCurrent(a)) refreshMessages(a);
            }
        }
    }
    if (a.palette != null and !a.palette_links_mode and !a.palette_accounts_mode and !a.palette_views_mode) paletteFilter(a);
}

fn peopleChat(a: *App, entry: people_index.Entry) Chat {
    var chat = Chat{ .account = a.cache_tag, .archived = entry.origin == .archived };
    if (entry.provider.len > 0) {
        chat.provider = std.meta.stringToEnum(transport.Provider, entry.provider) orelse .whatsapp;
        if (entry.account.len > 0) chat.account.set(entry.account);
        chat.view_account.set(entry.view_account);
    }
    chat.jid.set(entry.jid);
    chat.name.set(a.allocator, entry.name);
    chat.kind.set(a.allocator, if (entry.origin == .contact) "Contact" else if (std.mem.endsWith(u8, entry.jid, "@g.us")) "Group" else "Chat");
    chat.timestamp.set(entry.last_message_ts);
    formatTime(&chat.time, a.allocator, entry.last_message_ts);
    return chat;
}

fn applyGroups(a: *App, raw: []const u8) void {
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return,
    };
    const data_value = root.get("data") orelse return;
    const data = switch (data_value) {
        .array => |items| items,
        else => return,
    };
    a.group_count = 0;
    for (data.items) |item| {
        if (a.group_count >= max_groups) break;
        const object = switch (item) {
            .object => |value| value,
            else => continue,
        };
        var group = Group{};
        group.jid.set(getString(object, "JID"));
        group.name.set(getString(object, "Name"));
        if (group.jid.len == 0 or group.name.len == 0) continue;
        a.groups[a.group_count] = group;
        a.group_count += 1;
    }
}

fn refreshChats(a: *App) void {
    const flags: u8 = if (a.show_archived) 2 else if (a.include_archived) 1 else 0;
    if (wacliPendingGet(a, .chats) > 0 and a.chats_pending_flags == flags) return;
    var job = WacliJob{ .account = a.cache_tag, .kind = .chats };
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "chats", "list", "--limit", "250" });
    if (a.show_archived or !a.include_archived or hubConfigured(a)) {
        job.args[job.arg_count].set(if (a.show_archived) "--archived" else if (a.include_archived) "--include-archived" else "--no-archived");
        job.arg_count += 1;
    }
    a.chats_gen += 1;
    job.gen = a.chats_gen;
    _ = wacliEnqueue(a, job, wacliPendingGet(a, .chats) > 0);
    a.chats_pending_flags = flags;
}

fn isUnresolvableChatEntry(name: []const u8, jid: []const u8, kind: []const u8) bool {
    if (!std.mem.eql(u8, kind, "unknown")) return false;
    if (std.mem.indexOfScalar(u8, jid, '@') != null) return false;
    return name.len == 0 or std.mem.eql(u8, name, jid);
}

fn applyChats(a: *App, raw: []const u8, fresh: bool) bool {
    const previous_rows = a.allocator.dupe(Chat, a.chats[0..a.chat_count]) catch return false;
    defer a.allocator.free(previous_rows);
    const previous_marker = if (a.selected_chat < a.chat_count) archiveMarker(a, &a.chats[a.selected_chat]) else null;
    const view_switched = a.chat_view_switched;
    var query_wide: [256]u16 = [_]u16{0} ** 256;
    const query_len = if (a.search) |search| @as(usize, @intCast(win.GetWindowTextW(search, &query_wide, query_wide.len))) else 0;
    const query_utf8 = if (query_len > 0) std.unicode.utf16LeToUtf8Alloc(a.allocator, query_wide[0..query_len]) catch null else null;
    defer if (query_utf8) |query| a.allocator.free(query);

    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch {
        setStatus(a, "Unable to read chats from wacli");
        return false;
    };
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |o| o,
        else => return false,
    };
    const data_value = root.get("data") orelse return false;
    const data = switch (data_value) {
        .array => |items| items,
        else => return false,
    };
    if (fresh) migrateLegacyArchiveState(a, data.items);
    if (fresh) observeBackgroundMediaChats(a, data.items);
    if (!a.pins_loaded) {
        if (loadPins(a)) {
            a.pins_loaded = true;
        } else if (data.items.len > 0) {
            a.pins_loaded = true;
            for (data.items) |item| {
                const object = switch (item) {
                    .object => |o| o,
                    else => continue,
                };
                if (getBool(object, "pinned")) addPin(a, .{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = getString(object, "jid") });
            }
            _ = savePins(a);
        }
    }
    rebuildViews(a, data.items);
    if (unifiedHub(a) and !a.show_archived) a.people.replaceInboxHub(raw, peopleHubFields) catch {};
    if (fresh and unifiedHub(a) and !a.show_archived and a.startup_view_pending) {
        a.startup_view_pending = false;
        if (a.chat_view == .signal or a.chat_view == .telegram) {
            var populated = false;
            for (data.items) |row| {
                if (row != .object) continue;
                const provider = hub.sourceProvider(row.object) orelse continue;
                if (chatInView(a, .{ .provider = provider, .account = hub.viewAccount(row.object, a.cache_tag.slice()), .id = "" })) {
                    populated = true;
                    break;
                }
            }
            if (!populated) {
                a.chat_view = .all;
                a.view_account.set("");
                loadViewArchiveSetting(a);
                saveChatView(.all);
                _ = saveRegistryString(a.allocator, lit("AccountView"), "");
                a.chat_view_switched = true;
            }
        }
    }
    const view = activeChatView(a);
    var needed = data.items.len + a.tg_chat_count + max_chats;
    for (&a.slack_installations) |*installation| if (installation.active) {
        needed += installation.chat_count;
    };
    if (a.chats.len < needed) a.chats = a.allocator.realloc(a.chats, needed) catch return false;
    var selected_key = selectedViewKey(a).*;
    if (!a.chat_view_switched and a.selected_chat < a.chat_count) selected_key.set(chat_key.of(&a.chats[a.selected_chat]));
    var anchor_key = chat_key.Stored{};
    var selected_jid: [192]u8 = [_]u8{0} ** 192;
    var selected_len: usize = 0;
    selected_len = selected_key.id_len;
    @memcpy(selected_jid[0..selected_len], selected_key.key().id);

    var anchor_jid: [192]u8 = [_]u8{0} ** 192;
    var anchor_len: usize = 0;
    var top_index: i32 = -1;
    if (a.chat_view_switched) {
        a.chat_view_switched = false;
    } else if (a.chats_hwnd) |list| {
        const current_top = win.SendMessageW(list, win.LB_GETTOPINDEX, 0, 0);
        if (current_top >= 0 and @as(usize, @intCast(current_top)) < a.chat_count) {
            const top_chat = &a.chats[@intCast(current_top)];
            anchor_key.set(chat_key.of(top_chat));
            if (top_chat.jid.len <= anchor_jid.len) {
                top_index = @intCast(current_top);
                anchor_len = top_chat.jid.len;
                @memcpy(anchor_jid[0..anchor_len], top_chat.jid.slice());
            }
        }
    }
    a.chat_count = 0;
    a.last_refresh_unix = nowUnixSeconds();
    for (data.items) |item| {
        if (!unifiedHub(a) and !messenger_view.includes(view, .whatsapp)) break;
        if (a.chat_count >= a.chats.len) break;
        const object = switch (item) {
            .object => |o| o,
            else => continue,
        };
        var chat = Chat{ .account = a.cache_tag };
        if (unifiedHub(a)) {
            chat.provider = hub.sourceProvider(object) orelse continue;
            chat.account.set(hub.sourceAccount(object, a.cache_tag.slice()));
            chat.view_account.set(hub.viewAccount(object, a.cache_tag.slice()));
            chat.saved = hub.savedMessages(object);
        }
        const jid = getString(object, "jid");
        chat.jid.set(jid);
        if (!chatInView(a, chatViewKey(&chat))) continue;
        if (fresh and chat.provider != .slack) _ = holdKeptArchived(a, chat_key.of(&chat), getBool(object, "archived"), getString(object, "last_message_ts"));
        if (pendingArchiveHidesChat(a, jid, a.show_archived)) continue;
        const raw_name = if (chat.saved) "Saved Messages" else getString(object, "name");
        const display_name = groupName(a, jid) orelse raw_name;
        if (isUnresolvableChatEntry(display_name, jid, getString(object, "kind"))) continue;
        if (query_utf8) |query| {
            if (!containsIgnoreCase(display_name, query) and !containsIgnoreCase(jid, query)) continue;
        }
        chat.name.set(a.allocator, if (chat.saved) "Saved Messages" else display_name);
        chat.kind.set(a.allocator, if (std.mem.endsWith(u8, jid, "@g.us")) "Group" else getString(object, "kind"));
        chat.timestamp.set(getString(object, "last_message_ts"));
        fillSlackTimestamp(a, &chat);
        chat.provider_unread = getBool(object, "unread") or getInt(object, "unread_count") > 0;
        const timestamp = media_age.unixSeconds(chat.timestamp.slice()) orelse 0;
        a.read_state.observeChat(a.allocator, a.cache_tag.slice(), jid, timestamp, chat.provider_unread, fresh and !a.startup_probe_pending);
        chat.unread = a.read_state.isUnread(a.cache_tag.slice(), jid);
        chat.unread_count = if (chat.unread) @max(1, getInt(object, "unread_count")) else 0;
        queueUnreadProbe(a, &chat);
        chat.pinned = getBool(object, "pinned");
        chat.archived = if (a.archive_state) |state| state.isArchived(chat_key.of(&chat), getBool(object, "archived")) else getBool(object, "archived");
        chat.provider_archived = getBool(object, "archived");
        for (a.pending_archives[0..a.pending_archive_count]) |*pending| {
            if (chat.provider == .whatsapp and std.mem.eql(u8, pending.jid.slice(), chat.jid.slice())) chat.archived = !pending.should_unarchive;
        }
        if (!messenger_view.archiveMatches(a.show_archived, a.include_archived, activeChatView(a) == .all, a.unread_only, chat.archived, chat.unread)) continue;
        a.chats[a.chat_count] = chat;
        a.chat_count += 1;
    }
    if (!unifiedHub(a)) {
        if (messenger_view.includes(view, .slack)) appendSlackChats(a, query_utf8);
        if (!a.show_archived and messenger_view.includes(view, .telegram)) appendTelegramChats(a, query_utf8);
    }
    controlSortChats(a, a.chats[0..a.chat_count], view);
    if (!unifiedHub(a) and messenger_view.includes(view, .whatsapp) and !a.show_archived and !a.unread_only and !(a.include_archived and view == .all)) {
        if (query_utf8) |query| {
            const exclude = a.allocator.alloc(people_index.Identity, a.chat_count) catch return false;
            defer a.allocator.free(exclude);
            var exclude_count: usize = 0;
            for (a.chats[0..a.chat_count]) |*chat| {
                if (chat.provider != .whatsapp) continue;
                const key = chat_key.of(chat);
                exclude[exclude_count] = .{ .provider = @tagName(key.provider), .account = key.account, .id = key.id };
                exclude_count += 1;
            }
            var matches: [max_chats]people_index.Entry = undefined;
            const count = a.people.search(query, exclude[0..exclude_count], a.cache_tag.slice(), &matches, @min(max_chats, a.chats.len - a.chat_count));
            for (matches[0..count]) |entry| {
                if (pendingArchiveHidesChat(a, entry.jid, entry.origin == .archived)) continue;
                a.chats[a.chat_count] = peopleChat(a, entry);
                a.chat_count += 1;
            }
        }
    }
    if (a.people_open_jid.len > 0) {
        const open_allowed = if (unifiedHub(a)) true else messenger_view.includes(view, .whatsapp) and selected_key.provider == .whatsapp;
        if (!open_allowed or a.show_archived or (a.include_archived and view == .all) or query_len > 0 or
            !std.mem.eql(u8, selected_jid[0..selected_len], a.people_open_jid.slice()))
        {
            a.people_open_jid.set("");
        } else {
            var shown = false;
            for (a.chats[0..a.chat_count]) |*chat| {
                if (std.mem.eql(u8, chat.jid.slice(), a.people_open_jid.slice())) shown = true;
            }
            if (!shown and a.chat_count < a.chats.len) {
                if (a.people.find(a.people_open_jid.slice())) |entry| {
                    a.chats[a.chat_count] = peopleChat(a, entry);
                    a.chat_count += 1;
                }
            }
        }
    }
    a.selected_chat = 0;
    if (selected_len > 0) {
        for (a.chats[0..a.chat_count], 0..) |chat, index| {
            if (chat_key.Key.eql(selected_key.key(), chat_key.of(&chat))) {
                a.selected_chat = index;
                break;
            }
        }
    }
    if (a.selected_chat >= a.chat_count or
        !chat_key.Key.eql(selected_key.key(), chat_key.of(&a.chats[a.selected_chat])))
    {
        a.user_viewed = false;
        cancelSlackMark(a);
    }
    switchComposerDraft(a);
    if (a.selected_chat < a.chat_count) selectedViewKey(a).set(chat_key.of(&a.chats[a.selected_chat]));
    updateSearchCue(a, view);
    updateWindowTitle(a);
    if (a.chats_hwnd) |list| {
        const rows_changed = !chat_rows.equal(Chat, previous_rows, a.chats[0..a.chat_count]);
        const selection_changed = win.SendMessageW(list, win.LB_GETCURSEL, 0, 0) != @as(win.LRESULT, @intCast(a.selected_chat));
        if (rows_changed or selection_changed or view_switched) {
            const count_changed = previous_rows.len != a.chat_count;
            if (count_changed) _ = win.SendMessageW(list, win.WM_SETREDRAW, 0, 0);
            var count = previous_rows.len;
            while (count > a.chat_count) {
                count -= 1;
                _ = win.SendMessageW(list, win.LB_DELETESTRING, count, 0);
            }
            while (count < a.chat_count) : (count += 1) {
                _ = win.SendMessageW(list, win.LB_ADDSTRING, 0, 0);
            }
            var restore_top = top_index;
            for (a.chats[0..a.chat_count], 0..) |*chat, index| {
                if (anchor_len > 0 and chat_key.Key.eql(anchor_key.key(), chat_key.of(chat))) {
                    restore_top = @intCast(index);
                    break;
                }
            }
            if (a.chat_count > 0 and top_index < 0) _ = win.SendMessageW(list, win.LB_SETTOPINDEX, 0, 0);
            if (a.chat_count > 0 and (selection_changed or view_switched)) _ = win.SendMessageW(list, win.LB_SETCURSEL, a.selected_chat, 0);
            if (a.chat_count > 0 and restore_top >= 0) {
                const clamped = @min(restore_top, @as(i32, @intCast(a.chat_count)) - 1);
                if (win.SendMessageW(list, win.LB_GETTOPINDEX, 0, 0) != clamped) _ = win.SendMessageW(list, win.LB_SETTOPINDEX, @intCast(clamped), 0);
            }
            if (count_changed) _ = win.SendMessageW(list, win.WM_SETREDRAW, 1, 0);
            if (win.SendMessageW(list, win.LB_GETTOPINDEX, 0, 0) != top_index and top_index >= 0) {
                _ = win.InvalidateRect(list, null, win.FALSE);
            } else {
                for (a.chats[0..@min(previous_rows.len, a.chat_count)], previous_rows[0..@min(previous_rows.len, a.chat_count)], 0..) |*chat, *before, index| {
                    if (!chat_rows.rowEqual(Chat, before, chat)) invalidateChatRow(a, index);
                }
                if (count_changed) {
                    var tail: win.RECT = undefined;
                    _ = win.GetClientRect(list, &tail);
                    const top = win.SendMessageW(list, win.LB_GETTOPINDEX, 0, 0);
                    tail.top = @max(0, (@as(i32, @intCast(@min(previous_rows.len, a.chat_count))) - @as(i32, @intCast(top))) * px(a, 64));
                    if (tail.top < tail.bottom) _ = win.InvalidateRect(list, &tail, win.FALSE);
                }
            }
        }
    }
    const marker = if (a.selected_chat < a.chat_count) archiveMarker(a, &a.chats[a.selected_chat]) else null;
    if (marker != previous_marker) {
        if (a.canvas) |canvas| {
            var client: win.RECT = undefined;
            _ = win.GetClientRect(canvas, &client);
            const badge = win.RECT{ .left = client.right - px(a, 150), .top = client.top + px(a, 8), .right = client.right - px(a, 24), .bottom = client.top + px(a, 32) };
            _ = win.InvalidateRect(canvas, &badge, win.FALSE);
        }
    }
    var status_buffer: [64]u8 = undefined;
    if (a.chat_count != a.last_chat_count) {
        a.last_chat_count = a.chat_count;
        const status = std.fmt.bufPrint(&status_buffer, "{d} chats", .{a.chat_count}) catch "Chats loaded";
        setStatus(a, if (a.sync_logged_out) logged_out_status else status);
    }
    persistReadState(a);
    if (fresh) {
        if (a.allocator.dupe(u8, raw)) |copy| {
            if (a.chats_raw) |old| a.allocator.free(old);
            a.chats_raw = copy;
            a.chats_raw_flags = a.chats_pending_flags;
        } else |_| {}
    }
    return true;
}

fn invalidateChatRow(a: *App, index: usize) void {
    if (a.chats_hwnd) |list| {
        var row: win.RECT = undefined;
        if (win.SendMessageW(list, win.LB_GETITEMRECT, index, @bitCast(@intFromPtr(&row))) != win.LB_ERR) _ = win.InvalidateRect(list, &row, win.FALSE);
    }
}

fn persistReadState(a: *App) void {
    if (!a.read_state.dirty) return;
    const path = messagesDirPath(a, "read-state.txt") orelse return;
    defer a.allocator.free(path);
    const data = a.read_state.encode(a.allocator) catch return;
    defer a.allocator.free(data);
    if (writeCacheFileAtomic(a, path, data)) a.read_state.dirty = false;
}

fn queueUnreadProbe(a: *App, chat: *const Chat) void {
    if ((!unifiedHub(a) and chat.provider != .whatsapp) or a.startup_probe_pending or wacliPendingGet(a, .unread_probe) > 0) return;
    const timestamp = media_age.unixSeconds(chat.timestamp.slice()) orelse return;
    if (!a.read_state.needsProbe(a.cache_tag.slice(), chat.jid.slice(), timestamp, chat.provider_unread)) return;
    var job = WacliJob{ .account = a.cache_tag, .kind = .unread_probe };
    job.provider = chat.provider;
    job.account = chat.account;
    job.jid.set(chat.jid.slice());
    job.extra.set(chat.timestamp.slice());
    job.msg_id.set(a.cache_tag.slice());
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "messages", "list", "--chat", chat.jid.slice(), "--from-them", "--limit", "1" });
    _ = wacliEnqueue(a, job, false);
}

fn applyUnreadProbe(a: *App, result: *const WacliResult) void {
    if (!result.ok or !std.mem.eql(u8, result.msg_id.slice(), a.cache_tag.slice())) return;
    const timestamp = media_age.unixSeconds(result.extra.slice()) orelse return;
    if (!a.read_state.acceptProbe(a.allocator, a.cache_tag.slice(), result.jid.slice(), timestamp, result.data)) return;
    for (a.chats[0..a.chat_count], 0..) |*chat, index| {
        if (!unifiedHub(a) and chat.provider != .whatsapp) continue;
        const was_unread = chat.unread or chat.unread_count > 0;
        chat.unread = a.read_state.isUnread(a.cache_tag.slice(), chat.jid.slice());
        chat.unread_count = if (chat.unread) @max(1, chat.unread_count) else 0;
        if (was_unread != (chat.unread or chat.unread_count > 0)) invalidateChatRow(a, index);
        queueUnreadProbe(a, chat);
    }
    if (a.unread_only or (a.include_archived and a.chat_view == .all)) refreshChats(a);
}

fn tgChatIdString(buffer: *[24]u8, chat_id: i64) []const u8 {
    return std.fmt.bufPrint(buffer, "{d}", .{chat_id}) catch "";
}

fn selectedChatIsTelegram(a: *const App) bool {
    if (unifiedHub(a)) return false;
    return a.selected_chat < a.chat_count and a.chats[a.selected_chat].provider == .telegram;
}

fn tgSelectedChatId(a: *const App) ?i64 {
    if (!selectedChatIsTelegram(a)) return null;
    return std.fmt.parseInt(i64, a.chats[a.selected_chat].jid.slice(), 10) catch null;
}

fn tgSelectedChatIsGroup(a: *App) bool {
    const chat_id = tgSelectedChatId(a) orelse return false;
    for (a.tg_chats[0..a.tg_chat_count]) |cached| {
        if (cached.id == chat_id) return cached.is_group;
    }
    return true;
}

fn upsertTgChat(a: *App, info: *tg.ChatInfo) void {
    var index: usize = 0;
    while (index < a.tg_chat_count) : (index += 1) {
        if (a.tg_chats[index].id == info.id) break;
    }
    if (index == a.tg_chat_count) {
        if (a.tg_chat_count == a.tg_chats.len) {
            a.tg_chats = a.allocator.realloc(a.tg_chats, @max(max_tg_chats, a.tg_chats.len * 2)) catch return;
        }
        a.tg_chat_count += 1;
        a.tg_chats[index] = .{ .id = info.id };
    }
    const cached = &a.tg_chats[index];
    if (info.title.len > 0) {
        cached.name.set(a.allocator, info.title);
        cached.kind.set(if (info.is_channel) "Telegram channel" else if (info.is_group) "Telegram group" else "Telegram");
        cached.is_group = info.is_group or info.is_channel;
    }
    cached.unread_count = info.unread_count;
    if (info.last_date != 0) {
        var buffer: [20]u8 = undefined;
        cached.timestamp.set(tj.formatTimestamp(&buffer, info.last_date));
    }
}

fn appendTelegramChats(a: *App, query_utf8: ?[]const u8) void {
    if (a.telegram == null or a.tg_auth != .ready or a.tg_account.len == 0) return;
    for (a.tg_chats[0..a.tg_chat_count]) |cached| {
        if (a.chat_count >= a.chats.len) break;
        const name_bytes = std.unicode.utf16LeToUtf8Alloc(a.allocator, cached.name.slice()) catch continue;
        defer a.allocator.free(name_bytes);
        var chat = Chat{};
        var id_buffer: [24]u8 = undefined;
        chat.jid.set(tgChatIdString(&id_buffer, cached.id));
        chat.name.set(a.allocator, name_bytes);
        chat.kind.set(a.allocator, cached.kind.slice());
        chat.timestamp.set(cached.timestamp.slice());
        chat.unread = cached.unread_count > 0;
        chat.unread_count = cached.unread_count;
        chat.provider = .telegram;
        chat.account = a.tg_account;
        if (!chatInView(a, chat_key.of(&chat))) continue;
        if (!messenger_view.matches(activeChatView(a), .telegram, a.unread_only or (a.include_archived and activeChatView(a) == .all), chat.unread, query_utf8 orelse "", name_bytes, chat.jid.slice())) continue;
        messenger_view.merge(Chat, a.chats, &a.chat_count, &.{chat});
    }
}

fn drainTelegram(a: *App) void {
    const client = a.telegram orelse return;
    while (client.poll()) |event_in| {
        var event = event_in;
        defer event.deinit(a.allocator);
        switch (event) {
            .auth => |auth| {
                if (auth.state != .unknown) {
                    a.tg_auth = auth.state;
                    a.tg_dirty = true;
                }
                switch (auth.state) {
                    .wait_phone => if (a.tg_login != .none) {
                        openTelegramLogin(a, .phone);
                    },
                    .wait_code => if (a.tg_login != .none) {
                        openTelegramLogin(a, .code);
                    },
                    .wait_password => if (a.tg_login != .none) {
                        openTelegramLogin(a, .password);
                    },
                    .ready => {
                        a.tg_login = .none;
                        if (a.tg_login_window) |window| _ = win.DestroyWindow(window);
                        client.requestChats();
                        setStatus(a, "Telegram connected");
                    },
                    .closed => {
                        a.tg_account.set("");
                        a.tg_login = .none;
                        if (a.tg_login_window) |window| _ = win.DestroyWindow(window);
                        a.tg_chat_count = 0;
                        refreshVisibleChats(a);
                        setStatus(a, "Telegram disconnected");
                    },
                    else => {},
                }
                if (auth.error_text.len > 0) {
                    setStatus(a, auth.error_text);
                    handleTgAuthError(a, auth.error_text);
                }
            },
            .chat => |*info| {
                upsertTgChat(a, info);
                a.tg_dirty = true;
            },
            .message => |msg| {
                if (msg.timestamp.len > 0) {
                    for (a.tg_chats[0..a.tg_chat_count]) |*cached| {
                        if (cached.id == msg.chat_id and std.mem.order(u8, msg.timestamp, cached.timestamp.slice()) == .gt) {
                            cached.timestamp.set(msg.timestamp);
                            a.tg_dirty = true;
                        }
                    }
                }
                if (tgSelectedChatId(a)) |selected_id| {
                    if (msg.chat_id == selected_id) refreshMessages(a);
                }
            },
            .history_done => {
                if (selectedChatIsTelegram(a)) refreshMessages(a);
            },
            .deleted => {
                if (selectedChatIsTelegram(a)) refreshMessages(a);
            },
            .file => |file_update| {
                if (file_update.local_path.len > 0 and selectedChatIsTelegram(a)) refreshMessages(a);
            },
            .chats_synced => {
                a.tg_dirty = true;
            },
            .chat_last_date => |last_message| {
                var index: usize = 0;
                while (index < a.tg_chat_count) : (index += 1) {
                    if (a.tg_chats[index].id == last_message.chat_id) {
                        a.tg_chats[index].timestamp.set(last_message.timestamp);
                        a.tg_dirty = true;
                        break;
                    }
                }
            },
            .account => |id| {
                var buffer: [32]u8 = undefined;
                a.tg_account.set(if (id > 0) std.fmt.bufPrint(&buffer, "{d}", .{id}) catch "" else "");
                a.tg_dirty = true;
            },
            .user => {},
            .conn, .ignored => {},
        }
    }
    if (a.tg_dirty and !a.show_archived) {
        const snapshot = client.chatSnapshot(a.allocator);
        defer client.freeChatSnapshot(a.allocator, snapshot);
        for (snapshot) |info| {
            var cached = info;
            upsertTgChat(a, &cached);
        }
        a.tg_dirty = false;
        refreshVisibleChats(a);
    } else a.tg_dirty = false;
}

fn telegramAutoDownload(a: *App) void {
    const client = a.telegram orelse return;
    for (a.messages[0..a.message_count]) |*message| {
        if (message.tg_file_id == 0 or message.local_path.len > 0) continue;
        client.download(message.tg_file_id);
    }
}

fn refreshTelegramMessages(a: *App) void {
    const client = a.telegram orelse return;
    const chat_id = tgSelectedChatId(a) orelse return;
    const snapshot = client.historySnapshot(a.allocator, chat_id);
    defer client.freeHistorySnapshot(a.allocator, snapshot);
    const chat_changed = !chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]));
    if (chat_changed) {
        stopAudio(a);
        client.requestHistory(chat_id);
    }
    var selected_id = Utf8Text(191){};
    if (a.selected_message) |selected| {
        if (selected < a.message_count) selected_id.set(a.messages[selected].id.slice());
    }
    clearMessages(a);
    a.selected_message = null;
    const take = @min(snapshot.len, max_messages);
    var source_index = take;
    while (source_index > 0) {
        source_index -= 1;
        const msg = &snapshot[source_index];
        var message = Message{};
        var id_buffer: [24]u8 = undefined;
        message.id.set(tgChatIdString(&id_buffer, msg.id));
        message.sender_jid.set(a.chats[a.selected_chat].jid.slice());
        message.sender.set(a.allocator, if (msg.sender_name.len > 0) msg.sender_name else "Unknown");
        message.from_me = msg.from_me;
        message.text.set(a.allocator, tgDisplayText(msg));
        if (msg.reply_to != 0) {
            message.quote.set(a.allocator, "[Original message]");
            const reply_chat_id = if (msg.reply_chat_id != 0) msg.reply_chat_id else chat_id;
            const originals = if (reply_chat_id == chat_id) snapshot else client.historySnapshot(a.allocator, reply_chat_id);
            defer if (reply_chat_id != chat_id) client.freeHistorySnapshot(a.allocator, originals);
            for (originals) |*original| {
                if (original.id == msg.reply_to) {
                    message.quote.set(a.allocator, tgDisplayText(original));
                    message.quote_sender.set(a.allocator, original.sender_name);
                    break;
                }
            }
        }
        message.mime_type.set(msg.mime);
        message.local_path.set(a.allocator, msg.local_path);
        message.tg_file_id = msg.file_id;
        message.media_type.set(switch (msg.media_kind) {
            .photo => "image",
            .sticker => "sticker",
            .voice => "audio",
            .video => "video",
            .document => "document",
            else => "",
        });
        if (msg.media_kind == .sticker and msg.animated_sticker) {
            message.text.set(a.allocator, "[Animated sticker]");
        }
        if (msg.duration_ms > 0) {
            var duration_buffer: [24]u8 = undefined;
            const duration = std.fmt.bufPrint(&duration_buffer, "[Voice message {d}s]", .{@divTrunc(msg.duration_ms, 1000)}) catch "[Voice message]";
            if (message.text.len == 0) message.text.set(a.allocator, duration);
        }
        formatTime(&message.time, a.allocator, msg.timestamp);
        a.messages[a.message_count] = message;
        a.message_count += 1;
        const stored = &a.messages[a.message_count - 1];
        if (isAudio(stored)) loadTranscriptCache(a, stored);
    }
    if (selected_id.len > 0) {
        for (a.messages[0..a.message_count], 0..) |*message, index| {
            if (std.mem.eql(u8, selected_id.slice(), message.id.slice())) {
                a.selected_message = index;
                break;
            }
        }
    }
    if (chat_changed) a.scroll_y = 0;
    a.displayed_jid.set(a.chats[a.selected_chat].jid.slice());
    a.displayed_account = a.chats[a.selected_chat].account;
    a.displayed_provider = a.chats[a.selected_chat].provider;
    a.displayed_timestamp.set(a.chats[a.selected_chat].timestamp.slice());
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    telegramAutoDownload(a);
    markChatRead(a);
}

fn tgDisplayText(msg: *const tg.Msg) []const u8 {
    if (msg.text.len > 0) return msg.text;
    return switch (msg.media_kind) {
        .photo => "[Photo]",
        .sticker => "[Sticker]",
        .voice => "[Voice message]",
        .video => "[Video]",
        .document => "[Document]",
        else => "",
    };
}

fn handleTgAuthError(a: *App, error_text: []const u8) void {
    if (a.tg_login == .none) return;
    if (std.mem.indexOf(u8, error_text, "app keys") != null) {
        wipeBadTelegramKeys(a);
        return;
    }
    if (a.tg_login == .api_id or a.tg_login == .api_hash) {
        tgLoginShowError(a, error_text);
        return;
    }
    const mode: TgLoginMode = if (std.mem.indexOf(u8, error_text, "phone number") != null)
        .phone
    else if (std.mem.indexOf(u8, error_text, "code") != null)
        .code
    else if (std.mem.indexOf(u8, error_text, "2FA password") != null)
        .password
    else {
        tgLoginRetryInput(a);
        tgLoginShowError(a, error_text);
        return;
    };
    openTelegramLogin(a, mode);
    tgLoginShowError(a, error_text);
}

fn tgPromptText(mode: TgLoginMode) [*:0]const u16 {
    return switch (mode) {
        .phone => lit("Telegram: type your phone number (with country code) and press Next"),
        .code => lit("Telegram: type the login code Telegram sent you and press Next"),
        .password => lit("Telegram: type your 2FA password and press Next"),
        .api_id => lit("Telegram: get api_id and api_hash at my.telegram.org/apps (button below), then type the api_id and press Next"),
        .api_hash => lit("Telegram: type your api_hash and press Next"),
        .none => lit("Telegram"),
    };
}

fn tgModeSecret(mode: TgLoginMode) bool {
    return mode == .password or mode == .api_hash;
}

fn parseTgApiId(text: []const u8) ?i32 {
    const parsed = std.fmt.parseInt(i32, text, 10) catch return null;
    if (parsed <= 0) return null;
    return parsed;
}

fn validTgApiHash(text: []const u8) bool {
    if (text.len != 32) return false;
    for (text) |c| {
        const hex = (c >= '0' and c <= '9') or (c >= 'a' and c <= 'f') or (c >= 'A' and c <= 'F');
        if (!hex) return false;
    }
    return true;
}

const tg_api_hash_error = "The api_hash is exactly 32 hexadecimal characters (0-9, a-f). Copy the whole value from my.telegram.org/apps.";

fn tgLoginShowError(a: *App, error_text: []const u8) void {
    const window = a.tg_login_window orelse return;
    const prompt_ctl = win.GetDlgItem(window, id_tg_prompt) orelse return;
    const error_wide = utf8ToWide(a.allocator, error_text) catch return;
    defer a.allocator.free(error_wide);
    if (a.tg_login == .none) {
        _ = win.SetWindowTextW(prompt_ctl, error_wide.ptr);
        return;
    }
    const prompt: []const u16 = std.mem.span(tgPromptText(a.tg_login));
    const buffer = a.allocator.alloc(u16, error_wide.len + 3 + prompt.len + 1) catch return;
    defer a.allocator.free(buffer);
    @memcpy(buffer[0..error_wide.len], error_wide);
    buffer[error_wide.len] = ' ';
    buffer[error_wide.len + 1] = '-';
    buffer[error_wide.len + 2] = ' ';
    @memcpy(buffer[error_wide.len + 3 ..][0..prompt.len], prompt);
    buffer[buffer.len - 1] = 0;
    _ = win.SetWindowTextW(prompt_ctl, @ptrCast(buffer.ptr));
}

fn tgLoginApplyMode(a: *App, window: win.HWND, mode: TgLoginMode) void {
    const edit = win.GetDlgItem(window, id_tg_edit) orelse return;
    _ = win.SendMessageW(edit, win.EM_SETPASSWORDCHAR, if (tgModeSecret(mode)) @as(usize, '*') else 0, 0);
    _ = win.SetWindowTextW(edit, lit(""));
    _ = win.EnableWindow(edit, 1);
    if (win.GetDlgItem(window, id_tg_next)) |next| {
        _ = win.EnableWindow(next, 1);
        setFont(next, a.font_bold);
    }
    if (win.GetDlgItem(window, id_tg_open_page)) |open_page| {
        _ = win.ShowWindow(open_page, if (mode == .api_id) win.SW_SHOW else win.SW_HIDE);
    }
    _ = win.InvalidateRect(edit, null, win.TRUE);
    _ = win.SetFocus(edit);
}

fn tgLoginSetChecking(a: *App) void {
    const window = a.tg_login_window orelse return;
    const edit = win.GetDlgItem(window, id_tg_edit) orelse return;
    _ = win.EnableWindow(edit, 0);
    if (win.GetDlgItem(window, id_tg_next)) |next| _ = win.EnableWindow(next, 0);
    const prompt = win.GetDlgItem(window, id_tg_prompt) orelse return;
    _ = win.SetWindowTextW(prompt, lit("Checking with Telegram..."));
}

fn tgLoginRetryInput(a: *App) void {
    const window = a.tg_login_window orelse return;
    const edit = win.GetDlgItem(window, id_tg_edit) orelse return;
    _ = win.EnableWindow(edit, 1);
    if (win.GetDlgItem(window, id_tg_next)) |next| _ = win.EnableWindow(next, 1);
    _ = win.SetFocus(edit);
}

fn openTelegramLogin(a: *App, mode: TgLoginMode) void {
    if (hubConfigured(a)) return;
    a.tg_login = mode;
    setStatus(a, switch (mode) {
        .phone => "Telegram: type your phone number in the box and press Next",
        .code => "Telegram: type the login code and press Next",
        .password => "Telegram: type your 2FA password and press Next",
        .api_id => "Telegram: open my.telegram.org/apps below, then type your api_id and press Next",
        .api_hash => "Telegram: type your api_hash and press Next",
        .none => "Telegram",
    });
    if (a.tg_login_window) |window| {
        if (win.GetDlgItem(window, id_tg_prompt)) |prompt| _ = win.SetWindowTextW(prompt, tgPromptText(mode));
        tgLoginApplyMode(a, window, mode);
        return;
    }
    const owner = a.hwnd orelse return;
    _ = win.EnableWindow(owner, 0);
    const window = win.CreateWindowExW(
        win.WS_EX_DLGMODALFRAME,
        lit("TelegramLogin"),
        lit("Sign in to Telegram"),
        win.WS_OVERLAPPED | win.WS_CAPTION | win.WS_SYSMENU,
        200,
        200,
        410,
        240,
        owner,
        null,
        a.instance,
        null,
    ) orelse {
        _ = win.EnableWindow(owner, 1);
        a.tg_login = .none;
        setStatus(a, "Telegram: the sign-in window could not open. Try Add Telegram account again.");
        return;
    };
    a.tg_login_window = window;
    if (theme.choice == .amoled) {
        var dark: win.BOOL = win.TRUE;
        _ = win.DwmSetWindowAttribute(window, 20, &dark, @sizeOf(win.BOOL));
    }
    tgLoginApplyMode(a, window, mode);
    _ = win.ShowWindow(window, win.SW_SHOW);
}

fn setPaletteCue(a: *App) void {
    const edit = a.palette_edit orelse return;
    const cue: [*:0]const u16 = if (a.palette_views_mode) lit("Ctrl+Up/Down reorders. Enter switches.") else if (a.palette_accounts_mode) lit("Accounts") else lit("Type a command");
    _ = win.SendMessageW(edit, win.EM_SETCUEBANNER, 1, @bitCast(@intFromPtr(cue)));
}

fn closeTgLogin(a: *App) void {
    a.tg_login = .none;
    if (a.tg_login_window) |window| _ = win.DestroyWindow(window);
}

fn layoutTgLogin(hwnd: win.HWND) void {
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    const btn_w: i32 = 90;
    const btn_h: i32 = 30;
    const gap: i32 = 8;
    const margin: i32 = 16;
    const bottom = client.bottom - margin - btn_h;
    if (win.GetDlgItem(hwnd, id_tg_prompt)) |p| _ = win.MoveWindow(p, margin, 14, client.right - 2 * margin, 48, win.TRUE);
    if (win.GetDlgItem(hwnd, id_tg_edit)) |e| _ = win.MoveWindow(e, margin, 70, client.right - 2 * margin, 28, win.TRUE);
    if (win.GetDlgItem(hwnd, id_tg_open_page)) |o| _ = win.MoveWindow(o, margin, 106, 210, btn_h, win.TRUE);
    if (win.GetDlgItem(hwnd, id_tg_cancel)) |c| _ = win.MoveWindow(c, client.right - margin - btn_w, bottom, btn_w, btn_h, win.TRUE);
    if (win.GetDlgItem(hwnd, id_tg_next)) |n| _ = win.MoveWindow(n, client.right - margin - 2 * btn_w - gap, bottom, btn_w, btn_h, win.TRUE);
}

fn telegramLoginProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) isize {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_CREATE => {
            _ = win.CreateWindowExW(0, lit("STATIC"), lit(""), win.WS_CHILD | win.WS_VISIBLE, 16, 14, 366, 48, hwnd, controlId(id_tg_prompt), a.instance, null);
            _ = win.CreateWindowExW(0, lit("EDIT"), null, win.WS_CHILD | win.WS_VISIBLE | win.WS_BORDER | win.WS_TABSTOP | win.ES_AUTOHSCROLL, 16, 70, 366, 28, hwnd, controlId(id_tg_edit), a.instance, null);
            const next = win.CreateWindowExW(0, lit("BUTTON"), lit("Next"), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.BS_OWNERDRAW | win.BS_DEFPUSHBUTTON, 0, 0, 90, 30, hwnd, controlId(id_tg_next), a.instance, null);
            const cancel = win.CreateWindowExW(0, lit("BUTTON"), lit("Cancel"), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.BS_OWNERDRAW, 0, 0, 90, 30, hwnd, controlId(id_tg_cancel), a.instance, null);
            const open_page = win.CreateWindowExW(0, lit("BUTTON"), lit("Open my.telegram.org/apps"), win.WS_CHILD | win.WS_TABSTOP | win.BS_OWNERDRAW, 0, 0, 210, 30, hwnd, controlId(id_tg_open_page), a.instance, null);
            setFont(win.GetDlgItem(hwnd, id_tg_prompt), a.font);
            setFont(win.GetDlgItem(hwnd, id_tg_edit), a.font);
            setFont(next, a.font_bold);
            setFont(cancel, a.font_bold);
            setFont(open_page, a.font_bold);
            subclassComposerButton(a, next, 5);
            subclassComposerButton(a, cancel, 6);
            subclassComposerButton(a, open_page, 7);
            layoutTgLogin(hwnd);
            return 0;
        },
        win.WM_SIZE => {
            layoutTgLogin(hwnd);
            return 0;
        },
        win.WM_ERASEBKGND => {
            var client: win.RECT = undefined;
            _ = win.GetClientRect(hwnd, &client);
            _ = win.FillRect(winHandle(win.HDC, @as(usize, @bitCast(wparam))), &client, a.brush_panel.?);
            return 1;
        },
        win.WM_PAINT => {
            if (theme.choice != .amoled) return win.DefWindowProcW(hwnd, message, wparam, lparam);
            var paint: win.PAINTSTRUCT = undefined;
            const hdc = win.BeginPaint(hwnd, &paint);
            defer _ = win.EndPaint(hwnd, &paint);
            var shapes = smooth.Context.init(hdc);
            defer shapes.deinit();
            paintPopupInput(&shapes, hwnd, win.GetDlgItem(hwnd, id_tg_edit));
            return 0;
        },
        win.WM_DRAWITEM => {
            const item: *win.DRAWITEMSTRUCT = winHandle(*win.DRAWITEMSTRUCT, @as(usize, @bitCast(lparam)));
            drawSetupButton(a, item);
            return 1;
        },
        win.WM_CTLCOLORSTATIC, win.WM_CTLCOLOREDIT => {
            const hdc: win.HDC = winHandle(win.HDC, wparam);
            _ = win.SetTextColor(hdc, theme.current.on_surface);
            if (theme.choice == .amoled and win.GetDlgItem(hwnd, id_tg_edit) == winHandle(win.HWND, @as(usize, @bitCast(lparam)))) {
                _ = win.SetBkColor(hdc, theme.current.surface_container_high);
                return @bitCast(@intFromPtr(a.brush_raised.?));
            }
            _ = win.SetBkColor(hdc, theme.current.surface_container_low);
            if (a.brush_panel) |brush| return @bitCast(@intFromPtr(brush));
            return @bitCast(@intFromPtr(win.GetStockObject(win.BLACK_BRUSH)));
        },
        win.WM_COMMAND => {
            const id = loword(wparam);
            const notification = hiword(wparam);
            if (id == id_tg_edit and (notification == win.EN_SETFOCUS or notification == win.EN_KILLFOCUS)) {
                _ = win.InvalidateRect(hwnd, null, win.FALSE);
                return 0;
            }
            if (id == id_tg_next or id == 1) {
                tgLoginSubmit(a);
                return 0;
            }
            if (id == id_tg_cancel or id == 2) {
                closeTgLogin(a);
                return 0;
            }
            if (id == id_tg_open_page) {
                openMyTelegramPage(a);
                return 0;
            }
            return 0;
        },
        win.WM_CLOSE => {
            closeTgLogin(a);
            return 0;
        },
        win.WM_NCDESTROY => {
            a.tg_login_window = null;
            if (a.hwnd) |main_hwnd| {
                _ = win.EnableWindow(main_hwnd, 1);
                _ = win.SetFocus(main_hwnd);
            }
            return 0;
        },
        else => {},
    }
    return win.DefWindowProcW(hwnd, message, wparam, lparam);
}

fn tgLoginSubmit(a: *App) void {
    const window = a.tg_login_window orelse return;
    const edit = win.GetDlgItem(window, id_tg_edit) orelse return;
    var wide_buffer: [128]u16 = [_]u16{0} ** 128;
    const length: usize = @intCast(win.GetWindowTextW(edit, &wide_buffer, wide_buffer.len));
    if (length == 0) return;
    const text = std.unicode.utf16LeToUtf8Alloc(a.allocator, wide_buffer[0..length]) catch return;
    defer a.allocator.free(text);
    if (hubConfigured(a)) return;
    const trimmed = std.mem.trim(u8, text, " ");
    switch (a.tg_login) {
        .phone, .code, .password => {
            const client = a.telegram orelse {
                tgLoginShowError(a, "Telegram is not running. Close this window and choose Add Telegram account again.");
                return;
            };
            switch (a.tg_login) {
                .phone => client.authPhone(trimmed),
                .code => client.authCode(trimmed),
                .password => client.authPassword(trimmed),
                else => unreachable,
            }
            tgLoginSetChecking(a);
            setStatus(a, "Telegram: checking with Telegram...");
        },
        .api_id, .api_hash => handleTgKeyInput(a, trimmed),
        .none => {},
    }
}

fn handleTgKeyInput(a: *App, trimmed: []const u8) void {
    switch (a.tg_login) {
        .api_id => {
            const parsed = parseTgApiId(trimmed) orelse {
                tgLoginShowError(a, "The api_id is a number. Type it again.");
                return;
            };
            a.tg_api_id = parsed;
            openTelegramLogin(a, .api_hash);
        },
        .api_hash => {
            if (!validTgApiHash(trimmed)) {
                tgLoginShowError(a, tg_api_hash_error);
                return;
            }
            a.tg_api_hash.set(trimmed);
            if (!saveTelegramKeys(a)) {
                tgLoginShowError(a, "Could not save the Telegram keys on this PC. Try again.");
                return;
            }
            createTelegramClient(a);
            if (a.telegram == null) {
                tgLoginShowError(a, "Telegram could not start on this PC. Press Next to try again.");
                return;
            }
            openTelegramLogin(a, .phone);
            setStatus(a, "Telegram: keys saved. Type your phone number and press Next");
        },
        else => {},
    }
}

fn openMyTelegramPage(a: *App) void {
    if (hubConfigured(a)) return;
    if (!shell_lazy.ensureShell32()) return;
    const url_wide = utf8ToWide(a.allocator, "https://my.telegram.org/apps") catch return;
    defer a.allocator.free(url_wide);
    const result = shell_lazy.shellExecuteW.?(a.hwnd orelse null, lit("open"), url_wide.ptr, null, null, win.SW_SHOWNORMAL);
    if (@intFromPtr(result) <= 32) setStatus(a, "Windows could not open the browser");
}

fn createTelegramClient(a: *App) void {
    if (hubConfigured(a)) return setStatus(a, "Manage accounts on the hub");
    if (a.telegram != null) return;
    if (a.tg_api_id == 0 or a.tg_api_hash.len == 0) {
        setStatus(a, "Telegram needs an api_id and api_hash before it can start");
        return;
    }
    if (a.tg_data_dir.len == 0) {
        setStatus(a, "Telegram could not start: its data folder is missing");
        return;
    }
    a.telegram = tg.Client.create(a.allocator, a.io, a.tg_api_id, a.tg_api_hash.slice(), a.tg_data_dir.slice());
    if (a.telegram == null) setStatus(a, "Telegram could not start on this PC");
}

fn startTelegramAdd(a: *App) void {
    if (hubConfigured(a)) return setStatus(a, "Manage accounts on the hub");
    if (!tg.enabled) {
        setStatus(a, "Telegram is not in this build");
        return;
    }
    if (a.tg_auth == .ready) {
        setStatus(a, "Telegram is already connected");
        return;
    }
    if (a.telegram == null) {
        if (a.tg_api_id == 0 or a.tg_api_hash.len == 0) {
            openTelegramLogin(a, .api_id);
            return;
        }
        createTelegramClient(a);
        if (a.telegram == null) {
            if (a.tg_login == .none) openTelegramLogin(a, .api_hash);
            return;
        }
    }
    openTelegramLogin(a, switch (a.tg_auth) {
        .wait_code => .code,
        .wait_password => .password,
        else => .phone,
    });
}

fn saveTelegramKeys(a: *App) bool {
    var key: win.HKEY = undefined;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, null) != win.ERROR_SUCCESS) return false;
    defer _ = win.RegCloseKey(key);
    var id_buffer: [16]u8 = undefined;
    const id_text = std.fmt.bufPrint(&id_buffer, "{d}", .{a.tg_api_id}) catch return false;
    const id_wide = utf8ToWide(a.allocator, id_text) catch return false;
    defer a.allocator.free(id_wide);
    const id_saved = win.RegSetValueExW(key, lit("TelegramApiId"), 0, win.REG_SZ, @ptrCast(id_wide.ptr), @intCast((id_wide.len + 1) * 2)) == win.ERROR_SUCCESS;
    const hash_saved = slack_win.saveSecret(lit("TelegramApiHash"), a.tg_api_hash.slice());
    if (!id_saved or !hash_saved) {
        _ = win.RegDeleteValueW(key, lit("TelegramApiId"));
        _ = win.RegDeleteValueW(key, lit("TelegramApiHash"));
        return false;
    }
    return true;
}

fn deleteTelegramKeys(a: *App) void {
    var key: win.HKEY = undefined;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, null) != win.ERROR_SUCCESS) return;
    defer _ = win.RegCloseKey(key);
    _ = win.RegDeleteValueW(key, lit("TelegramApiId"));
    _ = win.RegDeleteValueW(key, lit("TelegramApiHash"));
    a.tg_api_id = 0;
    a.tg_api_hash.set("");
}

fn wipeBadTelegramKeys(a: *App) void {
    deleteTelegramKeys(a);
    if (a.telegram) |client| {
        a.telegram = null;
        client.destroy();
    }
    openTelegramLogin(a, .api_id);
}

fn removeTelegramAccount(a: *App) void {
    if (a.telegram) |client| {
        a.telegram = null;
        client.destroy();
    }
    deleteTelegramKeys(a);
    a.tg_login = .none;
    if (a.tg_login_window) |window| _ = win.DestroyWindow(window);
    a.tg_auth = .unknown;
    a.tg_account.set("");
    a.tg_chat_count = 0;
    @memset(a.tg_chats, .{});
    var removed = true;
    if (a.tg_data_dir.len > 0) {
        std.Io.Dir.cwd().deleteTree(a.io, a.tg_data_dir.slice()) catch {
            removed = false;
        };
    }
    refreshVisibleChats(a);
    if (!messagesAreCurrent(a)) refreshMessages(a);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    setStatus(a, if (removed) "Telegram removed from this PC" else "Telegram signed out, but its files could not be deleted");
}

fn tdlibSmoke(io: std.Io) u8 {
    const client = tg.Client.create(std.heap.page_allocator, io, 1, "smoke", "tdlib-smoke") orelse return 1;
    defer client.destroy();
    var waited_ms: u32 = 0;
    while (waited_ms < 20_000) {
        if (client.poll()) |event_in| {
            var event = event_in;
            defer event.deinit(std.heap.page_allocator);
            if (event == .auth) switch (event.auth.state) {
                .wait_parameters, .wait_phone, .wait_code, .wait_password, .wait_registration, .wait_email, .ready => return 0,
                else => return 1,
            };
        }
        io.sleep(std.Io.Duration.fromMilliseconds(100), .awake) catch return 1;
        waited_ms += 100;
    }
    return 1;
}

var smoke_unfurl_done_count: u32 = 0;

fn smokeUnfurlProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    if (message == wm_unfurl_done) {
        const result: *UnfurlResult = @ptrFromInt(@as(usize, @bitCast(lparam)));
        if (app_ptr) |a| {
            applyUnfurlResult(a, result);
        } else {
            if (result.thumb) |bytes| std.heap.page_allocator.free(bytes);
            std.heap.page_allocator.destroy(result);
        }
        _ = @atomicRmw(u32, &smoke_unfurl_done_count, .Add, 1, .monotonic);
        return 0;
    }
    return win.DefWindowProcW(hwnd, message, wparam, lparam);
}

fn smokePump(io: std.Io, timeout_ms: u32, target_done: u32) void {
    var waited: u32 = 0;
    while (waited < timeout_ms) {
        var message = std.mem.zeroes(win.MSG);
        while (win.PeekMessageW(&message, null, 0, 0, win.PM_REMOVE) != 0) {
            _ = win.TranslateMessage(&message);
            _ = win.DispatchMessageW(&message);
        }
        if (@atomicLoad(u32, &smoke_unfurl_done_count, .monotonic) >= target_done) return;
        io.sleep(std.Io.Duration.fromMilliseconds(50), .awake) catch return;
        waited += 50;
    }
}

fn smokeRectsClose(a: win.RECT, b: win.RECT, tolerance: u32) bool {
    return @abs(a.left - b.left) <= tolerance and @abs(a.top - b.top) <= tolerance and
        @abs(a.right - b.right) <= tolerance and @abs(a.bottom - b.bottom) <= tolerance;
}

fn smokeWindowRect(hwnd: win.HWND) win.RECT {
    var rect = std.mem.zeroes(win.RECT);
    _ = win.GetWindowRect(hwnd, &rect);
    return rect;
}

fn smokeHasCaption(hwnd: win.HWND) bool {
    const style = win.GetWindowLongPtrW(hwnd, win.GWL_STYLE);
    return (style & @as(isize, @intCast(win.WS_CAPTION))) != 0;
}

fn smokeMonitorRect(hwnd: win.HWND) win.RECT {
    const monitor = win.MonitorFromWindow(hwnd, win.MONITOR_DEFAULTTONEAREST);
    var info = std.mem.zeroes(win.MONITORINFO);
    info.cbSize = @sizeOf(win.MONITORINFO);
    _ = win.GetMonitorInfoW(monitor, &info);
    return info.rcMonitor;
}

fn smokeWriteBmp(allocator: std.mem.Allocator, io: std.Io, dir: []const u8, name: []const u8, width: i32, height: i32, pixels: []const u8) void {
    var blob: std.ArrayList(u8) = .empty;
    defer blob.deinit(allocator);
    const data_size: u32 = @intCast(pixels.len);
    var file_header: [14]u8 = .{ 'B', 'M' } ++ [_]u8{0} ** 12;
    std.mem.writeInt(u32, file_header[2..6], 54 + data_size, .little);
    std.mem.writeInt(u32, file_header[10..14], 54, .little);
    var info_header = std.mem.zeroes(win.BITMAPINFOHEADER);
    info_header.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info_header.biWidth = width;
    info_header.biHeight = -height;
    info_header.biPlanes = 1;
    info_header.biBitCount = 32;
    info_header.biCompression = win.BI_RGB;
    info_header.biSizeImage = data_size;
    blob.appendSlice(allocator, &file_header) catch return;
    blob.appendSlice(allocator, std.mem.asBytes(&info_header)) catch return;
    blob.appendSlice(allocator, pixels) catch return;
    const path = std.fs.path.join(allocator, &.{ dir, name }) catch return;
    defer allocator.free(path);
    std.Io.Dir.cwd().writeFile(io, .{ .sub_path = path, .data = blob.items }) catch {};
}

fn smokeCaptureWindow(allocator: std.mem.Allocator, io: std.Io, dir: []const u8, name: []const u8, hwnd: win.HWND) bool {
    const rect = smokeWindowRect(hwnd);
    const w = rect.right - rect.left;
    const h = rect.bottom - rect.top;
    if (w <= 0 or h <= 0) return false;
    const window_dc = win.GetWindowDC(hwnd) orelse return false;
    defer _ = win.ReleaseDC(hwnd, window_dc);
    const memory = win.CreateCompatibleDC(window_dc) orelse return false;
    defer _ = win.DeleteDC(memory);
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = w;
    info.bmiHeader.biHeight = -h;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(memory, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return false;
    defer _ = win.DeleteObject(bitmap);
    if (bits == null) return false;
    const old = win.SelectObject(memory, bitmap);
    defer _ = win.SelectObject(memory, old);
    if (win.BitBlt(memory, 0, 0, w, h, window_dc, 0, 0, win.SRCCOPY) == 0) return false;
    const pixel_count = @as(usize, @intCast(w)) * @as(usize, @intCast(h)) * 4;
    const pixels = @as([*]const u8, @ptrCast(bits.?))[0..pixel_count];
    smokeWriteBmp(allocator, io, dir, name, w, h, pixels);
    return true;
}

fn smokeDrawCard(allocator: std.mem.Allocator, io: std.Io, a: *App, dir: []const u8, name: []const u8, provider: unfurl.Provider, id: []const u8, canonical: []const u8) bool {
    const width: i32 = 360;
    const height: i32 = 120;
    const screen_dc = win.GetDC(null) orelse return false;
    defer _ = win.ReleaseDC(null, screen_dc);
    const memory = win.CreateCompatibleDC(screen_dc) orelse return false;
    defer _ = win.DeleteDC(memory);
    _ = win.SetBkMode(memory, win.TRANSPARENT);
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = width;
    info.bmiHeader.biHeight = -height;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(memory, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return false;
    defer _ = win.DeleteObject(bitmap);
    if (bits == null) return false;
    const old = win.SelectObject(memory, bitmap);
    defer _ = win.SelectObject(memory, old);
    const background = win.CreateSolidBrush(theme.current.surface) orelse return false;
    defer _ = win.DeleteObject(background);
    _ = win.FillRect(memory, &.{ .left = 0, .top = 0, .right = width, .bottom = height }, background);
    var message = Message{};
    message.unfurl_provider = provider;
    message.unfurl_id.set(id);
    message.unfurl_canonical.set(canonical);
    var shapes = smooth.Context.init(memory);
    defer shapes.deinit();
    drawUnfurlCard(&shapes, memory, a, &message, 20, 10, 320);
    const pixel_count = @as(usize, @intCast(width)) * @as(usize, @intCast(height)) * 4;
    const pixels = @as([*]const u8, @ptrCast(bits.?))[0..pixel_count];
    smokeWriteBmp(allocator, io, dir, name, width, height, pixels);
    return true;
}

fn smokeMfProbe(a: *App, url: [*:0]const u16) win.HRESULT {
    if (!mf_lazy.ensureStarted()) return -1;
    var player: ?*win.IMFPMediaPlayer = null;
    const hr = mf_lazy.createMediaPlayer.?(url, 0, win.MFP_OPTION_NONE, &player_callback, a.hwnd orelse null, &player);
    if (player) |opened| {
        _ = opened.lpVtbl.*.Shutdown.?(opened);
        _ = opened.lpVtbl.*.Release.?(opened);
    }
    return hr;
}

const SmokePlayback = struct { state: win.MFP_MEDIAPLAYER_STATE = win.MFP_MEDIAPLAYER_STATE_EMPTY, width: i32 = 0, height: i32 = 0 };

fn smokeWaitPlaying(io: std.Io, a: *App, timeout_ms: u32) SmokePlayback {
    var result = SmokePlayback{};
    var waited: u32 = 0;
    while (waited < timeout_ms) : (waited += 100) {
        smokePump(io, 100, 0xFFFFFFFF);
        const player = a.mf_player orelse return result;
        var state: win.MFP_MEDIAPLAYER_STATE = win.MFP_MEDIAPLAYER_STATE_EMPTY;
        _ = player.lpVtbl.*.GetState.?(player, &state);
        var size = std.mem.zeroes(win.SIZE);
        _ = player.lpVtbl.*.GetNativeVideoSize.?(player, &size, null);
        result = .{ .state = state, .width = size.cx, .height = size.cy };
        if (state == win.MFP_MEDIAPLAYER_STATE_PLAYING and size.cx > 0 and size.cy > 0) return result;
    }
    return result;
}

fn smokeStateName(state: win.MFP_MEDIAPLAYER_STATE) []const u8 {
    return switch (state) {
        win.MFP_MEDIAPLAYER_STATE_EMPTY => "EMPTY",
        win.MFP_MEDIAPLAYER_STATE_STOPPED => "STOPPED",
        win.MFP_MEDIAPLAYER_STATE_PLAYING => "PLAYING",
        win.MFP_MEDIAPLAYER_STATE_PAUSED => "PAUSED",
        win.MFP_MEDIAPLAYER_STATE_SHUTDOWN => "SHUTDOWN",
        else => "UNKNOWN",
    };
}

const SmokeLog = struct {
    allocator: std.mem.Allocator,
    io: std.Io,
    dir: []const u8,
    buffer: std.ArrayList(u8) = .empty,

    fn line(self: *SmokeLog, comptime fmt: []const u8, args: anytype) void {
        const text = std.fmt.allocPrint(self.allocator, fmt ++ "\n", args) catch return;
        defer self.allocator.free(text);
        self.buffer.appendSlice(self.allocator, text) catch {};
    }

    fn flush(self: *SmokeLog) void {
        const path = std.fs.path.join(self.allocator, &.{ self.dir, "results.txt" }) catch return;
        defer self.allocator.free(path);
        std.Io.Dir.cwd().writeFile(self.io, .{ .sub_path = path, .data = self.buffer.items }) catch {};
    }
};

fn unfurlSmoke(init: std.process.Init) u8 {
    const allocator = init.gpa;
    const instance = win.GetModuleHandleW(null) orelse return 1;
    const out_dir = init.environ_map.get("UNFURL_SMOKE_DIR") orelse "unfurl-smoke";
    std.Io.Dir.cwd().createDirPath(init.io, out_dir) catch {};

    var smoke_log = SmokeLog{ .allocator = allocator, .io = init.io, .dir = out_dir };
    var failures: u32 = 0;

    const Case = struct { url: []const u8, provider: unfurl.Provider, id: []const u8 = "" };
    const cases = [_]Case{
        .{ .url = "https://www.youtube.com/watch?v=dQw4w9WgXcQ", .provider = .youtube, .id = "dQw4w9WgXcQ" },
        .{ .url = "https://youtu.be/dQw4w9WgXcQ?t=42", .provider = .youtube, .id = "dQw4w9WgXcQ" },
        .{ .url = "https://www.youtube.com/shorts/dQw4w9WgXcQ?feature=share", .provider = .youtube, .id = "dQw4w9WgXcQ" },
        .{ .url = "https://www.instagram.com/reel/Cabcdefghij/", .provider = .instagram, .id = "Cabcdefghij" },
        .{ .url = "https://www.instagram.com/p/Cabcdefghij/?img_index=1", .provider = .instagram, .id = "Cabcdefghij" },
        .{ .url = "https://www.facebook.com/watch?v=1234567890", .provider = .facebook, .id = "1234567890" },
        .{ .url = "https://www.facebook.com/nike/videos/9876543210/", .provider = .facebook, .id = "9876543210" },
        .{ .url = "https://fb.watch/AbCdEf123/", .provider = .facebook, .id = "AbCdEf123" },
        .{ .url = "https://example.com/watch?v=dQw4w9WgXcQ", .provider = .page },
        .{ .url = "https://youtube.com.evil.com/watch?v=dQw4w9WgXcQ", .provider = .page },
        .{ .url = "https://www.facebook.com/photo/?fbid=123", .provider = .page },
    };
    for (cases) |case| {
        const info = unfurl.classify(case.url);
        const ok = info.provider == case.provider and
            (case.id.len == 0 or std.mem.eql(u8, info.idSlice(), case.id));
        if (!ok) failures += 1;
        smoke_log.line("classify {s}: {s} (got {s}/{s})", .{ case.url, if (ok) "PASS" else "FAIL", @tagName(info.provider), info.idSlice() });
    }

    const Target = struct { provider: unfurl.Provider, id: []const u8, url: []const u8 };
    const targets = [_]Target{
        .{ .provider = .youtube, .id = "dQw4w9WgXcQ", .url = "https://www.youtube.com/watch?v=dQw4w9WgXcQ" },
        .{ .provider = .instagram, .id = "Cabcdefghij", .url = "https://www.instagram.com/reel/Cabcdefghij/" },
        .{ .provider = .facebook, .id = "1234567890", .url = "https://www.facebook.com/watch?v=1234567890" },
    };

    _ = win.SetProcessDpiAwarenessContext(win.DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);
    const font_files = @import("font_config.zig").files;
    var plex_loaded: usize = 0;
    var font_paths: [font_files.len]WideText(519) = undefined;
    var font_pointers: [font_files.len][*:0]const u16 = undefined;
    inline for (font_files, 0..) |file, i| {
        font_paths[i] = bundledFilePath(file);
        const font_path = &font_paths[i];
        font_pointers[i] = font_path.ptr();
        if (win.AddFontResourceExW(font_path.ptr(), win.FR_PRIVATE, null) > 0) plex_loaded += 1;
    }
    smoke_log.line("fonts: private IBM Plex loaded = {} ({}/{})", .{ plex_loaded == font_files.len, plex_loaded, font_files.len });
    text_draw.setBundledFontPaths(&font_pointers);
    _ = win.CoInitializeEx(null, win.COINIT_APARTMENTTHREADED);
    defer win.CoUninitialize();
    defer text_draw.reset();
    smoke_log.line("text: directwrite = {}", .{text_draw.available()});
    _ = mf_lazy.ensureStarted();
    defer mf_lazy.unloadIfStarted();

    var scratch: [1]u8 = .{0};
    const app = allocator.create(App) catch return 1;
    defer allocator.destroy(app);
    app.* = .{
        .allocator = allocator,
        .people = people_index.Index.init(allocator),
        .io = init.io,
        .instance = instance,
        .wacli_path = scratch[0..0],
        .avatar_dir = scratch[0..0],
    };
    defer app.allocator.free(app.chats);
    defer app.allocator.free(app.tg_chats);
    defer {
        persistDrafts(app);
        app.draft_store.deinit(app.allocator);
    }
    defer app.people.deinit();
    defer if (app.chats_raw) |raw| allocator.free(raw);
    app_ptr = app;
    defer app_ptr = null;
    _ = win.CoCreateInstance(&win.CLSID_WICImagingFactory, null, win.CLSCTX_INPROC_SERVER, &win.IID_IWICImagingFactory, @ptrCast(&app.wic_factory));
    text_draw.reset();
    recreateFonts(app);

    var smoke_class = win.WNDCLASSEXW{
        .cbSize = @sizeOf(win.WNDCLASSEXW),
        .lpfnWndProc = smokeUnfurlProc,
        .hInstance = instance,
        .lpszClassName = lit("MessagesUnfurlSmoke"),
    };
    if (win.RegisterClassExW(&smoke_class) == 0) {
        smoke_log.line("FAIL: could not register the smoke window class", .{});
        smoke_log.flush();
        return 1;
    }
    const smoke_hwnd = win.CreateWindowExW(0, lit("MessagesUnfurlSmoke"), lit("Messages unfurl smoke"), win.WS_OVERLAPPED, 0, 0, 0, 0, null, null, instance, null) orelse {
        smoke_log.line("FAIL: could not create the smoke message window", .{});
        smoke_log.flush();
        return 1;
    };
    defer _ = win.DestroyWindow(smoke_hwnd);
    app.hwnd = smoke_hwnd;

    for (targets, 0..) |target, index| {
        app.unfurl_entries[index].provider = target.provider;
        app.unfurl_entries[index].id.set(target.id);
        app.unfurl_entry_count = index + 1;
    }
    for (targets, 0..) |target, index| startUnfurlFetch(app, &app.unfurl_entries[index], target.url);
    smokePump(init.io, 45_000, targets.len);
    if (@atomicLoad(u32, &smoke_unfurl_done_count, .monotonic) < targets.len) {
        failures += 1;
        smoke_log.line("FAIL: only {d} of {d} unfurl fetches completed within the timeout", .{ @atomicLoad(u32, &smoke_unfurl_done_count, .monotonic), targets.len });
    }
    for (app.unfurl_entries[0..targets.len]) |*entry| {
        const decision: []const u8 = if (entry.play_url.len > 0) "inline play" else "open externally (ticket fallback)";
        smoke_log.line("card {s}/{s}: status={s} title_bytes={d} author_bytes={d} thumbnail={} decision={s}", .{
            @tagName(entry.provider),
            entry.id.slice(),
            @tagName(entry.status),
            entry.title.len,
            entry.author.len,
            entry.thumb != null,
            decision,
        });
    }

    const card_names = [_][]const u8{ "card-youtube.bmp", "card-instagram.bmp", "card-facebook.bmp" };
    for (targets, card_names) |spec, name| {
        const drawn = smokeDrawCard(allocator, init.io, app, out_dir, name, spec.provider, spec.id, spec.url);
        if (!drawn) failures += 1;
        smoke_log.line("render {s}: {s}", .{ name, if (drawn) "PASS" else "FAIL" });
    }

    const clip_path = init.environ_map.get("UNFURL_SMOKE_VIDEO") orelse "";
    var play_entry = UnfurlEntry{};
    play_entry.play_url.set(allocator, clip_path);
    if (clip_path.len > 0) playUnfurlVideo(app, &play_entry);
    const playback = smokeWaitPlaying(init.io, app, 8_000);
    const media_opened = app.player_window != null and app.mf_player != null;
    if (clip_path.len == 0) {
        failures += 1;
        smoke_log.line("FAIL: the test clip path is not set (UNFURL_SMOKE_VIDEO)", .{});
    } else if (!media_opened) {
        failures += 1;
        const hr = smokeMfProbe(app, play_entry.play_url.ptr());
        smoke_log.line("FAIL: the test clip {s} did not open in the player: MFPlay returned hr=0x{x:0>8}", .{ clip_path, @as(u32, @bitCast(hr)) });
    } else {
        const playing = playback.state == win.MFP_MEDIAPLAYER_STATE_PLAYING and playback.width > 0 and playback.height > 0;
        if (!playing) failures += 1;
        smoke_log.line("media: test clip {s} state={s} video={d}x{d}: {s}", .{ clip_path, smokeStateName(playback.state), playback.width, playback.height, if (playing) "PASS" else "FAIL" });
    }
    var player_hwnd = app.player_window;
    if (player_hwnd == null) {
        player_hwnd = openPlayerWindow(app, 800, 450);
        if (player_hwnd) |hwnd| _ = win.ShowWindow(hwnd, win.SW_SHOW);
    }
    const bare_window = player_hwnd orelse {
        failures += 1;
        smoke_log.line("FAIL: the player window did not open", .{});
        smoke_log.line("SMOKE RESULT: FAIL ({d} checks failed)", .{failures});
        smoke_log.flush();
        return 1;
    };
    smokePump(init.io, 2_000, 0xFFFFFFFF);
    const windowed_shot = smokeCaptureWindow(allocator, init.io, out_dir, "player-windowed.bmp", bare_window);
    smoke_log.line("capture player-windowed.bmp: {}", .{windowed_shot});

    const caption_before = smokeHasCaption(bare_window);
    togglePlayerFullscreen(app, bare_window);
    const entered = !smokeHasCaption(bare_window) and smokeRectsClose(smokeWindowRect(bare_window), smokeMonitorRect(bare_window), 8);
    if (!entered or !caption_before) failures += 1;
    smoke_log.line("fullscreen enter: had caption before = {}, borderless and covering monitor after = {}: {s}", .{ caption_before, entered, if (entered and caption_before) "PASS" else "FAIL" });
    smokePump(init.io, 2_000, 0xFFFFFFFF);
    const fullscreen_shot = smokeCaptureWindow(allocator, init.io, out_dir, "player-fullscreen.bmp", bare_window);
    smoke_log.line("capture player-fullscreen.bmp: {}", .{fullscreen_shot});

    togglePlayerFullscreen(app, bare_window);
    const restored = smokeHasCaption(bare_window) and
        smokeRectsClose(smokeWindowRect(bare_window), app.player_saved_placement.rcNormalPosition, 8);
    if (!restored) failures += 1;
    smoke_log.line("fullscreen exit: caption and placement restored = {}: {s}", .{ restored, if (restored) "PASS" else "FAIL" });

    _ = win.PostMessageW(bare_window, win.WM_KEYDOWN, win.VK_ESCAPE, 0);
    smokePump(init.io, 3_000, 0xFFFFFFFF);
    const closed = app.player_window == null and app.mf_player == null;
    if (!closed) failures += 1;
    smoke_log.line("player close on ESC: {s}", .{if (closed) "PASS" else "FAIL"});

    smoke_log.line("SMOKE RESULT: {s} ({d} checks failed)", .{ if (failures == 0) "PASS" else "FAIL", failures });
    smoke_log.flush();
    return if (failures == 0) 0 else 1;
}

fn slackInstallation(a: *App, account: []const u8) ?*SlackInstallation {
    for (&a.slack_installations) |*installation| {
        if (installation.active and std.mem.eql(u8, installation.team_id.slice(), account)) return installation;
    }
    return null;
}

fn slackChatCount(a: *App) usize {
    var count: usize = 0;
    for (&a.slack_installations) |*installation| if (installation.active) {
        count += installation.chat_count;
    };
    return count;
}

fn slackWorkspaceCount(a: *App) usize {
    var count: usize = 0;
    for (&a.slack_installations) |*installation| if (installation.active) {
        count += 1;
    };
    return count;
}

fn slackAccountConfigured(a: *App, account: []const u8) bool {
    return slackInstallation(a, account) != null;
}

fn slackAccountIsBridge(a: *App, account: []const u8) bool {
    const installation = slackInstallation(a, account) orelse return false;
    return installation.is_bridge;
}

fn slackConfigured(a: *App) bool {
    for (&a.slack_installations) |*installation| if (installation.active) return true;
    return a.slack_tokens != null or a.slack_bridge != null;
}

fn slackContext(a: *App, account: []const u8, legacy_bridge: bool) ?slack_win.JobContext {
    a.slack_install_mutex.lockUncancelable(a.io);
    defer a.slack_install_mutex.unlock(a.io);
    const installation = slackInstallation(a, account);
    const bridge = if (installation) |install| install.is_bridge else legacy_bridge and a.slack_bridge != null and account.len == 0;
    const token = if (bridge) (if (a.slack_bridge) |config| config.key else return null) else if (installation) |install| install.user_token else if (account.len == 0 and a.slack_tokens != null) a.slack_tokens.?.user else return null;
    const host = if (bridge) a.slack_bridge.?.host else "slack.com";
    const media_dir = if (installation) |install| install.media_dir.slice() else a.slack_media_dir;
    const owned_token = a.allocator.dupe(u8, token) catch return null;
    const owned_host = a.allocator.dupe(u8, host) catch {
        a.allocator.free(owned_token);
        return null;
    };
    const owned_dir = a.allocator.dupe(u8, media_dir) catch {
        a.allocator.free(owned_token);
        a.allocator.free(owned_host);
        return null;
    };
    return .{ .user_token = owned_token, .host = owned_host, .is_bridge = bridge, .media_dir = owned_dir, .io = a.io };
}

fn requireSlackSignIn(a: *App, account: []const u8, failed_token: []const u8) void {
    a.slack_install_mutex.lockUncancelable(a.io);
    defer a.slack_install_mutex.unlock(a.io);
    if (slackInstallation(a, account)) |installation| {
        if (std.mem.eql(u8, installation.user_token, failed_token)) installation.needs_signin.store(true, .release);
    }
}

fn refreshSlackCredentials(a: *App, account: []const u8, auth_error: []const u8, failed_token: []const u8) !void {
    var arena_state = std.heap.ArenaAllocator.init(a.allocator);
    defer arena_state.deinit();
    const arena = arena_state.allocator();
    a.slack_install_mutex.lockUncancelable(a.io);
    const installation = slackInstallation(a, account) orelse {
        a.slack_install_mutex.unlock(a.io);
        return error.WorkspaceDisconnected;
    };
    if (installation.is_bridge) {
        a.slack_install_mutex.unlock(a.io);
        return;
    }
    if (auth_error.len > 0 and !std.mem.eql(u8, installation.user_token, failed_token)) {
        a.slack_install_mutex.unlock(a.io);
        return;
    }
    if (installation.needs_signin.load(.acquire)) {
        a.slack_install_mutex.unlock(a.io);
        return error.SignInRequired;
    }
    if (!slack_oauth.refreshDue(nowUnixSeconds(), installation.expires_at, installation.refresh_token.len > 0, auth_error)) {
        const invalid = auth_error.len > 0 or (installation.expires_at > 0 and nowUnixSeconds() >= installation.expires_at);
        if (invalid) installation.needs_signin.store(true, .release);
        a.slack_install_mutex.unlock(a.io);
        if (invalid) return error.SignInRequired;
        return;
    }
    const generation = installation.generation;
    const saved: slack_win.Installation = snapshot: {
        defer a.slack_install_mutex.unlock(a.io);
        break :snapshot .{
            .team_id = try arena.dupe(u8, installation.team_id.slice()),
            .team_name = try arena.dupe(u8, installation.team_name.slice()),
            .user_id = try arena.dupe(u8, installation.user_id.slice()),
            .user_token = try arena.dupe(u8, installation.user_token),
            .refresh_token = try arena.dupe(u8, installation.refresh_token),
            .expires_at = installation.expires_at,
        };
    };
    const client_id = slack_win.loadClientId(arena) orelse {
        requireSlackSignIn(a, account, saved.user_token);
        return error.SignInRequired;
    };
    const rotated: anyerror!slack_oauth.RefreshedTokens = exchange: {
        const body = slack_oauth.buildRefreshBody(arena, client_id, saved.refresh_token) catch |err| break :exchange err;
        const json = slack_win.exchangeOAuth(arena, body) catch |err| break :exchange err;
        break :exchange slack_oauth.parseRefreshResponse(arena, json);
    };
    a.slack_install_mutex.lockUncancelable(a.io);
    defer a.slack_install_mutex.unlock(a.io);
    const current = slackInstallation(a, account) orelse return error.WorkspaceDisconnected;
    if (current.generation != generation) return error.WorkspaceChanged;
    const tokens = rotated catch {
        current.needs_signin.store(true, .release);
        return error.SignInRequired;
    };
    if (!slack_win.isUserToken(tokens.access_token)) {
        current.needs_signin.store(true, .release);
        return error.SignInRequired;
    }
    const access = a.allocator.dupe(u8, tokens.access_token) catch {
        current.needs_signin.store(true, .release);
        return error.SignInRequired;
    };
    errdefer a.allocator.free(access);
    const refresh = a.allocator.dupe(u8, tokens.refresh_token) catch {
        current.needs_signin.store(true, .release);
        return error.SignInRequired;
    };
    errdefer a.allocator.free(refresh);
    const expiry = nowUnixSeconds() + @as(i64, @intCast(tokens.expires_in));
    if (!slack_win.saveInstallation(.{ .team_id = saved.team_id, .team_name = saved.team_name, .user_id = saved.user_id, .user_token = access, .refresh_token = refresh, .expires_at = expiry })) {
        current.needs_signin.store(true, .release);
        return error.SignInRequired;
    }
    a.allocator.free(current.user_token);
    a.allocator.free(current.refresh_token);
    current.user_token = access;
    current.refresh_token = refresh;
    current.expires_at = expiry;
}

fn runSlackJob(a: *App, account: []const u8, initial: slack_win.JobContext, kind: slack_win.JobKind, args: []const []const u8) ![]u8 {
    if (account.len == 0 or initial.is_bridge) return slack_win.runJob(a.allocator, initial, kind, args);
    try refreshSlackCredentials(a, account, "", "");
    var attempt: usize = 0;
    while (attempt < 2) : (attempt += 1) {
        const context = slackContext(a, account, false) orelse return error.WorkspaceDisconnected;
        defer a.allocator.free(context.user_token);
        defer a.allocator.free(context.host);
        defer a.allocator.free(context.media_dir);
        const outcome = slack_win.runJob(a.allocator, context, kind, args);
        const auth_error = std.mem.sliceTo(&slack_win.last_error, 0);
        if (!std.mem.eql(u8, auth_error, "invalid_auth") and !std.mem.eql(u8, auth_error, "token_expired")) return outcome;
        if (outcome) |data| a.allocator.free(data) else |_| {}
        if (attempt == 1) {
            requireSlackSignIn(a, account, context.user_token);
            return error.SignInRequired;
        }
        try refreshSlackCredentials(a, account, auth_error, context.user_token);
    }
    unreachable;
}

fn slackUserName(installation: *SlackInstallation, user_id: []const u8) ?[]const u8 {
    for (installation.users[0..installation.user_count]) |*user| {
        if (std.mem.eql(u8, user.id.slice(), user_id)) return user.name.slice();
    }
    return null;
}

fn slackUserLookupFn(context: *anyopaque, user_id: []const u8) ?[]const u8 {
    const installation: *SlackInstallation = @ptrCast(@alignCast(context));
    return slackUserName(installation, user_id);
}

fn slackUserLookup(installation: *SlackInstallation) slack.UserLookup {
    return .{ .context = installation, .lookupFn = slackUserLookupFn };
}

fn slackChatById(a: *App, account: []const u8, channel_id: []const u8) ?*Chat {
    const installation = slackInstallation(a, account) orelse return null;
    const index = chat_key.indexOf(Chat, installation.chats[0..installation.chat_count], .{ .provider = .slack, .account = account, .id = channel_id }) orelse return null;
    return &installation.chats[index];
}

fn selectedChatIsSlack(a: *App) bool {
    if (unifiedHub(a)) return false;
    if (a.selected_chat >= a.chat_count) return false;
    return a.chats[a.selected_chat].provider == .slack;
}

fn stagedFileGoesToWacli(provider: transport.Provider) bool {
    return switch (provider) {
        .whatsapp => true,
        .slack, .telegram, .signal => false,
    };
}

fn raiseSlackTimestamp(chat: *Chat, seconds: i64) bool {
    if (seconds <= 0) return false;
    var buffer: [20]u8 = undefined;
    const text = tj.formatTimestamp(&buffer, seconds);
    if (text.len == 0 or std.mem.order(u8, text, chat.timestamp.slice()) != .gt) return false;
    chat.timestamp.set(text);
    return true;
}

fn noteSlackActivity(a: *App, account: []const u8, channel: []const u8, seconds: i64) void {
    if (slackChatById(a, account, channel)) |cached| _ = raiseSlackTimestamp(cached, seconds);
    for (a.chats[0..a.chat_count]) |*chat| {
        if (!chat_key.Key.eql(chat_key.of(chat), .{ .provider = .slack, .account = account, .id = channel })) continue;
        const was_displayed = chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat)) and
            std.mem.eql(u8, a.displayed_timestamp.slice(), chat.timestamp.slice());
        if (raiseSlackTimestamp(chat, seconds) and was_displayed) a.displayed_timestamp.set(chat.timestamp.slice());
        break;
    }
}

fn fillSlackTimestamp(a: *App, chat: *Chat) void {
    if (chat.provider != .slack or chat.timestamp.len > 0) return;
    const key = chat_key.of(chat);
    const disk = if (unifiedHub(a) and msgCacheGet(a, key) == null) loadMsgCacheDisk(a, key.id) else null;
    defer if (disk) |data| a.allocator.free(data);
    const raw = msgCacheGet(a, key) orelse disk orelse return;
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return;
    defer parsed.deinit();
    if (parsed.value != .object) return;
    const data = parsed.value.object.get("data") orelse return;
    if (data != .object) return;
    const messages = data.object.get("messages") orelse return;
    if (messages != .array) return;
    for (messages.array.items) |item| {
        if (item != .object) continue;
        const timestamp = getString(item.object, "Timestamp");
        if (std.mem.order(u8, timestamp, chat.timestamp.slice()) == .gt) chat.timestamp.set(timestamp);
    }
}

fn telegramReady(a: *App) bool {
    return a.telegram != null and a.tg_auth == .ready;
}

fn activeChatView(a: *App) messenger_view.View {
    return a.chat_view;
}

fn selectedViewKey(a: *App) *chat_key.Stored {
    for (a.views.items) |*view| {
        if (messenger_view.accountMatches(a.chat_view, a.view_account.slice(), view.key.key()) and a.view_account.len > 0) return &view.selected;
    }
    return &a.view_selected[@intFromEnum(a.chat_view)];
}

fn chatViewKey(chat: *const Chat) chat_key.Key {
    var key = chat_key.of(chat);
    if (chat.view_account.len > 0) key.account = chat.view_account.slice();
    return key;
}

fn chatInView(a: *App, key: chat_key.Key) bool {
    return messenger_view.accountMatches(activeChatView(a), a.view_account.slice(), key);
}

fn activeViewLabel(a: *App) []const u8 {
    for (a.views.items) |*view| {
        if (a.view_account.len > 0 and chatInView(a, view.key.key())) return view.labelText();
    }
    return messenger_view.label(activeChatView(a));
}

fn updateWindowTitle(a: *App) void {
    const hwnd = a.hwnd orelse return;
    const label = if (activeChatView(a) == .all) "Combined inbox" else activeViewLabel(a);
    var buffer: [512]u8 = undefined;
    const text = messenger_view.windowTitle(&buffer, label, app_version) catch return;
    var wide: [512]u16 = undefined;
    const len = std.unicode.utf8ToUtf16Le(wide[0 .. wide.len - 1], text) catch return;
    wide[len] = 0;
    var current: [512]u16 = undefined;
    const current_len: usize = @intCast(win.GetWindowTextW(hwnd, &current, current.len));
    if (!std.mem.eql(u16, current[0..current_len], wide[0..len])) _ = win.SetWindowTextW(hwnd, &wide);
}

fn hubWorkspaceNames(a: *App, rows: []const std.json.Value) ?std.json.Parsed(std.json.Value) {
    const path = providerStatePath(a, "workspace-names.json") orelse return null;
    defer a.allocator.free(path);
    if (a.hub_workspace_names == null) a.hub_workspace_names = readFileWin(a.allocator, path, msg_cache_max_bytes);
    var names = std.json.parseFromSlice(std.json.Value, a.allocator, a.hub_workspace_names orelse "{}", .{ .allocate = .alloc_always }) catch
        std.json.parseFromSlice(std.json.Value, a.allocator, "{}", .{}) catch return null;
    if (names.value != .object) {
        names.deinit();
        names = std.json.parseFromSlice(std.json.Value, a.allocator, "{}", .{}) catch return null;
    }
    const allocator = names.arena.allocator();
    var changed = false;
    for (rows) |row| {
        if (row != .object) continue;
        const name = hub.workspaceName(row.object);
        if (name.len == 0) continue;
        const account = hub.viewAccount(row.object, a.cache_tag.slice());
        if (std.mem.eql(u8, getString(names.value.object, account), name)) continue;
        const key = allocator.dupe(u8, account) catch continue;
        const value = allocator.dupe(u8, name) catch continue;
        names.value.object.put(allocator, key, .{ .string = value }) catch continue;
        changed = true;
    }
    if (changed) {
        if (std.json.Stringify.valueAlloc(a.allocator, names.value, .{})) |raw| {
            if (a.hub_workspace_names) |old| a.allocator.free(old);
            a.hub_workspace_names = raw;
            _ = writeCacheFileAtomic(a, path, raw);
        } else |_| {}
    }
    return names;
}

fn rebuildViews(a: *App, rows: []const std.json.Value) void {
    const previous_view = a.chat_view;
    const previous_account = a.view_account;
    var known: std.ArrayList(messenger_view.Account) = .empty;
    defer known.deinit(a.allocator);
    if (unifiedHub(a)) {
        var names = hubWorkspaceNames(a, rows);
        defer if (names) |*parsed| parsed.deinit();
        for (a.views.items) |view| {
            messenger_view.appendUnique(a.allocator, &known, view) catch return;
        }
        for (rows) |row| {
            if (row != .object) continue;
            const provider = hub.sourceProvider(row.object) orelse continue;
            const account = hub.viewAccount(row.object, a.cache_tag.slice());
            const key = chat_key.Key{ .provider = provider, .account = account, .id = "" };
            const cached_name = if (names) |parsed| getString(parsed.value.object, account) else "";
            var present: ?usize = null;
            for (known.items, 0..) |existing, index| {
                if (chat_key.Key.eql(existing.key.key(), key)) {
                    present = index;
                    break;
                }
            }
            var saved: ?std.json.Parsed(slack_win.Installation) = null;
            defer if (saved) |*parsed| parsed.deinit();
            const direct_name = if (provider == .slack) name: {
                if (slackInstallation(a, account)) |installation| break :name installation.team_name.slice();
                saved = slack_win.loadInstallation(a.allocator, account);
                break :name if (saved) |parsed| parsed.value.team_name else "";
            } else "";
            const view = hub.accountView(row.object, a.cache_tag.slice(), cached_name, direct_name, if (present) |index| known.items[index] else null) orelse continue;
            if (present) |index| {
                known.items[index] = view;
            } else {
                messenger_view.appendUnique(a.allocator, &known, view) catch return;
            }
        }
    } else {
        if (a.cache_tag.len > 0) messenger_view.appendUnique(a.allocator, &known, messenger_view.Account.init(.whatsapp, a.cache_tag.slice(), a.hub_account.slice())) catch return;
        for (&a.slack_installations) |*installation| {
            if (installation.active) messenger_view.appendUnique(a.allocator, &known, messenger_view.Account.init(.slack, installation.team_id.slice(), installation.team_name.slice())) catch return;
        }
        if (telegramReady(a)) messenger_view.appendUnique(a.allocator, &known, messenger_view.Account.init(.telegram, a.tg_account.slice(), a.tg_account.slice())) catch return;
    }
    if (unifiedHub(a)) {
        messenger_view.appendUnique(a.allocator, &known, messenger_view.Account.init(.signal, "signal", "")) catch return;
        messenger_view.appendUnique(a.allocator, &known, messenger_view.Account.init(.telegram, "telegram", "")) catch return;
    }
    const ordered = messenger_view.mergeOrder(a.allocator, a.view_order, known.items) catch return;
    for (ordered.items) |*view| {
        for (a.views.items) |old| {
            if (chat_key.Key.eql(view.key.key(), old.key.key())) view.selected = old.selected;
        }
    }
    a.views.deinit(a.allocator);
    a.views = ordered;
    _ = saveViewOrder(a);
    if (a.view_account.len == 0 and a.chat_view != .all) {
        for (a.views.items) |view| {
            if (messenger_view.includes(a.chat_view, view.key.provider)) {
                a.view_account.set(view.key.key().account);
                break;
            }
        } else a.chat_view = .all;
    }
    if (a.view_account.len > 0) {
        for (a.views.items) |view| {
            if (chatInView(a, view.key.key())) break;
        } else {
            a.chat_view = .all;
            a.view_account.set("");
        }
    }
    if (previous_view != a.chat_view or !std.mem.eql(u8, previous_account.slice(), a.view_account.slice())) loadViewArchiveSetting(a);
}

fn saveViewOrder(a: *App) bool {
    const text = messenger_view.saveOrder(a.allocator, a.view_order, a.views.items) catch return false;
    if (std.mem.eql(u8, text, a.view_order)) {
        a.allocator.free(text);
        return true;
    }
    if (!saveRegistryString(a.allocator, lit("ViewOrder"), text)) {
        a.allocator.free(text);
        return false;
    }
    if (a.view_order.len > 0) a.allocator.free(a.view_order);
    a.view_order = text;
    return true;
}

fn updateSearchCue(a: *App, view: messenger_view.View) void {
    const search = a.search orelse return;
    var buffer: [300]u8 = undefined;
    _ = view;
    const text = std.fmt.bufPrint(&buffer, "Search {s}  Ctrl+F", .{activeViewLabel(a)}) catch return;
    var wide: [300]u16 = undefined;
    const len = std.unicode.utf8ToUtf16Le(wide[0 .. wide.len - 1], text) catch return;
    wide[len] = 0;
    _ = win.SendMessageW(search, win.EM_SETCUEBANNER, 1, @bitCast(@intFromPtr(&wide)));
}

fn clearSearch(a: *App) bool {
    const search = a.search orelse return false;
    if (win.GetWindowTextLengthW(search) == 0) return false;
    _ = win.SetWindowTextW(search, lit(""));
    return true;
}

fn refreshVisibleChats(a: *App) void {
    _ = applyChats(a, a.chats_raw orelse "{\"data\":[]}", false);
}

fn refilterChats(a: *App) void {
    const flags: u8 = if (a.show_archived) 2 else if (a.include_archived) 1 else 0;
    if (a.chats_raw) |raw| {
        if (a.chats_raw_flags == flags) {
            _ = applyChats(a, raw, false);
            return;
        }
    }
    refreshVisibleChats(a);
    refreshChats(a);
}

fn loadViewArchiveSetting(a: *App) void {
    const key = messenger_view.archivedSettingKey(a.allocator, a.chat_view, a.view_account.slice()) catch return;
    defer a.allocator.free(key);
    const wide = utf8ToWide(a.allocator, key) catch return;
    defer a.allocator.free(wide);
    const value = loadRegistryString(a.allocator, wide.ptr);
    defer if (value) |text| a.allocator.free(text);
    a.include_archived = messenger_view.archivedSetting(value);
    updateViewArchiveButton(a);
}

fn updateViewArchiveButton(a: *App) void {
    if (a.include_archived_button) |button| {
        _ = win.SetWindowTextW(button, if (a.include_archived) lit("Show archived: On") else lit("Show archived: Off"));
        _ = win.InvalidateRect(button, null, win.FALSE);
    }
}

fn toggleViewArchived(a: *App) void {
    const key = messenger_view.archivedSettingKey(a.allocator, a.chat_view, a.view_account.slice()) catch return;
    defer a.allocator.free(key);
    const wide = utf8ToWide(a.allocator, key) catch return;
    defer a.allocator.free(wide);
    if (!saveRegistryString(a.allocator, wide.ptr, if (a.include_archived) "0" else "1")) return setStatus(a, "Could not save Show archived preference");
    a.include_archived = !a.include_archived;
    _ = clearBulkSelection(a);
    updateViewArchiveButton(a);
    refilterChats(a);
    refreshMessages(a);
}

fn switchChatView(a: *App, view: messenger_view.View) void {
    if (view == .all) return switchAccountView(a, null);
    for (a.views.items) |*account| {
        if (messenger_view.includes(view, account.key.provider)) return switchAccountView(a, account.key.key());
    }
    setStatus(a, "Account is not available");
}

fn switchAccountView(a: *App, wanted: ?chat_key.Key) void {
    a.startup_view_pending = false;
    _ = clearBulkSelection(a);
    if (a.selected_chat < a.chat_count) selectedViewKey(a).set(chat_key.of(&a.chats[a.selected_chat]));
    a.chat_view = if (wanted) |key| messenger_view.providerView(key.provider) else .all;
    a.view_account.set(if (wanted) |key| key.account else "");
    loadViewArchiveSetting(a);
    updateWindowTitle(a);
    saveChatView(a.chat_view);
    _ = saveRegistryString(a.allocator, lit("AccountView"), a.view_account.slice());
    layout(a, a.compose_client_width, a.compose_client_height);
    a.chat_view_switched = true;
    clearReply(a);
    discardStagedImage(a);
    refreshVisibleChats(a);
    if (unifiedHub(a) or messenger_view.includes(a.chat_view, .whatsapp)) refreshChats(a);
    refreshMessages(a);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    var buffer: [300]u8 = undefined;
    setStatus(a, std.fmt.bufPrint(&buffer, "Showing {s}", .{activeViewLabel(a)}) catch "");
}

fn appendSlackChats(a: *App, query_utf8: ?[]const u8) void {
    for (&a.slack_installations) |*installation| {
        if (!installation.active) continue;
        for (installation.chats[0..installation.chat_count]) |*cached| {
            const name = std.unicode.utf16LeToUtf8Alloc(a.allocator, cached.name.slice()) catch continue;
            defer a.allocator.free(name);
            cached.archived = if (a.archive_state) |state| state.localArchived(chat_key.of(cached)) else false;
            if (!messenger_view.archiveMatches(a.show_archived, a.include_archived, activeChatView(a) == .all, a.unread_only, cached.archived, cached.unread)) continue;
            if (!chatInView(a, chat_key.of(cached))) continue;
            if (!messenger_view.matches(activeChatView(a), .slack, a.unread_only, cached.unread, query_utf8 orelse "", name, cached.jid.slice())) continue;
            messenger_view.merge(Chat, a.chats, &a.chat_count, &.{cached.*});
        }
    }
}

fn applySlackWorkspace(a: *App, account: []const u8, raw: []const u8) bool {
    const installation = slackInstallation(a, account) orelse return false;
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return false;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return false,
    };
    const list = switch (root.get("channels") orelse return false) {
        .array => |items| items,
        else => return false,
    };
    for (list.items) |item| {
        const object = switch (item) {
            .object => |object| object,
            else => continue,
        };
        const channel = slack.workspaceChannel(object) orelse continue;
        const id = channel.id;
        const is_im = channel.is_im;
        var name: []const u8 = channel.name;
        if (is_im) name = slackUserName(installation, channel.user) orelse channel.user;
        if (name.len == 0) continue;
        var chat = Chat{ .provider = .slack };
        chat.account.set(account);
        chat.slack_user_id.set(channel.user);
        chat.slack_last_read.set(channel.last_read);
        chat.unread_count = channel.unread_count orelse 0;
        chat.unread = chat.unread_count > 0;
        chat.jid.set(id);
        const hash_prefix = id[0] == 'C' or id[0] == 'G';
        const shown = if (hash_prefix) std.fmt.allocPrint(a.allocator, "#{s}", .{name}) catch a.allocator.dupe(u8, name) catch continue else a.allocator.dupe(u8, name) catch continue;
        defer a.allocator.free(shown);
        const seconds = channel.seconds;
        if (slackChatById(a, account, id)) |existing| {
            existing.archived = if (a.archive_state) |state| state.localArchived(chat_key.of(existing)) else false;
            existing.name.set(a.allocator, shown);
            _ = raiseSlackTimestamp(existing, seconds);
            if (channel.unread_count) |unread| {
                if (existing.slack_last_read.len == 0 or slack.compareTs(channel.last_read, existing.slack_last_read.slice()) != .lt) {
                    existing.unread_count = unread;
                    existing.unread = unread > 0;
                    existing.slack_last_read.set(channel.last_read);
                }
            }
            continue;
        }
        chat.archived = if (a.archive_state) |state| state.localArchived(chat_key.of(&chat)) else false;
        chat.name.set(a.allocator, shown);
        chat.kind.set(a.allocator, if (is_im) "Slack DM" else "Slack channel");
        _ = raiseSlackTimestamp(&chat, seconds);
        if (installation.chat_count >= installation.chats.len) break;
        installation.chats[installation.chat_count] = chat;
        installation.chat_count += 1;
    }
    installation.workspace_pages += 1;
    const cursor = slack.nextCursor(root);
    if (slack.wantsNextPage(cursor, installation.workspace_pages, wacli_arg_cap)) {
        var job = WacliJob{ .provider = .slack, .kind = .slack_workspace };
        job.account.set(account);
        wacliJobArgs(&job, &.{ slack_workspace_types, cursor });
        _ = wacliEnqueue(a, job, false);
        return true;
    }
    const now = win.GetTickCount64();
    if (slack.logDue(a.slack_count_log_ms, a.slack_count_log_hash, now, installation.chat_count)) {
        a.slack_count_log_ms = now;
        a.slack_count_log_hash = installation.chat_count;
        var buffer: [96]u8 = undefined;
        appendLaunchLog(a, std.fmt.bufPrint(&buffer, "slack: workspace loaded, {d} chats in {d} pages", .{ installation.chat_count, installation.workspace_pages }) catch "slack: workspace loaded");
    }
    return true;
}

fn logSlackFailure(a: *App, kind: WacliJobKind, error_name: []const u8, http_status: u32) void {
    const index = @intFromEnum(kind);
    const now = win.GetTickCount64();
    const hash = std.hash.Wyhash.hash(http_status, error_name);
    if (!slack.logDue(a.slack_fail_log_ms[index], a.slack_fail_log_hash[index], now, hash)) return;
    a.slack_fail_log_ms[index] = now;
    a.slack_fail_log_hash[index] = hash;
    const tag = @tagName(kind);
    const name = if (std.mem.startsWith(u8, tag, "slack_")) tag["slack_".len..] else tag;
    var buffer: [128]u8 = undefined;
    appendLaunchLog(a, slack.formatJobFailure(&buffer, name, if (error_name.len > 0) error_name else "Unknown", http_status));
}

fn applySlackUsers(a: *App, account: []const u8, raw: []const u8) bool {
    const installation = slackInstallation(a, account) orelse return false;
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return false;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return false,
    };
    const list = switch (root.get("members") orelse return false) {
        .array => |items| items,
        else => return false,
    };
    for (list.items) |item| {
        const object = switch (item) {
            .object => |object| object,
            else => continue,
        };
        const id = getString(object, "id");
        if (id.len == 0) continue;
        var name = getString(object, "real_name");
        if (name.len == 0) {
            const profile = switch (object.get("profile") orelse continue) {
                .object => |profile_object| profile_object,
                else => continue,
            };
            name = getString(profile, "display_name");
            if (name.len == 0) name = getString(profile, "real_name");
        }
        var known = false;
        for (installation.users[0..installation.user_count]) |*user| {
            if (std.mem.eql(u8, user.id.slice(), id)) {
                if (name.len > 0) user.name.set(name);
                known = true;
            }
        }
        if (known or installation.user_count >= installation.users.len) continue;
        var user = SlackUser{};
        user.id.set(id);
        user.name.set(name);
        installation.users[installation.user_count] = user;
        installation.user_count += 1;
    }
    for (installation.chats[0..installation.chat_count]) |*chat| {
        if (chat.slack_user_id.len > 0) {
            if (slackUserName(installation, chat.slack_user_id.slice())) |name| chat.name.set(a.allocator, name);
        }
    }
    installation.user_pages += 1;
    const cursor = slack.nextCursor(root);
    if (slack.wantsNextPage(cursor, installation.user_pages, wacli_arg_cap)) {
        var job = WacliJob{ .provider = .slack, .kind = .slack_users };
        job.account.set(account);
        wacliJobArgs(&job, &.{cursor});
        _ = wacliEnqueue(a, job, false);
    }
    return true;
}

const slack_workspace_types = "public_channel,private_channel,mpim,im";

fn refreshSlackInstallation(a: *App, installation: *SlackInstallation) void {
    installation.workspace_pages = 0;
    var job = WacliJob{ .provider = .slack, .kind = .slack_workspace };
    job.account = installation.team_id;
    wacliJobArgs(&job, &.{ slack_workspace_types, "" });
    _ = wacliEnqueue(a, job, false);
    installation.user_pages = 0;
    var users_job = WacliJob{ .provider = .slack, .kind = .slack_users };
    users_job.account = installation.team_id;
    wacliJobArgs(&users_job, &.{""});
    _ = wacliEnqueue(a, users_job, false);
}

fn refreshSlackWorkspace(a: *App) void {
    for (&a.slack_installations) |*installation| if (installation.active) refreshSlackInstallation(a, installation);
}

fn refreshSlackHistory(a: *App) void {
    if (!selectedChatIsSlack(a)) return;
    const chat = &a.chats[a.selected_chat];
    if (a.slack_history_hash == 0) a.messages_gen += 1;
    var job = WacliJob{ .provider = .slack, .kind = .slack_history, .gen = a.messages_gen };
    job.provider = chat.provider;
    job.account = chat.account;
    job.jid.set(chat.jid.slice());
    wacliJobArgs(&job, &.{chat.jid.slice()});
    _ = wacliEnqueue(a, job, true);
}

fn pollSlackBridge(a: *App) void {
    a.slack_poll_ticks += 1;
    if (a.slack_poll_ticks % 60 == 0) {
        for (&a.slack_installations) |*installation| {
            a.slack_install_mutex.lockUncancelable(a.io);
            const due = installation.active and !installation.is_bridge and !installation.needs_signin.load(.acquire) and
                (slack_oauth.refreshDue(nowUnixSeconds(), installation.expires_at, installation.refresh_token.len > 0, "") or
                    (installation.expires_at > 0 and nowUnixSeconds() >= installation.expires_at));
            const account = installation.team_id;
            a.slack_install_mutex.unlock(a.io);
            if (!due) continue;
            var job = WacliJob{ .provider = .slack, .kind = .slack_auth };
            job.account = account;
            _ = wacliEnqueue(a, job, false);
        }
    }
    if (a.slack_bridge == null) return;
    if (a.hwnd) |hwnd| if (win.IsIconic(hwnd) != 0) return;
    if (selectedChatIsSlack(a)) {
        const installation = slackInstallation(a, a.chats[a.selected_chat].account.slice());
        if (installation != null and installation.?.is_bridge and a.slack_poll_ticks % 5 == 0 and wacliPendingGet(a, .slack_history) == 0) refreshSlackHistory(a);
    }
    if (a.slack_poll_ticks % 60 == 0 and wacliPendingGet(a, .slack_workspace) == 0) refreshSlackWorkspace(a);
}

fn slackMediaKind(mime: []const u8) []const u8 {
    if (std.mem.startsWith(u8, mime, "image/")) return "image";
    if (std.mem.startsWith(u8, mime, "video/")) return "video";
    if (std.mem.startsWith(u8, mime, "audio/")) return "audio";
    return "file";
}

fn buildSlackMessage(a: *App, account: []const u8, item: slack.HistoryItem) Message {
    var message = Message{};
    const installation = slackInstallation(a, account) orelse return message;
    message.id.set(item.ts);
    message.thread_ts.set(item.thread_ts);
    message.reply_count = @intCast(@max(0, item.reply_count));
    message.latest_reply.set(item.latest_reply);
    message.sender_jid.set(item.user);
    var reaction_buffer: [2048]u8 = undefined;
    message.reaction.set(a.allocator, slack.formatReactions(&reaction_buffer, item.reactions[0..item.reaction_count]));
    const from_me = installation.user_id.len > 0 and std.mem.eql(u8, item.user, installation.user_id.slice());
    message.from_me = from_me;
    const name = if (from_me) "You" else (slackUserName(installation, item.user) orelse (if (item.user.len > 0) item.user else "Slack"));
    message.sender.set(a.allocator, name);
    const lookup = slackUserLookup(installation);
    if (item.share_text.len > 0 or item.share_sender.len > 0) {
        var quote_buffer: [slack.max_text + 1]u8 = undefined;
        var emoji_buffer: [slack.max_text * 4 + 1]u8 = undefined;
        const quote = slack_emoji.replace(&emoji_buffer, item.share_text, .{ .context = a, .resolve = resolveCustomEmoji });
        message.quote.set(a.allocator, slack.convertMrkdwn(&quote_buffer, quote, lookup));
        message.quote_sender.set(a.allocator, item.share_sender);
    }
    var raw_buffer: [900]u8 = undefined;
    const raw_text = slack.historyItemBody(item, &raw_buffer);
    const text = raw_text;
    const is_thread_reply = slack.isThreadReply(item.ts, item.thread_ts) and !slackThreadsEnabled(a);
    if (is_thread_reply and text.len > 0 and text.len + 4 <= slack.max_text) {
        var threaded: [slack.max_text + 4]u8 = undefined;
        const rendered = std.fmt.bufPrint(&threaded, "\u{21a9} {s}", .{text}) catch text;
        setSlackMessageText(a, &message, rendered, lookup);
    } else {
        setSlackMessageText(a, &message, text, lookup);
    }
    formatSlackTime(&message.time, a.allocator, item.ts);
    if (slackThreadsEnabled(a)) rememberSlackThreadRow(a, &message);
    if (item.file_url.len > 0) {
        message.media_type.set(slackMediaKind(item.file_mime));
        message.mime_type.set(item.file_mime);
        message.filename.set(a.allocator, item.file_name);
    }
    return message;
}

fn setSlackMessageText(a: *App, message: *Message, raw: []const u8, lookup: ?slack.UserLookup) void {
    var buffer: [slack.max_text + 1]u8 = undefined;
    var emoji_buffer: [slack.max_text * 4 + 1]u8 = undefined;
    const rendered = slack_emoji.replace(&emoji_buffer, raw, .{ .context = a, .resolve = resolveCustomEmoji });
    message.text.set(a.allocator, slack.convertMrkdwnLinks(&buffer, rendered, lookup, &message.label_links, &message.label_link_count));
}

fn importCustomEmoji(a: *App, jid: []const u8, object: std.json.ObjectMap) void {
    const scope = hub.workspaceAvatarKey(jid) orelse return;
    const paths = object.get("SlackEmojiPaths") orelse return;
    if (paths != .object) return;
    var entries = paths.object.iterator();
    while (entries.next()) |entry| {
        if (entry.value_ptr.* != .string) continue;
        var slot: ?usize = null;
        for (a.custom_emoji.items, 0..) |*existing, index| {
            if (std.mem.eql(u8, existing.scope.slice(), scope) and std.mem.eql(u8, existing.name.slice(), entry.key_ptr.*)) {
                slot = index;
                break;
            }
        }
        if (slot == null) {
            if (a.custom_emoji.items.len >= 6400) continue;
            slot = a.custom_emoji.items.len;
            a.custom_emoji.append(a.allocator, .{}) catch return;
        }
        const emoji = &a.custom_emoji.items[slot.?];
        emoji.scope.set(scope);
        emoji.name.set(entry.key_ptr.*);
        const value = entry.value_ptr.string;
        var path = WideText(519){};
        if (std.unicode.utf8ValidateSlice(value) and value.len > 0 and value[0] >= 128) {
            emoji.token.set(value);
        } else {
            path.set(a.allocator, value);
            var token: [4]u8 = undefined;
            const length = std.unicode.utf8Encode(@intCast(0xE000 + slot.?), &token) catch continue;
            emoji.token.set(token[0..length]);
        }
        if (!std.mem.eql(u16, path.slice(), emoji.path.slice())) {
            if (emoji.bitmap) |bitmap| _ = win.DeleteObject(bitmap);
            emoji.bitmap = null;
            emoji.path = path;
        }
    }
}

fn resolveCustomEmoji(context: *anyopaque, name: []const u8) ?[]const u8 {
    const a: *App = @ptrCast(@alignCast(context));
    if (a.selected_chat >= a.chat_count) return null;
    const scope = hub.workspaceAvatarKey(a.chats[a.selected_chat].jid.slice()) orelse return null;
    for (a.custom_emoji.items) |*entry| {
        if (std.mem.eql(u8, entry.scope.slice(), scope) and std.mem.eql(u8, entry.name.slice(), name)) return entry.token.slice();
    }
    return null;
}

fn formatSlackTime(target: *WideText(15), allocator: std.mem.Allocator, ts: []const u8) void {
    const dot = std.mem.indexOfScalar(u8, ts, '.') orelse ts.len;
    const seconds = std.fmt.parseInt(i64, ts[0..dot], 10) catch {
        target.set(allocator, "");
        return;
    };
    if (seconds < 0 or seconds > 100_000_000_000) {
        target.set(allocator, "");
        return;
    }
    const ticks: i64 = (seconds + 11644473600) * 10_000_000;
    var ft = win.FILETIME{ .dwLowDateTime = @truncate(@as(u64, @bitCast(ticks))), .dwHighDateTime = @truncate(@as(u64, @bitCast(ticks)) >> 32) };
    var utc = std.mem.zeroes(win.SYSTEMTIME);
    if (win.FileTimeToSystemTime(&ft, &utc) == 0) {
        target.set(allocator, "");
        return;
    }
    var local = std.mem.zeroes(win.SYSTEMTIME);
    if (win.SystemTimeToTzSpecificLocalTime(null, &utc, &local) == 0) {
        target.set(allocator, "");
        return;
    }
    var buffer: [8]u8 = undefined;
    const rendered = std.fmt.bufPrint(&buffer, "{d:0>2}:{d:0>2}", .{ local.wHour, local.wMinute }) catch return;
    target.set(allocator, rendered);
}

fn applySlackHistory(a: *App, raw: []const u8) void {
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return;
    defer parsed.deinit();
    if (a.selected_chat >= a.chat_count) return;
    const chat = &a.chats[a.selected_chat];
    if (chat.provider != .slack) return;
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return,
    };
    const list = switch (root.get("messages") orelse return) {
        .array => |items| items,
        else => return,
    };
    var selected_id = Utf8Text(191){};
    if (a.selected_message) |selected| {
        if (selected < a.message_count) selected_id.set(a.messages[selected].id.slice());
    }
    var saved: []Message = &.{};
    var saved_count: usize = 0;
    if (chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat))) {
        for (a.messages[0..a.message_count]) |*message| {
            if (message.from_me and message.send_state != .none) saved_count += 1;
        }
        if (saved_count > 0) {
            saved = a.allocator.alloc(Message, saved_count) catch return;
            var filled: usize = 0;
            for (a.messages[0..a.message_count]) |*message| {
                if (message.from_me and message.send_state != .none) {
                    saved[filled] = message.*;
                    filled += 1;
                }
            }
            saved_count = filled;
        }
    }
    defer if (saved.len > 0) a.allocator.free(saved);
    clearMessages(a);
    a.selected_message = null;
    var reply_parents: [8]Utf8Text(64) = [_]Utf8Text(64){.{}} ** 8;
    var reply_parent_count: usize = 0;
    var item_index: usize = list.items.len;
    var count: usize = 0;
    var newest_seconds: i64 = 0;
    while (item_index > 0 and count < max_messages) {
        item_index -= 1;
        const item = slack.readHistoryItem(list.items[item_index]) orelse continue;
        newest_seconds = @max(newest_seconds, slack.tsSeconds(item.ts) orelse 0);
        const message = buildSlackMessage(a, chat.account.slice(), item);
        a.messages[a.message_count] = message;
        a.message_count += 1;
        count += 1;
        if (item.reply_count > 0 and reply_parent_count < reply_parents.len) {
            reply_parents[reply_parent_count].set(item.ts);
            reply_parent_count += 1;
        }
        if (item.file_url.len > 0) {
            requestSlackDownload(a, chat.account.slice(), chat.jid.slice(), item);
        }
    }
    for (saved[0..saved_count]) |message| {
        if (a.message_count >= max_messages) break;
        a.messages[a.message_count] = message;
        a.message_count += 1;
    }
    if (selected_id.len > 0) {
        for (a.messages[0..a.message_count], 0..) |*message, index| {
            if (std.mem.eql(u8, selected_id.slice(), message.id.slice())) {
                a.selected_message = index;
                break;
            }
        }
    }
    noteSlackActivity(a, chat.account.slice(), chat.jid.slice(), newest_seconds);
    a.displayed_jid.set(chat.jid.slice());
    a.displayed_account = chat.account;
    a.displayed_provider = chat.provider;
    a.displayed_timestamp.set(chat.timestamp.slice());
    for (reply_parents[0..reply_parent_count]) |parent| {
        var job = WacliJob{ .provider = .slack, .kind = .slack_replies, .gen = a.messages_gen };
        job.provider = chat.provider;
        job.account = chat.account;
        job.jid.set(chat.jid.slice());
        job.msg_id.set(parent.slice());
        wacliJobArgs(&job, &.{ chat.jid.slice(), parent.slice() });
        _ = wacliEnqueue(a, job, false);
    }
    for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
        if (a.message_count >= max_messages) break;
        if (slot.completed) continue;
        const entry = &slot.entry;
        if (!chat_key.Key.eql(chat_key.of(entry), chat_key.of(chat))) continue;
        if (entry.file.len > 0) {
            if (entry.state == .failed) setStatus(a, "Slack image send failed");
            continue;
        }
        if (entry.client_msg_id.len == 0) continue;
        var visible = false;
        for (a.messages[0..a.message_count]) |*message| {
            if (message.from_me and message.send_state != .none and std.mem.eql(u8, message.timestamp.slice(), entry.client_msg_id.slice())) {
                visible = true;
                break;
            }
        }
        if (visible) continue;
        appendSlackPending(a, entry.text.slice(), entry.client_msg_id.slice(), entry.reply_to.slice());
        if (entry.state == .failed) {
            var result = WacliResult{ .provider = .slack, .kind = .slack_send };
            result.account.set(entry.account.slice());
            result.jid.set(entry.jid.slice());
            result.msg_id.set(entry.idSlice());
            resolveSlackSend(a, &result);
        }
    }
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (a.chats_hwnd) |chats_list| _ = win.InvalidateRect(chats_list, null, win.FALSE);
    markChatRead(a);
    refreshVisibleChats(a);
}

fn applySlackReplies(a: *App, raw: []const u8, parent: []const u8) void {
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return;
    defer parsed.deinit();
    if (a.selected_chat >= a.chat_count) return;
    const chat = &a.chats[a.selected_chat];
    if (chat.provider != .slack) return;
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return,
    };
    const list = switch (root.get("messages") orelse return) {
        .array => |items| items,
        else => return,
    };
    for (list.items) |item_value| {
        const item = slack.readHistoryItem(item_value) orelse continue;
        const message = buildSlackMessage(a, chat.account.slice(), item);
        var known = false;
        for (a.messages[0..a.message_count]) |*existing| {
            if (std.mem.eql(u8, existing.id.slice(), item.ts)) known = true;
        }
        if (known) continue;
        insertSlackMessageSorted(a, message);
        if (item.file_url.len > 0) requestSlackDownload(a, chat.account.slice(), chat.jid.slice(), item);
    }
    const cursor = slack.nextCursor(root);
    if (slackThreadsEnabled(a) and cursor.len > 0) requestSlackThread(a, parent, cursor);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (a.user_viewed) requestSlackMark(a, chat.jid.slice());
}

fn insertSlackMessageSorted(a: *App, message: Message) void {
    if (a.message_count >= max_messages) return;
    var index: usize = a.message_count;
    while (index > 0 and slack.compareTs(a.messages[index - 1].id.slice(), message.id.slice()) == .gt) : (index -= 1) {
        a.messages[index] = a.messages[index - 1];
    }
    a.messages[index] = message;
    a.message_count += 1;
}

fn appendSlackPending(a: *App, text: []const u8, client_msg_id: []const u8, thread_ts: []const u8) void {
    if (a.message_count >= max_messages) return;
    var message = Message{};
    message.from_me = true;
    message.thread_ts.set(thread_ts);
    message.sender.set(a.allocator, "You");
    message.text.set(a.allocator, text);
    message.timestamp.set(client_msg_id);
    var local = std.mem.zeroes(win.SYSTEMTIME);
    win.GetLocalTime(&local);
    var buffer: [6]u8 = undefined;
    if (std.fmt.bufPrint(&buffer, "{d:0>2}:{d:0>2}", .{ local.wHour, local.wMinute })) |rendered| {
        message.time.set(a.allocator, rendered);
    } else |_| {}
    message.send_state = .pending;
    a.messages[a.message_count] = message;
    a.message_count += 1;
    a.scroll_y = 0;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn oldestPendingSend(a: *App) ?usize {
    for (a.messages[0..a.message_count], 0..) |*message, index| {
        if (message.from_me and message.send_state == .pending) return index;
    }
    return null;
}

fn localSendId(buffer: []u8, seq: u64) []const u8 {
    return std.fmt.bufPrint(buffer, "local-{d}", .{seq}) catch "local";
}

const file_send_placeholder = "Sending file...";

fn sendBaseText(buffer: []u8, text: []const u8, has_file: bool, ptt: bool, voice_seconds: u32) []const u8 {
    if (ptt) return std.fmt.bufPrint(buffer, "Voice message {d}:{d:0>2}", .{ voice_seconds / 60, voice_seconds % 60 }) catch "Voice message";
    if (has_file and text.len == 0) return "Image";
    return text;
}

fn retryingBubbleText(buffer: []u8, text: []const u8, retries: u8) []const u8 {
    if (retries == 0 or text.len == 0) return text;
    return std.fmt.bufPrint(buffer, "{s} (retrying {d}/{d})", .{ text, retries, max_send_retries - 1 }) catch text;
}

fn appendWhatsAppPending(a: *App, pending: *const PendingSend, from_reload: bool) void {
    if (pending.completed or a.message_count >= max_messages or a.chat_count == 0 or a.selected_chat >= a.chat_count) return;
    if (!chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(pending))) return;
    if (from_reload and !pending.from_disk) {
        for (a.messages[0..a.message_count]) |*message| {
            if (!message.from_me or message.send_state != .none) continue;
            if (pending.ptt) {
                const row_unix = media_age.unixSeconds(message.timestamp.slice()) orelse continue;
                if (voice_sent.rowMatchesEntry(true, message.media_type.slice(), row_unix, pending.queued_unix, true)) return;
                continue;
            }
            const text = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch continue;
            defer a.allocator.free(text);
            if (!std.mem.eql(u8, text, pending.text.slice())) continue;
            const stored_unix = media_age.unixSeconds(message.timestamp.slice()) orelse continue;
            if (stored_unix >= pending.queued_unix - 5) return;
        }
    }
    var message = Message{};
    message.from_me = true;
    if (pending.provider == .slack) message.thread_ts.set(pending.reply_to.slice());
    message.sender.set(a.allocator, "You");
    if (pending.ptt) {
        message.media_type.set("audio");
        message.local_path.set(a.allocator, pending.file.slice());
    } else if (pending.file.len > 0 and pending.text.len == 0) {
        message.text.set(a.allocator, file_send_placeholder);
    } else {
        var retry_buffer: [4095]u8 = undefined;
        message.text.set(a.allocator, retryingBubbleText(&retry_buffer, pending.text.slice(), pending.retries));
    }
    var id_buffer: [32]u8 = undefined;
    message.id.set(localSendId(&id_buffer, pending.seq));
    var local = std.mem.zeroes(win.SYSTEMTIME);
    win.GetLocalTime(&local);
    var time_buffer: [6]u8 = undefined;
    if (std.fmt.bufPrint(&time_buffer, "{d:0>2}:{d:0>2}", .{ local.wHour, local.wMinute })) |rendered| {
        message.time.set(a.allocator, rendered);
    } else |_| {}
    message.send_state = .pending;
    a.messages[a.message_count] = message;
    a.message_count += 1;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn markPendingSendFailed(a: *App, pending: *const PendingSend) void {
    var id_buffer: [32]u8 = undefined;
    const id = localSendId(&id_buffer, pending.seq);
    for (a.messages[0..a.message_count]) |*message| {
        if (!message.from_me or message.send_state != .pending or
            !std.mem.eql(u8, message.id.slice(), id)) continue;
        message.send_state = .failed;
        var base_buffer: [48]u8 = undefined;
        const old = sendBaseText(&base_buffer, pending.text.slice(), pending.file.len > 0, pending.ptt, pending.voice_seconds);
        if (pending.failure_reason.len > 0) {
            var buffer: [4095]u8 = undefined;
            var length = @min(old.len, 3900);
            while (!std.unicode.utf8ValidateSlice(old[0..length])) length -= 1;
            const marked = std.fmt.bufPrint(&buffer, "{s} (not sent: {s})", .{ old[0..length], pending.failure_reason.slice() }) catch return;
            message.text.set(a.allocator, marked);
        } else if (old.len + " (not sent)".len < 4095) {
            const marked = std.fmt.allocPrint(a.allocator, "{s} (not sent)", .{old}) catch return;
            defer a.allocator.free(marked);
            message.text.set(a.allocator, marked);
        } else {
            message.text.set(a.allocator, old);
        }
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        return;
    }
}

fn markPendingSendRetrying(a: *App, pending: *const PendingSend) void {
    if (pending.text.len == 0) return;
    var id_buffer: [32]u8 = undefined;
    const id = localSendId(&id_buffer, pending.seq);
    for (a.messages[0..a.message_count]) |*message| {
        if (!message.from_me or message.send_state != .pending or
            !std.mem.eql(u8, message.id.slice(), id)) continue;
        var retry_buffer: [4095]u8 = undefined;
        message.text.set(a.allocator, retryingBubbleText(&retry_buffer, pending.text.slice(), pending.retries));
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        return;
    }
}

fn appendWhatsAppFailed(a: *App, failed: *const FailedSend) void {
    if (a.message_count >= max_messages or a.chat_count == 0 or a.selected_chat >= a.chat_count) return;
    if (!chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(failed))) return;
    var message = Message{};
    message.from_me = true;
    if (failed.provider == .slack) message.thread_ts = failed.reply_to;
    message.sender.set(a.allocator, "You");
    var base_buffer: [48]u8 = undefined;
    const base = sendBaseText(&base_buffer, failed.text.slice(), failed.is_file, failed.ptt, failed.voice_seconds);
    if (failed.failure_reason.len > 0) {
        var buffer: [4095]u8 = undefined;
        var length = @min(base.len, 3900);
        while (!std.unicode.utf8ValidateSlice(base[0..length])) length -= 1;
        const marked = std.fmt.bufPrint(&buffer, "{s} (not sent: {s})", .{ base[0..length], failed.failure_reason.slice() }) catch return;
        message.text.set(a.allocator, marked);
    } else if (base.len == 0) {
        message.text.set(a.allocator, "(not sent)");
    } else if (base.len + " (not sent)".len < 4095) {
        const marked = std.fmt.allocPrint(a.allocator, "{s} (not sent)", .{base}) catch return;
        defer a.allocator.free(marked);
        message.text.set(a.allocator, marked);
    } else {
        message.text.set(a.allocator, base);
    }
    var local = std.mem.zeroes(win.SYSTEMTIME);
    win.GetLocalTime(&local);
    var time_buffer: [6]u8 = undefined;
    if (std.fmt.bufPrint(&time_buffer, "{d:0>2}:{d:0>2}", .{ local.wHour, local.wMinute })) |rendered| {
        message.time.set(a.allocator, rendered);
    } else |_| {}
    message.send_state = .failed;
    a.messages[a.message_count] = message;
    a.message_count += 1;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn rememberFailedSend(a: *App, pending: *const PendingSend) void {
    for (a.failed_sends[0..a.failed_send_count]) |*entry| {
        if (chat_key.Key.eql(chat_key.of(entry), chat_key.of(pending)) and
            std.mem.eql(u8, entry.text.slice(), pending.text.slice()) and
            std.mem.eql(u8, entry.file.slice(), pending.file.slice())) return;
    }
    if (a.failed_send_count == a.failed_sends.len) {
        var index: usize = 1;
        while (index < a.failed_send_count) : (index += 1) a.failed_sends[index - 1] = a.failed_sends[index];
        a.failed_send_count -= 1;
    }
    a.failed_sends[a.failed_send_count].provider = pending.provider;
    a.failed_sends[a.failed_send_count].account = pending.account;
    a.failed_sends[a.failed_send_count].jid.set(pending.jid.slice());
    a.failed_sends[a.failed_send_count].text.set(pending.text.slice());
    a.failed_sends[a.failed_send_count].reply_to = pending.reply_to;
    a.failed_sends[a.failed_send_count].queued_unix = pending.queued_unix;
    a.failed_sends[a.failed_send_count].is_file = pending.file.len > 0;
    a.failed_sends[a.failed_send_count].file.set(pending.file.slice());
    a.failed_sends[a.failed_send_count].ptt = pending.ptt;
    a.failed_sends[a.failed_send_count].voice_seconds = pending.voice_seconds;
    a.failed_sends[a.failed_send_count].failure_reason = pending.failure_reason;
    a.failed_send_count += 1;
}

fn forgetFailedSend(a: *App, key: chat_key.Key, text: []const u8) void {
    for (a.failed_sends[0..a.failed_send_count], 0..) |*entry, index| {
        if (entry.is_file or !chat_key.Key.eql(chat_key.of(entry), key) or !std.mem.eql(u8, entry.text.slice(), text)) continue;
        var shift = index;
        while (shift + 1 < a.failed_send_count) : (shift += 1) a.failed_sends[shift] = a.failed_sends[shift + 1];
        a.failed_send_count -= 1;
        a.failed_sends[a.failed_send_count] = .{};
        return;
    }
}

fn pruneFailedSends(a: *App, key: chat_key.Key) void {
    var index: usize = 0;
    while (index < a.failed_send_count) {
        const entry = &a.failed_sends[index];
        var delivered = false;
        if (chat_key.Key.eql(chat_key.of(entry), key)) {
            for (a.messages[0..a.message_count]) |*message| {
                if (!message.from_me or message.send_state != .none) continue;
                const text = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch continue;
                defer a.allocator.free(text);
                if (!std.mem.eql(u8, text, entry.text.slice())) continue;
                const stored_unix = media_age.unixSeconds(message.timestamp.slice()) orelse continue;
                if (stored_unix >= entry.queued_unix - 5) {
                    delivered = true;
                    break;
                }
            }
        }
        if (!delivered) {
            index += 1;
            continue;
        }
        if (entry.is_file and entry.file.len > 0) deleteFileUtf8(entry.file.slice());
        var shift = index;
        while (shift + 1 < a.failed_send_count) : (shift += 1) a.failed_sends[shift] = a.failed_sends[shift + 1];
        a.failed_send_count -= 1;
        a.failed_sends[a.failed_send_count] = .{};
        persistFileOutbox(a);
    }
}

fn restoreFailedSendText(a: *App, failed: *const PendingSend) void {
    if (failed.file.len > 0 or failed.text.len == 0) return;
    const key = chat_key.of(failed);
    if (a.draft_store.get(key).len > 0) return;
    a.draft_store.save(a.allocator, key, failed.text.slice()) catch return;
    if (a.draft_store.isOpen(key)) {
        setComposerDraft(a, a.draft_store.get(key));
        layout(a, a.compose_client_width, a.compose_client_height);
        focusCompose(a);
    }
    persistDrafts(a);
    if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
}

fn resendFailedMessage(a: *App, index: usize) bool {
    if (index >= a.message_count) return false;
    const message = &a.messages[index];
    if (!message.from_me or message.send_state != .failed) return false;
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) return false;
    if (selectedChatIsSlack(a)) {
        for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
            const entry = &slot.entry;
            if (slot.completed or entry.state != .failed or entry.file.len > 0 or
                !chat_key.Key.eql(chat_key.of(entry), chat_key.of(&a.chats[a.selected_chat])) or
                !std.mem.eql(u8, entry.client_msg_id.slice(), message.timestamp.slice())) continue;
            entry.state = .queued;
            entry.attempts = 0;
            slot.not_before_ms = 0;
            a.slack_outbox_dirty = true;
            if (!persistOutbox(a)) {
                entry.state = .failed;
                setStatus(a, "Could not save outbox; message not queued");
                return true;
            }
            message.send_state = .pending;
            message.text.set(a.allocator, entry.text.slice());
            enqueueSlackOutbox(a, slot);
            setStatus(a, "Resending...");
            if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
            return true;
        }
        setStatus(a, "Can't resend this message - type it again");
        return true;
    }
    if (selectedChatIsTelegram(a)) return false;
    if (a.pending_send_count >= max_pending_sends) {
        setStatus(a, "Send queue is full");
        return true;
    }
    const bubble_text = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch return true;
    defer a.allocator.free(bubble_text);
    const suffix = " (not sent)";
    const reason_start = std.mem.lastIndexOf(u8, bubble_text, " (not sent: ");
    const original = if (reason_start) |start| bubble_text[0..start] else if (std.mem.endsWith(u8, bubble_text, suffix)) bubble_text[0 .. bubble_text.len - suffix.len] else bubble_text;
    const jid = a.chats[a.selected_chat].jid.slice();
    var entry: ?*const FailedSend = null;
    for (a.failed_sends[0..a.failed_send_count]) |*candidate| {
        var base_buffer: [48]u8 = undefined;
        const base = sendBaseText(&base_buffer, candidate.text.slice(), candidate.is_file, candidate.ptt, candidate.voice_seconds);
        if (chat_key.Key.eql(chat_key.of(candidate), chat_key.of(&a.chats[a.selected_chat])) and (std.mem.eql(u8, base, original) or (candidate.failure_reason.len > 0 and original.len >= 3897 and std.mem.startsWith(u8, base, original)))) {
            entry = candidate;
            break;
        }
    }
    const failed = entry orelse {
        setStatus(a, "Can't resend this message - type it again");
        return true;
    };
    if (failed.is_file) {
        if (!fileExistsUtf8(failed.file.slice())) {
            forgetFailedSendEntry(a, failed);
            setStatus(a, "The file is gone - attach it again");
            return true;
        }
        const file_pending = &a.pending_sends[a.pending_send_count];
        file_pending.* = .{};
        file_pending.provider = failed.provider;
        file_pending.account = failed.account;
        file_pending.jid.set(jid);
        file_pending.text.set(failed.text.slice());
        if (failed.provider == .slack) file_pending.reply_to = failed.reply_to;
        file_pending.file.set(failed.file.slice());
        file_pending.ptt = failed.ptt;
        file_pending.voice_seconds = failed.voice_seconds;
        a.send_seq += 1;
        file_pending.seq = a.send_seq;
        file_pending.queued_unix = nowUnixSeconds();
        mintSendId(a, &file_pending.id);
        a.pending_send_count += 1;
        if (!persistOutbox(a)) {
            a.pending_send_count -= 1;
            file_pending.* = .{};
            setStatus(a, "Could not save outbox; message not queued");
            return true;
        }
        message.send_state = .pending;
        var label_buffer: [48]u8 = undefined;
        message.text.set(a.allocator, sendBaseText(&label_buffer, file_pending.text.slice(), true, file_pending.ptt, file_pending.voice_seconds));
        var file_id_buffer: [32]u8 = undefined;
        message.id.set(localSendId(&file_id_buffer, file_pending.seq));
        forgetFailedSendEntry(a, failed);
        persistFileOutbox(a);
        setStatus(a, "Resending...");
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        startNextSend(a);
        return true;
    }
    if (original.len == 0) {
        setStatus(a, "Nothing to resend");
        return true;
    }
    if (sentMessageExists(a, chat_key.of(failed), original, failed.queued_unix)) {
        forgetFailedSend(a, chat_key.of(failed), original);
        setStatus(a, "Already sent");
        refreshMessages(a);
        return true;
    }
    const pending = &a.pending_sends[a.pending_send_count];
    pending.* = .{};
    pending.provider = failed.provider;
    pending.account = failed.account;
    pending.jid.set(jid);
    pending.text.set(original);
    if (failed.provider == .slack) pending.reply_to = failed.reply_to;
    a.send_seq += 1;
    pending.seq = a.send_seq;
    pending.queued_unix = nowUnixSeconds();
    mintSendId(a, &pending.id);
    a.pending_send_count += 1;
    if (!persistOutbox(a)) {
        a.pending_send_count -= 1;
        pending.* = .{};
        setStatus(a, "Could not save outbox; message not queued");
        return true;
    }
    forgetFailedSend(a, chat_key.of(failed), original);
    message.send_state = .pending;
    message.text.set(a.allocator, original);
    var id_buffer: [32]u8 = undefined;
    message.id.set(localSendId(&id_buffer, pending.seq));
    if (a.compose) |compose| {
        var wide_buffer: [4096]u16 = undefined;
        const length: usize = @intCast(win.GetWindowTextW(compose, &wide_buffer, wide_buffer.len));
        if (length > 0) {
            if (std.unicode.utf16LeToUtf8Alloc(a.allocator, wide_buffer[0..length])) |compose_text| {
                defer a.allocator.free(compose_text);
                if (std.mem.eql(u8, compose_text, original)) {
                    _ = win.SetWindowTextW(compose, lit(""));
                    saveComposerDraft(a);
                }
            } else |_| {}
        }
    }
    setStatus(a, "Resending...");
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    startNextSend(a);
    return true;
}

fn pendingByClientMsgId(a: *App, client_msg_id: []const u8) ?usize {
    if (client_msg_id.len == 0) return null;
    for (a.messages[0..a.message_count], 0..) |*message, index| {
        if (message.from_me and message.send_state == .pending and
            std.mem.eql(u8, message.timestamp.slice(), client_msg_id)) return index;
    }
    return null;
}

fn removeMessageAt(a: *App, index: usize) void {
    a.text_selection = .{};
    a.text_dragging = false;
    if (a.canvas) |canvas| {
        _ = win.KillTimer(canvas, timer_passage_scroll);
        if (win.GetCapture() == canvas) _ = win.ReleaseCapture();
    }
    if (a.selected_message) |selected| {
        if (selected == index) {
            a.selected_message = null;
        } else if (selected > index) {
            a.selected_message = selected - 1;
        }
    }
    var shift = index;
    while (shift + 1 < a.message_count) : (shift += 1) a.messages[shift] = a.messages[shift + 1];
    a.message_count -= 1;
}

fn dropPendingForEcho(a: *App, event: *slack_win.Event) void {
    const cmid = event.clientMsgIdSlice();
    var index: ?usize = null;
    if (cmid.len > 0) {
        for (a.messages[0..a.message_count], 0..) |*message, i| {
            if (message.from_me and message.send_state != .none and
                std.mem.eql(u8, message.timestamp.slice(), cmid))
            {
                index = i;
                break;
            }
        }
    } else {
        for (a.messages[0..a.message_count], 0..) |*message, i| {
            if (!message.from_me or message.send_state == .none) continue;
            const bubble_text = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch continue;
            defer a.allocator.free(bubble_text);
            if (std.mem.eql(u8, bubble_text, event.textSlice()) or
                (message.send_state == .failed and bubble_text.len == event.textSlice().len + " (not sent)".len and
                    std.mem.startsWith(u8, bubble_text, event.textSlice()) and
                    std.mem.endsWith(u8, bubble_text, " (not sent)")))
            {
                index = i;
                break;
            }
        }
    }
    if (index) |found| removeMessageAt(a, found);
}

fn resolveSlackSend(a: *App, result: *WacliResult) void {
    if (!chat_key.Key.eql(chat_key.displayed(a), chat_key.of(result))) return;
    var client_msg_id: []const u8 = "";
    for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
        if (std.mem.eql(u8, slot.entry.idSlice(), result.msg_id.slice())) {
            client_msg_id = slot.entry.client_msg_id.slice();
            break;
        }
    }
    const index = pendingByClientMsgId(a, client_msg_id) orelse return;
    if (!result.ok) {
        const message = &a.messages[index];
        message.send_state = .failed;
        if (message.text.len + " (not sent)".len < slack.max_text) {
            const old = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch return;
            defer a.allocator.free(old);
            const marked = std.fmt.allocPrint(a.allocator, "{s} (not sent)", .{old}) catch return;
            defer a.allocator.free(marked);
            message.text.set(a.allocator, marked);
        }
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        return;
    }
    const ts = slack.parseSentTs(a.allocator, result.data) orelse {
        a.messages[index].send_state = .none;
        return;
    };
    defer a.allocator.free(ts);
    for (a.messages[0..a.message_count]) |*message| {
        if (std.mem.eql(u8, message.id.slice(), ts)) {
            removeMessageAt(a, index);
            return;
        }
    }
    const message = &a.messages[index];
    message.id.set(ts);
    formatSlackTime(&message.time, a.allocator, ts);
    message.send_state = .none;
    a.slack_log_mutex.lockUncancelable(a.io);
    _ = a.slack_log.markAccount(result.account.slice(), result.jid.slice(), ts);
    a.slack_log_mutex.unlock(a.io);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn mintSendId(a: *App, id: *[outbox.id_len]u8) void {
    var raw: [16]u8 = undefined;
    a.io.random(&raw);
    id.* = outbox.hexId(raw);
}

fn persistOutbox(a: *App) bool {
    if (a.outbox_path.len == 0 or a.outbox_load_failed) return false;
    var allocating = std.Io.Writer.Allocating.init(a.allocator);
    defer allocating.deinit();
    for (a.pending_sends[0..a.pending_send_count]) |*pending| {
        if (pending.completed) continue;
        var entry = outbox.Entry{ .queued_unix = pending.queued_unix };
        entry.id = pending.id;
        entry.provider = std.meta.stringToEnum(outbox.Provider, @tagName(pending.provider)) orelse return false;
        entry.account.set(pending.account.slice());
        entry.jid.set(pending.jid.slice());
        entry.text.set(pending.text.slice());
        entry.file.set(pending.file.slice());
        entry.ptt = pending.ptt;
        entry.voice_seconds = pending.voice_seconds;
        entry.reply_to.set(pending.reply_to.slice());
        entry.reply_sender.set(pending.reply_sender.slice());
        outbox.writeLine(&allocating.writer, &entry) catch return false;
    }
    for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
        if (slot.completed) continue;
        outbox.writeLine(&allocating.writer, &slot.entry) catch return false;
    }
    const temp_path = std.fmt.allocPrint(a.allocator, "{s}.new", .{a.outbox_path}) catch return false;
    defer a.allocator.free(temp_path);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, temp_path) catch return false;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_WRITE, 0, null, win.CREATE_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return false;
    defer _ = win.DeleteFileW(wide.ptr);
    const data = allocating.written();
    var written_total: usize = 0;
    var ok = true;
    while (ok and written_total < data.len) {
        var written: win.DWORD = 0;
        if (win.WriteFile(handle, data[written_total..].ptr, @intCast(data.len - written_total), &written, null) == 0 or written == 0) ok = false;
        written_total += written;
    }
    const flushed = ok and written_total == data.len and win.FlushFileBuffers(handle) != 0;
    const closed = win.CloseHandle(handle) != 0;
    if (!flushed or !closed) return false;
    const target = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, a.outbox_path) catch return false;
    defer a.allocator.free(target);
    if (win.MoveFileExW(wide.ptr, target.ptr, win.MOVEFILE_REPLACE_EXISTING | win.MOVEFILE_WRITE_THROUGH) == 0) return false;
    a.slack_outbox_dirty = false;
    return true;
}

fn restoreOutbox(a: *App) void {
    a.outbox_load_failed = true;
    if (a.outbox_path.len == 0) return;
    const folder = std.fs.path.dirname(a.outbox_path) orelse return;
    const dir = std.Io.Dir.cwd().openDir(a.io, folder, .{ .iterate = true }) catch return;
    defer dir.close(a.io);
    var slack_accounts: std.ArrayList([]const u8) = .empty;
    defer slack_accounts.deinit(a.allocator);
    const installations = if (!unifiedHub(a)) slack_win.loadSecret(a.allocator, lit("SlackInstallations")) else null;
    defer if (installations) |stored| a.allocator.free(stored.value);
    if (installations) |stored| {
        var ids = std.mem.tokenizeScalar(u8, stored.value, '\n');
        while (ids.next()) |id| slack_accounts.append(a.allocator, id) catch return;
    }
    outbox.adopt(a.allocator, a.io, dir, std.fs.path.basename(a.outbox_path), .{
        .account = a.cache_tag.slice(),
        .unified = unifiedHub(a),
        .slack_accounts = slack_accounts.items,
    }) catch {
        appendLaunchLog(a, "startup: outbox adoption failed");
    };
    loadOutbox(a);
}

fn loadOutbox(a: *App) void {
    a.outbox_load_failed = true;
    if (a.outbox_path.len == 0) return;
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, a.outbox_path) catch return;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_READ, win.FILE_SHARE_READ, null, win.OPEN_EXISTING, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) {
        if (win.GetLastError() == win.ERROR_FILE_NOT_FOUND) a.outbox_load_failed = false;
        return;
    }
    defer {
        _ = win.CloseHandle(handle);
        bindOutboxAccount(a);
    }
    var size: win.LARGE_INTEGER = undefined;
    if (win.GetFileSizeEx(handle, &size) == 0 or size.QuadPart < 0 or
        size.QuadPart > outbox.max_entries * outbox.max_line_len) return;
    const buffer = a.allocator.alloc(u8, @intCast(size.QuadPart)) catch return;
    defer a.allocator.free(buffer);
    var total: usize = 0;
    while (total < buffer.len) {
        var got: win.DWORD = 0;
        if (win.ReadFile(handle, buffer[total..].ptr, @intCast(buffer.len - total), &got, null) == 0) return;
        if (got == 0) return;
        total += got;
    }
    var scanner = outbox.Scanner.init(a.allocator, buffer[0..total]);
    while (scanner.next()) |entry| {
        if (entry.provider == .whatsapp or unifiedHub(a)) {
            if (a.pending_send_count >= a.pending_sends.len) return;
            const pending = &a.pending_sends[a.pending_send_count];
            pending.* = .{};
            pending.id = entry.id;
            pending.provider = std.meta.stringToEnum(transport.Provider, @tagName(entry.provider)).?;
            pending.account.set(entry.account.slice());
            pending.jid.set(entry.jid.slice());
            pending.text.set(entry.text.slice());
            pending.file.set(entry.file.slice());
            pending.ptt = entry.ptt;
            pending.voice_seconds = entry.voice_seconds;
            pending.reply_to.set(entry.reply_to.slice());
            pending.reply_sender.set(entry.reply_sender.slice());
            pending.queued_unix = entry.queued_unix;
            pending.from_disk = true;
            a.send_seq += 1;
            pending.seq = a.send_seq;
            a.pending_send_count += 1;
        } else {
            if (a.slack_outbox_count >= a.slack_outbox.len) return;
            const slot = &a.slack_outbox[a.slack_outbox_count];
            slot.* = .{};
            slot.entry = entry.*;
            a.slack_outbox_count += 1;
        }
    }
    a.outbox_load_failed = false;
}

fn bindOutboxAccount(a: *App) void {
    if (a.outbox_load_failed or a.cache_tag.len == 0 or unifiedHub(a)) return;
    for (a.pending_sends[0..a.pending_send_count]) |*pending| {
        if (pending.provider == .whatsapp and (pending.account.len == 0 or
            (hubConfigured(a) and a.hub_account.len > 0 and !std.mem.eql(u8, pending.account.slice(), a.cache_tag.slice()))))
        {
            pending.account = a.cache_tag;
            a.slack_outbox_dirty = true;
        }
    }
    if (a.slack_outbox_dirty) _ = persistOutbox(a);
}

fn enqueueSlackOutbox(a: *App, slot: *SlackOutbox) void {
    if (a.outbox_load_failed or a.slack_outbox_dirty or !slackConfigured(a) or !slackAccountConfigured(a, slot.entry.account.slice()) or slot.inflight or slot.completed or slot.entry.state == .failed) return;
    for (a.slack_outbox[0..a.slack_outbox_count]) |*earlier| {
        if (earlier == slot) break;
        if (!earlier.inflight and !earlier.completed and earlier.entry.state != .failed and
            std.mem.eql(u8, earlier.entry.account.slice(), slot.entry.account.slice())) return;
    }
    if (win.GetTickCount64() < slot.not_before_ms) return;
    const entry = &slot.entry;
    const is_file = entry.file.len > 0;
    var job = WacliJob{ .provider = .slack, .kind = if (!is_file) .slack_send else if (entry.upload_file_id.len > 0) .slack_share else .slack_attach, .started_ms = win.GetTickCount64() };
    job.account.set(entry.account.slice());
    job.jid.set(entry.jid.slice());
    job.msg_id.set(entry.idSlice());
    if (!is_file) job.extra.set(entry.client_msg_id.slice());
    if (is_file) {
        wacliJobArgs(&job, &.{ entry.jid.slice(), entry.reply_to.slice(), if (entry.upload_file_id.len > 0) entry.upload_file_id.slice() else entry.file.slice(), entry.text.slice() });
    } else {
        wacliJobArgs(&job, &.{ entry.jid.slice(), entry.text.slice(), entry.reply_to.slice(), entry.client_msg_id.slice() });
    }
    if (wacliEnqueue(a, job, true)) {
        slot.inflight = true;
        slot.not_before_ms = 0;
    } else {
        slot.not_before_ms = win.GetTickCount64() + 3_000;
        setStatus(a, "Send queue is full; retrying");
    }
}

fn retrySlackOutbox(a: *App) void {
    if (a.slack_outbox_dirty and !persistOutbox(a)) {
        setStatus(a, "Could not save Slack outbox; retrying journal");
        return;
    }
    var index: usize = 0;
    while (index < a.slack_outbox_count) {
        const slot = &a.slack_outbox[index];
        if (slot.completed) {
            const id = slot.entry.id;
            const before = a.slack_outbox_count;
            retireSlackOutbox(a, &id);
            if (a.slack_outbox_count < before) continue;
        } else if (!slot.inflight) enqueueSlackOutbox(a, slot);
        index += 1;
    }
}

fn retireSlackOutbox(a: *App, id: []const u8) void {
    for (a.slack_outbox[0..a.slack_outbox_count], 0..) |*slot, victim| {
        if (!std.mem.eql(u8, slot.entry.idSlice(), id)) continue;
        slot.completed = true;
        slot.inflight = false;
        if (!persistOutbox(a)) {
            setStatus(a, "Could not save send completion; retrying journal");
            return;
        }
        var shift = victim;
        while (shift + 1 < a.slack_outbox_count) : (shift += 1) a.slack_outbox[shift] = a.slack_outbox[shift + 1];
        a.slack_outbox_count -= 1;
        a.slack_outbox[a.slack_outbox_count] = .{};
        return;
    }
}

fn handleSlackSendResult(a: *App, result: *WacliResult) void {
    for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
        if (!std.mem.eql(u8, slot.entry.idSlice(), result.msg_id.slice()) or slot.completed) continue;
        slot.inflight = false;
        if (!result.ok and std.mem.eql(u8, result.extra.slice(), "WorkspaceDisconnected")) return;
        const entry = &slot.entry;
        if (result.ok and result.kind != .slack_attach) {
            if (slack.parseSentTs(a.allocator, result.data)) |ts| {
                defer a.allocator.free(ts);
                noteSlackActivity(a, result.account.slice(), result.jid.slice(), slack.tsSeconds(ts) orelse 0);
            }
            if (result.kind == .slack_send) resolveSlackSend(a, result);
            refreshVisibleChats(a);
            retireSlackOutbox(a, result.msg_id.slice());
            var status_buffer: [64]u8 = undefined;
            const label: []const u8 = if (result.kind == .slack_send) "Sent" else "Image sent";
            const elapsed = win.GetTickCount64() - result.started_ms;
            setStatus(a, std.fmt.bufPrint(&status_buffer, "{s} in {d} ms", .{ label, elapsed }) catch label);
            return;
        }
        if (result.ok) {
            entry.upload_file_id.set(result.data);
            entry.state = .uploaded;
            entry.attempts = 0;
            a.slack_outbox_dirty = true;
            if (!persistOutbox(a)) {
                setStatus(a, "Could not save Slack upload; retrying journal");
                return;
            }
            enqueueSlackOutbox(a, slot);
            return;
        }
        if (result.kind == .slack_share and std.mem.eql(u8, result.extra.slice(), "FileMissing")) {
            entry.upload_file_id.set("");
            entry.state = .queued;
            a.slack_outbox_dirty = true;
            if (!persistOutbox(a)) {
                setStatus(a, "Could not save Slack upload; retrying journal");
                return;
            }
            enqueueSlackOutbox(a, slot);
            return;
        }
        entry.attempts +|= 1;
        switch (slack_send.retryDecision(result.extra.slice(), result.http_status, result.slack_error.slice(), entry.attempts)) {
            .retry => |delay| {
                slot.not_before_ms = win.GetTickCount64() + delay;
                a.slack_outbox_dirty = true;
                if (!persistOutbox(a)) {
                    setStatus(a, "Could not save Slack retry; retrying journal");
                    return;
                }
                setStatus(a, if (entry.file.len == 0) "Slack send failed, retrying" else "Slack image send failed, retrying");
            },
            .give_up => {
                entry.state = .failed;
                a.slack_outbox_dirty = true;
                const saved = persistOutbox(a);
                if (result.kind == .slack_send) resolveSlackSend(a, result);
                setStatus(a, if (!saved) "Could not save Slack failure; retrying journal" else if (entry.file.len == 0) "Slack send failed" else "Slack image send failed");
                var failed: usize = 0;
                for (a.slack_outbox[0..a.slack_outbox_count]) |*candidate| {
                    if (!candidate.completed and candidate.entry.state == .failed) failed += 1;
                }
                if (failed > max_failed_sends) _ = evictOldestFailedSlackOutbox(a);
            },
        }
        return;
    }
}

fn evictOldestFailedSlackOutbox(a: *App) bool {
    var oldest: ?usize = null;
    for (a.slack_outbox[0..a.slack_outbox_count], 0..) |*slot, index| {
        if (slot.entry.state != .failed or slot.completed) continue;
        if (oldest == null or slot.entry.queued_unix < a.slack_outbox[oldest.?].entry.queued_unix) oldest = index;
    }
    const victim = oldest orelse return false;
    const id = a.slack_outbox[victim].entry.id;
    const before = a.slack_outbox_count;
    retireSlackOutbox(a, &id);
    return a.slack_outbox_count < before;
}

fn requestSlackDownload(a: *App, account: []const u8, channel: []const u8, item: slack.HistoryItem) void {
    if (item.file_id.len == 0 or item.file_url.len == 0) return;
    var job = WacliJob{ .provider = .slack, .kind = .slack_download };
    job.account.set(account);
    job.jid.set(channel);
    job.msg_id.set(item.ts);
    wacliJobArgs(&job, &.{ item.file_url, item.file_id, item.file_name, channel, item.ts });
    _ = wacliEnqueue(a, job, false);
}

fn applySlackEvent(a: *App, event: *slack_win.Event) void {
    defer slack_win.destroyEvent(event);
    const account = event.teamIdSlice();
    const installation = slackInstallation(a, account) orelse return;
    const key = chat_key.Key{ .provider = .slack, .account = account, .id = event.channelSlice() };
    const is_open = a.selected_chat < a.chat_count and chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), key);
    if (std.mem.startsWith(u8, event.eventTypeSlice(), "reaction_")) {
        if (is_open) refreshSlackHistory(a);
        return;
    }
    a.slack_log_mutex.lockUncancelable(a.io);
    const fresh = a.slack_log.markAccount(account, event.channelSlice(), event.tsSlice());
    a.slack_log_mutex.unlock(a.io);
    const from_me = installation.user_id.len > 0 and std.mem.eql(u8, event.userSlice(), installation.user_id.slice());
    if (from_me and event.clientMsgIdSlice().len > 0) {
        for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
            if (slot.entry.file.len == 0 and chat_key.Key.eql(chat_key.of(&slot.entry), key) and
                std.mem.eql(u8, slot.entry.client_msg_id.slice(), event.clientMsgIdSlice()))
            {
                const id = slot.entry.id;
                setStatus(a, "Sent");
                retireSlackOutbox(a, &id);
                break;
            }
        }
    }
    if (!fresh) return;
    const channel = event.channelSlice();
    noteSlackActivity(a, account, channel, slack.tsSeconds(event.tsSlice()) orelse 0);
    const viewed = is_open and a.user_viewed and a.hwnd != null and win.IsIconic(a.hwnd.?) == 0;
    if (slackChatById(a, account, channel)) |chat| {
        if (!from_me and !viewed and slack.compareTs(event.tsSlice(), chat.slack_last_read.slice()) == .gt) {
            chat.unread = true;
            chat.unread_count += 1;
        }
    } else refreshSlackInstallation(a, installation);
    if (is_open and chat_key.Key.eql(chat_key.displayed(a), key)) {
        const item = slack.HistoryItem{
            .ts = event.tsSlice(),
            .user = event.userSlice(),
            .text = event.textSlice(),
            .thread_ts = event.threadTsSlice(),
            .file_id = event.fileIdSlice(),
            .file_url = event.fileUrlSlice(),
            .file_name = event.fileNameSlice(),
            .file_mime = event.fileMimeSlice(),
            .file_size = event.file_size,
        };
        if (from_me) dropPendingForEcho(a, event);
        insertSlackMessageSorted(a, buildSlackMessage(a, account, item));
        if (viewed) requestSlackMark(a, channel);
        if (item.file_url.len > 0) requestSlackDownload(a, account, channel, item);
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    }
    refreshVisibleChats(a);
}

fn saveSlackInstallationIndex(a: *App, extra: []const u8, removed: []const u8) bool {
    var list = std.ArrayList(u8).empty;
    defer list.deinit(a.allocator);
    var has_extra = false;
    for (&a.slack_installations) |*installation| {
        if (!installation.active or installation.is_bridge or std.mem.eql(u8, installation.team_id.slice(), removed)) continue;
        if (std.mem.eql(u8, installation.team_id.slice(), extra)) has_extra = true;
        list.appendSlice(a.allocator, installation.team_id.slice()) catch return false;
        list.append(a.allocator, '\n') catch return false;
    }
    if (extra.len > 0 and !has_extra) list.appendSlice(a.allocator, extra) catch return false;
    return slack_win.saveSecret(lit("SlackInstallations"), list.items);
}

fn installSlackWorkspace(a: *App, team_id: []const u8, team_name: []const u8, user_id: []const u8, user_token: []const u8, refresh_token: []const u8, expires_at: i64, is_bridge: bool) bool {
    if (!slack.validTeamId(team_id)) return false;
    var target = slackInstallation(a, team_id);
    if (target == null) for (&a.slack_installations) |*installation| {
        if (!installation.active) {
            target = installation;
            break;
        }
    };
    const installation = target orelse return false;
    const user = a.allocator.dupe(u8, user_token) catch return false;
    const refresh = a.allocator.dupe(u8, refresh_token) catch {
        a.allocator.free(user);
        return false;
    };
    var path_buffer: [519]u8 = undefined;
    const path = std.fmt.bufPrint(&path_buffer, "{s}\\{s}", .{ a.slack_media_dir, team_id }) catch {
        a.allocator.free(user);
        a.allocator.free(refresh);
        return false;
    };
    a.slack_install_mutex.lockUncancelable(a.io);
    a.allocator.free(installation.user_token);
    a.allocator.free(installation.refresh_token);
    if (!installation.active) {
        installation.chat_count = 0;
        installation.user_count = 0;
    }
    installation.user_token = user;
    installation.refresh_token = refresh;
    installation.expires_at = expires_at;
    installation.generation +%= 1;
    installation.needs_signin.store(false, .release);
    installation.team_id.set(team_id);
    installation.team_name.set(team_name);
    installation.user_id.set(user_id);
    installation.media_dir.set(path);
    installation.is_bridge = is_bridge;
    installation.active = true;
    a.slack_install_mutex.unlock(a.io);
    if (std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path)) |wide| {
        defer a.allocator.free(wide);
        _ = win.CreateDirectoryW(wide, null);
    } else |_| {}
    refreshSlackInstallation(a, installation);
    startSlackSocket(a);
    retrySlackOutbox(a);
    return true;
}

pub fn addSlackInstallation(team_id: []const u8, team_name: []const u8, user_id: []const u8, user_token: []const u8, refresh_token: []const u8, expires_at: i64) bool {
    const a = app_ptr orelse return false;
    var available = slackInstallation(a, team_id) != null;
    for (&a.slack_installations) |*installation| if (!installation.active) {
        available = true;
    };
    if (!available) return false;
    a.slack_install_mutex.lockUncancelable(a.io);
    const saved = slack_win.saveInstallation(.{ .team_id = team_id, .team_name = team_name, .user_id = user_id, .user_token = user_token, .refresh_token = refresh_token, .expires_at = expires_at }) and saveSlackInstallationIndex(a, team_id, "");
    if (saved) if (slackInstallation(a, team_id)) |installation| {
        installation.generation +%= 1;
    };
    a.slack_install_mutex.unlock(a.io);
    if (!saved) return false;
    return installSlackWorkspace(a, team_id, team_name, user_id, user_token, refresh_token, expires_at, false);
}

pub fn removeSlackInstallation(team_id: []const u8) bool {
    const a = app_ptr orelse return false;
    a.slack_install_mutex.lockUncancelable(a.io);
    const installation = slackInstallation(a, team_id) orelse {
        a.slack_install_mutex.unlock(a.io);
        return false;
    };
    if (installation.is_bridge) {
        slack_win.clearBridge();
    } else {
        if (!saveSlackInstallationIndex(a, "", team_id)) {
            a.slack_install_mutex.unlock(a.io);
            return false;
        }
        slack_win.deleteInstallation(team_id);
    }
    installation.active = false;
    installation.generation +%= 1;
    a.allocator.free(installation.user_token);
    a.allocator.free(installation.refresh_token);
    installation.user_token = &.{};
    installation.refresh_token = &.{};
    installation.chat_count = 0;
    installation.user_count = 0;
    a.slack_install_mutex.unlock(a.io);
    slack_win.deleteSecret(lit("SlackUserToken"));
    a.slack_install_mutex.lockUncancelable(a.io);
    a.slack_tokens = null;
    if (installation.is_bridge) a.slack_bridge = null;
    a.slack_install_mutex.unlock(a.io);
    cancelSlackMark(a);
    refreshVisibleChats(a);
    if (!messagesAreCurrent(a)) refreshMessages(a);
    return true;
}

fn bindSlackOutboxAccount(a: *App, team_id: []const u8) void {
    for (a.slack_outbox[0..a.slack_outbox_count]) |*slot| {
        if (slot.entry.account.len == 0) {
            slot.entry.account.set(team_id);
            a.slack_outbox_dirty = true;
        }
    }
    if (a.slack_outbox_dirty) _ = persistOutbox(a);
}

fn loadSlackTokens(a: *App) void {
    if (a.slack_app_token.len == 0) {
        if (slack_win.loadSecret(a.allocator, lit("SlackAppToken"))) |stored| a.slack_app_token = stored.value;
    }
    if (slack_win.loadSecret(a.allocator, lit("SlackInstallations"))) |stored| {
        defer a.allocator.free(stored.value);
        var ids = std.mem.tokenizeScalar(u8, stored.value, '\n');
        while (ids.next()) |id| {
            const saved = slack_win.loadInstallation(a.allocator, id) orelse continue;
            defer saved.deinit();
            const value = saved.value;
            _ = installSlackWorkspace(a, value.team_id, value.team_name, value.user_id, value.user_token, value.refresh_token, value.expires_at, false);
        }
    }
    a.slack_install_mutex.lockUncancelable(a.io);
    if (a.slack_tokens == null) a.slack_tokens = slack_win.loadTokens(a.allocator);
    if (a.slack_bridge == null) a.slack_bridge = slack_win.loadBridge(a.allocator);
    a.slack_install_mutex.unlock(a.io);
    if (a.slack_tokens != null) {
        const job = WacliJob{ .provider = .slack, .kind = .slack_auth };
        _ = wacliEnqueue(a, job, false);
    }
    if (a.slack_bridge != null) {
        var job = WacliJob{ .provider = .slack, .kind = .slack_auth };
        job.extra.set("bridge");
        _ = wacliEnqueue(a, job, false);
    }
    startSlackSocket(a);
    retrySlackOutbox(a);
}

const SlackOAuthTask = struct {
    arena: std.heap.ArenaAllocator,
    client_id: []const u8,
    applied: win.HANDLE,
    response: ?slack_oauth.TokenResponse = null,
    failure: []const u8 = "",
    saved: std.atomic.Value(bool) = .init(false),
    app_token: []const u8 = "",
    socket_stopped: bool = false,
};

fn finishSlackSignIn(a: *App) void {
    if (a.slack_oauth_thread) |thread| thread.join();
    a.slack_oauth_thread = null;
    if (a.slack_oauth_task) |task| {
        _ = win.CloseHandle(task.applied);
        task.arena.deinit();
        a.allocator.destroy(task);
    }
    a.slack_oauth_task = null;
}

fn slackSignInWorker(a: *App, task: *SlackOAuthTask) void {
    var callback: ?slack_oauth_win.Callback = null;
    defer if (callback) |connection| connection.close();
    const allocator = task.arena.allocator();
    if (!std.mem.eql(u8, a.slack_app_token, task.app_token)) {
        a.slack_stop.store(true, .release);
        if (a.slack_socket_thread) |thread| thread.join();
        task.socket_stopped = true;
    }
    const outcome: anyerror!slack_oauth.TokenResponse = blk: {
        callback = slack_oauth_win.authorize(allocator, a.io, task.client_id, &a.slack_oauth_stop) catch |err| break :blk err;
        const connection = callback.?;
        const body = slack_oauth.buildAccessBody(allocator, task.client_id, connection.code, &connection.attempt.code_verifier) catch |err| break :blk err;
        const json = slack_win.exchangeOAuth(allocator, body) catch |err| break :blk err;
        const response = slack_oauth.parseResponse(allocator, json) catch |err| break :blk err;
        if (!slack.validTeamId(response.team_id) or response.user_id.len > 32 or response.user_id.len < 2 or
            response.user_id[0] != 'U' or !slack_win.isUserToken(response.access_token)) break :blk error.UserTokenRequired;
        break :blk response;
    };
    if (outcome) |response| task.response = response else |err| task.failure = @errorName(err);
    if (!a.slack_oauth_stop.load(.acquire)) {
        if (a.hwnd) |hwnd| {
            if (win.PostMessageW(hwnd, wm_slack_oauth_done, 0, 0) != 0) _ = win.WaitForSingleObject(task.applied, win.INFINITE);
        }
    }
    if (callback) |connection| connection.respond(task.saved.load(.acquire), if (task.saved.load(.acquire)) "Return to Messages to view your workspace." else "Return to Messages for details and try connecting again.");
    if (a.hwnd) |hwnd| _ = win.PostMessageW(hwnd, wm_slack_oauth_finished, 0, 0);
}

fn startSlackSignIn(a: *App, client_id: []const u8) void {
    if (unifiedHub(a)) return setStatus(a, "Manage accounts on the hub");
    if (a.slack_oauth_thread != null) return setStatus(a, "Slack sign-in is already in progress");
    const app_token = slack_win.loadSecret(a.allocator, lit("SlackAppToken")) orelse return setStatus(a, "Enter a Socket Mode app token in Slack sign-in settings");
    if (!slack_win.isAppToken(app_token.value)) {
        a.allocator.free(app_token.value);
        return setStatus(a, "Invalid Socket Mode app token; open Slack sign-in settings");
    }
    defer a.allocator.free(app_token.value);
    const task = a.allocator.create(SlackOAuthTask) catch return setStatus(a, "Could not start Slack sign-in");
    const event = win.CreateEventW(null, win.TRUE, win.FALSE, null) orelse {
        a.allocator.destroy(task);
        return setStatus(a, "Could not start Slack sign-in");
    };
    task.* = .{ .arena = std.heap.ArenaAllocator.init(a.allocator), .client_id = "", .applied = event };
    task.client_id = task.arena.allocator().dupe(u8, client_id) catch {
        _ = win.CloseHandle(event);
        task.arena.deinit();
        a.allocator.destroy(task);
        return setStatus(a, "Could not start Slack sign-in");
    };
    task.app_token = task.arena.allocator().dupe(u8, app_token.value) catch {
        _ = win.CloseHandle(event);
        task.arena.deinit();
        a.allocator.destroy(task);
        return setStatus(a, "Could not start Slack sign-in");
    };
    a.slack_oauth_task = task;
    a.slack_oauth_stop.store(false, .release);
    a.slack_oauth_thread = std.Thread.spawn(.{ .stack_size = 1024 * 1024 }, slackSignInWorker, .{ a, task }) catch {
        finishSlackSignIn(a);
        return setStatus(a, "Could not start Slack sign-in worker");
    };
    setStatus(a, "Sign in with Slack in your browser (5 minute timeout)...");
}

const id_slack_user_edit = 100;
const id_slack_app_edit = 101;
const id_slack_save = 102;
const id_slack_cancel = 103;

const id_tg_prompt = 110;
const id_tg_edit = 111;
const id_tg_next = 112;
const id_tg_cancel = 113;
const id_tg_open_page = 114;

