};

fn pickImageFile(a: *App) ?WideText(519) {
    if (!shell_lazy.ensureComdlg32()) return null;
    var buffer: [519]u16 = [_]u16{0} ** 519;
    var ofn = std.mem.zeroes(OPENFILENAMEW);
    ofn.lStructSize = @sizeOf(OPENFILENAMEW);
    ofn.hwndOwner = a.hwnd orelse return null;
    ofn.lpstrFilter = lit("Images\x00*.png;*.jpg;*.jpeg;*.gif;*.webp\x00All files\x00*.*\x00");
    ofn.lpstrFile = @ptrCast(&buffer);
    ofn.nMaxFile = buffer.len;
    ofn.Flags = 0x00000800 | 0x00001000 | 0x00000008;
    if (shell_lazy.getOpenFileNameW.?(@ptrCast(&ofn)) == 0) return null;
    const chosen = std.unicode.utf16LeToUtf8Alloc(a.allocator, std.mem.span(@as([*:0]const u16, @ptrCast(&buffer)))) catch return null;
    defer a.allocator.free(chosen);
    var result = WideText(519){};
    result.set(a.allocator, chosen);
    return result;
}

fn layoutSetupButtons(hwnd: win.HWND) void {
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    const btn_w: i32 = 90;
    const btn_h: i32 = 30;
    const gap: i32 = 8;
    const margin: i32 = 16;
    const bottom = client.bottom - margin - btn_h;
    if (win.GetDlgItem(hwnd, id_slack_cancel)) |c| _ = win.MoveWindow(c, client.right - margin - btn_w, bottom, btn_w, btn_h, win.TRUE);
    if (win.GetDlgItem(hwnd, id_slack_save)) |s| _ = win.MoveWindow(s, client.right - margin - 2 * btn_w - gap, bottom, btn_w, btn_h, win.TRUE);
}

fn slackSetupProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) isize {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, @bitCast(wparam), @bitCast(lparam));
    switch (message) {
        win.WM_CREATE => {
            _ = win.CreateWindowExW(0, lit("STATIC"), lit("Slack app Client ID"), win.WS_CHILD | win.WS_VISIBLE, 16, 16, 360, 20, hwnd, null, a.instance, null);
            _ = win.CreateWindowExW(0, lit("EDIT"), null, win.WS_CHILD | win.WS_VISIBLE | win.WS_BORDER | win.WS_TABSTOP | win.ES_AUTOHSCROLL, 16, 38, 360, 26, hwnd, controlId(id_slack_user_edit), a.instance, null);
            _ = win.CreateWindowExW(0, lit("STATIC"), lit("App token (xapp-) for Socket Mode"), win.WS_CHILD | win.WS_VISIBLE, 16, 74, 360, 20, hwnd, null, a.instance, null);
            _ = win.CreateWindowExW(0, lit("EDIT"), null, win.WS_CHILD | win.WS_VISIBLE | win.WS_BORDER | win.WS_TABSTOP | win.ES_AUTOHSCROLL | win.ES_PASSWORD, 16, 96, 360, 26, hwnd, controlId(id_slack_app_edit), a.instance, null);
            const save = win.CreateWindowExW(0, lit("BUTTON"), lit("Sign in"), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.BS_OWNERDRAW | win.BS_DEFPUSHBUTTON, 0, 0, 90, 30, hwnd, controlId(id_slack_save), a.instance, null);
            const cancel = win.CreateWindowExW(0, lit("BUTTON"), lit("Cancel"), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.BS_OWNERDRAW, 0, 0, 90, 30, hwnd, controlId(id_slack_cancel), a.instance, null);
            setFont(save, a.font_bold);
            setFont(cancel, a.font_bold);
            subclassComposerButton(a, save, 3);
            subclassComposerButton(a, cancel, 4);
            if (slack_win.loadClientId(a.allocator)) |client| {
                defer a.allocator.free(client);
                var text: WideText(511) = .{};
                text.set(a.allocator, client);
                _ = win.SetDlgItemTextW(hwnd, id_slack_user_edit, text.ptr());
            }
            if (slack_win.loadSecret(a.allocator, lit("SlackAppToken"))) |stored| {
                defer a.allocator.free(stored.value);
                var text: WideText(511) = .{};
                text.set(a.allocator, stored.value);
                _ = win.SetDlgItemTextW(hwnd, id_slack_app_edit, text.ptr());
            }
            setFont(win.GetDlgItem(hwnd, id_slack_user_edit), a.font);
            setFont(win.GetDlgItem(hwnd, id_slack_app_edit), a.font);
            layoutSetupButtons(hwnd);
            return 0;
        },
        win.WM_SIZE => {
            layoutSetupButtons(hwnd);
            return 0;
        },
        win.WM_ERASEBKGND => {
            var client: win.RECT = undefined;
            _ = win.GetClientRect(hwnd, &client);
            _ = win.FillRect(winHandle(win.HDC, @as(usize, @bitCast(wparam))), &client, a.brush_panel.?);
            return 1;
        },
        win.WM_PAINT => {
            if (theme.choice != .amoled) return win.DefWindowProcW(hwnd, message, wparam, lparam);
            var paint: win.PAINTSTRUCT = undefined;
            const hdc = win.BeginPaint(hwnd, &paint);
            defer _ = win.EndPaint(hwnd, &paint);
            var shapes = smooth.Context.init(hdc);
            defer shapes.deinit();
            paintPopupInput(&shapes, hwnd, win.GetDlgItem(hwnd, id_slack_user_edit));
            paintPopupInput(&shapes, hwnd, win.GetDlgItem(hwnd, id_slack_app_edit));
            return 0;
        },
        win.WM_DRAWITEM => {
            const item: *win.DRAWITEMSTRUCT = winHandle(*win.DRAWITEMSTRUCT, @as(usize, @bitCast(lparam)));
            if (item.CtlID == id_slack_save or item.CtlID == id_slack_cancel) drawSetupButton(a, item);
            return 1;
        },
        win.WM_CTLCOLORSTATIC, win.WM_CTLCOLOREDIT => {
            const hdc: win.HDC = winHandle(win.HDC, wparam);
            _ = win.SetTextColor(hdc, theme.current.on_surface);
            if (message == win.WM_CTLCOLOREDIT and theme.choice == .amoled) {
                _ = win.SetBkColor(hdc, theme.current.surface_container_high);
                return @bitCast(@intFromPtr(a.brush_raised.?));
            }
            _ = win.SetBkColor(hdc, theme.current.surface_container_low);
            if (a.brush_panel) |brush| return @bitCast(@intFromPtr(brush));
            return @bitCast(@intFromPtr(win.GetStockObject(win.BLACK_BRUSH)));
        },
        win.WM_COMMAND => {
            const id = loword(wparam);
            const notification = hiword(wparam);
            if ((id == id_slack_user_edit or id == id_slack_app_edit) and (notification == win.EN_SETFOCUS or notification == win.EN_KILLFOCUS)) {
                _ = win.InvalidateRect(hwnd, null, win.FALSE);
                return 0;
            }
            if (id == id_slack_cancel) {
                _ = win.DestroyWindow(hwnd);
                return 0;
            }
            if (id != id_slack_save) return 0;
            var user_wide: [512]u16 = [_]u16{0} ** 512;
            var app_wide: [512]u16 = [_]u16{0} ** 512;
            const user_len: usize = @intCast(win.GetDlgItemTextW(hwnd, id_slack_user_edit, &user_wide, user_wide.len));
            const app_len: usize = @intCast(win.GetDlgItemTextW(hwnd, id_slack_app_edit, &app_wide, app_wide.len));
            const user = std.unicode.utf16LeToUtf8Alloc(a.allocator, user_wide[0..user_len]) catch return 0;
            defer a.allocator.free(user);
            const app = std.unicode.utf16LeToUtf8Alloc(a.allocator, app_wide[0..app_len]) catch return 0;
            defer a.allocator.free(app);
            if (!slack_win.validClientId(user) or !slack_win.isAppToken(app)) {
                setStatus(a, "Enter a Slack Client ID and an xapp- Socket Mode token");
                return 0;
            }
            if (!slack_win.saveClientId(user) or !slack_win.saveSecret(lit("SlackAppToken"), app)) {
                setStatus(a, "Could not store Slack sign-in settings");
                return 0;
            }
            _ = win.DestroyWindow(hwnd);
            startSlackSignIn(a, user);
            return 0;
        },
        win.WM_CLOSE => {
            _ = win.DestroyWindow(hwnd);
            return 0;
        },
        win.WM_NCDESTROY => {
            a.slack_setup_window = null;
            if (a.hwnd) |main_hwnd| {
                _ = win.EnableWindow(main_hwnd, 1);
                _ = win.SetFocus(main_hwnd);
            }
            return 0;
        },
        else => {},
    }
    return win.DefWindowProcW(hwnd, message, wparam, lparam);
}

fn openSlackSetup(a: *App) void {
    if (unifiedHub(a)) return setStatus(a, "Manage accounts on the hub");
    if (a.slack_setup_window != null) {
        if (a.slack_setup_window) |setup| _ = win.SetFocus(setup);
        return;
    }
    if (a.hwnd) |main_hwnd| _ = win.EnableWindow(main_hwnd, 0);
    const wnd = win.CreateWindowExW(
        win.WS_EX_DLGMODALFRAME,
        lit("SlackSetup"),
        lit("Sign in to Slack"),
        win.WS_OVERLAPPED | win.WS_CAPTION | win.WS_SYSMENU,
        200,
        200,
        410,
        215,
        a.hwnd orelse return,
        null,
        a.instance,
        null,
    ) orelse {
        if (a.hwnd) |main_hwnd| _ = win.EnableWindow(main_hwnd, 1);
        return;
    };
    a.slack_setup_window = wnd;
    if (theme.choice == .amoled) {
        var dark: win.BOOL = win.TRUE;
        _ = win.DwmSetWindowAttribute(wnd, 20, &dark, @sizeOf(win.BOOL));
    }
    _ = win.ShowWindow(wnd, win.SW_SHOW);
    var msg: win.MSG = undefined;
    while (true) {
        const got = win.GetMessageW(&msg, null, 0, 0);
        if (got == 0) {
            _ = win.PostQuitMessage(@intCast(msg.wParam));
            break;
        }
        if (got < 0) break;
        if (win.IsDialogMessageW(wnd, &msg) != 0) {
            if (a.slack_setup_window == null) break;
            continue;
        }
        _ = win.TranslateMessage(&msg);
        _ = win.DispatchMessageW(&msg);
        if (a.slack_setup_window == null) break;
    }
}

fn startSlackSocket(a: *App) void {
    if (!slackConfigured(a) or a.slack_socket_thread != null) return;
    if (a.slack_app_token.len == 0) return;
    a.slack_stop.store(false, .release);
    const config = slack_win.SocketConfig{
        .user_token = "",
        .app_token = a.slack_app_token,
        .stop = &a.slack_stop,
        .connected = &a.slack_connected,
        .sink = .{
            .hwnd = if (a.hwnd) |hwnd| hwnd else return,
            .message_id = wm_slack_event,
            .queue = &a.slack_event_pending,
        },
    };
    a.slack_socket_thread = std.Thread.spawn(.{ .stack_size = 1024 * 1024 }, slack_win.socketThreadMain, .{config}) catch null;
    if (a.slack_socket_thread == null) setStatus(a, "Slack connection failed to start");
}

fn markChatRead(a: *App) void {
    if (!a.user_viewed or a.selected_chat >= a.chat_count) return;
    const chat = &a.chats[a.selected_chat];
    const was_unread = chat.unread or chat.unread_count > 0;
    if (!unifiedHub(a) and chat.provider == .telegram) {
        if (a.message_count > 0) {
            const last = a.messages[a.message_count - 1];
            const chat_id = tgSelectedChatId(a) orelse return;
            const message_id = std.fmt.parseInt(i64, last.id.slice(), 10) catch return;
            if (a.telegram) |client| client.markRead(chat_id, message_id);
        }
        chat.unread = false;
        chat.unread_count = 0;
        const id = std.fmt.parseInt(i64, chat.jid.slice(), 10) catch return;
        for (a.tg_chats[0..a.tg_chat_count]) |*cached| if (cached.id == id) {
            cached.unread_count = 0;
        };
        return;
    }
    if (!unifiedHub(a) and chat.provider == .slack) {
        chat.unread = false;
        chat.unread_count = 0;
        if (slackChatById(a, chat.account.slice(), chat.jid.slice())) |cached| {
            cached.unread = false;
            cached.unread_count = 0;
        }
        if (was_unread != (chat.unread or chat.unread_count > 0)) invalidateChatRow(a, a.selected_chat);
        requestSlackMark(a, chat.jid.slice());
        return;
    }
    const needs_receipt = chat.provider_unread or chat.unread or chat.unread_count > 0;
    if (chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat))) {
        for (a.messages[0..a.message_count]) |*message| {
            if (message.send_state != .none) continue;
            const timestamp = media_age.unixSeconds(message.timestamp.slice()) orelse continue;
            a.read_state.markRead(a.allocator, a.cache_tag.slice(), chat.jid.slice(), timestamp);
        }
        persistReadState(a);
        chat.unread = a.read_state.isUnread(a.cache_tag.slice(), chat.jid.slice());
        chat.unread_count = if (chat.unread) @max(1, chat.unread_count) else 0;
        if (was_unread != (chat.unread or chat.unread_count > 0)) invalidateChatRow(a, a.selected_chat);
    }
    if (!needs_receipt or a.read_queue_dead) return;
    var already_queued = false;
    var index: usize = 0;
    while (index < a.pending_read_count) : (index += 1) {
        if (std.mem.eql(u8, a.pending_reads[index].slice(), chat.jid.slice())) already_queued = true;
    }
    if (already_queued or a.pending_read_count < a.pending_reads.len) {
        if (!already_queued) {
            a.pending_reads[a.pending_read_count].set(chat.jid.slice());
            a.read_retries[a.pending_read_count] = 0;
            a.pending_read_count += 1;
            persistPendingReads(a);
        }
    }
    startNextMarkRead(a);
}

const slack_mark_debounce_ms: u32 = 750;

fn cancelSlackMark(a: *App) void {
    if (a.hwnd) |hwnd| _ = win.KillTimer(hwnd, timer_slack_mark);
    a.slack_mark_account.set("");
    a.slack_mark_channel.set("");
    a.slack_mark_ts.set("");
    a.slack_mark_gen += 1;
    a.slack_mark_due_ms = 0;
}

fn slackMarkViewMatches(a: *App, channel: []const u8) bool {
    if (!a.user_viewed or a.chat_selection_pending or !selectedChatIsSlack(a)) return false;
    return std.mem.eql(u8, a.chats[a.selected_chat].jid.slice(), channel) and
        chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]));
}

fn requestSlackMark(a: *App, channel: []const u8) void {
    if (!slackMarkViewMatches(a, channel)) return;
    var newest: []const u8 = "";
    for (a.messages[0..a.message_count]) |*message| {
        newest = slack.newerMarkTs(newest, message.id.slice());
    }
    const account = a.chats[a.selected_chat].account;
    if (!std.mem.eql(u8, a.slack_mark_account.slice(), account.slice())) cancelSlackMark(a);
    if (slack.markDebounce(a.slack_mark_channel.slice(), a.slack_mark_ts.slice(), channel, newest) == .skip) return;
    a.slack_mark_account = account;
    a.slack_mark_channel.set(channel);
    a.slack_mark_ts.set(newest);
    a.slack_mark_due_ms = win.GetTickCount64() + slack_mark_debounce_ms;
    if (a.hwnd) |hwnd| {
        _ = win.KillTimer(hwnd, timer_slack_mark);
        if (win.SetTimer(hwnd, timer_slack_mark, slack_mark_debounce_ms, null) == 0) {
            cancelSlackMark(a);
            logSlackFailure(a, .slack_mark, "TimerFailed", 0);
        }
    }
}

fn fireSlackMark(a: *App) void {
    const channel = a.slack_mark_channel.slice();
    const ts = a.slack_mark_ts.slice();
    if (channel.len == 0 or ts.len == 0 or a.slack_mark_due_ms == 0) return;
    if (!slackMarkViewMatches(a, channel) or !std.mem.eql(u8, a.chats[a.selected_chat].account.slice(), a.slack_mark_account.slice()) or !slackConfigured(a)) {
        cancelSlackMark(a);
        return;
    }
    const now = win.GetTickCount64();
    if (now < a.slack_mark_due_ms) {
        if (a.hwnd) |hwnd| {
            if (win.SetTimer(hwnd, timer_slack_mark, @intCast(a.slack_mark_due_ms - now), null) == 0) {
                cancelSlackMark(a);
                logSlackFailure(a, .slack_mark, "TimerFailed", 0);
            }
        }
        return;
    }
    a.slack_mark_due_ms = 0;
    var job = WacliJob{ .provider = .slack, .kind = .slack_mark, .gen = a.slack_mark_gen };
    job.account = a.slack_mark_account;
    job.jid.set(channel);
    job.msg_id.set(ts);
    wacliJobArgs(&job, &.{ channel, ts });
    _ = wacliEnqueue(a, job, false);
}

fn removeFirstPendingRead(a: *App) void {
    if (a.pending_read_count == 0) return;
    var index: usize = 1;
    while (index < a.pending_read_count) : (index += 1) {
        a.pending_reads[index - 1] = a.pending_reads[index];
        a.read_retries[index - 1] = a.read_retries[index];
        a.read_backoff_until[index - 1] = a.read_backoff_until[index];
    }
    a.pending_read_count -= 1;
    a.pending_reads[a.pending_read_count] = .{};
    a.read_retries[a.pending_read_count] = 0;
    a.read_backoff_until[a.pending_read_count] = 0;
    persistPendingReads(a);
}

const max_read_retries = 3;

const read_retry_backoff_ms: u64 = 10 * 60 * 1000;

fn nextReadRetry(retries: u8) u8 {
    return if (retries + 1 >= max_read_retries) 0 else retries + 1;
}

fn requeueFailedRead(a: *App) void {
    const jid = a.pending_reads[0];
    const retries = nextReadRetry(a.read_retries[0]);
    const backoff = if (retries == 0) win.GetTickCount64() + read_retry_backoff_ms else a.read_backoff_until[0];
    removeFirstPendingRead(a);
    a.pending_reads[a.pending_read_count] = jid;
    a.read_retries[a.pending_read_count] = retries;
    a.read_backoff_until[a.pending_read_count] = backoff;
    a.pending_read_count += 1;
    persistPendingReads(a);
}

fn persistPendingReads(a: *App) void {
    if (a.read_path.len == 0) return;
    var buffer: [max_pending_reads * 192]u8 = undefined;
    var total: usize = 0;
    for (a.pending_reads[0..a.pending_read_count]) |entry| {
        const jid = entry.slice();
        if (jid.len == 0) continue;
        @memcpy(buffer[total..][0..jid.len], jid);
        total += jid.len;
        buffer[total] = '\n';
        total += 1;
    }
    const temp_path = std.fmt.allocPrint(a.allocator, "{s}.new", .{a.read_path}) catch return;
    defer a.allocator.free(temp_path);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, temp_path) catch return;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_WRITE, 0, null, win.CREATE_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    var written_total: usize = 0;
    var ok = true;
    while (ok and written_total < total) {
        var written: win.DWORD = 0;
        if (win.WriteFile(handle, buffer[written_total..].ptr, @intCast(total - written_total), &written, null) == 0 or written == 0) ok = false;
        written_total += written;
    }
    _ = win.CloseHandle(handle);
    if (!ok or written_total != total) return;
    const target = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, a.read_path) catch return;
    defer a.allocator.free(target);
    _ = win.MoveFileExW(wide.ptr, target.ptr, win.MOVEFILE_REPLACE_EXISTING);
}

fn loadPendingReads(a: *App) void {
    if (a.read_path.len == 0) return;
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, a.read_path) catch return;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_READ, win.FILE_SHARE_READ, null, win.OPEN_EXISTING, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var buffer: [4 * 1024]u8 = undefined;
    var total: usize = 0;
    while (total < buffer.len) {
        var got: win.DWORD = 0;
        if (win.ReadFile(handle, buffer[total..].ptr, @intCast(buffer.len - total), &got, null) == 0) break;
        if (got == 0) break;
        total += got;
    }
    var parsed: [pending_reads.max_pending_reads][pending_reads.max_jid_len + 1]u8 = undefined;
    const count = pending_reads.parse(buffer[0..total], &parsed, unifiedHub(a));
    a.pending_read_count = 0;
    for (parsed[0..count]) |entry| {
        const jid = pending_reads.term(entry[0..]);
        a.pending_reads[a.pending_read_count].set(jid);
        a.pending_read_count += 1;
    }
}

fn startNextMarkRead(a: *App) void {
    if (hubConfigured(a)) {
        startHubMarkRead(a);
        return;
    }
    if (a.read_child != null or a.pending_read_count == 0) return;
    if (a.read_backoff_until[0] > win.GetTickCount64()) {
        const now = win.GetTickCount64();
        var ready: ?usize = null;
        var index: usize = 1;
        while (index < a.pending_read_count) : (index += 1) {
            if (a.read_backoff_until[index] <= now) {
                ready = index;
                break;
            }
        }
        const swap_with = ready orelse return;
        const jid = a.pending_reads[0];
        const retries = a.read_retries[0];
        const backoff = a.read_backoff_until[0];
        a.pending_reads[0] = a.pending_reads[swap_with];
        a.read_retries[0] = a.read_retries[swap_with];
        a.read_backoff_until[0] = a.read_backoff_until[swap_with];
        a.pending_reads[swap_with] = jid;
        a.read_retries[swap_with] = retries;
        a.read_backoff_until[swap_with] = backoff;
        persistPendingReads(a);
    }
    if (a.send_child != null or sendReadyPending(a) or
        a.archive_child != null or a.pending_archive_count > 0 or
        avatarBusy(a) or mediaBusy(a)) return;
    stopSync(a, "mark read");
    const child = child_process.spawn(a.io, .{
        .argv = &.{ a.wacli_path, "--json", "--lock-wait", "70s", "chats", "mark-read", "--chat", a.pending_reads[0].slice() },
        .stdin = .ignore,
        .stdout = .ignore,
        .stderr = .ignore,
        .create_no_window = true,
    }) catch {
        a.read_spawn_failures += 1;
        if (a.read_spawn_failures >= 3) {
            a.pending_read_count = 0;
            a.read_queue_dead = true;
            a.read_spawn_failures = 0;
            startSync(a);
            refreshChats(a);
            setStatus(a, "Could not sync read state; local reads saved");
        } else setStatus(a, "Could not start mark as read; retrying");
        return;
    };
    a.read_spawn_failures = 0;
    a.read_child = child;
    a.read_started_ms = win.GetTickCount64();
}

const mark_read_hung_child_timeout_ms: u64 = 90_000;

const send_timeout_ms: u64 = 90_000;

fn checkMarkRead(a: *App) void {
    if (a.read_child) |*child| {
        const handle = child.id orelse return;
        var code: win.DWORD = 0;
        if (win.GetExitCodeProcess(handle, &code) == 0 or code == win.STILL_ACTIVE) {
            if (win.GetTickCount64() - a.read_started_ms <= mark_read_hung_child_timeout_ms) return;
            _ = child.kill(a.io);
            code = 1;
        } else _ = child.wait(a.io) catch {};
        a.read_child = null;
        if (code != 0) requeueFailedRead(a) else removeFirstPendingRead(a);
        if (a.pending_read_count > 0) {
            startNextMarkRead(a);
            if (a.read_child != null) return;
        }
        startNextSend(a);
        startNextArchive(a);
        drainMediaDownloads(a);
        startSync(a);
        refreshChats(a);
        setStatus(a, if (code == 0) "Chat marked as read" else "Mark as read failed");
        retryPendingDownload(a);
    } else startNextMarkRead(a);
}

fn retryPendingDownload(a: *App) void {
    if (a.pending_download_id.len == 0 or freeMediaSlot(a) == null or a.send_child != null) return;
    if (a.selected_chat >= a.chat_count) return;
    if (!std.mem.eql(u8, a.pending_download_jid.slice(), a.chats[a.selected_chat].jid.slice())) {
        a.pending_download_jid.set("");
        a.pending_download_id.set("");
        return;
    }
    var found: ?usize = null;
    for (a.messages[0..a.message_count], 0..) |*message, index| {
        if (std.mem.eql(u8, message.id.slice(), a.pending_download_id.slice())) found = index;
    }
    a.pending_download_jid.set("");
    a.pending_download_id.set("");
    if (found) |index| _ = downloadMedia(a, index, false);
}

fn clearMessages(a: *App) void {
    a.text_selection = .{};
    a.text_dragging = false;
    if (a.canvas) |canvas| {
        _ = win.KillTimer(canvas, timer_passage_scroll);
        if (win.GetCapture() == canvas) _ = win.ReleaseCapture();
    }
    for (a.messages[0..a.message_count]) |*message| {
        if (message.bitmap) |bitmap| {
            _ = win.DeleteObject(bitmap);
            message.bitmap = null;
        }
        a.message_bitmap_lru.remove(@intFromPtr(message));
        if (message.gif_reader != null) _ = message.gif_reader.*.lpVtbl.*.Release.?(message.gif_reader);
    }
    a.message_count = 0;
    a.selected_message = null;
}

fn messagesAreCurrent(a: *const App) bool {
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) return a.displayed_jid.len == 0;
    const chat = &a.chats[a.selected_chat];
    return chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat)) and
        std.mem.eql(u8, a.displayed_timestamp.slice(), chat.timestamp.slice());
}

fn isImage(message: *const Message) bool {
    return std.ascii.eqlIgnoreCase(message.media_type.slice(), "image") or
        std.ascii.eqlIgnoreCase(message.media_type.slice(), "sticker");
}

fn isVideo(message: *const Message) bool {
    return std.ascii.eqlIgnoreCase(message.media_type.slice(), "video") or
        std.ascii.eqlIgnoreCase(message.media_type.slice(), "gif");
}

fn isAudio(message: *const Message) bool {
    return std.ascii.eqlIgnoreCase(message.media_type.slice(), "audio") or
        std.ascii.eqlIgnoreCase(message.media_type.slice(), "voice");
}

fn ensureAudioPlayer(a: *App) ?*audio.Player {
    if (a.audio_player) |player| return player;
    a.audio_player = audio.Player.create(a.allocator, a.io) catch null;
    return a.audio_player;
}

fn voicePosKey(a: *const App, jid: []const u8, id: []const u8) u64 {
    _ = a;
    return played.Set.pairKey(jid, id);
}

fn saveAudioPos(a: *App) void {
    if (a.audio_playing_id.len == 0) return;
    const player = a.audio_player orelse return;
    const duration: i64 = if (a.audio_duration_ms > 0) a.audio_duration_ms else player.durationMs();
    var position: i64 = player.positionMs();
    if (player.state() == .ended or (duration > 0 and position >= duration - 500)) position = 0;
    const key = voicePosKey(a, a.audio_playing_jid.slice(), a.audio_playing_id.slice());
    if (!a.voice_pos.set(key, @intCast(@max(0, position)), @intCast(@max(0, duration)))) return;
    var buffer: [voice_pos.capacity * 48]u8 = undefined;
    const text = a.voice_pos.serialize(&buffer) orelse return;
    const path = messagesDirPath(a, "voice-pos.txt") orelse return;
    defer a.allocator.free(path);
    _ = writeCacheFileAtomic(a, path, text);
}

fn loadVoicePos(a: *App) void {
    const path = messagesDirPath(a, "voice-pos.txt") orelse return;
    defer a.allocator.free(path);
    const contents = readFileWin(a.allocator, path, voice_pos.capacity * 48) orelse return;
    defer a.allocator.free(contents);
    a.voice_pos.load(contents);
}

fn stopAudio(a: *App) void {
    a.audio_auto_advance = false;
    a.audio_chain_waiting = false;
    if (a.audio_state == .empty) return;
    saveAudioPos(a);
    a.audio_resume_ms = 0;
    a.audio_state = .empty;
    a.audio_playing_id.set("");
    a.audio_position_ms = 0;
    a.audio_duration_ms = 0;
    if (a.audio_player) |player| player.stop();
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn startAudioPlayback(a: *App, message: *Message) void {
    const player = ensureAudioPlayer(a) orelse {
        setStatus(a, "Windows cannot start audio playback");
        return;
    };
    const path_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.local_path.slice()) catch return;
    defer a.allocator.free(path_utf8);
    if (a.audio_state != .empty and !std.mem.eql(u8, a.audio_playing_id.slice(), message.id.slice())) saveAudioPos(a);
    const jid = if (a.chat_count > 0 and a.selected_chat < a.chat_count) a.chats[a.selected_chat].jid.slice() else "";
    player.play(path_utf8);
    markPlayed(a, message.id.slice());
    a.audio_auto_advance = true;
    a.audio_chain_waiting = false;
    a.audio_playing_jid.set(jid);
    a.audio_resume_ms = if (a.voice_pos.get(voicePosKey(a, jid, message.id.slice()))) |saved| saved.pos_ms else 0;
    a.audio_playing_id.set(message.id.slice());
    a.audio_state = .playing;
    a.audio_position_ms = 0;
    a.audio_duration_ms = 0;
    setStatus(a, "Playing voice message...");
}

fn toggleAudio(a: *App, message: *Message) void {
    const player = a.audio_player orelse return;
    switch (player.state()) {
        .playing => {
            player.pause();
            a.audio_state = .paused;
            saveAudioPos(a);
        },
        .paused => {
            player.unpause();
            a.audio_state = .playing;
        },
        .ended => {
            player.seek(0);
            player.unpause();
            a.audio_state = .playing;
        },
        else => startAudioPlayback(a, message),
    }
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn seekAudio(a: *App, x: i32, hit: win.RECT) void {
    const player = a.audio_player orelse return;
    if (a.audio_duration_ms <= 0) return;
    const track_left = hit.left + px(a, 94);
    const track_right = hit.right - px(a, 64);
    if (track_right <= track_left) return;
    const fraction = std.math.clamp(@as(f64, @floatFromInt(x - track_left)) / @as(f64, @floatFromInt(track_right - track_left)), 0, 1);
    const target_ms: i64 = @intFromFloat(fraction * @as(f64, @floatFromInt(a.audio_duration_ms)));
    player.seek(target_ms);
    a.audio_position_ms = target_ms;
    player.unpause();
    a.audio_state = .playing;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn handleAudioClick(a: *App, message: *Message, x: i32) void {
    const active = std.mem.eql(u8, a.audio_playing_id.slice(), message.id.slice()) and a.audio_state != .empty;
    if (!active) {
        startAudioPlayback(a, message);
        return;
    }
    const hit = message.media_hit;
    if (x < hit.left + px(a, 48)) {
        toggleAudio(a, message);
        return;
    }
    if (x < hit.left + px(a, 96)) {
        cycleSpeed(a);
        return;
    }
    seekAudio(a, x, hit);
}

fn advanceAudio(a: *App, after_id: []const u8) bool {
    if (!a.audio_auto_advance) return false;
    var start: usize = a.message_count;
    for (a.messages[0..a.message_count], 0..) |*message, index| {
        if (std.mem.eql(u8, message.id.slice(), after_id)) {
            start = index + 1;
            break;
        }
    }
    if (start >= a.message_count) return false;
    for (a.messages[start..a.message_count], start..) |*message, index| {
        if (!isAudio(message) or message.id.len == 0) continue;
        if (message.local_path.len > 0) {
            startAudioPlayback(a, message);
            return true;
        } else if (freeMediaSlot(a) != null or mediaDownloading(a, a.chats[a.selected_chat].jid.slice(), message.id.slice())) {
            _ = downloadMedia(a, index, true);
            if (mediaDownloading(a, a.chats[a.selected_chat].jid.slice(), message.id.slice())) {
                a.audio_chain_waiting = true;
                a.audio_chain_id.set(message.id.slice());
            }
        }
        return true;
    }
    return false;
}

fn updateAudioPlayback(a: *App) void {
    const player = a.audio_player orelse return;
    const state = player.state();
    if (state == .ended and (a.audio_state == .playing or a.audio_state == .paused)) {
        var ended_id: [191]u8 = undefined;
        const ended = a.audio_playing_id.slice();
        const ended_len = @min(ended.len, ended_id.len);
        @memcpy(ended_id[0..ended_len], ended[0..ended_len]);
        saveAudioPos(a);
        if (advanceAudio(a, ended_id[0..ended_len])) return;
    }
    if (player.start_failed.load(.acquire) and state == .idle) {
        if (a.audio_state != .empty) {
            a.audio_state = .empty;
            a.audio_playing_id.set("");
            a.audio_position_ms = 0;
            a.audio_duration_ms = 0;
            setStatus(a, "Windows cannot play this audio format");
            if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        }
        return;
    }
    const mapped: @TypeOf(a.audio_state) = switch (state) {
        .ready => .ready,
        .playing => .playing,
        .paused => .paused,
        .ended => .ready,
        .idle => .empty,
    };
    var changed = false;
    if (mapped != a.audio_state) {
        a.audio_state = mapped;
        changed = true;
        if (mapped == .empty) {
            a.audio_playing_id.set("");
            a.audio_position_ms = 0;
            a.audio_duration_ms = 0;
        }
    }
    const duration = player.durationMs();
    if (a.audio_resume_ms > 0 and duration > 0) {
        player.seek(a.audio_resume_ms);
        a.audio_resume_ms = 0;
    }
    const position = player.positionMs();
    if (duration > 0 and duration != a.audio_duration_ms) {
        a.audio_duration_ms = duration;
        changed = true;
    }
    if (position != a.audio_position_ms) {
        a.audio_position_ms = position;
        changed = true;
    }
    if (changed) {
        if (a.canvas) |canvas| {
            for (a.messages[0..a.message_count]) |*message| {
                if (!isAudio(message)) continue;
                const dirty = message.bubble_hit;
                if (dirty.right > dirty.left and dirty.bottom > dirty.top) _ = win.InvalidateRect(canvas, &dirty, win.FALSE);
            }
        }
    }
}

fn formatClock(buffer: []u8, ms: i64) []const u8 {
    const seconds = @divTrunc(ms, 1000);
    return std.fmt.bufPrint(buffer, "{d}:{d:0>2}", .{ @divTrunc(seconds, 60), @mod(seconds, 60) }) catch "0:00";
}

fn isGif(message: *const Message) bool {
    return std.ascii.eqlIgnoreCase(message.media_type.slice(), "gif") or
        std.ascii.eqlIgnoreCase(message.mime_type.slice(), "image/gif");
}

fn isVideoGif(message: *const Message) bool {
    const mime = message.mime_type.slice();
    return std.ascii.eqlIgnoreCase(message.media_type.slice(), "gif") and
        mime.len >= 6 and std.ascii.eqlIgnoreCase(mime[0..6], "video/");
}

fn decodeGifVideoFrame(message: *Message) bool {
    if (message.gif_reader == null or message.bitmap_width <= 0 or message.bitmap_height <= 0) return false;
    var actual_stream: win.DWORD = 0;
    var flags: win.DWORD = 0;
    var timestamp: win.LONGLONG = 0;
    var sample: ?*win.IMFSample = null;
    const hr = message.gif_reader.*.lpVtbl.*.ReadSample.?(message.gif_reader, win.MF_SOURCE_READER_FIRST_VIDEO_STREAM, 0, &actual_stream, &flags, &timestamp, &sample);
    if (hr < 0 or (flags & win.MF_SOURCE_READERF_ENDOFSTREAM) != 0) {
        if (sample) |value| _ = value.*.lpVtbl.*.Release.?(value);
        _ = message.gif_reader.*.lpVtbl.*.Release.?(message.gif_reader);
        message.gif_reader = null;
        return false;
    }
    const media_sample = sample orelse return false;
    defer _ = media_sample.*.lpVtbl.*.Release.?(media_sample);
    var buffer: ?*win.IMFMediaBuffer = null;
    if (media_sample.*.lpVtbl.*.ConvertToContiguousBuffer.?(media_sample, &buffer) < 0 or buffer == null) return false;
    defer _ = buffer.?.*.lpVtbl.*.Release.?(buffer);
    const row_bytes: usize = @intCast(message.bitmap_width * 4);
    const required: usize = row_bytes * @as(usize, @intCast(message.bitmap_height));
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = message.bitmap_width;
    info.bmiHeader.biHeight = -message.bitmap_height;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return false;
    if (bits == null) {
        _ = win.DeleteObject(bitmap);
        return false;
    }
    errdefer _ = win.DeleteObject(bitmap);
    const destination: [*]u8 = @ptrCast(bits.?);

    var two_d: [*c]win.IMF2DBuffer = null;
    if (buffer.?.*.lpVtbl.*.QueryInterface.?(buffer.?, &win.IID_IMF2DBuffer, @ptrCast(&two_d)) >= 0 and two_d != null) {
        defer _ = two_d.*.lpVtbl.*.Release.?(two_d);
        var scanline: [*c]u8 = null;
        var pitch: win.LONG = 0;
        if (two_d.*.lpVtbl.*.Lock2D.?(two_d, &scanline, &pitch) < 0) return false;
        defer _ = two_d.*.lpVtbl.*.Unlock2D.?(two_d);
        var row: usize = 0;
        while (row < @as(usize, @intCast(message.bitmap_height))) : (row += 1) {
            const source_address: isize = @as(isize, @intCast(@intFromPtr(scanline))) + @as(isize, pitch) * @as(isize, @intCast(row));
            const source: [*]const u8 = @ptrFromInt(@as(usize, @intCast(source_address)));
            @memcpy(destination[row * row_bytes ..][0..row_bytes], source[0..row_bytes]);
        }
    } else {
        var bytes: [*c]u8 = null;
        var maximum: win.DWORD = 0;
        var length: win.DWORD = 0;
        if (buffer.?.*.lpVtbl.*.Lock.?(buffer.?, &bytes, &maximum, &length) < 0) return false;
        defer _ = buffer.?.*.lpVtbl.*.Unlock.?(buffer.?);
        if (length < required) return false;
        const source_stride: usize = @intCast(length / @as(u32, @intCast(message.bitmap_height)));
        var row: usize = 0;
        while (row < @as(usize, @intCast(message.bitmap_height))) : (row += 1) {
            @memcpy(destination[row * row_bytes ..][0..row_bytes], bytes[row * source_stride ..][0..row_bytes]);
        }
    }
    message.bitmap = bitmap;
    noteMessageBitmap(message);
    return true;
}

fn ensureGifVideoBitmap(message: *Message) void {
    if (message.local_path.len == 0) return;
    if (message.gif_reader == null) {
        if (!mf_lazy.ensureStarted()) return;
        var attributes: ?*win.IMFAttributes = null;
        if (mf_lazy.createAttributes.?(&attributes, 1) < 0 or attributes == null) return;
        defer _ = attributes.?.*.lpVtbl.*.Release.?(attributes);
        _ = attributes.?.*.lpVtbl.*.SetUINT32.?(attributes.?, &win.MF_SOURCE_READER_ENABLE_ADVANCED_VIDEO_PROCESSING, 1);
        var reader: [*c]win.IMFSourceReader = null;
        if (mf_lazy.createSourceReaderFromURL.?(message.local_path.ptr(), attributes, &reader) < 0 or reader == null) return;
        message.gif_reader = reader;

        var native_type: ?*win.IMFMediaType = null;
        var source_width: win.UINT32 = 0;
        var source_height: win.UINT32 = 0;
        if (reader.*.lpVtbl.*.GetNativeMediaType.?(reader, win.MF_SOURCE_READER_FIRST_VIDEO_STREAM, 0, &native_type) >= 0 and native_type != null) {
            var packed_size: win.UINT64 = 0;
            if (native_type.?.*.lpVtbl.*.GetUINT64.?(native_type.?, &win.MF_MT_FRAME_SIZE, &packed_size) >= 0) {
                source_width = @truncate(packed_size >> 32);
                source_height = @truncate(packed_size);
            }
            _ = native_type.?.*.lpVtbl.*.Release.?(native_type);
        }
        if (source_width == 0 or source_height == 0) {
            source_width = 320;
            source_height = 180;
        }
        var target_width: win.UINT32 = @min(source_width, 420);
        var target_height: win.UINT32 = @intCast(@max(1, @divTrunc(@as(u64, source_height) * target_width, source_width)));
        if (target_height > 250) {
            target_height = 250;
            target_width = @intCast(@max(1, @divTrunc(@as(u64, source_width) * target_height, source_height)));
        }
        var output_type: ?*win.IMFMediaType = null;
        if (mf_lazy.createMediaType.?(&output_type) < 0 or output_type == null) return;
        defer _ = output_type.?.*.lpVtbl.*.Release.?(output_type);
        _ = output_type.?.*.lpVtbl.*.SetGUID.?(output_type.?, &win.MF_MT_MAJOR_TYPE, &win.MFMediaType_Video);
        _ = output_type.?.*.lpVtbl.*.SetGUID.?(output_type.?, &win.MF_MT_SUBTYPE, &win.MFVideoFormat_RGB32);
        _ = output_type.?.*.lpVtbl.*.SetUINT64.?(output_type.?, &win.MF_MT_FRAME_SIZE, (@as(u64, target_width) << 32) | target_height);
        if (reader.*.lpVtbl.*.SetCurrentMediaType.?(reader, win.MF_SOURCE_READER_FIRST_VIDEO_STREAM, null, output_type.?) < 0) return;
        var effective_type: ?*win.IMFMediaType = null;
        if (reader.*.lpVtbl.*.GetCurrentMediaType.?(reader, win.MF_SOURCE_READER_FIRST_VIDEO_STREAM, &effective_type) >= 0 and effective_type != null) {
            var packed_size: win.UINT64 = 0;
            if (effective_type.?.*.lpVtbl.*.GetUINT64.?(effective_type.?, &win.MF_MT_FRAME_SIZE, &packed_size) >= 0) {
                const actual_width: win.UINT32 = @truncate(packed_size >> 32);
                const actual_height: win.UINT32 = @truncate(packed_size);
                if (actual_width > 0 and actual_height > 0) {
                    target_width = actual_width;
                    target_height = actual_height;
                }
            }
            _ = effective_type.?.*.lpVtbl.*.Release.?(effective_type);
        }
        message.bitmap_width = @intCast(target_width);
        message.bitmap_height = @intCast(target_height);
        message.gif_frame_count = 2;
    }
    _ = decodeGifVideoFrame(message);
}

fn ensureVideoBitmap(message: *Message) void {
    if (!shell_lazy.ensureShell32()) return;
    var factory: [*c]win.IShellItemImageFactory = null;
    if (shell_lazy.shCreateItemFromParsingName.?(message.local_path.ptr(), null, &win.IID_IShellItemImageFactory, @ptrCast(&factory)) < 0 or factory == null) return;
    defer _ = factory.*.lpVtbl.*.Release.?(factory);
    var bitmap: win.HBITMAP = null;
    const requested = win.SIZE{ .cx = 420, .cy = 250 };
    if (factory.*.lpVtbl.*.GetImage.?(factory, requested, win.SIIGBF_THUMBNAILONLY | win.SIIGBF_BIGGERSIZEOK, &bitmap) < 0 or bitmap == null) return;
    var details = std.mem.zeroes(win.BITMAP);
    if (win.GetObjectW(bitmap, @sizeOf(win.BITMAP), &details) == 0 or details.bmWidth <= 0 or details.bmHeight <= 0) {
        _ = win.DeleteObject(bitmap);
        return;
    }
    message.bitmap = bitmap;
    message.bitmap_width = details.bmWidth;
    message.bitmap_height = details.bmHeight;
    noteMessageBitmap(message);
}

fn ensureBitmap(a: *App, message: *Message) void {
    if (message.bitmap != null) {
        noteMessageBitmap(message);
        return;
    }
    if (message.local_path.len == 0) return;
    if (isVideoGif(message)) {
        ensureGifVideoBitmap(message);
        return;
    }
    if (isVideo(message)) {
        ensureVideoBitmap(message);
        return;
    }
    if (!isImage(message) or a.wic_factory == null) return;
    var decoder: [*c]win.IWICBitmapDecoder = null;
    const decoder_hr = a.wic_factory.*.lpVtbl.*.CreateDecoderFromFilename.?(
        a.wic_factory,
        message.local_path.ptr(),
        null,
        win.GENERIC_READ,
        win.WICDecodeMetadataCacheOnLoad,
        &decoder,
    );
    if (decoder_hr < 0 or decoder == null) {
        ensureWebPBitmap(a, message);
        return;
    }
    defer _ = decoder.*.lpVtbl.*.Release.?(decoder);

    var frame_count: win.UINT = 0;
    if (decoder.*.lpVtbl.*.GetFrameCount.?(decoder, &frame_count) < 0 or frame_count == 0) return;
    message.gif_frame_count = if (isGif(message)) frame_count else 1;
    if (message.gif_frame_index >= message.gif_frame_count) message.gif_frame_index = 0;
    var frame: [*c]win.IWICBitmapFrameDecode = null;
    if (decoder.*.lpVtbl.*.GetFrame.?(decoder, message.gif_frame_index, &frame) < 0 or frame == null) return;
    defer _ = frame.*.lpVtbl.*.Release.?(frame);
    var source_width: win.UINT = 0;
    var source_height: win.UINT = 0;
    if (frame.*.lpVtbl.*.GetSize.?(@ptrCast(frame), &source_width, &source_height) < 0 or source_width == 0 or source_height == 0) return;

    fillBitmapFromSource(a, message, @ptrCast(frame), source_width, source_height);
}

fn ensureWebPBitmap(a: *App, message: *Message) void {
    const path_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.local_path.slice()) catch return;
    defer a.allocator.free(path_utf8);
    const data = readFileWin(a.allocator, path_utf8, 32 * 1024 * 1024) orelse return;
    defer a.allocator.free(data);
    if (!webp_detect.isWebPBytes(data)) return;
    var features: webp.WebPBitstreamFeatures = undefined;
    if (webp.WebPGetFeatures(data.ptr, data.len, &features) != webp.VP8_STATUS_OK) return;

    if (features.has_animation == 0) {
        const fit = webp_detect.fitBox(@intCast(features.width), @intCast(features.height), 420, 250);
        var config: webp.WebPDecoderConfig = undefined;
        if (webp.WebPInitDecoderConfig(&config) == 0) return;
        config.options.use_scaling = 1;
        config.options.scaled_width = @intCast(fit.width);
        config.options.scaled_height = @intCast(fit.height);
        config.output.colorspace = webp.MODE_RGBA;
        const status = webp.WebPDecode(data.ptr, data.len, &config);
        if (status == webp.VP8_STATUS_OK and config.output.u.RGBA.stride == @as(c_int, @intCast(fit.width * 4))) {
            var wic_bitmap: [*c]win.IWICBitmap = null;
            const create_hr = a.wic_factory.*.lpVtbl.*.CreateBitmapFromMemory.?(
                a.wic_factory,
                fit.width,
                fit.height,
                &win.GUID_WICPixelFormat32bppRGBA,
                fit.width * 4,
                fit.width * fit.height * 4,
                config.output.u.RGBA.rgba,
                &wic_bitmap,
            );
            webp.WebPFreeDecBuffer(&config.output);
            if (create_hr >= 0 and wic_bitmap != null) {
                defer _ = wic_bitmap.*.lpVtbl.*.Release.?(wic_bitmap);
                fillDibFromWic(a, message, @ptrCast(wic_bitmap), fit.width, fit.height);
                return;
            }
        } else webp.WebPFreeDecBuffer(&config.output);
    }

    const max_decode_pixels: u64 = message_bitmap_budget_bytes / 4;
    if (!webp_detect.decodeAllowed(features.width, features.height, max_decode_pixels)) return;
    var width: c_int = 0;
    var height: c_int = 0;
    var pixels = webp.WebPDecodeRGBA(data.ptr, data.len, &width, &height);
    if (pixels == null) {
        if (webp_detect.firstAnimationFrame(data)) |frame| {
            if (webp.WebPGetInfo(frame.ptr, frame.len, &width, &height) == 0 or
                !webp_detect.decodeAllowed(width, height, max_decode_pixels)) return;
            pixels = webp.WebPDecodeRGBA(frame.ptr, frame.len, &width, &height);
        }
    }
    defer webp.WebPFree(pixels);
    if (pixels == null or width <= 0 or height <= 0) return;

    var wic_bitmap: [*c]win.IWICBitmap = null;
    const create_hr = a.wic_factory.*.lpVtbl.*.CreateBitmapFromMemory.?(
        a.wic_factory,
        @intCast(width),
        @intCast(height),
        &win.GUID_WICPixelFormat32bppRGBA,
        @intCast(@as(u32, @intCast(width)) * 4),
        @intCast(@as(u32, @intCast(width)) * @as(u32, @intCast(height)) * 4),
        pixels,
        &wic_bitmap,
    );
    if (create_hr < 0 or wic_bitmap == null) return;
    defer _ = wic_bitmap.*.lpVtbl.*.Release.?(wic_bitmap);
    fillDibFromWic(a, message, @ptrCast(wic_bitmap), @intCast(width), @intCast(height));
}

fn fillDibFromWic(a: *App, message: *Message, source: *win.IWICBitmapSource, source_width: win.UINT, source_height: win.UINT) void {
    const fit = webp_detect.fitBox(source_width, source_height, 420, 250);
    const target_width: win.UINT = fit.width;
    const target_height: win.UINT = fit.height;

    var converter: [*c]win.IWICFormatConverter = null;
    if (a.wic_factory.*.lpVtbl.*.CreateFormatConverter.?(a.wic_factory, &converter) < 0 or converter == null) return;
    defer _ = converter.*.lpVtbl.*.Release.?(converter);
    if (converter.*.lpVtbl.*.Initialize.?(
        converter,
        source,
        &win.GUID_WICPixelFormat32bppPBGRA,
        win.WICBitmapDitherTypeNone,
        null,
        0,
        win.WICBitmapPaletteTypeCustom,
    ) < 0) return;

    if (source_width == target_width and source_height == target_height) {
        fillDibFromSource(a, message, @ptrCast(converter), target_width, target_height);
        return;
    }

    var scaler: [*c]win.IWICBitmapScaler = null;
    if (a.wic_factory.*.lpVtbl.*.CreateBitmapScaler.?(a.wic_factory, &scaler) < 0 or scaler == null) return;
    defer _ = scaler.*.lpVtbl.*.Release.?(scaler);
    if (scaler.*.lpVtbl.*.Initialize.?(scaler, @ptrCast(converter), target_width, target_height, win.WICBitmapInterpolationModeFant) < 0) return;

    fillDibFromSource(a, message, @ptrCast(scaler), target_width, target_height);
}

fn fillBitmapFromSource(a: *App, message: *Message, source: *win.IWICBitmapSource, source_width: win.UINT, source_height: win.UINT) void {
    const fit = webp_detect.fitBox(source_width, source_height, 420, 250);
    const target_width: win.UINT = fit.width;
    const target_height: win.UINT = fit.height;

    var converter: [*c]win.IWICFormatConverter = null;
    if (a.wic_factory.*.lpVtbl.*.CreateFormatConverter.?(a.wic_factory, &converter) < 0 or converter == null) return;
    defer _ = converter.*.lpVtbl.*.Release.?(converter);
    if (converter.*.lpVtbl.*.Initialize.?(
        converter,
        source,
        &win.GUID_WICPixelFormat32bppPBGRA,
        win.WICBitmapDitherTypeNone,
        null,
        0,
        win.WICBitmapPaletteTypeCustom,
    ) < 0) return;

    if (source_width == target_width and source_height == target_height) {
        fillDibFromSource(a, message, @ptrCast(converter), target_width, target_height);
        return;
    }

    var scaler: [*c]win.IWICBitmapScaler = null;
    if (a.wic_factory.*.lpVtbl.*.CreateBitmapScaler.?(a.wic_factory, &scaler) < 0 or scaler == null) return;
    defer _ = scaler.*.lpVtbl.*.Release.?(scaler);
    if (scaler.*.lpVtbl.*.Initialize.?(scaler, @ptrCast(converter), target_width, target_height, win.WICBitmapInterpolationModeFant) < 0) return;

    fillDibFromSource(a, message, @ptrCast(scaler), target_width, target_height);
}

fn fillDibFromSource(a: *App, message: *Message, source: *win.IWICBitmapSource, target_width: win.UINT, target_height: win.UINT) void {
    const stride: win.UINT = target_width * 4;
    const byte_count: win.UINT = stride * target_height;
    const pixels = a.allocator.alloc(u8, byte_count) catch return;
    defer a.allocator.free(pixels);
    if (source.*.lpVtbl.*.CopyPixels.?(source, null, stride, byte_count, pixels.ptr) < 0) return;

    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = @intCast(target_width);
    info.bmiHeader.biHeight = -@as(win.LONG, @intCast(target_height));
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return;
    if (bits == null) {
        _ = win.DeleteObject(bitmap);
        return;
    }
    const destination: [*]u8 = @ptrCast(bits.?);
    @memcpy(destination[0..byte_count], pixels);
    message.bitmap = bitmap;
    message.bitmap_width = @intCast(target_width);
    message.bitmap_height = @intCast(target_height);
    noteMessageBitmap(message);
}

fn nowUnixSeconds() i64 {
    var ft: win.FILETIME = undefined;
    win.GetSystemTimeAsFileTime(&ft);
    return filetimeToUnixSeconds(ft);
}

fn filetimeToUnixSeconds(ft: win.FILETIME) i64 {
    const q: i64 = (@as(i64, ft.dwHighDateTime) << 32) | ft.dwLowDateTime;
    return @divTrunc(q - 116444736000000000, 10_000_000);
}

fn startMediaDownload(a: *App, chat_jid: []const u8, message_id: []const u8) bool {
    if (hubConfigured(a)) {
        hubTransport(a).downloadMedia(chat_jid, message_id);
        return mediaDownloading(a, chat_jid, message_id);
    }
    if (a.send_child != null or a.pending_send_count > 0 or a.read_child != null or
        a.archive_child != null or avatarBusy(a)) return false;
    if (mediaDownloading(a, chat_jid, message_id)) return false;
    const slot = freeMediaSlot(a) orelse return false;
    slot.jid.set(chat_jid);
    slot.id.set(message_id);
    if (a.sync_child != null or a.media_burst_files == 0) {
        a.media_burst_started_ms = win.GetTickCount64();
        a.media_burst_files = 0;
    }
    stopSync(a, "media");
    const args = [_][]const u8{ a.wacli_path, "--json", "--lock-wait", "10s", "--timeout", "60s", "media", "download", "--chat", slot.jid.slice(), "--id", slot.id.slice() };
    const child = child_process.spawn(a.io, .{
        .argv = &args,
        .stdin = .ignore,
        .stdout = .ignore,
        .stderr = .ignore,
        .create_no_window = true,
    }) catch {
        slot.jid.set("");
        slot.id.set("");
        noteMediaFailure(a, chat_jid, message_id);
        setStatus(a, "Could not start attachment download");
        if (!mediaBusy(a)) startSync(a);
        return false;
    };
    slot.child = child;
    slot.started_ms = win.GetTickCount64();
    a.media_burst_files += 1;
    return true;
}

fn downloadMedia(a: *App, message_index: usize, automatic: bool) bool {
    if (message_index >= a.message_count or a.selected_chat >= a.chat_count) return false;
    if (!chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]))) return false;
    const message = &a.messages[message_index];
    if (message.media_type.len == 0 or message.id.len == 0) return false;
    if (!voice_sent.needsDownload(message.local_path.len > 0)) return false;
    if (automatic and media_drain.oversized(message.media_size)) return false;
    const chat = &a.chats[a.selected_chat];
    if (!unifiedHub(a) and chat.provider != .whatsapp) return false;
    if (media_drain.wazi_135 and !automatic) {
        clearMediaFailure(a, chat.jid.slice(), message.id.slice());
        media_drain.forgetAttempt(&a.media_attempts, &a.media_attempt_count, played.Set.pairKey(chat.jid.slice(), message.id.slice()));
    }
    if (mediaDownloading(a, a.chats[a.selected_chat].jid.slice(), message.id.slice())) return false;
    if (freeMediaSlot(a) == null or a.send_child != null or a.pending_send_count > 0 or
        a.read_child != null or a.archive_child != null or avatarBusy(a))
    {
        if (!automatic) {
            a.pending_download_jid.set(chat.jid.slice());
            a.pending_download_id.set(message.id.slice());
            setStatus(a, "Attachment download queued");
            return true;
        }
        return false;
    }
    if (!startMediaDownload(a, chat.jid.slice(), message.id.slice())) return false;
    setStatus(a, if (automatic) "Downloading media..." else "Downloading attachment...");
    if (a.hwnd) |hwnd| _ = win.UpdateWindow(hwnd);
    return true;
}

fn mediaAttempted(a: *const App, jid: []const u8, id: []const u8) bool {
    const hash = played.Set.pairKey(jid, id);
    for (a.media_attempts[0..a.media_attempt_count]) |attempt| if (attempt == hash) return true;
    return false;
}

fn markMediaAttempted(a: *App, jid: []const u8, id: []const u8) void {
    const hash = played.Set.pairKey(jid, id);
    if (a.media_attempt_count >= a.media_attempts.len) a.media_attempt_count = 0;
    a.media_attempts[a.media_attempt_count] = hash;
    a.media_attempt_count += 1;
}

fn mediaUnavailable(a: *const App, jid: []const u8, id: []const u8) bool {
    return std.mem.indexOfScalar(u64, a.media_unavailable[0..a.media_unavailable_count], played.Set.pairKey(jid, id)) != null;
}

fn markMediaUnavailable(a: *App, jid: []const u8, id: []const u8) void {
    markMediaAttempted(a, jid, id);
    if (mediaUnavailable(a, jid, id)) return;
    if (a.media_unavailable_count >= a.media_unavailable.len) a.media_unavailable_count = 0;
    a.media_unavailable[a.media_unavailable_count] = played.Set.pairKey(jid, id);
    a.media_unavailable_count += 1;
}

fn clearMediaFailure(a: *App, jid: []const u8, id: []const u8) void {
    const hash = played.Set.pairKey(jid, id);
    media_drain.forgetAttempt(&a.media_unavailable, &a.media_unavailable_count, hash);
    for (&a.media_failures) |*entry| {
        if (entry.hash == hash) {
            entry.hash = 0;
            entry.count = 0;
            return;
        }
    }
}

fn noteMediaFailure(a: *App, jid: []const u8, id: []const u8) void {
    const hash = played.Set.pairKey(jid, id);
    var count: u8 = 0;
    var matched: ?*MediaFailure = null;
    for (&a.media_failures) |*entry| {
        if (entry.hash == hash) {
            matched = entry;
            count = entry.count;
            break;
        }
    }
    count += 1;
    const retry_after_ms = win.GetTickCount64() + 30_000;
    if (count >= max_media_retries) {
        if (matched) |entry| {
            entry.hash = 0;
            entry.count = 0;
        }
        markMediaUnavailable(a, jid, id);
        return;
    }
    if (matched) |entry| {
        entry.count = count;
        entry.retry_after_ms = retry_after_ms;
        return;
    }
    for (&a.media_failures) |*entry| {
        if (entry.hash == 0 and entry.count == 0) {
            entry.hash = hash;
            entry.count = count;
            entry.retry_after_ms = retry_after_ms;
            return;
        }
    }
    markMediaUnavailable(a, jid, id);
}

fn isDownloadableMedia(message: *const Message) bool {
    return !message.revoked and media_drain.downloadable(message.media_type.slice());
}

fn autoDownloadNextMedia(a: *App) bool {
    if (freeMediaSlot(a) == null) return false;
    const now_ms = win.GetTickCount64();
    if (a.sync_child == null and a.media_burst_files > 0 and !media_drain.mayContinueBurst(a.media_burst_files, a.media_burst_started_ms, now_ms)) return false;
    if (a.sync_child != null and (now_ms < a.media_resume_after_ms or a.read_child != null or
        !sync_gate.gapElapsed(a.last_sync_stop_ms, win.GetTickCount64(), sync_gate.media_stop_gap_ms))) return false;
    if (a.selected_chat >= a.chat_count or (!unifiedHub(a) and a.chats[a.selected_chat].provider != .whatsapp)) return false;
    if (!chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]))) return false;
    const pick = nextOpenMediaCandidate(a, now_ms) orelse return false;
    return downloadMedia(a, pick, true);
}

fn nextOpenMediaCandidate(a: *App, now_ms: u64) ?usize {
    if (a.selected_chat >= a.chat_count or (!unifiedHub(a) and a.chats[a.selected_chat].provider != .whatsapp)) return null;
    if (!chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]))) return null;
    const chat_jid = a.chats[a.selected_chat].jid.slice();
    var candidates: [max_messages]media_drain.Candidate = undefined;
    var count: usize = 0;
    var index = a.message_count;
    while (index > 0) {
        index -= 1;
        const message = &a.messages[index];
        const id = message.id.slice();
        var retry_after_ms: u64 = 0;
        const hash = played.Set.pairKey(chat_jid, id);
        for (a.media_failures) |failure| {
            if (failure.hash == hash) retry_after_ms = failure.retry_after_ms;
        }
        candidates[count] = .{
            .index = index,
            .downloadable = isDownloadableMedia(message),
            .has_id = id.len > 0,
            .has_local_path = message.local_path.len > 0,
            .in_flight = mediaDownloading(a, chat_jid, id),
            .attempted = mediaAttempted(a, chat_jid, id),
            .retry_after_ms = retry_after_ms,
            .size_bytes = message.media_size,
            .whatsapp_store = true,
        };
        count += 1;
    }
    return media_drain.selectNext(candidates[0..count], now_ms);
}

fn drainMediaDownloads(a: *App) void {
    retryPendingDownload(a);
    var steps: usize = 0;
    var started = true;
    while (media_drain.mayDrainStep(steps, started) and freeMediaSlot(a) != null) {
        started = autoDownloadNextMedia(a);
        if (!started) started = autoDownloadBackgroundMedia(a);
        steps += 1;
    }
}

fn observeBackgroundMediaChats(a: *App, rows: []const std.json.Value) void {
    if (a.background_media_count > 0 and !std.mem.eql(u8, a.background_media_chats[0].account.slice(), a.cache_tag.slice())) a.background_media_count = 0;
    for (rows) |row| {
        const object = switch (row) {
            .object => |o| o,
            else => continue,
        };
        var chat = BackgroundMediaChat{ .account = a.cache_tag };
        chat.jid.set(getString(object, "jid"));
        chat.timestamp.set(getString(object, "last_message_ts"));
        if (chat.jid.len == 0 or chat.timestamp.len == 0) continue;
        if (chat_key.indexOf(BackgroundMediaChat, a.background_media_chats[0..a.background_media_count], chat_key.of(&chat))) |index| {
            a.background_media_chats[index].timestamp = chat.timestamp;
        } else {
            var index: usize = 0;
            if (a.background_media_count < a.background_media_chats.len) {
                index = a.background_media_count;
                a.background_media_count += 1;
            } else {
                for (a.background_media_chats[0..a.background_media_count], 0..) |*previous, i| {
                    if (std.mem.order(u8, previous.timestamp.slice(), a.background_media_chats[index].timestamp.slice()) == .lt) index = i;
                }
            }
            a.background_media_chats[index] = chat;
        }
    }
}

fn enqueueBackgroundMedia(a: *App) bool {
    const batch = &a.background_media;
    var job = WacliJob{ .account = batch.account, .kind = .background_media, .jid = batch.jid, .extra = batch.timestamp };
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "messages", "list", "--chat", batch.jid.slice(), "--limit", if (batch.phase == .caching) "80" else "16" });
    return wacliEnqueue(a, job, false);
}

fn applyBackgroundMedia(a: *App, result: *const WacliResult) void {
    const batch = &a.background_media;
    if (!chat_key.Key.eql(chat_key.of(batch), chat_key.of(result)) or !std.mem.eql(u8, batch.timestamp.slice(), result.extra.slice())) return;
    if (a.selected_chat < a.chat_count and chat_key.Key.eql(chat_key.of(batch), chat_key.of(&a.chats[a.selected_chat]))) {
        batch.* = .{};
        return;
    }
    batch.retry_after_ms = win.GetTickCount64() + 30_000;
    batch.read_failures += 1;
    defer {
        if (media_drain.backgroundReadExhausted(batch.read_failures)) {
            if (chat_key.indexOf(BackgroundMediaChat, a.background_media_chats[0..a.background_media_count], chat_key.of(batch))) |index| {
                a.background_media_chats[index].swept = batch.timestamp;
            }
            batch.* = .{};
        }
    }
    if (!result.ok) return;
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, result.data, .{}) catch return;
    defer parsed.deinit();
    if (parsed.value != .object) return;
    const data = parsed.value.object.get("data") orelse return;
    if (data != .object) return;
    const messages = data.object.get("messages") orelse return;
    if (messages != .array) return;
    batch.read_failures = 0;
    if (batch.phase == .caching) {
        msgCacheStore(a, chat_key.of(result), result.data);
        if (chat_key.indexOf(BackgroundMediaChat, a.background_media_chats[0..a.background_media_count], chat_key.of(batch))) |index| {
            a.background_media_chats[index].swept = batch.timestamp;
        }
        batch.* = .{};
        return;
    }
    batch.count = 0;
    for (messages.array.items[0..@min(messages.array.items.len, background_media_limit)]) |row| {
        const object = switch (row) {
            .object => |o| o,
            else => continue,
        };
        const id = getString(object, "MsgID");
        const path = getString(object, "LocalPath");
        const size = media_drain.sizeFromJson(object);
        const candidate = media_drain.Candidate{
            .index = 0,
            .downloadable = !getBool(object, "Revoked") and media_drain.downloadable(getString(object, "MediaType")),
            .has_id = id.len > 0,
            .has_local_path = path.len > 0 and fileExistsUtf8(path),
            .size_bytes = size,
            .whatsapp_store = true,
        };
        if (media_drain.backgroundSelectNext(&.{candidate}, win.GetTickCount64()) == null) continue;
        batch.ids[batch.count].set(id);
        batch.sizes[batch.count] = size;
        batch.count += 1;
    }
    batch.phase = .downloading;
    drainMediaDownloads(a);
}

fn autoDownloadBackgroundMedia(a: *App) bool {
    const now_ms = win.GetTickCount64();
    if (a.cache_tag.len == 0 or a.startup_probe_pending or a.sync_logged_out or a.accounts_maintenance) return false;
    if (!media_drain.backgroundMayStart(if (mediaBusy(a)) 1 else 0, nextOpenMediaCandidate(a, now_ms) != null, a.media_burst_files, a.media_burst_started_ms, now_ms, a.sync_child != null, a.media_resume_after_ms, a.last_sync_stop_ms)) return false;
    if (wacliPendingGet(a, .background_media) > 0 or wacliPendingGet(a, .messages) > 0) return false;
    if (a.selected_chat < a.chat_count and a.chats[a.selected_chat].provider == .whatsapp and
        !chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]))) return false;
    const batch = &a.background_media;
    if (batch.phase != .idle and (!std.mem.eql(u8, batch.account.slice(), a.cache_tag.slice()) or
        (a.selected_chat < a.chat_count and chat_key.Key.eql(chat_key.of(batch), chat_key.of(&a.chats[a.selected_chat]))))) batch.* = .{};
    if (batch.phase == .idle) {
        var pick: ?usize = null;
        const now_unix = nowUnixSeconds();
        for (a.background_media_chats[0..a.background_media_count], 0..) |*chat, i| {
            if (!std.mem.eql(u8, chat.account.slice(), a.cache_tag.slice())) continue;
            const open = a.selected_chat < a.chat_count and chat_key.Key.eql(chat_key.of(chat), chat_key.of(&a.chats[a.selected_chat]));
            if (!media_drain.backgroundChatDue(chat.timestamp.slice(), chat.swept.slice(), open, now_unix, media_cache_eviction_days)) continue;
            if (pick == null or std.mem.order(u8, chat.timestamp.slice(), a.background_media_chats[pick.?].timestamp.slice()) == .gt) pick = i;
        }
        const chat = &a.background_media_chats[pick orelse return false];
        batch.* = .{ .account = chat.account, .jid = chat.jid, .timestamp = chat.timestamp, .phase = .listing };
    }
    if (batch.phase == .downloading) {
        var candidates: [background_media_limit]media_drain.Candidate = undefined;
        for (batch.ids[0..batch.count], 0..) |*id, i| {
            const path = if (hubConfigured(a)) hubMediaPath(a, a.allocator, chat_key.of(batch), id.slice()) catch null else null;
            defer if (path) |cached| a.allocator.free(cached);
            var retry_after_ms: u64 = 0;
            const hash = played.Set.pairKey(batch.jid.slice(), id.slice());
            for (a.media_failures) |failure| {
                if (failure.hash == hash) retry_after_ms = failure.retry_after_ms;
            }
            candidates[i] = .{
                .index = i,
                .downloadable = true,
                .has_id = id.len > 0,
                .has_local_path = if (path) |cached| fileExistsUtf8(cached) else false,
                .size_bytes = batch.sizes[i],
                .whatsapp_store = true,
                .in_flight = mediaDownloading(a, batch.jid.slice(), id.slice()),
                .attempted = mediaAttempted(a, batch.jid.slice(), id.slice()),
                .retry_after_ms = retry_after_ms,
            };
        }
        if (media_drain.backgroundSelectNext(candidates[0..batch.count], now_ms)) |index| {
            return startMediaDownload(a, batch.jid.slice(), batch.ids[index].slice());
        }
        if (media_drain.backgroundSelectNext(candidates[0..batch.count], std.math.maxInt(u64)) != null) return false;
        batch.phase = .caching;
        batch.retry_after_ms = 0;
    }
    if (now_ms >= batch.retry_after_ms) {
        batch.retry_after_ms = now_ms + 30_000;
        _ = enqueueBackgroundMedia(a);
    }
    return false;
}

fn ensureAvatarSession(a: *App) ?*avatar.Session {
    if (a.avatar_session) |session| return session;
    a.avatar_session = avatar.Session.create(a.allocator, a.io) catch null;
    return a.avatar_session;
}

fn avatarBusy(a: *const App) bool {
    if (hubConfigured(a) and a.avatar_active_index != null) return true;
    if (a.avatar_batch_active) return true;
    return if (a.avatar_session) |session| session.state() == .working else false;
}

fn avatarBatchBlocked(a: *App) bool {
    return a.read_child != null or a.pending_read_count > 0 or mediaBusy(a) or
        a.send_child != null or a.pending_send_count > 0 or
        a.archive_child != null or a.pending_archive_count > 0 or
        wacliPendingGet(a, .reaction) > 0;
}

fn checkAvatarDownload(a: *App) void {
    if (hubConfigured(a)) {
        if (wacliPendingGet(a, .hub_avatar) == 0) requestNextAvatar(a);
        return;
    }
    const session = a.avatar_session orelse {
        requestNextAvatar(a);
        return;
    };
    const state = session.state();
    if (state == .working) return;
    if (state != .idle) {
        if (a.avatar_active_index) |target| switch (target) {
            .chat => |index| if (index < a.avatar_count) applyAvatarResult(a, &a.avatars[index], state),
            .participant => |index| if (index < a.participant_avatar_count) applyAvatarResult(a, &a.participant_avatars[index], state),
        };
        a.avatar_active_index = null;
        session.reset();
        if (state == .failed) a.avatar_retry_after_ms = win.GetTickCount64() + sync_gate.avatar_failure_backoff_ms;
        if (a.avatar_batch_active) {
            const continues = sync_gate.avatarBatchContinues(a.avatar_batch_fetched, a.avatar_batch_started_ms, win.GetTickCount64(), state == .failed) and
                !avatarBatchBlocked(a);
            const next = if (continues) nextAvatarTarget(a) else null;
            if (next == null or !startAvatarFetch(a, next.?)) endAvatarBatch(a);
        } else startSync(a);
        if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
        return;
    }
    if (a.avatar_batch_active) endAvatarBatch(a);
    requestNextAvatar(a);
}

fn avatarWanted(entry: *const AvatarEntry) bool {
    if (entry.path.len == 0) return false;
    return entry.status == .unknown or (entry.status == .ready and entry.refresh);
}

fn nextAvatarTarget(a: *App) ?AvatarTarget {
    if (a.selected_chat < a.chat_count and hub.chatAvatarEnabled(a.chats[a.selected_chat].provider, unifiedHub(a), hub.igsh_696_telegram_avatars)) {
        if (avatarForChat(a, a.chats[a.selected_chat].jid.slice())) |entry| {
            if (avatarWanted(entry)) return .{ .chat = avatarIndex(a, entry) };
        }
    }
    for (a.chats[0..a.chat_count]) |*chat| {
        const entry = if (hub.chatAvatarEnabled(chat.provider, unifiedHub(a), hub.igsh_696_telegram_avatars))
            avatarForChat(a, chat.jid.slice()) orelse continue
        else if (hub.igsh_604_workspace_icons and unifiedHub(a) and chat.provider == .slack) blk: {
            const key = hub.workspaceAvatarKey(chat.jid.slice()) orelse continue;
            const workspace_entry = avatarForChat(a, key) orelse continue;
            workspace_entry.workspace_icon = true;
            break :blk workspace_entry;
        } else continue;
        if (avatarWanted(entry)) return .{ .chat = avatarIndex(a, entry) };
    }
    for (a.avatars[0..a.avatar_count], 0..) |*entry, index| {
        if (avatarWanted(entry)) return .{ .chat = index };
    }
    for (a.participant_avatars[0..a.participant_avatar_count], 0..) |*entry, index| {
        if (avatarWanted(entry)) return .{ .participant = index };
    }
    return null;
}

fn avatarIndex(a: *const App, entry: *const AvatarEntry) usize {
    return (@intFromPtr(entry) - @intFromPtr(&a.avatars[0])) / @sizeOf(AvatarEntry);
}

fn requestNextAvatar(a: *App) void {
    if (a.sync_logged_out or a.pairing_process != null) return;
    if (avatarBusy(a) or avatarBatchBlocked(a)) return;
    const now = win.GetTickCount64();
    if (!(hub.igsh_604_workspace_icons and unifiedHub(a)) and !sync_gate.avatarBatchMayStart(a.last_sync_stop_ms, a.avatar_batch_end_ms, a.avatar_retry_after_ms, now)) return;
    const target = nextAvatarTarget(a) orelse return;
    stopSync(a, "avatars");
    a.avatar_batch_active = true;
    a.avatar_batch_fetched = 0;
    a.avatar_batch_started_ms = now;
    if (!startAvatarFetch(a, target)) endAvatarBatch(a);
}

fn endAvatarBatch(a: *App) void {
    a.avatar_batch_active = false;
    a.avatar_batch_end_ms = win.GetTickCount64();
    startSync(a);
}

fn startAvatarFetch(a: *App, target: AvatarTarget) bool {
    if (hubConfigured(a)) return startHubAvatar(a, target);
    const entry = switch (target) {
        .chat => |index| if (index < a.avatar_count) &a.avatars[index] else return false,
        .participant => |index| if (index < a.participant_avatar_count) &a.participant_avatars[index] else return false,
    };
    entry.refresh = false;
    const session = ensureAvatarSession(a) orelse return false;
    const destination = std.unicode.utf16LeToUtf8Alloc(a.allocator, entry.path.slice()) catch return false;
    defer a.allocator.free(destination);
    if (!session.start(a.wacli_path, entry.jid.slice(), destination)) {
        if (entry.status == .unknown) entry.status = .unavailable;
        session.reset();
        return false;
    }
    if (entry.status == .unknown) entry.status = .loading;
    a.avatar_active_index = target;
    a.avatar_batch_fetched += 1;
    return true;
}

fn applyAvatarResult(a: *App, entry: *AvatarEntry, state: avatar.State) void {
    if (entry.workspace_icon) {
        if (entry.bitmap) |old| _ = win.DeleteObject(old);
        entry.bitmap = null;
    }
    var buffer: [540]u16 = undefined;
    switch (state) {
        .ready => if (loadAvatarBitmap(a, entry.path.ptr())) |bitmap| {
            if (entry.bitmap) |old| _ = win.DeleteObject(old);
            entry.bitmap = bitmap;
            entry.status = .ready;
            if (avatarMarkerPath(entry, ".none", &buffer)) |path| _ = win.DeleteFileW(path);
            if (avatarMarkerPath(entry, ".fail", &buffer)) |path| _ = win.DeleteFileW(path);
        } else {
            if (avatarMarkerPath(entry, ".fail", &buffer)) |path| touchFileW(path);
            entry.status = if (entry.bitmap != null) .ready else .unavailable;
        },
        .unavailable => {
            if (entry.bitmap) |old| _ = win.DeleteObject(old);
            entry.bitmap = null;
            _ = win.DeleteFileW(entry.path.ptr());
            if (avatarMarkerPath(entry, ".none", &buffer)) |path| touchFileW(path);
            if (avatarMarkerPath(entry, ".fail", &buffer)) |path| _ = win.DeleteFileW(path);
            entry.status = .unavailable;
        },
        else => {
            if (avatarMarkerPath(entry, ".fail", &buffer)) |path| touchFileW(path);
            entry.status = if (entry.bitmap != null) .ready else .unavailable;
        },
    }
}

fn avatarMarkerPath(entry: *const AvatarEntry, suffix: []const u8, buffer: *[540]u16) ?[*:0]const u16 {
    const path = entry.path.slice();
    if (path.len == 0 or path.len + suffix.len >= buffer.len) return null;
    @memcpy(buffer[0..path.len], path);
    for (suffix, 0..) |char, index| buffer[path.len + index] = char;
    buffer[path.len + suffix.len] = 0;
    return @ptrCast(buffer);
}

fn fileStampSecs(path: [*:0]const u16) ?i64 {
    var attributes = std.mem.zeroes(win.WIN32_FILE_ATTRIBUTE_DATA);
    if (win.GetFileAttributesExW(path, win.GetFileExInfoStandard, &attributes) == 0) return null;
    return filetimeToUnixSeconds(attributes.ftLastWriteTime);
}

fn touchFileW(path: [*:0]const u16) void {
    _ = win.DeleteFileW(path);
    const handle = win.CreateFileW(path, win.GENERIC_WRITE, 0, null, win.CREATE_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    _ = win.CloseHandle(handle);
}

fn formatCachePath(a: *App, key: format_cache.Key) ?[]u8 {
    const name = format_cache.filename(a.allocator, key) catch return null;
    defer a.allocator.free(name);
    const dir_name = std.fmt.allocPrint(a.allocator, "voice-format-{s}", .{key.account}) catch return null;
    defer a.allocator.free(dir_name);
    const dir = messagesDirPath(a, dir_name) orelse return null;
    defer a.allocator.free(dir);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, dir) catch return null;
    defer a.allocator.free(wide);
    _ = win.CreateDirectoryW(wide.ptr, null);
    return std.fs.path.join(a.allocator, &.{ dir, name }) catch null;
}

fn saveFormattedCache(a: *App, key: format_cache.Key, text: []const u8) void {
    const path = formatCachePath(a, key) orelse return;
    defer a.allocator.free(path);
    const data = format_cache.envelope(a.allocator, key, text) catch return;
    defer a.allocator.free(data);
    _ = writeCacheFileAtomic(a, path, data);
}

fn loadTranscriptCache(a: *App, message: *Message) void {
    const key = format_cache.Key{
        .account = a.cache_tag.slice(),
        .chat = if (a.selected_chat < a.chat_count) a.chats[a.selected_chat].jid.slice() else "",
        .message = message.id.slice(),
    };
    if (formatCachePath(a, key)) |path| {
        defer a.allocator.free(path);
        if (readFileWin(a.allocator, path, format_cache.max_bytes)) |data| {
            defer a.allocator.free(data);
            if (format_cache.restore(a.allocator, message, data, key)) return;
        }
    }
    if (message.local_path.len == 0) return;
    const path_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.local_path.slice()) catch return;
    defer a.allocator.free(path_utf8);
    const cache_path = std.fmt.allocPrint(a.allocator, "{s}.txt", .{path_utf8}) catch return;
    defer a.allocator.free(cache_path);
    const contents = readFileWin(a.allocator, cache_path, format_cache.max_bytes) orelse return;
    defer a.allocator.free(contents);
    const trimmed = std.mem.trim(u8, contents, " \r\n\t");
    if (trimmed.len == 0) return;
    message.transcript.set(a.allocator, trimmed);
    message.transcript_state = .ready;
    if (format_request.looksFormatted(u8, trimmed)) saveFormattedCache(a, key, trimmed);
}

fn readFileWin(allocator: std.mem.Allocator, path_utf8: []const u8, max_bytes: usize) ?[]u8 {
    const wide = std.unicode.utf8ToUtf16LeAllocZ(allocator, path_utf8) catch return null;
    defer allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_READ, win.FILE_SHARE_READ, null, win.OPEN_EXISTING, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return null;
    defer _ = win.CloseHandle(handle);
    var size: win.LARGE_INTEGER = undefined;
    if (win.GetFileSizeEx(handle, &size) == 0 or size.QuadPart <= 0 or size.QuadPart > max_bytes) return null;
    const buffer = allocator.alloc(u8, @intCast(size.QuadPart)) catch return null;
    var total: usize = 0;
    while (total < buffer.len) {
        var got: win.DWORD = 0;
        if (win.ReadFile(handle, buffer[total..].ptr, @intCast(buffer.len - total), &got, null) == 0) break;
        if (got == 0) break;
        total += got;
    }
    if (total != buffer.len) {
        allocator.free(buffer);
        return null;
    }
    return buffer;
}

fn writeFileWin(path_utf8: []const u8, data: []const u8) void {
    const allocator = app_ptr orelse return;
    _ = allocator;
    const app = app_ptr.?;
    const wide = std.unicode.utf8ToUtf16LeAllocZ(app.allocator, path_utf8) catch return;
    defer app.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_WRITE, 0, null, win.CREATE_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var written: win.DWORD = 0;
    _ = win.WriteFile(handle, data.ptr, @intCast(data.len), &written, null);
}

fn messagesDirPath(a: *App, part: []const u8) ?[]u8 {
    const dir = std.fs.path.dirname(a.avatar_dir) orelse return null;
    return std.fs.path.join(a.allocator, &.{ dir, part }) catch null;
}

fn writeCacheFileAtomic(a: *App, path: []const u8, data: []const u8) bool {
    const tmp = std.fmt.allocPrint(a.allocator, "{s}.{x}.tmp", .{ path, win.GetTickCount64() }) catch return false;
    defer a.allocator.free(tmp);
    const tmp_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, tmp) catch return false;
    defer a.allocator.free(tmp_wide);
    const handle = win.CreateFileW(tmp_wide.ptr, win.GENERIC_WRITE, 0, null, win.CREATE_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return false;
    var written: win.DWORD = 0;
    const wrote = win.WriteFile(handle, data.ptr, @intCast(data.len), &written, null) != 0 and written == data.len;
    const flushed = win.FlushFileBuffers(handle) != 0;
    _ = win.CloseHandle(handle);
    if (!wrote or !flushed) {
        _ = win.DeleteFileW(tmp_wide.ptr);
        return false;
    }
    const path_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path) catch return false;
    defer a.allocator.free(path_wide);
    if (win.MoveFileExW(tmp_wide.ptr, path_wide.ptr, win.MOVEFILE_REPLACE_EXISTING | win.MOVEFILE_WRITE_THROUGH) == 0) {
        _ = win.DeleteFileW(tmp_wide.ptr);
        return false;
    }
    return true;
}

fn deleteAccountCaches(a: *App) void {
    const tag = a.cache_tag.slice();
    if (tag.len == 0) return;
    var name_buffer: [64]u8 = undefined;
    if (std.fmt.bufPrint(&name_buffer, "chats-{s}.json", .{tag})) |name| {
        if (messagesDirPath(a, name)) |path| {
            defer a.allocator.free(path);
            deleteFileUtf8(path);
        }
    } else |_| {}
    if (std.fmt.bufPrint(&name_buffer, "msg-cache-{s}", .{tag})) |dir_name| {
        if (messagesDirPath(a, dir_name)) |dir_path| {
            defer a.allocator.free(dir_path);
            std.Io.Dir.cwd().deleteTree(a.io, dir_path) catch {};
        }
    } else |_| {}
    if (std.fmt.bufPrint(&name_buffer, "voice-format-{s}", .{tag})) |dir_name| {
        if (messagesDirPath(a, dir_name)) |dir_path| {
            defer a.allocator.free(dir_path);
            std.Io.Dir.cwd().deleteTree(a.io, dir_path) catch {};
        }
    } else |_| {}
}

fn chatsCachePath(a: *App) ?[]u8 {
    const tag = a.cache_tag.slice();
    if (tag.len == 0) return null;
    var name_buffer: [64]u8 = undefined;
    const name = std.fmt.bufPrint(&name_buffer, "{s}chats-{s}.json", .{ if (unifiedHub(a)) "hub-" else "", tag }) catch return null;
    return messagesDirPath(a, name);
}

fn saveChatsCache(a: *App, raw: []const u8) void {
    if (a.startup_probe_pending) return;
    if (a.search) |search| {
        if (win.GetWindowTextLengthW(search) > 0) return;
    }
    const path = chatsCachePath(a) orelse return;
    defer a.allocator.free(path);
    _ = writeCacheFileAtomic(a, path, raw);
    if (!unifiedHub(a)) removeOtherChatsCaches(a, path);
}

fn removeOtherChatsCaches(a: *App, keep_path: []const u8) void {
    const dir = std.fs.path.dirname(a.avatar_dir) orelse return;
    const pattern = messagesDirPath(a, "chats-*.json") orelse return;
    defer a.allocator.free(pattern);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, pattern) catch return;
    defer a.allocator.free(wide);
    var find: win.WIN32_FIND_DATAW = undefined;
    const handle = win.FindFirstFileW(wide.ptr, &find);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.FindClose(handle);
    while (true) {
        const name_len = std.mem.indexOfScalar(u16, &find.cFileName, 0) orelse find.cFileName.len;
        const candidate = std.unicode.utf16LeToUtf8Alloc(a.allocator, find.cFileName[0..name_len]) catch break;
        defer a.allocator.free(candidate);
        if (std.fs.path.join(a.allocator, &.{ dir, candidate })) |full| {
            defer a.allocator.free(full);
            if (!std.mem.eql(u8, full, keep_path)) deleteFileUtf8(full);
        } else |_| {}
        if (win.FindNextFileW(handle, &find) == 0) break;
    }
}

fn loadChatsCache(a: *App) void {
    const path = chatsCachePath(a) orelse {
        appendLaunchLog(a, "cache-load skipped: no account tag");
        return;
    };
    defer a.allocator.free(path);
    const data = readFileWin(a.allocator, path, msg_cache_max_bytes) orelse {
        appendLaunchLog(a, "cache-load: chats snapshot missing");
        return;
    };
    defer a.allocator.free(data);
    const applied = applyChats(a, data, false);
    if (applied) {
        if (a.allocator.dupe(u8, data)) |copy| {
            if (a.chats_raw) |old| a.allocator.free(old);
            a.chats_raw = copy;
            a.chats_raw_flags = if (a.show_archived) 2 else if (a.include_archived) 1 else 0;
        } else |_| {}
        logStartupMilestone(a, .chats, "chat list from cache");
    }
    var log_buffer: [64]u8 = undefined;
    const log_line = std.fmt.bufPrint(&log_buffer, "cache-load: {d} bytes, applied={}", .{ data.len, applied }) catch "cache-load: logged";
    appendLaunchLog(a, log_line);
}

fn msgCacheDirName(a: *App, buffer: []u8) ?[]const u8 {
    if (a.cache_tag.len == 0) return null;
    return std.fmt.bufPrint(buffer, "{s}msg-cache-{s}", .{ if (unifiedHub(a)) "hub-" else "", a.cache_tag.slice() }) catch null;
}

fn msgCacheDiskPath(a: *App, jid: []const u8) ?[]u8 {
    var dir_buffer: [64]u8 = undefined;
    const dir_name = msgCacheDirName(a, &dir_buffer) orelse return null;
    const dir_path = messagesDirPath(a, dir_name) orelse return null;
    defer a.allocator.free(dir_path);
    const dir_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, dir_path) catch return null;
    defer a.allocator.free(dir_wide);
    _ = win.CreateDirectoryW(dir_wide.ptr, null);
    var name_buffer: [32]u8 = undefined;
    const name = std.fmt.bufPrint(&name_buffer, "{x:0>16}.msg", .{std.hash.Wyhash.hash(0, jid)}) catch return null;
    return std.fs.path.join(a.allocator, &.{ dir_path, name }) catch null;
}

fn loadMsgCacheDisk(a: *App, jid: []const u8) ?[]u8 {
    const path = msgCacheDiskPath(a, jid) orelse return null;
    defer a.allocator.free(path);
    const data = readFileWin(a.allocator, path, msg_cache_max_bytes) orelse return null;
    defer a.allocator.free(data);
    const payload = chat_cache.payloadFor(data, a.cache_tag.slice(), jid) orelse return null;
    return a.allocator.dupe(u8, payload) catch null;
}

fn pruneStaleMsgCache(a: *App) void {
    const dir = std.fs.path.dirname(a.avatar_dir) orelse return;
    const dirs_pattern = messagesDirPath(a, "msg-cache-*") orelse return;
    defer a.allocator.free(dirs_pattern);
    const dirs_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, dirs_pattern) catch return;
    defer a.allocator.free(dirs_wide);
    var dirs: win.WIN32_FIND_DATAW = undefined;
    const dirs_handle = win.FindFirstFileW(dirs_wide.ptr, &dirs);
    if (dirs_handle == win.INVALID_HANDLE_VALUE or dirs_handle == null) return;
    defer _ = win.FindClose(dirs_handle);
    const now = nowUnixSeconds();
    var scanned: usize = 0;
    while (scanned < 4096) : (scanned += 1) {
        if ((dirs.dwFileAttributes & win.FILE_ATTRIBUTE_DIRECTORY) != 0 and
            (dirs.dwFileAttributes & win.FILE_ATTRIBUTE_REPARSE_POINT) == 0)
        {
            pruneStaleInDir(a, dir, &dirs, now, &scanned);
        }
        if (win.FindNextFileW(dirs_handle, &dirs) == 0) break;
    }
}

fn pruneStaleInDir(a: *App, parent: []const u8, entry: *const win.WIN32_FIND_DATAW, now: i64, scanned: *usize) void {
    const name_len = std.mem.indexOfScalar(u16, &entry.cFileName, 0) orelse entry.cFileName.len;
    const dir_name = std.unicode.utf16LeToUtf8Alloc(a.allocator, entry.cFileName[0..name_len]) catch return;
    defer a.allocator.free(dir_name);
    const dir_path = std.fs.path.join(a.allocator, &.{ parent, dir_name }) catch return;
    defer a.allocator.free(dir_path);
    var pattern_buffer: [80]u8 = undefined;
    const dir_pattern = std.fmt.bufPrint(&pattern_buffer, "{s}\\*", .{dir_path}) catch return;
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, dir_pattern) catch return;
    defer a.allocator.free(wide);
    var find: win.WIN32_FIND_DATAW = undefined;
    const handle = win.FindFirstFileW(wide.ptr, &find);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.FindClose(handle);
    while (scanned.* < 4096) : (scanned.* += 1) {
        const is_dir = (find.dwFileAttributes & win.FILE_ATTRIBUTE_DIRECTORY) != 0;
        if (!is_dir and (find.dwFileAttributes & win.FILE_ATTRIBUTE_REPARSE_POINT) == 0) {
            const ticks: i64 = (@as(i64, find.ftLastWriteTime.dwHighDateTime) << 32) | find.ftLastWriteTime.dwLowDateTime;
            const written = @divTrunc(ticks - 116444736000000000, 10_000_000);
            if (now - written > media_cache_eviction_days * 24 * 60 * 60) {
                const file_len = std.mem.indexOfScalar(u16, &find.cFileName, 0) orelse find.cFileName.len;
                const file_name = std.unicode.utf16LeToUtf8Alloc(a.allocator, find.cFileName[0..file_len]) catch continue;
                defer a.allocator.free(file_name);
                if (std.fs.path.join(a.allocator, &.{ dir_path, file_name })) |full| {
                    defer a.allocator.free(full);
                    deleteFileUtf8(full);
                } else |_| {}
            }
        }
        if (win.FindNextFileW(handle, &find) == 0) break;
    }
}

fn saveTranscriptCache(a: *App, message: *const Message) void {
    const path_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.local_path.slice()) catch return;
    defer a.allocator.free(path_utf8);
    const cache_path = std.fmt.allocPrint(a.allocator, "{s}.txt", .{path_utf8}) catch return;
    defer a.allocator.free(cache_path);
    const transcript_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.transcript.slice()) catch return;
    defer a.allocator.free(transcript_utf8);
    writeFileWin(cache_path, transcript_utf8);
}

fn ensureTranscribeSession(a: *App) ?*dictation.FileSession {
    if (a.transcribe_session) |session| return session;
    a.transcribe_session = dictation.FileSession.create(a.allocator) catch null;
    return a.transcribe_session;
}

fn beginTranscriptionOpen(a: *App) void {
    a.transcribe_attempt_count = 0;
    if (a.transcribe_active_id.len > 0) _ = transcribeWasAttempted(a, a.transcribe_active_id.slice());
    for (a.messages[0..a.message_count]) |*message| {
        if (message.transcript_state == .failed) message.transcript_state = .none;
    }
}

fn transcribeWasAttempted(a: *App, id: []const u8) bool {
    const hash = std.hash.Wyhash.hash(0, id);
    for (a.transcribe_attempts[0..a.transcribe_attempt_count]) |attempt| if (attempt == hash) return true;
    if (a.transcribe_attempt_count >= a.transcribe_attempts.len) return true;
    a.transcribe_attempts[a.transcribe_attempt_count] = hash;
    a.transcribe_attempt_count += 1;
    return false;
}

fn appendDebugLog(a: *App, comptime format: []const u8, args: anytype) void {
    const line = std.fmt.allocPrint(a.allocator, format ++ "\n", args) catch return;
    defer a.allocator.free(line);
    const log_path = std.fs.path.join(a.allocator, &.{ a.avatar_dir, "..", "transcribe.log" }) catch return;
    defer a.allocator.free(log_path);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, log_path) catch return;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.FILE_APPEND_DATA, win.FILE_SHARE_READ | win.FILE_SHARE_WRITE, null, win.OPEN_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var written: win.DWORD = 0;
    _ = win.WriteFile(handle, line.ptr, @intCast(line.len), &written, null);
}

fn scheduleNextTranscription(a: *App) void {
    if (!a.deepgram_configured or a.chat_selection_pending or a.selected_chat >= a.chat_count) return;
    if (!chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]))) return;
    if (a.openrouter_session) |format_session| {
        const format_state = format_session.state();
        if (format_state == .recording or format_state == .transcribing) return;
    }
    const session = ensureTranscribeSession(a) orelse return;
    const state = session.state();
    if (state != .idle and state != .ready and state != .failed) return;
    var candidate: ?usize = null;
    var index: usize = a.message_count;
    while (index > 0) {
        index -= 1;
        const message = &a.messages[index];
        if (!isAudio(message) or message.local_path.len == 0 or message.transcript_state != .none) continue;
        if (message.id.len == 0) continue;
        if (transcribeWasAttempted(a, message.id.slice())) {
            message.transcript_state = if (std.mem.eql(u8, a.transcribe_active_id.slice(), message.id.slice())) .loading else .failed;
            continue;
        }
        candidate = index;
        break;
    }
    if (candidate == null) return;
    const message = &a.messages[candidate.?];
    const language: dictation.Language = .automatic;
    const path_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.local_path.slice()) catch return;
    defer a.allocator.free(path_utf8);
    if (session.start(path_utf8, a.deepgram_key, language)) {
        message.transcript_state = .loading;
        a.transcribe_active_id.set(message.id.slice());
        appendDebugLog(a, "schedule: started path_len={d} language={s}", .{ path_utf8.len, @tagName(language) });
    } else {
        message.transcript_state = .failed;
        message.transcript_error.set(a.allocator, "Transcription could not start");
        appendDebugLog(a, "schedule: start returned false", .{});
    }
}

fn pollTranscription(a: *App) void {
    const session = a.transcribe_session orelse return;
    const state = session.state();
    if (state != .ready and state != .failed) return;
    const done_id = a.transcribe_active_id;
    a.transcribe_active_id.set("");
    if (done_id.len == 0) {
        if (state == .ready) {
            var discard: [8192]u8 = undefined;
            _ = session.takeResult(&discard);
        }
        return;
    }
    for (a.messages[0..a.message_count]) |*message| {
        if (!std.mem.eql(u8, message.id.slice(), done_id.slice())) continue;
        if (state == .ready) {
            var buffer: [8192]u8 = undefined;
            if (session.takeResult(&buffer)) |transcript| {
                if (transcript.len > 0) {
                    message.transcript.set(a.allocator, transcript);
                    message.transcript_state = .ready;
                    saveTranscriptCache(a, message);
                    appendDebugLog(a, "poll: ready len={d}", .{transcript.len});
                } else {
                    message.transcript_state = .failed;
                    message.transcript_error.set(a.allocator, dictation_policy.failureText(error.NoSpeech));
                    appendDebugLog(a, "poll: ready but empty transcript", .{});
                }
            }
        } else {
            message.transcript_state = .failed;
            const failure = session.failure orelse error.TranscriptionFailed;
            message.transcript_error.set(a.allocator, dictation_policy.failureText(failure));
            appendDebugLog(a, "poll: failed reason={s}", .{@errorName(failure)});
            setStatus(a, "Transcription failed for a voice message");
        }
        break;
    }
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn ensureOpenRouterSession(a: *App) ?*dictation.TextSession {
    if (a.openrouter_session) |session| return session;
    a.openrouter_session = dictation.TextSession.create(a.allocator) catch null;
    return a.openrouter_session;
}

fn pollFormatting(a: *App) void {
    const session = a.openrouter_session orelse return;
    const state = session.state();
    if (state != .ready and state != .failed) return;
    const done_id = a.openrouter_active_id;
    a.openrouter_active_id.set("");
    if (done_id.len == 0) {
        if (state == .ready) {
            var discard: [16384]u8 = undefined;
            _ = session.takeResult(&discard);
        }
        return;
    }
    const key = format_cache.Key{
        .account = a.openrouter_active_account.slice(),
        .chat = a.openrouter_active_chat.slice(),
        .message = done_id.slice(),
    };
    if (state == .ready) {
        var buffer: [16384]u8 = undefined;
        if (session.takeResult(&buffer)) |formatted| {
            if (formatted.len > 0 and std.mem.eql(u8, key.account, a.cache_tag.slice())) {
                saveFormattedCache(a, key, formatted);
                if (a.displayed_provider == .whatsapp and std.mem.eql(u8, key.account, a.displayed_account.slice()) and std.mem.eql(u8, key.chat, a.displayed_jid.slice())) {
                    for (a.messages[0..a.message_count]) |*message| {
                        if (!std.mem.eql(u8, message.id.slice(), done_id.slice())) continue;
                        message.transcript.set(a.allocator, formatted);
                        message.transcript_state = .ready;
                        break;
                    }
                }
                appendDebugLog(a, "format: ready len={d}", .{formatted.len});
            }
        }
    } else {
        appendDebugLog(a, "format: failed, keeping raw transcript", .{});
    }
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn scheduleNextFormatting(a: *App) void {
    if (!a.openrouter_configured) return;
    if (a.openrouter_active_id.len > 0) return;
    const session = ensureOpenRouterSession(a) orelse return;
    const state = session.state();
    if (state == .recording or state == .transcribing) return;
    if (state == .ready) {
        var discard: [16384]u8 = undefined;
        _ = session.takeResult(&discard);
    }
    var candidate: ?usize = null;
    var index: usize = a.message_count;
    while (index > 0) {
        index -= 1;
        const message = &a.messages[index];
        if (message.transcript_state != .ready or message.transcript.len == 0) continue;
        if (!a.formatting_requests.claim(u16, message.id.slice(), message.transcript.slice())) continue;
        candidate = index;
        break;
    }
    const message_index = candidate orelse return;
    const message = &a.messages[message_index];
    const transcript_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.transcript.slice()) catch return;
    defer a.allocator.free(transcript_utf8);
    var contact_buffer: [192]u8 = undefined;
    const contact_name = blk: {
        const named = if (message.sender.len > 0 and !message.from_me) message.sender.slice() else if (a.selected_chat < a.chat_count) a.chats[a.selected_chat].name.slice() else &[_]u16{};
        const len = std.unicode.utf16LeToUtf8(&contact_buffer, named) catch 0;
        break :blk contact_buffer[0..len];
    };
    const speaker = format_request.speakerInstruction(a.allocator, message.from_me, contact_name) catch return;
    defer a.allocator.free(speaker);
    if (session.start(transcript_utf8, a.openrouter_key, a.openrouter_model, a.format_workspace, speaker)) {
        a.openrouter_active_id.set(message.id.slice());
        a.openrouter_active_chat = a.displayed_jid;
        a.openrouter_active_account = a.cache_tag;
        appendDebugLog(a, "format schedule: queued len={d}", .{transcript_utf8.len});
    }
}

fn cycleSpeed(a: *App) void {
    const player = a.audio_player orelse return;
    const next: u32 = switch (player.speed()) {
        100 => 150,
        150 => 200,
        else => 100,
    };
    player.setSpeed(next);
    var buffer: [32]u8 = undefined;
    const label: []const u8 = switch (next) {
        150 => "1.5x",
        200 => "2x",
        else => "1x",
    };
    setStatus(a, std.fmt.bufPrint(&buffer, "Playback speed {s}", .{label}) catch "Playback speed changed");
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn speedLabel(player: ?*audio.Player) [*:0]const u16 {
    const current: u32 = if (player) |p| p.speed() else 100;
    return switch (current) {
        150 => lit("1.5x"),
        200 => lit("2x"),
        else => lit("1x"),
    };
}

fn checkMediaDownload(a: *App) void {
    if (hubConfigured(a)) {
        for (&a.media_downloads) |*slot| {
            if (slot.hub_pending and slot.hub_retry_ms > 0 and win.GetTickCount64() >= slot.hub_retry_ms) _ = enqueueHubMedia(a, slot);
        }
        if (a.audio_chain_waiting) {
            for (a.messages[0..a.message_count]) |*message| {
                if (std.mem.eql(u8, message.id.slice(), a.audio_chain_id.slice()) and message.local_path.len > 0) {
                    a.audio_chain_waiting = false;
                    startAudioPlayback(a, message);
                    break;
                }
            }
        }
        return;
    }
    var finished_ok: usize = 0;
    var finished_failed: usize = 0;
    var chain_slot_done = false;
    for (&a.media_downloads) |*slot| {
        if (slot.child) |*child| {
            const timed_out = win.GetTickCount64() - slot.started_ms > media_timeout_ms;
            var code: win.DWORD = 0;
            var got_code = false;
            if (child.id) |handle| got_code = win.GetExitCodeProcess(handle, &code) != 0;
            if (got_code and code == win.STILL_ACTIVE and !timed_out) continue;
            if (timed_out or !got_code) _ = child.kill(a.io);
            if (!got_code) code = 1;
            _ = child.wait(a.io) catch {};
            if (code == 0) {
                markMediaAttempted(a, slot.jid.slice(), slot.id.slice());
                clearMediaFailure(a, slot.jid.slice(), slot.id.slice());
            } else {
                noteMediaFailure(a, slot.jid.slice(), slot.id.slice());
            }
            image_viewer.downloadFinished(a, slot.jid.slice(), slot.id.slice(), code == 0);
            if (std.mem.eql(u8, slot.id.slice(), a.audio_chain_id.slice())) chain_slot_done = true;
            slot.child = null;
            slot.jid.set("");
            slot.id.set("");
            if (code == 0) finished_ok += 1 else finished_failed += 1;
        }
    }
    if (finished_ok + finished_failed > 0) {
        drainMediaDownloads(a);
        startSync(a);
        refreshMessages(a);
        if (a.audio_chain_waiting and chain_slot_done) {
            a.audio_chain_waiting = false;
            var chain_started = false;
            for (a.messages[0..a.message_count]) |*message| {
                if (std.mem.eql(u8, message.id.slice(), a.audio_chain_id.slice())) {
                    if (message.local_path.len > 0) {
                        startAudioPlayback(a, message);
                        chain_started = true;
                    }
                    break;
                }
            }
            if (!chain_started and a.audio_state != .empty) a.audio_auto_advance = false;
        }
        if (finished_ok > 0) {
            setStatus(a, "Attachment downloaded");
        } else {
            setStatus(a, "Download failed, the attachment may have expired");
        }
    }
}

fn openMedia(a: *App, message: *const Message) void {
    if (message.local_path.len == 0) return;
    if (!shell_lazy.ensureShell32()) {
        setStatus(a, "Windows could not open the attachment");
        return;
    }
    const result = shell_lazy.shellExecuteW.?(a.hwnd.?, lit("open"), message.local_path.ptr(), null, null, win.SW_SHOWNORMAL);
    if (@intFromPtr(result) <= 32) setStatus(a, "Windows could not open the attachment");
}

fn clampPlayerSize(width: u32, height: u32) [2]u32 {
    const max_width: u32 = 800;
    const max_height: u32 = 450;
    if (width == 0 or height == 0) return .{ 640, 360 };
    var w: u64 = width;
    var h: u64 = height;
    if (w > max_width) {
        h = @max(1, h * max_width / w);
        w = max_width;
    }
    if (h > max_height) {
        w = @max(1, w * max_height / h);
        h = max_height;
    }
    return .{ @intCast(w), @intCast(h) };
}

fn playerCallbackQueryInterface(_: [*c]win.IMFPMediaPlayerCallback, riid: [*c]const win.GUID, ppv_object: [*c]?*anyopaque) callconv(.winapi) win.HRESULT {
    if (ppv_object != null and riid != null) {
        const iid_callback = win.GUID{ .Data1 = 0x766c8ffb, .Data2 = 0x5fdb, .Data3 = 0x4fea, .Data4 = .{ 0xa2, 0x8d, 0xb9, 0x12, 0x99, 0x6f, 0x51, 0xbd } };
        const iid_unknown = win.GUID{ .Data1 = 0, .Data2 = 0, .Data3 = 0, .Data4 = .{ 0xc0, 0, 0, 0, 0, 0, 0, 0x46 } };
        const g = riid.*;
        const is_unknown = std.meta.eql(g, iid_unknown);
        const is_callback = std.meta.eql(g, iid_callback);
        if (is_unknown or is_callback) {
            ppv_object.* = @ptrCast(&player_callback);
            _ = playerCallbackAddRef(&player_callback);
            return 0;
        }
        ppv_object.* = null;
    }
    return win.E_NOINTERFACE;
}

fn playerCallbackAddRef(_: [*c]win.IMFPMediaPlayerCallback) callconv(.winapi) win.ULONG {
    return @atomicRmw(u32, &player_callback_refs, .Add, 1, .monotonic) + 1;
}

fn playerCallbackRelease(_: [*c]win.IMFPMediaPlayerCallback) callconv(.winapi) win.ULONG {
    return @atomicRmw(u32, &player_callback_refs, .Sub, 1, .monotonic) - 1;
}

fn playerCallbackEvent(_: [*c]win.IMFPMediaPlayerCallback, event: [*c]win.MFP_EVENT_HEADER) callconv(.winapi) void {
    _ = event;
}

var player_callback = win.IMFPMediaPlayerCallback{ .lpVtbl = &player_callback_vtable };
var player_callback_vtable = win.IMFPMediaPlayerCallbackVtbl{
    .QueryInterface = playerCallbackQueryInterface,
    .AddRef = playerCallbackAddRef,
    .Release = playerCallbackRelease,
    .OnMediaPlayerEvent = playerCallbackEvent,
};
var player_callback_refs: u32 = 1;

var player_class_registered: bool = false;

fn closePlayer(a: *App) void {
    a.player_fullscreen = false;
    if (a.mf_player) |player| {
        a.mf_player = null;
        _ = player.lpVtbl.*.Shutdown.?(player);
        _ = player.lpVtbl.*.Release.?(player);
    }
    if (a.player_window) |hwnd| {
        a.player_window = null;
        _ = win.DestroyWindow(hwnd);
    }
}

fn playerProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_ERASEBKGND => {
            var client: win.RECT = undefined;
            _ = win.GetClientRect(hwnd, &client);
            if (win.CreateSolidBrush(theme.current.surface)) |brush| {
                _ = win.FillRect(winHandle(win.HDC, wparam), &client, brush);
                _ = win.DeleteObject(brush);
            }
            return 1;
        },
        win.WM_KEYDOWN => {
            if (wparam == win.VK_F11) {
                togglePlayerFullscreen(a, hwnd);
                return 0;
            }
            if (wparam == 27) {
                if (a.player_fullscreen) {
                    togglePlayerFullscreen(a, hwnd);
                } else {
                    closePlayer(a);
                }
                return 0;
            }
        },
        win.WM_LBUTTONDBLCLK => {
            togglePlayerFullscreen(a, hwnd);
            return 0;
        },
        win.WM_SIZE => {
            if (a.mf_player) |player| _ = player.lpVtbl.*.UpdateVideo.?(player);
        },
        win.WM_PAINT => {
            var ps = win.PAINTSTRUCT{};
            const hdc = win.BeginPaint(hwnd, &ps);
            if (a.mf_player) |player| _ = player.lpVtbl.*.UpdateVideo.?(player);
            _ = win.EndPaint(hwnd, &ps);
            _ = hdc;
            return 0;
        },
        win.WM_CLOSE => {
            closePlayer(a);
            return 0;
        },
        win.WM_DESTROY => {
            if (a.player_window != null and a.player_window.? == hwnd) a.player_window = null;
            if (a.mf_player) |player| {
                _ = player.lpVtbl.*.Shutdown.?(player);
                _ = player.lpVtbl.*.Release.?(player);
                a.mf_player = null;
            }
            return 0;
        },
        else => {},
    }
    return win.DefWindowProcW(hwnd, message, wparam, lparam);
}

fn playVideoInline(a: *App, message: *const Message) void {
    if (message.local_path.len == 0) return;
    if (!mf_lazy.ensureStarted()) {
        setStatus(a, "Video playback is not available for this file");
        return;
    }
    if (a.player_window != null) closePlayer(a);
    const size = clampPlayerSize(@intCast(@max(message.bitmap_width, 0)), @intCast(@max(message.bitmap_height, 0)));
    var rect = win.RECT{ .left = 0, .top = 0, .right = @intCast(size[0]), .bottom = @intCast(size[1]) };
    _ = win.AdjustWindowRect(&rect, win.WS_OVERLAPPEDWINDOW, 0);
    const hwnd = openPlayerWindow(a, rect.right - rect.left, rect.bottom - rect.top) orelse {
        setStatus(a, "Could not open the video player");
        return;
    };
    var player: ?*win.IMFPMediaPlayer = null;
    const hr = mf_lazy.createMediaPlayer.?(message.local_path.ptr(), 1, win.MFP_OPTION_NONE, &player_callback, hwnd, &player);
    if (hr < 0 or player == null) {
        setStatus(a, "Video playback is not available for this file");
        a.player_window = null;
        _ = win.DestroyWindow(hwnd);
        return;
    }
    a.mf_player = player;
    _ = win.ShowWindow(hwnd, win.SW_SHOW);
}

fn playUnfurlVideo(a: *App, entry: *const UnfurlEntry) void {
    if (entry.play_url.len == 0) return;
    if (!mf_lazy.ensureStarted()) {
        setStatus(a, "This video cannot play in the app");
        return;
    }
    if (a.player_window != null) closePlayer(a);
    const hwnd = openPlayerWindow(a, 800, 450) orelse {
        setStatus(a, "Could not open the video player");
        return;
    };
    var player: ?*win.IMFPMediaPlayer = null;
    const hr = mf_lazy.createMediaPlayer.?(entry.play_url.ptr(), 1, win.MFP_OPTION_NONE, &player_callback, hwnd, &player);
    if (hr < 0 or player == null) {
        setStatus(a, "This video cannot play in the app");
        a.player_window = null;
        _ = win.DestroyWindow(hwnd);
        return;
    }
    a.mf_player = player;
    _ = win.ShowWindow(hwnd, win.SW_SHOW);
}

fn openPlayerWindow(a: *App, width: i32, height: i32) ?win.HWND {
    if (!player_class_registered) {
        var class = win.WNDCLASSEXW{
            .cbSize = @sizeOf(win.WNDCLASSEXW),
            .style = win.CS_HREDRAW | win.CS_VREDRAW | win.CS_DBLCLKS,
            .lpfnWndProc = playerProc,
            .hInstance = a.instance,
            .hCursor = win.LoadCursorW(null, @ptrFromInt(32512)),
            .hbrBackground = null,
            .lpszClassName = lit("MessagesVideoPlayer"),
            .hIconSm = null,
        };
        if (win.RegisterClassExW(&class) == 0) {
            return null;
        }
        player_class_registered = true;
    }
    const hwnd = win.CreateWindowExW(
        0,
        lit("MessagesVideoPlayer"),
        lit("Messages · Video"),
        win.WS_OVERLAPPEDWINDOW,
        win.CW_USEDEFAULT,
        win.CW_USEDEFAULT,
        width,
        height,
        a.hwnd orelse null,
        null,
        a.instance,
        null,
    ) orelse return null;
    a.player_window = hwnd;
    return hwnd;
}

fn togglePlayerFullscreen(a: *App, hwnd: win.HWND) void {
    const style = win.GetWindowLongPtrW(hwnd, win.GWL_STYLE);
    if (!a.player_fullscreen) {
        var placement = std.mem.zeroes(win.WINDOWPLACEMENT);
        placement.length = @sizeOf(win.WINDOWPLACEMENT);
        if (win.GetWindowPlacement(hwnd, &placement) == 0) return;
        const monitor = win.MonitorFromWindow(hwnd, win.MONITOR_DEFAULTTONEAREST);
        var info = std.mem.zeroes(win.MONITORINFO);
        info.cbSize = @sizeOf(win.MONITORINFO);
        if (win.GetMonitorInfoW(monitor, &info) == 0) return;
        a.player_saved_placement = placement;
        const overlapped: isize = @intCast(win.WS_OVERLAPPEDWINDOW);
        const popup: isize = @intCast(win.WS_POPUP);
        _ = win.SetWindowLongPtrW(hwnd, win.GWL_STYLE, (style & ~overlapped) | popup);
        _ = win.SetWindowPos(
            hwnd,
            null,
            info.rcMonitor.left,
            info.rcMonitor.top,
            info.rcMonitor.right - info.rcMonitor.left,
            info.rcMonitor.bottom - info.rcMonitor.top,
            win.SWP_FRAMECHANGED | win.SWP_NOOWNERZORDER,
        );
        a.player_fullscreen = true;
    } else {
        const overlapped: isize = @intCast(win.WS_OVERLAPPEDWINDOW);
        const popup: isize = @intCast(win.WS_POPUP);
        _ = win.SetWindowLongPtrW(hwnd, win.GWL_STYLE, (style & ~popup) | overlapped);
        _ = win.SetWindowPlacement(hwnd, &a.player_saved_placement);
        _ = win.SetWindowPos(hwnd, null, 0, 0, 0, 0, win.SWP_FRAMECHANGED | win.SWP_NOMOVE | win.SWP_NOSIZE | win.SWP_NOZORDER | win.SWP_NOOWNERZORDER);
        a.player_fullscreen = false;
    }
    if (a.mf_player) |player| _ = player.lpVtbl.*.UpdateVideo.?(player);
}

fn isViewerImage(message: *const Message) bool {
    return isImage(message) or (isGif(message) and !isVideoGif(message));
}

const viewer_actions = .{
    .isImage = isViewerImage,
    .download = downloadMedia,
    .isDownloading = mediaDownloading,
    .openExternal = openMedia,
};

fn closeImageViewer(a: *App) void {
    image_viewer.close(a);
}

fn openImageViewer(a: *App, message: *const Message) void {
    image_viewer.open(a, message, viewer_actions);
}

fn openImageInViewerOrQueue(a: *App, index: usize, message: *const Message) void {
    _ = index;
    openImageViewer(a, message);
}

fn imageViewerProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    return image_viewer.windowProc(a, hwnd, message, wparam, lparam, viewer_actions);
}

fn detectUnfurl(message: *Message) void {
    if (message.unfurl_provider != .none) return;
    var buffer: [slack.max_text * 3]u8 = undefined;
    var url: []const u8 = "";
    if (message.label_link_count > 0) {
        const link = &message.label_links[0];
        url = link.url[0..link.url_len];
    } else {
        const length = std.unicode.utf16LeToUtf8(&buffer, message.text.slice()) catch return;
        var words = std.mem.tokenizeAny(u8, buffer[0..length], " \t\r\n<>");
        while (words.next()) |word| {
            if (unfurl.classify(word).provider != .none) {
                url = word;
                break;
            }
        }
    }
    const info = unfurl.classify(url);
    if (info.provider == .none or (info.provider == .image and message.media_type.len > 0)) return;
    message.unfurl_provider = info.provider;
    message.unfurl_id.set(info.idSlice());
    message.unfurl_canonical.set(info.canonicalSlice());
}

fn unfurlCardVisible(a: *App, message: *Message) bool {
    detectUnfurl(message);
    if (message.unfurl_provider == .none) return false;
    const entry = unfurlEntryFor(a, message) orelse return false;
    if (message.unfurl_provider == .image) {
        if (entry.status == .ready and entry.image_path.len > 0 and message.local_path.len == 0) {
            message.local_path = entry.image_path;
            message.media_type.set("image");
            if (std.ascii.endsWithIgnoreCase(message.unfurl_canonical.slice()[0 .. std.mem.indexOfAny(u8, message.unfurl_canonical.slice(), "?#") orelse message.unfurl_canonical.len], ".gif")) message.mime_type.set("image/gif");
        }
        return false;
    }
    return message.unfurl_provider != .page or (entry.status == .ready and entry.thumb != null);
}

fn unfurlEntryFor(a: *App, message: *Message) ?*UnfurlEntry {
    for (a.unfurl_entries[0..a.unfurl_entry_count]) |*entry| {
        if (entry.provider == message.unfurl_provider and
            std.mem.eql(u8, entry.id.slice(), message.unfurl_id.slice()))
        {
            if (!entry.fetch_started and message.unfurl_canonical.len > 0) {
                startUnfurlFetch(a, entry, message.unfurl_canonical.slice());
            }
            return entry;
        }
    }
    var entry: *UnfurlEntry = undefined;
    if (a.unfurl_entry_count < max_unfurl_entries) {
        entry = &a.unfurl_entries[a.unfurl_entry_count];
        a.unfurl_entry_count += 1;
    } else {
        entry = &a.unfurl_entries[a.unfurl_evict_slot];
        a.unfurl_evict_slot = (a.unfurl_evict_slot + 1) % max_unfurl_entries;
        if (entry.thumb) |thumb| _ = win.DeleteObject(thumb);
        entry.* = .{};
    }
    entry.provider = message.unfurl_provider;
    entry.id.set(message.unfurl_id.slice());
    if (message.unfurl_canonical.len > 0) {
        var canonical_buffer: [unfurl.max_canonical_len]u8 = undefined;
        @memcpy(canonical_buffer[0..message.unfurl_canonical.len], message.unfurl_canonical.slice());
        startUnfurlFetch(a, entry, canonical_buffer[0..message.unfurl_canonical.len]);
    }
    return entry;
}

fn unfurlProviderLabel(provider: unfurl.Provider) []const u8 {
    return switch (provider) {
        .youtube => "YouTube",
        .instagram => "Instagram",
        .facebook => "Facebook",
        .page, .image => "Link",
        .none => "Video",
    };
}

fn unfurlPlaceholderColor(provider: unfurl.Provider) u32 {
    return switch (provider) {
        .youtube => rgb(197, 40, 40),
        .instagram => rgb(225, 48, 108),
        .facebook => rgb(24, 119, 242),
        .none, .page, .image => theme.current.surface_container_highest,
    };
}

fn drawUnfurlThumbnail(hdc: win.HDC, bitmap: ?win.HBITMAP, rect: win.RECT, color: win.COLORREF) void {
    const width = rect.right - rect.left;
    const height = rect.bottom - rect.top;
    const memory = win.CreateCompatibleDC(hdc) orelse return;
    defer _ = win.DeleteDC(memory);
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = width;
    info.bmiHeader.biHeight = -height;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    var bits: ?*anyopaque = null;
    const dib = win.CreateDIBSection(memory, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return;
    defer _ = win.DeleteObject(dib);
    if (bits == null) return;
    const previous = win.SelectObject(memory, dib);
    defer _ = win.SelectObject(memory, previous);
    if (bitmap) |image| {
        const source = win.CreateCompatibleDC(hdc) orelse return;
        defer _ = win.DeleteDC(source);
        const old = win.SelectObject(source, image);
        defer _ = win.SelectObject(source, old);
        _ = win.SetStretchBltMode(memory, win.HALFTONE);
        _ = win.StretchBlt(memory, 0, 0, width, height, source, 0, 0, 320, 180, win.SRCCOPY);
    } else {
        const brush = win.CreateSolidBrush(color) orelse return;
        defer _ = win.DeleteObject(brush);
        _ = win.FillRect(memory, &.{ .left = 0, .top = 0, .right = width, .bottom = height }, brush);
    }
    _ = win.GdiFlush();
    const pixels: [*]u8 = @ptrCast(bits.?);
    for (0..@intCast(height)) |y| {
        for (0..@intCast(width)) |x| {
            const alpha: u16 = if (x < 5 and y < 5) avatar_mask.alphaAt(x, y, 10) else if (x < 5 and y >= height - 5) avatar_mask.alphaAt(x, y - @as(usize, @intCast(height - 10)), 10) else 255;
            const index = (y * @as(usize, @intCast(width)) + x) * 4;
            for (0..3) |channel| pixels[index + channel] = @intCast(@as(u16, pixels[index + channel]) * alpha / 255);
            pixels[index + 3] = @intCast(alpha);
        }
    }
    _ = win.AlphaBlend(hdc, rect.left, rect.top, width, height, memory, 0, 0, width, height, .{ .BlendOp = win.AC_SRC_OVER, .BlendFlags = 0, .SourceConstantAlpha = 255, .AlphaFormat = win.AC_SRC_ALPHA });
}

fn drawUnfurlCard(shapes: *const smooth.Context, hdc: win.HDC, a: *App, message: *Message, x: i32, top: i32, width: i32) void {
    const card_width = @min(@max(width, 200), unfurl_card_width);
    const entry = unfurlEntryFor(a, message) orelse return;
    const bottom = top + unfurl_card_height;
    message.unfurl_card_hit = .{ .left = x, .top = top, .right = x + card_width, .bottom = bottom };
    var face = message.unfurl_card_hit;
    face.left += 5;
    smooth.fillRoundRect(shapes, face, 10, 10, theme.current.surface_container);
    if (theme.choice == .amoled) smooth.strokeRoundRect(shapes, message.unfurl_card_hit, 10, 10, theme.current.outline_variant, 1);
    const old_pen = win.SelectObject(hdc, win.GetStockObject(win.NULL_PEN));
    defer _ = win.SelectObject(hdc, old_pen);

    const thumb_right = x + unfurl_thumb_width;
    drawUnfurlThumbnail(hdc, entry.thumb, .{ .left = x, .top = top, .right = thumb_right, .bottom = bottom }, unfurlPlaceholderColor(message.unfurl_provider));
    if (message.unfurl_provider != .page) {
        const play_brush = win.CreateSolidBrush(theme.current.on_surface) orelse return;
        defer _ = win.DeleteObject(play_brush);
        const old_play = win.SelectObject(hdc, play_brush);
        const center_x = x + @divTrunc(unfurl_thumb_width, 2);
        const center_y = top + @divTrunc(unfurl_card_height, 2);
        var points = [3]win.POINT{
            .{ .x = center_x - 9, .y = center_y - 13 },
            .{ .x = center_x - 9, .y = center_y + 13 },
            .{ .x = center_x + 15, .y = center_y },
        };
        _ = win.Polygon(hdc, &points, 3);
        _ = win.SelectObject(hdc, old_play);
    }
    _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
    _ = win.SetTextColor(hdc, theme.current.on_surface);
    var title: []const u16 = std.unicode.utf8ToUtf16LeStringLiteral("Loading…")[0..];
    if (entry.status == .ready and entry.title.len > 0) {
        title = entry.title.slice();
    } else if (entry.status == .failed) {
        title = std.unicode.utf8ToUtf16LeStringLiteral("Open in browser")[0..];
    }
    var title_rect = win.RECT{ .left = thumb_right + 10, .top = top + 10, .right = x + card_width - 10, .bottom = top + unfurl_card_height - (if (entry.description.len > 0) @as(i32, 54) else 34) };
    _ = text_draw.drawText(hdc, title.ptr, @intCast(title.len), &title_rect, win.DT_WORDBREAK | win.DT_END_ELLIPSIS);
    _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
    var label_buffer: [96]u8 = undefined;
    var author_utf8: [128]u8 = undefined;
    const author_length = std.unicode.utf16LeToUtf8(&author_utf8, entry.author.slice()) catch 0;
    const author = author_utf8[0..author_length];
    if (entry.description.len > 0) {
        var description_rect = win.RECT{ .left = thumb_right + 10, .top = bottom - 50, .right = x + card_width - 10, .bottom = bottom - 30 };
        _ = text_draw.drawText(hdc, entry.description.ptr(), @intCast(entry.description.len), &description_rect, win.DT_SINGLELINE | win.DT_END_ELLIPSIS);
    }
    const label = if (message.unfurl_provider == .page)
        author
    else if (author.len > 0)
        std.fmt.bufPrint(&label_buffer, "{s} · {s}", .{ unfurlProviderLabel(message.unfurl_provider), author }) catch "Video"
    else
        std.fmt.bufPrint(&label_buffer, "{s}", .{unfurlProviderLabel(message.unfurl_provider)}) catch "Video";
    var label_wide = WideText(96){};
    label_wide.set(a.allocator, label);
    var label_rect = win.RECT{ .left = thumb_right + 10, .top = bottom - 28, .right = x + card_width - 10, .bottom = bottom - 8 };
    _ = text_draw.drawText(hdc, label_wide.ptr(), @intCast(label_wide.len), &label_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS);
    _ = win.SelectObject(hdc, @ptrCast(a.font.?));
}

fn openUnfurlCard(a: *App, message: *const Message) void {
    for (a.unfurl_entries[0..a.unfurl_entry_count]) |*entry| {
        if (entry.provider != message.unfurl_provider) continue;
        if (!std.mem.eql(u8, entry.id.slice(), message.unfurl_id.slice())) continue;
        if (entry.play_url.len > 0) {
            playUnfurlVideo(a, entry);
        } else if (message.unfurl_canonical.len > 0) {
            const wide = utf8ToWide(a.allocator, message.unfurl_canonical.slice()) catch return;
            defer a.allocator.free(wide);
            openUrlWide(a, wide.ptr);
        }
        return;
    }
}

var unfurl_fetch_count = std.atomic.Value(u32).init(0);

const UnfurlContext = struct {
    hwnd: win.HWND,
    provider: u8,
    id: []u8,
    canonical: []u8,
    cache_path: ?[]u8,
};

const UnfurlResult = struct {
    provider: u8 = 0,
    id: [unfurl.max_id_len]u8 = undefined,
    id_len: usize = 0,
    ok: bool = false,
    title: [160]u8 = undefined,
    title_len: usize = 0,
    author: [64]u8 = undefined,
    author_len: usize = 0,
    description: [160]u8 = undefined,
    description_len: usize = 0,
    from_cache: bool = false,
    play_url: [1024]u8 = undefined,
    play_len: usize = 0,
    thumb: ?[]u8 = null,
};

fn startUnfurlFetch(a: *App, entry: *UnfurlEntry, url_utf8: []const u8) void {
    if (a.hwnd == null) {
        entry.status = .failed;
        return;
    }
    if (unfurl_fetch_count.load(.monotonic) >= max_unfurl_fetches) return;
    const page = std.heap.page_allocator;
    const url = page.dupe(u8, url_utf8) catch {
        entry.status = .failed;
        return;
    };
    const id = page.dupe(u8, entry.id.slice()) catch {
        page.free(url);
        entry.status = .failed;
        return;
    };
    const ctx = page.create(UnfurlContext) catch {
        page.free(url);
        page.free(id);
        entry.status = .failed;
        return;
    };
    const cache_path = unfurlCachePath(a, page, entry.provider, entry.id.slice());
    ctx.* = .{ .hwnd = a.hwnd.?, .provider = @intFromEnum(entry.provider), .id = id, .canonical = url, .cache_path = cache_path };
    _ = unfurl_fetch_count.fetchAdd(1, .monotonic);
    const thread = std.Thread.spawn(.{ .stack_size = 512 * 1024 }, unfurlThreadMain, .{ctx}) catch {
        _ = unfurl_fetch_count.fetchSub(1, .monotonic);
        page.free(url);
        page.free(id);
        if (cache_path) |path| page.free(path);
        page.destroy(ctx);
        entry.status = .failed;
        return;
    };
    thread.detach();
    entry.fetch_started = true;
}

fn unfurlCachePath(a: *App, allocator: std.mem.Allocator, provider: unfurl.Provider, id: []const u8) ?[]u8 {
    const dir = messagesDirPath(a, "link-previews") orelse return null;
    defer a.allocator.free(dir);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(allocator, dir) catch return null;
    defer allocator.free(wide);
    _ = win.CreateDirectoryW(wide.ptr, null);
    return std.fmt.allocPrint(allocator, "{s}/{s}-{s}.json", .{ dir, @tagName(provider), id }) catch null;
}

fn loadUnfurlCache(allocator: std.mem.Allocator, ctx: *const UnfurlContext, result: *UnfurlResult) bool {
    const path = ctx.cache_path orelse return false;
    const data = readFileWin(allocator, path, 16384) orelse return false;
    defer allocator.free(data);
    var parsed = std.json.parseFromSlice(std.json.Value, allocator, data, .{}) catch return false;
    defer parsed.deinit();
    if (parsed.value != .object) return false;
    const object = parsed.value.object;
    if (getBool(object, "image")) {
        const image_path = std.fmt.allocPrint(allocator, "{s}.image", .{path}) catch return false;
        defer allocator.free(image_path);
        result.thumb = readFileWin(allocator, image_path, 2 * 1024 * 1024) orelse return false;
    }
    result.title_len = copyInto(&result.title, getString(object, "title"));
    result.author_len = copyInto(&result.author, getString(object, "author"));
    result.description_len = copyInto(&result.description, getString(object, "description"));
    result.play_len = copyInto(&result.play_url, getString(object, "play_url"));
    result.from_cache = true;
    return true;
}

fn saveUnfurlCache(a: *App, entry: *UnfurlEntry, result: *const UnfurlResult) void {
    const path = unfurlCachePath(a, a.allocator, entry.provider, entry.id.slice()) orelse return;
    defer a.allocator.free(path);
    const image_path = std.fmt.allocPrint(a.allocator, "{s}.image", .{path}) catch return;
    defer a.allocator.free(image_path);
    if (result.thumb) |bytes| {
        if (result.from_cache or writeCacheFileAtomic(a, image_path, bytes)) entry.image_path.set(a.allocator, image_path);
    }
    if (result.from_cache) return;
    const data = std.json.Stringify.valueAlloc(a.allocator, .{
        .title = result.title[0..result.title_len],
        .author = result.author[0..result.author_len],
        .description = result.description[0..result.description_len],
        .play_url = result.play_url[0..result.play_len],
        .image = result.thumb != null and entry.image_path.len > 0,
    }, .{}) catch return;
    defer a.allocator.free(data);
    _ = writeCacheFileAtomic(a, path, data);
}

fn verificationUnfurlUrl(url: []const u8) bool {
    if (!verification_fixture) return false;
    const a = app_ptr orelse return false;
    const origin = std.mem.trimEnd(u8, a.wa_bridge_url, "/");
    return origin.len > 0 and std.mem.startsWith(u8, url, origin) and url.len > origin.len and url[origin.len] == '/';
}

fn httpGetChecked(allocator: std.mem.Allocator, url: []const u8, comptime kind: unfurl.FetchKind, max_bytes: usize) ![]u8 {
    if (!verificationUnfurlUrl(url)) switch (kind) {
        .page => if (!unfurl.isPageFetchAllowed(url)) return error.UpdateBadUrl,
        .image => if (!unfurl.isImageFetchAllowed(url)) return error.UpdateBadUrl,
    };
    const wide = try utf8ToWide(allocator, url);
    defer allocator.free(wide);
    var components: win.URL_COMPONENTSW = std.mem.zeroes(win.URL_COMPONENTSW);
    components.dwStructSize = @sizeOf(win.URL_COMPONENTSW);
    var host_buf: [256]u16 = undefined;
    var path_buf: [2048]u16 = undefined;
    var extra_buf: [1024]u16 = undefined;
    components.lpszHostName = &host_buf;
    components.dwHostNameLength = host_buf.len;
    components.lpszUrlPath = &path_buf;
    components.dwUrlPathLength = path_buf.len;
    components.lpszExtraInfo = &extra_buf;
    components.dwExtraInfoLength = extra_buf.len;
    if (win.WinHttpCrackUrl(wide.ptr, @intCast(wide.len), 0, &components) == 0) return error.UpdateBadUrl;
    if (components.nScheme != win.INTERNET_SCHEME_HTTPS and components.nScheme != win.INTERNET_SCHEME_HTTP) return error.UpdateBadUrl;
    if (components.dwHostNameLength == 0 or components.dwHostNameLength >= host_buf.len) return error.UpdateBadUrl;
    if (components.dwUrlPathLength + components.dwExtraInfoLength >= path_buf.len) return error.UpdateBadUrl;
    host_buf[components.dwHostNameLength] = 0;
    std.mem.copyForwards(u16, path_buf[components.dwUrlPathLength..], extra_buf[0..components.dwExtraInfoLength]);
    const path_total = components.dwUrlPathLength + components.dwExtraInfoLength;
    path_buf[path_total] = 0;
    return httpGet(
        allocator,
        host_buf[0..components.dwHostNameLength :0].ptr,
        path_buf[0..path_total :0].ptr,
        lit("User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64)\r\nAccept: */*\r\n"),
        max_bytes,
        components.nPort,
        components.nScheme == win.INTERNET_SCHEME_HTTPS,
        false,
    );
}

fn copyInto(dest: []u8, source: []const u8) usize {
    var length = @min(dest.len, source.len);
    while (length > 0 and !std.unicode.utf8ValidateSlice(source[0..length])) length -= 1;
    @memcpy(dest[0..length], source[0..length]);
    return length;
}

fn unfurlThreadMain(ctx: *UnfurlContext) void {
    const page = std.heap.page_allocator;
    defer {
        page.free(ctx.canonical);
        page.free(ctx.id);
        if (ctx.cache_path) |path| page.free(path);
        page.destroy(ctx);
    }
    const allocator = page;
    const result = allocator.create(UnfurlResult) catch {
        _ = unfurl_fetch_count.fetchSub(1, .monotonic);
        return;
    };
    result.* = .{ .provider = ctx.provider };
    result.id_len = copyInto(&result.id, ctx.id);
    const provider: unfurl.Provider = @enumFromInt(ctx.provider);
    var small_buffer: [unfurl.max_canonical_len]u8 = undefined;

    const cached = loadUnfurlCache(allocator, ctx, result);
    if (!cached) switch (provider) {
        .youtube => {
            const info = unfurl.classify(ctx.canonical);
            if (info.provider == .youtube) {
                if (unfurl.oembedEndpoint(&info, &small_buffer)) |endpoint| {
                    if (httpGetChecked(allocator, endpoint, .page, 16384)) |body| {
                        defer allocator.free(body);
                        var parsed = std.json.parseFromSlice(std.json.Value, allocator, body, .{}) catch null;
                        if (parsed) |*document| {
                            defer document.deinit();
                            if (document.value.object.get("title")) |title| {
                                if (title == .string) result.title_len = copyInto(&result.title, title.string);
                            }
                            if (document.value.object.get("author_name")) |author| {
                                if (author == .string) result.author_len = copyInto(&result.author, author.string);
                            }
                        }
                    } else |_| {}
                }
                if (httpGetChecked(allocator, ctx.canonical, .page, 1024 * 1024)) |page_body| {
                    defer allocator.free(page_body);
                    var stream_buffer: [2048]u8 = undefined;
                    if (unfurl.extractYoutubeStream(page_body, &stream_buffer)) |stream| {
                        result.play_len = copyInto(&result.play_url, stream);
                    }
                } else |_| {}
                if (unfurl.thumbnailUrl(&info, &small_buffer)) |thumb_url| {
                    if (httpGetChecked(allocator, thumb_url, .image, 2 * 1024 * 1024)) |bytes| {
                        result.thumb = bytes;
                    } else |_| {}
                }
            }
        },
        .image => {
            result.thumb = httpGetChecked(allocator, ctx.canonical, .image, 2 * 1024 * 1024) catch null;
        },
        .page, .instagram, .facebook => {
            if (httpGetChecked(allocator, ctx.canonical, .page, 256 * 1024)) |page_body| {
                defer allocator.free(page_body);
                var meta_buffer: [2048]u8 = undefined;
                if (unfurl.scrapeOgMeta(page_body, "og:title")) |title| result.title_len = copyInto(&result.title, slack.decodeHtmlEntities(&meta_buffer, title));
                if (unfurl.scrapeOgMeta(page_body, "og:description")) |description| result.description_len = copyInto(&result.description, slack.decodeHtmlEntities(&meta_buffer, description));
                if (provider == .page) result.author_len = copyInto(&result.author, unfurl.siteHost(ctx.canonical));
                if (provider != .page) {
                    if (unfurl.scrapeOgMeta(page_body, "og:video")) |stream| {
                        if (unfurl.isStreamUrlAllowed(stream)) result.play_len = copyInto(&result.play_url, stream);
                    }
                }
                const image_key: []const u8 = if (unfurl.scrapeOgMeta(page_body, "og:image:secure_url")) |image|
                    image
                else if (unfurl.scrapeOgMeta(page_body, "og:image")) |image|
                    image
                else
                    "";
                var image_buffer: [2048]u8 = undefined;
                const image_url = unfurl.resolveImageUrl(ctx.canonical, slack.decodeHtmlEntities(&meta_buffer, image_key), &image_buffer) orelse "";
                if (image_url.len > 0) {
                    if (httpGetChecked(allocator, image_url, .image, 2 * 1024 * 1024)) |bytes| {
                        result.thumb = bytes;
                    } else |_| {}
                }
            } else |_| {}
        },
        .none => {},
    };
    if (provider == .page and result.title_len == 0) result.title_len = copyInto(&result.title, result.author[0..result.author_len]);
    result.ok = if (provider == .page or provider == .image) result.thumb != null else result.title_len > 0 or result.play_len > 0 or result.thumb != null;
    _ = unfurl_fetch_count.fetchSub(1, .monotonic);
    if (win.PostMessageW(ctx.hwnd, wm_unfurl_done, 0, @bitCast(@intFromPtr(result))) == 0) {
        if (result.thumb) |bytes| page.free(bytes);
        page.destroy(result);
    }
}

fn decodeUnfurlThumb(a: *App, bytes: []const u8) ?win.HBITMAP {
    if (a.wic_factory == null or bytes.len == 0) return null;
    var stream: [*c]win.IWICStream = null;
    if (a.wic_factory.*.lpVtbl.*.CreateStream.?(a.wic_factory, &stream) < 0 or stream == null) return null;
    defer _ = stream.*.lpVtbl.*.Release.?(stream);
    if (stream.*.lpVtbl.*.InitializeFromMemory.?(stream, @constCast(bytes.ptr), @intCast(bytes.len)) < 0) return null;
    var decoder: [*c]win.IWICBitmapDecoder = null;
    if (a.wic_factory.*.lpVtbl.*.CreateDecoderFromStream.?(a.wic_factory, @ptrCast(stream), null, win.WICDecodeMetadataCacheOnLoad, &decoder) < 0 or decoder == null) return null;
    defer _ = decoder.*.lpVtbl.*.Release.?(decoder);
    var frame: [*c]win.IWICBitmapFrameDecode = null;
    if (decoder.*.lpVtbl.*.GetFrame.?(decoder, 0, &frame) < 0 or frame == null) return null;
    defer _ = frame.*.lpVtbl.*.Release.?(frame);
    var converter: [*c]win.IWICFormatConverter = null;
    if (a.wic_factory.*.lpVtbl.*.CreateFormatConverter.?(a.wic_factory, &converter) < 0 or converter == null) return null;
    defer _ = converter.*.lpVtbl.*.Release.?(converter);
    if (converter.*.lpVtbl.*.Initialize.?(converter, @ptrCast(frame), &win.GUID_WICPixelFormat32bppPBGRA, win.WICBitmapDitherTypeNone, null, 0, win.WICBitmapPaletteTypeCustom) < 0) return null;
    var scaler: [*c]win.IWICBitmapScaler = null;
    if (a.wic_factory.*.lpVtbl.*.CreateBitmapScaler.?(a.wic_factory, &scaler) < 0 or scaler == null) return null;
    defer _ = scaler.*.lpVtbl.*.Release.?(scaler);
    const target_w: u32 = 320;
    const target_h: u32 = 180;
    if (scaler.*.lpVtbl.*.Initialize.?(scaler, @ptrCast(converter), target_w, target_h, win.WICBitmapInterpolationModeFant) < 0) return null;
    var pixels: [target_w * target_h * 4]u8 = undefined;
    if (scaler.*.lpVtbl.*.CopyPixels.?(@ptrCast(scaler), null, target_w * 4, pixels.len, &pixels) < 0) return null;
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = @intCast(target_w);
    info.bmiHeader.biHeight = -@as(i32, @intCast(target_h));
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return null;
    if (bits == null) {
        _ = win.DeleteObject(bitmap);
        return null;
    }
    @memcpy(@as([*]u8, @ptrCast(bits.?))[0..pixels.len], &pixels);
    return bitmap;
}

fn applyUnfurlResult(a: *App, result: *UnfurlResult) void {
    defer {
        if (result.thumb) |bytes| std.heap.page_allocator.free(bytes);
        std.heap.page_allocator.destroy(result);
    }
    const provider: unfurl.Provider = @enumFromInt(result.provider);
    for (a.unfurl_entries[0..a.unfurl_entry_count]) |*entry| {
        if (entry.provider != provider) continue;
        if (!std.mem.eql(u8, entry.id.slice(), result.id[0..result.id_len])) continue;
        entry.status = if (result.ok) .ready else .failed;
        if (result.title_len > 0) entry.title.set(a.allocator, result.title[0..result.title_len]);
        if (result.author_len > 0) entry.author.set(a.allocator, result.author[0..result.author_len]);
        if (result.description_len > 0) entry.description.set(a.allocator, result.description[0..result.description_len]);
        if (result.play_len > 0 and unfurl.isStreamUrlAllowed(result.play_url[0..result.play_len])) {
            entry.play_url.set(a.allocator, result.play_url[0..result.play_len]);
        }
        if (result.thumb) |bytes| entry.thumb = decodeUnfurlThumb(a, bytes);
        saveUnfurlCache(a, entry, result);
        for (a.messages[0..a.message_count]) |*message| {
            if (message.unfurl_provider == provider and std.mem.eql(u8, message.unfurl_id.slice(), entry.id.slice())) message.measure_tag = 0;
        }
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        return;
    }
}

const message_bitmap_budget_bytes: usize = 24 * 1024 * 1024;

fn noteMessageBitmap(message: *Message) void {
    const a = app_ptr orelse return;
    if (message.bitmap != null) {
        const bytes: usize = @as(usize, @intCast(message.bitmap_width)) * @as(usize, @intCast(message.bitmap_height)) * 4;
        a.message_bitmap_lru.touch(@intFromPtr(message), bytes);
    } else {
        a.message_bitmap_lru.remove(@intFromPtr(message));
    }
}

fn dropMessageBitmap(message: *Message) void {
    if (message.bitmap) |bitmap| {
        _ = win.DeleteObject(bitmap);
        message.bitmap = null;
    }
    if (app_ptr) |a| a.message_bitmap_lru.remove(@intFromPtr(message));
}

const PROCESS_MEMORY_COUNTERS_EX = extern struct {
    cb: win.DWORD = @sizeOf(@This()),
    PageFaultCount: win.DWORD = 0,
    PeakWorkingSetSize: usize = 0,
    WorkingSetSize: usize = 0,
    QuotaPeakPagedPoolUsage: usize = 0,
    QuotaPagedPoolUsage: usize = 0,
    QuotaPeakNonPagedPoolUsage: usize = 0,
    QuotaNonPagedPoolUsage: usize = 0,
    PagefileUsage: usize = 0,
    PeakPagefileUsage: usize = 0,
    PrivateUsage: usize = 0,
};
extern "kernel32" fn K32GetProcessMemoryInfo(process: win.HANDLE, counters: *PROCESS_MEMORY_COUNTERS_EX, cb: win.DWORD) win.BOOL;

pub const MemorySnapshot = struct {
    working_set_bytes: usize = 0,
    private_bytes: usize = 0,
    module_count: u32 = 0,
};

pub fn readMemorySnapshot() MemorySnapshot {
    var result = MemorySnapshot{};
    var counters = PROCESS_MEMORY_COUNTERS_EX{};
    if (K32GetProcessMemoryInfo(win.GetCurrentProcess(), &counters, @sizeOf(PROCESS_MEMORY_COUNTERS_EX)) != 0) {
        result.working_set_bytes = counters.WorkingSetSize;
        result.private_bytes = counters.PrivateUsage;
    }
    const TH32CS_SNAPMODULE = 0x00000008;
    const snapshot = win.CreateToolhelp32Snapshot(TH32CS_SNAPMODULE, win.GetCurrentProcessId()) orelse return result;
    defer _ = win.CloseHandle(snapshot);
    var entry = std.mem.zeroes(win.MODULEENTRY32W);
    entry.dwSize = @sizeOf(win.MODULEENTRY32W);
    if (win.Module32FirstW(snapshot, &entry) == 0) return result;
    result.module_count = 1;
    while (win.Module32NextW(snapshot, &entry) != 0) result.module_count += 1;
    return result;
}

fn logStartupMemorySnapshot(a: *App) void {
    const snapshot = readMemorySnapshot();
    var buffer: [160]u8 = undefined;
    const line = std.fmt.bufPrint(&buffer, "memory: working set {d} KB, private {d} KB, {d} modules loaded", .{
        snapshot.working_set_bytes / 1024,
        snapshot.private_bytes / 1024,
        snapshot.module_count,
    }) catch "memory: snapshot failed to format";
    appendLaunchLog(a, line);
}

const mf_idle_unload_ticks: u32 = 60;

fn anyGifReaderOpen(a: *App) bool {
    for (a.messages[0..a.message_count]) |*message| {
        if (message.gif_reader != null) return true;
    }
    return false;
}

fn tickMediaFoundationIdle(a: *App) void {
    if (!mf_lazy.isStarted()) {
        a.mf_idle_ticks = 0;
        return;
    }
    if (a.mf_player != null or anyGifReaderOpen(a)) {
        a.mf_idle_ticks = 0;
        return;
    }
    a.mf_idle_ticks += 1;
    if (a.mf_idle_ticks >= mf_idle_unload_ticks) {
        mf_lazy.unloadIfStarted();
        a.mf_idle_ticks = 0;
    }
}

fn advanceGifs(a: *App) void {
    var changed = false;
    var dirty = win.RECT{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
    for (a.messages[0..a.message_count]) |*message| {
        if (!isGif(message) or message.gif_frame_count <= 1) continue;
        const hit = message.bubble_hit;
        if (hit.right <= hit.left or hit.bottom <= hit.top) continue;
        const previous = message.bitmap;
        message.bitmap = null;
        message.gif_frame_index = (message.gif_frame_index + 1) % message.gif_frame_count;
        ensureBitmap(a, message);
        if (message.bitmap) |replacement| {
            _ = replacement;
            if (previous) |bitmap| _ = win.DeleteObject(bitmap);
            changed = true;
            if (dirty.right > dirty.left and dirty.bottom > dirty.top) {
                dirty.left = @min(dirty.left, hit.left);
                dirty.top = @min(dirty.top, hit.top);
                dirty.right = @max(dirty.right, hit.right);
                dirty.bottom = @max(dirty.bottom, hit.bottom);
            } else dirty = hit;
        } else message.bitmap = previous;
    }
    if (changed) {
        if (a.canvas) |canvas| {
            if (dirty.right > dirty.left and dirty.bottom > dirty.top) {
                _ = win.InvalidateRect(canvas, &dirty, win.FALSE);
            } else _ = win.InvalidateRect(canvas, null, win.FALSE);
        }
    }
}

fn refreshMessages(a: *App) void {
    cancelSlackMark(a);
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) {
        a.messages_read_key = .{};
        a.messages_refresh_again = false;
        clearMessages(a);
        a.displayed_jid.set("");
        a.displayed_account.set("");
        a.displayed_timestamp.set("");
        a.msg_read_last_jid.set("");
        a.msg_read_attempts = 0;
        a.msg_read_retry_ticks = 0;
        return;
    }
    const chat = &a.chats[a.selected_chat];
    a.slack_history_hash = 0;
    if (chat.provider != .whatsapp or !std.mem.eql(u8, a.msg_read_last_jid.slice(), chat.jid.slice())) {
        a.msg_read_last_jid.set(chat.jid.slice());
        a.msg_read_attempts = 0;
        a.msg_read_retry_ticks = 0;
    }
    if (!unifiedHub(a) and chat.provider != .whatsapp) {
        a.messages_read_key = .{};
        a.messages_refresh_again = false;
        if (chat.provider == .telegram) return refreshTelegramMessages(a);
        return refreshSlackHistory(a);
    }
    if (chat_key.Key.eql(a.messages_read_key.key(), chat_key.of(chat)) and wacliPendingGet(a, .messages) > 0) {
        a.messages_refresh_again = true;
        return;
    }
    a.messages_refresh_again = false;
    const chat_changed = !chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat));
    if (chat_changed) {
        stopAudio(a);
        beginTranscriptionOpen(a);
    }
    if (msgCacheGet(a, chat_key.of(chat))) |cached| {
        _ = applyMessageData(a, cached, false);
    } else if (loadMsgCacheDisk(a, chat.jid.slice())) |cached| {
        defer a.allocator.free(cached);
        _ = applyMessageData(a, cached, false);
    } else if (chat_changed) {
        _ = applyMessageData(a, "{\"data\":{\"messages\":[]}}", false);
    }
    a.messages_gen += 1;
    a.messages_read_key.set(chat_key.of(chat));
    var job = WacliJob{ .account = a.cache_tag, .kind = .messages, .gen = a.messages_gen };
    job.provider = chat.provider;
    job.account = chat.account;
    job.jid.set(chat.jid.slice());
    wacliJobArgs(&job, &.{
        a.wacli_path, "--json", "--read-only", "messages", "list", "--chat", chat.jid.slice(), "--limit", "80",
    });
    if (!wacliEnqueue(a, job, true)) a.messages_read_key = .{};
}

fn reconcileOpenChat(a: *App) void {
    if (a.chat_selection_pending) return;
    if (a.selected_chat >= a.chat_count) {
        if (a.displayed_jid.len > 0) refreshMessages(a);
        return;
    }
    const chat = &a.chats[a.selected_chat];
    if (!chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat))) {
        refreshMessages(a);
        return;
    }
    if (!a.user_viewed) return;
    if (!unifiedHub(a) and chat.provider != .whatsapp) return;
    if (wacliPendingGet(a, .messages) > 0) return;
    if (!chat_reconcile.openChatStale(chat.jid.slice(), chat.timestamp.slice(), a.displayed_jid.slice(), a.displayed_timestamp.slice())) return;
    refreshMessages(a);
}

fn scheduleMessageReadRetry(a: *App) void {
    const attempt = a.msg_read_attempts + 1;
    const delay = chat_reconcile.retryDelayTicks(attempt) orelse return;
    a.msg_read_attempts = attempt;
    a.msg_read_retry_ticks = delay;
}

fn youSender(allocator: std.mem.Allocator) WideText(159) {
    var sender = WideText(159){};
    sender.set(allocator, "You");
    return sender;
}

fn resolveQuoteSender(a: *const App, chat_jid: []const u8, jid: []const u8) WideText(159) {
    if (jid.len == 0) return .{};
    for (a.messages[0..a.message_count]) |*prior| {
        if (!std.mem.eql(u8, prior.sender_jid.slice(), jid)) continue;
        if (prior.from_me) return youSender(a.allocator);
        if (prior.sender.len > 0) return prior.sender;
    }
    if (!std.mem.endsWith(u8, chat_jid, "@g.us") and std.mem.eql(u8, jidUser(jid), jidUser(chat_jid))) {
        if (a.selected_chat < a.chat_count) return a.chats[a.selected_chat].name;
    }
    return .{};
}

fn jidUser(jid: []const u8) []const u8 {
    const end = std.mem.indexOfAny(u8, jid, "@:") orelse jid.len;
    return jid[0..end];
}

fn reuseContactAvatar(a: *App, sender_jid: []const u8) ?*AvatarEntry {
    if (sender_jid.len == 0) return null;
    const sender_user = jidUser(sender_jid);
    if (sender_user.len == 0) return null;
    for (a.chats[0..a.chat_count]) |*chat| {
        const chat_jid = chat.jid.slice();
        if (std.mem.endsWith(u8, chat_jid, "@g.us")) continue;
        if (std.mem.eql(u8, jidUser(chat_jid), sender_user)) return avatarForChat(a, chat_jid);
    }
    return null;
}

fn avatarEntryForSender(a: *App, sender_jid: []const u8) ?*AvatarEntry {
    if (sender_jid.len == 0) return null;
    if (reuseContactAvatar(a, sender_jid)) |entry| return entry;
    return avatarForParticipant(a, sender_jid);
}

fn applyMessageData(a: *App, raw: []const u8, fresh_read: bool) bool {
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return false;
    defer parsed.deinit();
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) return false;
    const chat = &a.chats[a.selected_chat];
    const chat_changed = !chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat));
    const root = switch (parsed.value) {
        .object => |o| o,
        else => return false,
    };
    const data_value = root.get("data") orelse return false;
    const data_object = switch (data_value) {
        .object => |o| o,
        else => return false,
    };
    const list_value = data_object.get("messages") orelse return false;
    const list = switch (list_value) {
        .array => |items| items,
        else => return false,
    };
    if (!chat_changed and a.pending_send_count == 0 and a.failed_send_count == 0 and
        std.hash.Wyhash.hash(0, raw) == a.msg_applied_hash)
    {
        if (fresh_read) {
            a.displayed_timestamp = chat.timestamp;
            markChatRead(a);
        }
        drainMediaDownloads(a);
        return true;
    }
    var selected_id = Utf8Text(191){};
    if (a.selected_message) |selected| {
        if (selected < a.message_count) selected_id.set(a.messages[selected].id.slice());
    }
    clearMessages(a);
    a.selected_message = null;
    var united: std.ArrayList(std.json.Value) = .empty;
    defer united.deinit(a.allocator);
    var kept_rows: ?std.json.Parsed(std.json.Value) = null;
    defer if (kept_rows) |*kept| kept.deinit();
    var rows: []const std.json.Value = list.items;
    var merged = false;
    if (unifiedHub(a) and chat.provider == .whatsapp) {
        if (hubOlderFor(a, chat_key.of(chat)).rows) |kept_text| {
            if (std.json.parseFromSlice(std.json.Value, a.allocator, kept_text, .{ .allocate = .alloc_always })) |kept| {
                kept_rows = kept;
                if (kept.value == .array) {
                    if (hub.unite(a.allocator, list.items, kept.value.array.items, &united)) |_| {
                        rows = united.items;
                        merged = true;
                    } else |_| {
                        united.clearRetainingCapacity();
                    }
                }
            } else |_| {}
        }
    }
    const take = if (chat.provider == .slack and slackThreadsEnabled(a)) rows.len else @min(rows.len, max_messages);
    var source_index = take;
    while (source_index > 0) {
        source_index -= 1;
        const object = switch (rows[source_index]) {
            .object => |o| o,
            else => continue,
        };
        const id = getString(object, "MsgID");
        var text = getString(object, "DisplayText");
        if (text.len == 0) text = getString(object, "Text");
        text = message_filter.stripPlaceholder(text);
        const revoked = getBool(object, "Revoked");
        const media_type = getString(object, "MediaType");
        const filename = getString(object, "Filename");
        const local_path = getString(object, "LocalPath");
        const reaction_to = getString(object, "ReactionToID");
        if (!message_filter.isRealMessage(.{
            .id = id,
            .text = text,
            .media_type = media_type,
            .filename = filename,
            .local_path = local_path,
            .revoked = revoked,
            .reaction_to = reaction_to,
        })) continue;
        var message = Message{};
        message.id.set(id);
        if (chat.provider == .slack) {
            importCustomEmoji(a, chat.jid.slice(), object);
            message.thread_ts.set(getString(object, "thread_ts"));
            message.reply_count = @intCast(@max(0, getInt(object, "reply_count")));
            message.latest_reply.set(getString(object, "latest_reply"));
            if (slackThreadsEnabled(a) and slack.isThreadReply(id, message.thread_ts.slice())) {
                if (splitQuote(text, getString(object, "Text"))) |parts| text = parts.body;
            }
        }
        message.sender_jid.set(getString(object, "SenderJID"));
        message.sender.set(a.allocator, if (getBool(object, "FromMe")) "You" else getString(object, "SenderName"));
        message.revoked = revoked;
        if (message.revoked) {
            text = "Message deleted";
        } else if (!(chat.provider == .slack and slackThreadsEnabled(a) and slack.isThreadReply(id, message.thread_ts.slice())) and getString(object, "quoted_msg_id").len > 0) {
            if (splitQuote(text, getString(object, "Text"))) |parts| {
                const quoted_sender_jid = getString(object, "quoted_sender_jid");
                var quote_buffer: [slack.max_text + 1]u8 = undefined;
                const lookup = if (slackInstallation(a, chat.account.slice())) |installation| slackUserLookup(installation) else null;
                var emoji_buffer: [slack.max_text * 4 + 1]u8 = undefined;
                const quote = slack_emoji.replace(&emoji_buffer, parts.quote, .{ .context = a, .resolve = resolveCustomEmoji });
                message.quote.set(a.allocator, if (unifiedHub(a) and std.mem.startsWith(u8, chat.jid.slice(), "slack:")) slack.convertMrkdwn(&quote_buffer, quote, lookup) else parts.quote);
                message.quote_sender_jid.set(quoted_sender_jid);
                message.quote_sender = resolveQuoteSender(a, chat.jid.slice(), quoted_sender_jid);
                text = parts.body;
            }
        }
        if (unifiedHub(a) and std.mem.startsWith(u8, chat.jid.slice(), "slack:")) {
            const lookup = if (slackInstallation(a, chat.account.slice())) |installation| slackUserLookup(installation) else null;
            setSlackMessageText(a, &message, if (media_drain.isPlaceholder(media_type, text)) "" else text, lookup);
        } else {
            message.text.set(a.allocator, if (media_drain.isPlaceholder(media_type, text)) "" else text);
        }
        message.from_me = getBool(object, "FromMe");
        message.media_type.set(media_type);
        message.mime_type.set(getString(object, "MimeType"));
        message.local_path.set(a.allocator, local_path);
        message.media_size = media_drain.sizeFromJson(object);
        if (message.local_path.len > 0) {
            if (wideFileSize(message.local_path.ptr())) |size| {
                message.media_size = size;
                media_drain.forgetAttempt(&a.media_attempts, &a.media_attempt_count, played.Set.pairKey(chat.jid.slice(), id));
                clearMediaFailure(a, chat.jid.slice(), id);
                var alias_buffer: [1024]u8 = undefined;
                const playable = playableVideoPath(&alias_buffer, media_type, message.mime_type.slice(), local_path);
                if (playable.ptr != local_path.ptr) message.local_path.set(a.allocator, playable);
            } else message.local_path = .{};
        }
        message.filename.set(a.allocator, if (filename.len > 0) filename else std.fs.path.basename(local_path));
        message.reaction_to.set(reaction_to);
        message.reaction.set(a.allocator, getString(object, "ReactionEmoji"));
        if (message.from_me and reaction_to.len > 0) message.my_reaction.set(getString(object, "ReactionEmoji"));
        message.timestamp.set(getString(object, "Timestamp"));
        formatTime(&message.time, a.allocator, getString(object, "Timestamp"));
        if (chat.provider == .slack) {
            var reaction_buffer: [4096]u8 = undefined;
            message.reaction.set(a.allocator, slack_emoji.replace(&reaction_buffer, getString(object, "ReactionEmoji"), .{ .context = a, .resolve = resolveCustomEmoji }));
        }
        if (chat.provider == .slack and slackThreadsEnabled(a)) rememberSlackThreadRow(a, &message);
        if (source_index >= max_messages) continue;
        a.messages[a.message_count] = message;
        a.message_count += 1;
        const stored = &a.messages[a.message_count - 1];
        if (isAudio(stored)) loadTranscriptCache(a, stored);
    }
    if (merged) storeHubOlder(a, chat_key.of(chat), rows);
    var reaction_index: usize = 0;
    while (reaction_index < a.message_count) {
        const reaction_to = a.messages[reaction_index].reaction_to.slice();
        if (reaction_to.len == 0) {
            reaction_index += 1;
            continue;
        }
        for (a.messages[0..a.message_count]) |*target| {
            if (std.mem.eql(u8, target.id.slice(), reaction_to)) {
                target.reaction = a.messages[reaction_index].reaction;
                if (a.messages[reaction_index].from_me) target.my_reaction = a.messages[reaction_index].my_reaction;
                break;
            }
        }
        var shift = reaction_index;
        while (shift + 1 < a.message_count) : (shift += 1) a.messages[shift] = a.messages[shift + 1];
        a.message_count -= 1;
    }
    reapplyPendingReactions(a, chat.jid.slice());
    if (selected_id.len > 0) {
        for (a.messages[0..a.message_count], 0..) |*message, index| {
            if (std.mem.eql(u8, selected_id.slice(), message.id.slice())) {
                a.selected_message = index;
                break;
            }
        }
    }
    if (chat_changed) a.scroll_y = 0;
    a.displayed_jid.set(chat.jid.slice());
    a.displayed_account = chat.account;
    a.displayed_provider = chat.provider;
    if (fresh_read) a.displayed_timestamp.set(chat.timestamp.slice());
    for (a.pending_sends[0..a.pending_send_count]) |*pending| {
        if (a.message_count >= max_messages) break;
        appendWhatsAppPending(a, pending, true);
    }
    applySentVoice(a, chat.jid.slice());
    pruneFailedSends(a, chat_key.of(chat));
    for (a.failed_sends[0..a.failed_send_count]) |*failed| {
        if (a.message_count >= max_messages) break;
        appendWhatsAppFailed(a, failed);
    }
    a.msg_applied_hash = std.hash.Wyhash.hash(0, raw);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (fresh_read) markChatRead(a);
    drainMediaDownloads(a);
    if (a.message_count > 0) logStartupMilestone(a, .messages, if (fresh_read) "first messages shown (fresh)" else "first messages shown (cache)");
    return true;
}

fn enqueueCacheTagProbe(a: *App) void {
    a.cache_tag_gen += 1;
    if (wacliPendingGet(a, .cache_tag) > 0) {
        a.cache_tag_probe_again = true;
        return;
    }
    var job = WacliJob{ .account = a.cache_tag, .kind = .cache_tag, .gen = a.cache_tag_gen };
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "auth", "status" });
    _ = wacliEnqueue(a, job, false);
}

fn readsPendingBlockingSync(a: *const App) bool {
    if (a.pending_read_count == 0) return false;
    const now = win.GetTickCount64();
    for (a.read_backoff_until[0..a.pending_read_count]) |backoff| {
        if (backoff <= now) return true;
    }
    return false;
}

const sync_stderr_line_max_bytes = 400;
const sync_stderr_line_cap = 200;

fn syncStderrMain(a: *App, stderr: std.Io.File) void {
    defer stderr.close(a.io);
    var buffer: [4096]u8 = undefined;
    var reader = stderr.readerStreaming(a.io, &buffer);
    var logged: usize = 0;
    while (true) {
        const raw = reader.interface.takeDelimiter('\n') catch |err| switch (err) {
            error.StreamTooLong => {
                while (true) {
                    const byte = reader.interface.takeByte() catch return;
                    if (byte == '\n') break;
                }
                continue;
            },
            error.ReadFailed => return,
        };
        const line = std.mem.trimEnd(u8, raw orelse return, "\r");
        if (line.len == 0) continue;
        var parse_buffer: [16 * 1024]u8 = undefined;
        var parse_allocator = std.heap.FixedBufferAllocator.init(&parse_buffer);
        if (auth_status.syncLineLoggedOut(parse_allocator.allocator(), line)) a.sync_auth_lost.store(true, .release);
        if (logged >= sync_stderr_line_cap) continue;
        logged += 1;
        const text = line[0..@min(line.len, sync_stderr_line_max_bytes)];
        var event_buffer: [6 + sync_stderr_line_max_bytes]u8 = undefined;
        const event = std.fmt.bufPrint(&event_buffer, "sync: {s}", .{text}) catch continue;
        appendLaunchLog(a, event);
    }
}

fn startSync(a: *App) void {
    if (hubConfigured(a)) {
        startHubEvents(a);
        return;
    }
    if (verification_fixture) return;
    if (a.sync_logged_out or a.pairing_process != null) return;
    if (a.accounts_maintenance) {
        if (!whatsappStorePresent(a)) return;
        a.accounts_maintenance = false;
        a.cache_tag.set("");
        enqueueCacheTagProbe(a);
        a.last_sync_refresh_ms = null;
    }
    if (a.sync_child != null or a.read_child != null or readsPendingBlockingSync(a) or
        mediaBusy(a) or (a.send_child != null and a.send_direct) or
        a.archive_child != null or a.pending_archive_count > 0 or avatarBusy(a) or
        wacliPendingGet(a, .reaction) > 0) return;
    const now_ms = win.GetTickCount64();
    const refresh = sync_gate.gapElapsed(a.last_sync_refresh_ms, now_ms, sync_gate.sync_refresh_gap_ms);
    const base_argv = [_][]const u8{ a.wacli_path, "--events", "sync", "--follow", "--max-reconnect", "0", "--stale-threshold", "1m", "--download-media" };
    const refresh_argv = base_argv ++ [_][]const u8{ "--refresh-contacts", "--refresh-groups" };
    const child = child_process.spawn(a.io, .{
        .argv = if (refresh) &refresh_argv else &base_argv,
        .stdin = .ignore,
        .stdout = .ignore,
        .stderr = .pipe,
        .create_no_window = true,
    }) catch {
        setStatus(a, "Could not start live sync");
        return;
    };
    if (a.sync_job == null) {
        a.sync_job = win.CreateJobObjectW(null, null);
        if (a.sync_job) |job| {
            var info = std.mem.zeroes(win.JOBOBJECT_EXTENDED_LIMIT_INFORMATION);
            info.BasicLimitInformation.LimitFlags = win.JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
            _ = win.SetInformationJobObject(job, win.JobObjectExtendedLimitInformation, &info, @sizeOf(win.JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
        }
    }
    if (a.sync_job) |job| {
        if (child.id) |handle| _ = win.AssignProcessToJobObject(job, handle);
    }
    a.sync_child = child;
    if (a.media_burst_files > 0) a.media_resume_after_ms = now_ms + sync_gate.media_stop_gap_ms;
    a.media_burst_files = 0;
    const sync_stderr = a.sync_child.?.stderr;
    a.sync_child.?.stderr = null;
    if (sync_stderr) |file| {
        if (std.Thread.spawn(.{ .stack_size = 256 * 1024 }, syncStderrMain, .{ a, file })) |thread| {
            thread.detach();
        } else |_| {
            file.close(a.io);
        }
    }
    if (refresh) {
        a.last_sync_refresh_ms = now_ms;
        refreshContactsIndex(a);
    }
    appendLaunchLog(a, if (refresh) "sync: child started (refresh groups)" else "sync: child started");
    a.sync_started_secs = nowUnixSeconds();
    a.sync_heartbeat_ticks = 0;
    a.sync_heartbeat_mtime = 0;
    a.sync_heartbeat_unreadable = false;
    setStatus(a, "Live sync running");
}

fn stopSync(a: *App, reason: []const u8) void {
    if (a.sync_child) |*child| {
        child.kill(a.io);
        a.last_sync_stop_ms = win.GetTickCount64();
        var event_buffer: [96]u8 = undefined;
        const event = std.fmt.bufPrint(&event_buffer, "sync: child stopped ({s})", .{reason}) catch "sync: child stopped";
        appendLaunchLog(a, event);
    }
    a.sync_child = null;
}

const sync_heartbeat_check_ticks: u32 = 30;
const sync_heartbeat_stale_secs: i64 = 900;

fn syncHeartbeatMtime(a: *App) ?i64 {
    if (a.sync_heartbeat_path.len == 0) return null;
    var attributes = std.mem.zeroes(win.WIN32_FILE_ATTRIBUTE_DATA);
    if (win.GetFileAttributesExW(a.sync_heartbeat_path.ptr(), win.GetFileExInfoStandard, &attributes) == 0) return null;
    return filetimeToUnixSeconds(attributes.ftLastWriteTime);
}

fn checkSyncHeartbeat(a: *App) void {
    a.sync_heartbeat_ticks += 1;
    if (a.sync_heartbeat_ticks < sync_heartbeat_check_ticks) return;
    a.sync_heartbeat_ticks = 0;
    const mtime = syncHeartbeatMtime(a) orelse {
        if (!a.sync_heartbeat_unreadable) {
            a.sync_heartbeat_unreadable = true;
            appendLaunchLog(a, "sync: heartbeat unreadable");
        }
        return;
    };
    const previous = a.sync_heartbeat_mtime;
    a.sync_heartbeat_mtime = mtime;
    const now = nowUnixSeconds();
    const age = now - mtime;
    if (previous == 0 or mtime != previous) return;
    if (now - a.sync_started_secs <= sync_heartbeat_stale_secs) return;
    if (age <= sync_heartbeat_stale_secs) return;
    if (now - a.sync_heartbeat_restart_secs <= sync_heartbeat_stale_secs) return;
    var event_buffer: [64]u8 = undefined;
    const event = std.fmt.bufPrint(&event_buffer, "sync: heartbeat stale {d}s, restarting child", .{age}) catch return;
    appendLaunchLog(a, event);
    a.sync_heartbeat_restart_secs = now;
    stopSync(a, "heartbeat");
}

const logged_out_status = "WhatsApp logged out. Press Ctrl+K, Manage accounts, Reconnect WhatsApp";

fn markWhatsAppLoggedOut(a: *App) void {
    if (!a.sync_logged_out) appendLaunchLog(a, "sync: WhatsApp logged out, live sync halted");
    a.sync_logged_out = true;
    stopSync(a, "logged out");
    setStatus(a, logged_out_status);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn checkPairing(a: *App) void {
    const handle = a.pairing_process orelse return;
    if (win.WaitForSingleObject(handle, 0) != win.WAIT_OBJECT_0) return;
    _ = win.CloseHandle(handle);
    a.pairing_process = null;
    appendLaunchLog(a, "accounts: pairing window closed");
    a.cache_tag.set("");
    a.pairing_probe = true;
    enqueueCacheTagProbe(a);
    setStatus(a, "Pairing window closed - checking WhatsApp login");
}

fn applyPairingProbe(a: *App, ok: bool, data: []const u8) void {
    a.pairing_probe = false;
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, data, .{}) catch null;
    defer if (parsed) |*value| value.deinit();
    const unauthenticated = if (ok and parsed != null) auth_status.unauthenticated(parsed.?.value) else null;
    if (unauthenticated == true) {
        a.sync_logged_out = true;
        setStatus(a, "WhatsApp is still not linked. Press Ctrl+K, Manage accounts, Reconnect WhatsApp");
        return;
    }
    a.sync_logged_out = false;
    a.sync_fail_count = 0;
    a.last_sync_refresh_ms = null;
    startSync(a);
}

fn checkSync(a: *App) void {
    if (hubConfigured(a)) {
        if (a.hub_account.len == 0 and wacliPendingGet(a, .cache_tag) == 0) enqueueCacheTagProbe(a);
        startHubEvents(a);
        return;
    }
    checkPairing(a);
    if (a.sync_auth_lost.swap(false, .acq_rel)) markWhatsAppLoggedOut(a);
    if (mediaBusy(a) or a.read_child != null or (a.send_child != null and a.send_direct) or a.archive_child != null or a.pending_archive_count > 0 or avatarBusy(a)) return;
    if (a.sync_fail_count >= accounts.sync_halt_after_fast_deaths) return;
    if (a.sync_child) |*child| {
        if (child.id) |handle| {
            var code: win.DWORD = 0;
            if (win.GetExitCodeProcess(handle, &code) != 0 and code != win.STILL_ACTIVE) {
                _ = child.wait(a.io) catch {};
                a.sync_child = null;
                appendLaunchLog(a, "sync: child exited");
                const lived_secs = nowUnixSeconds() - a.sync_started_secs;
                if (lived_secs < accounts.sync_fast_death_secs) {
                    a.sync_fail_count += 1;
                } else {
                    a.sync_fail_count = 0;
                }
                if (accounts.syncDeathAction(lived_secs, a.sync_fail_count) == .probe_login) {
                    a.sync_auth_probe = true;
                    enqueueCacheTagProbe(a);
                    setStatus(a, "Live sync keeps stopping - checking WhatsApp login");
                    return;
                }
                setStatus(a, "Live sync stopped - restarting");
                startSync(a);
            } else checkSyncHeartbeat(a);
        }
    } else startSync(a);
}

fn applySyncAuthProbe(a: *App, ok: bool, data: []const u8) void {
    a.sync_auth_probe = false;
    if (!ok) {
        setStatus(a, "Live sync keeps stopping - run wacli doctor in a terminal");
        return;
    }
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, data, .{}) catch {
        setStatus(a, "Live sync keeps stopping - run wacli doctor in a terminal");
        return;
    };
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => {
            setStatus(a, "Live sync keeps stopping - run wacli doctor in a terminal");
            return;
        },
    };
    if (root.get("data") == null and root.get("authenticated") == null) {
        setStatus(a, "Live sync keeps stopping - run wacli doctor in a terminal");
        return;
    }
    const holder = root.get("data") orelse parsed.value;
    const authenticated = switch (holder) {
        .object => |object| object.get("authenticated") orelse std.json.Value{ .bool = false },
        else => std.json.Value{ .bool = false },
    };
    if (authenticated != .bool or authenticated.bool == false) {
        markWhatsAppLoggedOut(a);
        return;
    }
    setStatus(a, "Live sync keeps stopping - press Ctrl+K and pick Restart live sync");
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn setStatus(a: *App, text: []const u8) void {
    var buffer: [64]u8 = undefined;
    const progress = if (a.pending_archive_count > 0)
        archive_rules.progressStatus(&buffer, a.pending_archives[0].should_unarchive, a.archive_batch_total, a.pending_archive_count)
    else
        null;
    if (a.status) |status| {
        var wide_text = WideText(255){};
        wide_text.set(a.allocator, progress orelse text);
        var previous: [256]u16 = undefined;
        const length: usize = @intCast(win.GetWindowTextW(status, &previous, previous.len));
        if (std.mem.eql(u16, previous[0..length], wide_text.slice())) return;
        _ = win.SetWindowTextW(status, wide_text.ptr());
    }
}

fn sendKindName(pending: *const PendingSend) []const u8 {
    if (pending.ptt) return "voice";
    return if (pending.file.len > 0) "file" else "text";
}

fn logSendTiming(a: *App, outcome: []const u8, pending: PendingSend) void {
    var buffer: [160]u8 = undefined;
    const line = std.fmt.bufPrint(&buffer, "send: {s} kind={s} run={d}ms since_queued={d}s retries={d}", .{ outcome, sendKindName(&pending), win.GetTickCount64() -| a.send_started_ms, nowUnixSeconds() - pending.queued_unix, pending.retries }) catch "send: ok";
    appendLaunchLog(a, line);
}

fn completePendingSend(a: *App, delivered: bool) bool {
    const head = &a.pending_sends[0];
    if (!head.completed) head.delivered = delivered;
    head.completed = true;
    if (!persistOutbox(a)) {
        setStatus(a, "Could not save send completion; retrying journal");
        return false;
    }
    return true;
}

fn removeFirstPendingSend(a: *App, delivered: bool) void {
    if (a.pending_send_count == 0) return;
    if (!completePendingSend(a, delivered)) return;
    const head = &a.pending_sends[0];
    if (delivered and head.provider != .slack and !(unifiedHub(a) and (head.provider == .telegram or head.provider == .signal))) unarchiveSentChat(a, head.jid.slice());
    if (delivered and head.file.len > 0 and head.jid.len <= 191 and head.file.len <= 520) {
        var entry = voice_sent.Entry{ .queued_unix = head.queued_unix, .seconds = head.voice_seconds, .seq = head.seq, .voice = head.ptt };
        @memcpy(entry.jid[0..head.jid.len], head.jid.slice());
        entry.jid_len = head.jid.len;
        @memcpy(entry.file[0..head.file.len], head.file.slice());
        entry.file_len = head.file.len;
        voice_sent.push(&a.sent_voice, &a.sent_voice_count, entry);
    } else if (delivered and head.file.len > 0) deleteFileUtf8(head.file.slice());
    var index: usize = 1;
    while (index < a.pending_send_count) : (index += 1) {
        a.pending_sends[index - 1] = a.pending_sends[index];
    }
    a.pending_send_count -= 1;
    a.pending_sends[a.pending_send_count] = .{};
    persistFileOutbox(a);
}

fn playableVideoPath(buffer: []u8, media_type: []const u8, mime: []const u8, path: []const u8) []const u8 {
    if (!video_alias.needsAlias(media_type, mime, path)) return path;
    const alias = video_alias.aliasPath(buffer, path) orelse return path;
    if (fileExistsUtf8(alias)) return alias;
    const source = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, path) catch return path;
    defer std.heap.page_allocator.free(source);
    const target = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, alias) catch return path;
    defer std.heap.page_allocator.free(target);
    if (win.CreateHardLinkW(target.ptr, source.ptr, null) == 0) return path;
    return alias;
}

fn fileExistsUtf8(path_utf8: []const u8) bool {
    const wide = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, path_utf8) catch return false;
    defer std.heap.page_allocator.free(wide);
    return win.GetFileAttributesW(wide.ptr) != win.INVALID_FILE_ATTRIBUTES;
}

fn forgetFailedSendEntry(a: *App, entry: *const FailedSend) void {
    const index = (@intFromPtr(entry) - @intFromPtr(&a.failed_sends[0])) / @sizeOf(FailedSend);
    if (index >= a.failed_send_count) return;
    var shift = index;
    while (shift + 1 < a.failed_send_count) : (shift += 1) a.failed_sends[shift] = a.failed_sends[shift + 1];
    a.failed_send_count -= 1;
    a.failed_sends[a.failed_send_count] = .{};
    persistFileOutbox(a);
}

fn persistFileOutbox(a: *App) void {
    if (unifiedHub(a)) return;
    const path = messagesDirPath(a, "outbox-files.txt") orelse return;
    defer a.allocator.free(path);
    var body: std.ArrayList(u8) = .empty;
    defer body.deinit(a.allocator);
    for (a.failed_sends[0..a.failed_send_count]) |*failed| {
        if (!failed.is_file) continue;
        appendOutboxLine(a, &body, failed.jid.slice(), failed.ptt, failed.voice_seconds, failed.queued_unix, failed.file.slice(), failed.text.slice());
    }
    if (body.items.len == 0) {
        deleteFileUtf8(path);
        return;
    }
    _ = writeCacheFileAtomic(a, path, body.items);
}

fn appendOutboxLine(a: *App, body: *std.ArrayList(u8), jid: []const u8, ptt: bool, seconds: u32, queued_unix: i64, file: []const u8, caption: []const u8) void {
    const line = std.fmt.allocPrint(a.allocator, "{s}\t{d}\t{d}\t{d}\t{s}\t", .{ jid, @intFromBool(ptt), seconds, queued_unix, file }) catch return;
    defer a.allocator.free(line);
    body.appendSlice(a.allocator, line) catch return;
    for (caption) |byte| body.append(a.allocator, if (byte == '\t' or byte == '\n' or byte == '\r') ' ' else byte) catch return;
    body.append(a.allocator, '\n') catch return;
}

fn loadFileOutbox(a: *App) void {
    const path = messagesDirPath(a, "outbox-files.txt") orelse return;
    defer a.allocator.free(path);
    const data = readFileWin(a.allocator, path, 256 * 1024) orelse return;
    defer a.allocator.free(data);
    var lines = std.mem.splitScalar(u8, data, '\n');
    while (lines.next()) |line| {
        if (line.len == 0 or a.failed_send_count >= max_failed_sends) continue;
        var fields = std.mem.splitScalar(u8, line, '\t');
        const jid = fields.next() orelse continue;
        const ptt = fields.next() orelse continue;
        const seconds = fields.next() orelse continue;
        const queued = fields.next() orelse continue;
        const file = fields.next() orelse continue;
        const caption = fields.rest();
        if (jid.len == 0 or file.len == 0 or !fileExistsUtf8(file)) continue;
        var pending_file = false;
        for (a.pending_sends[0..a.pending_send_count]) |*pending| {
            if (std.mem.eql(u8, pending.file.slice(), file)) pending_file = true;
        }
        if (pending_file) continue;
        const entry = &a.failed_sends[a.failed_send_count];
        entry.* = .{};
        entry.jid.set(jid);
        entry.text.set(caption);
        entry.file.set(file);
        entry.is_file = true;
        entry.ptt = std.mem.eql(u8, ptt, "1");
        entry.voice_seconds = std.fmt.parseInt(u32, seconds, 10) catch 0;
        entry.queued_unix = std.fmt.parseInt(i64, queued, 10) catch 0;
        a.failed_send_count += 1;
    }
    if (a.failed_send_count > 0) appendLaunchLog(a, "outbox: restored unsent file sends");
}

fn failHeadPendingSend(a: *App, code: u32, ambiguous: bool, detail: []const u8, auth_failed: bool) void {
    a.pending_sends[0].retries += 1;
    a.pending_sends[0].ambiguous = ambiguous;
    const retries = a.pending_sends[0].retries;
    var log_buffer: [320]u8 = undefined;
    const head = &a.pending_sends[0];
    const event = std.fmt.bufPrint(&log_buffer, "send: failed exit {d} retry {d} kind={s} run={d}ms since_queued={d}s: {s}", .{ code, retries, sendKindName(head), win.GetTickCount64() -| a.send_started_ms, nowUnixSeconds() - head.queued_unix, detail }) catch "send: failed";
    appendLaunchLog(a, event);
    if (!auth_failed) {
        if (sendRetryDelayMs(retries)) |delay_ms| {
            a.pending_sends[0].not_before_ms = win.GetTickCount64() + delay_ms;
            var retry_buffer: [80]u8 = undefined;
            const status = std.fmt.bufPrint(&retry_buffer, "Sending, retry {d} of {d}", .{ retries, max_send_retries - 1 }) catch "Sending, retrying";
            setStatus(a, status);
            markPendingSendRetrying(a, &a.pending_sends[0]);
            startSync(a);
            return;
        }
    }
    const failed = a.pending_sends[0];
    markPendingSendFailed(a, &failed);
    rememberFailedSend(a, &failed);
    removeFirstPendingSend(a, false);
    restoreFailedSendText(a, &failed);
    var status_buffer: [400]u8 = undefined;
    const status = if (auth_failed)
        "WhatsApp logged out. Press Ctrl+K to reconnect"
    else
        std.fmt.bufPrint(&status_buffer, "Message to {s} failed to send - text copied back to the box", .{failed.jid.slice()}) catch "Message failed to send - text copied back to the box";
    setStatus(a, status);
    if (a.pending_send_count > 0) {
        startNextSend(a);
    } else {
        drainMediaDownloads(a);
        if (!auth_failed) startSync(a);
    }
}

fn sendReadyPending(a: *const App) bool {
    return a.pending_send_count > 0 and a.pending_sends[0].not_before_ms <= win.GetTickCount64();
}

const send_output_max_bytes = 64 * 1024;

const send_log_snippet_len = 200;
fn oneLineSnippet(buffer: []u8, text: []const u8) []const u8 {
    var length: usize = 0;
    for (text) |byte| {
        if (length >= buffer.len) break;
        buffer[length] = if (byte == '\n' or byte == '\r') ' ' else byte;
        length += 1;
    }
    while (length > 0 and (buffer[length - 1] & 0xC0) == 0x80) length -= 1;
    return std.mem.trim(u8, buffer[0..length], " ");
}

fn storedAfterQueued(stored_unix: i64, queued_unix: i64) bool {
    return stored_unix >= queued_unix - 5;
}

fn saveSentVoice(a: *App) void {
    var text = std.ArrayList(u8).empty;
    defer text.deinit(a.allocator);
    for (a.sent_voice[0..a.sent_voice_count]) |*entry| {
        if (entry.matched_len == 0) continue;
        text.print(a.allocator, "{s}\t{s}\t{s}\t{s}\n", .{ entry.jidSlice(), entry.matchedSlice(), entry.fileSlice(), if (entry.voice) "v" else "f" }) catch return;
    }
    const path = messagesDirPath(a, "voice-sent.txt") orelse return;
    defer a.allocator.free(path);
    _ = writeCacheFileAtomic(a, path, text.items);
}

fn loadSentVoice(a: *App) void {
    const path = messagesDirPath(a, "voice-sent.txt") orelse return;
    defer a.allocator.free(path);
    const contents = readFileWin(a.allocator, path, 64 * 1024) orelse return;
    defer a.allocator.free(contents);
    var lines = std.mem.tokenizeAny(u8, contents, "\r\n");
    while (lines.next()) |line| {
        const entry = voice_sent.parseLine(line) orelse continue;
        voice_sent.push(&a.sent_voice, &a.sent_voice_count, entry);
    }
}

fn applySentVoice(a: *App, jid: []const u8) void {
    for (a.sent_voice[0..a.sent_voice_count]) |*entry| {
        if (!std.mem.eql(u8, entry.jidSlice(), jid) or !fileExistsUtf8(entry.fileSlice())) continue;
        var found: ?*Message = null;
        for (a.messages[0..a.message_count]) |*message| {
            if (!message.from_me or message.send_state != .none) continue;
            const row_unix = media_age.unixSeconds(message.timestamp.slice()) orelse continue;
            if (entry.matched_len > 0) {
                if (!std.mem.eql(u8, message.id.slice(), entry.matchedSlice())) continue;
            } else {
                if (!voice_sent.rowMatchesEntry(true, message.media_type.slice(), row_unix, entry.queued_unix, entry.voice)) continue;
                var claimed = false;
                for (a.sent_voice[0..a.sent_voice_count]) |*other| {
                    if (other != entry and std.mem.eql(u8, other.matchedSlice(), message.id.slice())) claimed = true;
                }
                if (claimed) continue;
            }
            found = message;
            break;
        }
        if (found) |message| {
            if (entry.matched_len == 0 and message.id.len <= entry.matched_id.len) {
                @memcpy(entry.matched_id[0..message.id.len], message.id.slice());
                entry.matched_len = message.id.len;
                saveSentVoice(a);
            }
            message.local_path.set(a.allocator, entry.fileSlice());
            message.media_size = wideFileSize(message.local_path.ptr()) orelse 0;
            media_drain.forgetAttempt(&a.media_attempts, &a.media_attempt_count, played.Set.pairKey(jid, message.id.slice()));
            clearMediaFailure(a, jid, message.id.slice());
            if (message.filename.len == 0) message.filename.set(a.allocator, std.fs.path.basename(entry.fileSlice()));
            if (entry.voice) loadTranscriptCache(a, message);
            continue;
        }
        if (!entry.voice or entry.matched_len > 0 or a.message_count >= max_messages) continue;
        var message = Message{};
        message.from_me = true;
        message.sender.set(a.allocator, "You");
        message.media_type.set("audio");
        message.local_path.set(a.allocator, entry.fileSlice());
        var id_buffer: [32]u8 = undefined;
        message.id.set(std.fmt.bufPrint(&id_buffer, "sent-{d}", .{entry.seq}) catch "sent");
        const epoch = std.time.epoch.EpochSeconds{ .secs = @intCast(@max(0, entry.queued_unix)) };
        const year_day = epoch.getEpochDay().calculateYearDay();
        const month_day = year_day.calculateMonthDay();
        const day_seconds = epoch.getDaySeconds();
        var stamp: [24]u8 = undefined;
        if (std.fmt.bufPrint(&stamp, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z", .{
            year_day.year,
            month_day.month.numeric(),
            month_day.day_index + 1,
            day_seconds.getHoursIntoDay(),
            day_seconds.getMinutesIntoHour(),
            day_seconds.getSecondsIntoMinute(),
        })) |text| {
            message.timestamp.set(text);
            formatTime(&message.time, a.allocator, text);
        } else |_| {}
        a.messages[a.message_count] = message;
        a.message_count += 1;
        loadTranscriptCache(a, &a.messages[a.message_count - 1]);
    }
}

fn sentMessageExists(a: *App, key: chat_key.Key, text: []const u8, queued_unix: i64) bool {
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) return false;
    if (!chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), key) or !chat_key.Key.eql(chat_key.displayed(a), key)) return false;
    for (a.messages[0..a.message_count]) |*message| {
        if (!message.from_me or message.send_state != .none) continue;
        const stored = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch continue;
        defer a.allocator.free(stored);
        if (!std.mem.eql(u8, stored, text)) continue;
        const stored_unix = media_age.unixSeconds(message.timestamp.slice()) orelse continue;
        if (storedAfterQueued(stored_unix, queued_unix)) return true;
    }
    return false;
}

fn readChildOutput(a: *App, file: ?std.Io.File) ?[]u8 {
    const stream = file orelse return null;
    var buffer: [4096]u8 = undefined;
    var reader = stream.readerStreaming(a.io, &buffer);
    return reader.interface.allocRemaining(a.allocator, .limited(send_output_max_bytes)) catch null;
}

fn startNextSend(a: *App) void {
    if (a.outbox_load_failed) {
        setStatus(a, "Outbox could not be loaded; sends paused");
        return;
    }
    if (a.send_child != null or a.read_child != null or a.pending_send_count == 0) return;
    if (a.pending_sends[0].completed) {
        removeFirstPendingSend(a, a.pending_sends[0].delivered);
        return;
    }
    if (!hubConfigured(a) and a.sync_child == null and (a.read_child != null or mediaBusy(a) or avatarBusy(a) or a.archive_child != null)) return;
    if (win.GetTickCount64() < a.pending_sends[0].not_before_ms) return;
    bindOutboxAccount(a);
    const head = &a.pending_sends[0];
    if (a.slack_outbox_dirty or head.account.len == 0 or (!unifiedHub(a) and !std.mem.eql(u8, head.account.slice(), a.cache_tag.slice()))) return;
    if ((head.from_disk or (head.retries > 0 and head.ambiguous)) and
        sentMessageExists(a, chat_key.of(head), head.text.slice(), head.queued_unix))
    {
        appendLaunchLog(a, "send: matched an already-delivered message, not resending");
        removeFirstPendingSend(a, true);
        if (a.pending_send_count > 0) {
            startNextSend(a);
        } else {
            drainMediaDownloads(a);
            startSync(a);
            refreshChats(a);
            refreshMessages(a);
            setStatus(a, "Sent");
        }
        return;
    }
    const pending = &a.pending_sends[0];
    if (hubConfigured(a)) {
        startHubSend(a, pending);
        return;
    }
    var args: [send_args.max_args][]const u8 = undefined;
    const count = send_args.buildSend(&args, .{
        .wacli = a.wacli_path,
        .jid = pending.jid.slice(),
        .text = pending.text.slice(),
        .file = pending.file.slice(),
        .ptt = pending.ptt,
        .reply_to = pending.reply_to.slice(),
        .reply_sender = pending.reply_sender.slice(),
    });
    const child = child_process.spawn(a.io, .{
        .argv = args[0..count],
        .stdin = .ignore,
        .stdout = .pipe,
        .stderr = .pipe,
        .create_no_window = true,
    }) catch {
        failHeadPendingSend(a, 1, false, "spawn failed", false);
        return;
    };
    a.send_child = child;
    a.send_direct = a.sync_child == null;
    a.send_started_ms = win.GetTickCount64();
    var start_buffer: [120]u8 = undefined;
    if (std.fmt.bufPrint(&start_buffer, "send: start kind={s} waited_in_queue={d}s lock_wait={s}", .{ sendKindName(pending), nowUnixSeconds() - pending.queued_unix, send_args.lock_wait })) |start_line| appendLaunchLog(a, start_line) else |_| {}
    var status_buffer: [80]u8 = undefined;
    const status = std.fmt.bufPrint(&status_buffer, "Sending queued message, {d} remaining", .{a.pending_send_count}) catch "Sending queued message...";
    setStatus(a, status);
}

fn checkSend(a: *App) void {
    if (a.send_child) |*child| {
        const handle = child.id orelse return;
        var code: win.DWORD = 0;
        var timed_out = false;
        if (win.GetExitCodeProcess(handle, &code) == 0 or code == win.STILL_ACTIVE) {
            if (win.GetTickCount64() - a.send_started_ms <= send_timeout_ms) return;
            _ = child.kill(a.io);
            code = 1;
            timed_out = true;
        }
        const stdout_output = readChildOutput(a, child.stdout);
        defer if (stdout_output) |buffer| a.allocator.free(buffer);
        const stderr_output = readChildOutput(a, child.stderr);
        defer if (stderr_output) |buffer| a.allocator.free(buffer);
        if (!timed_out) _ = child.wait(a.io) catch {};
        a.send_child = null;
        a.send_direct = false;
        if (code == 0) {
            logSendTiming(a, "ok", a.pending_sends[0]);
            removeFirstPendingSend(a, true);
            if (a.pending_send_count > 0) {
                startNextSend(a);
            } else {
                drainMediaDownloads(a);
                startSync(a);
                refreshChats(a);
                refreshMessages(a);
                setStatus(a, "Sent");
            }
            return;
        }
        const has_lock = outputHasStoreLock(stdout_output) or outputHasStoreLock(stderr_output);
        const ambiguous = timed_out or !has_lock;
        const auth_failed = !sendFailureRetryable(a.sync_logged_out, stdout_output, stderr_output);
        var snippet_buffer: [send_log_snippet_len]u8 = undefined;
        const message_text = a.pending_sends[0].text.slice();
        const detail = if (timed_out)
            "timed out"
        else if (stderr_output) |text|
            (if (text.len == 0)
                "no error output"
            else if (message_text.len > 0 and std.mem.indexOf(u8, text, message_text) != null)
                "error output withheld (contains message text)"
            else
                oneLineSnippet(&snippet_buffer, text))
        else
            "no error output";
        failHeadPendingSend(a, code, ambiguous, detail, auth_failed);
        return;
    }
    if (a.pending_send_count == 0) return;
    startNextSend(a);
}

fn outputHasStoreLock(output: ?[]const u8) bool {
    const text = output orelse return false;
    return std.mem.indexOf(u8, text, "store is locked") != null or
        std.mem.indexOf(u8, text, "store lock") != null;
}

fn isAuthFailureText(text: []const u8) bool {
    return std.mem.indexOf(u8, text, "not authenticated") != null;
}

fn sendFailureRetryable(sync_logged_out: bool, stdout: ?[]const u8, stderr: ?[]const u8) bool {
    if (sync_logged_out) return false;
    if (stdout) |text| if (isAuthFailureText(text)) return false;
    if (stderr) |text| if (isAuthFailureText(text)) return false;
    return true;
}

fn deleteFileUtf8(path_utf8: []const u8) void {
    const wide = std.unicode.utf8ToUtf16LeAllocZ(std.heap.page_allocator, path_utf8) catch return;
    defer std.heap.page_allocator.free(wide);
    _ = win.DeleteFileW(wide.ptr);
}

fn discardStagedImage(a: *App) void {
    while (a.staged_images.count > 0) removeStagedImage(a, 0, true);
    layout(a, a.compose_client_width, a.compose_client_height);
    if (a.hwnd) |hwnd| _ = win.InvalidateRect(hwnd, null, win.FALSE);
}

fn removeStagedImage(a: *App, index: usize, discard: bool) void {
    const image = a.staged_images.remove(index) orelse return;
    if (image.preview) |bitmap| _ = win.DeleteObject(bitmap);
    if (discard and image.owned and image.path.len > 0) deleteFileUtf8(image.path.slice());
}

fn releaseStagedImage(a: *App) void {
    while (a.staged_images.count > 0) removeStagedImage(a, 0, false);
}

fn pasteDirectory(a: *App) ?[]u8 {
    const parent = std.fs.path.dirname(a.avatar_dir) orelse return null;
    const dir = std.fs.path.join(a.allocator, &.{ parent, "paste" }) catch return null;
    const cwd = std.Io.Dir.cwd();
    cwd.createDirPath(a.io, dir) catch {};
    return dir;
}

fn makePreviewBitmap(a: *App, path_wide: [*:0]const u16) ?win.HBITMAP {
    if (a.wic_factory == null) return null;
    var decoder: [*c]win.IWICBitmapDecoder = null;
    if (a.wic_factory.*.lpVtbl.*.CreateDecoderFromFilename.?(a.wic_factory, path_wide, null, win.GENERIC_READ, win.WICDecodeMetadataCacheOnLoad, &decoder) < 0 or decoder == null) return null;
    defer _ = decoder.*.lpVtbl.*.Release.?(decoder);
    var frame: [*c]win.IWICBitmapFrameDecode = null;
    if (decoder.*.lpVtbl.*.GetFrame.?(decoder, 0, &frame) < 0 or frame == null) return null;
    defer _ = frame.*.lpVtbl.*.Release.?(frame);
    var source_width: win.UINT = 0;
    var source_height: win.UINT = 0;
    if (frame.*.lpVtbl.*.GetSize.?(@ptrCast(frame), &source_width, &source_height) < 0 or source_width == 0 or source_height == 0) return null;
    var converter: [*c]win.IWICFormatConverter = null;
    if (a.wic_factory.*.lpVtbl.*.CreateFormatConverter.?(a.wic_factory, &converter) < 0 or converter == null) return null;
    defer _ = converter.*.lpVtbl.*.Release.?(converter);
    if (converter.*.lpVtbl.*.Initialize.?(converter, @ptrCast(frame), &win.GUID_WICPixelFormat32bppBGR, win.WICBitmapDitherTypeNone, null, 0, win.WICBitmapPaletteTypeCustom) < 0) return null;
    var source: *win.IWICBitmapSource = @ptrCast(converter);
    var scaler: [*c]win.IWICBitmapScaler = null;
    const fit = webp_detect.fitBox(source_width, source_height, 44, 44);
    if (fit.width < source_width or fit.height < source_height) {
        if (a.wic_factory.*.lpVtbl.*.CreateBitmapScaler.?(a.wic_factory, &scaler) < 0 or scaler == null) return null;
        if (scaler.*.lpVtbl.*.Initialize.?(scaler, source, fit.width, fit.height, win.WICBitmapInterpolationModeFant) < 0) {
            _ = scaler.*.lpVtbl.*.Release.?(scaler);
            return null;
        }
        source = @ptrCast(scaler);
    }
    defer {
        if (scaler) |scaled| _ = scaled.*.lpVtbl.*.Release.?(scaled);
    }
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = @intCast(fit.width);
    info.bmiHeader.biHeight = -@as(i32, @intCast(fit.height));
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return null;
    if (bits == null) {
        _ = win.DeleteObject(bitmap);
        return null;
    }
    if (source.*.lpVtbl.*.CopyPixels.?(source, null, fit.width * 4, fit.width * 4 * fit.height, @ptrCast(bits.?)) < 0) {
        _ = win.DeleteObject(bitmap);
        return null;
    }
    return bitmap;
}

fn writePngFile(a: *App, path_wide: [*:0]const u16, width: u32, height: u32, pixels: []const u8) bool {
    var stream: [*c]win.IWICStream = null;
    if (a.wic_factory.*.lpVtbl.*.CreateStream.?(a.wic_factory, &stream) < 0 or stream == null) return false;
    defer _ = stream.*.lpVtbl.*.Release.?(stream);
    if (stream.*.lpVtbl.*.InitializeFromFilename.?(stream, path_wide, win.GENERIC_WRITE | win.STGM_CREATE) < 0) return false;
    var encoder: [*c]win.IWICBitmapEncoder = null;
    if (a.wic_factory.*.lpVtbl.*.CreateEncoder.?(a.wic_factory, &win.GUID_ContainerFormatPng, null, &encoder) < 0 or encoder == null) return false;
    defer _ = encoder.*.lpVtbl.*.Release.?(encoder);
    if (encoder.*.lpVtbl.*.Initialize.?(encoder, @ptrCast(stream), win.WICBitmapEncoderNoCache) < 0) return false;
    var frame: [*c]win.IWICBitmapFrameEncode = null;
    if (encoder.*.lpVtbl.*.CreateNewFrame.?(encoder, &frame, null) < 0 or frame == null) return false;
    defer _ = frame.*.lpVtbl.*.Release.?(frame);
    if (frame.*.lpVtbl.*.Initialize.?(frame, null) < 0) return false;
    if (frame.*.lpVtbl.*.SetSize.?(frame, width, height) < 0) return false;
    var format = win.GUID_WICPixelFormat32bppBGRA;
    if (frame.*.lpVtbl.*.SetPixelFormat.?(frame, &format) < 0 or
        !std.mem.eql(u8, std.mem.asBytes(&format), std.mem.asBytes(&win.GUID_WICPixelFormat32bppBGRA))) return false;
    const stride = std.math.cast(u32, @as(usize, width) * 4) orelse return false;
    var row: usize = 0;
    while (row < height) : (row += 1) {
        if (frame.*.lpVtbl.*.WritePixels.?(frame, 1, stride, stride, @constCast(pixels[row * stride ..].ptr)) < 0) return false;
    }
    if (frame.*.lpVtbl.*.Commit.?(frame) < 0) return false;
    return encoder.*.lpVtbl.*.Commit.?(encoder) >= 0;
}

fn clipboardDibPixels(a: *App, handle: win.HANDLE) ?paste_image.Bitmap {
    const size = win.GlobalSize(handle);
    if (size == 0) return null;
    const locked = win.GlobalLock(handle) orelse return null;
    defer _ = win.GlobalUnlock(handle);
    const bytes: [*]const u8 = @ptrCast(locked);
    return paste_image.dibToBitmap(a.allocator, bytes[0..size]);
}

fn stageNewPath(a: *App, buffer: []u8, extension: []const u8) ?usize {
    var dir_buffer: [520]u8 = undefined;
    const dir = pasteDirectory(a) orelse return null;
    defer a.allocator.free(dir);
    const tick = win.GetTickCount64();
    var attempt: u32 = 0;
    while (attempt < 10) : (attempt += 1) {
        const name = std.fmt.bufPrint(&dir_buffer, "paste-{d}-{d}.{s}", .{ tick, attempt, extension }) catch return null;
        const full = std.fmt.bufPrint(buffer, "{s}\\{s}", .{ dir, name }) catch return null;
        const file = std.Io.Dir.cwd().createFile(a.io, full, .{ .exclusive = true }) catch continue;
        file.close(a.io);
        return full.len;
    }
    return null;
}

fn stageImageFromClipboard(a: *App) bool {
    if (a.compose == null or a.wic_factory == null or a.chat_count == 0 or a.selected_chat >= a.chat_count) return false;
    const png_format = win.RegisterClipboardFormatW(lit("PNG"));
    if (win.IsClipboardFormatAvailable(png_format) == 0 and win.IsClipboardFormatAvailable(win.CF_DIBV5) == 0 and win.IsClipboardFormatAvailable(win.CF_DIB) == 0 and win.IsClipboardFormatAvailable(win.CF_BITMAP) == 0 and win.IsClipboardFormatAvailable(win.CF_HDROP) == 0) return false;
    if (win.IsClipboardFormatAvailable(win.CF_UNICODETEXT) != 0 or win.IsClipboardFormatAvailable(win.CF_TEXT) != 0) return false;
    if (win.OpenClipboard(a.hwnd orelse null) == 0) return false;
    var path_buffer: [520]u8 = undefined;
    var path_len: usize = 0;
    var pixels: ?paste_image.Bitmap = null;
    var source_name: ?[]u8 = null;
    var png_data: ?[]u8 = null;
    defer if (png_data) |data| a.allocator.free(data);

    {
        defer _ = win.CloseClipboard();
        if (win.GetClipboardData(win.CF_HDROP)) |hdrop| {
            var name_buffer: [520]u16 = undefined;
            if (!shell_lazy.ensureShell32()) return true;
            const count = shell_lazy.dragQueryFileW.?(@ptrCast(@alignCast(hdrop)), 0xffffffff, null, 0);
            if (count > 1) {
                for (0..count) |index| {
                    const chars = shell_lazy.dragQueryFileW.?(@ptrCast(@alignCast(hdrop)), @intCast(index), &name_buffer, name_buffer.len);
                    if (chars == 0 or chars >= name_buffer.len) continue;
                    name_buffer[chars] = 0;
                    if (!stageAttachmentFile(a, @ptrCast(&name_buffer))) break;
                }
                return true;
            }
            const chars = shell_lazy.dragQueryFileW.?(@ptrCast(@alignCast(hdrop)), 0, &name_buffer, name_buffer.len);
            source_name = std.unicode.utf16LeToUtf8Alloc(a.allocator, name_buffer[0..chars]) catch {
                setStatus(a, "Clipboard holds no image to paste");
                return true;
            };
        } else if (win.GetClipboardData(png_format)) |handle| {
            const size = win.GlobalSize(handle);
            const locked = if (size > 0) win.GlobalLock(handle) else null;
            if (locked == null) {
                setStatus(a, "Clipboard holds no image to paste");
                return true;
            }
            defer _ = win.GlobalUnlock(handle);
            const bytes: [*]const u8 = @ptrCast(locked.?);
            png_data = a.allocator.dupe(u8, bytes[0..size]) catch {
                setStatus(a, "Could not stage the pasted image");
                return true;
            };
        } else if (win.GetClipboardData(win.CF_DIBV5)) |handle| {
            pixels = clipboardDibPixels(a, handle) orelse {
                setStatus(a, "Clipboard holds no image to paste");
                return true;
            };
        } else if (win.GetClipboardData(win.CF_DIB)) |handle| {
            pixels = clipboardDibPixels(a, handle) orelse {
                setStatus(a, "Clipboard holds no image to paste");
                return true;
            };
        } else if (win.GetClipboardData(win.CF_BITMAP)) |handle| {
            var bitmap_header: win.BITMAP = undefined;
            if (win.GetObjectW(handle, @sizeOf(win.BITMAP), &bitmap_header) == 0 or bitmap_header.bmWidth <= 0 or bitmap_header.bmHeight <= 0) {
                setStatus(a, "Clipboard holds no image to paste");
                return true;
            }
            const w: u32 = @intCast(bitmap_header.bmWidth);
            const h: u32 = @intCast(bitmap_header.bmHeight);
            var info = std.mem.zeroes(win.BITMAPINFO);
            info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
            info.bmiHeader.biWidth = @intCast(w);
            info.bmiHeader.biHeight = -@as(i32, @intCast(h));
            info.bmiHeader.biPlanes = 1;
            info.bmiHeader.biBitCount = 32;
            info.bmiHeader.biCompression = win.BI_RGB;
            const pixel_count = std.math.mul(usize, w, h) catch return true;
            const byte_count = std.math.mul(usize, pixel_count, 4) catch return true;
            const buffer = a.allocator.alloc(u8, byte_count) catch {
                setStatus(a, "Could not stage the pasted image");
                return true;
            };
            const screen_dc = win.GetDC(null);
            const rows = win.GetDIBits(screen_dc, @ptrCast(@alignCast(handle)), 0, h, buffer.ptr, &info, win.DIB_RGB_COLORS);
            if (screen_dc != null) _ = win.ReleaseDC(null, screen_dc);
            if (rows != h) {
                a.allocator.free(buffer);
                setStatus(a, "Clipboard holds no image to paste");
                return true;
            }
            var offset: usize = 0;
            while (offset < buffer.len) : (offset += 4) buffer[offset + 3] = 255;
            pixels = .{ .width = w, .height = h, .pixels = buffer };
        } else {
            setStatus(a, "Clipboard holds no image to paste");
            return true;
        }
    }

    if (source_name) |name_len| {
        defer a.allocator.free(name_len);
        var extension: []const u8 = "";
        const file_extension = std.fs.path.extension(name_len);
        for ([_][]const u8{ "png", "jpg", "jpeg" }) |ext| {
            if (file_extension.len == ext.len + 1 and std.ascii.eqlIgnoreCase(file_extension[1..], ext)) extension = ext;
        }
        if (selectedChatIsTelegram(a)) {
            _ = stageFile(a, name_len);
            return true;
        }
        if (extension.len == 0) {
            setStatus(a, "Only PNG and JPEG files can be pasted as images");
            return true;
        }
        path_len = stageNewPath(a, &path_buffer, extension) orelse {
            setStatus(a, "Could not stage the pasted image");
            return true;
        };
        const data = readFileWin(a.allocator, name_len, 32 * 1024 * 1024) orelse {
            deleteFileUtf8(path_buffer[0..path_len]);
            path_len = 0;
            setStatus(a, "Could not read the copied image file");
            return true;
        };
        defer a.allocator.free(data);
        std.Io.Dir.cwd().writeFile(a.io, .{ .sub_path = path_buffer[0..path_len], .data = data }) catch {
            deleteFileUtf8(path_buffer[0..path_len]);
            path_len = 0;
            setStatus(a, "Could not stage the pasted image");
            return true;
        };
    }

    if (png_data) |data| {
        path_len = stageNewPath(a, &path_buffer, "png") orelse {
            setStatus(a, "Could not stage the pasted image");
            return true;
        };
        std.Io.Dir.cwd().writeFile(a.io, .{ .sub_path = path_buffer[0..path_len], .data = data }) catch {
            deleteFileUtf8(path_buffer[0..path_len]);
            setStatus(a, "Could not stage the pasted image");
            return true;
        };
    }

    if (pixels) |bitmap| {
        defer a.allocator.free(bitmap.pixels);
        path_len = stageNewPath(a, &path_buffer, "png") orelse {
            setStatus(a, "Could not stage the pasted image");
            return true;
        };
        const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path_buffer[0..path_len]) catch {
            deleteFileUtf8(path_buffer[0..path_len]);
            setStatus(a, "Could not stage the pasted image");
            return true;
        };
        defer a.allocator.free(wide);
        if (!writePngFile(a, wide.ptr, bitmap.width, bitmap.height, bitmap.pixels)) {
            deleteFileUtf8(path_buffer[0..path_len]);
            setStatus(a, "Could not stage the pasted image");
            return true;
        }
    }

    if (path_len == 0) return true;
    const staged_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path_buffer[0..path_len]) catch {
        deleteFileUtf8(path_buffer[0..path_len]);
        setStatus(a, "Could not stage the pasted image");
        return true;
    };
    defer a.allocator.free(staged_wide);
    const preview = makePreviewBitmap(a, staged_wide.ptr) orelse {
        deleteFileUtf8(path_buffer[0..path_len]);
        setStatus(a, "Could not preview the pasted image");
        return true;
    };
    var image = StagedImage{};
    image.path.set(path_buffer[0..path_len]);
    image.provider = a.chats[a.selected_chat].provider;
    image.account = a.chats[a.selected_chat].account;
    image.jid = a.chats[a.selected_chat].jid;
    image.preview = preview;
    var bitmap: win.BITMAP = undefined;
    if (win.GetObjectW(preview, @sizeOf(win.BITMAP), &bitmap) != 0) {
        image.preview_width = bitmap.bmWidth;
        image.preview_height = bitmap.bmHeight;
    }
    if (!a.staged_images.add(image)) {
        _ = win.DeleteObject(preview);
        deleteFileUtf8(image.path.slice());
        setStatus(a, "Could not stage the pasted image");
        return true;
    }
    layout(a, a.compose_client_width, a.compose_client_height);
    if (a.hwnd) |hwnd| _ = win.InvalidateRect(hwnd, null, win.FALSE);
    setStatus(a, "Image ready... Enter sends, Esc discards");
    focusCompose(a);
    return true;
}

fn stageFile(a: *App, path: []const u8) bool {
    if (path.len > 519) {
        setStatus(a, "The file path is too long");
        return false;
    }
    if (a.selected_chat >= a.chat_count) return false;
    var image = StagedImage{ .owned = false };
    image.path.set(path);
    image.provider = a.chats[a.selected_chat].provider;
    image.account = a.chats[a.selected_chat].account;
    image.jid = a.chats[a.selected_chat].jid;
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path) catch return false;
    defer a.allocator.free(wide);
    image.preview = makePreviewBitmap(a, wide.ptr);
    if (image.preview) |preview| {
        var bitmap: win.BITMAP = undefined;
        if (win.GetObjectW(preview, @sizeOf(win.BITMAP), &bitmap) != 0) {
            image.preview_width = bitmap.bmWidth;
            image.preview_height = bitmap.bmHeight;
        }
    }
    if (!a.staged_images.add(image)) {
        if (image.preview) |preview| _ = win.DeleteObject(preview);
        setStatus(a, "Could not stage the attachment");
        return false;
    }
    layout(a, a.compose_client_width, a.compose_client_height);
    setStatus(a, "File attached - Enter sends, Esc discards");
    focusCompose(a);
    return true;
}

fn stageAttachmentFile(a: *App, path: [*:0]const u16) bool {
    const utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, std.mem.span(path)) catch return false;
    defer a.allocator.free(utf8);
    if (selectedChatIsTelegram(a) and !unifiedHub(a)) return stageFile(a, utf8);
    var buffer: [520]u8 = undefined;
    const extension = std.fs.path.extension(utf8);
    const length = stageNewPath(a, &buffer, if (extension.len > 1) extension[1..] else "bin") orelse return false;
    var copy_path = WideText(519){};
    copy_path.set(a.allocator, buffer[0..length]);
    if (win.CopyFileW(path, copy_path.ptr(), win.FALSE) == 0) {
        deleteFileUtf8(buffer[0..length]);
        setStatus(a, "Could not stage the attachment");
        return false;
    }
    if (!stageFile(a, buffer[0..length])) {
        deleteFileUtf8(buffer[0..length]);
        return false;
    }
    a.staged_images.items[a.staged_images.count - 1].owned = true;
    return true;
}

fn stageDroppedFiles(a: *App, drop: win.HDROP) void {
    if (!shell_lazy.ensureShell32()) return;
    const module = win.GetModuleHandleW(lit("shell32.dll")) orelse return;
    const finish: *const @TypeOf(win.DragFinish) = @ptrCast(@alignCast(win.GetProcAddress(module, "DragFinish") orelse return));
    defer finish(drop);
    if (attachUnavailableReason(a)) |reason| {
        setStatus(a, reason);
        return;
    }
    const count = shell_lazy.dragQueryFileW.?(drop, 0xffffffff, null, 0);
    for (0..count) |index| {
        var path: [520]u16 = undefined;
        const length = shell_lazy.dragQueryFileW.?(drop, @intCast(index), &path, path.len);
        if (length == 0 or length >= path.len) continue;
        path[length] = 0;
        if (!stageAttachmentFile(a, @ptrCast(&path))) break;
    }
}

fn voiceChatAllowed(a: *const App) bool {
    return a.selected_chat < a.chat_count and a.chats[a.selected_chat].provider == .whatsapp;
}

fn updateVoiceButton(a: *App) void {
    const button = a.voice_btn orelse return;
    const allowed = voiceChatAllowed(a);
    if (a.voice_active and !allowed) cancelVoice(a, "Voice note cancelled");
    if (allowed == a.voice_visible) return;
    a.voice_visible = allowed;
    _ = win.ShowWindow(button, if (allowed) win.SW_SHOW else win.SW_HIDE);
}

fn toggleVoice(a: *App) void {
    if (a.voice_active) {
        if (!a.voice_finishing) finishVoice(a);
        return;
    }
    if (!voiceChatAllowed(a)) return;
    if (a.pending_send_count >= max_pending_sends) {
        setStatus(a, "Send queue is full");
        return;
    }
    if (a.voice_session == null) a.voice_session = voice_capture.Session.create(a.allocator) catch null;
    const session = a.voice_session orelse {
        setStatus(a, "Could not start the microphone");
        return;
    };
    if (!session.start()) {
        setStatus(a, "Could not start the microphone");
        return;
    }
    a.voice_jid.set(a.chats[a.selected_chat].jid.slice());
    a.voice_origin = drafts.Identity.init(chat_key.of(&a.chats[a.selected_chat]));
    a.voice_reply_to = a.reply_to;
    a.voice_reply_sender = a.reply_sender;
    a.voice_active = true;
    a.voice_finishing = false;
    if (a.hwnd) |hwnd| _ = win.SetTimer(hwnd, timer_voice, recording_paint.tick_interval_ms, null);
    layout(a, a.compose_client_width, a.compose_client_height);
    setStatus(a, "Recording... Enter sends, Esc cancels");
    focusCompose(a);
}

fn finishVoice(a: *App) void {
    const session = a.voice_session orelse return;
    a.voice_finishing = true;
    session.finish();
    setStatus(a, "Preparing voice note...");
}

fn endVoiceUi(a: *App) void {
    a.voice_active = false;
    a.voice_finishing = false;
    if (a.hwnd) |hwnd| _ = win.KillTimer(hwnd, timer_voice);
    layout(a, a.compose_client_width, a.compose_client_height);
    if (a.voice_btn) |button| _ = win.InvalidateRect(button, null, win.TRUE);
}

fn cancelVoice(a: *App, status: []const u8) void {
    if (a.voice_session) |session| {
        session.cancel();
        session.reap();
    }
    endVoiceUi(a);
    setStatus(a, status);
}

fn invalidateRecordingTick(a: *App) void {
    const owner = a.hwnd orelse return;
    const button = a.voice_btn orelse return;
    var client: win.RECT = undefined;
    var strip: win.RECT = undefined;
    if (win.GetClientRect(owner, &client) == 0 or win.GetWindowRect(button, &strip) == 0) return;
    _ = win.MapWindowPoints(null, owner, @ptrCast(&strip), 2);
    const dirty = recording_paint.tickDirtyRect(client, strip) orelse return;
    var rect = dirty.rect;
    _ = win.MapWindowPoints(owner, button, @ptrCast(&rect), 2);
    _ = win.InvalidateRect(button, &rect, if (dirty.erase) win.TRUE else win.FALSE);
}

fn tickVoice(a: *App) void {
    if (!a.voice_active) return;
    const session = a.voice_session orelse return;
    if (!a.voice_finishing and (!voiceChatAllowed(a) or !chat_key.Key.eql(a.voice_origin.key(), chat_key.of(&a.chats[a.selected_chat])))) {
        cancelVoice(a, "Voice note cancelled: you switched chats");
        return;
    }
    switch (session.state()) {
        .recording, .encoding => invalidateRecordingTick(a),
        .ready => {
            const result = session.take();
            endVoiceUi(a);
            if (result) |note| {
                defer a.allocator.free(note.ogg);
                if (!queueVoiceNote(a, a.voice_jid.slice(), note.ogg, note.seconds, &note.waveform)) setStatus(a, "Could not send the voice note");
            }
        },
        .failed => {
            const too_short = session.elapsedMs() < 250;
            session.reap();
            endVoiceUi(a);
            setStatus(a, if (too_short) "Voice note too short" else "Could not record; check the microphone");
        },
        .idle => endVoiceUi(a),
    }
}

fn queueVoiceNote(a: *App, jid: []const u8, ogg: []const u8, seconds: u32, waveform: *const [64]u8) bool {
    _ = waveform;
    if (a.outbox_load_failed or a.pending_send_count >= max_pending_sends) return false;
    var path_buffer: [520]u8 = undefined;
    const path_len = stageNewPath(a, &path_buffer, "ogg") orelse return false;
    const path = path_buffer[0..path_len];
    std.Io.Dir.cwd().writeFile(a.io, .{ .sub_path = path, .data = ogg }) catch {
        deleteFileUtf8(path);
        return false;
    };
    const pending = &a.pending_sends[a.pending_send_count];
    pending.* = .{};
    pending.provider = a.voice_origin.key().provider;
    pending.account.set(a.voice_origin.key().account);
    pending.jid.set(jid);
    pending.file.set(path);
    pending.ptt = true;
    pending.voice_seconds = seconds;
    pending.reply_to = a.voice_reply_to;
    pending.reply_sender = a.voice_reply_sender;
    a.send_seq += 1;
    pending.seq = a.send_seq;
    pending.queued_unix = nowUnixSeconds();
    mintSendId(a, &pending.id);
    a.pending_send_count += 1;
    if (!persistOutbox(a)) {
        a.pending_send_count -= 1;
        pending.* = .{};
        deleteFileUtf8(path);
        return false;
    }
    if (a.draft_store.isOpen(a.voice_origin.key())) clearReply(a);
    a.user_viewed = true;
    a.scroll_y = 0;
    appendWhatsAppPending(a, pending, false);
    persistFileOutbox(a);
    if (a.hwnd) |main_hwnd| _ = win.InvalidateRect(main_hwnd, null, win.FALSE);
    startNextSend(a);
    return true;
}

fn sendMessage(a: *App) void {
    sendMessageFrom(a, false);
}

fn sendMessageFrom(a: *App, thread: bool) void {
    const compose = (if (thread) a.thread_compose else a.compose) orelse return;
    if (thread and (a.thread_parent.len == 0 or a.selected_chat >= a.chat_count or !chat_key.Key.eql(a.thread_origin.key(), chat_key.of(&a.chats[a.selected_chat])))) return;
    const reply_to = if (thread) a.thread_parent.slice() else a.reply_to.slice();
    if (verification_fixture and !hubConfigured(a)) return setStatus(a, "Verification is offline; sending is disabled");
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) return;
    if (a.outbox_load_failed) {
        setStatus(a, "Outbox could not be loaded; sends paused");
        return;
    }
    if (!selectedChatIsSlack(a) and a.pending_send_count >= max_pending_sends) {
        setStatus(a, "Send queue is full");
        return;
    }
    var wide_buffer: [drafts.max_text + 1]u16 = undefined;
    const length: usize = @intCast(win.GetWindowTextW(compose, &wide_buffer, wide_buffer.len));
    if (length == 0 and a.staged_images.count == 0) return;
    var staged_file: []const u8 = "";
    var attach_path_buffer: [1600]u8 = undefined;
    if (!thread and a.staged_images.count > 0) {
        if (chat_key.Key.eql(chat_key.of(&a.staged_images.items[0]), chat_key.of(&a.chats[a.selected_chat]))) {
            staged_file = a.staged_images.items[0].path.slice();
        } else discardStagedImage(a);
    }
    if (length == 0 and staged_file.len == 0) return;
    const text = std.unicode.utf16LeToUtf8Alloc(a.allocator, wide_buffer[0..length]) catch return;
    defer a.allocator.free(text);
    if (text.len > outbox.max_text_len) {
        setStatus(a, "Message exceeds 4095 UTF-8 bytes; shorten it first");
        return;
    }
    if (staged_file.len > 0 and (unifiedHub(a) or stagedFileGoesToWacli(a.chats[a.selected_chat].provider))) {
        const plan = a.staged_images.sendPlan(text, .single_file);
        const start = a.pending_send_count;
        if (plan.count > max_pending_sends - start) {
            setStatus(a, "Send queue is full");
            return;
        }
        for (plan.items[0..plan.count]) |send| {
            const image = &a.staged_images.items[send.first];
            const pending = &a.pending_sends[a.pending_send_count];
            pending.* = .{};
            pending.provider = image.provider;
            pending.account = image.account;
            pending.jid = image.jid;
            pending.text.set(send.text);
            pending.file = image.path;
            pending.reply_to.set(reply_to);
            pending.reply_sender.set(a.reply_sender.slice());
            a.send_seq += 1;
            pending.seq = a.send_seq;
            pending.queued_unix = nowUnixSeconds();
            mintSendId(a, &pending.id);
            a.pending_send_count += 1;
        }
        if (!persistOutbox(a)) {
            for (a.pending_sends[start..a.pending_send_count]) |*pending| pending.* = .{};
            a.pending_send_count = start;
            setStatus(a, "Could not save outbox; message not queued");
            return;
        }
        releaseStagedImage(a);
        if (!thread) clearReply(a);
        a.user_viewed = true;
        a.scroll_y = 0;
        for (a.pending_sends[start..a.pending_send_count]) |*pending| {
            forgetFailedSend(a, chat_key.of(pending), pending.text.slice());
            appendWhatsAppPending(a, pending, false);
        }
        persistFileOutbox(a);
        _ = win.SetWindowTextW(compose, lit(""));
        if (!thread) saveComposerDraft(a);
        layout(a, a.compose_client_width, a.compose_client_height);
        if (a.hwnd) |main_hwnd| _ = win.InvalidateRect(main_hwnd, null, win.FALSE);
        startNextSend(a);
        return;
    }

    if (selectedChatIsTelegram(a)) {
        const chat_id = tgSelectedChatId(a) orelse return;
        const client = a.telegram orelse return;
        const telegram_reply_to = std.fmt.parseInt(i64, reply_to, 10) catch 0;
        if (!thread and a.staged_images.count > 0) {
            const plan = a.staged_images.sendPlan(text, .single_file);
            for (plan.items[0..plan.count]) |send| {
                if (!client.sendFile(chat_id, a.staged_images.items[0].path.slice(), send.text, telegram_reply_to)) {
                    layout(a, a.compose_client_width, a.compose_client_height);
                    setStatus(a, "Telegram refused the message");
                    return;
                }
                removeStagedImage(a, 0, false);
                _ = win.SetWindowTextW(compose, lit(""));
                if (!thread) saveComposerDraft(a);
            }
        } else if (!client.sendTextReply(chat_id, text, telegram_reply_to)) {
            setStatus(a, "Telegram refused the message");
            return;
        }
        if (!thread) clearReply(a);
        _ = win.SetWindowTextW(compose, lit(""));
        if (!thread) saveComposerDraft(a);
        layout(a, a.compose_client_width, a.compose_client_height);
        focusCompose(a);
        setStatus(a, "Sending...");
        return;
    }
    if (selectedChatIsSlack(a)) {
        if (a.slack_outbox_count >= max_slack_outbox and !evictOldestFailedSlackOutbox(a)) {
            setStatus(a, "Send queue is full");
            return;
        }
        const chat = &a.chats[a.selected_chat];
        var attach: []const u8 = "";
        var staged_attach_buffer: [520]u8 = undefined;
        if (!thread and a.slack_attach.len > 0) {
            if (std.mem.eql(u8, a.slack_attach_account.slice(), chat.account.slice()) and std.mem.eql(u8, a.slack_attach_jid.slice(), chat.jid.slice())) {
                const attach_len = std.unicode.utf16LeToUtf8(&attach_path_buffer, a.slack_attach.slice()) catch 0;
                attach = attach_path_buffer[0..attach_len];
            } else setStatus(a, "Attached image dropped: chat changed");
        } else if (staged_file.len > 0) {
            if (slackAccountIsBridge(a, chat.account.slice())) {
                setStatus(a, "File upload not available over the Slack bridge");
                return;
            }
            const staged_len = @min(staged_file.len, staged_attach_buffer.len);
            @memcpy(staged_attach_buffer[0..staged_len], staged_file[0..staged_len]);
            attach = staged_attach_buffer[0..staged_len];
        }
        if (attach.len > outbox.max_file_len) {
            setStatus(a, "Attachment path is too long; file not queued");
            return;
        }
        if (attach.len > 0) {
            var plan = a.staged_images.sendPlan(text, .single_file);
            if (staged_file.len == 0) {
                plan.items[0] = .{ .first = 0, .count = 1, .text = text };
                plan.count = 1;
            }
            while (plan.count > max_slack_outbox - a.slack_outbox_count) {
                if (!evictOldestFailedSlackOutbox(a)) {
                    setStatus(a, "Send queue is full");
                    return;
                }
            }
            const start = a.slack_outbox_count;
            for (plan.items[0..plan.count]) |send| {
                const slot = &a.slack_outbox[a.slack_outbox_count];
                slot.* = .{};
                mintSendId(a, &slot.entry.id);
                slot.entry.provider = .slack;
                slot.entry.account.set(chat.account.slice());
                slot.entry.jid.set(chat.jid.slice());
                slot.entry.text.set(send.text);
                slot.entry.file.set(if (staged_file.len > 0) a.staged_images.items[send.first].path.slice() else attach);
                slot.entry.reply_to.set(reply_to);
                slot.entry.queued_unix = nowUnixSeconds();
                a.slack_outbox_count += 1;
            }
            if (!persistOutbox(a)) {
                for (a.slack_outbox[start..a.slack_outbox_count]) |*slot| slot.* = .{};
                a.slack_outbox_count = start;
                setStatus(a, "Could not save outbox; message not queued");
                return;
            }
            for (a.slack_outbox[start..a.slack_outbox_count]) |*slot| enqueueSlackOutbox(a, slot);
        } else {
            var uuid_bytes: [16]u8 = undefined;
            a.io.random(&uuid_bytes);
            uuid_bytes[6] = (uuid_bytes[6] & 0x0f) | 0x40;
            uuid_bytes[8] = (uuid_bytes[8] & 0x3f) | 0x80;
            var cmid_buffer: [36]u8 = undefined;
            const client_msg_id = std.fmt.bufPrint(&cmid_buffer, "{x:0>2}{x:0>2}{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}-{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}{x:0>2}", .{
                uuid_bytes[0],  uuid_bytes[1],  uuid_bytes[2],  uuid_bytes[3],
                uuid_bytes[4],  uuid_bytes[5],  uuid_bytes[6],  uuid_bytes[7],
                uuid_bytes[8],  uuid_bytes[9],  uuid_bytes[10], uuid_bytes[11],
                uuid_bytes[12], uuid_bytes[13], uuid_bytes[14], uuid_bytes[15],
            }) catch "";
            const slot = &a.slack_outbox[a.slack_outbox_count];
            slot.* = .{};
            mintSendId(a, &slot.entry.id);
            slot.entry.provider = .slack;
            slot.entry.account.set(chat.account.slice());
            slot.entry.jid.set(chat.jid.slice());
            slot.entry.text.set(text);
            slot.entry.reply_to.set(reply_to);
            slot.entry.client_msg_id.set(client_msg_id);
            slot.entry.queued_unix = nowUnixSeconds();
            a.slack_outbox_count += 1;
            if (!persistOutbox(a)) {
                a.slack_outbox_count -= 1;
                slot.* = .{};
                setStatus(a, "Could not save outbox; message not queued");
                return;
            }
            enqueueSlackOutbox(a, slot);
            appendSlackPending(a, text, client_msg_id, reply_to);
        }
        if (staged_file.len > 0) releaseStagedImage(a);
        if (!thread) {
            a.slack_attach.set(a.allocator, "");
            a.slack_attach_jid.set("");
        }
        if (!thread) clearReply(a);
        a.user_viewed = true;
        _ = win.SetWindowTextW(compose, lit(""));
        if (!thread) saveComposerDraft(a);
        layout(a, a.compose_client_width, a.compose_client_height);
        if (thread) {
            _ = win.SetFocus(compose);
        } else focusCompose(a);
        return;
    }

    const pending = &a.pending_sends[a.pending_send_count];
    pending.provider = a.chats[a.selected_chat].provider;
    pending.account = a.chats[a.selected_chat].account;
    pending.jid.set(a.chats[a.selected_chat].jid.slice());
    pending.text.set(text);
    pending.reply_to.set(reply_to);
    pending.reply_sender.set(a.reply_sender.slice());
    pending.file = .{};
    a.send_seq += 1;
    pending.seq = a.send_seq;
    pending.queued_unix = nowUnixSeconds();
    mintSendId(a, &pending.id);
    a.pending_send_count += 1;
    if (!persistOutbox(a)) {
        a.pending_send_count -= 1;
        pending.* = .{};
        setStatus(a, "Could not save outbox; message not queued");
        return;
    }
    if (!thread) clearReply(a);
    forgetFailedSend(a, chat_key.of(pending), pending.text.slice());
    a.user_viewed = true;
    a.scroll_y = 0;
    appendWhatsAppPending(a, pending, false);
    _ = win.SetWindowTextW(compose, lit(""));
    if (!thread) saveComposerDraft(a);
    if (thread) {
        _ = win.SetFocus(compose);
    } else focusCompose(a);
    startNextSend(a);
}

fn clearReply(a: *App) void {
    a.reply_to.set("");
    a.reply_sender.set("");
}

fn startReply(a: *App) void {
    const selected = a.selected_message orelse {
        setStatus(a, "Select a message with right-click or Ctrl+Tab");
        return;
    };
    if (selected >= a.message_count or a.selected_chat >= a.chat_count) return;
    const message = &a.messages[selected];
    a.reply_to.set(message.id.slice());
    a.reply_sender.set(message.sender_jid.slice());
    const sender_bytes = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.sender.slice()) catch {
        setStatus(a, "Reply ready... Esc in the composer cancels");
        return;
    };
    defer a.allocator.free(sender_bytes);
    const shown = if (sender_bytes.len == 0) "message" else sender_bytes[0..@min(sender_bytes.len, 64)];
    var status_buffer: [160]u8 = undefined;
    const status = std.fmt.bufPrint(&status_buffer, "Replying to {s}... Esc in the composer cancels", .{shown}) catch return;
    setStatus(a, status);
    focusCompose(a);
}

fn focusCompose(a: *App) void {
    if (a.compose) |compose| {
        _ = win.SetFocus(compose);
        const length: usize = @intCast(win.GetWindowTextLengthW(compose));
        const caret: isize = @intCast(length);
        _ = win.SendMessageW(compose, win.EM_SETSEL, @bitCast(caret), @bitCast(caret));
    }
}

fn composerText(a: *App) ?[]u8 {
    const compose = a.compose orelse return null;
    const length: usize = @intCast(win.GetWindowTextLengthW(compose));
    const wide = a.allocator.alloc(u16, length + 1) catch return null;
    defer a.allocator.free(wide);
    const got: usize = @intCast(win.GetWindowTextW(compose, wide.ptr, @intCast(wide.len)));
    return std.unicode.utf16LeToUtf8Alloc(a.allocator, wide[0..got]) catch null;
}

fn handleComposerPaste(a: *App, key: u32, control: bool, shift: bool, alt: bool) bool {
    if (!edit_contract.pasteShortcut(key, control, shift, alt)) return false;
    if (!stageImageFromClipboard(a)) pasteComposerText(a);
    return true;
}

fn pasteComposerText(a: *App) void {
    const origin = a.draft_store.open orelse return;
    const compose = a.compose orelse return;
    const text = blk: {
        if (win.OpenClipboard(a.hwnd orelse null) == 0) return;
        defer _ = win.CloseClipboard();
        const handle = win.GetClipboardData(win.CF_UNICODETEXT) orelse return;
        const size = win.GlobalSize(handle) / @sizeOf(u16);
        const locked = win.GlobalLock(handle) orelse return;
        defer _ = win.GlobalUnlock(handle);
        const wide: [*]const u16 = @ptrCast(@alignCast(locked));
        const length = std.mem.indexOfScalar(u16, wide[0..@min(size, drafts.max_text + 1)], 0) orelse return;
        break :blk std.unicode.utf16LeToUtf8Alloc(a.allocator, wide[0..length]) catch return;
    };
    defer a.allocator.free(text);
    if (a.draft_store.isOpen(origin.key())) {
        const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, text) catch return;
        defer a.allocator.free(wide);
        _ = win.SendMessageW(compose, win.EM_REPLACESEL, win.TRUE, @bitCast(@intFromPtr(wide.ptr)));
        saveComposerDraft(a);
    } else {
        _ = a.draft_store.append(a.allocator, origin.key(), "", text, false) catch {
            setStatus(a, "Could not paste: draft limit reached");
            return;
        };
        if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
    }
    persistDrafts(a);
}

fn saveComposerDraft(a: *App) void {
    if (a.draft_loading) return;
    const open = if (a.draft_store.open) |*key| key.key() else {
        setComposerDraft(a, "");
        return;
    };
    const text = composerText(a) orelse return;
    defer a.allocator.free(text);
    a.draft_store.save(a.allocator, open, text) catch {
        setComposerDraft(a, a.draft_store.get(open));
        setStatus(a, "Could not save draft: storage limit reached");
        return;
    };
    if (a.draft_store.get(open).len == 0) persistDrafts(a);
    if (a.chats_hwnd) |list| {
        if (visibleChatIndex(a, open)) |index| {
            var row: win.RECT = undefined;
            if (win.SendMessageW(list, win.LB_GETITEMRECT, index, @bitCast(@intFromPtr(&row))) != win.LB_ERR) _ = win.InvalidateRect(list, &row, win.FALSE);
        }
    }
}

fn persistDrafts(a: *App) void {
    if (!a.draft_store.dirty) return;
    const path = messagesDirPath(a, "drafts.json") orelse return;
    defer a.allocator.free(path);
    const bytes = a.draft_store.encode(a.allocator) catch return;
    defer a.allocator.free(bytes);
    if (writeCacheFileAtomic(a, path, bytes)) a.draft_store.dirty = false;
}

fn loadDrafts(a: *App) void {
    const path = messagesDirPath(a, "drafts.json") orelse return;
    defer a.allocator.free(path);
    const bytes = readFileWin(a.allocator, path, drafts.max_file) orelse return;
    defer a.allocator.free(bytes);
    a.draft_store.load(a.allocator, bytes);
}

fn setComposerDraft(a: *App, text: []const u8) void {
    const compose = a.compose orelse return;
    var wide: [drafts.max_text + 1]u16 = undefined;
    const length = std.unicode.utf8ToUtf16Le(wide[0..drafts.max_text], text) catch 0;
    wide[length] = 0;
    a.draft_loading = true;
    defer a.draft_loading = false;
    _ = win.SetWindowTextW(compose, &wide);
    _ = win.SendMessageW(compose, win.EM_EMPTYUNDOBUFFER, 0, 0);
    _ = win.SendMessageW(compose, win.EM_SETSEL, length, @intCast(length));
    _ = win.SendMessageW(compose, win.EM_SCROLLCARET, 0, 0);
    layout(a, a.compose_client_width, a.compose_client_height);
}

fn switchComposerDraft(a: *App) void {
    updateAttachButton(a);
    const next: ?chat_key.Key = if (a.selected_chat < a.chat_count and a.chats[a.selected_chat].account.len > 0) chat_key.of(&a.chats[a.selected_chat]) else null;
    if (a.draft_store.open) |*open| {
        if (next) |key| {
            if (chat_key.Key.eql(open.key(), key)) return;
        }
    } else if (next == null) return;
    const text = composerText(a);
    defer if (text) |value| a.allocator.free(value);
    const previous = if (a.draft_store.open) |*open| a.draft_store.get(open.key()) else "";
    const restored = a.draft_store.switchTo(a.allocator, next, text orelse previous) catch blk: {
        a.draft_store.open = if (next) |key| drafts.Identity.init(key) else null;
        setStatus(a, "Could not save previous draft: storage limit reached");
        break :blk if (next) |key| a.draft_store.get(key) else "";
    };
    clearReply(a);
    shortcodeHide(a);
    setComposerDraft(a, restored);
    if (a.compose) |compose| _ = win.EnableWindow(compose, if (next != null) win.TRUE else win.FALSE);
    persistDrafts(a);
    if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
}

fn ensureDictation(a: *App) ?*dictation.Session {
    if (a.dictation_session) |session| return session;
    a.dictation_session = dictation.Session.create(a.allocator) catch null;
    return a.dictation_session;
}

fn toggleDictation(a: *App) void {
    if (!a.deepgram_configured) {
        setStatus(a, "Set DEEPGRAM_API_KEY to enable dictation");
        return;
    }
    const session = ensureDictation(a) orelse {
        setStatus(a, "Could not initialize dictation");
        return;
    };
    switch (session.state()) {
        .idle, .failed => {
            if (a.selected_chat >= a.chat_count or a.chats[a.selected_chat].account.len == 0) return;
            if (session.start(a.deepgram_key, a.dictation_language, chat_key.of(&a.chats[a.selected_chat]))) {
                updateDictateButton(a, .recording);
                setStatus(a, "Listening... press Ctrl+D to stop");
            } else setStatus(a, "Could not start microphone capture");
        },
        .recording => {
            session.requestStop();
            updateDictateButton(a, .transcribing);
            setStatus(a, "Transcribing...");
        },
        .transcribing => setStatus(a, "Transcription is still running"),
        .ready => {},
    }
}

fn updateDictation(a: *App) void {
    const session = a.dictation_session orelse return;
    const state = session.state();
    if (state == .ready) {
        var transcript_buffer: [8192]u8 = undefined;
        if (session.takeTranscript(&transcript_buffer)) |transcript| {
            const composer = composerText(a) orelse return;
            defer a.allocator.free(composer);
            const same_chat = a.draft_store.isOpen(session.origin.key());
            if (same_chat) {
                const compose = a.compose orelse return;
                var start: u32 = 0;
                var end: u32 = 0;
                _ = win.SendMessageW(compose, win.EM_GETSEL, @intFromPtr(&start), @bitCast(@intFromPtr(&end)));
                const composer_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, composer) catch return;
                defer a.allocator.free(composer_wide);
                const padding = edit_contract.dictationPadding(composer_wide, start, end);
                var wide: [8195]u16 = undefined;
                const offset: usize = @intFromBool(padding.before);
                if (padding.before) wide[0] = ' ';
                const count = std.unicode.utf8ToUtf16Le(wide[offset .. wide.len - 2], transcript) catch return;
                var length = offset + count;
                if (padding.after) {
                    wide[length] = ' ';
                    length += 1;
                }
                wide[length] = 0;
                _ = win.SendMessageW(compose, win.EM_REPLACESEL, win.TRUE, @bitCast(@intFromPtr(&wide)));
                _ = win.SendMessageW(compose, win.EM_SCROLLCARET, 0, 0);
                _ = win.SetFocus(compose);
            } else {
                _ = a.draft_store.transcript(a.allocator, session.origin.key(), composer, transcript) catch {
                    setStatus(a, "Could not insert dictation: draft limit reached");
                    return;
                };
            }
            persistDrafts(a);
            if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
            setStatus(a, if (same_chat) "Dictation inserted" else "Dictation saved to its chat draft");
        }
        updateDictateButton(a, .idle);
        return;
    }
    if (state == a.last_dictation_state) return;
    updateDictateButton(a, state);
    switch (state) {
        .idle, .recording => {},
        .transcribing => {
            setStatus(a, "Transcribing...");
        },
        .failed => {
            setStatus(a, "Dictation failed; check the microphone and DEEPGRAM_API_KEY");
        },
        .ready => unreachable,
    }
}

fn selectChat(a: *App, delta: i32, wrap: bool) void {
    _ = clearBulkSelection(a);
    if (a.chat_count == 0) return;
    clearReply(a);
    var next: i32 = @intCast(a.selected_chat);
    next += delta;
    const count: i32 = @intCast(a.chat_count);
    if (wrap) {
        if (next < 0) next = count - 1;
        if (next >= count) next = 0;
    } else {
        next = std.math.clamp(next, 0, count - 1);
    }
    if (next != a.selected_chat) discardStagedImage(a);
    cancelSlackMark(a);
    a.selected_chat = @intCast(next);
    switchComposerDraft(a);
    a.user_viewed = true;
    if (a.chats_hwnd) |list| {
        _ = win.SendMessageW(list, win.LB_SETCURSEL, a.selected_chat, 0);
    }
    a.chat_selection_pending = true;
    if (a.hwnd) |hwnd| {
        _ = win.KillTimer(hwnd, timer_chat_select);
        _ = win.SetTimer(hwnd, timer_chat_select, 120, null);
    }
}

fn messageBubbleWidth(a: *const App, available_width: i32) i32 {
    const chat_jid = if (a.displayed_jid.len > 0)
        a.displayed_jid.slice()
    else if (a.chat_count > 0 and a.selected_chat < a.chat_count)
        a.chats[a.selected_chat].jid.slice()
    else
        "";
    const left_inset = px(a, if (std.mem.endsWith(u8, chat_jid, "@g.us")) @as(i32, 62) else @as(i32, 24));
    const max_width = @max(1, available_width - left_inset - px(a, 24));
    return @min(max_width, std.math.clamp(@divTrunc(available_width * 7, 10), px(a, 280), px(a, 620)));
}

fn scrollToSelectedMessage(a: *App) void {
    const selected = a.selected_message orelse return;
    if (selected >= a.message_count) return;
    const canvas = a.canvas orelse return;
    const hdc = win.GetDC(canvas) orelse return;
    defer _ = win.ReleaseDC(canvas, hdc);
    var client: win.RECT = undefined;
    _ = win.GetClientRect(canvas, &client);
    const bubble_width = messageBubbleWidth(a, client.right - client.left);
    ensureBitmap(a, &a.messages[selected]);
    var total_height: i32 = px(a, 18);
    for (a.messages[0..a.message_count], 0..) |*message, index| {
        if (channelMessageVisible(a, message)) total_height += measureMessage(hdc, a, message, bubble_width, showSenderName(a, index)) + threadSummaryHeight(a, message) + messageGap(a, index);
    }
    a.max_scroll = @max(0, total_height - (client.bottom - client.top));
    var y = client.bottom - px(a, 14) + a.scroll_y;
    var index = a.message_count;
    while (index > 0) {
        index -= 1;
        if (!channelMessageVisible(a, &a.messages[index])) continue;
        const height = measureMessage(hdc, a, &a.messages[index], bubble_width, showSenderName(a, index)) + threadSummaryHeight(a, &a.messages[index]);
        y -= height + messageGap(a, index);
        if (index != selected) continue;
        const delta = message_scroll.scrollDelta(y, height, client.top, client.bottom, px(a, 8));
        a.scroll_y = std.math.clamp(a.scroll_y + delta, 0, a.max_scroll);
        break;
    }
}

fn selectMessage(a: *App, delta: i32) void {
    if (a.message_count == 0) return;
    var next: i32 = if (a.selected_message) |selected| @as(i32, @intCast(selected)) + delta else @intCast(a.message_count - 1);
    while (next >= 0 and next < a.message_count and !channelMessageVisible(a, &a.messages[@intCast(next)])) next += delta;
    if (next < 0 and delta < 0) requestHubOlder(a);
    if (next < 0 or next >= a.message_count) return;
    a.selected_message = @intCast(next);
    scrollToSelectedMessage(a);
    if (a.canvas) |canvas| {
        _ = win.InvalidateRect(canvas, null, win.FALSE);
    }
}

fn walkMessageHighlight(a: *App, key: u32) void {
    if (key == win.VK_DOWN) {
        if (a.selected_message) |selected| {
            if (selected + 1 >= a.message_count) {
                a.selected_message = null;
                a.scroll_y = 0;
                if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
            } else selectMessage(a, 1);
        }
    } else selectMessage(a, -1);
}

fn reactionForCommand(command: u16) ?[]const u8 {
    return switch (command) {
        reaction_like => "👍",
        reaction_love => "❤️",
        reaction_laugh => "😂",
        reaction_surprised => "😮",
        reaction_sad => "😢",
        reaction_thanks => "🙏",
        reaction_woozy => "🥴",
        reaction_remove => "",
        else => null,
    };
}

fn copyToClipboard(a: *App, text_in: []const u16) bool {
    var expanded: std.ArrayList(u16) = .empty;
    defer expanded.deinit(a.allocator);
    var text = text_in;
    const scope = if (a.selected_chat < a.chat_count) hub.workspaceAvatarKey(a.chats[a.selected_chat].jid.slice()) else null;
    for (text_in, 0..) |unit, index| {
        if (unit < 0xE000 or unit > 0xF8FF or unit - 0xE000 >= a.custom_emoji.items.len) {
            if (expanded.items.len > 0) expanded.append(a.allocator, unit) catch return false;
            continue;
        }
        const entry = &a.custom_emoji.items[unit - 0xE000];
        if (scope == null or !std.mem.eql(u8, entry.scope.slice(), scope.?)) {
            if (expanded.items.len > 0) expanded.append(a.allocator, unit) catch return false;
            continue;
        }
        if (expanded.items.len == 0) expanded.appendSlice(a.allocator, text_in[0..index]) catch return false;
        expanded.append(a.allocator, ':') catch return false;
        for (entry.name.slice()) |byte| expanded.append(a.allocator, byte) catch return false;
        expanded.append(a.allocator, ':') catch return false;
    }
    if (expanded.items.len > 0) text = expanded.items;
    if (a.hwnd == null or text.len == 0) return false;
    if (win.OpenClipboard(a.hwnd.?) == 0) return false;
    defer _ = win.CloseClipboard();
    _ = win.EmptyClipboard();
    const bytes = (text.len + 1) * 2;
    const handle = win.GlobalAlloc(win.GMEM_MOVEABLE, bytes) orelse return false;
    const dest = win.GlobalLock(handle);
    if (dest == null) {
        _ = win.GlobalFree(handle);
        return false;
    }
    const destination: [*]u16 = @ptrCast(@alignCast(dest.?));
    @memcpy(destination[0..text.len], text);
    destination[text.len] = 0;
    _ = win.GlobalUnlock(handle);
    if (win.SetClipboardData(win.CF_UNICODETEXT, handle) == null) {
        _ = win.GlobalFree(handle);
        return false;
    }
    return true;
}

fn selectionPoint(a: *const App, index: usize, word: usize) passage.Endpoint {
    const span = a.messages[index].word_rects[word];
    return .{ .message = index, .word = word, .start = span.start, .end = @as(usize, span.start) + span.len };
}

fn updatePassageFocus(a: *App, x: i32, pointer_y: i32) void {
    var y = pointer_y;
    if (a.canvas) |canvas| {
        var client: win.RECT = undefined;
        if (win.GetClientRect(canvas, &client) != 0) y = std.math.clamp(y, client.top, @max(client.top, client.bottom - 1));
    }
    var nearest: ?passage.Endpoint = null;
    var vertical_distance: i64 = std.math.maxInt(i64);
    var horizontal_distance: i64 = std.math.maxInt(i64);
    for (a.messages[0..a.message_count], 0..) |*item, index| {
        const bubble = item.bubble_hit;
        if (item.word_count == 0 or bubble.right <= bubble.left) continue;
        if (rectHasPoint(bubble, x, y)) {
            if (hitTestWord(item, x, y)) |word| {
                a.text_selection.focus = selectionPoint(a, index, word);
                return;
            }
        }
        const first = item.word_rects[0].rect;
        const last = item.word_rects[item.word_count - 1].rect;
        for ([_]usize{ 0, item.word_count - 1 }) |word| {
            if (item.word_count > 1 and ((y < first.top and word != 0) or (y > last.bottom and word == 0))) continue;
            const rect = item.word_rects[word].rect;
            const dx = @max(@as(i64, rect.left) - x, @max(@as(i64, x) - rect.right, 0));
            const dy = @max(@as(i64, rect.top) - y, @max(@as(i64, y) - rect.bottom, 0));
            if (dy < vertical_distance or (dy == vertical_distance and dx < horizontal_distance)) {
                vertical_distance = dy;
                horizontal_distance = dx;
                var boundary = selectionPoint(a, index, word);
                if (word == 0) boundary.start = 0;
                if (word == item.word_count - 1) boundary.end = item.text.len;
                nearest = boundary;
            }
        }
    }
    if (nearest) |point| a.text_selection.focus = point;
}

fn copyPassage(a: *App) bool {
    const ends = a.text_selection.bounds() orelse return false;
    if (ends[0].message == ends[1].message) return false;
    if (ends[1].message >= a.message_count) return false;
    const days = a.allocator.alloc([20]u8, ends[1].message - ends[0].message + 1) catch {
        setStatus(a, "Could not copy");
        return true;
    };
    defer a.allocator.free(days);
    var messages: std.ArrayList(passage.Message) = .empty;
    defer messages.deinit(a.allocator);
    for (a.messages[ends[0].message .. ends[1].message + 1], ends[0].message..) |*message, index| {
        if (!channelMessageVisible(a, message)) continue;
        const range = a.text_selection.range(index, message.text.len) orelse continue;
        var timestamp = message.timestamp.slice();
        if (timestamp.len == 0) {
            if (slack.tsSeconds(message.id.slice())) |seconds| timestamp = tj.formatTimestamp(&days[index - ends[0].message], seconds);
        }
        const local = localTimestamp(timestamp);
        messages.append(a.allocator, .{
            .sender = message.sender.slice(),
            .from_me = message.from_me,
            .time = message.time.slice(),
            .day = passage.dayKey(&days[index - ends[0].message], timestamp, if (local) |value| .{ value.wYear, value.wMonth, value.wDay } else null),
            .text = message.text.slice(),
            .start = range.start,
            .end = range.end,
        }) catch {
            setStatus(a, "Could not copy");
            return true;
        };
    }
    const text = passage.build(a.allocator, messages.items) catch {
        setStatus(a, "Could not copy");
        return true;
    };
    defer a.allocator.free(text);
    setStatus(a, if (copyToClipboard(a, text)) "Selection copied" else "Could not copy");
    return true;
}

fn copySelectedText(a: *App) void {
    if (copyPassage(a)) return;
    const selected = a.selected_message orelse {
        setStatus(a, "Select a message first (Alt+J/K or click)");
        return;
    };
    if (selected >= a.message_count) return;
    const message = &a.messages[selected];
    if (a.text_selection.range(selected, message.text.len)) |range| {
        setStatus(a, if (copyToClipboard(a, message.text.slice()[range.start..range.end])) "Selection copied" else "Could not copy");
        return;
    }
    if (message.text.len == 0) {
        setStatus(a, "This message has no text");
        return;
    }
    setStatus(a, if (copyToClipboard(a, message.text.slice())) "Text copied" else "Could not copy text");
}

fn copySelectedLink(a: *App) void {
    const selected = a.selected_message orelse {
        setStatus(a, "Select a message first (Alt+J/K or click)");
        return;
    };
    if (selected >= a.message_count) return;
    const message = &a.messages[selected];
    if (message.link_count == 0) {
        setStatus(a, "No link in the selected message");
        return;
    }
    setStatus(a, if (copyToClipboard(a, message.links[0].url.slice())) "Link copied" else "Could not copy the link");
}

fn hitTestWord(message: *const Message, x: i32, y: i32) ?usize {
    var best: ?usize = null;
    var best_distance: i32 = 30;
    for (message.word_rects[0..message.word_count], 0..) |*span, index| {
        const dx = if (x < span.rect.left) span.rect.left - x else if (x > span.rect.right) x - span.rect.right else 0;
        const dy = if (y < span.rect.top) span.rect.top - y else if (y > span.rect.bottom) y - span.rect.bottom else 0;
        const distance = @max(dx, dy);
        if (distance < best_distance) {
            best_distance = distance;
            best = index;
        }
    }
    return best;
}

fn rectHasPoint(rect: win.RECT, x: i32, y: i32) bool {
    return x >= rect.left and x <= rect.right and y >= rect.top and y <= rect.bottom;
}

fn linkSpanHit(span: *const LinkSpan, x: i32, y: i32) bool {
    if (rectHasPoint(span.rect, x, y)) return true;
    for (span.chunk_rects[0..span.chunk_count]) |rect| {
        if (rectHasPoint(rect, x, y)) return true;
    }
    return false;
}

fn handleCanvasClick(a: *App, hwnd: win.HWND, x: i32, y: i32) void {
    for (a.messages[0..a.message_count], 0..) |*item, index| {
        const chip = item.reaction_hit;
        if (chip.right > chip.left and rectHasPoint(chip, x, y)) {
            if (a.selected_chat >= a.chat_count) return;
            const font = a.font orelse return;
            const hdc = win.GetDC(hwnd) orelse return;
            defer _ = win.ReleaseDC(hwnd, hdc);
            const previous_font = win.SelectObject(hdc, @ptrCast(font));
            defer _ = win.SelectObject(hdc, previous_font);
            const text = item.reaction.slice();
            var segments = std.mem.splitSequence(u16, text, &.{ ' ', ' ' });
            var segment_index: usize = 0;
            while (segments.next()) |segment| {
                const end = (@intFromPtr(segment.ptr) - @intFromPtr(text.ptr)) / @sizeOf(u16) + segment.len;
                const boundary = mixedSliceWidth(hdc, font, a.font_emoji orelse font, textLineHeight(hdc, font), fontAscent(hdc, font), text[0..end]);
                if (x - chip.left - px(a, 6) < boundary or end == text.len) break;
                segment_index += 1;
            }
            const utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, text) catch return;
            defer a.allocator.free(utf8);
            const mine = resolveCustomEmoji(a, item.my_reaction.slice()) orelse item.my_reaction.slice();
            const action = reaction_chip.decide(utf8, segment_index, mine) orelse return;
            a.selected_message = index;
            a.text_selection = .{};
            reactToMessageWithChip(a, a.chats[a.selected_chat].jid.slice(), item.id.slice(), switch (action) {
                .add => |emoji| blk: {
                    for (a.custom_emoji.items) |*entry| {
                        if (entry.path.len > 0 and std.mem.eql(u8, entry.token.slice(), emoji)) break :blk entry.name.slice();
                    }
                    break :blk emoji;
                },
                .remove => "",
            }, true);
            return;
        }
        const media = item.media_hit;
        const bubble = item.bubble_hit;
        if (item.send_state == .failed and x >= bubble.left and x <= bubble.right and y >= bubble.top and y <= bubble.bottom and
            resendFailedMessage(a, index))
        {
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            return;
        }
        if (x >= media.left and x <= media.right and y >= media.top and y <= media.bottom) {
            a.selected_message = index;
            if (isImage(item)) {
                if (!a.click_moved) openImageViewer(a, item);
            } else if (item.local_path.len == 0) {
                _ = downloadMedia(a, index, false);
            } else if (isAudio(item)) {
                handleAudioClick(a, item, x);
            } else if (std.ascii.eqlIgnoreCase(item.media_type.slice(), "video")) {
                playVideoInline(a, item);
            } else if (!isGif(item)) {
                openMedia(a, item);
            }
            return;
        }
        if (item.transcript.len > 0) {
            const toggle = item.toggle_hit;
            if (x >= toggle.left and x <= toggle.right and y >= toggle.top and y <= toggle.bottom) {
                item.transcript_expanded = !item.transcript_expanded;
                a.selected_message = index;
                _ = win.InvalidateRect(hwnd, null, win.FALSE);
                return;
            }
        }
        const card = item.unfurl_card_hit;
        if (x >= card.left and x <= card.right and y >= card.top and y <= card.bottom) {
            a.selected_message = index;
            openUnfurlCard(a, item);
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            return;
        }
        if (x >= bubble.left and x <= bubble.right and y >= bubble.top and y <= bubble.bottom) {
            for (item.links[0..item.link_count]) |*span| {
                if (linkSpanHit(span, x, y)) {
                    openUrlWide(a, span.url.ptr());
                    a.selected_message = index;
                    _ = win.InvalidateRect(hwnd, null, win.FALSE);
                    return;
                }
            }
            a.selected_message = index;
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            return;
        }
    }
}

fn handleCanvasDoubleClick(a: *App, x: i32, y: i32) bool {
    for (a.messages[0..a.message_count], 0..) |*item, index| {
        const chip = item.reaction_hit;
        if (chip.right > chip.left and x >= chip.left and x <= chip.right and y >= chip.top and y <= chip.bottom) return false;
        const media = item.media_hit;
        if (x >= media.left and x <= media.right and y >= media.top and y <= media.bottom) {
            if (!isImage(item) and (!isGif(item) or isVideoGif(item))) return false;
            a.selected_message = index;
            if (item.local_path.len == 0) {
                setStatus(a, "Downloading image...");
                _ = downloadMedia(a, index, false);
                return true;
            }
            if (isImage(item)) return true;
            openImageViewer(a, item);
            return true;
        }
        const bubble = item.bubble_hit;
        if (x >= bubble.left and x <= bubble.right and y >= bubble.top and y <= bubble.bottom and
            a.selected_chat < a.chat_count and a.chats[a.selected_chat].provider == .whatsapp)
        {
            const action = message_double_click.decide(item.from_me, item.my_reaction.slice());
            if (action != .ignore) {
                a.selected_message = index;
                reactToMessage(a, a.chats[a.selected_chat].jid.slice(), item.id.slice(), if (action == .add) message_double_click.thumbs_up else "");
                return true;
            }
        }
    }
    return false;
}

fn reactToSelected(a: *App, command: u16) void {
    if (command == command_copy_selection) {
        if (a.text_selection.active()) copySelectedText(a);
        return;
    }
    if (command == command_copy_transcript) {
        const selected = a.selected_message orelse return;
        if (selected >= a.message_count) return;
        const message = &a.messages[selected];
        if (message.transcript.len == 0) return;
        setStatus(a, if (copyToClipboard(a, message.transcript.slice())) "Transcript copied" else "Could not copy");
        return;
    }
    if (command == command_copy_text) {
        copySelectedText(a);
        return;
    }
    if (command == command_copy_link) {
        copySelectedLink(a);
        return;
    }
    const emoji = reactionForCommand(command) orelse return;
    const selected = a.selected_message orelse {
        setStatus(a, "Right-click a message to select it");
        return;
    };
    if (selected >= a.message_count or a.selected_chat >= a.chat_count) return;
    reactToMessage(a, a.chats[a.selected_chat].jid.slice(), a.messages[selected].id.slice(), emoji);
}

fn findPendingReaction(a: *App, msg_id: []const u8) ?*PendingReaction {
    for (a.pending_reactions[0..a.pending_reaction_count]) |*entry| {
        if (std.mem.eql(u8, entry.msg_id.slice(), msg_id)) return entry;
    }
    return null;
}

fn removePendingReaction(a: *App, entry: *PendingReaction) void {
    const index = (@intFromPtr(entry) - @intFromPtr(&a.pending_reactions[0])) / @sizeOf(PendingReaction);
    var shift = index;
    while (shift + 1 < a.pending_reaction_count) : (shift += 1) a.pending_reactions[shift] = a.pending_reactions[shift + 1];
    a.pending_reaction_count -= 1;
}

fn findLoadedMessage(a: *App, msg_id: []const u8) ?*Message {
    for (a.messages[0..a.message_count]) |*message| {
        if (std.mem.eql(u8, message.id.slice(), msg_id)) return message;
    }
    return null;
}

fn reactToMessage(a: *App, jid: []const u8, msg_id: []const u8, emoji: []const u8) void {
    reactToMessageWithChip(a, jid, msg_id, emoji, false);
}

fn reactToMessageWithChip(a: *App, jid: []const u8, msg_id: []const u8, emoji: []const u8, preserve_chip: bool) void {
    if (a.selected_chat >= a.chat_count or !std.mem.eql(u8, a.chats[a.selected_chat].jid.slice(), jid)) {
        setStatus(a, "The chat changed; reaction not sent");
        return;
    }
    const chat = &a.chats[a.selected_chat];
    if (chat.provider != .whatsapp and !unifiedHub(a)) {
        setStatus(a, "Reactions work in WhatsApp chats only for now");
        return;
    }
    const message = findLoadedMessage(a, msg_id) orelse {
        setStatus(a, "That message is no longer loaded");
        return;
    };
    const entry = findPendingReaction(a, msg_id) orelse blk: {
        if (a.pending_reaction_count == max_pending_reactions) {
            setStatus(a, "Too many reactions still sending; try again");
            return;
        }
        const fresh = &a.pending_reactions[a.pending_reaction_count];
        a.pending_reaction_count += 1;
        fresh.* = .{ .provider = chat.provider, .account = chat.account, .previous = message.reaction, .previous_my_reaction = message.my_reaction };
        fresh.jid.set(jid);
        fresh.msg_id.set(msg_id);
        if (std.mem.endsWith(u8, jid, "@g.us")) fresh.sender.set(message.sender_jid.slice());
        break :blk fresh;
    };
    entry.emoji.set(emoji);
    entry.client_id.set("");
    entry.retries = 0;
    entry.retry_at_ms = 0;
    entry.preserve_chip = preserve_chip;
    if (!preserve_chip) message.reaction.set(a.allocator, emoji);
    message.my_reaction.set(emoji);
    message.reaction_pending = true;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (emoji.len > 0) {
        if (emoji_picker.indexOf(emoji)) |index| {
            emoji_picker.pushRecent(&a.emoji_recents, &a.emoji_recents_count, index);
            saveEmojiRecents(a);
        }
    }
    enqueueReactionJob(a, entry);
    setStatus(a, if (emoji.len == 0) "Removing reaction..." else "Reacting...");
}

fn enqueueReactionJob(a: *App, entry: *PendingReaction) void {
    var args: [send_args.max_args][]const u8 = undefined;
    const count = send_args.buildReact(&args, a.wacli_path, entry.jid.slice(), entry.msg_id.slice(), entry.emoji.slice(), entry.sender.slice());
    var job = WacliJob{ .provider = entry.provider, .account = entry.account, .kind = .reaction };
    job.jid.set(entry.jid.slice());
    job.msg_id.set(entry.msg_id.slice());
    job.extra.set(entry.emoji.slice());
    if (hubConfigured(a)) {
        enqueueHubReaction(a, entry);
        return;
    }
    wacliJobArgs(&job, args[0..count]);
    if (!wacliEnqueue(a, job, true)) {
        if (entry.retry_at_ms == 0) entry.retry_at_ms = win.GetTickCount64() + 3_000;
        setStatus(a, "Reaction queue is full; retrying");
    }
}

fn applyReaction(a: *App, result: *WacliResult) void {
    defer if (!mediaBusy(a)) startSync(a);
    const entry = findPendingReaction(a, result.msg_id.slice()) orelse return;
    if (!std.mem.eql(u8, entry.emoji.slice(), result.extra.slice())) return;
    const message = findLoadedMessage(a, result.msg_id.slice());
    if (hubConfigured(a) and result.http_status == 409) {
        if (message) |target| target.reaction_pending = false;
        removePendingReaction(a, entry);
        setStatus(a, "Reaction delivery unknown; check the chat");
    } else if (result.ok) {
        if (message) |target| target.reaction_pending = false;
        removePendingReaction(a, entry);
        setStatus(a, if (result.extra.len == 0) "Reaction removed" else "Reaction sent");
    } else {
        entry.retries += 1;
        if (sendRetryDelayMs(entry.retries)) |delay| {
            entry.retry_at_ms = win.GetTickCount64() + delay;
            setStatus(a, "Reaction not sent yet; retrying");
            return;
        }
        if (message) |target| {
            target.reaction = entry.previous;
            target.my_reaction = entry.previous_my_reaction;
            target.reaction_pending = false;
        }
        removePendingReaction(a, entry);
        setStatus(a, "Reaction failed and was taken off");
    }
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn retryPendingReactions(a: *App) void {
    const now = win.GetTickCount64();
    for (a.pending_reactions[0..a.pending_reaction_count]) |*entry| {
        if (entry.retry_at_ms == 0 or entry.retry_at_ms > now) continue;
        entry.retry_at_ms = 0;
        enqueueReactionJob(a, entry);
    }
}

fn reapplyPendingReactions(a: *App, jid: []const u8) void {
    for (a.pending_reactions[0..a.pending_reaction_count]) |*entry| {
        if (!std.mem.eql(u8, entry.jid.slice(), jid)) continue;
        const message = findLoadedMessage(a, entry.msg_id.slice()) orelse continue;
        if (!entry.preserve_chip) message.reaction.set(a.allocator, entry.emoji.slice());
        message.my_reaction.set(entry.emoji.slice());
        message.reaction_pending = true;
    }
}

fn insertEmoji(a: *App, emoji: []const u8) void {
    if (!a.draft_store.isOpen(a.emoji_origin.key())) {
        _ = a.draft_store.append(a.allocator, a.emoji_origin.key(), "", emoji, false) catch {
            setStatus(a, "Could not insert emoji: draft limit reached");
            return;
        };
        persistDrafts(a);
        if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
        return;
    }
    const compose = a.compose orelse return;
    var wide = WideText(31){};
    wide.set(a.allocator, emoji);
    if (wide.len == 0) return;
    const length = win.GetWindowTextLengthW(compose);
    _ = win.SendMessageW(compose, win.EM_SETSEL, @bitCast(@as(isize, length)), @bitCast(@as(isize, length)));
    _ = win.SendMessageW(compose, win.EM_REPLACESEL, win.TRUE, @bitCast(@intFromPtr(wide.ptr())));
    _ = win.SendMessageW(compose, win.EM_SCROLLCARET, 0, 0);
    _ = win.SetFocus(compose);
}

const sc_row_base: i32 = 30;

fn shortcodeTyping(a: *App) ?shortcodes.Typing {
    const compose = a.compose orelse return null;
    var start: u32 = 0;
    var end: u32 = 0;
    _ = win.SendMessageW(compose, win.EM_GETSEL, @intFromPtr(&start), @bitCast(@intFromPtr(&end)));
    if (start != end or end == 0) return null;
    var buffer: [2048]u16 = undefined;
    const length: usize = @intCast(win.GetWindowTextW(compose, &buffer, buffer.len));
    if (end > length) return null;
    return shortcodes.typing(buffer[0..end]);
}

fn shortcodeHide(a: *App) void {
    a.sc_count = 0;
    if (a.sc_wnd) |popup| _ = win.ShowWindow(popup, win.SW_HIDE);
}

fn shortcodeReplace(a: *App, t: shortcodes.Typing, emoji: []const u8) void {
    const compose = a.compose orelse return;
    var wide = WideText(31){};
    wide.set(a.allocator, emoji);
    if (wide.len == 0) return;
    shortcodeHide(a);
    _ = win.SendMessageW(compose, win.EM_SETSEL, t.start, @bitCast(@as(isize, @intCast(t.end))));
    _ = win.SendMessageW(compose, win.EM_REPLACESEL, win.TRUE, @bitCast(@intFromPtr(wide.ptr())));
    _ = win.SendMessageW(compose, win.EM_SCROLLCARET, 0, 0);
}

fn shortcodeUpdate(a: *App) void {
    const t = shortcodeTyping(a) orelse return shortcodeHide(a);
    if (t.closed) {
        if (shortcodes.resolve(t.query())) |emoji| return shortcodeReplace(a, t, emoji);
        return shortcodeHide(a);
    }
    a.sc_count = shortcodes.matches(t.query(), &a.sc_matches);
    a.sc_sel = 0;
    if (a.sc_count == 0) return shortcodeHide(a);
    const owner = a.hwnd orelse return;
    const compose = a.compose orelse return;
    if (a.sc_wnd == null) {
        a.sc_wnd = win.CreateWindowExW(win.WS_EX_TOOLWINDOW | win.WS_EX_NOACTIVATE, lit("MessagesShortcodePopup"), null, win.WS_POPUP, 0, 0, 10, 10, owner, null, a.instance, null);
        if (a.sc_wnd) |popup| {
            var corner: win.DWORD = 2;
            _ = win.DwmSetWindowAttribute(popup, 33, &corner, @sizeOf(win.DWORD));
        }
    }
    const popup = a.sc_wnd orelse return;
    const row = px(a, sc_row_base);
    const width = px(a, 300);
    const height = row * @as(i32, @intCast(a.sc_count)) + px(a, 8);
    const at = win.SendMessageW(compose, win.EM_POSFROMCHAR, t.start, 0);
    var point = win.POINT{ .x = @as(i16, @bitCast(loword(@as(usize, @bitCast(at))))), .y = @as(i16, @bitCast(hiword(@as(usize, @bitCast(at))))) };
    _ = win.ClientToScreen(compose, &point);
    _ = win.MoveWindow(popup, point.x, @max(0, point.y - height - px(a, 4)), width, height, win.TRUE);
    _ = win.ShowWindow(popup, win.SW_SHOWNOACTIVATE);
    _ = win.InvalidateRect(popup, null, win.TRUE);
}

fn shortcodeAccept(a: *App) bool {
    if (a.sc_count == 0 or a.sc_sel >= a.sc_count) return false;
    const t = shortcodeTyping(a) orelse {
        shortcodeHide(a);
        return false;
    };
    if (t.closed) return false;
    shortcodeReplace(a, t, a.sc_matches[a.sc_sel].emoji);
    return true;
}

fn shortcodeMove(a: *App, down: bool) void {
    if (a.sc_count == 0) return;
    a.sc_sel = if (down) (a.sc_sel + 1) % a.sc_count else (a.sc_sel + a.sc_count - 1) % a.sc_count;
    if (a.sc_wnd) |popup| _ = win.InvalidateRect(popup, null, win.FALSE);
}

fn shortcodeProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_MOUSEACTIVATE => return win.MA_NOACTIVATE,
        win.WM_ERASEBKGND => return 1,
        win.WM_LBUTTONDOWN => {
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            const index = @divTrunc(y - px(a, 4), px(a, sc_row_base));
            if (index >= 0 and index < a.sc_count) {
                a.sc_sel = @intCast(index);
                _ = shortcodeAccept(a);
                focusCompose(a);
            }
            return 0;
        },
        win.WM_PAINT => {
            var paint: win.PAINTSTRUCT = undefined;
            const hdc = win.BeginPaint(hwnd, &paint);
            defer _ = win.EndPaint(hwnd, &paint);
            var client: win.RECT = undefined;
            _ = win.GetClientRect(hwnd, &client);
            _ = win.FillRect(hdc, &client, a.brush_panel.?);
            if (theme.choice == .amoled) _ = win.FrameRect(hdc, &client, a.brush_muted.?);
            _ = win.SetBkMode(hdc, win.TRANSPARENT);
            const row = px(a, sc_row_base);
            const em = px(a, 20);
            for (a.sc_matches[0..a.sc_count], 0..) |*entry, index| {
                var cell = win.RECT{ .left = 0, .top = px(a, 4) + @as(i32, @intCast(index)) * row, .right = client.right, .bottom = px(a, 4) + @as(i32, @intCast(index + 1)) * row };
                if (index == a.sc_sel) {
                    const highlight = win.CreateSolidBrush(theme.current.secondary_container) orelse return 0;
                    defer _ = win.DeleteObject(highlight);
                    _ = win.FillRect(hdc, &cell, highlight);
                }
                var wide = WideText(31){};
                wide.set(a.allocator, entry.emoji);
                const left = px(a, 12);
                const top = cell.top + @divTrunc(row - em, 2);
                if (emoji_draw.draw(hdc, wide.slice(), left, top, em, em) == null) {
                    _ = win.SelectObject(hdc, @ptrCast((if (a.font_emoji != null) a.font_emoji else a.font) orelse return 0));
                    _ = win.SetTextColor(hdc, if (index == a.sc_sel and theme.choice == .amoled) theme.current.on_secondary_container else theme.current.on_surface);
                    _ = win.TextOutW(hdc, left, top, wide.ptr(), @intCast(wide.len));
                }
                var label = WideText(80){};
                var label_utf8: [shortcodes.max_matches + 70]u8 = undefined;
                label.set(a.allocator, std.fmt.bufPrint(&label_utf8, ":{s}:", .{entry.name()}) catch "");
                _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                _ = win.SetTextColor(hdc, if (index == a.sc_sel and theme.choice == .amoled) theme.current.on_secondary_container else theme.current.on_surface);
                cell.left = px(a, 12) + em + px(a, 12);
                _ = text_draw.drawText(hdc, label.ptr(), -1, &cell, win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER | win.DT_END_ELLIPSIS);
            }
            return 0;
        },
        else => return win.DefWindowProcW(hwnd, message, wparam, lparam),
    }
}

fn closeEmojiPicker(a: *App) void {
    if (a.emoji_wnd) |picker| _ = win.DestroyWindow(picker);
    focusCompose(a);
}

fn openEmojiPicker(a: *App) void {
    if (a.emoji_wnd != null) {
        closeEmojiPicker(a);
        return;
    }
    if (a.selected_chat >= a.chat_count) return;
    a.emoji_react = false;
    a.emoji_origin = drafts.Identity.init(chat_key.of(&a.chats[a.selected_chat]));
    showEmojiPickerWindow(a);
}

fn openReactionPicker(a: *App) void {
    if (a.emoji_wnd) |picker| _ = win.DestroyWindow(picker);
    if (a.selected_chat >= a.chat_count or a.message_count == 0) return;
    const chat = &a.chats[a.selected_chat];
    if (chat.provider != .whatsapp and !unifiedHub(a)) {
        setStatus(a, "Reactions work in WhatsApp chats only for now");
        return;
    }
    if (a.selected_message == null or a.selected_message.? >= a.message_count) {
        var index = a.message_count;
        while (index > 0) {
            index -= 1;
            if (!a.messages[index].from_me) {
                a.selected_message = index;
                break;
            }
        }
    }
    const selected = a.selected_message orelse {
        setStatus(a, "No incoming message to react to");
        return;
    };
    scrollToSelectedMessage(a);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    a.emoji_react = true;
    a.emoji_react_jid.set(chat.jid.slice());
    a.emoji_react_id.set(a.messages[selected].id.slice());
    showEmojiPickerWindow(a);
}

fn emojiCell(a: *const App) i32 {
    return px(a, emoji_picker.cell_size);
}

fn emojiEditZone(a: *const App) i32 {
    return px(a, emoji_edit_zone_base);
}

fn emojiPickerWidth(a: *const App) i32 {
    return emojiCell(a) * @as(i32, @intCast(emoji_picker.grid_columns)) + px(a, 12) + scrollbar_width;
}

fn buildEmojiMatches(a: *App) void {
    a.emoji_match_count = 0;
    var query_buf: [64]u16 = [_]u16{0} ** 64;
    const query_len: usize = if (a.emoji_edit) |edit| @intCast(win.GetWindowTextW(edit, &query_buf, query_buf.len)) else 0;
    var utf8_buf: [192]u8 = undefined;
    const utf8_len = std.unicode.utf16LeToUtf8(&utf8_buf, query_buf[0..query_len]) catch 0;
    const query = std.mem.trim(u8, utf8_buf[0..utf8_len], " ");
    for (@constCast(query)) |*character| character.* = std.ascii.toLower(character.*);
    if (query.len == 0) {
        var row: [emoji_picker.grid_columns]u16 = undefined;
        const frequent = emoji_picker.frequentRow(a.emoji_recents[0..a.emoji_recents_count], &row);
        @memcpy(a.emoji_matches[0..frequent], row[0..frequent]);
        a.emoji_match_count = frequent;
    }
    a.emoji_match_count += emoji_picker.search(query, a.emoji_matches[a.emoji_match_count..]);
}

fn emojiLayout(a: *App) void {
    const picker = a.emoji_wnd orelse return;
    const columns = emoji_picker.grid_columns;
    const match_rows: i32 = @intCast(@divTrunc(a.emoji_match_count + columns - 1, columns));
    const rows = @max(1, @min(match_rows, emoji_max_rows));
    const width = emojiPickerWidth(a);
    const height = emojiEditZone(a) + rows * emojiCell(a) + px(a, 12);
    _ = win.SetWindowPos(picker, null, 0, 0, width, height, win.SWP_NOMOVE | win.SWP_NOZORDER | win.SWP_NOACTIVATE);
    if (a.emoji_list) |list| {
        _ = win.MoveWindow(list, 1, emojiEditZone(a), width - 2 - scrollbar_width, height - emojiEditZone(a) - 1, win.TRUE);
    }
}

fn emojiFilter(a: *App) void {
    buildEmojiMatches(a);
    a.emoji_selected = 0;
    if (a.emoji_list) |list| {
        _ = win.SendMessageW(list, win.WM_SETREDRAW, 0, 0);
        _ = win.SendMessageW(list, win.LB_RESETCONTENT, 0, 0);
        const rows: i32 = @divTrunc(@as(i32, @intCast(a.emoji_match_count)) + @as(i32, @intCast(emoji_picker.grid_columns)) - 1, @as(i32, @intCast(emoji_picker.grid_columns)));
        for (0..@intCast(@max(0, rows))) |_| {
            _ = win.SendMessageW(list, win.LB_ADDSTRING, 0, 1);
        }
        _ = win.SendMessageW(list, win.WM_SETREDRAW, 1, 0);
        _ = win.InvalidateRect(list, null, win.TRUE);
    }
    emojiLayout(a);
    if (a.emoji_wnd) |picker| _ = win.InvalidateRect(picker, null, win.TRUE);
}

fn emojiMove(a: *App, delta_columns: i32, delta_rows: i32) void {
    if (a.emoji_match_count == 0) return;
    const columns: i32 = @intCast(emoji_picker.grid_columns);
    var next: i32 = @as(i32, @intCast(a.emoji_selected)) + delta_rows * columns + delta_columns;
    next = std.math.clamp(next, 0, @as(i32, @intCast(a.emoji_match_count - 1)));
    a.emoji_selected = @intCast(next);
    if (a.emoji_list) |list| {
        _ = win.SendMessageW(list, win.LB_SETCURSEL, @intCast(@divTrunc(next, columns)), 0);
        _ = win.InvalidateRect(list, null, win.FALSE);
    }
}

fn emojiActivate(a: *App) void {
    if (a.emoji_selected >= a.emoji_match_count) return;
    const catalog_index = a.emoji_matches[a.emoji_selected];
    const emoji = emoji_picker.emoji(catalog_index);
    const react = a.emoji_react;
    closeEmojiPicker(a);
    if (react) {
        reactToMessage(a, a.emoji_react_jid.slice(), a.emoji_react_id.slice(), emoji);
        return;
    }
    emoji_picker.pushRecent(&a.emoji_recents, &a.emoji_recents_count, catalog_index);
    saveEmojiRecents(a);
    insertEmoji(a, emoji);
}

fn emojiCellClicked(a: *App, x: i32, item_index: i32) void {
    const column = emoji_picker.cellFromHit(x, emojiCell(a)) orelse return;
    const index = @as(i32, @intCast(item_index)) * @as(i32, @intCast(emoji_picker.grid_columns)) + @as(i32, @intCast(column));
    if (index < 0 or index >= @as(i32, @intCast(a.emoji_match_count))) return;
    a.emoji_selected = @intCast(index);
    emojiActivate(a);
}

fn drawEmojiCell(a: *App, item: *win.DRAWITEMSTRUCT) void {
    const background = win.CreateSolidBrush(theme.current.surface_container_low) orelse return;
    defer _ = win.DeleteObject(background);
    _ = win.FillRect(item.hDC, &item.rcItem, background);
    _ = win.SetBkMode(item.hDC, win.TRANSPARENT);
    const row: i32 = @intCast(item.itemID);
    const columns: i32 = @intCast(emoji_picker.grid_columns);
    const cell_size = emojiCell(a);
    for (0..emoji_picker.grid_columns) |column| {
        const index = row * columns + @as(i32, @intCast(column));
        if (index < 0 or index >= @as(i32, @intCast(a.emoji_match_count))) break;
        const catalog_index = a.emoji_matches[@intCast(index)];
        var cell = win.RECT{
            .left = item.rcItem.left + @as(i32, @intCast(column)) * cell_size,
            .top = item.rcItem.top,
            .right = item.rcItem.left + @as(i32, @intCast(column)) * cell_size + cell_size,
            .bottom = item.rcItem.bottom,
        };
        if (index == @as(i32, @intCast(a.emoji_selected))) {
            const selected_brush = win.CreateSolidBrush(theme.current.secondary_container) orelse return;
            defer _ = win.DeleteObject(selected_brush);
            _ = win.FillRect(item.hDC, &cell, selected_brush);
        }
        var wide = WideText(31){};
        wide.set(a.allocator, emoji_picker.emoji(catalog_index));
        if (wide.len == 0) continue;
        const em: i32 = px(a, 28);
        const offset_x = cell.left + @divTrunc(cell_size - em, 2);
        const offset_y = cell.top + @divTrunc(cell_size - em, 2);
        if (emoji_draw.draw(item.hDC, wide.slice(), offset_x, offset_y, em, em) == null) {
            const fallback_font = (if (a.font_emoji != null) a.font_emoji else a.font) orelse return;
            _ = win.SelectObject(item.hDC, @ptrCast(fallback_font));
            _ = win.SetTextColor(item.hDC, if (index == @as(i32, @intCast(a.emoji_selected)) and theme.choice == .amoled) theme.current.on_secondary_container else theme.current.on_surface);
            _ = win.TextOutW(item.hDC, offset_x, offset_y, wide.ptr(), @intCast(wide.len));
        }
    }
}

fn showEmojiPickerWindow(a: *App) void {
    const owner = a.hwnd orelse return;
    var owner_rect: win.RECT = undefined;
    _ = win.GetWindowRect(owner, &owner_rect);
    const width = emojiPickerWidth(a);
    const edit_zone = emojiEditZone(a);
    const grid_height = emoji_max_rows * emojiCell(a) + px(a, 12);
    const x = owner_rect.right - width - px(a, 16);
    const y = owner_rect.bottom - edit_zone - grid_height - px(a, 120);
    const picker = win.CreateWindowExW(
        win.WS_EX_TOOLWINDOW,
        lit("MessagesEmojiPicker"),
        null,
        win.WS_POPUP,
        @max(owner_rect.left + px(a, 8), x),
        @max(owner_rect.top + px(a, 60), y),
        width,
        edit_zone + grid_height,
        owner,
        null,
        a.instance,
        null,
    ) orelse return;
    a.emoji_wnd = picker;
    a.emoji_ever_active = false;
    var corner: win.DWORD = 2;
    _ = win.DwmSetWindowAttribute(picker, 33, &corner, @sizeOf(win.DWORD));
    var margins = win.MARGINS{ .cxLeftWidth = 0, .cxRightWidth = 0, .cyTopHeight = 0, .cyBottomHeight = 1 };
    _ = win.DwmExtendFrameIntoClientArea(picker, &margins);
    const edit_height = px(a, 36);
    a.emoji_edit = directwrite_edit.create(a.instance, picker, controlId(id_emoji_edit), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.ES_AUTOHSCROLL, px(a, 16), @divTrunc(edit_zone - edit_height, 2), width - px(a, 32), edit_height);
    if (a.emoji_edit == null) {
        _ = win.DestroyWindow(picker);
        return;
    }
    a.emoji_list = win.CreateWindowExW(0, lit("LISTBOX"), null, win.WS_CHILD | win.WS_VISIBLE | win.LBS_NOTIFY | win.LBS_OWNERDRAWFIXED | win.LBS_NOINTEGRALHEIGHT, 1, edit_zone, width - 2 - scrollbar_width, grid_height, picker, controlId(id_emoji_list), a.instance, null);
    setFont(a.emoji_edit, a.font);
    setFont(a.emoji_list, a.font);
    if (a.emoji_edit) |edit| {
        const cue = if (a.emoji_react) lit("React: search emoji (thumbs, heart, laugh...)") else lit("Search emoji");
        _ = win.SendMessageW(edit, win.EM_SETCUEBANNER, 1, @bitCast(@intFromPtr(cue)));
    }
    if (a.emoji_list) |list| _ = win.SendMessageW(list, win.LB_SETITEMHEIGHT, 0, emojiCell(a));
    emojiFilter(a);
    _ = win.ShowWindow(picker, win.SW_SHOW);
    if (a.emoji_edit) |edit| _ = win.SetFocus(edit);
}

fn emojiProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_COMMAND => {
            const id = loword(wparam);
            const notification = hiword(wparam);
            if (id == id_emoji_edit and (notification == win.EN_SETFOCUS or notification == win.EN_KILLFOCUS)) {
                _ = win.InvalidateRect(hwnd, null, win.FALSE);
                return 0;
            }
            if (id == id_emoji_edit and notification == win.EN_CHANGE) {
                emojiFilter(a);
            } else if (id == id_emoji_list and notification == win.LBN_SELCHANGE) {
                const list = a.emoji_list orelse return 0;
                const row = win.SendMessageW(list, win.LB_GETCURSEL, 0, 0);
                if (row >= 0) emojiCellClicked(a, emojiCellX(a), @intCast(row));
            }
            return 0;
        },
        win.WM_DRAWITEM => {
            const item: *win.DRAWITEMSTRUCT = winHandle(*win.DRAWITEMSTRUCT, @as(usize, @bitCast(lparam)));
            if (item.CtlID == id_emoji_list) drawEmojiCell(a, item);
            return 1;
        },
        win.WM_CTLCOLORSTATIC, win.WM_CTLCOLOREDIT, win.WM_CTLCOLORLISTBOX => {
            const hdc: win.HDC = winHandle(win.HDC, wparam);
            _ = win.SetTextColor(hdc, theme.current.on_surface);
            if (message == win.WM_CTLCOLOREDIT and theme.choice == .amoled) {
                _ = win.SetBkColor(hdc, theme.current.surface_container_high);
                return @bitCast(@intFromPtr(a.brush_raised.?));
            }
            _ = win.SetBkColor(hdc, theme.current.surface_container_low);
            if (a.brush_panel) |brush| return @bitCast(@intFromPtr(brush));
            return @bitCast(@intFromPtr(win.GetStockObject(win.BLACK_BRUSH)));
        },
        win.WM_PAINT => {
            var paint: win.PAINTSTRUCT = undefined;
            const hdc = win.BeginPaint(hwnd, &paint);
            defer _ = win.EndPaint(hwnd, &paint);
            var client: win.RECT = undefined;
            _ = win.GetClientRect(hwnd, &client);
            _ = win.FillRect(hdc, &client, a.brush_panel.?);
            const edit_zone = emojiEditZone(a);
            var separator = win.RECT{ .left = 0, .top = edit_zone - 2, .right = client.right, .bottom = edit_zone - 1 };
            _ = win.FillRect(hdc, &separator, a.brush_raised.?);
            if (a.emoji_match_count == 0) {
                _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
                _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                var empty_rect = win.RECT{ .left = px(a, 20), .top = edit_zone + px(a, 4), .right = client.right - px(a, 20), .bottom = edit_zone + px(a, 36) };
                _ = text_draw.drawText(hdc, lit("No matching emoji"), -1, &empty_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER);
            }
            var shapes = smooth.Context.init(hdc);
            defer shapes.deinit();
            paintPopupInput(&shapes, hwnd, a.emoji_edit);
            if (theme.choice == .amoled) _ = win.FrameRect(hdc, &client, a.brush_muted.?);
            if (a.emoji_list) |list| drawScrollbar(&shapes, stripRightOf(list, hwnd), listboxScrollInfo(list), theme.current.outline);
            return 0;
        },
        win.WM_LBUTTONDOWN => {
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            if (a.emoji_list) |list| {
                const strip = stripRightOf(list, hwnd);
                if (hitStrip(strip, x, y)) {
                    const info = listboxScrollInfo(list);
                    if (scrollbar.thumbGeom(trackOf(strip).top, trackOf(strip).h, info.total, info.page, info.top, scrollbar_min_thumb) != null)
                        beginStripDrag(a, hwnd, strip, info, y, .emoji, setEmojiScroll);
                    return 0;
                }
            }
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_MOUSEMOVE => {
            if (a.sb_drag == .emoji) {
                const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
                if (a.emoji_list) |list| dragStrip(a, stripRightOf(list, hwnd), listboxScrollInfo(list), y, setEmojiScroll);
                return 0;
            }
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_LBUTTONUP => {
            if (a.sb_drag == .emoji) {
                _ = win.ReleaseCapture();
                a.sb_drag = .none;
                return 0;
            }
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_CAPTURECHANGED => {
            a.sb_drag = .none;
            return 0;
        },
        win.WM_ACTIVATE => {
            if (loword(wparam) == win.WA_INACTIVE) {
                if (a.emoji_ever_active) _ = win.DestroyWindow(hwnd);
            } else a.emoji_ever_active = true;
            return 0;
        },
        win.WM_DESTROY => {
            a.emoji_wnd = null;
            a.emoji_edit = null;
            a.emoji_list = null;
            if (a.sb_drag == .emoji) a.sb_drag = .none;
            return 0;
        },
        else => return win.DefWindowProcW(hwnd, message, wparam, lparam),
    }
}

fn setEmojiScroll(a: *App, top: i32) void {
    if (a.emoji_list) |list| setListboxTop(list, top);
}

fn emojiCellX(a: *App) i32 {
    var point: win.POINT = undefined;
    _ = win.GetCursorPos(&point);
    const list = a.emoji_list orelse return 0;
    _ = win.ScreenToClient(list, &point);
    return point.x;
}

fn openEmojiMenu(a: *App) void {
    openEmojiPicker(a);
}

const quick_reactions = [_]u16{ reaction_like, reaction_love, reaction_laugh, reaction_surprised, reaction_sad, reaction_thanks, reaction_woozy };
const quick_cells = quick_reactions.len + 1;

fn reactionCellWidth(a: *const App) i32 {
    return px(a, 36);
}

fn appendMessageMenuItem(menu: win.HMENU, command: u16, label: ?[*:0]const u16) void {
    const flags: win.UINT = if (theme.choice == .amoled) win.MF_OWNERDRAW else if (label == null) win.MF_SEPARATOR else win.MF_STRING;
    _ = win.AppendMenuW(menu, flags, command, label);
}

fn addReactionItems(menu: win.HMENU) void {
    _ = win.AppendMenuW(menu, win.MF_OWNERDRAW, reaction_row, null);
    appendMessageMenuItem(menu, 0, null);
    appendMessageMenuItem(menu, reaction_remove, lit("Remove reaction"));
    appendMessageMenuItem(menu, 0, null);
    appendMessageMenuItem(menu, command_copy_text, lit("Copy text"));
    appendMessageMenuItem(menu, command_copy_link, lit("Copy link address"));
}

fn openUrlWide(a: *App, url: [*:0]const u16) void {
    if (!shell_lazy.ensureShell32()) {
        setStatus(a, "Windows could not open the link");
        return;
    }
    const result = shell_lazy.shellExecuteW.?(a.hwnd.?, lit("open"), url, null, null, win.SW_SHOWNORMAL);
    if (@intFromPtr(result) <= 32) setStatus(a, "Windows could not open the link");
}

fn openReactionMenu(a: *App, x: i32, y: i32) void {
    const menu = win.CreatePopupMenu() orelse return;
    defer _ = win.DestroyMenu(menu);
    if (theme.choice == .amoled) {
        var info = std.mem.zeroes(win.MENUINFO);
        info.cbSize = @sizeOf(win.MENUINFO);
        info.fMask = @as(win.DWORD, win.MIM_BACKGROUND) | win.MIM_APPLYTOSUBMENUS;
        info.hbrBack = a.brush_panel.?;
        _ = win.SetMenuInfo(menu, &info);
    }
    appendMessageMenuItem(menu, command_reply, lit("Reply                Ctrl+Shift+R"));
    appendMessageMenuItem(menu, 0, null);
    addReactionItems(menu);
    a.reaction_row_rect = null;
    const choice = win.TrackPopupMenu(menu, win.TPM_RETURNCMD | win.TPM_NONOTIFY, x, y, 0, a.hwnd.?, null);
    if (choice == command_reply) {
        startReply(a);
    } else if (choice == reaction_row) {
        const position = win.GetMessagePos();
        const mouse_x: i32 = @as(i16, @bitCast(@as(u16, @truncate(position))));
        const mouse_y: i32 = @as(i16, @bitCast(@as(u16, @truncate(position >> 16))));
        var cell: usize = 0;
        if (a.reaction_row_rect) |rect| {
            if (mouse_y >= rect.top and mouse_y < rect.bottom and mouse_x < rect.right)
                cell = reactionCellAt(mouse_x, rect.left, reactionCellWidth(a), quick_reactions.len + 1);
        }
        if (cell == quick_reactions.len) openReactionPicker(a) else reactToSelected(a, quick_reactions[cell]);
    } else reactToSelected(a, @intCast(choice));
}

fn reactionCellAt(x: i32, left: i32, width: i32, count: usize) usize {
    if (x < left or width <= 0) return 0;
    const cell: usize = @intCast(@divTrunc(@as(i64, x) - left, width));
    return if (cell < count) cell else 0;
}

fn measureMessageMenuItem(a: *const App, item: *win.MEASUREITEMSTRUCT) void {
    if (item.itemData == 0) {
        item.itemWidth = 0;
        item.itemHeight = @intCast(px(a, 8));
        return;
    }
    const label: [*:0]const u16 = @ptrFromInt(item.itemData);
    const hwnd = a.hwnd orelse return;
    const hdc = win.GetDC(hwnd) orelse return;
    defer _ = win.ReleaseDC(hwnd, hdc);
    const saved = win.SaveDC(hdc);
    defer _ = win.RestoreDC(hdc, saved);
    _ = win.SelectObject(hdc, @ptrCast(a.font orelse return));
    var size: win.SIZE = .{ .cx = 0, .cy = 0 };
    _ = win.GetTextExtentPoint32W(hdc, label, @intCast(std.mem.len(label)), &size);
    item.itemWidth = @intCast(size.cx + px(a, 40));
    item.itemHeight = @intCast(@max(px(a, 24), size.cy + px(a, 8)));
}

fn drawMessageMenuItem(a: *App, item: *win.DRAWITEMSTRUCT) void {
    const saved = win.SaveDC(item.hDC);
    defer _ = win.RestoreDC(item.hDC, saved);
    const selected = item.itemState & win.ODS_SELECTED != 0;
    _ = win.FillRect(item.hDC, &item.rcItem, if (selected) a.brush_raised.? else a.brush_panel.?);
    var rect = item.rcItem;
    rect.left += px(a, 16);
    rect.right -= px(a, 16);
    if (item.itemData == 0) {
        rect.top = @divTrunc(rect.top + rect.bottom, 2);
        rect.bottom = rect.top + 1;
        _ = win.FillRect(item.hDC, &rect, a.brush_muted.?);
        return;
    }
    _ = win.SelectObject(item.hDC, @ptrCast(a.font orelse return));
    _ = win.SetBkMode(item.hDC, win.TRANSPARENT);
    _ = win.SetTextColor(item.hDC, if (item.itemState & win.ODS_DISABLED != 0) theme.current.on_surface_variant else theme.current.on_surface);
    const label: [*:0]const u16 = @ptrFromInt(item.itemData);
    _ = text_draw.drawText(item.hDC, label, -1, &rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER | win.DT_NOPREFIX);
}

fn measureReactionRow(a: *const App, item: *win.MEASUREITEMSTRUCT) void {
    item.itemWidth = @intCast(reactionCellWidth(a) * @as(i32, @intCast(quick_cells)));
    item.itemHeight = @intCast(reactionCellWidth(a));
}

fn drawReactionRow(a: *App, item: *win.DRAWITEMSTRUCT) void {
    if (win.WindowFromDC(item.hDC)) |menu_window| {
        var rect = item.rcItem;
        _ = win.MapWindowPoints(menu_window, null, @ptrCast(&rect), 2);
        a.reaction_row_rect = rect;
    }
    const selected = item.itemState & win.ODS_SELECTED != 0;
    _ = win.FillRect(item.hDC, &item.rcItem, if (theme.choice == .amoled) (if (selected) a.brush_raised.? else a.brush_panel.?) else win.GetSysColorBrush(if (selected) win.COLOR_BTNFACE else win.COLOR_MENU));
    _ = win.SetBkMode(item.hDC, win.TRANSPARENT);
    _ = win.SetTextColor(item.hDC, if (theme.choice == .amoled) theme.current.on_surface else win.GetSysColor(win.COLOR_MENUTEXT));
    const cell = reactionCellWidth(a);
    const em = px(a, 22);
    for (0..quick_cells) |index| {
        var wide = WideText(31){};
        wide.set(a.allocator, if (index < quick_reactions.len) reactionForCommand(quick_reactions[index]).? else "+");
        const left = item.rcItem.left + @as(i32, @intCast(index)) * cell + @divTrunc(cell - em, 2);
        const top = item.rcItem.top + @divTrunc(cell - em, 2);
        if (index == quick_reactions.len or emoji_draw.draw(item.hDC, wide.slice(), left, top, em, em) == null) {
            _ = win.SelectObject(item.hDC, @ptrCast((if (a.font_emoji != null) a.font_emoji else a.font) orelse return));
            var box = win.RECT{ .left = item.rcItem.left + @as(i32, @intCast(index)) * cell, .top = item.rcItem.top, .right = item.rcItem.left + @as(i32, @intCast(index + 1)) * cell, .bottom = item.rcItem.bottom };
            _ = text_draw.drawText(item.hDC, wide.ptr(), -1, &box, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
        }
    }
}

fn migrateLegacyArchiveState(a: *App, chats: []const std.json.Value) void {
    if (!unifiedHub(a) or a.archive_legacy_done) return;
    const state = a.archive_state orelse return;
    if (a.archive_state_path.len == 0) return;
    const marker = providerStatePath(a, "archive-legacy-done.txt") orelse return;
    defer a.allocator.free(marker);
    if (fileExistsUtf8(marker)) {
        a.archive_legacy_done = true;
        return;
    }
    const path = messagesDirPath(a, "archive-state.txt") orelse return;
    defer a.allocator.free(path);
    if (fileExistsUtf8(path)) {
        const data = readFileWin(a.allocator, path, archive_rules.max_entries * 260) orelse return;
        defer a.allocator.free(data);
        const legacy = a.allocator.create(archive_rules.State) catch return;
        defer a.allocator.destroy(legacy);
        legacy.* = .{};
        legacy.parse(data);
        for (chats) |row| {
            if (row != .object) continue;
            const key = chat_key.Key{
                .provider = hub.sourceProvider(row.object) orelse continue,
                .account = hub.sourceAccount(row.object, a.cache_tag.slice()),
                .id = getString(row.object, "jid"),
            };
            _ = archive_rules.migrateLegacyKeep(state, legacy, key, getString(row.object, "last_message_ts"));
        }
        const buffer = a.allocator.alloc(u8, archive_rules.max_entries * 260) catch return;
        defer a.allocator.free(buffer);
        if (!writeCacheFileAtomic(a, a.archive_state_path, state.format(buffer))) return;
    }
    a.archive_legacy_done = writeCacheFileAtomic(a, marker, "done\n");
}

fn loadArchiveState(a: *App) void {
    const state = a.allocator.create(archive_rules.State) catch return;
    state.* = .{};
    a.archive_state = state;
    const path = providerStatePath(a, "archive-state.txt") orelse return;
    a.archive_state_path = path;
    const data = readFileWin(a.allocator, path, archive_rules.max_entries * 260) orelse return;
    defer a.allocator.free(data);
    state.parse(data);
}

fn saveArchiveState(a: *App) void {
    const state = a.archive_state orelse return;
    if (a.archive_state_path.len == 0) return;
    const buffer = a.allocator.alloc(u8, archive_rules.max_entries * 260) catch return;
    defer a.allocator.free(buffer);
    _ = writeCacheFileAtomic(a, a.archive_state_path, state.format(buffer));
}

fn isKeptArchived(a: *const App, jid: []const u8) bool {
    const state = a.archive_state orelse return false;
    return state.isKept(jid);
}

fn archiveMarker(a: *const App, chat: *const Chat) ?[*:0]const u16 {
    if (chat.provider == .slack) return if (chat.archived) lit("Kept archived") else null;
    if (chat.provider != .whatsapp) return if (chat.archived) lit("Archived") else null;
    if (std.mem.eql(u16, chat.kind.slice(), std.mem.span(lit("Contact")))) return lit("Contact");
    if (!chat.archived and !a.show_archived) return null;
    return if (isKeptArchived(a, chat.jid.slice())) lit("Kept archived") else lit("Archived");
}

fn queueUnarchiveChat(a: *App, jid: []const u8, source: archive_rules.Source) void {
    var already_queued = false;
    for (a.pending_archives[0..a.pending_archive_count]) |*pending| {
        if (std.mem.eql(u8, pending.jid.slice(), jid)) already_queued = pending.should_unarchive;
    }
    if (already_queued) {
        if (std.mem.eql(u8, a.unarchive_retry.slice(), jid)) a.unarchive_retry.set("");
        return;
    }
    if (a.pending_archive_count >= a.pending_archives.len) {
        if (a.unarchive_retry.len == 0 or (source == .send and std.mem.eql(u8, a.unarchive_retry.slice(), jid))) {
            a.unarchive_retry.set(jid);
            a.unarchive_retry_source = source;
        }
        return;
    }
    if (std.mem.eql(u8, a.unarchive_retry.slice(), jid)) a.unarchive_retry.set("");
    const pending = &a.pending_archives[a.pending_archive_count];
    pending.jid.set(jid);
    pending.should_unarchive = true;
    pending.source = source;
    a.archive_batch_total = if (a.pending_archive_count == 0) 1 else a.archive_batch_total + 1;
    a.pending_archive_count += 1;
    if (a.archive_state) |state| {
        state.remove(jid);
        saveArchiveState(a);
    }
    startNextArchive(a);
}

fn holdKeptArchived(a: *App, key: chat_key.Key, provider_archived: bool, ts: []const u8) bool {
    if (key.provider == .slack or (unifiedHub(a) and (key.provider == .telegram or key.provider == .signal))) return false;
    const jid = key.id;
    const state = a.archive_state orelse return false;
    if (!state.holdKept(jid, provider_archived, ts)) return false;
    if (archiveChat(a, key, if (state.isKept(jid)) .keep else .archive, .kept) == null) return true;
    state.releaseHold(jid);
    return false;
}

const archived_scan_min_ticks = 20;
const archived_scan_idle_ticks = 300;

fn tickArchivedScan(a: *App, store_changed: bool) void {
    if (a.archive_state == null) return;
    if (store_changed) a.archived_scan_dirty = true;
    a.archived_scan_ticks +|= 1;
    if (a.archived_scan_ticks < archived_scan_min_ticks) return;
    if (!a.archived_scan_dirty and a.archived_scan_ticks < archived_scan_idle_ticks) return;
    if (wacliPendingGet(a, .archived_scan) > 0) return;
    if (a.pending_archive_count > 0 or a.archive_child != null) return;
    a.archived_scan_dirty = false;
    a.archived_scan_ticks = 0;
    var job = WacliJob{ .account = a.cache_tag, .kind = .archived_scan };
    wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "chats", "list", "--archived", "--limit", "10000" });
    _ = wacliEnqueue(a, job, false);
}

fn applyArchivedScan(a: *App, raw: []const u8) void {
    if (unifiedHub(a)) {
        a.people.replaceArchivedHub(raw, peopleHubFields) catch {};
    } else {
        a.people.replaceArchived(raw) catch {};
    }
    refreshPeopleSearch(a);
    const state = a.archive_state orelse return;
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |o| o,
        else => return,
    };
    const rows = switch (root.get("data") orelse return) {
        .array => |items| items.items,
        else => return,
    };
    var changed = false;
    var missing_kept = false;
    for (rows[0..@min(rows.len, archive_rules.max_entries)]) |item| {
        const object = switch (item) {
            .object => |o| o,
            else => continue,
        };
        if (!getBool(object, "archived")) continue;
        const jid = getString(object, "jid");
        const stamp = getString(object, "last_message_ts");
        if (jid.len == 0 or stamp.len == 0 or std.mem.indexOfScalar(u8, jid, '@') == null) continue;
        const kept = state.isKept(jid);
        const base = state.baseline(jid) orelse {
            state.setBaseline(jid, stamp);
            changed = true;
            continue;
        };
        if (kept and std.mem.order(u8, stamp, base) == .gt) {
            state.setBaseline(jid, stamp);
            changed = true;
        }
    }
    if (rows.len < archive_rules.max_entries and a.pending_archive_count == 0 and a.archive_child == null) {
        var index = state.count;
        while (index > 0) {
            index -= 1;
            const entry = &state.entries[index];
            if (entry.provider != .whatsapp) continue;
            var present = false;
            for (rows) |item| {
                const object = switch (item) {
                    .object => |o| o,
                    else => continue,
                };
                if (std.mem.eql(u8, getString(object, "jid"), entry.jidSlice())) {
                    present = true;
                    break;
                }
            }
            if (present) continue;
            missing_kept = true;
        }
    }
    if (changed) saveArchiveState(a);
    if (missing_kept and a.show_archived and wacliPendingGet(a, .kept_check) == 0) {
        var job = WacliJob{ .account = a.cache_tag, .kind = .kept_check };
        wacliJobArgs(&job, &.{ a.wacli_path, "--json", "--read-only", "chats", "list", "--limit", "250", "--no-archived" });
        _ = wacliEnqueue(a, job, false);
    }
    var log_buffer: [96]u8 = undefined;
    appendLaunchLog(a, std.fmt.bufPrint(&log_buffer, "archive-scan: {d} archived", .{rows.len}) catch "archive-scan");
}

fn applyKeptCheck(a: *App, raw: []const u8) void {
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |o| o,
        else => return,
    };
    const rows = switch (root.get("data") orelse return) {
        .array => |items| items.items,
        else => return,
    };
    for (rows) |item| {
        const object = switch (item) {
            .object => |o| o,
            else => continue,
        };
        const key = chat_key.Key{
            .provider = if (unifiedHub(a)) hub.sourceProvider(object) orelse continue else .whatsapp,
            .account = if (unifiedHub(a)) hub.sourceAccount(object, a.cache_tag.slice()) else a.cache_tag.slice(),
            .id = getString(object, "jid"),
        };
        if (key.provider == .slack or (unifiedHub(a) and (key.provider == .telegram or key.provider == .signal))) continue;
        _ = holdKeptArchived(a, key, getBool(object, "archived"), getString(object, "last_message_ts"));
    }
}

fn retryUnarchiveChat(a: *App) void {
    if (a.unarchive_retry.len == 0) return;
    const jid = a.unarchive_retry.slice();
    queueUnarchiveChat(a, jid, a.unarchive_retry_source);
}

fn pendingArchiveHidesChat(a: *const App, jid: []const u8, show_archived: bool) bool {
    if (a.include_archived and !show_archived) return false;
    for (a.pending_archives[0..a.pending_archive_count]) |*pending| {
        if (archive_rules.pendingHidesChat(show_archived, pending.should_unarchive) and
            std.mem.eql(u8, pending.jid.slice(), jid)) return true;
    }
    return false;
}

fn removeFirstPendingArchive(a: *App) void {
    if (a.pending_archive_count == 0) return;
    var index: usize = 1;
    while (index < a.pending_archive_count) : (index += 1) a.pending_archives[index - 1] = a.pending_archives[index];
    a.pending_archive_count -= 1;
}

fn startNextArchive(a: *App) void {
    if (hubConfigured(a)) {
        startHubArchive(a);
        return;
    }
    if (verification_fixture) return;
    if (a.pending_archive_count > 0 and a.archive_batch_total > 1) setStatus(a, "");
    if (a.archive_child != null or a.read_child != null or a.pending_archive_count == 0) return;
    if (mediaBusy(a) or a.send_child != null or sendReadyPending(a) or avatarBusy(a)) return;
    stopSync(a, "archive");
    const pending = &a.pending_archives[0];
    var log_buffer: [288]u8 = undefined;
    appendLaunchLog(a, archive_rules.logLine(&log_buffer, pending.jid.slice(), !pending.should_unarchive, pending.source));
    const child = child_process.spawn(a.io, .{
        .argv = &.{ a.wacli_path, "--json", "--lock-wait", "10s", "chats", if (pending.should_unarchive) "unarchive" else "archive", "--chat", pending.jid.slice() },
        .stdin = .ignore,
        .stdout = .ignore,
        .stderr = .ignore,
        .create_no_window = true,
    }) catch {
        removeFirstPendingArchive(a);
        setStatus(a, "Could not start archive operation");
        startSync(a);
        return;
    };
    a.archive_child = child;
}

fn checkArchive(a: *App) void {
    if (verification_fixture and !hubConfigured(a)) {
        if (a.pending_archive_count == 0) return;
        const pending = &a.pending_archives[0];
        const response = verificationProvider(a, if (pending.should_unarchive) .unarchive else .archive, pending.jid.slice()) orelse return;
        a.allocator.free(response);
        var log_buffer: [288]u8 = undefined;
        appendLaunchLog(a, archive_rules.logLine(&log_buffer, pending.jid.slice(), !pending.should_unarchive, pending.source));
        completeArchive(a, 0);
        return;
    }
    if (a.archive_child) |*child| {
        const handle = child.id orelse return;
        var code: win.DWORD = 0;
        if (win.GetExitCodeProcess(handle, &code) == 0 or code == win.STILL_ACTIVE) return;
        _ = child.wait(a.io) catch {};
        a.archive_child = null;
        completeArchive(a, code);
    } else startNextArchive(a);
}

fn completeArchive(a: *App, code: win.DWORD) void {
    const completed = &a.pending_archives[0];
    const action: archive_rules.Action = if (completed.should_unarchive) .unarchive else if (isKeptArchived(a, completed.jid.slice())) .keep else .archive;
    const quiet = completed.source == .kept and code == 0;
    removeFirstPendingArchive(a);
    if (a.pending_archive_count > 0) {
        startNextArchive(a);
    } else {
        drainMediaDownloads(a);
        startSync(a);
        refreshChats(a);
        refreshMessages(a);
        if (!quiet) setStatus(a, if (code == 0) action.status() else "Archive operation failed");
    }
}

fn removeChatRow(a: *App, removed: usize) void {
    if (removed >= a.chat_count) return;
    var index = removed + 1;
    while (index < a.chat_count) : (index += 1) a.chats[index - 1] = a.chats[index];
    a.chat_count -= 1;
    if (removed < a.selected_chat) a.selected_chat -= 1;
    if (a.chat_count > 0 and a.selected_chat >= a.chat_count) a.selected_chat = a.chat_count - 1;
    switchComposerDraft(a);
    if (a.chats_hwnd) |list| {
        _ = win.SendMessageW(list, win.LB_DELETESTRING, removed, 0);
        if (a.chat_count > 0) _ = win.SendMessageW(list, win.LB_SETCURSEL, a.selected_chat, 0);
    }
}

fn visibleChatIndex(a: *const App, key: chat_key.Key) ?usize {
    return chat_key.indexOf(Chat, a.chats[0..a.chat_count], key);
}

fn chatProvider(a: *App, jid: []const u8) transport.Provider {
    if (a.selected_chat < a.chat_count and std.mem.eql(u8, a.chats[a.selected_chat].jid.slice(), jid)) return a.chats[a.selected_chat].provider;
    for (a.chats[0..a.chat_count]) |*chat| if (std.mem.eql(u8, chat.jid.slice(), jid)) return chat.provider;
    if (std.mem.indexOfScalar(u8, jid, '@') != null) return .whatsapp;
    for (&a.slack_installations) |*installation| {
        if (slackChatById(a, installation.team_id.slice(), jid) != null) return .slack;
    }
    if (std.fmt.parseInt(i64, jid, 10)) |id| {
        for (a.tg_chats[0..a.tg_chat_count]) |*chat| if (chat.id == id) return .telegram;
    } else |_| {}
    return .whatsapp;
}

fn archiveChat(a: *App, key: chat_key.Key, action: archive_rules.Action, source: archive_rules.Source) ?[]const u8 {
    const jid = key.id;
    const unarchive = action == .unarchive;
    if (key.provider == .slack or (unifiedHub(a) and (key.provider == .telegram or key.provider == .signal))) {
        const state = a.archive_state orelse return "Archive is not available";
        const provider_archived = if (visibleChatIndex(a, key)) |index| a.chats[index].provider_archived else false;
        const saved = if (unarchive and provider_archived) state.setLocalUnarchived(key) else state.setLocalArchived(key, !unarchive);
        if (!saved) return "Keep archived list is full";
        saveArchiveState(a);
        if (visibleChatIndex(a, key)) |index| {
            a.chats[index].archived = !unarchive;
            if (!messenger_view.archiveMatches(a.show_archived, a.include_archived, activeChatView(a) == .all, a.unread_only, !unarchive, a.chats[index].unread)) removeChatRow(a, index);
        }
        if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
        if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        return null;
    }
    if (!unifiedHub(a)) switch (key.provider) {
        .telegram => return "Archiving is not available for Telegram chats yet",
        .slack => unreachable,
        .signal => return "Archiving is not available for Signal chats yet",
        .whatsapp => {},
    };
    if (jid.len == 0 or jid.len > archive_rules.max_jid or (!unifiedHub(a) and std.mem.indexOfScalar(u8, jid, '@') == null)) return "Unknown chat id";
    var already_queued = false;
    for (a.pending_archives[0..a.pending_archive_count]) |*pending| {
        if (std.mem.eql(u8, pending.jid.slice(), jid)) already_queued = pending.should_unarchive == unarchive;
    }
    if (!already_queued and a.pending_archive_count >= a.pending_archives.len) return "Archive queue is full";
    if (a.archive_state) |state| {
        if (unarchive) {
            state.remove(jid);
        } else {
            const row_stamp = if (visibleChatIndex(a, key)) |index| a.chats[index].timestamp.slice() else "";
            var stamp_buffer: [archive_rules.stamp_len]u8 = undefined;
            const stamp = archive_rules.archiveBaseline(&stamp_buffer, row_stamp, nowUnixSeconds());
            if (!state.archive(jid, stamp, action == .keep) and action == .keep) return "Keep archived list is full";
        }
        saveArchiveState(a);
    } else if (action == .keep) return "Keep archived is not available";
    if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (!already_queued) {
        const pending = &a.pending_archives[a.pending_archive_count];
        pending.jid.set(jid);
        pending.should_unarchive = unarchive;
        pending.source = source;
        a.archive_batch_total = if (a.pending_archive_count == 0) 1 else a.archive_batch_total + 1;
        a.pending_archive_count += 1;
    }
    if (visibleChatIndex(a, key)) |index| {
        a.chats[index].archived = !unarchive;
        if (!messenger_view.archiveMatches(a.show_archived, a.include_archived, activeChatView(a) == .all, a.unread_only, !unarchive, a.chats[index].unread)) removeChatRow(a, index);
    }
    startNextArchive(a);
    return null;
}

fn archiveChatKey(a: *App, jid: []const u8) chat_key.Key {
    if (a.selected_chat < a.chat_count and std.mem.eql(u8, a.chats[a.selected_chat].jid.slice(), jid)) return chat_key.of(&a.chats[a.selected_chat]);
    for (a.chats[0..a.chat_count]) |*chat| if (std.mem.eql(u8, chat.jid.slice(), jid)) return chat_key.of(chat);
    return .{ .provider = chatProvider(a, jid), .account = a.cache_tag.slice(), .id = jid };
}

fn paneFollowSelection(a: *App, open_jid: []const u8) void {
    const now: ?[]const u8 = if (a.selected_chat < a.chat_count) a.chats[a.selected_chat].jid.slice() else null;
    if (!archive_rules.paneNeedsSwitch(open_jid, now) and a.selected_chat < a.chat_count and chat_key.Key.eql(chat_key.displayed(a), chat_key.of(&a.chats[a.selected_chat]))) return;
    clearReply(a);
    discardStagedImage(a);
    a.user_viewed = true;
    refreshMessages(a);
    if (a.chat_count > 0) focusCompose(a);
    if (a.hwnd) |hwnd| _ = win.InvalidateRect(hwnd, null, win.FALSE);
}

fn archiveShortcutAllowed(a: *const App, focus: ?win.HWND, lparam: win.LPARAM, allow_compose: bool) bool {
    if ((@as(usize, @bitCast(lparam)) & (@as(usize, 1) << 30)) != 0) return false;
    return focus != null and (focus == a.chats_hwnd or focus == a.canvas or focus == a.hwnd or (allow_compose and focus == a.compose));
}

fn unarchiveSentChat(a: *App, jid: []const u8) void {
    var archived = if (a.archive_state) |state| state.find(jid) != null else false;
    if (visibleChatIndex(a, .{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = jid })) |index| archived = archived or a.chats[index].archived;
    if (a.people.find(jid)) |entry| archived = archived or entry.origin == .archived;
    for (a.pending_archives[0..a.pending_archive_count]) |*pending| {
        if (std.mem.eql(u8, pending.jid.slice(), jid)) archived = !pending.should_unarchive;
    }
    if (archived) queueUnarchiveChat(a, jid, .send);
}

fn archivePaletteSelection(a: *App) void {
    if (a.selected_chat >= a.chat_count or !chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), a.palette_archive_key.key()) or
        a.bulk.count != a.palette_archive_bulk_count or a.show_archived != a.palette_archive_show_archived or
        (a.selected_chat < a.chat_count and a.chats[a.selected_chat].archived != a.palette_archive_was_archived))
        return setStatus(a, "Chat selection changed. Open the command palette again");
    archiveSelectedChat(a, false, .menu);
}

fn archiveSelectedChat(a: *App, keep: bool, source: archive_rules.Source) void {
    if (a.chat_count == 0 or a.selected_chat >= a.chat_count) return;
    if (a.bulk.count > 0) return archiveBulkSelection(a, keep, source);
    const chat = &a.chats[a.selected_chat];
    if (source == .shortcut and a.displayed_jid.len > 0 and !chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat)))
        return setStatus(a, "Chat selection changed. Wait for the selected chat to open");
    var open_jid = Utf8Text(191){};
    open_jid.set(chat.jid.slice());
    const action: archive_rules.Action = if (keep) .keep else if (a.show_archived or chat.archived) .unarchive else .archive;
    var key = chat_key.Stored{};
    key.set(chat_key.of(chat));
    if (archiveChat(a, key.key(), action, source)) |problem| return setStatus(a, problem);
    paneFollowSelection(a, open_jid.slice());
    setStatus(a, if (key.provider == .slack and action != .unarchive) archive_rules.Action.keep.status() else action.status());
}

fn selectAllChats(a: *App) void {
    a.bulk.clear();
    for (a.chats[0..a.chat_count]) |*chat| a.bulk.addKey(chat_key.of(chat));
    if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
    var buffer: [128]u8 = undefined;
    setStatus(a, std.fmt.bufPrint(&buffer, "{d} chats selected - Ctrl+E archives, Esc cancels", .{a.bulk.count}) catch "Chats selected");
}

fn clearBulkSelection(a: *App) bool {
    if (a.bulk.count == 0) return false;
    a.bulk.clear();
    if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
    return true;
}

fn archiveBulkSelection(a: *App, keep: bool, source: archive_rules.Source) void {
    var open_jid = Utf8Text(191){};
    if (a.selected_chat < a.chat_count) open_jid.set(a.chats[a.selected_chat].jid.slice());
    const action: archive_rules.Action = if (keep) .keep else if (a.show_archived) .unarchive else .archive;
    var problem: ?[]const u8 = null;
    var slack_only = true;
    var index: usize = 0;
    while (index < a.bulk.count) : (index += 1) {
        const key = a.bulk.atKey(chat_key.Key, index);
        slack_only = slack_only and key.provider == .slack;
        if (key.provider != .slack and !unifiedHub(a) and (key.provider != .whatsapp or !std.mem.eql(u8, key.account, a.cache_tag.slice()))) {
            problem = "Archiving is only available for the active WhatsApp account";
            continue;
        }
        if (archiveChat(a, key, action, source)) |why| problem = why;
    }
    a.bulk.clear();
    if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
    paneFollowSelection(a, open_jid.slice());
    if (problem) |why| return setStatus(a, why);
    setStatus(a, if (slack_only and action != .unarchive) archive_rules.Action.keep.status() else action.status());
}

const control_call_posted: u8 = 0;
const control_call_answered: u8 = 1;
const control_call_abandoned: u8 = 2;
const control_not_ready_retry_window_ms: u64 = 8_000;
const control_ui_reply_timeout_ms: u32 = 10_000;

const ControlCall = struct {
    parsed: std.json.Parsed(control_api.Request),
    out: std.Io.Writer.Allocating,
    event: win.HANDLE,
    state: std.atomic.Value(u8) = .init(control_call_posted),
    retry: bool = false,
    need_whatsapp: bool = false,
    whatsapp_raw: []u8 = &.{},
    phase: enum { select, main, wait } = .main,
};

fn controlThreadMain(a: *App) void {
    control_pipe.serve(a.allocator, a, controlHandle);
}

fn controlCallDestroy(a: *App, call: *ControlCall) void {
    call.parsed.deinit();
    call.out.deinit();
    _ = win.CloseHandle(call.event);
    if (call.whatsapp_raw.len > 0) a.allocator.free(call.whatsapp_raw);
    a.allocator.destroy(call);
}

fn controlHandle(context: *anyopaque, line: []const u8, out: *std.Io.Writer.Allocating) void {
    const a: *App = @ptrCast(@alignCast(context));
    const w = &out.writer;
    const parsed = control_api.parseRequest(a.allocator, line) catch {
        control_api.writeError(w, "bad request; run wazigctl --help") catch {};
        return;
    };
    const event = win.CreateEventW(null, win.FALSE, win.FALSE, null) orelse {
        parsed.deinit();
        control_api.writeError(w, "could not create an event") catch {};
        return;
    };
    const call = a.allocator.create(ControlCall) catch {
        parsed.deinit();
        _ = win.CloseHandle(event);
        control_api.writeError(w, "out of memory") catch {};
        return;
    };
    call.* = .{ .parsed = parsed, .out = .init(a.allocator), .event = event };
    var owned = true;
    defer if (owned) controlCallDestroy(a, call);
    if (call.parsed.value.cmd == .messages and call.parsed.value.id.len > 0) {
        call.phase = .select;
        const outcome = controlRound(a, call);
        if (outcome == .abandoned) owned = false;
        if (outcome != .answered or !control_api.responseOk(call.out.written())) return controlFinish(call, outcome, w);
        call.phase = .main;
    }
    const outcome = controlRound(a, call);
    if (outcome == .abandoned) owned = false;
    controlFinish(call, outcome, w);
}

const ControlOutcome = enum { answered, abandoned, gone, too_slow, wacli_failed };

fn controlFinish(call: *ControlCall, outcome: ControlOutcome, w: *std.Io.Writer) void {
    const problem = switch (outcome) {
        .answered => return w.writeAll(call.out.written()) catch {},
        .abandoned => "Wazig did not answer within 10 s",
        .gone => "Wazig is closing",
        .too_slow => "timed out waiting for the app (chat still loading?)",
        .wacli_failed => "could not read the WhatsApp chat list",
    };
    control_api.writeError(w, problem) catch {};
}

fn controlRound(a: *App, call: *ControlCall) ControlOutcome {
    const hwnd = a.hwnd orelse return .gone;
    const deadline = win.GetTickCount64() + control_not_ready_retry_window_ms;
    while (true) {
        call.out.clearRetainingCapacity();
        call.retry = false;
        call.need_whatsapp = false;
        call.state.store(control_call_posted, .release);
        switch (control_pipe.callUi(hwnd, wm_control, call, call.event, control_ui_reply_timeout_ms)) {
            .gone => return .gone,
            .timeout => {
                if (call.state.cmpxchgStrong(control_call_posted, control_call_abandoned, .acq_rel, .acquire) == null) return .abandoned;
                control_pipe.waitForever(call.event);
            },
            .done => {},
        }
        if (call.need_whatsapp) {
            if (call.whatsapp_raw.len > 0) return .wacli_failed;
            call.whatsapp_raw = controlReadWhatsAppChats(a, call.parsed.value.archived) orelse return .wacli_failed;
            continue;
        }
        if (!call.retry) return .answered;
        if (win.GetTickCount64() >= deadline) return .too_slow;
        win.Sleep(200);
    }
}

fn controlReadWhatsAppChats(a: *App, archived: bool) ?[]u8 {
    if (hubConfigured(a)) return readHubChats(a, archived);
    const run = child_process.run(a.allocator, a.io, .{
        .argv = &.{ a.wacli_path, "--json", "--read-only", "chats", "list", "--limit", "250", if (archived) "--archived" else "--no-archived" },
        .stdout_limit = .limited(8 * 1024 * 1024),
        .stderr_limit = .limited(64 * 1024),
        .create_no_window = true,
    }) catch return null;
    a.allocator.free(run.stderr);
    const ok = switch (run.term) {
        .exited => |code| code == 0,
        else => false,
    };
    if (ok and run.stdout.len > 0) return run.stdout;
    a.allocator.free(run.stdout);
    return null;
}

fn controlOnUi(a: *App, call: *ControlCall) void {
    controlDispatch(a, call) catch {
        call.out.clearRetainingCapacity();
        control_api.writeError(&call.out.writer, "out of memory") catch {};
    };
    if (call.state.cmpxchgStrong(control_call_posted, control_call_answered, .acq_rel, .acquire) == null) {
        _ = win.SetEvent(call.event);
    } else controlCallDestroy(a, call);
}

fn controlDispatch(a: *App, call: *ControlCall) !void {
    const request = &call.parsed.value;
    const w = &call.out.writer;
    if (call.phase == .select or request.cmd == .select or request.cmd == .search or request.cmd == .view) {
        if (a.image_viewer_window != null) closeImageViewer(a);
    }
    switch (request.cmd) {
        .search, .view, .archive, .unarchive, .@"archive-many" => a.user_viewed = false,
        else => {},
    }
    if (call.phase == .select) return controlSelect(a, call);
    switch (request.cmd) {
        .theme => {
            const choice = request.theme orelse return control_api.writeError(w, "theme needs green or amoled");
            if (!changeTheme(a, choice)) return control_api.writeError(w, "could not change theme");
            try w.print("{{\"ok\":true,\"result\":{{\"theme\":\"{s}\"}}}}\n", .{@tagName(theme.choice)});
        },
        .status => try controlStatus(a, w),
        .chats => try controlChats(a, call),
        .search => try controlSearch(a, call),
        .view => try controlView(a, w, request),
        .select => try controlSelect(a, call),
        .messages => try controlMessages(a, call),
        .archive, .unarchive => {
            if (request.id.len == 0) return control_api.writeError(w, "needs a chat id");
            if (archiveChat(a, archiveChatKey(a, request.id), if (request.cmd == .unarchive) .unarchive else .archive, .control)) |problem| return control_api.writeError(w, problem);
            try w.writeAll("{\"ok\":true,\"result\":{\"id\":");
            try control_api.writeString(w, request.id);
            try w.print(",\"queued\":\"{s}\"}}}}\n", .{@tagName(request.cmd)});
        },
        .@"archive-many" => try controlArchiveMany(a, w, request.ids),
    }
}

fn controlProvider(messenger: control_api.Messenger) messenger_view.View {
    return switch (messenger) {
        .all => .all,
        .whatsapp => .whatsapp,
        .slack => .slack,
        .telegram => .telegram,
        .signal => .signal,
    };
}

fn controlWriteChat(a: *const App, w: *std.Io.Writer, chat: *const Chat) !void {
    try w.writeAll("{\"id\":");
    try control_api.writeString(w, chat.jid.slice());
    try w.print(",\"provider\":\"{s}\",\"account\":", .{@tagName(chat.provider)});
    try control_api.writeString(w, chat.account.slice());
    try w.writeAll(",\"view_account\":");
    try control_api.writeString(w, chatViewKey(chat).account);
    try w.print(",\"saved\":{}", .{chat.saved});
    try w.writeAll(",\"name\":");
    try control_api.writeStringUtf16(w, chat.name.slice());
    try w.writeAll(",\"kind\":");
    try control_api.writeStringUtf16(w, chat.kind.slice());
    try w.print(",\"messenger\":\"{s}\",\"unread\":{},\"unread_count\":{d},\"pinned\":{},\"archived\":{},\"last_message_time\":", .{
        @tagName(chat.provider),            chat.unread or chat.unread_count > 0, chat.unread_count,
        isChatPinned(a, chat_key.of(chat)), chat.archived,
    });
    try control_api.writeString(w, chat.timestamp.slice());
    try w.writeAll(",\"archive_label\":");
    try control_api.writeStringUtf16(w, if (archiveMarker(a, chat)) |marker| std.mem.span(marker) else &.{});
    try w.writeByte('}');
}

fn controlSearchText(a: *App, buffer: *[1024]u8) []const u8 {
    const search = a.search orelse return "";
    var wide: [256]u16 = undefined;
    const len: usize = @intCast(win.GetWindowTextW(search, &wide, wide.len));
    const bytes = std.unicode.utf16LeToUtf8(buffer, wide[0..len]) catch return "";
    return buffer[0..bytes];
}

fn controlStatus(a: *App, w: *std.Io.Writer) !void {
    const sync = if (a.accounts_maintenance) "maintenance" else if (a.sync_logged_out) "logged_out" else if (a.sync_child != null) "running" else "stopped";
    const pending_sends = a.pending_send_count + wacliPendingGet(a, .slack_send) + wacliPendingGet(a, .slack_attach) + wacliPendingGet(a, .slack_share);
    try w.print("{{\"ok\":true,\"result\":{{\"version\":\"{s}\",\"view\":\"{s}\",\"selected\":", .{ app_version, @tagName(activeChatView(a)) });
    if (a.selected_chat < a.chat_count) try controlWriteChat(a, w, &a.chats[a.selected_chat]) else try w.writeAll("null");
    try w.writeAll(",\"current_view\":");
    try controlWriteView(w, currentViewKey(a), activeViewLabel(a));
    try w.writeAll(",\"view_order\":[");
    for (a.views.items, 0..) |*view, index| {
        if (index > 0) try w.writeByte(',');
        try controlWriteView(w, view.key.key(), view.labelText());
    }
    try w.writeByte(']');
    try w.print(",\"include_archived\":{}", .{a.include_archived});
    var buffer: [1024]u8 = undefined;
    try w.print(",\"sync\":\"{s}\",\"slack_connected\":{},\"pending_sends\":{d},\"pending_archives\":{d},\"slack_chat_count\":{d},\"chat_count\":{d},\"show_archived\":{},\"unread_only\":{},\"search\":", .{
        sync,              a.slack_connected.load(.acquire), pending_sends,   a.pending_archive_count,
        slackChatCount(a), a.chat_count,                     a.show_archived, a.unread_only,
    });
    try control_api.writeString(w, controlSearchText(a, &buffer));
    try w.print(",\"theme\":\"{s}\",\"staged_attachment_count\":{d}", .{ @tagName(theme.choice), a.staged_images.count });
    try w.writeAll(",\"paints\":");
    try a.paints.write(w);
    const box = a.compose_pill;
    try w.print(",\"composer\":{{\"box\":{{\"left\":{d},\"top\":{d},\"right\":{d},\"bottom\":{d}}},\"lines\":{d},\"controls\":[", .{ box.left, box.top, box.right, box.bottom, if (a.compose) |edit| win.SendMessageW(edit, win.EM_GETLINECOUNT, 0, 0) else 0 });
    const controls = [_]?win.HWND{ a.attach_btn, a.compose, a.voice_btn, a.dictate, a.emoji_btn, a.send };
    const names = [_][]const u8{ "attach", "text", "mic", "dictate", "emoji", "send" };
    for (controls, names, 0..) |control, name, index| {
        if (index > 0) try w.writeByte(',');
        var rect = std.mem.zeroes(win.RECT);
        if (control) |child| {
            _ = win.GetWindowRect(child, &rect);
            _ = win.MapWindowPoints(null, a.hwnd.?, @ptrCast(&rect), 2);
        }
        try w.print("{{\"name\":\"{s}\",\"left\":{d},\"top\":{d},\"right\":{d},\"bottom\":{d}}}", .{ name, rect.left, rect.top, rect.right, rect.bottom });
    }
    try w.writeAll("]}");
    try controlSlackThreads(a, w);
    const memory = readMemorySnapshot();
    try w.print(",\"memory\":{{\"working_set_kb\":{d},\"private_kb\":{d},\"module_count\":{d},\"media_foundation_loaded\":{}}}", .{
        memory.working_set_bytes / 1024,
        memory.private_bytes / 1024,
        memory.module_count,
        mf_lazy.isStarted(),
    });
    try w.writeAll("}}\n");
}

fn controlMatches(a: *App, chat: *const Chat, query: []const u8) bool {
    if (query.len == 0) return true;
    if (containsIgnoreCase(chat.jid.slice(), query)) return true;
    const name = std.unicode.utf16LeToUtf8Alloc(a.allocator, chat.name.slice()) catch return false;
    defer a.allocator.free(name);
    return containsIgnoreCase(name, query);
}

fn controlChats(a: *App, call: *ControlCall) !void {
    const request = &call.parsed.value;
    const w = &call.out.writer;
    const active = activeChatView(a);
    const view = if (request.messenger) |messenger| controlProvider(messenger) else active;
    var list: std.ArrayList(Chat) = .empty;
    defer list.deinit(a.allocator);
    var query_buffer: [1024]u8 = undefined;
    const query = controlSearchText(a, &query_buffer);
    var filtered = query.len > 0 and !request.all;
    if (request.messenger == null and view == active and request.archived == a.show_archived and !request.all) {
        try list.appendSlice(a.allocator, a.chats[0..a.chat_count]);
        filtered = filtered or a.unread_only;
    } else {
        const wanted = if (request.all) "" else query;
        if (!unifiedHub(a) and messenger_view.includes(view, .slack)) {
            for (&a.slack_installations) |*installation| {
                if (!installation.active) continue;
                for (installation.chats[0..installation.chat_count]) |*chat| {
                    chat.archived = if (a.archive_state) |state| state.localArchived(chat_key.of(chat)) else false;
                    if (chat.archived != request.archived) continue;
                    if ((request.messenger != null or chatInView(a, chat_key.of(chat))) and controlMatches(a, chat, wanted)) try list.append(a.allocator, chat.*);
                }
            }
        }
        if (!unifiedHub(a) and messenger_view.includes(view, .telegram) and !request.archived and telegramReady(a) and a.tg_account.len > 0) {
            for (a.tg_chats[0..a.tg_chat_count]) |*cached| {
                var chat = Chat{ .name = cached.name, .unread = cached.unread_count > 0, .unread_count = cached.unread_count, .provider = .telegram, .account = a.tg_account };
                var id_buffer: [24]u8 = undefined;
                chat.jid.set(tgChatIdString(&id_buffer, cached.id));
                chat.kind.set(a.allocator, cached.kind.slice());
                chat.timestamp.set(cached.timestamp.slice());
                if ((request.messenger != null or chatInView(a, chat_key.of(&chat))) and controlMatches(a, &chat, wanted)) try list.append(a.allocator, chat);
            }
        }
        if (unifiedHub(a) or messenger_view.includes(view, .whatsapp)) {
            if (call.whatsapp_raw.len == 0) {
                call.need_whatsapp = true;
                return;
            }
            controlWhatsAppChats(a, call.whatsapp_raw, view, if (request.messenger == null) a.view_account.slice() else "", request.archived, wanted, &list) catch |err| switch (err) {
                error.OutOfMemory => return err,
                else => return control_api.writeError(w, "could not parse the WhatsApp chat list"),
            };
        }
        controlSortChats(a, list.items, view);
    }
    const shown = @min(list.items.len, request.limit orelse std.math.maxInt(u32));
    try w.print("{{\"ok\":true,\"result\":{{\"messenger\":\"{s}\",\"archived\":{},\"filtered\":{},\"total\":{d},\"chats\":[", .{ @tagName(view), request.archived, filtered, list.items.len });
    for (list.items[0..shown], 0..) |*chat, index| {
        if (index > 0) try w.writeByte(',');
        try controlWriteChat(a, w, chat);
    }
    try w.writeAll("]}}\n");
}

fn controlWhatsAppChats(a: *App, raw: []const u8, view: messenger_view.View, account: []const u8, show_archived: bool, query: []const u8, list: *std.ArrayList(Chat)) !void {
    var parsed = try std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{});
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return error.BadChatList,
    };
    const data = switch (root.get("data") orelse return error.BadChatList) {
        .array => |items| items,
        else => return error.BadChatList,
    };
    for (data.items) |item| {
        const object = switch (item) {
            .object => |object| object,
            else => continue,
        };
        const jid = getString(object, "jid");
        if (pendingArchiveHidesChat(a, jid, show_archived)) continue;
        const display_name = groupName(a, jid) orelse getString(object, "name");
        if (isUnresolvableChatEntry(display_name, jid, getString(object, "kind"))) continue;
        if (query.len > 0 and !containsIgnoreCase(display_name, query) and !containsIgnoreCase(jid, query)) continue;
        var chat = Chat{ .account = a.cache_tag };
        if (unifiedHub(a)) {
            chat.provider = hub.sourceProvider(object) orelse continue;
            chat.account.set(hub.sourceAccount(object, a.cache_tag.slice()));
            chat.view_account.set(hub.viewAccount(object, a.cache_tag.slice()));
            chat.saved = hub.savedMessages(object);
        }
        chat.jid.set(jid);
        if (!messenger_view.accountMatches(view, account, chatViewKey(&chat))) continue;
        chat.name.set(a.allocator, if (chat.saved) "Saved Messages" else display_name);
        chat.kind.set(a.allocator, if (std.mem.endsWith(u8, jid, "@g.us")) "Group" else getString(object, "kind"));
        chat.timestamp.set(getString(object, "last_message_ts"));
        fillSlackTimestamp(a, &chat);
        chat.unread = getBool(object, "unread");
        chat.unread_count = getInt(object, "unread_count");
        chat.archived = if (a.archive_state) |state| state.isArchived(chat_key.of(&chat), getBool(object, "archived")) else getBool(object, "archived");
        if (chat.archived != show_archived) continue;
        try list.append(a.allocator, chat);
    }
}

fn controlSortChats(a: *const App, chats: []Chat, view: messenger_view.View) void {
    var i: usize = 1;
    while (i < chats.len) : (i += 1) {
        var j = i;
        while (j > 0) : (j -= 1) {
            const by_time = std.mem.order(u8, chats[j - 1].timestamp.slice(), chats[j].timestamp.slice());
            const by_name = std.mem.order(u16, chats[j - 1].name.slice(), chats[j].name.slice());
            const jid_order = chat_key.order(chat_key.of(&chats[j - 1]), chat_key.of(&chats[j]));
            const move = if (view == .all) messenger_view.inboxMoveUp(by_time, jid_order) else chat_order.shouldMoveUp(isChatPinned(a, chat_key.of(&chats[j - 1])), isChatPinned(a, chat_key.of(&chats[j])), by_time, by_name, jid_order);
            if (!move) break;
            std.mem.swap(Chat, &chats[j - 1], &chats[j]);
        }
    }
}

fn controlSearch(a: *App, call: *ControlCall) !void {
    const w = &call.out.writer;
    const search = a.search orelse return control_api.writeError(w, "the search box is not ready");
    if (call.phase == .main) {
        const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, call.parsed.value.text) catch
            return control_api.writeError(w, "search text is not valid UTF-8");
        defer a.allocator.free(wide);
        _ = win.SetWindowTextW(search, wide.ptr);
        if (a.hwnd) |hwnd| _ = win.KillTimer(hwnd, timer_search);
        refilterChats(a);
        if (!messagesAreCurrent(a)) refreshMessages(a);
        call.phase = .wait;
        call.retry = true;
        return;
    }
    if (wacliPendingGet(a, .chats) > 0) {
        call.retry = true;
        return;
    }
    var buffer: [1024]u8 = undefined;
    try w.writeAll("{\"ok\":true,\"result\":{\"search\":");
    try control_api.writeString(w, controlSearchText(a, &buffer));
    try w.print(",\"chat_count\":{d}}}}}\n", .{a.chat_count});
}

fn controlWriteView(w: *std.Io.Writer, key: ?chat_key.Key, label: []const u8) !void {
    try w.writeAll("{\"provider\":");
    if (key) |value| try control_api.writeString(w, @tagName(value.provider)) else try w.writeAll("null");
    try w.writeAll(",\"account\":");
    if (key) |value| try control_api.writeString(w, value.account) else try w.writeAll("null");
    try w.writeAll(",\"label\":");
    try control_api.writeString(w, label);
    try w.print(",\"inbox\":{}}}", .{key == null});
}

fn controlView(a: *App, w: *std.Io.Writer, request: *const control_api.Request) !void {
    if (request.view_number) |number| {
        const index = messenger_view.forNumber(number, a.views.items) orelse return control_api.writeError(w, "view number is not available");
        switchAccountView(a, a.views.items[index].key.key());
    } else {
        const view = controlProvider(request.messenger orelse return control_api.writeError(w, "view needs a number, inbox or provider"));
        if (view != .all) {
            for (a.views.items) |account| {
                if (messenger_view.includes(view, account.key.provider)) break;
            } else return control_api.writeError(w, "account is not available");
        }
        switchChatView(a, view);
    }
    try w.print("{{\"ok\":true,\"result\":{{\"view\":\"{s}\",\"current_view\":", .{@tagName(activeChatView(a))});
    try controlWriteView(w, currentViewKey(a), activeViewLabel(a));
    try w.writeAll("}}\n");
}

fn currentViewKey(a: *App) ?chat_key.Key {
    for (a.views.items) |*view| if (a.view_account.len > 0 and chatInView(a, view.key.key())) return view.key.key();
    return null;
}

fn controlSelectIndex(a: *App, index: usize) void {
    if (index != a.selected_chat) {
        clearReply(a);
        discardStagedImage(a);
    }
    a.selected_chat = index;
    switchComposerDraft(a);
    a.user_viewed = true;
    selectedViewKey(a).set(chat_key.of(&a.chats[index]));
    if (a.chats_hwnd) |list| _ = win.SendMessageW(list, win.LB_SETCURSEL, index, 0);
    refreshMessages(a);
    if (a.hwnd) |hwnd| _ = win.InvalidateRect(hwnd, null, win.FALSE);
}

fn controlSelect(a: *App, call: *ControlCall) !void {
    const w = &call.out.writer;
    const request = &call.parsed.value;
    if (request.id.len == 0) return control_api.writeError(w, "needs a chat id");
    var selected: ?chat_key.Stored = null;
    var ambiguous = false;
    for (a.chats[0..a.chat_count]) |*chat| {
        const key = chat_key.of(chat);
        if (!std.mem.eql(u8, key.id, request.id)) continue;
        if (request.provider) |provider| if (key.provider != provider) continue;
        if (request.account.len > 0 and !std.mem.eql(u8, request.account, key.account)) continue;
        if (selected != null) {
            ambiguous = true;
            break;
        }
        selected = .{};
        selected.?.set(key);
    }
    if (ambiguous) return control_api.writeError(w, "ambiguous chat id: specify --provider and --account");
    if (selected == null and request.provider != null) {
        const provider = request.provider.?;
        const account = if (request.account.len > 0) request.account else if (provider == .whatsapp) a.cache_tag.slice() else "";
        var wanted = chat_key.Stored{};
        wanted.set(.{ .provider = provider, .account = account, .id = request.id });
        a.view_selected[@intFromEnum(messenger_view.View.all)] = wanted;
        switchChatView(a, .all);
        if (visibleChatIndex(a, wanted.key()) != null) selected = wanted;
    }
    const found = if (selected) |*key| visibleChatIndex(a, key.key()) else null;
    const index = found orelse {
        if (wacliPendingGet(a, .chats) > 0) {
            call.retry = true;
            return;
        }
        return control_api.writeError(w, "chat is not in the sidebar list (clear search or select All networks)");
    };
    controlSelectIndex(a, index);
    try w.writeAll("{\"ok\":true,\"result\":{\"selected\":");
    try controlWriteChat(a, w, &a.chats[index]);
    try w.writeAll("}}\n");
}

fn controlMessages(a: *App, call: *ControlCall) !void {
    const request = &call.parsed.value;
    const w = &call.out.writer;
    if (a.selected_chat >= a.chat_count) return control_api.writeError(w, "no chat is selected");
    const chat = &a.chats[a.selected_chat];
    const wrong_chat = request.id.len > 0 and !std.mem.eql(u8, chat.jid.slice(), request.id);
    if (wrong_chat or !chat_key.Key.eql(chat_key.displayed(a), chat_key.of(chat))) {
        call.retry = true;
        return;
    }
    const count = @min(a.message_count, request.limit orelse max_messages);
    try w.writeAll("{\"ok\":true,\"result\":{\"chat\":");
    try controlWriteChat(a, w, chat);
    try w.writeAll(",\"messages\":[");
    for (a.messages[a.message_count - count .. a.message_count], 0..) |*message, index| {
        if (index > 0) try w.writeByte(',');
        try w.writeAll("{\"id\":");
        try control_api.writeString(w, message.id.slice());
        try w.writeAll(",\"sender\":");
        try control_api.writeStringUtf16(w, message.sender.slice());
        try w.writeAll(",\"sender_id\":");
        try control_api.writeString(w, message.sender_jid.slice());
        try w.writeAll(",\"time\":");
        try control_api.writeString(w, message.timestamp.slice());
        try w.writeAll(",\"text\":");
        try control_api.writeStringUtf16(w, message.text.slice());
        try w.writeAll(",\"quote\":");
        try control_api.writeStringUtf16(w, message.quote.slice());
        try w.writeAll(",\"links\":[");
        for (message.links[0..message.link_count], 0..) |*link, link_index| {
            if (link_index > 0) try w.writeByte(',');
            try control_api.writeStringUtf16(w, link.url.slice());
        }
        try w.writeAll("],\"preview\":{\"kind\":");
        try control_api.writeString(w, @tagName(message.unfurl_provider));
        var preview: ?*const UnfurlEntry = null;
        for (a.unfurl_entries[0..a.unfurl_entry_count]) |*entry| {
            if (entry.provider == message.unfurl_provider and std.mem.eql(u8, entry.id.slice(), message.unfurl_id.slice())) {
                preview = entry;
                break;
            }
        }
        try w.writeAll(",\"title\":");
        try control_api.writeStringUtf16(w, if (preview) |entry| entry.title.slice() else &.{});
        try w.writeAll(",\"site\":");
        try control_api.writeStringUtf16(w, if (preview) |entry| entry.author.slice() else &.{});
        try w.writeAll(",\"description\":");
        try control_api.writeStringUtf16(w, if (preview) |entry| entry.description.slice() else &.{});
        try w.print(",\"ready\":{},\"image\":{}}}", .{ if (preview) |entry| entry.status == .ready else false, if (preview) |entry| entry.thumb != null else false });
        try w.writeAll(",\"reaction\":");
        try control_api.writeStringUtf16(w, message.reaction.slice());
        try w.writeAll(",\"my_reaction\":");
        try control_api.writeString(w, message.my_reaction.slice());
        try w.print(",\"gif_frames\":{d},\"gif_frame\":{d}", .{ message.gif_frame_count, message.gif_frame_index });
        try w.writeAll(",\"media_type\":");
        try control_api.writeString(w, message.media_type.slice());
        try w.print(",\"local\":{},\"transcript_chars\":{d},\"expanded\":{}", .{ message.local_path.len > 0, message.transcript.len, message.transcript_expanded });
        for ([_]struct { name: []const u8, rect: win.RECT }{
            .{ .name = "bubble", .rect = message.bubble_hit },
            .{ .name = "reaction_chip", .rect = message.reaction_hit },
            .{ .name = "media", .rect = message.media_hit },
            .{ .name = "card", .rect = message.unfurl_card_hit },
            .{ .name = "toggle", .rect = message.toggle_hit },
        }) |entry| try w.print(",\"{s}\":[{d},{d},{d},{d}]", .{ entry.name, entry.rect.left, entry.rect.top, entry.rect.right, entry.rect.bottom });
        try w.print(",\"from_me\":{},\"revoked\":{},\"send_state\":\"{s}\"}}", .{ message.from_me, message.revoked, @tagName(message.send_state) });
    }
    try w.writeAll("]}}\n");
}

fn controlArchiveMany(a: *App, w: *std.Io.Writer, ids: []const []const u8) !void {
    if (ids.len == 0) return control_api.writeError(w, "needs at least one chat id");
    const problems = try a.allocator.alloc(?[]const u8, ids.len);
    defer a.allocator.free(problems);
    var failed: usize = 0;
    for (ids, problems) |id, *problem| {
        problem.* = archiveChat(a, archiveChatKey(a, id), .archive, .control);
        if (problem.* != null) failed += 1;
    }
    if (failed == 0) try w.writeAll("{\"ok\":true,\"result\":{\"results\":[") else try w.print("{{\"ok\":false,\"error\":\"{d} of {d} chats could not be archived\",\"result\":{{\"results\":[", .{ failed, ids.len });
    for (ids, problems, 0..) |id, problem, index| {
        if (index > 0) try w.writeByte(',');
        try w.writeAll("{\"id\":");
        try control_api.writeString(w, id);
        if (problem) |text| {
            try w.writeAll(",\"ok\":false,\"error\":");
            try control_api.writeString(w, text);
            try w.writeByte('}');
        } else try w.writeAll(",\"ok\":true}");
    }
    try w.writeAll("]}}\n");
}

fn appendPalette(a: *App, label: []const u8, shortcut: []const u8, command: u16) void {
    if (a.palette_item_count >= max_palette_items) return;
    const item = &a.palette_items[a.palette_item_count];
    a.palette_item_count += 1;
    item.label.set(a.allocator, label);
    item.shortcut.set(a.allocator, shortcut);
    item.command = command;
    item.url = .{};
    item.chat_jid = .{};
    item.chat_identity = .{};
    item.view_identity = .{};
    item.message_id = .{};
}

fn appendPaletteChat(a: *App, index: usize) void {
    if (a.palette_item_count >= max_palette_items) return;
    const chat = &a.chats[index];
    if (chat.name.len == 0) return;
    const item = &a.palette_items[a.palette_item_count];
    a.palette_item_count += 1;
    item.label.len = @min(chat.name.len, item.label.buf.len - 1);
    @memcpy(item.label.buf[0..item.label.len], chat.name.buf[0..item.label.len]);
    item.label.buf[item.label.len] = 0;
    item.shortcut.set(a.allocator, "");
    item.command = 0;
    item.url = .{};
    item.message_id = .{};
    item.chat_jid.set(chat.jid.slice());
    item.chat_identity.set(chat_key.of(chat));
    item.view_identity = .{};
}

fn appendMicrophones(a: *App) void {
    a.mic_count = mic_choice.list(&a.mic_names);
    const picked = mic_choice.current();
    appendPalette(a, if (picked.len == 0) "Microphone: System default (in use)" else "Microphone: System default", "", command_mic_default);
    for (a.mic_names[0..a.mic_count], 0..) |*name, index| {
        var label: [mic_choice.name_cap + 40]u8 = undefined;
        const in_use = std.mem.eql(u8, name.slice(), picked);
        const text = std.fmt.bufPrint(&label, "Microphone: {s}{s}", .{ name.slice(), if (in_use) " (in use)" else "" }) catch continue;
        appendPalette(a, text, "", @intCast(command_mic_default + 1 + index));
    }
}

fn buildPaletteItems(a: *App) void {
    a.palette_archive_key.set(if (a.selected_chat < a.chat_count) chat_key.of(&a.chats[a.selected_chat]) else .{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = "" });
    a.palette_archive_bulk_count = a.bulk.count;
    a.palette_archive_show_archived = a.show_archived;
    a.palette_archive_was_archived = a.selected_chat < a.chat_count and a.chats[a.selected_chat].archived;
    a.palette_item_count = 0;
    appendPalette(a, "Search chats", "Ctrl+F", command_search);
    appendPalette(a, "Compose message", "C", command_compose);
    if (slackThreadsAccount(a).len > 0) appendPalette(a, "Slack threads like Slack for this account", if (slackThreadsEnabled(a)) "On" else "Off", command_slack_threads);
    appendPalette(a, "Keyboard shortcuts", "F1", command_shortcuts_help);
    appendPalette(a, "Dictate", "Ctrl+D", command_dictate);
    appendPalette(a, "Dictation language: Automatic", "", command_dictation_auto);
    appendPalette(a, "Dictation language: English", "", command_dictation_english);
    appendPalette(a, "Dictation language: German", "", command_dictation_german);
    appendMicrophones(a);
    appendPalette(a, "Playback speed: 1x", "", command_speed_1);
    appendPalette(a, "Playback speed: 1.5x", "", command_speed_150);
    appendPalette(a, "Playback speed: 2x", "", command_speed_200);
    appendPalette(a, "Make text smaller", "Ctrl+-", command_font_smaller);
    appendPalette(a, "Make text larger", "Ctrl++", command_font_larger);
    appendPalette(a, "Reset text size", "Ctrl+0", command_font_reset);
    appendPalette(a, "Theme: AMOLED black", "", command_theme_amoled);
    appendPalette(a, "Theme: Green", "", command_theme_green);
    appendPalette(a, "Toggle unread chats", "U", command_unread);
    appendPalette(a, "Show combined inbox", "Alt+I", command_show_all);
    appendPalette(a, "Sort views", "", command_sort_views);
    for (a.views.items, 0..) |*view, index| {
        var shortcut: [16]u8 = undefined;
        var label_buffer: [300]u8 = undefined;
        const before = a.palette_item_count;
        appendPalette(a, std.fmt.bufPrint(&label_buffer, "Show {s}", .{view.labelText()}) catch continue, if (index < 9) std.fmt.bufPrint(&shortcut, "Alt+{d}", .{index + 1}) catch "" else "", 0);
        if (a.palette_item_count > before) a.palette_items[before].view_identity = view.key;
    }
    appendPalette(a, if (a.selected_chat < a.chat_count and isChatPinned(a, chat_key.of(&a.chats[a.selected_chat]))) "Unpin selected chat" else "Pin chat to top", "", command_pin);
    appendPalette(a, "Toggle archived chats in this view", "Alt+A", command_include_archived);
    appendPalette(a, if (a.show_archived) "Show inbox chats" else "Show archived chats", "", command_archived);
    appendPalette(a, if (a.show_archived or (a.selected_chat < a.chat_count and a.chats[a.selected_chat].archived)) "Unarchive selected chat" else "Archive selected chat", "Ctrl+E", command_archive);
    appendPalette(a, "Reply to selected message", "Ctrl+Shift+R", command_reply);
    appendPalette(a, "Resend failed message", "", command_resend);
    appendPalette(a, "React to selected message", "Ctrl+R", command_react_menu);
    appendPalette(a, "Copy message text", "Ctrl+C", command_copy_text);
    appendPalette(a, "Copy message link", "", command_copy_link);
    appendPalette(a, "Copy transcript", "", command_copy_transcript);
    appendPalette(a, "Play or pause voice message", "Ctrl+P", command_play_audio);
    appendPalette(a, "Show or hide transcript", "Ctrl+T", command_toggle_transcript);
    appendPalette(a, "Select next message", "Alt+J", command_next_message);
    appendPalette(a, "Select previous message", "Alt+K", command_prev_message);
    appendPalette(a, "Jump to latest message", "Alt+G", command_jump_latest);
    appendPalette(a, "Open links in message", "Ctrl+O", command_links);
    appendPalette(a, "Next chat", "Ctrl+Tab", command_next_chat);
    appendPalette(a, "Previous chat", "Ctrl+Shift+Tab", command_prev_chat);
    appendPalette(a, "Insert emoji", "", command_emoji);
    if (emoji_draw.failureNotice() != null) appendPalette(a, "Why are emoji black and white?", "", command_emoji_diag);
    appendPalette(a, "Send message", "Enter", command_send);
    appendPalette(a, "React to message: 👍 Like", "", reaction_like);
    appendPalette(a, "React to message: ❤️ Love", "", reaction_love);
    appendPalette(a, "React to message: 😂 Laugh", "", reaction_laugh);
    appendPalette(a, "React to message: 😮 Surprised", "", reaction_surprised);
    appendPalette(a, "React to message: 😢 Sad", "", reaction_sad);
    appendPalette(a, "React to message: 🙏 Thanks", "", reaction_thanks);
    appendPalette(a, "Remove reaction", "", reaction_remove);
    appendPalette(a, "Refresh", "R", command_refresh);
    appendPalette(a, "Restart live sync", "S", command_sync);
    appendPalette(a, "Manage accounts", "", command_accounts);
    if (!hubConfigured(a)) {
        if (a.tg_auth == .ready) {
            appendPalette(a, "Log out of Telegram", "", command_telegram_logout);
        } else {
            appendPalette(a, "Connect Telegram account", "", command_telegram_login);
        }
    }
    appendPalette(a, "Open video in external player", "", command_open_video_external);
    appendPalette(a, "Open image in Windows viewer", "", command_open_image_external);
    appendPalette(a, "Attach photo or file", "", command_slack_attach);
    appendPalette(a, "Connect Slack workspace", "", command_slack_connect);
    appendPalette(a, "Slack sign-in settings", "", command_slack_setup);
    for (&a.slack_installations, 0..) |*installation, index| {
        if (!installation.active) continue;
        var label: [256]u8 = undefined;
        appendPalette(a, std.fmt.bufPrint(&label, "Disconnect Slack workspace: {s}", .{installation.team_name.slice()}) catch "Disconnect Slack workspace", "", @intCast(command_slack_disconnect_workspace + index));
    }
    appendPalette(a, "Check for updates now", "", command_update_check);
    if (a.update_pending != null) appendPalette(a, "Restart now to install update", "", command_update_install);
    appendPalette(a, "Quit Messages", "Q", command_quit);
    for (0..a.chat_count) |index| appendPaletteChat(a, index);
    a.palette_base_item_count = a.palette_item_count;
}

fn lowerUnit(unit: u16) u16 {
    return if (unit >= 'A' and unit <= 'Z') unit + 32 else unit;
}

fn paletteScore(label: []const u16, query: []const u16) ?i32 {
    var score: i32 = 0;
    var text_index: usize = 0;
    var previous: ?usize = null;
    for (query) |query_unit| {
        const wanted = lowerUnit(query_unit);
        var matched = false;
        while (text_index < label.len) : (text_index += 1) {
            if (lowerUnit(label[text_index]) != wanted) continue;
            score += 1;
            if (previous) |previous_index| {
                if (text_index == previous_index + 1) score += 4 else score -= @intCast(@min(text_index - previous_index, 8));
            }
            if (text_index == 0 or label[text_index - 1] == ' ' or label[text_index - 1] == ':') score += 3;
            previous = text_index;
            text_index += 1;
            matched = true;
            break;
        }
        if (!matched) return null;
    }
    return score;
}

fn paletteLayout(a: *App) void {
    const palette = a.palette orelse return;
    const rows: i32 = @intCast(@max(1, @min(a.palette_match_count, palette_max_rows)));
    const height = palette_edit_zone + rows * palette_row_height + 12;
    _ = win.SetWindowPos(palette, null, 0, 0, palette_width, height, win.SWP_NOMOVE | win.SWP_NOZORDER | win.SWP_NOACTIVATE);
    if (a.palette_list) |list| {
        _ = win.MoveWindow(list, 1, palette_edit_zone, palette_width - 2 - scrollbar_width, height - palette_edit_zone - 1, win.TRUE);
    }
}

fn appendPalettePeople(a: *App, query_wide: []const u16, scores: *[max_palette_items]i32, scored: bool) void {
    if (a.palette_links_mode or a.palette_accounts_mode or a.palette_views_mode or query_wide.len == 0) return;
    const query = std.unicode.utf16LeToUtf8Alloc(a.allocator, query_wide) catch return;
    defer a.allocator.free(query);
    var exclude: [max_palette_items]people_index.Identity = undefined;
    var exclude_count: usize = 0;
    for (a.palette_matches[0..a.palette_match_count]) |match| {
        const item = &a.palette_items[match];
        if (item.chat_jid.len == 0) continue;
        const key = item.chat_identity.key();
        exclude[exclude_count] = .{ .provider = @tagName(key.provider), .account = key.account, .id = key.id };
        exclude_count += 1;
    }
    var matches: [20]people_index.Entry = undefined;
    const count = a.people.search(query, exclude[0..exclude_count], a.cache_tag.slice(), &matches, 20);
    for (matches[0..count]) |entry| {
        if (a.palette_item_count == max_palette_items) break;
        const label = (if (entry.origin == .inbox)
            std.fmt.allocPrint(a.allocator, "{s}", .{entry.name})
        else
            std.fmt.allocPrint(a.allocator, "{s}  ·  {s}", .{ entry.name, if (entry.origin == .archived) "Archived" else "Contact" })) catch continue;
        defer a.allocator.free(label);
        const index = a.palette_item_count;
        appendPalette(a, label, "", 0);
        const item = &a.palette_items[index];
        item.chat_jid.set(entry.jid);
        item.chat_identity.set(.{
            .provider = std.meta.stringToEnum(transport.Provider, entry.provider) orelse .whatsapp,
            .account = if (entry.account.len > 0) entry.account else a.cache_tag.slice(),
            .id = entry.jid,
        });
        a.palette_matches[a.palette_match_count] = index;
        if (scored) scores[a.palette_match_count] = paletteScore(item.label.slice(), query_wide) orelse 0;
        a.palette_match_count += 1;
    }
}

fn paletteFilter(a: *App) void {
    var query_buf: [64]u16 = [_]u16{0} ** 64;
    const query_len: usize = if (a.palette_edit) |edit| @intCast(win.GetWindowTextW(edit, &query_buf, query_buf.len)) else 0;
    if (!a.palette_links_mode and !a.palette_accounts_mode and !a.palette_views_mode) a.palette_item_count = a.palette_base_item_count;
    a.palette_match_count = 0;
    a.palette_selected = 0;
    var scores: [max_palette_items]i32 = [_]i32{0} ** max_palette_items;
    for (0..a.palette_item_count) |index| {
        if (query_len == 0) {
            scores[a.palette_match_count] = 0;
            a.palette_matches[a.palette_match_count] = index;
            a.palette_match_count += 1;
            continue;
        }
        if (paletteScore(a.palette_items[index].label.slice(), query_buf[0..query_len])) |score| {
            scores[a.palette_match_count] = score;
            a.palette_matches[a.palette_match_count] = index;
            a.palette_match_count += 1;
        }
    }
    if (unifiedHub(a)) appendPalettePeople(a, query_buf[0..query_len], &scores, true);
    var i: usize = 1;
    while (i < a.palette_match_count) : (i += 1) {
        var j = i;
        while (j > 0 and scores[j - 1] < scores[j]) : (j -= 1) {
            std.mem.swap(usize, &a.palette_matches[j - 1], &a.palette_matches[j]);
            std.mem.swap(i32, &scores[j - 1], &scores[j]);
        }
    }
    if (!unifiedHub(a) and messenger_view.includes(activeChatView(a), .whatsapp)) appendPalettePeople(a, query_buf[0..query_len], &scores, false);
    if (a.palette_list) |list| {
        _ = win.SendMessageW(list, win.WM_SETREDRAW, 0, 0);
        _ = win.SendMessageW(list, win.LB_RESETCONTENT, 0, 0);
        for (a.palette_matches[0..a.palette_match_count]) |match| {
            _ = win.SendMessageW(list, win.LB_ADDSTRING, 0, @bitCast(@intFromPtr(a.palette_items[match].label.ptr())));
        }
        if (a.palette_match_count > 0) _ = win.SendMessageW(list, win.LB_SETCURSEL, 0, 0);
        _ = win.SendMessageW(list, win.WM_SETREDRAW, 1, 0);
        _ = win.InvalidateRect(list, null, win.TRUE);
    }
    paletteLayout(a);
    if (a.palette) |palette| _ = win.InvalidateRect(palette, null, win.TRUE);
}

fn paletteMove(a: *App, delta: i32) void {
    if (a.palette_match_count == 0) return;
    var next: i32 = @intCast(a.palette_selected);
    next = std.math.clamp(next + delta, 0, @as(i32, @intCast(a.palette_match_count - 1)));
    a.palette_selected = @intCast(next);
    if (a.palette_list) |list| {
        _ = win.SendMessageW(list, win.LB_SETCURSEL, a.palette_selected, 0);
        _ = win.InvalidateRect(list, null, win.FALSE);
    }
}

fn closePalette(a: *App) void {
    a.palette_views_mode = false;
    a.accounts_confirm_remove = false;
    a.accounts_confirm_remove_tg = false;
    if (a.palette) |palette| {
        _ = win.DestroyWindow(palette);
    }
    focusCompose(a);
}

fn paletteActivate(a: *App) void {
    if (a.palette_selected >= a.palette_match_count) return;
    const item = &a.palette_items[a.palette_matches[a.palette_selected]];
    if (item.view_identity.account_len > 0) {
        const wanted = item.view_identity;
        closePalette(a);
        switchAccountView(a, wanted.key());
        return;
    }
    if (item.chat_jid.len > 0) {
        var chat_index: ?usize = null;
        for (a.chats[0..a.chat_count], 0..) |*chat, index| {
            if (chat_key.Key.eql(chat_key.of(chat), item.chat_identity.key())) {
                chat_index = index;
                break;
            }
        }
        if (chat_index == null and (unifiedHub(a) or messenger_view.includes(activeChatView(a), .whatsapp)) and !a.palette_links_mode and !a.palette_accounts_mode and !a.palette_views_mode) {
            if (a.people.find(item.chat_jid.slice())) |entry| {
                const index = @min(a.chat_count, max_chats - 1);
                a.chats[index] = peopleChat(a, entry);
                a.people_open_jid.set(entry.jid);
                if (a.chats_hwnd) |list| {
                    if (a.chat_count == max_chats) _ = win.SendMessageW(list, win.LB_DELETESTRING, index, 0);
                    _ = win.SendMessageW(list, win.LB_ADDSTRING, 0, @bitCast(@intFromPtr(a.chats[index].name.ptr())));
                }
                a.chat_count = index + 1;
                chat_index = index;
            }
        }
        const selected = chat_index orelse {
            appendDebugLog(a, "palette: chat not in current list, jid={s}", .{item.chat_jid.slice()});
            const name_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, item.label.slice()) catch null;
            defer if (name_utf8) |n| a.allocator.free(n);
            if (name_utf8) |n| appendDebugLog(a, "palette: chat name={s}", .{n});
            const status = if (name_utf8) |n|
                std.fmt.allocPrintSentinel(a.allocator, "\"{s}\" is not in the chat list right now. Press R to refresh, then try again.", .{n}, 0) catch null
            else
                null;
            defer if (status) |s| a.allocator.free(s);
            setStatus(a, status orelse "Chat not in the current list. Press R to refresh, then try again.");
            return;
        };
        closePalette(a);
        discardStagedImage(a);
        a.selected_chat = @intCast(selected);
        switchComposerDraft(a);
        if (a.chats_hwnd) |list| _ = win.SendMessageW(list, win.LB_SETCURSEL, selected, 0);
        a.user_viewed = true;
        refreshMessages(a);
        focusCompose(a);
        if (a.hwnd) |hwnd| _ = win.InvalidateRect(hwnd, null, win.FALSE);
        return;
    }
    if (item.url.len > 0) {
        const url_ptr = item.url.ptr();
        closePalette(a);
        openUrlWide(a, url_ptr);
        return;
    }
    if (item.message_id.len > 0) {
        var found: ?usize = null;
        for (a.messages[0..a.message_count], 0..) |*candidate, index| {
            if (std.mem.eql(u8, candidate.id.slice(), item.message_id.slice())) {
                found = index;
                break;
            }
        }
        const index = found orelse {
            setStatus(a, "That attachment is no longer on screen");
            return;
        };
        const message = &a.messages[index];
        if (isImage(message)) {
            closePalette(a);
            openImageInViewerOrQueue(a, index, message);
            return;
        }
        if (message.local_path.len > 0) {
            closePalette(a);
            openMedia(a, message);
            return;
        }
        if (a.selected_chat < a.chat_count and a.chats[a.selected_chat].provider == .whatsapp) {
            _ = downloadMedia(a, index, false);
        } else setStatus(a, "Still downloading");
        return;
    }
    const command = item.command;
    closePalette(a);
    if (command == 0) return;
    if (command == command_archive) {
        archivePaletteSelection(a);
        return;
    }
    runCommand(a, command);
}

fn openPalette(a: *App) void {
    if (a.palette != null) {
        closePalette(a);
        return;
    }
    a.palette_links_mode = false;
    a.palette_accounts_mode = false;
    a.palette_views_mode = false;
    buildPaletteItems(a);
    showPaletteWindow(a);
}

fn openLinkPalette(a: *App) void {
    if (a.palette != null) {
        closePalette(a);
        return;
    }
    a.palette_links_mode = true;
    a.palette_accounts_mode = false;
    a.palette_views_mode = false;
    buildLinkPaletteItems(a);
    if (a.palette_item_count == 0) {
        a.palette_links_mode = false;
        setStatus(a, "Nothing to open on screen");
        return;
    }
    showPaletteWindow(a);
}

fn buildLinkPaletteItems(a: *App) void {
    a.palette_item_count = 0;
    for (a.messages[0..a.message_count]) |*message| {
        if (message.bubble_hit.right <= message.bubble_hit.left) continue;
        for (message.links[0..message.link_count]) |*span| {
            if (span.url.len == 0) continue;
            var duplicate = false;
            for (a.palette_items[0..a.palette_item_count]) |*existing| {
                if (std.mem.eql(u16, existing.url.slice(), span.url.slice())) duplicate = true;
            }
            if (duplicate) continue;
            if (a.palette_item_count >= max_palette_items) return;
            const item = &a.palette_items[a.palette_item_count];
            const url_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, span.url.slice()) catch continue;
            defer a.allocator.free(url_utf8);
            item.label.set(a.allocator, url_utf8);
            item.url.set(a.allocator, url_utf8);
            item.shortcut.set(a.allocator, "");
            item.command = 0;
            item.chat_jid = .{};
            item.chat_identity = .{};
            item.view_identity = .{};
            item.message_id = .{};
            a.palette_item_count += 1;
        }
        if ((isImage(message) or isVideo(message)) and message.id.len > 0) {
            if (a.palette_item_count >= max_palette_items) return;
            const item = &a.palette_items[a.palette_item_count];
            const sender_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.sender.slice()) catch continue;
            defer a.allocator.free(sender_utf8);
            const time_utf8 = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.time.slice()) catch continue;
            defer a.allocator.free(time_utf8);
            const kind = if (isImage(message)) "Image" else "Video";
            const label = std.fmt.allocPrint(a.allocator, "{s} - {s} {s}", .{ kind, sender_utf8, time_utf8 }) catch continue;
            defer a.allocator.free(label);
            item.label.set(a.allocator, label);
            item.shortcut.set(a.allocator, "");
            item.command = 0;
            item.url = .{};
            item.chat_jid = .{};
            item.chat_identity = .{};
            item.view_identity = .{};
            item.message_id.set(message.id.slice());
            a.palette_item_count += 1;
        }
    }
}

fn whatsappStorePresent(a: *App) bool {
    var db_buf: [280]u8 = undefined;
    const db = std.fmt.bufPrint(&db_buf, "{s}\\wacli.db", .{a.wacli_dir.slice()}) catch return false;
    const db_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, db) catch return false;
    defer a.allocator.free(db_wide);
    return win.GetFileAttributesW(db_wide.ptr) != win.INVALID_FILE_ATTRIBUTES;
}

fn buildSortViewsItems(a: *App) void {
    a.palette_item_count = 0;
    for (a.views.items, 0..) |*view, index| {
        var shortcut: [16]u8 = undefined;
        const before = a.palette_item_count;
        appendPalette(a, view.labelText(), if (index < 9) std.fmt.bufPrint(&shortcut, "Alt+{d}", .{index + 1}) catch "" else "", 0);
        if (a.palette_item_count > before) a.palette_items[before].view_identity = view.key;
    }
}

fn openSortViews(a: *App) void {
    a.palette_links_mode = false;
    a.palette_accounts_mode = false;
    a.palette_views_mode = true;
    buildSortViewsItems(a);
    showPaletteWindow(a);
}

fn moveView(a: *App, down: bool) void {
    if (a.palette_selected >= a.palette_match_count) return;
    const wanted = a.palette_items[a.palette_matches[a.palette_selected]].view_identity;
    for (a.views.items, 0..) |*view, index| {
        if (!chat_key.Key.eql(wanted.key(), view.key.key())) continue;
        if ((down and index + 1 == a.views.items.len) or (!down and index == 0)) return;
        const target = if (down) index + 1 else index - 1;
        std.mem.swap(messenger_view.Account, &a.views.items[index], &a.views.items[target]);
        if (!saveViewOrder(a)) {
            std.mem.swap(messenger_view.Account, &a.views.items[index], &a.views.items[target]);
            setStatus(a, "Could not save view order");
            return;
        }
        buildSortViewsItems(a);
        paletteFilter(a);
        for (a.palette_matches[0..a.palette_match_count], 0..) |match, selected| {
            if (chat_key.Key.eql(wanted.key(), a.palette_items[match].view_identity.key())) {
                a.palette_selected = selected;
                if (a.palette_list) |list| _ = win.SendMessageW(list, win.LB_SETCURSEL, selected, 0);
                break;
            }
        }
        return;
    }
}

fn openAccountsPalette(a: *App) void {
    if (a.palette != null) {
        closePalette(a);
        return;
    }
    a.palette_links_mode = false;
    a.palette_accounts_mode = true;
    a.palette_views_mode = false;
    buildAccountsItems(a);
    showPaletteWindow(a);
}

fn buildAccountsItems(a: *App) void {
    a.palette_item_count = 0;
    var line_buf: [128]u8 = undefined;
    if (a.sync_logged_out) {
        appendPalette(a, "WhatsApp - logged out; scan the QR again to relink", "", 0);
    } else {
        appendPalette(a, accounts.whatsappLabel(&line_buf, a.sync_child != null, a.last_refresh_unix), "", 0);
    }
    const store_present = whatsappStorePresent(a);
    if (!store_present) {
        appendPalette(a, "Add WhatsApp account (opens the pairing window)", "", command_accounts_add);
    } else {
        appendPalette(a, "Reconnect WhatsApp", "", command_accounts_reconnect);
        if (a.accounts_confirm_remove) {
            appendPalette(a, "Confirm: remove the WhatsApp account from this PC", "", command_accounts_remove_confirm);
        } else {
            appendPalette(a, "Remove WhatsApp account...", "", command_accounts_remove);
        }
    }
    if (hubConfigured(a)) return;
    appendPalette(a, accounts.telegramLabel(a.tg_auth), "", 0);
    if (a.tg_auth == .ready) {
        appendPalette(a, "Log out of Telegram", "", command_telegram_logout);
    } else {
        appendPalette(a, "Connect Telegram account", "", command_telegram_login);
    }
    if (a.telegram != null or a.tg_auth == .ready) {
        if (a.accounts_confirm_remove_tg) {
            appendPalette(a, "Confirm: remove the Telegram account from this PC", "", command_accounts_tg_remove_confirm);
        } else {
            appendPalette(a, "Remove Telegram account...", "", command_accounts_tg_remove);
        }
    }
}

fn removeWhatsAppAccount(a: *App) void {
    if (hubConfigured(a)) return setStatus(a, "Manage WhatsApp accounts on the hub");
    if (mediaBusy(a) or a.send_child != null or a.pending_send_count > 0 or
        a.read_child != null or a.pending_read_count > 0 or
        a.archive_child != null or a.pending_archive_count > 0 or avatarBusy(a) or
        wacliPendingGet(a, .chats) > 0 or wacliPendingGet(a, .groups) > 0 or
        wacliPendingGet(a, .messages) > 0 or wacliPendingGet(a, .reaction) > 0 or
        wacliPendingGet(a, .contacts_index) > 0 or wacliPendingGet(a, .archived_scan) > 0)
    {
        setStatus(a, "Wait for pending tasks to finish, then remove again");
        return;
    }
    if (a.wacli_dir.len == 0) {
        setStatus(a, "Could not locate the WhatsApp data folder");
        return;
    }
    stopSync(a, "remove account");
    const dir_wide = utf8ToWide(a.allocator, a.wacli_dir.slice()) catch {
        setStatus(a, "Could not locate the WhatsApp data folder");
        return;
    };
    defer a.allocator.free(dir_wide);
    var target_buf: [300]u8 = undefined;
    const target = std.fmt.bufPrint(&target_buf, "{s}.old-{d}", .{ a.wacli_dir.slice(), nowUnixSeconds() }) catch {
        setStatus(a, "Could not locate the WhatsApp data folder");
        return;
    };
    const target_wide = utf8ToWide(a.allocator, target) catch {
        setStatus(a, "Could not locate the WhatsApp data folder");
        return;
    };
    defer a.allocator.free(target_wide);
    const moved = win.MoveFileExW(dir_wide.ptr, target_wide.ptr, win.MOVEFILE_WRITE_THROUGH) != 0;
    if (!moved) {
        setStatus(a, "WhatsApp is still closing - try Remove again in a few seconds");
        return;
    }
    a.accounts_maintenance = true;
    deleteAccountCaches(a);
    for (a.msg_cache[0..a.msg_cache_len]) |*entry| {
        if (entry.data) |data| a.allocator.free(data);
        entry.data = null;
    }
    a.msg_cache_len = 0;
    a.people.deinit();
    a.people_open_jid.set("");
    if (a.chats_raw) |raw| a.allocator.free(raw);
    a.chats_raw = null;
    a.cache_tag.set("");
    a.cache_tag_gen += 1;
    if (a.selected_chat < a.chat_count) selectedViewKey(a).set(chat_key.of(&a.chats[a.selected_chat]));
    a.chat_view_switched = true;
    a.chat_count = 0;
    a.selected_chat = 0;
    switchComposerDraft(a);
    a.selected_message = null;
    a.scroll_y = 0;
    a.max_scroll = 0;
    a.message_count = 0;
    a.last_refresh_unix = 0;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    refreshVisibleChats(a);
    refreshMessages(a);
    setStatus(a, "WhatsApp signed out - its data was kept as a backup folder; pair again with Add account");
}

fn addWhatsAppAccount(a: *App) void {
    if (hubConfigured(a)) return setStatus(a, "Manage WhatsApp linking on the hub");
    if (a.pairing_process != null) {
        setStatus(a, "Pairing window is already open - scan the QR code there");
        return;
    }
    stopSync(a, "pairing");
    a.sync_fail_count = 0;
    const exe_wide = utf8ToWide(a.allocator, a.wacli_path) catch {
        setStatus(a, "Could not open the pairing window");
        return;
    };
    defer a.allocator.free(exe_wide);
    const command_utf8 = std.fmt.allocPrint(a.allocator, "\"{s}\" auth --idle-exit 10m", .{a.wacli_path}) catch {
        setStatus(a, "Could not open the pairing window");
        return;
    };
    defer a.allocator.free(command_utf8);
    const command_wide = utf8ToWide(a.allocator, command_utf8) catch {
        setStatus(a, "Could not open the pairing window");
        return;
    };
    defer a.allocator.free(command_wide);
    var startup: win.STARTUPINFOW = std.mem.zeroes(win.STARTUPINFOW);
    startup.cb = @sizeOf(win.STARTUPINFOW);
    var process: win.PROCESS_INFORMATION = std.mem.zeroes(win.PROCESS_INFORMATION);
    const create_new_console: win.DWORD = 0x00000010;
    if (win.CreateProcessW(exe_wide.ptr, command_wide.ptr, null, null, win.FALSE, create_new_console, null, null, &startup, &process) != 0) {
        _ = win.CloseHandle(process.hThread);
        a.pairing_process = process.hProcess;
        appendLaunchLog(a, "accounts: pairing window opened");
        setStatus(a, "Pairing window opened - scan the QR code, then close that window to start live sync");
    } else {
        setStatus(a, "Could not open the pairing window");
    }
}

fn showPaletteWindow(a: *App) void {
    const owner = a.hwnd orelse return;
    var owner_rect: win.RECT = undefined;
    _ = win.GetWindowRect(owner, &owner_rect);
    const x = @max(owner_rect.left + 8, owner_rect.left + @divTrunc((owner_rect.right - owner_rect.left) - palette_width, 2));
    const y = owner_rect.top + 110;
    const palette = win.CreateWindowExW(
        win.WS_EX_TOOLWINDOW,
        lit("MessagesPalette"),
        null,
        win.WS_POPUP,
        x,
        y,
        palette_width,
        palette_edit_zone + palette_max_rows * palette_row_height + 12,
        owner,
        null,
        a.instance,
        null,
    ) orelse return;
    a.palette = palette;
    a.palette_ever_active = false;
    var corner: win.DWORD = 2;
    _ = win.DwmSetWindowAttribute(palette, 33, &corner, @sizeOf(win.DWORD));
    var margins = win.MARGINS{ .cxLeftWidth = 0, .cxRightWidth = 0, .cyTopHeight = 0, .cyBottomHeight = 1 };
    _ = win.DwmExtendFrameIntoClientArea(palette, &margins);
    a.palette_edit = directwrite_edit.create(a.instance, palette, controlId(id_palette_edit), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.ES_AUTOHSCROLL, 16, 13, palette_width - 32, 36);
    if (a.palette_edit == null) {
        _ = win.DestroyWindow(palette);
        return;
    }
    a.palette_list = win.CreateWindowExW(0, lit("LISTBOX"), null, win.WS_CHILD | win.WS_VISIBLE | win.LBS_NOTIFY | win.LBS_OWNERDRAWFIXED | win.LBS_HASSTRINGS | win.LBS_NOINTEGRALHEIGHT, 1, palette_edit_zone, palette_width - 2 - scrollbar_width, palette_max_rows * palette_row_height + 12, palette, controlId(id_palette_list), a.instance, null);
    setFont(a.palette_edit, a.font);
    setFont(a.palette_list, a.font);
    setPaletteCue(a);
    if (a.palette_list) |list| _ = win.SendMessageW(list, win.LB_SETITEMHEIGHT, 0, palette_row_height);
    paletteFilter(a);
    _ = win.ShowWindow(palette, win.SW_SHOW);
    if (a.palette_edit) |edit| _ = win.SetFocus(edit);
}

fn drawPaletteItem(a: *App, item: *win.DRAWITEMSTRUCT) void {
    if (item.itemID == @as(win.UINT, @bitCast(@as(c_int, -1)))) return;
    const index: usize = @intCast(item.itemID);
    if (index >= a.palette_match_count) return;
    const palette_item = &a.palette_items[a.palette_matches[index]];
    const selected = (item.itemState & win.ODS_SELECTED) != 0;
    const background = win.CreateSolidBrush(if (selected) theme.current.secondary_container else theme.current.surface_container_low) orelse return;
    defer _ = win.DeleteObject(background);
    _ = win.FillRect(item.hDC, &item.rcItem, background);
    _ = win.SetBkMode(item.hDC, win.TRANSPARENT);
    if (selected) {
        const accent_brush = win.CreateSolidBrush(theme.current.primary) orelse return;
        defer _ = win.DeleteObject(accent_brush);
        var bar = win.RECT{ .left = item.rcItem.left, .top = item.rcItem.top, .right = item.rcItem.left + 3, .bottom = item.rcItem.bottom };
        _ = win.FillRect(item.hDC, &bar, accent_brush);
    }
    _ = win.SelectObject(item.hDC, @ptrCast(a.font.?));
    _ = win.SetTextColor(item.hDC, if (selected and theme.choice == .amoled) theme.current.on_secondary_container else theme.current.on_surface);
    const label_right = if (palette_item.shortcut.len > 0) item.rcItem.right - 130 else item.rcItem.right - 20;
    var label_rect = win.RECT{ .left = item.rcItem.left + 20, .top = item.rcItem.top, .right = label_right, .bottom = item.rcItem.bottom };
    _ = text_draw.drawText(item.hDC, palette_item.label.ptr(), @intCast(palette_item.label.len), &label_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS | win.DT_VCENTER);
    if (palette_item.shortcut.len > 0) {
        _ = win.SelectObject(item.hDC, @ptrCast(a.font_small.?));
        _ = win.SetTextColor(item.hDC, if (selected and theme.choice == .amoled) theme.current.on_secondary_container else theme.current.on_surface_variant);
        var shortcut_rect = win.RECT{ .left = item.rcItem.right - 120, .top = item.rcItem.top, .right = item.rcItem.right - 16, .bottom = item.rcItem.bottom };
        _ = text_draw.drawText(item.hDC, palette_item.shortcut.ptr(), @intCast(palette_item.shortcut.len), &shortcut_rect, win.DT_RIGHT | win.DT_SINGLELINE | win.DT_VCENTER);
    }
}

fn paletteProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_COMMAND => {
            const id = loword(wparam);
            const notification = hiword(wparam);
            if (id == id_palette_edit and (notification == win.EN_SETFOCUS or notification == win.EN_KILLFOCUS)) {
                _ = win.InvalidateRect(hwnd, null, win.FALSE);
                return 0;
            }
            if (id == id_palette_edit and notification == win.EN_CHANGE) {
                paletteFilter(a);
            } else if (id == id_palette_list and notification == win.LBN_SELCHANGE) {
                const selected = win.SendMessageW(a.palette_list.?, win.LB_GETCURSEL, 0, 0);
                if (selected >= 0) {
                    a.palette_selected = @intCast(selected);
                    if (a.palette_list) |list| _ = win.InvalidateRect(list, null, win.FALSE);
                }
            } else if (id == id_palette_list and notification == win.LBN_DBLCLK) {
                paletteActivate(a);
            }
            return 0;
        },
        win.WM_DRAWITEM => {
            const item: *win.DRAWITEMSTRUCT = winHandle(*win.DRAWITEMSTRUCT, @as(usize, @bitCast(lparam)));
            if (item.CtlID == id_palette_list) drawPaletteItem(a, item);
            return 1;
        },
        win.WM_CTLCOLORSTATIC, win.WM_CTLCOLOREDIT, win.WM_CTLCOLORLISTBOX => {
            const hdc: win.HDC = winHandle(win.HDC, wparam);
            _ = win.SetTextColor(hdc, theme.current.on_surface);
            if (message == win.WM_CTLCOLOREDIT and theme.choice == .amoled) {
                _ = win.SetBkColor(hdc, theme.current.surface_container_high);
                return @bitCast(@intFromPtr(a.brush_raised.?));
            }
            _ = win.SetBkColor(hdc, theme.current.surface_container_low);
            if (a.brush_panel) |brush| return @bitCast(@intFromPtr(brush));
            return @bitCast(@intFromPtr(win.GetStockObject(win.BLACK_BRUSH)));
        },
        win.WM_PAINT => {
            var paint: win.PAINTSTRUCT = undefined;
            const hdc = win.BeginPaint(hwnd, &paint);
            defer _ = win.EndPaint(hwnd, &paint);
            var client: win.RECT = undefined;
            _ = win.GetClientRect(hwnd, &client);
            _ = win.FillRect(hdc, &client, a.brush_panel.?);
            var separator = win.RECT{ .left = 0, .top = palette_edit_zone - 2, .right = client.right, .bottom = palette_edit_zone - 1 };
            _ = win.FillRect(hdc, &separator, a.brush_raised.?);
            if (a.palette_match_count == 0) {
                _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
                _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                const empty_text: [*:0]const u16 = if (a.tg_login != .none)
                    lit("Type in the box above and press Enter")
                else
                    lit("No matching commands");
                var empty_rect = win.RECT{ .left = 20, .top = palette_edit_zone + 4, .right = client.right - 20, .bottom = palette_edit_zone + 36 };
                _ = text_draw.drawText(hdc, empty_text, -1, &empty_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER);
            }
            var shapes = smooth.Context.init(hdc);
            defer shapes.deinit();
            paintPopupInput(&shapes, hwnd, a.palette_edit);
            if (theme.choice == .amoled) _ = win.FrameRect(hdc, &client, a.brush_muted.?);
            if (a.palette_list) |list| drawScrollbar(&shapes, stripRightOf(list, hwnd), listboxScrollInfo(list), theme.current.outline);
            return 0;
        },
        win.WM_LBUTTONDOWN => {
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            if (a.palette_list) |list| {
                const strip = stripRightOf(list, hwnd);
                if (hitStrip(strip, x, y)) {
                    const info = listboxScrollInfo(list);
                    if (scrollbar.thumbGeom(trackOf(strip).top, trackOf(strip).h, info.total, info.page, info.top, scrollbar_min_thumb) != null)
                        beginStripDrag(a, hwnd, strip, info, y, .palette, setPaletteScroll);
                    return 0;
                }
            }
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_MOUSEMOVE => {
            if (a.sb_drag == .palette) {
                const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
                if (a.palette_list) |list| dragStrip(a, stripRightOf(list, hwnd), listboxScrollInfo(list), y, setPaletteScroll);
                return 0;
            }
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_LBUTTONUP => {
            if (a.sb_drag == .palette) {
                _ = win.ReleaseCapture();
                a.sb_drag = .none;
                return 0;
            }
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_CAPTURECHANGED => {
            a.sb_drag = .none;
            return 0;
        },
        win.WM_ACTIVATE => {
            if (loword(wparam) == win.WA_INACTIVE) {
                if (a.palette_ever_active) _ = win.DestroyWindow(hwnd);
            } else a.palette_ever_active = true;
            return 0;
        },
        win.WM_DESTROY => {
            a.palette = null;
            a.palette_views_mode = false;
            a.palette_edit = null;
            a.palette_list = null;
            a.tg_login = .none;
            if (a.sb_drag == .palette) a.sb_drag = .none;
            return 0;
        },
        else => return win.DefWindowProcW(hwnd, message, wparam, lparam),
    }
}

const shortcut_padding: i32 = 22;
const shortcut_title_height: i32 = 40;
const shortcut_heading_height: i32 = 30;
const shortcut_row_height: i32 = 26;
const shortcut_group_gap: i32 = 16;
const shortcut_col_width: i32 = 460;
const shortcut_key_col_width: i32 = 210;

fn shortcutGroupHeight(a: *const App, group: shortcuts.Group) i32 {
    const rows: i32 = @intCast(group.items.len);
    return px(a, shortcut_heading_height) + rows * px(a, shortcut_row_height) + px(a, shortcut_group_gap);
}

const ShortcutLayout = struct {
    two_columns: bool,
    column_of: [shortcuts.groups.len]u1,
    width: i32,
    height: i32,
};

fn computeShortcutLayout(a: *const App, available_height: i32) ShortcutLayout {
    var total: i32 = 0;
    for (shortcuts.groups) |group| total += shortcutGroupHeight(a, group);
    const single_height = px(a, shortcut_title_height) + total + px(a, shortcut_padding);
    var sh_layout = ShortcutLayout{
        .two_columns = false,
        .column_of = [_]u1{0} ** shortcuts.groups.len,
        .width = px(a, shortcut_padding) * 2 + px(a, shortcut_col_width),
        .height = single_height,
    };
    if (single_height <= available_height) return sh_layout;
    sh_layout.two_columns = true;
    var col_a_height: i32 = 0;
    var col_b_height: i32 = 0;
    for (shortcuts.groups, 0..) |group, index| {
        const height = shortcutGroupHeight(a, group);
        if (col_a_height <= col_b_height) {
            sh_layout.column_of[index] = 0;
            col_a_height += height;
        } else {
            sh_layout.column_of[index] = 1;
            col_b_height += height;
        }
    }
    sh_layout.width = px(a, shortcut_padding) * 3 + px(a, shortcut_col_width) * 2;
    sh_layout.height = px(a, shortcut_title_height) + @max(col_a_height, col_b_height) + px(a, shortcut_padding);
    return sh_layout;
}

fn drawAscii(hdc: win.HDC, rect: *win.RECT, text: []const u8, flags: c_uint) void {
    var buffer: [256]u16 = undefined;
    const len = @min(text.len, buffer.len - 1);
    for (text[0..len], 0..) |byte, index| buffer[index] = byte;
    buffer[len] = 0;
    _ = text_draw.drawText(hdc, &buffer, @intCast(len), rect, flags);
}

fn drawShortcutHelp(a: *App, hwnd: win.HWND) void {
    var paint: win.PAINTSTRUCT = undefined;
    const hdc = win.BeginPaint(hwnd, &paint);
    defer _ = win.EndPaint(hwnd, &paint);
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    _ = win.FillRect(hdc, &client, a.brush_panel orelse return);
    if (theme.choice == .amoled) _ = win.FrameRect(hdc, &client, a.brush_muted.?);
    _ = win.SetBkMode(hdc, win.TRANSPARENT);

    _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
    _ = win.SetTextColor(hdc, theme.current.on_surface);
    var title_rect = win.RECT{ .left = px(a, shortcut_padding), .top = px(a, 10), .right = client.right - px(a, shortcut_padding), .bottom = px(a, shortcut_title_height) };
    drawAscii(hdc, &title_rect, "Keyboard shortcuts", win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER);

    const available_height = client.bottom - client.top - px(a, shortcut_padding);
    const sh_layout = computeShortcutLayout(a, available_height);
    const col_width = px(a, shortcut_col_width);
    const key_width = px(a, shortcut_key_col_width);
    var col_x = [2]i32{ px(a, shortcut_padding), px(a, shortcut_padding) };
    if (sh_layout.two_columns) col_x[1] = px(a, shortcut_padding) * 2 + col_width;
    var col_y = [2]i32{ px(a, shortcut_title_height), px(a, shortcut_title_height) };

    for (shortcuts.groups, 0..) |group, index| {
        const col: usize = if (sh_layout.two_columns) sh_layout.column_of[index] else 0;
        const x = col_x[col];
        var y = col_y[col];

        _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
        _ = win.SetTextColor(hdc, theme.current.primary);
        var heading_rect = win.RECT{ .left = x, .top = y, .right = x + col_width, .bottom = y + px(a, shortcut_heading_height) };
        drawAscii(hdc, &heading_rect, group.name, win.DT_LEFT | win.DT_SINGLELINE | win.DT_VCENTER);
        y += px(a, shortcut_heading_height);

        for (group.items) |item| {
            _ = win.SelectObject(hdc, @ptrCast(a.font.?));
            _ = win.SetTextColor(hdc, theme.current.on_surface);
            var key_rect = win.RECT{ .left = x, .top = y, .right = x + key_width, .bottom = y + px(a, shortcut_row_height) };
            drawAscii(hdc, &key_rect, item.key, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS | win.DT_VCENTER);

            _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
            var desc_rect = win.RECT{ .left = x + key_width, .top = y, .right = x + col_width, .bottom = y + px(a, shortcut_row_height) };
            drawAscii(hdc, &desc_rect, item.desc, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS | win.DT_VCENTER);
            y += px(a, shortcut_row_height);
        }
        y += px(a, shortcut_group_gap);
        col_y[col] = y;
    }
}

fn openShortcutHelp(a: *App) void {
    if (a.shortcut_help != null) return;
    const owner = a.hwnd orelse return;
    const monitor = win.MonitorFromWindow(owner, win.MONITOR_DEFAULTTONEAREST);
    var info = std.mem.zeroes(win.MONITORINFO);
    info.cbSize = @sizeOf(win.MONITORINFO);
    if (win.GetMonitorInfoW(monitor, &info) == 0) return;
    const work = info.rcWork;
    const margin = px(a, 40);
    const available_height = @max(px(a, 200), (work.bottom - work.top) - margin);
    const sh_layout = computeShortcutLayout(a, available_height);
    const width = @min(sh_layout.width, work.right - work.left - margin);
    const height = @min(sh_layout.height, work.bottom - work.top - margin);
    const x = work.left + @divTrunc((work.right - work.left) - width, 2);
    const y = work.top + @divTrunc((work.bottom - work.top) - height, 2);
    const hwnd = win.CreateWindowExW(
        win.WS_EX_TOOLWINDOW,
        lit("MessagesShortcutHelp"),
        null,
        win.WS_POPUP,
        x,
        y,
        width,
        height,
        owner,
        null,
        a.instance,
        null,
    ) orelse return;
    a.shortcut_help = hwnd;
    var corner: win.DWORD = 2;
    _ = win.DwmSetWindowAttribute(hwnd, 33, &corner, @sizeOf(win.DWORD));
    _ = win.ShowWindow(hwnd, win.SW_SHOW);
    _ = win.SetForegroundWindow(hwnd);
    _ = win.SetFocus(hwnd);
}

fn closeShortcutHelp(a: *App) void {
    if (a.shortcut_help) |hwnd| _ = win.DestroyWindow(hwnd);
}

fn shortcutHelpProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_ERASEBKGND => return 1,
        win.WM_PAINT => {
            drawShortcutHelp(a, hwnd);
            return 0;
        },
        win.WM_KEYDOWN => {
            if (wparam == win.VK_ESCAPE or wparam == win.VK_F1) closeShortcutHelp(a);
            return 0;
        },
        win.WM_LBUTTONDOWN => {
            closeShortcutHelp(a);
            return 0;
        },
        win.WM_CLOSE => {
            closeShortcutHelp(a);
            return 0;
        },
        win.WM_DESTROY => {
            if (a.shortcut_help != null and a.shortcut_help.? == hwnd) a.shortcut_help = null;
            return 0;
        },
        else => {},
    }
    return win.DefWindowProcW(hwnd, message, wparam, lparam);
}

fn runCommand(a: *App, command: u16) void {
    switch (command) {
        command_slack_threads => toggleSlackThreads(a),
        command_search => {
            if (a.search) |search| _ = win.SetFocus(search);
        },
        command_compose => {
            a.user_viewed = true;
            if (a.compose) |compose| _ = win.SetFocus(compose);
        },
        command_emoji => openEmojiPicker(a),
        command_shortcuts_help => openShortcutHelp(a),
        command_emoji_diag => setStatus(a, emoji_draw.failureNotice() orelse "Colour emoji is working"),
        command_unread => {
            _ = clearBulkSelection(a);
            a.unread_only = !a.unread_only;
            refilterChats(a);
            refreshMessages(a);
        },
        command_archive => archiveSelectedChat(a, false, .menu),
        command_pin => togglePinSelected(a),
        command_reply => startReply(a),
        command_resend => {
            const selected = a.selected_message orelse {
                setStatus(a, "Select a failed message first");
                return;
            };
            if (selected >= a.message_count or a.messages[selected].send_state != .failed) {
                setStatus(a, "Select a failed message first");
                return;
            }
            if (!resendFailedMessage(a, selected)) setStatus(a, "Only a failed WhatsApp message can be resent");
        },
        command_sort_views => openSortViews(a),
        command_show_all => switchChatView(a, .all),
        command_show_whatsapp => switchChatView(a, .whatsapp),
        command_show_slack => switchChatView(a, .slack),
        command_show_telegram => switchChatView(a, .telegram),
        command_include_archived => toggleViewArchived(a),
        command_archived => {
            _ = clearBulkSelection(a);
            a.show_archived = !a.show_archived;
            if (!unifiedHub(a) and messenger_view.includes(activeChatView(a), .slack)) _ = applyChats(a, "{\"data\":[]}", false);
            refreshChats(a);
            refreshMessages(a);
        },
        command_dictate => toggleDictation(a),
        command_dictation_auto, command_dictation_english, command_dictation_german => {
            a.dictation_language = switch (command) {
                command_dictation_english => .english,
                command_dictation_german => .german,
                else => .automatic,
            };
            saveDictationLanguage(a.dictation_language);
            setStatus(a, switch (a.dictation_language) {
                .automatic => "Dictation language: Automatic",
                .english => "Dictation language: English",
                .german => "Dictation language: German",
            });
        },
        command_mic_default...command_mic_default + mic_choice.max_devices => {
            const slot = command - command_mic_default;
            if (slot == 0) {
                mic_choice.choose("");
                setStatus(a, "Microphone: System default");
            } else if (slot - 1 < a.mic_count) {
                mic_choice.choose(a.mic_names[slot - 1].slice());
                setStatus(a, "Microphone changed");
            }
        },
        command_theme_green, command_theme_amoled => {
            _ = changeTheme(a, if (command == command_theme_amoled) .amoled else .green);
        },
        command_font_smaller => changeFontScale(a, -10),
        command_speed_1, command_speed_150, command_speed_200 => {
            const player = ensureAudioPlayer(a) orelse return;
            player.setSpeed(switch (command) {
                command_speed_150 => 150,
                command_speed_200 => 200,
                else => 100,
            });
            setStatus(a, switch (command) {
                command_speed_150 => "Playback speed 1.5x",
                command_speed_200 => "Playback speed 2x",
                else => "Playback speed 1x",
            });
            if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
        },
        command_font_larger => changeFontScale(a, 10),
        command_font_reset => {
            a.font_scale = 82;
            text_draw.reset();
            recreateFonts(a);
            saveFontScale(a.font_scale);
            setStatus(a, "Font size 82%");
        },
        command_refresh => {
            refreshGroups(a);
            refreshChats(a);
            refreshMessages(a);
        },
        command_sync => {
            stopSync(a, "restart command");
            a.sync_fail_count = 0;
            a.sync_logged_out = false;
            startSync(a);
        },
        command_update_check => {
            if (a.update_installed) {
                setStatus(a, "Update installed - restarting soon");
                return;
            }
            setStatus(a, "Checking for updates...");
            if (a.hwnd) |hwnd| startUpdateCheck(hwnd, true);
        },
        command_update_install => {
            updateCardClick(a);
        },
        command_telegram_login => {
            startTelegramAdd(a);
        },
        command_telegram_logout => {
            if (a.telegram) |client| client.logOut();
            setStatus(a, "Logging out of Telegram...");
        },
        command_slack_connect => {
            if (slack_win.loadClientId(a.allocator)) |client| {
                defer a.allocator.free(client);
                if (slack_win.loadSecret(a.allocator, lit("SlackAppToken"))) |stored| {
                    defer a.allocator.free(stored.value);
                    if (slack_win.validClientId(client) and slack_win.isAppToken(stored.value)) {
                        startSlackSignIn(a, client);
                        return;
                    }
                }
            }
            openSlackSetup(a);
        },
        command_slack_setup => {
            if (a.slack_oauth_thread != null) return setStatus(a, "Slack sign-in is already in progress");
            openSlackSetup(a);
        },
        command_slack_disconnect_workspace...command_slack_disconnect_workspace + max_slack_installations - 1 => {
            const installation = &a.slack_installations[command - command_slack_disconnect_workspace];
            if (!installation.active) return;
            const account = installation.team_id;
            if (removeSlackInstallation(account.slice())) setStatus(a, "Slack workspace disconnected") else setStatus(a, "Could not disconnect Slack workspace");
        },
        command_accounts_tg_remove => {
            a.accounts_confirm_remove_tg = true;
            openAccountsPalette(a);
        },
        command_accounts_tg_remove_confirm => {
            a.accounts_confirm_remove_tg = false;
            removeTelegramAccount(a);
        },
        command_slack_disconnect => {
            if (!selectedChatIsSlack(a)) return setStatus(a, "Select a Slack workspace chat to disconnect");
            const account = a.chats[a.selected_chat].account;
            if (removeSlackInstallation(account.slice())) setStatus(a, "Slack workspace disconnected") else setStatus(a, "Could not disconnect Slack workspace");
        },
        command_slack_attach => {
            if (attachUnavailableReason(a)) |reason| {
                setStatus(a, reason);
                return;
            }
            if (pickImageFile(a)) |path| _ = stageAttachmentFile(a, path.ptr());
        },
        command_open_video_external => {
            const selected = a.selected_message orelse {
                setStatus(a, "Select a video first");
                return;
            };
            if (selected >= a.message_count) return;
            const message = &a.messages[selected];
            if (!std.ascii.eqlIgnoreCase(message.media_type.slice(), "video")) {
                setStatus(a, "Select a video first");
                return;
            }
            if (message.local_path.len == 0) {
                setStatus(a, "The video is still downloading");
                return;
            }
            openMedia(a, message);
        },
        command_open_image_external => {
            const selected = a.selected_message orelse {
                setStatus(a, "Select an image first");
                return;
            };
            if (selected >= a.message_count) return;
            const message = &a.messages[selected];
            if (!isImage(message)) {
                setStatus(a, "Select an image first");
                return;
            }
            if (message.local_path.len == 0) {
                setStatus(a, "The image is still downloading");
                return;
            }
            openMedia(a, message);
        },
        command_quit => {
            if (a.hwnd) |hwnd| _ = win.PostMessageW(hwnd, win.WM_CLOSE, 0, 0);
        },
        command_react_menu => openReactionPicker(a),
        command_copy_text => copySelectedText(a),
        command_copy_link => copySelectedLink(a),
        command_play_audio => playSelectedAudio(a),
        command_toggle_transcript => toggleSelectedTranscript(a),
        command_next_message => selectMessage(a, 1),
        command_prev_message => selectMessage(a, -1),
        command_jump_latest => {
            jumpToLatestMessage(a);
            setStatus(a, "Jumped to latest message");
        },
        command_links => openLinkPalette(a),
        command_accounts => openAccountsPalette(a),
        command_accounts_reconnect => {
            stopSync(a, "reconnect");
            if (a.sync_logged_out or a.pairing_process != null) {
                addWhatsAppAccount(a);
            } else {
                a.sync_fail_count = 0;
                startSync(a);
            }
        },
        command_accounts_add => addWhatsAppAccount(a),
        command_accounts_remove => {
            a.accounts_confirm_remove = true;
            openAccountsPalette(a);
        },
        command_accounts_remove_confirm => {
            a.accounts_confirm_remove = false;
            removeWhatsAppAccount(a);
        },
        command_next_chat => {
            selectChat(a, 1, true);
            focusCompose(a);
        },
        command_prev_chat => {
            selectChat(a, -1, true);
            focusCompose(a);
        },
        command_send => sendMessage(a),
        else => reactToSelected(a, command),
    }
}

fn composerContentHeight(a: *App) i32 {
    const compose = a.compose orelse return compose_layout.edit_min_height;
    return directwrite_edit.contentHeight(compose, compose_layout.edit_min_height);
}

fn stagedPreviewColumns(a: *const App, width: i32) usize {
    const left_width = std.math.clamp(@divTrunc(width, 3), px(a, 280), px(a, 390));
    const available = width - left_width - threadPanelWidth(a, width, left_width) - px(a, 26);
    return @intCast(@max(1, @divTrunc(available, px(a, 56))));
}

fn stagedComposerSizes(a: *App, width: i32, height: i32) compose_layout.Composer {
    const columns = stagedPreviewColumns(a, width);
    const extra = @as(i32, @intCast((a.staged_images.count -| 1) / columns)) * px(a, compose_layout.preview_band);
    var sizes = compose_layout.computeScaled(a.compose_dragged, composerContentHeight(a), height - extra, a.staged_images.count > 0, @intCast(a.dpi));
    sizes.strip_height += extra;
    return sizes;
}

fn stagedPreviewRect(a: *const App, index: usize) win.RECT {
    const columns = stagedPreviewColumns(a, a.compose_client_width);
    const left_width = std.math.clamp(@divTrunc(a.compose_client_width, 3), px(a, 280), px(a, 390));
    const left = left_width + px(a, 13) + @as(i32, @intCast(index % columns)) * px(a, 56);
    const top = a.compose_strip_top + px(a, 10) + @as(i32, @intCast(index / columns)) * px(a, compose_layout.preview_band);
    return .{ .left = left, .top = top, .right = left + px(a, 44) + 2, .bottom = top + px(a, 44) + 2 };
}

fn stagedRemoveRect(a: *const App, index: usize) win.RECT {
    const preview = stagedPreviewRect(a, index);
    return .{ .left = preview.right - px(a, 14), .top = preview.top, .right = preview.right, .bottom = preview.top + px(a, 14) };
}

fn layoutComposer(a: *App) void {
    const height = a.compose_client_height;
    const sizes = stagedComposerSizes(a, a.compose_client_width, height);
    if (a.compose_strip_top == height - sizes.strip_height and a.compose_pill.top == height - px(a, 11) - sizes.edit_height) return;
    const left_width = std.math.clamp(@divTrunc(a.compose_client_width, 3), px(a, 280), px(a, 390));
    var dirty = win.RECT{ .left = left_width + 1, .top = @min(a.compose_strip_top, height - sizes.strip_height), .right = a.compose_client_width, .bottom = height };
    layoutRegion(a, a.compose_client_width, height, &dirty);
}

fn layout(a: *App, width: i32, height: i32) void {
    layoutRegion(a, width, height, null);
}

fn layoutRegion(a: *App, width: i32, height: i32, dirty: ?*const win.RECT) void {
    a.compose_client_width = width;
    a.compose_client_height = height;
    const left_width = std.math.clamp(@divTrunc(width, 3), px(a, 280), px(a, 390));
    const header_height: i32 = 0;
    const search_height: i32 = px(a, 48);
    const status_height: i32 = px(a, 26);
    var sizes = stagedComposerSizes(a, width, height);
    if (a.compose) |hwnd| {
        for (0..2) |pass| {
            if (pass > 0) sizes = stagedComposerSizes(a, width, height);
            a.compose_geometry = compose_layout.arrange(.{ .left = left_width + 1, .top = 0, .right = width - threadPanelWidth(a, width, left_width), .bottom = height }, sizes.edit_height, @intCast(a.dpi), a.voice_active);
            a.compose_pill = @bitCast(a.compose_geometry.box);
            const inner = a.compose_geometry.text;
            _ = win.MoveWindow(hwnd, inner.left, inner.top, inner.right - inner.left, inner.bottom - inner.top, win.TRUE);
            var rect = win.RECT{ .left = px(a, 2), .top = px(a, 8), .right = @max(px(a, 2), inner.right - inner.left - px(a, 2)), .bottom = @max(px(a, 8), inner.bottom - inner.top - px(a, 8)) };
            _ = win.SendMessageW(hwnd, win.EM_SETRECTNP, 0, @bitCast(@intFromPtr(&rect)));
        }
    }
    a.compose_strip_top = height - sizes.strip_height;
    a.search_pill = .{ .left = px(a, 12), .top = header_height + px(a, 8), .right = left_width - px(a, 148), .bottom = header_height + px(a, 8) + px(a, 34) };
    if (a.search) |hwnd| {
        const pill = field_pill.compute(a.search_pill, px(a, theme.radius_field * 2));
        var inner = pill.inner;
        inner.top += 1;
        inner.bottom = @max(inner.top, inner.bottom - 1);
        _ = win.MoveWindow(hwnd, inner.left, inner.top, inner.right - inner.left, inner.bottom - inner.top, win.TRUE);
        _ = win.SendMessageW(hwnd, win.EM_SETMARGINS, win.EC_LEFTMARGIN | win.EC_RIGHTMARGIN, @as(win.LPARAM, px(a, 2)) | (@as(win.LPARAM, px(a, 2)) << 16));
    }
    if (a.include_archived_button) |button| _ = win.MoveWindow(button, left_width - px(a, 140), px(a, 8), px(a, 128), px(a, 34), win.TRUE);
    if (a.chats_hwnd) |hwnd| _ = win.MoveWindow(hwnd, 0, header_height + search_height, left_width - scrollbar_width, height - header_height - search_height - status_height - updateCardSpan(a), win.TRUE);
    if (a.status) |hwnd| _ = win.MoveWindow(hwnd, px(a, 12), height - status_height, left_width - px(a, 24), status_height, win.TRUE);
    if (a.thread_parent.len > 0 and (a.selected_chat >= a.chat_count or !chat_key.Key.eql(a.thread_origin.key(), chat_key.of(&a.chats[a.selected_chat])))) closeSlackThread(a);
    const chat_width = width - left_width - 1;
    const panel_width = if (a.thread_parent.len > 0) @divTrunc(chat_width, 2) else 0;
    if (a.canvas) |hwnd| _ = win.MoveWindow(hwnd, left_width + 1, header_height, chat_width - panel_width, height - header_height - sizes.strip_height, win.TRUE);
    if (a.thread_list) |hwnd| _ = win.MoveWindow(hwnd, width - panel_width + px(a, 8), px(a, 8), @max(1, panel_width - px(a, 16)), @max(1, height - sizes.strip_height - px(a, 16)), win.TRUE);
    if (a.thread_compose) |hwnd| _ = win.MoveWindow(hwnd, width - panel_width + px(a, 8), height - sizes.strip_height + px(a, 8), @max(1, panel_width - px(a, 16)), @max(1, sizes.strip_height - px(a, 16)), win.TRUE);
    const buttons = [_]?win.HWND{ a.attach_btn, a.voice_btn, a.dictate, a.emoji_btn, a.send };
    const rects = [_]compose_layout.Rect{ a.compose_geometry.attach, a.compose_geometry.voice, a.compose_geometry.dictate, a.compose_geometry.emoji, a.compose_geometry.send };
    for (buttons, rects) |button, rect| {
        if (button) |hwnd| _ = win.MoveWindow(hwnd, rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top, win.TRUE);
    }
    updateAttachButton(a);
    if (a.hwnd) |main_hwnd| _ = win.InvalidateRect(main_hwnd, dirty, win.FALSE);
}

fn loadAvatarBitmap(a: *App, path: [*:0]const u16) ?win.HBITMAP {
    if (a.wic_factory == null) return null;
    var decoder: [*c]win.IWICBitmapDecoder = null;
    if (a.wic_factory.*.lpVtbl.*.CreateDecoderFromFilename.?(a.wic_factory, path, null, win.GENERIC_READ, win.WICDecodeMetadataCacheOnLoad, &decoder) < 0 or decoder == null) return null;
    defer _ = decoder.*.lpVtbl.*.Release.?(decoder);
    var frame: [*c]win.IWICBitmapFrameDecode = null;
    if (decoder.*.lpVtbl.*.GetFrame.?(decoder, 0, &frame) < 0 or frame == null) return null;
    defer _ = frame.*.lpVtbl.*.Release.?(frame);
    var converter: [*c]win.IWICFormatConverter = null;
    if (a.wic_factory.*.lpVtbl.*.CreateFormatConverter.?(a.wic_factory, &converter) < 0 or converter == null) return null;
    defer _ = converter.*.lpVtbl.*.Release.?(converter);
    if (converter.*.lpVtbl.*.Initialize.?(converter, @ptrCast(frame), &win.GUID_WICPixelFormat32bppPBGRA, win.WICBitmapDitherTypeNone, null, 0, win.WICBitmapPaletteTypeCustom) < 0) return null;
    var scaler: [*c]win.IWICBitmapScaler = null;
    if (a.wic_factory.*.lpVtbl.*.CreateBitmapScaler.?(a.wic_factory, &scaler) < 0 or scaler == null) return null;
    defer _ = scaler.*.lpVtbl.*.Release.?(scaler);
    if (scaler.*.lpVtbl.*.Initialize.?(scaler, @ptrCast(converter), 42, 42, win.WICBitmapInterpolationModeFant) < 0) return null;
    var pixels: [42 * 42 * 4]u8 = undefined;
    if (scaler.*.lpVtbl.*.CopyPixels.?(@ptrCast(scaler), null, 42 * 4, pixels.len, &pixels) < 0) return null;
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = 42;
    info.bmiHeader.biHeight = -42;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const bitmap = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return null;
    if (bits == null) {
        _ = win.DeleteObject(bitmap);
        return null;
    }
    const destination: [*]u8 = @ptrCast(bits.?);
    @memcpy(destination[0..pixels.len], &pixels);
    return bitmap;
}

fn populateAvatarEntry(a: *App, entry: *AvatarEntry, jid: []const u8) void {
    entry.jid.set(jid);
    var filename_buffer: [40]u8 = undefined;
    const filename = std.fmt.bufPrint(&filename_buffer, "{x:0>16}.img", .{std.hash.Wyhash.hash(0, jid)}) catch return;
    const path = std.fs.path.join(a.allocator, &.{ a.avatar_dir, filename }) catch return;
    defer a.allocator.free(path);
    entry.path.set(a.allocator, path);
    const image_secs = fileStampSecs(entry.path.ptr());
    if (image_secs != null) entry.bitmap = loadAvatarBitmap(a, entry.path.ptr());
    var buffer: [540]u16 = undefined;
    const none_secs = if (avatarMarkerPath(entry, ".none", &buffer)) |marker| fileStampSecs(marker) else null;
    const failed_secs = if (avatarMarkerPath(entry, ".fail", &buffer)) |marker| fileStampSecs(marker) else null;
    const cache = sync_gate.classifyAvatar(image_secs, entry.bitmap != null, none_secs, failed_secs, nowUnixSeconds());
    if (cache.has_image) {
        entry.status = .ready;
        entry.refresh = cache.needs_fetch;
    } else entry.status = if (cache.needs_fetch) .unknown else .unavailable;
}

fn avatarForChat(a: *App, jid: []const u8) ?*AvatarEntry {
    for (a.avatars[0..a.avatar_count]) |*entry| {
        if (std.mem.eql(u8, entry.jid.slice(), jid)) return entry;
    }
    if (a.avatar_count >= max_avatars) return null;
    const entry = &a.avatars[a.avatar_count];
    a.avatar_count += 1;
    populateAvatarEntry(a, entry, jid);
    return entry;
}

fn avatarForParticipant(a: *App, jid: []const u8) ?*AvatarEntry {
    const now = win.GetTickCount64();
    for (a.participant_avatars[0..a.participant_avatar_count], 0..) |*entry, index| {
        if (std.mem.eql(u8, entry.jid.slice(), jid)) {
            a.participant_avatar_touch_ms[index] = now;
            return entry;
        }
    }
    var slot: usize = undefined;
    if (a.participant_avatar_count < max_participant_avatars) {
        slot = a.participant_avatar_count;
        a.participant_avatar_count += 1;
    } else {
        slot = 0;
        for (a.participant_avatar_touch_ms[0..max_participant_avatars], 0..) |touch, index| {
            if (touch < a.participant_avatar_touch_ms[slot]) slot = index;
        }
        if (a.participant_avatars[slot].bitmap) |bitmap| _ = win.DeleteObject(bitmap);
        a.participant_avatars[slot] = .{};
    }
    const entry = &a.participant_avatars[slot];
    a.participant_avatar_touch_ms[slot] = now;
    populateAvatarEntry(a, entry, jid);
    return entry;
}

fn drawAvatarBitmap(hdc: win.HDC, bitmap: win.HBITMAP, left: i32, top: i32, size: i32) void {
    if (size <= 0) return;
    var source: win.BITMAP = undefined;
    if (win.GetObjectW(bitmap, @sizeOf(win.BITMAP), &source) == 0 or source.bmBits == null) return;
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = size;
    info.bmiHeader.biHeight = -size;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    info.bmiHeader.biCompression = win.BI_RGB;
    var bits: ?*anyopaque = null;
    const circle = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return;
    defer _ = win.DeleteObject(circle);
    if (bits == null) return;
    const target_size: usize = @intCast(size);
    avatar_mask.scaleCircle(@as([*]const u8, @ptrCast(source.bmBits.?))[0 .. 42 * 42 * 4], 42, @as([*]u8, @ptrCast(bits.?))[0 .. target_size * target_size * 4], target_size);
    const memory = win.CreateCompatibleDC(hdc) orelse return;
    defer _ = win.DeleteDC(memory);
    const old_bitmap = win.SelectObject(memory, circle);
    defer _ = win.SelectObject(memory, old_bitmap);
    const blend = win.BLENDFUNCTION{
        .BlendOp = win.AC_SRC_OVER,
        .BlendFlags = 0,
        .SourceConstantAlpha = 255,
        .AlphaFormat = win.AC_SRC_ALPHA,
    };
    _ = win.AlphaBlend(hdc, left, top, size, size, memory, 0, 0, size, size, blend);
}

fn drawWorkspaceBadge(hdc: win.HDC, bitmap: win.HBITMAP, rect: win.RECT, radius_px: i32) bool {
    const side = rect.bottom - rect.top;
    if (rect.right <= rect.left or side <= 0) return false;
    var source: win.BITMAP = undefined;
    if (win.GetObjectW(bitmap, @sizeOf(win.BITMAP), &source) == 0 or source.bmBits == null) return false;
    var info = std.mem.zeroes(win.BITMAPINFO);
    info.bmiHeader.biSize = @sizeOf(win.BITMAPINFOHEADER);
    info.bmiHeader.biWidth = side;
    info.bmiHeader.biHeight = -side;
    info.bmiHeader.biPlanes = 1;
    info.bmiHeader.biBitCount = 32;
    var bits: ?*anyopaque = null;
    const rounded = win.CreateDIBSection(null, &info, win.DIB_RGB_COLORS, &bits, null, 0) orelse return false;
    defer _ = win.DeleteObject(rounded);
    if (bits == null) return false;
    const size: usize = @intCast(side);
    const pixels = @as([*]u8, @ptrCast(bits.?))[0 .. size * size * 4];
    const original = @as([*]const u8, @ptrCast(source.bmBits.?))[0 .. 42 * 42 * 4];
    avatar_mask.scaleSquareArea(original, 42, pixels, size);
    const radius: f32 = @floatFromInt(radius_px);
    for (0..size) |y| {
        for (0..size) |x| {
            const dx = @max(radius - (@as(f32, @floatFromInt(x)) + 0.5), @as(f32, @floatFromInt(x)) + 0.5 - (@as(f32, @floatFromInt(side)) - radius));
            const dy = @max(radius - (@as(f32, @floatFromInt(y)) + 0.5), @as(f32, @floatFromInt(y)) + 0.5 - (@as(f32, @floatFromInt(side)) - radius));
            const alpha: u16 = avatar_mask.distanceAlpha(@sqrt(@max(dx, 0) * @max(dx, 0) + @max(dy, 0) * @max(dy, 0)) - radius);
            for (0..4) |channel| pixels[(y * size + x) * 4 + channel] = @intCast(@as(u16, pixels[(y * size + x) * 4 + channel]) * alpha / 255);
        }
    }
    const memory = win.CreateCompatibleDC(hdc) orelse return false;
    defer _ = win.DeleteDC(memory);
    const previous = win.SelectObject(memory, rounded);
    defer _ = win.SelectObject(memory, previous);
    return win.AlphaBlend(hdc, rect.right - side, rect.bottom - side, side, side, memory, 0, 0, side, side, .{ .BlendOp = win.AC_SRC_OVER, .BlendFlags = 0, .SourceConstantAlpha = 255, .AlphaFormat = win.AC_SRC_ALPHA }) != 0;
}

fn drawProviderMark(shapes: *const smooth.Context, badge: win.RECT, mark: hub.Badge) void {
    const diameter = badge.bottom - badge.top;
    const left = badge.left + @divTrunc(badge.right - badge.left - diameter, 2);
    const circle = win.RECT{ .left = left, .top = badge.top, .right = left + diameter, .bottom = badge.bottom };
    smooth.fillEllipse(shapes, circle, if (mark == .signal_mark) rgb(58, 118, 240) else if (mark == .telegram_mark) rgb(42, 171, 238) else 0x0066d325);
    const x: f32 = @floatFromInt(left);
    const y: f32 = @floatFromInt(badge.top);
    const size: f32 = @floatFromInt(diameter);
    if (mark == .telegram_mark) {
        smooth.strokePolyline(shapes, &.{ .{ x + size * 0.24, y + size * 0.46 }, .{ x + size * 0.76, y + size * 0.26 }, .{ x + size * 0.62, y + size * 0.75 }, .{ x + size * 0.46, y + size * 0.57 }, .{ x + size * 0.66, y + size * 0.37 }, .{ x + size * 0.39, y + size * 0.53 }, .{ x + size * 0.24, y + size * 0.46 } }, 0x00ffffff, size * 0.07);
        return;
    }
    if (mark == .signal_mark) {
        const inner = @divTrunc(diameter * 5, 18);
        smooth.fillEllipse(shapes, .{ .left = circle.left + inner, .top = circle.top + inner, .right = circle.right - inner, .bottom = circle.bottom - inner }, 0x00ffffff);
        smooth.strokePolyline(shapes, &.{ .{ x + size * 0.36, y + size * 0.61 }, .{ x + size * 0.30, y + size * 0.72 }, .{ x + size * 0.47, y + size * 0.65 } }, 0x00ffffff, size * 0.08);
        return;
    }
    smooth.strokePolyline(shapes, &.{
        .{ x + size * 0.34, y + size * 0.29 },
        .{ x + size * 0.29, y + size * 0.39 },
        .{ x + size * 0.35, y + size * 0.53 },
        .{ x + size * 0.48, y + size * 0.66 },
        .{ x + size * 0.61, y + size * 0.71 },
        .{ x + size * 0.71, y + size * 0.65 },
    }, 0x00ffffff, size * 0.12);
    smooth.strokePolyline(shapes, &.{ .{ x + size * 0.34, y + size * 0.29 }, .{ x + size * 0.41, y + size * 0.39 } }, 0x00ffffff, size * 0.15);
    smooth.strokePolyline(shapes, &.{ .{ x + size * 0.61, y + size * 0.59 }, .{ x + size * 0.71, y + size * 0.65 } }, 0x00ffffff, size * 0.15);
}

fn isEmojiCodepoint(cp: u21) bool {
    return (cp >= 0xE000 and cp <= 0xF8FF) or
        (cp >= 0x1F000 and cp <= 0x1FAFF) or
        (cp >= 0xE0020 and cp <= 0xE007F) or
        (cp >= 0x2600 and cp <= 0x27BF) or
        (cp >= 0x2B00 and cp <= 0x2BFF) or
        cp == 0xFE0F or cp == 0x200D or cp == 0x20E3 or
        cp == 0x00A9 or cp == 0x00AE or cp == 0x2122;
}

const TextUnit = struct { emoji: bool, len: usize };

fn emojiUnitAt(text: []const u16, index: usize) TextUnit {
    const unit = text[index];
    if (unit >= 0xD800 and unit <= 0xDBFF and index + 1 < text.len) {
        const low = text[index + 1];
        if (low >= 0xDC00 and low <= 0xDFFF) {
            const cp: u21 = 0x10000 + ((@as(u21, unit) - 0xD800) << 10) + (@as(u21, low) - 0xDC00);
            return .{ .emoji = isEmojiCodepoint(cp), .len = 2 };
        }
    }
    return .{ .emoji = isEmojiCodepoint(unit), .len = 1 };
}

const TextRun = struct { start: usize, len: usize, emoji: bool };
const max_text_runs = 128;

fn splitRuns(text: []const u16, runs: []TextRun) usize {
    var count: usize = 0;
    var index: usize = 0;
    while (index < text.len) {
        const emoji = emojiUnitAt(text, index).emoji;
        const start = index;
        while (index < text.len) {
            const unit = text[index];
            const current = emojiUnitAt(text, index);
            const glue = unit == 0x200D or unit == 0xFE0F or unit == 0x20E3;
            if (current.emoji != emoji and !glue) break;
            index += current.len;
        }
        if (count >= runs.len) break;
        runs[count] = .{ .start = start, .len = index - start, .emoji = emoji };
        count += 1;
    }
    return count;
}

fn containsEmoji(text: []const u16) bool {
    var index: usize = 0;
    while (index < text.len) {
        const current = emojiUnitAt(text, index);
        if (current.emoji) return true;
        index += current.len;
    }
    return false;
}

fn runWidth(hdc: win.HDC, text: []const u16) i32 {
    var rect = win.RECT{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
    _ = text_draw.drawText(hdc, text.ptr, @intCast(text.len), &rect, win.DT_SINGLELINE | win.DT_NOPREFIX | win.DT_CALCRECT);
    return rect.right;
}

fn drawEmojiRun(hdc: win.HDC, emoji_font: win.HFONT, text_ascent: i32, line_height: i32, slice: []const u16, cursor: i32, y: i32, draw: bool) i32 {
    const em = line_height;
    if (slice.len == 1 and slice[0] >= 0xE000 and slice[0] <= 0xF8FF) {
        if (app_ptr) |a| {
            const index: usize = slice[0] - 0xE000;
            if (index < a.custom_emoji.items.len) {
                const entry = &a.custom_emoji.items[index];
                if (draw) {
                    if (entry.bitmap == null) {
                        var loaded: usize = 0;
                        for (a.custom_emoji.items) |cached| {
                            if (cached.bitmap != null) loaded += 1;
                        }
                        while (loaded >= 128) {
                            const old = &a.custom_emoji.items[a.custom_emoji_evict % a.custom_emoji.items.len];
                            a.custom_emoji_evict += 1;
                            if (old.bitmap) |bitmap| {
                                _ = win.DeleteObject(bitmap);
                                old.bitmap = null;
                                loaded -= 1;
                            }
                        }
                        entry.bitmap = loadAvatarBitmap(a, entry.path.ptr());
                    }
                    if (entry.bitmap) |bitmap| {
                        const memory = win.CreateCompatibleDC(hdc) orelse return em;
                        defer _ = win.DeleteDC(memory);
                        const old = win.SelectObject(memory, bitmap);
                        defer _ = win.SelectObject(memory, old);
                        _ = win.AlphaBlend(hdc, cursor, y, em, em, memory, 0, 0, 42, 42, .{ .BlendOp = win.AC_SRC_OVER, .BlendFlags = 0, .SourceConstantAlpha = 255, .AlphaFormat = win.AC_SRC_ALPHA });
                    }
                }
                return em;
            }
        }
    }
    if (slice.len > 1) {
        var start: usize = 0;
        var width: i32 = 0;
        for (slice, 0..) |unit, index| {
            if (unit < 0xE000 or unit > 0xF8FF) continue;
            if (index > start) width += drawEmojiRun(hdc, emoji_font, text_ascent, line_height, slice[start..index], cursor + width, y, draw);
            width += drawEmojiRun(hdc, emoji_font, text_ascent, line_height, slice[index .. index + 1], cursor + width, y, draw);
            start = index + 1;
        }
        if (start > 0) {
            if (start < slice.len) width += drawEmojiRun(hdc, emoji_font, text_ascent, line_height, slice[start..], cursor + width, y, draw);
            return width;
        }
    }
    if (draw) {
        if (emoji_draw.draw(hdc, slice, cursor, y, text_ascent, em)) |run_metrics| return run_metrics.width;
    } else if (emoji_draw.metrics(slice, em)) |run_metrics| {
        return run_metrics.width;
    }
    if (draw) {
        if (app_ptr) |app| {
            if (emoji_draw.takeNotice()) |notice| {
                setStatus(app, notice);
                appendLaunchLog(app, notice);
            }
        }
    }
    _ = win.SelectObject(hdc, @ptrCast(emoji_font));
    if (draw) _ = win.TextOutW(hdc, cursor, y, slice.ptr, @intCast(slice.len));
    var size: win.SIZE = undefined;
    _ = win.GetTextExtentPoint32W(hdc, slice.ptr, @intCast(slice.len), &size);
    return size.cx;
}

fn drawMixedLine(hdc: win.HDC, text_font: win.HFONT, emoji_font: win.HFONT, text: []const u16, x: i32, y: i32) i32 {
    var runs: [max_text_runs]TextRun = undefined;
    const count = splitRuns(text, &runs);
    var cursor = x;
    _ = win.SelectObject(hdc, @ptrCast(text_font));
    const line_height = textLineHeight(hdc, text_font);
    const text_ascent = fontAscent(hdc, text_font);
    for (runs[0..count]) |run| {
        const slice = text[run.start..][0..run.len];
        if (run.emoji) {
            cursor += drawEmojiRun(hdc, emoji_font, text_ascent, line_height, slice, cursor, y, true);
        } else {
            _ = win.SelectObject(hdc, @ptrCast(text_font));
            _ = text_draw.drawRun(hdc, cursor, y, slice.ptr, @intCast(slice.len));
            cursor += runWidth(hdc, slice);
        }
    }
    return cursor;
}

fn fontAscent(hdc: win.HDC, font: win.HFONT) i32 {
    var metrics: win.TEXTMETRICW = undefined;
    const old = win.SelectObject(hdc, @ptrCast(font));
    _ = win.GetTextMetricsW(hdc, &metrics);
    _ = win.SelectObject(hdc, old);
    return metrics.tmAscent;
}

fn textLineHeight(hdc: win.HDC, font: win.HFONT) i32 {
    var metrics: win.TEXTMETRICW = undefined;
    const old = win.SelectObject(hdc, @ptrCast(font));
    _ = win.GetTextMetricsW(hdc, &metrics);
    _ = win.SelectObject(hdc, old);
    return metrics.tmHeight;
}

fn senderBandHeight(hdc: win.HDC, a: *App) i32 {
    const font = a.font_bold orelse a.font.?;
    return textLineHeight(hdc, font);
}

fn messageHeaderHeight(hdc: win.HDC, a: *App, show_sender: bool) i32 {
    if (!show_sender) return px(a, 12);
    return px(a, 6) + senderBandHeight(hdc, a) + px(a, 8);
}

fn timeBandHeight(hdc: win.HDC, a: *App) i32 {
    const font = a.font_small orelse a.font.?;
    return textLineHeight(hdc, font);
}

fn messageTimeRect(hdc: win.HDC, a: *App, right: i32, bottom: i32) win.RECT {
    return .{ .left = right - px(a, 52), .top = bottom - px(a, 5) - timeBandHeight(hdc, a), .right = right - px(a, 10), .bottom = bottom - px(a, 5) };
}

fn startsWithIgnoreCaseUtf16(hay: []const u16, comptime needle: []const u8) bool {
    if (hay.len < needle.len) return false;
    for (needle, 0..) |character, index| {
        if (lowerUnit(hay[index]) != lowerUnit(@as(u16, character))) return false;
    }
    return true;
}

fn wordIsUrl(word: []const u16) bool {
    return startsWithIgnoreCaseUtf16(word, "http://") or
        startsWithIgnoreCaseUtf16(word, "https://") or
        startsWithIgnoreCaseUtf16(word, "www.");
}

fn wrapMixed(hdc: win.HDC, a: *App, text_ptr: [*]const u16, len: c_int, max_width: i32, draw: bool, left: i32, top: i32) i32 {
    return wrapMixedSink(hdc, a, text_ptr, len, max_width, draw, left, top, null);
}

fn containsUrlHint(text: []const u16) bool {
    var index: usize = 0;
    while (index + 4 <= text.len) : (index += 1) {
        if (startsWithIgnoreCaseUtf16(text[index..], "http") or startsWithIgnoreCaseUtf16(text[index..], "www.")) return true;
    }
    return false;
}

fn mixedSliceWidth(hdc: win.HDC, text_font: win.HFONT, emoji_font: win.HFONT, line_height: i32, text_ascent: i32, slice: []const u16) i32 {
    var runs: [max_text_runs]TextRun = undefined;
    const count = splitRuns(slice, &runs);
    var width: i32 = 0;
    for (runs[0..count]) |run| {
        const part = slice[run.start..][0..run.len];
        if (run.emoji) {
            width += drawEmojiRun(hdc, emoji_font, text_ascent, line_height, part, 0, 0, false);
        } else {
            _ = win.SelectObject(hdc, @ptrCast(text_font));
            width += runWidth(hdc, part);
        }
    }
    return width;
}

fn drawWordSlice(hdc: win.HDC, a: *App, text_font: win.HFONT, emoji_font: win.HFONT, line_height: i32, text_ascent: i32, slice: []const u16, cursor_x_in: i32, line_top: i32, link: bool) i32 {
    const text_color = win.GetTextColor(hdc);
    defer _ = win.SetTextColor(hdc, text_color);
    var runs: [max_text_runs]TextRun = undefined;
    const count = splitRuns(slice, &runs);
    var cursor_x = cursor_x_in;
    for (runs[0..count]) |run| {
        const part = slice[run.start..][0..run.len];
        if (!link and run.emoji) {
            cursor_x += drawEmojiRun(hdc, emoji_font, text_ascent, line_height, part, cursor_x, line_top, true);
            continue;
        }
        if (link) {
            _ = win.SelectObject(hdc, @ptrCast(a.font_underline orelse text_font));
            _ = win.SetTextColor(hdc, theme.current.primary);
        } else {
            _ = win.SelectObject(hdc, @ptrCast(text_font));
        }
        if (run.emoji) {
            _ = win.TextOutW(hdc, cursor_x, line_top, part.ptr, @intCast(part.len));
            var size: win.SIZE = undefined;
            _ = win.GetTextExtentPoint32W(hdc, part.ptr, @intCast(part.len), &size);
            cursor_x += size.cx;
        } else {
            _ = text_draw.drawRun(hdc, cursor_x, line_top, part.ptr, @intCast(part.len));
            cursor_x += runWidth(hdc, part);
        }
    }
    return cursor_x;
}

fn containsSurrogateUnit(text: []const u16) bool {
    for (text) |unit| if (unit >= 0xD800 and unit <= 0xDFFF) return true;
    return false;
}

fn isHighSurrogate(unit: u16) bool {
    return unit >= 0xD800 and unit <= 0xDBFF;
}

fn isLowSurrogate(unit: u16) bool {
    return unit >= 0xDC00 and unit <= 0xDFFF;
}

fn isCombiningGlue(unit: u16) bool {
    return unit == 0x200D or unit == 0xFE0F or unit == 0x20E3;
}

fn previousCharStart(word: []const u16, index: usize) usize {
    if (index >= 2 and isLowSurrogate(word[index - 1]) and isHighSurrogate(word[index - 2])) return index - 2;
    return if (index > 0) index - 1 else 0;
}

fn fittingPrefixLen(hdc: win.HDC, text_font: win.HFONT, emoji_font: win.HFONT, line_height: i32, text_ascent: i32, word: []const u16, max_width: i32) usize {
    if (word.len == 0) return 0;
    if (mixedSliceWidth(hdc, text_font, emoji_font, line_height, text_ascent, word[0..1]) > max_width) return 1;
    var lo: usize = 1;
    var hi: usize = word.len;
    while (lo < hi) {
        const mid = lo + (hi - lo + 1) / 2;
        if (mixedSliceWidth(hdc, text_font, emoji_font, line_height, text_ascent, word[0..mid]) <= max_width) {
            lo = mid;
        } else {
            hi = mid - 1;
        }
    }
    return lo;
}

fn wrapChunkLen(word: []const u16, fit: usize) usize {
    if (word.len == 0) return 1;
    const limit = @min(fit, word.len);
    var last_break: usize = 0;
    var index: usize = 0;
    while (index < limit) : (index += 1) {
        switch (word[index]) {
            '/', '?', '&', '=', '-', '.', '_' => last_break = index + 1,
            else => {},
        }
    }
    return clampChunkCut(word, if (last_break > 0) last_break else @max(1, limit));
}

fn clampChunkCut(word: []const u16, cut_in: usize) usize {
    if (word.len == 0) return 1;
    var cut = @min(cut_in, word.len);
    if (cut < word.len and isLowSurrogate(word[cut])) {
        cut = if (cut >= 2) cut - 1 else @min(2, word.len);
    }
    if (cut < 2 and word.len >= 2 and isHighSurrogate(word[0])) cut = 2;
    while (cut < word.len and isCombiningGlue(word[cut])) {
        const start = previousCharStart(word, cut);
        if (start == 0) break;
        cut = start;
    }
    return cut;
}

fn wrapMixedSink(hdc: win.HDC, a: *App, text_ptr: [*]const u16, len: c_int, max_width: i32, draw: bool, left: i32, top: i32, sink: ?*const Message) i32 {
    return wrapMixedSinkExtent(hdc, a, text_ptr, len, max_width, draw, left, top, sink, null);
}

fn wrapMixedSinkExtent(hdc: win.HDC, a: *App, text_ptr: [*]const u16, len: c_int, max_width: i32, draw: bool, left: i32, top: i32, sink: ?*const Message, last_line_right: ?*i32) i32 {
    if (last_line_right) |extent| extent.* = 0;
    const text = text_ptr[0..@intCast(len)];
    if (last_line_right == null and sink == null and !containsEmoji(text) and !containsUrlHint(text)) {
        var rect = win.RECT{ .left = 0, .top = 0, .right = max_width, .bottom = 0 };
        const flags: win.UINT = win.DT_CALCRECT | win.DT_WORDBREAK | win.DT_EDITCONTROL | win.DT_NOPREFIX;
        _ = text_draw.drawText(hdc, text_ptr, len, &rect, flags);
        if (draw) {
            var target = win.RECT{ .left = left, .top = top, .right = left + max_width, .bottom = top + (rect.bottom - rect.top) + 4 };
            _ = text_draw.drawText(hdc, text_ptr, len, &target, win.DT_WORDBREAK | win.DT_EDITCONTROL | win.DT_NOPREFIX);
        }
        return rect.bottom - rect.top;
    }
    const text_font = a.font orelse return 0;
    const emoji_font = a.font_emoji orelse text_font;
    const line_height = textLineHeight(hdc, text_font);
    const text_ascent = fontAscent(hdc, text_font);
    var line_top = top;
    var cursor_x = left;
    var last_right = left;
    var word_start: usize = 0;
    var index: usize = 0;
    while (index <= text.len) {
        const at_end = index == text.len;
        if (at_end or text[index] == ' ' or text[index] == '\n') {
            const word = text[word_start..index];
            const space_width = runWidth(hdc, &[_]u16{' '});
            const word_width = mixedSliceWidth(hdc, text_font, emoji_font, line_height, text_ascent, word);
            if (cursor_x > left and cursor_x + word_width > left + max_width) {
                line_top += line_height;
                cursor_x = left;
                last_right = left;
            }
            var wide_url: [519]u16 = undefined;
            var link_word = word;
            if (sink) |target| {
                if (text.ptr == target.text.ptr()) {
                    for (target.label_links[0..target.label_link_count]) |*link| {
                        if (word_start >= link.start and word_start < link.end) {
                            const length = std.unicode.utf8ToUtf16Le(&wide_url, link.url[0..link.url_len]) catch 0;
                            if (length > 0) link_word = wide_url[0..length];
                            break;
                        }
                    }
                }
            }
            const is_link = wordIsUrl(link_word);
            var emitted: usize = 0;
            while (true) {
                const remaining = word[emitted..];
                var chunk = remaining;
                if (word_width > max_width and remaining.len > 0) {
                    const fit = fittingPrefixLen(hdc, text_font, emoji_font, line_height, text_ascent, remaining, max_width);
                    if (fit < remaining.len) chunk = remaining[0..wrapChunkLen(remaining, fit)];
                }
                const chunk_start = word_start + emitted;
                if (draw) {
                    const word_x_start = cursor_x;
                    cursor_x = drawWordSlice(hdc, a, text_font, emoji_font, line_height, text_ascent, chunk, cursor_x, line_top, is_link);
                    if (is_link) {
                        if (sink) |const_target| {
                            const target = @constCast(const_target);
                            const chunk_rect = win.RECT{ .left = word_x_start, .top = line_top, .right = cursor_x, .bottom = line_top + line_height };
                            var extended = false;
                            if (target.link_count > 0) {
                                const last = &target.links[target.link_count - 1];
                                if (std.mem.eql(u16, last.url.slice(), link_word)) {
                                    if (last.chunk_count < last.chunk_rects.len) {
                                        last.chunk_rects[last.chunk_count] = chunk_rect;
                                        last.chunk_count += 1;
                                    }
                                    extended = true;
                                }
                            }
                            if (!extended and target.link_count < target.links.len) {
                                const span = &target.links[target.link_count];
                                span.rect = chunk_rect;
                                span.chunk_count = 0;
                                if (std.unicode.utf16LeToUtf8Alloc(a.allocator, link_word)) |utf8_word| {
                                    defer a.allocator.free(utf8_word);
                                    span.url.set(a.allocator, utf8_word);
                                    target.link_count += 1;
                                } else |_| {}
                            }
                        }
                    }
                    if (sink) |const_target| {
                        const target = @constCast(const_target);
                        if (text.ptr == target.text.ptr() and target.word_count < target.word_rects.len) {
                            const span = &target.word_rects[target.word_count];
                            span.rect = .{ .left = word_x_start, .top = line_top, .right = cursor_x, .bottom = line_top + line_height };
                            span.start = @intCast(chunk_start);
                            span.len = @intCast(chunk.len);
                            target.word_count += 1;
                        }
                    }
                } else {
                    cursor_x += mixedSliceWidth(hdc, text_font, emoji_font, line_height, text_ascent, chunk);
                }
                if (chunk.len > 0) last_right = cursor_x;
                emitted += chunk.len;
                if (emitted >= word.len or chunk.len == 0) break;
                line_top += line_height;
                cursor_x = left;
                last_right = left;
            }
            if (!at_end) {
                if (draw) {
                    _ = win.SelectObject(hdc, @ptrCast(text_font));
                    _ = text_draw.drawRun(hdc, cursor_x, line_top, &[_]u16{' '}, 1);
                }
                cursor_x += space_width;
            }
            word_start = index + 1;
            if (at_end) break;
            if (text[index] == '\n') {
                line_top += line_height;
                cursor_x = left;
                last_right = left;
            }
        }
        index += 1;
    }
    _ = win.SelectObject(hdc, @ptrCast(text_font));
    if (last_line_right) |extent| extent.* = last_right - left;
    return line_height + (line_top - top);
}

fn drawChat(a: *App, screen_item: *win.DRAWITEMSTRUCT) void {
    if (screen_item.itemID == @as(win.UINT, @bitCast(@as(c_int, -1)))) return;
    const index: usize = @intCast(screen_item.itemID);
    if (index >= a.chat_count) return;
    const background = win.CreateSolidBrush(theme.current.surface_container_low) orelse return;
    defer _ = win.DeleteObject(background);
    var client: win.RECT = undefined;
    _ = win.GetClientRect(screen_item.hwndItem, &client);
    var surface = paint_buffer.Buffer.init(screen_item.hDC, client, screen_item.rcItem);
    defer surface.deinit();
    var buffered = screen_item.*;
    buffered.hDC = surface.hdc;
    const item = &buffered;
    const chat = &a.chats[index];
    const selected = (item.itemState & win.ODS_SELECTED) != 0;
    const bulk_selected = a.bulk.count > 0 and a.bulk.containsKey(chat_key.of(chat));
    _ = win.FillRect(item.hDC, &item.rcItem, background);
    _ = win.SetBkMode(item.hDC, win.TRANSPARENT);
    if (bulk_selected) {
        if (win.CreateSolidBrush(theme.current.primary)) |bar_brush| {
            defer _ = win.DeleteObject(bar_brush);
            var bar = win.RECT{ .left = item.rcItem.left, .top = item.rcItem.top, .right = item.rcItem.left + px(a, 4), .bottom = item.rcItem.bottom };
            _ = win.FillRect(item.hDC, &bar, bar_brush);
        }
    }

    var shapes = smooth.Context.init(item.hDC);
    if (selected or bulk_selected) {
        smooth.fillRoundRect(&shapes, .{ .left = item.rcItem.left + px(a, 8), .top = item.rcItem.top + px(a, 2), .right = item.rcItem.right - px(a, 8), .bottom = item.rcItem.bottom - px(a, 2) }, px(a, theme.selected_row_radius * 2), px(a, theme.selected_row_radius * 2), if (bulk_selected) theme.current.primary_container else theme.current.surface_container_highest);
    }
    const row_text = if (bulk_selected) theme.current.on_primary_container else theme.current.on_surface;
    const row_muted = if (bulk_selected) row_text else theme.current.on_surface_variant;

    const avatar_left = item.rcItem.left + px(a, 12);
    const avatar_top = item.rcItem.top + px(a, 10);
    const avatar_entry = if (hub.chatAvatarEnabled(chat.provider, unifiedHub(a), hub.igsh_696_telegram_avatars)) avatarForChat(a, chat.jid.slice()) else null;
    if (avatar_entry == null or avatar_entry.?.bitmap == null) {
        smooth.fillEllipse(&shapes, .{ .left = avatar_left, .top = avatar_top, .right = avatar_left + 42, .bottom = avatar_top + 42 }, theme.current.surface_container_highest);
    }
    if (avatar_entry != null and avatar_entry.?.bitmap != null) {
        shapes.deinit();
        drawAvatarBitmap(item.hDC, avatar_entry.?.bitmap.?, avatar_left, avatar_top, 42);
        shapes = smooth.Context.init(item.hDC);
    }
    const badge = win.RECT{ .left = avatar_left + px(a, 27), .top = avatar_top + px(a, 28), .right = avatar_left + px(a, 48), .bottom = avatar_top + px(a, 46) };
    var workspace_bitmap: ?win.HBITMAP = null;
    if (hub.igsh_604_workspace_icons and unifiedHub(a) and chat.provider == .slack) {
        if (hub.workspaceAvatarKey(chat.jid.slice())) |key| {
            for (a.avatars[0..a.avatar_count]) |*entry| {
                if (entry.workspace_icon and std.mem.eql(u8, entry.jid.slice(), key)) {
                    workspace_bitmap = entry.bitmap;
                    break;
                }
            }
        }
    }
    var provider_badge = hub.providerBadge(chat.provider, workspace_bitmap != null, hub.igsh_604_workspace_icons);
    if (provider_badge == .workspace_icon) {
        shapes.deinit();
        if (!drawWorkspaceBadge(item.hDC, workspace_bitmap.?, badge, px(a, 4))) provider_badge = .letter_s;
        shapes = smooth.Context.init(item.hDC);
    }
    if (provider_badge == .whatsapp_mark or provider_badge == .signal_mark or provider_badge == .telegram_mark) {
        drawProviderMark(&shapes, badge, provider_badge);
    } else if (provider_badge != .workspace_icon) {
        smooth.fillRoundRect(&shapes, badge, px(a, 8), px(a, 8), theme.current.primary_container);
    }
    const pinned_chat = isChatPinned(a, chat_key.of(chat));
    if (pinned_chat) {
        drawPinIcon(a, &shapes, item.rcItem.right - px(a, 78), item.rcItem.top + px(a, 10), row_muted, false);
    }
    if (chat.unread or chat.unread_count > 0) {
        const diameter = px(a, theme.unread_dot_px);
        const dot_right = item.rcItem.right - px(a, 12);
        const dot_top = item.rcItem.top + @divTrunc(px(a, 35) + px(a, 56) - diameter, 2);
        smooth.fillEllipse(&shapes, .{ .left = dot_right - diameter, .top = dot_top, .right = dot_right, .bottom = dot_top + diameter }, theme.current.primary);
    }
    shapes.deinit();
    _ = win.SetBkMode(item.hDC, win.TRANSPARENT);
    if ((avatar_entry == null or avatar_entry.?.bitmap == null) and chat.name.len > 0) {
        var initial_length: c_int = 1;
        if (chat.name.buf[0] >= 0xd800 and chat.name.buf[0] <= 0xdbff and chat.name.len > 1) initial_length = 2;
        _ = win.SelectObject(item.hDC, @ptrCast(a.font_bold.?));
        _ = win.SetTextColor(item.hDC, theme.current.on_surface);
        var avatar_rect = win.RECT{ .left = avatar_left, .top = avatar_top, .right = avatar_left + 42, .bottom = avatar_top + 42 };
        _ = text_draw.drawText(item.hDC, chat.name.ptr(), initial_length, &avatar_rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
    }

    const name_text = chat.name.slice();
    if (containsEmoji(name_text)) {
        _ = win.SelectObject(item.hDC, @ptrCast(a.font_bold.?));
        _ = win.SetTextColor(item.hDC, row_text);
        const line_h = textLineHeight(item.hDC, a.font_bold.?);
        const name_y = item.rcItem.top + px(a, 10) + @divTrunc(px(a, 24) - line_h, 2);
        _ = drawMixedLine(item.hDC, a.font_bold.?, a.font_emoji orelse a.font_bold.?, name_text, item.rcItem.left + px(a, 66), name_y);
    }

    _ = win.SelectObject(item.hDC, @ptrCast(a.font_small.?));
    _ = win.SetTextColor(item.hDC, theme.current.on_primary_container);
    var badge_text = badge;
    if (provider_badge != .workspace_icon and provider_badge != .whatsapp_mark and provider_badge != .signal_mark and provider_badge != .telegram_mark) {
        _ = text_draw.drawText(item.hDC, switch (provider_badge) {
            .letter_w => lit("W"),
            .letter_s => lit("S"),
            .letter_t => lit("T"),
            else => unreachable,
        }, 1, &badge_text, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
    }
    _ = win.SelectObject(item.hDC, @ptrCast(a.font_bold.?));
    _ = win.SetTextColor(item.hDC, row_text);
    var name_rect = win.RECT{ .left = item.rcItem.left + px(a, 66), .top = item.rcItem.top + px(a, 10), .right = item.rcItem.right - px(a, if (pinned_chat) @as(i32, 78) else 54), .bottom = item.rcItem.top + px(a, 34) };
    _ = text_draw.drawText(item.hDC, chat.name.ptr(), @intCast(chat.name.len), &name_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS | win.DT_VCENTER);
    _ = win.SelectObject(item.hDC, @ptrCast(a.font_small.?));
    _ = win.SetTextColor(item.hDC, row_muted);
    var time_rect = win.RECT{ .left = item.rcItem.right - px(a, 52), .top = item.rcItem.top + px(a, 10), .right = item.rcItem.right - px(a, 10), .bottom = item.rcItem.top + px(a, 32) };
    _ = text_draw.drawText(item.hDC, chat.time.ptr(), @intCast(chat.time.len), &time_rect, win.DT_RIGHT | win.DT_SINGLELINE | win.DT_VCENTER);
    const marker = archiveMarker(a, chat);
    var kind_rect = win.RECT{ .left = item.rcItem.left + px(a, 66), .top = item.rcItem.top + px(a, 35), .right = item.rcItem.right - px(a, if (marker != null) @as(i32, 130) else 42), .bottom = item.rcItem.top + px(a, 56) };
    const draft_text = a.draft_store.get(chat_key.of(chat));
    if (draft_text.len > 0) {
        if (drafts.label(a.allocator, draft_text)) |label| {
            defer a.allocator.free(label);
            var wide_label = WideText(191){};
            wide_label.set(a.allocator, label);
            const row_background = if (bulk_selected) theme.current.primary_container else if (selected) theme.current.surface_container_highest else theme.current.surface_container_low;
            _ = win.SetTextColor(item.hDC, drafts.labelColor(theme.current.*, row_background));
            var prefix_rect = kind_rect;
            _ = text_draw.drawText(item.hDC, wide_label.ptr(), 7, &prefix_rect, win.DT_CALCRECT | win.DT_SINGLELINE | win.DT_NOPREFIX);
            _ = text_draw.drawText(item.hDC, wide_label.ptr(), 7, &kind_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_NOPREFIX);
            var preview_rect = kind_rect;
            preview_rect.left = @min(kind_rect.right, kind_rect.left + prefix_rect.right - prefix_rect.left);
            _ = win.SetTextColor(item.hDC, row_muted);
            _ = text_draw.drawText(item.hDC, wide_label.ptr() + 7, @intCast(wide_label.len - 7), &preview_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS | win.DT_NOPREFIX);
        } else |_| {}
    } else {
        var kind = WideText(255){};
        if (chat.provider == .slack and slackWorkspaceCount(a) > 1) {
            if (slackInstallation(a, chat.account.slice())) |installation| {
                var kind_utf8: [96]u8 = undefined;
                const kind_len = std.unicode.utf16LeToUtf8(&kind_utf8, chat.kind.slice()) catch 0;
                var label: [320]u8 = undefined;
                kind.set(a.allocator, std.fmt.bufPrint(&label, "{s} · {s}", .{ kind_utf8[0..kind_len], if (installation.team_name.len > 0) installation.team_name.slice() else installation.team_id.slice() }) catch installation.team_name.slice());
            }
        }
        if (kind.len == 0) {
            @memcpy(kind.buf[0..chat.kind.len], chat.kind.slice());
            kind.len = chat.kind.len;
        }
        _ = text_draw.drawText(item.hDC, kind.ptr(), @intCast(kind.len), &kind_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS);
    }
    if (marker) |text| {
        _ = win.SetTextColor(item.hDC, if (selected or bulk_selected) row_text else theme.current.primary);
        var marker_rect = win.RECT{ .left = item.rcItem.right - px(a, 128), .top = item.rcItem.top + px(a, 35), .right = item.rcItem.right - px(a, 40), .bottom = item.rcItem.top + px(a, 56) };
        _ = text_draw.drawText(item.hDC, text, -1, &marker_rect, win.DT_RIGHT | win.DT_SINGLELINE);
        _ = win.SetTextColor(item.hDC, row_muted);
    }
}

fn transcriptLineKind(line: []const u16) enum { text, header, bullet, rule, blank } {
    if (line.len == 0) return .blank;
    if (line[0] == '#') return .header;
    if (line[0] == '-' and (line.len == 1 or line[1] == ' ')) return .bullet;
    if (line[0] == '*' and line.len >= 2 and line[1] == ' ') return .bullet;
    if (line.len >= 3) {
        var all_dash = true;
        for (line) |character| {
            if (character != '-') {
                all_dash = false;
                break;
            }
        }
        if (all_dash) return .rule;
    }
    return .text;
}

fn transcriptRender(hdc: win.HDC, a: *App, message: *const Message, shown: c_int, width: i32, draw: bool, left: i32, top: i32) i32 {
    const text = message.transcript.slice()[0..@intCast(shown)];
    var y = top;
    var line_start: usize = 0;
    var index: usize = 0;
    const bullet_char = [_]u16{0x2022};
    while (index <= text.len) {
        const at_end = index == text.len;
        if (at_end or text[index] == '\n') {
            var line = text[line_start..index];
            while (line.len > 0 and (line[line.len - 1] == '\r' or line[line.len - 1] == ' ')) line = line[0 .. line.len - 1];
            switch (transcriptLineKind(line)) {
                .blank => y += 8,
                .rule => {
                    if (draw) {
                        const rule_brush = win.CreateSolidBrush(theme.current.outline_variant) orelse return y - top;
                        defer _ = win.DeleteObject(rule_brush);
                        var rule_rect = win.RECT{ .left = left, .top = y + 3, .right = left + width, .bottom = y + 5 };
                        _ = win.FillRect(hdc, &rule_rect, rule_brush);
                    }
                    y += 12;
                },
                .header => {
                    var content = line;
                    while (content.len > 0 and content[0] == '#') content = content[1..];
                    while (content.len > 0 and content[0] == ' ') content = content[1..];
                    _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
                    _ = win.SetTextColor(hdc, theme.current.primary);
                    if (content.len > 0) y += wrapMixedSink(hdc, a, content.ptr, @intCast(content.len), width, draw, left, y, null) + 6;
                },
                .bullet => {
                    var content = line[1..];
                    while (content.len > 0 and content[0] == ' ') content = content[1..];
                    _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                    _ = win.SetTextColor(hdc, theme.current.primary);
                    if (draw) _ = text_draw.drawRun(hdc, left, y, &bullet_char, 1);
                    _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                    _ = win.SetTextColor(hdc, if (message.from_me) theme.current.on_primary_container else theme.current.on_surface);
                    y += wrapMixedSink(hdc, a, content.ptr, @intCast(content.len), width - 16, draw, left + 16, y, null) + 2;
                },
                .text => {
                    _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                    _ = win.SetTextColor(hdc, if (message.from_me) theme.current.on_primary_container else theme.current.on_surface);
                    y += wrapMixedSink(hdc, a, line.ptr, @intCast(line.len), width, draw, left, y, null) + 2;
                },
            }
            line_start = index + 1;
            if (at_end) break;
        }
        index += 1;
    }
    return y - top;
}

fn showSenderName(a: *App, index: usize) bool {
    if (index == 0) return true;
    const message = &a.messages[index];
    const previous = &a.messages[index - 1];
    if (message.from_me != previous.from_me) return true;
    if (message.sender_jid.len > 0 and previous.sender_jid.len > 0)
        return !std.mem.eql(u8, message.sender_jid.slice(), previous.sender_jid.slice());
    if (message.sender.len == 0 or previous.sender.len == 0) return true;
    return !std.mem.eql(u16, message.sender.slice(), previous.sender.slice());
}

fn messageGap(a: *App, index: usize) i32 {
    return if (showSenderName(a, index)) 8 else 2;
}

const quote_inset: i32 = 12;
const quote_bar_width: i32 = 3;
const quote_text_gap: i32 = 6;
const quote_vertical_pad: i32 = 6;
const quote_after_gap: i32 = 6;
const quote_max_lines: i32 = 2;

fn quoteTextWidth(a: *const App, bubble_width: i32) i32 {
    return @max(1, bubble_width - px(a, quote_inset) * 2 - px(a, quote_bar_width) - px(a, quote_text_gap) * 2);
}

fn quoteBodyHeight(hdc: win.HDC, a: *App, text: []const u16, width: i32) i32 {
    if (text.len == 0) return 0;
    const font = a.font_small orelse return 0;
    _ = win.SelectObject(hdc, @ptrCast(font));
    const line_height = textLineHeight(hdc, font);
    var rect = win.RECT{ .left = 0, .top = 0, .right = width, .bottom = 0 };
    _ = text_draw.drawText(hdc, text.ptr, @intCast(text.len), &rect, win.DT_CALCRECT | win.DT_WORDBREAK | win.DT_EDITCONTROL | win.DT_NOPREFIX);
    return @min(rect.bottom - rect.top, line_height * quote_max_lines);
}

fn quoteBlockHeight(hdc: win.HDC, a: *App, message: *const Message, width: i32) i32 {
    if (message.quote.len == 0) return 0;
    var name_height: i32 = 0;
    if (message.quote_sender.len > 0) {
        const font = a.font_small orelse return 0;
        name_height = textLineHeight(hdc, font);
    }
    return px(a, quote_vertical_pad) + name_height + quoteBodyHeight(hdc, a, message.quote.slice(), quoteTextWidth(a, width)) + px(a, quote_after_gap);
}

fn quoteBlockTint(base: win.COLORREF, toward: u8) win.COLORREF {
    const r: i32 = @intCast(base & 0xff);
    const g: i32 = @intCast((base >> 8) & 0xff);
    const b: i32 = @intCast((base >> 16) & 0xff);
    const t: i32 = toward;
    return rgb(
        @intCast(@divTrunc(r * 88 + t * 12, 100)),
        @intCast(@divTrunc(g * 88 + t * 12, 100)),
        @intCast(@divTrunc(b * 88 + t * 12, 100)),
    );
}

fn measureTag(a: *const App, message: *const Message, width: i32, show_sender: bool) u64 {
    var h = std.hash.Wyhash.init(0);
    const parts = [_]u64{
        @intCast(width),
        @intFromBool(show_sender),
        a.dpi,
        @intCast(a.font_scale),
        message.text.len,
        message.quote.len,
        message.quote_sender.len,
        message.transcript.len,
        @intFromBool(message.transcript_expanded),
        @intFromEnum(message.transcript_state),
        @intCast(message.bitmap_width),
        @intCast(message.bitmap_height),
        message.media_type.len,
        message.reaction.len,
        @intFromEnum(message.unfurl_provider),
        @intCast(threadSummaryHeight(@constCast(a), message)),
    };
    h.update(std.mem.sliceAsBytes(&parts));
    return h.final() | 1;
}

fn measureMessageCached(hdc: win.HDC, a: *App, message: *Message, width: i32, show_sender: bool) i32 {
    _ = unfurlCardVisible(a, message);
    if (message.measure_tag == measureTag(a, message, width, show_sender)) return message.measure_height;
    return measureMessageStore(hdc, a, message, width, show_sender);
}

fn measureMessageStore(hdc: win.HDC, a: *App, message: *Message, width: i32, show_sender: bool) i32 {
    const height = measureMessage(hdc, a, message, width, show_sender) + threadSummaryHeight(a, message);
    message.measure_tag = measureTag(a, message, width, show_sender);
    message.measure_height = height;
    return height;
}

fn reactionChipSize(hdc: win.HDC, a: *App, message: *const Message, width: i32) win.SIZE {
    if (message.reaction.len == 0) return .{ .cx = 0, .cy = 0 };
    const font = a.font.?;
    _ = win.SelectObject(hdc, @ptrCast(font));
    const text_width = @max(1, @min(width - px(a, 36), mixedSliceWidth(hdc, font, a.font_emoji orelse font, textLineHeight(hdc, font), fontAscent(hdc, font), message.reaction.slice())));
    const text_height = wrapMixedSink(hdc, a, message.reaction.ptr(), @intCast(message.reaction.len), text_width, false, 0, 0, null);
    return .{ .cx = text_width + px(a, 12), .cy = text_height + px(a, 8) };
}

fn measureMessage(hdc: win.HDC, a: *App, message: *const Message, width: i32, show_sender: bool) i32 {
    _ = win.SelectObject(hdc, @ptrCast(a.font.?));
    const header_height = messageHeaderHeight(hdc, a, show_sender);
    const skip_body_line = message.text.len == 0 and message.quote.len > 0;
    var height = quoteBlockHeight(hdc, a, message, width) + header_height;
    const text_width = width - px(a, 24);
    var last_line_right: i32 = 0;
    if (!skip_body_line) {
        height += wrapMixedSink(hdc, a, if (message.text.len > 0) message.text.ptr() else lit(" "), if (message.text.len > 0) @intCast(message.text.len) else 1, width - px(a, 24), false, 0, 0, message);
        _ = wrapMixedSinkExtent(hdc, a, if (message.text.len > 0) message.text.ptr() else lit(" "), if (message.text.len > 0) @intCast(message.text.len) else 1, text_width, false, 0, 0, message, &last_line_right);
    }
    if (unfurlCardVisible(a, @constCast(message))) height += unfurl_card_height + px(a, 6);
    if (message.bitmap_height > 0) {
        const display = media_layout.fit(message.bitmap_width, message.bitmap_height, text_width, px(a, 250));
        height += display.height + px(a, 8);
    } else if (message.media_type.len > 0) height += px(a, 54);
    if (message.transcript_state == .loading or message.transcript_state == .failed) height += px(a, 24);
    if (message.transcript.len > 0) {
        _ = win.SelectObject(hdc, @ptrCast(a.font.?));
        const shown: c_int = if (message.transcript_expanded) @intCast(message.transcript.len) else @intCast(@min(message.transcript.len, 400));
        height += transcriptRender(hdc, a, message, shown, width - px(a, 24), false, 0, 0) + px(a, 22);
    }
    const time_rect = messageTimeRect(hdc, a, width, 0);
    const time_width_with_gap = px(a, 12) + text_width - time_rect.left + px(a, 4);
    if (!skip_body_line and message.unfurl_provider == .none and media_layout.needsTimeLine(last_line_right, time_width_with_gap, text_width)) height += timeBandHeight(hdc, a);
    const min_height: i32 = header_height + timeBandHeight(hdc, a) + px(a, 5);
    return @max(height, min_height) + @max(0, reactionChipSize(hdc, a, message, width).cy - px(a, 4));
}

const SenderColor = struct { r: u8, g: u8, b: u8 };

const sender_palette = [_]SenderColor{
    .{ .r = 0, .g = 168, .b = 132 },
    .{ .r = 83, .g = 189, .b = 235 },
    .{ .r = 235, .g = 140, .b = 84 },
    .{ .r = 178, .g = 132, .b = 235 },
    .{ .r = 235, .g = 195, .b = 84 },
    .{ .r = 235, .g = 110, .b = 150 },
};

fn senderColorFor(seed: []const u8) SenderColor {
    if (seed.len == 0) return sender_palette[0];
    var hash: u32 = 2166136261;
    for (seed) |byte| {
        hash ^= byte;
        hash = hash *% 16777619;
    }
    return sender_palette[hash % sender_palette.len];
}

fn senderInitial(sender: []const u16) []const u16 {
    if (sender.len == 0) return sender;
    const first = sender[0];
    if (first >= 0xd800 and first <= 0xdbff and sender.len > 1 and sender[1] >= 0xdc00 and sender[1] <= 0xdfff)
        return sender[0..2];
    return sender[0..1];
}

fn drawSenderAvatar(shapes: *const smooth.Context, hdc: win.HDC, a: *App, x: i32, top: i32, message: *const Message) void {
    if (message.sender_jid.len > 0 and a.selected_chat < a.chat_count and
        a.chats[a.selected_chat].provider == .whatsapp)
    {
        if (avatarEntryForSender(a, message.sender_jid.slice())) |entry| {
            if (entry.bitmap) |bitmap| {
                drawAvatarBitmap(hdc, bitmap, x, top, px(a, 30));
                return;
            }
        }
    }
    const seed = if (message.sender_jid.len > 0)
        message.sender_jid.slice()
    else blk: {
        const units = message.sender.slice();
        break :blk std.mem.sliceAsBytes(units[0..@min(units.len, 2)]);
    };
    const tint = senderColorFor(seed);
    smooth.fillEllipse(shapes, .{ .left = x, .top = top, .right = x + px(a, 30), .bottom = top + px(a, 30) }, rgb(tint.r, tint.g, tint.b));
    const initial = senderInitial(message.sender.slice());
    const old_font = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
    const old_color = win.SetTextColor(hdc, theme.current.on_surface);
    var rect = win.RECT{ .left = x, .top = top, .right = x + px(a, 30), .bottom = top + px(a, 30) };
    _ = text_draw.drawText(hdc, @ptrCast(initial.ptr), @intCast(initial.len), &rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
    _ = win.SetTextColor(hdc, old_color);
    _ = win.SelectObject(hdc, old_font);
}

const ScrollInfo = struct { total: i32 = 0, page: i32 = 0, top: i32 = 0 };

fn trackOf(strip: win.RECT) struct { top: i32, h: i32 } {
    return .{ .top = strip.top + 2, .h = strip.bottom - strip.top - 4 };
}

fn stripRightOf(child: win.HWND, parent: win.HWND) win.RECT {
    var rect: win.RECT = undefined;
    _ = win.GetWindowRect(child, &rect);
    var top_left = win.POINT{ .x = rect.left, .y = rect.top };
    var bottom_right = win.POINT{ .x = rect.right, .y = rect.bottom };
    _ = win.ScreenToClient(parent, &top_left);
    _ = win.ScreenToClient(parent, &bottom_right);
    return .{ .left = bottom_right.x, .top = top_left.y, .right = bottom_right.x + scrollbar_width, .bottom = bottom_right.y };
}

fn hitStrip(strip: win.RECT, x: i32, y: i32) bool {
    return x >= strip.left and x < strip.right and y >= strip.top and y <= strip.bottom;
}

fn drawScrollbar(shapes: *const smooth.Context, strip: win.RECT, info: ScrollInfo, color: win.COLORREF) void {
    const t = trackOf(strip);
    const geom = scrollbar.thumbGeom(t.top, t.h, info.total, info.page, info.top, scrollbar_min_thumb) orelse return;
    const width = strip.right - strip.left - 2;
    smooth.fillRoundRect(shapes, .{ .left = strip.left + 1, .top = geom.top, .right = strip.right - 2, .bottom = geom.top + geom.height - 1 }, width, width, color);
}

fn listboxScrollInfo(hwnd: win.HWND) ScrollInfo {
    const total: i32 = @intCast(win.SendMessageW(hwnd, win.LB_GETCOUNT, 0, 0));
    if (total <= 0) return .{};
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    const item_height: i32 = @intCast(@max(1, win.SendMessageW(hwnd, win.LB_GETITEMHEIGHT, 0, 0)));
    return .{
        .total = total,
        .page = @max(1, @divTrunc(client.bottom - client.top, item_height)),
        .top = @intCast(@max(0, win.SendMessageW(hwnd, win.LB_GETTOPINDEX, 0, 0))),
    };
}

fn setListboxTop(hwnd: win.HWND, top: i32) void {
    _ = win.SendMessageW(hwnd, win.LB_SETTOPINDEX, @intCast(@max(0, top)), 0);
}

fn composeScrollInfo(a: *App, hwnd: win.HWND) ScrollInfo {
    const total: i32 = @intCast(@max(1, win.SendMessageW(hwnd, win.EM_GETLINECOUNT, 0, 0)));
    const top: i32 = @intCast(win.SendMessageW(hwnd, win.EM_GETFIRSTVISIBLELINE, 0, 0));
    const font = a.font orelse return .{ .total = total, .page = 1, .top = top };
    const dc = win.GetDC(hwnd) orelse return .{ .total = total, .page = 1, .top = top };
    defer _ = win.ReleaseDC(hwnd, dc);
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    const line_height = @max(1, textLineHeight(dc, font));
    return .{ .total = total, .page = @max(1, @divTrunc(client.bottom - client.top, line_height)), .top = top };
}

fn setComposeTop(hwnd: win.HWND, target: i32) void {
    const current: i32 = @intCast(win.SendMessageW(hwnd, win.EM_GETFIRSTVISIBLELINE, 0, 0));
    _ = win.SendMessageW(hwnd, win.EM_LINESCROLL, 0, @bitCast(@as(isize, target - current)));
}

fn canvasStripRect(a: *App) win.RECT {
    const canvas = a.canvas orelse return .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
    var client: win.RECT = undefined;
    _ = win.GetClientRect(canvas, &client);
    return .{ .left = client.right - scrollbar_width, .top = client.top, .right = client.right, .bottom = client.bottom };
}

fn canvasScrollInfo(a: *App) ScrollInfo {
    const canvas = a.canvas orelse return .{};
    var client: win.RECT = undefined;
    _ = win.GetClientRect(canvas, &client);
    const page = @max(1, client.bottom - client.top);
    const max_scroll = @max(0, a.max_scroll);
    return .{ .total = page + max_scroll, .page = page, .top = max_scroll - a.scroll_y };
}

fn setCanvasScroll(a: *App, top: i32) void {
    const max_scroll = @max(0, a.max_scroll);
    a.scroll_y = std.math.clamp(max_scroll - @max(0, top), 0, max_scroll);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
    if (a.scroll_y >= max_scroll) requestHubOlder(a);
}

fn setChatsScroll(a: *App, top: i32) void {
    if (a.chats_hwnd) |list| setListboxTop(list, top);
}

fn setComposeScroll(a: *App, top: i32) void {
    if (a.compose) |edit| setComposeTop(edit, top);
}

fn setPaletteScroll(a: *App, top: i32) void {
    if (a.palette_list) |list| setListboxTop(list, top);
}

const SetScrollTop = *const fn (*App, i32) void;

fn beginStripDrag(a: *App, hwnd: win.HWND, strip: win.RECT, info: ScrollInfo, y: i32, target: SbDrag, set_top: SetScrollTop) void {
    const t = trackOf(strip);
    set_top(a, scrollbar.topFromPoint(y, t.top, t.h, info.total, info.page, scrollbar_min_thumb));
    a.sb_drag = target;
    _ = win.SetCapture(hwnd);
}

fn dragStrip(a: *App, strip: win.RECT, info: ScrollInfo, y: i32, set_top: SetScrollTop) void {
    const t = trackOf(strip);
    set_top(a, scrollbar.topFromPoint(y, t.top, t.h, info.total, info.page, scrollbar_min_thumb));
}

fn syncScrollbarStrips(a: *App) void {
    const owner = a.hwnd orelse return;
    if (a.chats_hwnd) |list| {
        const info = listboxScrollInfo(list);
        if (info.total != a.sb_chats_total or info.top != a.sb_chats_top) {
            a.sb_chats_total = info.total;
            a.sb_chats_top = info.top;
            var strip = stripRightOf(list, owner);
            _ = win.InvalidateRect(owner, &strip, win.FALSE);
        }
    }
    if (a.compose) |edit| {
        const info = composeScrollInfo(a, edit);
        if (info.total != a.sb_compose_lines or info.top != a.sb_compose_top) {
            a.sb_compose_lines = info.total;
            a.sb_compose_top = info.top;
            var strip = stripRightOf(edit, owner);
            _ = win.InvalidateRect(owner, &strip, win.FALSE);
        }
    }
    if (a.palette_list) |list| {
        if (a.palette) |palette| {
            const info = listboxScrollInfo(list);
            if (info.total != a.sb_palette_total or info.top != a.sb_palette_top) {
                a.sb_palette_total = info.total;
                a.sb_palette_top = info.top;
                var strip = stripRightOf(list, palette);
                _ = win.InvalidateRect(palette, &strip, win.FALSE);
            }
        }
    }
}

fn drawQuoteBlock(shapes: *const smooth.Context, hdc: win.HDC, a: *App, message: *const Message, left: i32, right: i32, top: i32) i32 {
    const font = a.font_small orelse return top;
    const block_left = left + px(a, quote_inset);
    const block_right = right - px(a, quote_inset);
    const body_height = quoteBodyHeight(hdc, a, message.quote.slice(), quoteTextWidth(a, right - left));
    var name_height: i32 = 0;
    if (message.quote_sender.len > 0) name_height = textLineHeight(hdc, font);
    const block_bottom = top + px(a, quote_vertical_pad) + name_height + body_height;

    const tint = if (message.from_me) quoteBlockTint(theme.current.primary_container, 0) else quoteBlockTint(theme.current.surface_container_high, 255);
    smooth.fillRoundRect(shapes, .{ .left = block_left, .top = top, .right = block_right, .bottom = block_bottom }, 8, 8, tint);

    const accent = senderColorFor(message.quote_sender_jid.slice());
    const accent_color = rgb(accent.r, accent.g, accent.b);
    if (win.CreateSolidBrush(accent_color)) |bar_brush| {
        var bar = win.RECT{ .left = block_left, .top = top + @divTrunc(px(a, quote_vertical_pad), 2), .right = block_left + px(a, quote_bar_width), .bottom = block_bottom - @divTrunc(px(a, quote_vertical_pad), 2) };
        _ = win.FillRect(hdc, &bar, bar_brush);
        _ = win.DeleteObject(bar_brush);
    }

    _ = win.SelectObject(hdc, @ptrCast(font));
    const text_left = block_left + px(a, quote_bar_width) + px(a, quote_text_gap);
    const text_right = block_right - px(a, quote_text_gap);
    var cursor = top + @divTrunc(px(a, quote_vertical_pad), 2);
    if (message.quote_sender.len > 0) {
        _ = win.SetTextColor(hdc, accent_color);
        var name_rect = win.RECT{ .left = text_left, .top = cursor, .right = text_right, .bottom = cursor + name_height };
        _ = text_draw.drawText(hdc, message.quote_sender.ptr(), @intCast(message.quote_sender.len), &name_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS | win.DT_NOPREFIX);
        cursor += name_height;
    }
    if (body_height > 0) {
        _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
        var body_rect = win.RECT{ .left = text_left, .top = cursor, .right = text_right, .bottom = cursor + body_height };
        _ = text_draw.drawText(hdc, message.quote.ptr(), @intCast(message.quote.len), &body_rect, win.DT_LEFT | win.DT_WORDBREAK | win.DT_EDITCONTROL | win.DT_WORD_ELLIPSIS | win.DT_NOPREFIX);
    }
    _ = win.SetTextColor(hdc, if (message.from_me) theme.current.on_primary_container else theme.current.on_surface);
    return block_bottom + px(a, quote_after_gap);
}

fn countPaint(hwnd: win.HWND, dirty: win.RECT, total: *u64, full: *u64) void {
    total.* +%= 1;
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    if (client.right > client.left and client.bottom > client.top and
        dirty.left <= client.left and dirty.top <= client.top and
        dirty.right >= client.right and dirty.bottom >= client.bottom) full.* +%= 1;
}

fn chatsProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    if (message == win.WM_ERASEBKGND) return 1;
    if (message == win.WM_PAINT) {
        var paint: win.PAINTSTRUCT = undefined;
        const screen_dc = win.BeginPaint(hwnd, &paint);
        defer _ = win.EndPaint(hwnd, &paint);
        countPaint(hwnd, paint.rcPaint, &a.paints.list, &a.paints.list_full);
        var client: win.RECT = undefined;
        _ = win.GetClientRect(hwnd, &client);
        var surface = paint_buffer.Buffer.init(screen_dc, client, paint.rcPaint);
        defer surface.deinit();
        _ = win.FillRect(surface.hdc, &paint.rcPaint, if (theme.choice == .amoled) a.brush_bg.? else a.brush_raised.?);
        _ = win.CallWindowProcW(@ptrFromInt(a.chats_prev_proc), hwnd, win.WM_PRINTCLIENT, @intFromPtr(surface.hdc), win.PRF_CLIENT);
        return 0;
    }
    return win.CallWindowProcW(@ptrFromInt(a.chats_prev_proc), hwnd, message, wparam, lparam);
}

fn drawCanvas(hwnd: win.HWND, a: *App) void {
    var paint: win.PAINTSTRUCT = undefined;
    const screen_dc = win.BeginPaint(hwnd, &paint);
    defer _ = win.EndPaint(hwnd, &paint);
    countPaint(hwnd, paint.rcPaint, &a.paints.canvas, &a.paints.canvas_full);
    var client: win.RECT = undefined;
    _ = win.GetClientRect(hwnd, &client);
    var surface = paint_buffer.Buffer.init(screen_dc, client, paint.rcPaint);
    defer surface.deinit();
    const hdc = surface.hdc;
    var shapes = smooth.Context.init(hdc);
    defer shapes.deinit();
    _ = win.FillRect(hdc, &client, a.brush_bg.?);
    _ = win.SetBkMode(hdc, win.TRANSPARENT);
    refreshSlackThreadPanel(a);
    const available_width = client.right - client.left;
    const bubble_width = messageBubbleWidth(a, available_width);
    const chat_jid = if (a.displayed_jid.len > 0)
        a.displayed_jid.slice()
    else if (a.chat_count > 0 and a.selected_chat < a.chat_count)
        a.chats[a.selected_chat].jid.slice()
    else
        "";
    const in_group = std.mem.endsWith(u8, chat_jid, "@g.us");
    if (a.message_bitmap_lru.total_bytes > message_bitmap_budget_bytes) {
        var victims: [max_messages]usize = undefined;
        const evicted = a.message_bitmap_lru.evict(message_bitmap_budget_bytes, &victims);
        for (victims[0..evicted]) |key| {
            for (a.messages[0..a.message_count]) |*message| {
                if (@intFromPtr(message) == key) {
                    if (message.bitmap) |bitmap| {
                        _ = win.DeleteObject(bitmap);
                        message.bitmap = null;
                    }
                    break;
                }
            }
        }
    }
    var total_height: i32 = px(a, 18);
    for (a.messages[0..a.message_count], 0..) |*message, index| {
        if (channelMessageVisible(a, message)) total_height += measureMessageCached(hdc, a, message, bubble_width, showSenderName(a, index)) + messageGap(a, index);
    }
    a.max_scroll = @max(0, total_height - (client.bottom - client.top));
    a.scroll_y = std.math.clamp(a.scroll_y, 0, a.max_scroll);
    var y = client.bottom - px(a, 14) + a.scroll_y;
    var index = a.message_count;
    while (index > 0) {
        index -= 1;
        const message = &a.messages[index];
        setPaintingMessageId(message.id.slice());
        defer clearPaintingMessageId();
        message.media_hit = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
        message.bubble_hit = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
        message.reaction_hit = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
        message.unfurl_card_hit = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
        message.replies_hit = .{ .left = 0, .top = 0, .right = 0, .bottom = 0 };
        message.link_count = 0;
        message.word_count = 0;
        if (!channelMessageVisible(a, message)) continue;
        const show_sender = showSenderName(a, index);
        const estimated_height = measureMessageCached(hdc, a, message, bubble_width, show_sender);
        y -= estimated_height + messageGap(a, index);
        if (y > client.bottom or y + estimated_height < client.top) continue;
        ensureBitmap(a, message);
        var height = measureMessageStore(hdc, a, message, bubble_width, show_sender);
        y -= height - estimated_height;
        if (y > client.bottom or y + height < client.top) continue;
        const left: i32 = if (message.from_me) client.right - bubble_width - px(a, 24) else if (in_group) px(a, 62) else px(a, 24);
        const right = left + bubble_width;
        const reaction_size = reactionChipSize(hdc, a, message, bubble_width);
        const replies_height = threadSummaryHeight(a, message);
        height -= replies_height;
        const bubble_height = height - @max(0, reaction_size.cy - px(a, 4));
        message.bubble_hit = .{ .left = left, .top = y, .right = right, .bottom = y + bubble_height };
        if (replies_height > 0) {
            _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
            _ = win.SetTextColor(hdc, theme.current.primary);
            var line_buffer: [64]u8 = undefined;
            var line = WideText(63){};
            line.set(a.allocator, slack.repliesLine(&line_buffer, threadReplyCount(a, message)));
            message.replies_hit = .{ .left = left + px(a, 12), .top = y + bubble_height, .right = right - px(a, 12), .bottom = y + height + replies_height };
            var line_rect = message.replies_hit;
            line_rect.bottom = line_rect.top + @divTrunc(replies_height, 2);
            _ = text_draw.drawText(hdc, line.ptr(), @intCast(line.len), &line_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_NOPREFIX);
            var last_time = WideText(15){};
            formatSlackTime(&last_time, a.allocator, threadLatestReply(a, message));
            line_rect.top = line_rect.bottom;
            line_rect.bottom = message.replies_hit.bottom;
            _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
            _ = text_draw.drawText(hdc, last_time.ptr(), @intCast(last_time.len), &line_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_NOPREFIX);
        }
        const selected = if (a.selected_message) |selected_index| selected_index == index else false;
        smooth.fillRoundRect(&shapes, message.bubble_hit, px(a, theme.radius_bubble * 2), px(a, theme.radius_bubble * 2), if (message.from_me) theme.current.primary_container else theme.current.surface_container_high);
        if (selected) smooth.strokeRoundRect(&shapes, message.bubble_hit, px(a, theme.radius_bubble * 2), px(a, theme.radius_bubble * 2), theme.current.primary, px(a, 2));

        var text_top = y + messageHeaderHeight(hdc, a, show_sender) - px(a, 6);
        if (show_sender) {
            _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
            const name_tint = if (!message.from_me and in_group and message.sender_jid.len > 0)
                senderColorFor(message.sender_jid.slice())
            else
                null;
            _ = win.SetTextColor(hdc, if (message.from_me)
                theme.current.on_primary_container
            else if (name_tint) |tint|
                rgb(tint.r, tint.g, tint.b)
            else
                theme.current.primary);
            const sender_band = senderBandHeight(hdc, a);
            var sender_rect = win.RECT{ .left = left + px(a, 12), .top = y + px(a, 6), .right = right - px(a, 52), .bottom = y + px(a, 6) + sender_band };
            const sender_text = message.sender.slice();
            if (containsEmoji(sender_text)) {
                _ = drawMixedLine(hdc, a.font_bold.?, a.font_emoji orelse a.font_bold.?, sender_text, left + px(a, 12), y + px(a, 6));
            } else {
                _ = text_draw.drawText(hdc, message.sender.ptr(), @intCast(message.sender.len), &sender_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS);
            }
        }
        if (show_sender and in_group and !message.from_me and message.sender.len > 0) drawSenderAvatar(&shapes, hdc, a, left - px(a, 38), y + px(a, 6), message);
        if (message.quote.len > 0) text_top = drawQuoteBlock(&shapes, hdc, a, message, left, right, text_top);
        if (message.bitmap) |bitmap| {
            const display = media_layout.fit(message.bitmap_width, message.bitmap_height, bubble_width - px(a, 24), px(a, 250));
            const image_left = left + @divTrunc(bubble_width - display.width, 2);
            const image_top = text_top + px(a, 4);
            const image_memory_dc = win.CreateCompatibleDC(hdc);
            if (image_memory_dc != null) {
                const previous = win.SelectObject(image_memory_dc, @ptrCast(bitmap));
                if (display.width != message.bitmap_width or display.height != message.bitmap_height) {
                    const previous_mode = win.SetStretchBltMode(hdc, win.HALFTONE);
                    var previous_origin = std.mem.zeroes(win.POINT);
                    _ = win.SetBrushOrgEx(hdc, 0, 0, &previous_origin);
                    _ = win.StretchBlt(hdc, image_left, image_top, display.width, display.height, image_memory_dc, 0, 0, message.bitmap_width, message.bitmap_height, win.SRCCOPY);
                    _ = win.SetBrushOrgEx(hdc, previous_origin.x, previous_origin.y, null);
                    _ = win.SetStretchBltMode(hdc, previous_mode);
                } else {
                    _ = win.BitBlt(hdc, image_left, image_top, display.width, display.height, image_memory_dc, 0, 0, win.SRCCOPY);
                }
                _ = win.SelectObject(image_memory_dc, previous);
                _ = win.DeleteDC(image_memory_dc);
            }
            message.media_hit = .{ .left = image_left, .top = image_top, .right = image_left + display.width, .bottom = image_top + display.height };
            if (std.ascii.eqlIgnoreCase(message.media_type.slice(), "video")) {
                const radius = @min(26, @min(@divTrunc(display.width, 2), @divTrunc(display.height, 2)));
                if (radius > 4) {
                    const center_x = image_left + @divTrunc(display.width, 2);
                    const center_y = image_top + @divTrunc(display.height, 2);
                    const button_rect = win.RECT{ .left = center_x - radius, .top = center_y - radius, .right = center_x + radius, .bottom = center_y + radius };
                    smooth.fillEllipse(&shapes, button_rect, theme.current.surface);
                    smooth.strokeEllipse(&shapes, button_rect, theme.current.primary, 2);
                    _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
                    _ = win.SetTextColor(hdc, if (message.from_me) theme.current.on_primary_container else theme.current.on_surface);
                    var play_rect = win.RECT{ .left = center_x - radius, .top = center_y - radius, .right = center_x + radius, .bottom = center_y + radius };
                    _ = text_draw.drawText(hdc, lit("▶"), -1, &play_rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
                }
            }
            text_top += display.height + px(a, 8);
        } else if (isAudio(message)) {
            const strip_top = text_top + px(a, 4);
            const button_cx = left + px(a, 26);
            const button_cy = strip_top + px(a, 18);
            const active = std.mem.eql(u8, a.audio_playing_id.slice(), message.id.slice()) and a.audio_state != .empty;
            if (message.local_path.len == 0) {
                _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                _ = win.SetTextColor(hdc, theme.current.primary);
                var media_rect = win.RECT{ .left = left + px(a, 12), .top = strip_top, .right = right - px(a, 12), .bottom = strip_top + px(a, 42) };
                var label_buffer: [128]u8 = undefined;
                var label_wide = WideText(127){};
                label_wide.set(a.allocator, media_drain.attachmentLabel(&label_buffer, "Voice message", message.media_size, if (media_drain.oversized(message.media_size)) .oversized else .downloading));
                _ = text_draw.drawText(hdc, label_wide.ptr(), @intCast(label_wide.len), &media_rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
            } else {
                const playing_now = active and a.audio_state == .playing;
                const glyph_brush = win.CreateSolidBrush(if (theme.choice == .amoled) theme.amoled_button_text else theme.current.on_primary) orelse continue;
                const previous_brush = win.SelectObject(hdc, glyph_brush);
                const previous_pen = win.SelectObject(hdc, win.GetStockObject(win.NULL_PEN));
                smooth.fillEllipse(&shapes, .{ .left = left + px(a, 12), .top = strip_top + px(a, 4), .right = left + px(a, 40), .bottom = strip_top + px(a, 32) }, if (theme.choice == .amoled) theme.amoled_send else theme.current.primary);
                if (theme.choice == .amoled) smooth.strokeEllipse(&shapes, .{ .left = left + px(a, 12), .top = strip_top + px(a, 4), .right = left + px(a, 40), .bottom = strip_top + px(a, 32) }, theme.current.outline, 1);
                if (playing_now) {
                    _ = win.Rectangle(hdc, button_cx - 7, button_cy - 8, button_cx - 2, button_cy + 8);
                    _ = win.Rectangle(hdc, button_cx + 2, button_cy - 8, button_cx + 7, button_cy + 8);
                } else {
                    var triangle = [3]win.POINT{
                        .{ .x = button_cx - 4, .y = button_cy - 8 },
                        .{ .x = button_cx - 4, .y = button_cy + 8 },
                        .{ .x = button_cx + 9, .y = button_cy },
                    };
                    _ = win.Polygon(hdc, &triangle, 3);
                }
                _ = win.SelectObject(hdc, previous_brush);
                _ = win.SelectObject(hdc, previous_pen);
                _ = win.DeleteObject(glyph_brush);

                _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                const speed_active = a.audio_player != null and a.audio_player.?.speed() != 100;
                _ = win.SetTextColor(hdc, if (speed_active) theme.current.primary else theme.current.on_surface_variant);
                var speed_rect = win.RECT{ .left = left + px(a, 48), .top = strip_top + px(a, 4), .right = left + px(a, 90), .bottom = strip_top + px(a, 32) };
                _ = text_draw.drawText(hdc, speedLabel(a.audio_player), -1, &speed_rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);

                const track_left = left + px(a, 94);
                const track_right = right - px(a, 64);
                const track_brush = win.CreateSolidBrush(theme.current.outline_variant) orelse continue;
                var track = win.RECT{ .left = track_left, .top = button_cy - 3, .right = track_right, .bottom = button_cy + 3 };
                _ = win.FillRect(hdc, &track, track_brush);
                if (active and a.audio_duration_ms > 0) {
                    const fraction = std.math.clamp(@as(f64, @floatFromInt(a.audio_position_ms)) / @as(f64, @floatFromInt(a.audio_duration_ms)), 0, 1);
                    track.right = track_left + @as(i32, @intFromFloat(fraction * @as(f64, @floatFromInt(track_right - track_left))));
                    const filled_brush = win.CreateSolidBrush(theme.current.primary) orelse {
                        _ = win.DeleteObject(track_brush);
                        continue;
                    };
                    _ = win.FillRect(hdc, &track, filled_brush);
                    _ = win.DeleteObject(filled_brush);
                }
                if (!active) {
                    const jid_here = if (a.chat_count > 0 and a.selected_chat < a.chat_count) a.chats[a.selected_chat].jid.slice() else "";
                    if (a.voice_pos.get(voicePosKey(a, jid_here, message.id.slice()))) |saved| {
                        if (saved.dur_ms > 0) {
                            const fraction = std.math.clamp(@as(f64, @floatFromInt(saved.pos_ms)) / @as(f64, @floatFromInt(saved.dur_ms)), 0, 1);
                            track.right = track_left + @as(i32, @intFromFloat(fraction * @as(f64, @floatFromInt(track_right - track_left))));
                            if (win.CreateSolidBrush(theme.current.primary)) |filled_brush| {
                                _ = win.FillRect(hdc, &track, filled_brush);
                                _ = win.DeleteObject(filled_brush);
                            }
                        }
                    }
                }
                _ = win.DeleteObject(track_brush);
                if (!active and a.played_set.wasPlayed(message.id.slice())) {
                    _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                    _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
                    var played_rect = win.RECT{ .left = right - px(a, 60), .top = strip_top, .right = right - px(a, 10), .bottom = strip_top + px(a, 42) };
                    _ = text_draw.drawText(hdc, lit("✓ played"), -1, &played_rect, win.DT_RIGHT | win.DT_SINGLELINE | win.DT_VCENTER);
                }
                if (active and a.audio_duration_ms > 0) {
                    var time_buffer: [24]u8 = undefined;
                    var position_buffer: [16]u8 = undefined;
                    var duration_buffer: [16]u8 = undefined;
                    const time_text = std.fmt.bufPrint(&time_buffer, "{s} / {s}", .{ formatClock(&position_buffer, a.audio_position_ms), formatClock(&duration_buffer, a.audio_duration_ms) }) catch "";
                    var time_wide = WideText(31){};
                    time_wide.set(a.allocator, time_text);
                    _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                    _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
                    var time_rect = win.RECT{ .left = right - px(a, 60), .top = strip_top, .right = right - px(a, 10), .bottom = strip_top + px(a, 42) };
                    _ = text_draw.drawText(hdc, time_wide.ptr(), @intCast(time_wide.len), &time_rect, win.DT_RIGHT | win.DT_SINGLELINE | win.DT_VCENTER);
                }
            }
            message.media_hit = .{ .left = left + px(a, 8), .top = strip_top, .right = right - px(a, 8), .bottom = strip_top + px(a, 42) };
            text_top += px(a, 54);
            if (message.transcript_state == .loading) {
                _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
                var loading_rect = win.RECT{ .left = left + px(a, 12), .top = text_top, .right = right - px(a, 12), .bottom = text_top + px(a, 20) };
                _ = text_draw.drawText(hdc, lit("Transcribing…"), -1, &loading_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS);
                text_top += px(a, 24);
            } else if (message.transcript_state == .failed) {
                _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
                var error_rect = win.RECT{ .left = left + px(a, 12), .top = text_top, .right = right - px(a, 12), .bottom = text_top + px(a, 20) };
                _ = text_draw.drawText(hdc, if (message.transcript_error.len > 0) message.transcript_error.ptr() else lit("Transcription failed"), -1, &error_rect, win.DT_LEFT | win.DT_SINGLELINE | win.DT_END_ELLIPSIS);
                text_top += px(a, 24);
            } else if (message.transcript.len > 0) {
                const shown: c_int = if (message.transcript_expanded) @intCast(message.transcript.len) else @intCast(@min(message.transcript.len, 400));
                const transcript_height = transcriptRender(hdc, a, message, shown, right - left - px(a, 24), true, left + px(a, 12), text_top);
                text_top += transcript_height + px(a, 2);
                _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
                _ = win.SetTextColor(hdc, theme.current.primary);
                var toggle_rect = win.RECT{ .left = left + px(a, 12), .top = text_top, .right = right - px(a, 12), .bottom = text_top + px(a, 18) };
                _ = text_draw.drawText(hdc, if (message.transcript_expanded) lit("Show less") else lit("Show more"), -1, &toggle_rect, win.DT_LEFT | win.DT_SINGLELINE);
                message.toggle_hit = toggle_rect;
                text_top += px(a, 20);
            }
        } else if (message.media_type.len > 0) {
            _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
            _ = win.SetTextColor(hdc, theme.current.primary);
            var media_rect = win.RECT{ .left = left + px(a, 12), .top = text_top + px(a, 4), .right = right - px(a, 12), .bottom = text_top + px(a, 46) };
            const local = message.local_path.len > 0;
            var label_buffer: [1024]u8 = undefined;
            var name_buffer: [780]u8 = undefined;
            const name = if (message.filename.len > 0)
                std.unicode.utf16LeToUtf8(&name_buffer, message.filename.slice()) catch 0
            else
                0;
            const kind = if (isVideoGif(message)) "GIF" else if (isVideo(message)) "Video" else if (isImage(message)) "Image" else "Attachment";
            const attachment_state: media_drain.AttachmentState = if (local)
                .local
            else if (media_drain.wazi_135 and mediaUnavailable(a, a.displayed_jid.slice(), message.id.slice()))
                .unavailable
            else if (media_drain.oversized(message.media_size))
                .oversized
            else
                .downloading;
            const label = media_drain.attachmentLabel(&label_buffer, if (name > 0) name_buffer[0..name] else kind, message.media_size, attachment_state);
            var label_wide = WideText(1023){};
            label_wide.set(a.allocator, label);
            _ = text_draw.drawText(hdc, label_wide.ptr(), @intCast(label_wide.len), &media_rect, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER | win.DT_END_ELLIPSIS);
            message.media_hit = media_rect;
            text_top += px(a, 54);
        }
        _ = win.SelectObject(hdc, @ptrCast(a.font.?));
        _ = win.SetTextColor(hdc, if (message.from_me) theme.current.on_primary_container else theme.current.on_surface);
        const skip_body_line = message.text.len == 0 and message.quote.len > 0;
        const text_len: c_int = if (message.text.len > 0) @intCast(message.text.len) else 1;
        const text_height: i32 = if (skip_body_line) 0 else wrapMixedSink(hdc, a, if (message.text.len > 0) message.text.ptr() else lit(" "), text_len, right - left - px(a, 24), true, left + px(a, 12), text_top, message);
        if (verification_fixture and verification_text_comparison and std.mem.eql(u8, message.id.slice(), "ISSUE-462-PARAGRAPH")) {
            saveVerificationTextMetrics(a, hdc, message, left + px(a, 12), text_top, right - left - px(a, 24), text_height);
        }
        if (unfurlCardVisible(a, message)) {
            drawUnfurlCard(&shapes, hdc, a, message, left + px(a, 12), text_top + text_height + px(a, 4), right - left - px(a, 24));
            text_top += text_height + unfurl_card_height + px(a, 6);
        }
        if (a.text_selection.range(index, message.text.len)) |range| {
            const colors = theme.selectionColors(theme.current.*, message.from_me);
            const highlight = win.CreateSolidBrush(colors.fill) orelse return;
            defer _ = win.DeleteObject(highlight);
            for (message.word_rects[0..message.word_count]) |*span| {
                if (span.start < range.start or @as(usize, span.start) + span.len > range.end) continue;
                _ = win.FillRect(hdc, &span.rect, highlight);
                _ = win.SelectObject(hdc, @ptrCast(a.font.?));
                _ = win.SetTextColor(hdc, colors.text);
                const slice = message.text.slice()[span.start..][0..span.len];
                var runs: [max_text_runs]TextRun = undefined;
                const count = splitRuns(slice, &runs);
                var cursor = span.rect.left;
                for (runs[0..count]) |run| {
                    const part = slice[run.start..][0..run.len];
                    if (run.emoji) {
                        cursor += drawEmojiRun(hdc, a.font_emoji orelse a.font.?, fontAscent(hdc, a.font.?), textLineHeight(hdc, a.font.?), part, cursor, span.rect.top, true);
                    } else {
                        _ = text_draw.drawRun(hdc, cursor, span.rect.top, part.ptr, @intCast(part.len));
                        cursor += runWidth(hdc, part);
                    }
                }
            }
        }
        if (message.reaction.len > 0) {
            _ = win.SelectObject(hdc, @ptrCast(a.font.?));
            var my_reaction: [63]u16 = undefined;
            const my_len = std.unicode.utf8ToUtf16Le(&my_reaction, message.my_reaction.slice()) catch 0;
            const included = message.from_me or (my_len > 0 and std.mem.indexOf(u16, message.reaction.slice(), my_reaction[0..my_len]) != null);
            _ = win.SetTextColor(hdc, if (message.reaction_pending) theme.current.on_surface_variant else if (included) theme.current.on_primary_container else theme.current.on_surface);
            const chip_left = if (message.from_me) right - px(a, 12) - reaction_size.cx else left + px(a, 12);
            const chip_top = message.bubble_hit.bottom - px(a, 4);
            const chip = win.RECT{ .left = chip_left, .top = chip_top, .right = chip_left + reaction_size.cx, .bottom = chip_top + reaction_size.cy };
            message.reaction_hit = chip;
            smooth.fillRoundRect(&shapes, chip, px(a, 12), px(a, 12), if (included) theme.current.primary_container else theme.current.surface_container_high);
            smooth.strokeRoundRect(&shapes, chip, px(a, 12), px(a, 12), theme.current.outline_variant, px(a, 1));
            _ = wrapMixedSink(hdc, a, message.reaction.ptr(), @intCast(message.reaction.len), reaction_size.cx - px(a, 12), true, chip.left + px(a, 6), chip.top + px(a, 4), null);
        }
        _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
        _ = win.SetTextColor(hdc, if (message.send_state == .failed) theme.current.@"error" else theme.current.on_surface_variant);
        const time_band = timeBandHeight(hdc, a);
        var time_rect = win.RECT{ .left = right - px(a, 52), .top = y + bubble_height - px(a, 5) - time_band, .right = right - px(a, 10), .bottom = y + bubble_height - px(a, 5) };
        _ = text_draw.drawText(hdc, message.time.ptr(), @intCast(message.time.len), &time_rect, win.DT_RIGHT | win.DT_SINGLELINE);
    }
    if (a.selected_chat < a.chat_count) {
        if (archiveMarker(a, &a.chats[a.selected_chat])) |text| {
            _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
            var badge = win.RECT{ .left = client.right - px(a, 150), .top = client.top + px(a, 8), .right = client.right - px(a, 24), .bottom = client.top + px(a, 32) };
            if (win.CreateSolidBrush(theme.current.surface_container_high)) |badge_brush| {
                defer _ = win.DeleteObject(badge_brush);
                _ = win.FillRect(hdc, &badge, badge_brush);
            }
            _ = win.SetTextColor(hdc, theme.current.primary);
            _ = text_draw.drawText(hdc, text, -1, &badge, win.DT_CENTER | win.DT_SINGLELINE | win.DT_VCENTER);
        }
    }
    drawScrollbar(&shapes, canvasStripRect(a), canvasScrollInfo(a), theme.current.outline);
}

fn canvasProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        win.WM_PAINT => {
            drawCanvas(hwnd, a);
            return 0;
        },
        win.WM_ERASEBKGND => return 1,
        win.WM_TIMER => {
            if (wparam != timer_passage_scroll or !a.text_dragging) return 0;
            var point: win.POINT = undefined;
            var client: win.RECT = undefined;
            if (win.GetCursorPos(&point) == 0 or win.ScreenToClient(hwnd, &point) == 0 or win.GetClientRect(hwnd, &client) == 0) return 0;
            const step: i32 = if (point.y <= client.top) px(a, 24) else if (point.y >= client.bottom - 1) -px(a, 24) else return 0;
            const previous = a.scroll_y;
            a.scroll_y = std.math.clamp(a.scroll_y + step, 0, a.max_scroll);
            if (a.scroll_y != previous) a.drag_moved = true;
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            _ = win.UpdateWindow(hwnd);
            updatePassageFocus(a, point.x, point.y);
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            return 0;
        },
        win.WM_MOUSEWHEEL => {
            const delta: i16 = @bitCast(hiword(wparam));
            a.scroll_y = std.math.clamp(a.scroll_y + @divTrunc(@as(i32, delta), 2), 0, a.max_scroll);
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            return 0;
        },
        win.WM_LBUTTONDOWN => {
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            if (a.canvas != null) {
                const strip = canvasStripRect(a);
                const info = canvasScrollInfo(a);
                if (hitStrip(strip, x, y)) {
                    if (scrollbar.thumbGeom(trackOf(strip).top, trackOf(strip).h, info.total, info.page, info.top, scrollbar_min_thumb)) |geom| {
                        _ = geom;
                        beginStripDrag(a, hwnd, strip, info, y, .canvas, setCanvasScroll);
                        return 0;
                    }
                }
            }
            for (a.messages[0..a.message_count]) |*item| {
                const chip = item.reaction_hit;
                if (chip.right > chip.left and rectHasPoint(chip, x, y)) {
                    a.canvas_double_click_handled = false;
                    return 0;
                }
            }
            for (a.messages[0..a.message_count], 0..) |*item, index| {
                const hit = item.replies_hit;
                if (hit.right > hit.left and x >= hit.left and x < hit.right and y >= hit.top and y < hit.bottom) {
                    openSlackThread(a, index);
                    return 0;
                }
            }
            a.click_origin = .{ .x = x, .y = y };
            a.click_moved = false;
            a.canvas_double_click_handled = false;
            for (a.messages[0..a.message_count], 0..) |*item, index| {
                const bubble = item.bubble_hit;
                if (x >= bubble.left and x <= bubble.right and y >= bubble.top and y <= bubble.bottom) {
                    if (hitTestWord(item, x, y)) |word_index| {
                        const point = selectionPoint(a, index, word_index);
                        a.text_selection = .{ .anchor = point, .focus = point };
                        a.selected_message = index;
                        a.text_dragging = true;
                        a.drag_moved = false;
                        a.drag_origin = .{ .x = x, .y = y };
                        _ = win.SetFocus(hwnd);
                        _ = win.SetCapture(hwnd);
                        _ = win.SetTimer(hwnd, timer_passage_scroll, 40, null);
                        _ = win.InvalidateRect(hwnd, null, win.FALSE);
                    }
                    break;
                }
            }
            return 0;
        },
        win.WM_LBUTTONDBLCLK => {
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            if (handleCanvasDoubleClick(a, x, y)) {
                a.canvas_double_click_handled = true;
                a.click_moved = true;
                return 0;
            }
            return canvasProc(hwnd, win.WM_LBUTTONDOWN, wparam, lparam);
        },
        win.WM_MOUSEMOVE => {
            if (a.sb_drag == .canvas) {
                const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
                if (a.canvas != null) dragStrip(a, canvasStripRect(a), canvasScrollInfo(a), y, setCanvasScroll);
                return 0;
            }
            if (!a.click_moved) {
                const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
                const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
                const cdx = x - a.click_origin.x;
                const cdy = y - a.click_origin.y;
                if (cdx * cdx + cdy * cdy > 16) a.click_moved = true;
            }
            if (!a.text_dragging or a.text_selection.anchor == null) return win.DefWindowProcW(hwnd, message, wparam, lparam);
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            const dx = x - a.drag_origin.x;
            const dy = y - a.drag_origin.y;
            if (dx * dx + dy * dy > 16) a.drag_moved = true;
            updatePassageFocus(a, x, y);
            _ = win.InvalidateRect(hwnd, null, win.FALSE);
            return 0;
        },
        win.WM_LBUTTONUP => {
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            if (a.sb_drag == .canvas) {
                _ = win.ReleaseCapture();
                a.sb_drag = .none;
                return 0;
            }
            if (a.canvas_double_click_handled) {
                a.canvas_double_click_handled = false;
                return 0;
            }
            if (a.text_dragging) {
                _ = win.KillTimer(hwnd, timer_passage_scroll);
                a.text_dragging = false;
                if (a.drag_moved) updatePassageFocus(a, x, y);
                _ = win.ReleaseCapture();
                if (!a.drag_moved) {
                    a.text_selection = .{};
                    handleCanvasClick(a, hwnd, x, y);
                }
                _ = win.InvalidateRect(hwnd, null, win.FALSE);
                return 0;
            }
            handleCanvasClick(a, hwnd, x, y);
            return 0;
        },
        win.WM_CAPTURECHANGED => {
            _ = win.KillTimer(hwnd, timer_passage_scroll);
            a.sb_drag = .none;
            a.text_dragging = false;
            return 0;
        },
        win.WM_RBUTTONUP => {
            const x: i32 = @as(i16, @bitCast(loword(@as(usize, @bitCast(lparam)))));
            const y: i32 = @as(i16, @bitCast(hiword(@as(usize, @bitCast(lparam)))));
            if (a.text_selection.active()) {
                const ends = a.text_selection.bounds().?;
                var selected_index = ends[0].message;
                while (selected_index <= ends[1].message and selected_index < a.message_count) : (selected_index += 1) {
                    const item = &a.messages[selected_index];
                    const bubble = item.bubble_hit;
                    if (x >= bubble.left and x <= bubble.right and y >= bubble.top and y <= bubble.bottom) {
                        a.selected_message = selected_index;
                        var point = win.POINT{ .x = x, .y = y };
                        _ = win.ClientToScreen(hwnd, &point);
                        const menu = win.CreatePopupMenu() orelse return 0;
                        defer _ = win.DestroyMenu(menu);
                        _ = win.AppendMenuW(menu, win.MF_STRING, command_reply, lit("Reply"));
                        _ = win.AppendMenuW(menu, win.MF_SEPARATOR, 0, null);
                        _ = win.AppendMenuW(menu, win.MF_STRING, command_copy_selection, lit("Copy selection"));
                        _ = win.AppendMenuW(menu, win.MF_STRING, command_copy_text, lit("Copy message text"));
                        if (item.transcript.len > 0) _ = win.AppendMenuW(menu, win.MF_STRING, command_copy_transcript, lit("Copy transcript"));
                        if (item.link_count > 0) _ = win.AppendMenuW(menu, win.MF_STRING, command_copy_link, lit("Copy link address"));
                        const choice = win.TrackPopupMenu(menu, win.TPM_RETURNCMD | win.TPM_NONOTIFY, point.x, point.y, 0, a.hwnd.?, null);
                        if (choice == command_reply) startReply(a) else reactToSelected(a, @intCast(choice));
                        return 0;
                    }
                }
            }
            for (a.messages[0..a.message_count], 0..) |*item, index| {
                const bubble = item.bubble_hit;
                if (x >= bubble.left and x <= bubble.right and y >= bubble.top and y <= bubble.bottom) {
                    a.selected_message = index;
                    _ = win.InvalidateRect(hwnd, null, win.FALSE);
                    var point = win.POINT{ .x = x, .y = y };
                    _ = win.ClientToScreen(hwnd, &point);
                    openReactionMenu(a, point.x, point.y);
                    break;
                }
            }
            return 0;
        },
        else => return win.DefWindowProcW(hwnd, message, wparam, lparam),
    }
}

fn selectChatRow(a: *App, row: usize) void {
    _ = clearBulkSelection(a);
    if (row >= a.chat_count) return;
    _ = win.SendMessageW(a.chats_hwnd.?, win.LB_SETCURSEL, row, 0);
    discardStagedImage(a);
    a.selected_chat = row;
    switchComposerDraft(a);
    a.user_viewed = true;
    beginTranscriptionOpen(a);
    refreshMessages(a);
    focusCompose(a);
    _ = win.InvalidateRect(a.hwnd.?, null, win.FALSE);
}

fn openChatMenu(a: *App, lparam: win.LPARAM) void {
    const list = a.chats_hwnd orelse return;
    var row: usize = undefined;
    var point: win.POINT = undefined;
    if (lparam == -1) {
        const selected = win.SendMessageW(list, win.LB_GETCURSEL, 0, 0);
        if (selected < 0 or selected >= a.chat_count) return;
        row = @intCast(selected);
        var rect: win.RECT = undefined;
        if (win.SendMessageW(list, win.LB_GETITEMRECT, row, @intCast(@intFromPtr(&rect))) == win.LB_ERR) return;
        point = .{ .x = rect.left, .y = rect.bottom };
        if (win.ClientToScreen(list, &point) == 0) return;
    } else {
        const coords: usize = @bitCast(lparam);
        point = .{ .x = @as(i16, @bitCast(loword(coords))), .y = @as(i16, @bitCast(hiword(coords))) };
        var client = point;
        if (win.ScreenToClient(list, &client) == 0) return;
        const client_coords = @as(u32, @as(u16, @bitCast(@as(i16, @intCast(client.x))))) |
            (@as(u32, @as(u16, @bitCast(@as(i16, @intCast(client.y))))) << 16);
        const hit = win.SendMessageW(list, win.LB_ITEMFROMPOINT, 0, @intCast(client_coords));
        const result: usize = @bitCast(hit);
        if (hiword(result) != 0) return;
        row = loword(result);
        if (row >= a.chat_count) return;
        var rect: win.RECT = undefined;
        if (win.SendMessageW(list, win.LB_GETITEMRECT, row, @intCast(@intFromPtr(&rect))) == win.LB_ERR) return;
        if (client.x < rect.left or client.x >= rect.right or client.y < rect.top or client.y >= rect.bottom) return;
    }
    if (row != a.selected_chat and !(a.bulk.count > 0 and a.bulk.containsKey(chat_key.of(&a.chats[row]))))
        selectChatRow(a, row);
    const chat = &a.chats[row];
    const choice = menu: {
        const popup = win.CreatePopupMenu() orelse return;
        defer _ = win.DestroyMenu(popup);
        var out: [2]chat_menu.Item = undefined;
        const rows = chat_menu.items(.{
            .archived = chat.archived,
            .pinned = isChatPinned(a, chat_key.of(chat)),
            .show_archived = a.show_archived,
        }, .{ .archive = command_archive, .pin = command_pin }, &out);
        for (rows) |item| _ = win.AppendMenuW(popup, win.MF_STRING, item.command, item.label.ptr);
        break :menu win.TrackPopupMenu(popup, win.TPM_RETURNCMD | win.TPM_NONOTIFY | win.TPM_RIGHTBUTTON, point.x, point.y, 0, a.hwnd.?, null);
    };
    if (choice != 0) runCommand(a, @intCast(choice));
}

fn mainProc(hwnd: win.HWND, message: win.UINT, wparam: win.WPARAM, lparam: win.LPARAM) callconv(.winapi) win.LRESULT {
    const a = app_ptr orelse return win.DefWindowProcW(hwnd, message, wparam, lparam);
    switch (message) {
        wm_update_ready => {
            if (wparam >= 2 and wparam <= 5) a.update_check_running = false;
            if (wparam == 1 or wparam >= 6) a.update_install_running.store(false, .release);
            switch (wparam) {
                1 => {
                    a.update_installed = true;
                    a.update_failures = 0;
                    setStatus(a, "Update installed - restarting");
                    _ = win.SetTimer(hwnd, timer_update_restart, update_card_restart_delay_ms, null);
                    updateCardRefresh(a);
                },
                2 => {
                    const upd: *UpdateAvailable = @ptrFromInt(@as(usize, @bitCast(lparam)));
                    if (a.update_installed) {
                        upd.deinit(std.heap.page_allocator);
                        std.heap.page_allocator.destroy(upd);
                        return 0;
                    }
                    const known = if (a.update_pending) |old| old.tag else null;
                    const is_new_offer = update.isNewOffer(known, upd.tag);
                    if (a.update_pending) |old| {
                        old.deinit(std.heap.page_allocator);
                        std.heap.page_allocator.destroy(old);
                    }
                    a.update_pending = upd;
                    if (is_new_offer) a.update_failures = 0;
                    if (is_new_offer) {
                        a.update_staged = false;
                        a.update_card_error_len = 0;
                    }
                    if (a.update_card_busy or a.update_install_running.load(.acquire)) {
                        updateCardRefresh(a);
                        return 0;
                    }
                    a.update_install_auto = true;
                    if (!a.update_staged) startUpdateInstall(hwnd, true);
                    var offer_buf: [128]u8 = undefined;
                    setStatus(a, std.fmt.bufPrint(&offer_buf, "New version {s} is available - use the card to update", .{upd.tag}) catch "New version available");
                    var offer_log_buf: [160]u8 = undefined;
                    appendLaunchLog(a, std.fmt.bufPrint(&offer_log_buf, "update: card offered {s}", .{upd.tag}) catch "update: card offered");
                    updateCardRefresh(a);
                },
                3 => {
                    a.update_failures = 0;
                    var none_buf: [96]u8 = undefined;
                    setStatus(a, std.fmt.bufPrint(&none_buf, "You are on v{s} - this is the newest version", .{app_version}) catch "No updates found");
                },
                9 => {
                    a.update_staged = true;
                    a.update_failures = 0;
                    if (a.update_click_wait) {
                        a.update_click_wait = false;
                        startUpdateInstall(hwnd, false);
                    }
                    updateCardRefresh(a);
                },
                6 => {
                    if (a.update_install_auto) {
                        a.update_failures += 1;
                    } else {
                        a.update_failures = 0;
                    }
                    if (!a.update_install_auto or a.update_failures >= 2) setStatus(a, "Update blocked: another copy of Messages is running - close other copies and try again");
                    updateCardFail(a, "Another copy of Messages is running");
                },
                8 => {
                    a.update_click_wait = false;
                    if (a.update_card_busy) {
                        a.update_card_busy = false;
                        if (a.update_pending) |old| {
                            old.deinit(std.heap.page_allocator);
                            std.heap.page_allocator.destroy(old);
                            a.update_pending = null;
                        }
                        updateCardRefresh(a);
                    }
                    if (a.update_install_auto) {
                        a.update_failures += 1;
                    } else {
                        a.update_failures = 0;
                    }
                    if (!a.update_install_auto or a.update_failures >= 2) {
                        var none_buf: [96]u8 = undefined;
                        setStatus(a, std.fmt.bufPrint(&none_buf, "You are on v{s} - this is the newest version", .{app_version}) catch "No updates found");
                    }
                },
                4, 5, 7 => {
                    const name: [*:0]const u8 = @ptrFromInt(@as(usize, @bitCast(lparam)));
                    a.update_failures += 1;
                    var fail_buf: [128]u8 = undefined;
                    const verb: []const u8 = if (wparam == 7) "install" else "check";
                    const text = std.fmt.bufPrint(&fail_buf, "Update {s} failed: {s}", .{ verb, std.mem.span(name) }) catch "Update failed";
                    const auto = wparam == 4 or (wparam == 7 and a.update_install_auto);
                    if (!auto or a.update_failures >= 2) setStatus(a, text);
                    if (wparam == 7 and (a.update_card_busy or a.update_click_wait)) updateCardFail(a, std.mem.span(name));
                },
                else => {},
            }
            return 0;
        },
        wm_hub_event => {
            a.hub_event_pending.store(false, .release);
            const reset = a.hub_reset_pending.swap(false, .acq_rel);
            if (reset) refreshGroups(a);
            const backend = hubTransport(a);
            backend.refreshChats();
            if (a.selected_chat < a.chat_count and (unifiedHub(a) or a.chats[a.selected_chat].provider == .whatsapp)) backend.refreshMessages(a.chats[a.selected_chat].jid.slice());
            drainMediaDownloads(a);
            appendLaunchLog(a, if (reset) "hub: baseline refreshed" else "hub: live event refreshed");
            return 0;
        },
        wm_wacli_done => {
            const result: *WacliResult = @ptrFromInt(@as(usize, @bitCast(lparam)));
            defer {
                if (result.data.len > 0) a.allocator.free(result.data);
                a.allocator.destroy(result);
            }
            wacliPendingSub(a, result.kind);
            defer {
                if (result.provider == .slack and std.mem.eql(u8, result.extra.slice(), "SignInRequired")) {
                    if (slackInstallation(a, result.account.slice())) |installation| {
                        if (installation.needs_signin.load(.acquire)) {
                            var buffer: [256]u8 = undefined;
                            setStatus(a, std.fmt.bufPrint(&buffer, "Slack workspace {s} needs sign-in; use Connect Slack workspace", .{installation.team_name.slice()}) catch "Slack workspace needs sign-in; use Connect Slack workspace");
                        }
                    }
                }
            }
            if (jobIsSlack(result.kind) and !result.ok) logSlackFailure(a, result.kind, result.extra.slice(), result.http_status);
            if (result.kind != .cache_tag and result.provider == .whatsapp and !std.mem.eql(u8, result.account.slice(), a.cache_tag.slice()) and !unifiedHub(a)) {
                var buffer: [128]u8 = undefined;
                appendLaunchLog(a, std.fmt.bufPrint(&buffer, "wacli-result: dropped {s}, account mismatch", .{@tagName(result.kind)}) catch "wacli-result: dropped, account mismatch");
                return 0;
            }
            switch (result.kind) {
                .hub_send, .hub_read, .hub_archive, .hub_media, .hub_avatar, .hub_thread, .hub_older => applyHubResult(a, result),
                .groups => if (result.ok) applyGroups(a, result.data),
                .contacts_index => if (result.ok) {
                    a.people.replaceContacts(result.data) catch return 0;
                    refreshPeopleSearch(a);
                },
                .chats => {
                    if (!result.ok and result.gen == a.chats_gen) {
                        setStatus(a, "Unable to read chats from wacli");
                        if (a.chats_read_attempts < 3) {
                            a.chats_read_attempts += 1;
                            a.chats_read_retry_ticks = 2;
                            var fail_buffer: [48]u8 = undefined;
                            const fail_line = std.fmt.bufPrint(&fail_buffer, "chats-read: fail, retry {d}/3", .{a.chats_read_attempts}) catch "chats-read: fail";
                            appendLaunchLog(a, fail_line);
                        }
                    } else if (result.ok and result.gen == a.chats_gen) {
                        if (applyChats(a, result.data, true)) {
                            a.chats_read_retry_ticks = 0;
                            a.chats_read_attempts = 0;
                            saveChatsCache(a, result.data);
                            var log_buffer: [64]u8 = undefined;
                            const log_line = std.fmt.bufPrint(&log_buffer, "chats-read: ok {d} bytes, {d} chats", .{ result.data.len, a.chat_count }) catch "chats-read: ok";
                            appendLaunchLog(a, log_line);
                            reconcileOpenChat(a);
                        } else if (a.chats_read_attempts < 3) {
                            a.chats_read_attempts += 1;
                            a.chats_read_retry_ticks = 2;
                            appendLaunchLog(a, "chats-read: malformed payload, retrying");
                        }
                    }
                },
                .messages => {
                    var kind: []const u8 = "unknown";
                    var refresh_again = result.gen == a.messages_gen and a.messages_refresh_again;
                    if (result.gen == a.messages_gen) {
                        a.messages_read_key = .{};
                        a.messages_refresh_again = false;
                    }
                    for (a.chats[0..a.chat_count]) |*chat| {
                        if (chat_key.Key.eql(chat_key.of(chat), chat_key.of(result))) {
                            kind = @tagName(chat.provider);
                            break;
                        }
                    }
                    if (!result.ok) {
                        setStatus(a, "Unable to read messages from wacli");
                        var fail_buffer: [128]u8 = undefined;
                        const fail_line = std.fmt.bufPrint(&fail_buffer, "messages-read: fail, chat={s} err={s}", .{ kind, result.extra.slice() }) catch "messages-read: fail";
                        appendLaunchLog(a, fail_line);
                        if (result.gen == a.messages_gen and a.selected_chat < a.chat_count and
                            chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(result)))
                        {
                            scheduleMessageReadRetry(a);
                        }
                    } else if (a.selected_chat < a.chat_count and
                        chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(result)) and
                        result.gen == a.messages_gen)
                    {
                        if (a.message_count > 0 and a.pending_send_count == 0 and a.failed_send_count == 0 and
                            chat_key.Key.eql(chat_key.displayed(a), chat_key.of(result)) and
                            std.hash.Wyhash.hash(0, result.data) == a.msg_applied_hash)
                        {
                            a.displayed_timestamp = a.chats[a.selected_chat].timestamp;
                            markChatRead(a);
                            a.msg_read_attempts = 0;
                            a.msg_read_retry_ticks = 0;
                        } else if (applyMessageData(a, result.data, true)) {
                            msgCacheStore(a, chat_key.of(result), result.data);
                            if (unifiedHub(a) and a.chats[a.selected_chat].provider == .slack) refreshVisibleChats(a);
                            a.msg_read_attempts = 0;
                            a.msg_read_retry_ticks = 0;
                        } else {
                            setStatus(a, "Unable to read messages from wacli");
                            var fail_buffer: [128]u8 = undefined;
                            const fail_line = std.fmt.bufPrint(&fail_buffer, "messages-read: empty payload, chat={s}", .{kind}) catch "messages-read: empty payload";
                            appendLaunchLog(a, fail_line);
                            scheduleMessageReadRetry(a);
                            refresh_again = false;
                        }
                    } else {
                        const reason: []const u8 = if (a.selected_chat >= a.chat_count)
                            "selection changed"
                        else if (!chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(result)))
                            "identity changed"
                        else
                            "generation changed";
                        var drop_buffer: [96]u8 = undefined;
                        appendLaunchLog(a, std.fmt.bufPrint(&drop_buffer, "messages-read: dropped reply, {s}", .{reason}) catch "messages-read: dropped reply");
                    }
                    if (refresh_again and result.ok and result.gen == a.messages_gen and a.selected_chat < a.chat_count and
                        chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(result))) refreshMessages(a);
                },
                .background_media => applyBackgroundMedia(a, result),
                .reaction => applyReaction(a, result),
                .archived_scan => if (result.ok) applyArchivedScan(a, result.data),
                .kept_check => if (result.ok) applyKeptCheck(a, result.data),
                .unread_probe => applyUnreadProbe(a, result),
                .cache_tag => {
                    if (hubConfigured(a)) {
                        applyHubAccounts(a, result);
                        return 0;
                    }
                    if (a.sync_auth_probe and result.gen == a.cache_tag_gen) applySyncAuthProbe(a, result.ok, result.data);
                    if (a.pairing_probe and result.gen == a.cache_tag_gen) applyPairingProbe(a, result.ok, result.data);
                    if (result.ok and result.gen == a.cache_tag_gen) {
                        var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, result.data, .{}) catch return 0;
                        defer parsed.deinit();
                        const linked = auth_status.linkedJid(parsed.value) orelse return 0;
                        if (linked.len > 0) {
                            var tag_buffer: [32]u8 = undefined;
                            const tag = std.fmt.bufPrint(&tag_buffer, "{x:0>16}", .{std.hash.Wyhash.hash(0, linked)}) catch return 0;
                            a.cache_tag.set(tag);
                            bindOutboxAccount(a);
                        }
                    }
                    if (a.cache_tag_probe_again) {
                        a.cache_tag_probe_again = false;
                        enqueueCacheTagProbe(a);
                    }
                },
                .slack_workspace => if (result.ok) {
                    if (!applySlackWorkspace(a, result.account.slice(), result.data)) logSlackFailure(a, result.kind, "ParseFailed", result.http_status);
                    refreshVisibleChats(a);
                } else if (slackConfigured(a)) setStatus(a, "Unable to read Slack channels"),
                .slack_users => if (result.ok) {
                    if (!applySlackUsers(a, result.account.slice(), result.data)) logSlackFailure(a, result.kind, "ParseFailed", result.http_status);
                    refreshVisibleChats(a);
                },
                .slack_auth => if (result.ok) {
                    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, result.data, .{}) catch return 0;
                    defer parsed.deinit();
                    const root = switch (parsed.value) {
                        .object => |object| object,
                        else => return 0,
                    };
                    const identity = slack.installationIdentity(root) orelse return 0;
                    if (result.account.len == 0) {
                        if (std.mem.eql(u8, result.extra.slice(), "bridge")) {
                            if (slackInstallation(a, identity.team_id) != null or installSlackWorkspace(a, identity.team_id, identity.team_name, identity.user_id, "", "", 0, true)) bindSlackOutboxAccount(a, identity.team_id);
                        } else if (a.slack_tokens) |tokens| {
                            if (addSlackInstallation(identity.team_id, identity.team_name, identity.user_id, tokens.user, "", 0)) {
                                if (a.slack_bridge == null) bindSlackOutboxAccount(a, identity.team_id);
                                slack_win.deleteSecret(lit("SlackUserToken"));
                                a.slack_install_mutex.lockUncancelable(a.io);
                                a.allocator.free(tokens.user);
                                a.allocator.free(tokens.app);
                                a.slack_tokens = null;
                                a.slack_install_mutex.unlock(a.io);
                            }
                        }
                    }
                    const team = getString(root, "team");
                    var status_buffer: [96]u8 = undefined;
                    setStatus(a, std.fmt.bufPrint(&status_buffer, "Slack connected: {s}", .{if (team.len > 0) team else "workspace"}) catch "Slack connected");
                } else setStatus(a, "Slack tokens are not valid"),
                .slack_history => {
                    if (!result.ok) {
                        setStatus(a, "Unable to read Slack history");
                    } else if (result.gen == a.messages_gen and selectedChatIsSlack(a) and
                        chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(result)))
                    {
                        const hash = std.hash.Wyhash.hash(0, result.data);
                        const unchanged = hash == a.slack_history_hash and
                            chat_key.Key.eql(chat_key.displayed(a), chat_key.of(result));
                        if (!unchanged) {
                            applySlackHistory(a, result.data);
                            a.slack_history_hash = hash;
                        }
                    }
                },
                .slack_replies => {
                    if (result.ok and result.gen == a.messages_gen and selectedChatIsSlack(a) and
                        chat_key.Key.eql(chat_key.of(&a.chats[a.selected_chat]), chat_key.of(result)))
                    {
                        applySlackReplies(a, result.data, result.msg_id.slice());
                    }
                },
                .slack_send, .slack_attach, .slack_share => handleSlackSendResult(a, result),
                .slack_download => {
                    if (result.ok and chat_key.Key.eql(chat_key.displayed(a), chat_key.of(result))) {
                        const ts = result.msg_id.slice();
                        for (a.messages[0..a.message_count]) |*stored| {
                            if (std.mem.eql(u8, stored.id.slice(), ts)) {
                                stored.local_path.set(a.allocator, result.data);
                                if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
                                break;
                            }
                        }
                    }
                },
                .slack_mark => {
                    if (result.ok) if (slackChatById(a, result.account.slice(), result.jid.slice())) |chat| {
                        chat.slack_last_read.set(slack.newerMarkTs(chat.slack_last_read.slice(), result.msg_id.slice()));
                    };
                    if (!result.ok and result.gen == a.slack_mark_gen and
                        std.mem.eql(u8, result.account.slice(), a.slack_mark_account.slice()) and
                        std.mem.eql(u8, result.jid.slice(), a.slack_mark_channel.slice()) and
                        std.mem.eql(u8, result.msg_id.slice(), a.slack_mark_ts.slice())) cancelSlackMark(a);
                },
            }
            return 0;
        },
        wm_slack_oauth_done => {
            const task = a.slack_oauth_task orelse return 0;
            if (task.socket_stopped) {
                a.slack_socket_thread = null;
                const token = a.allocator.dupe(u8, task.app_token) catch null;
                if (token) |value| {
                    a.allocator.free(a.slack_app_token);
                    a.slack_app_token = value;
                }
                startSlackSocket(a);
            }
            if (task.response) |response| {
                if (addSlackInstallation(response.team_id, response.team_name, response.user_id, response.access_token, response.refresh_token, if (response.expires_in == 0) 0 else nowUnixSeconds() + @as(i64, @intCast(response.expires_in)))) {
                    task.saved.store(true, .release);
                    setStatus(a, "Slack workspace connected");
                } else setStatus(a, "Could not save Slack workspace; try connecting again");
            } else {
                var buffer: [256]u8 = undefined;
                const detail = if (std.mem.eql(u8, task.failure, "CallbackPortBusy")) "port 53682 is busy; close the other listener and try again" else if (std.mem.eql(u8, task.failure, "CallbackTimedOut")) "browser authorization timed out after 5 minutes" else task.failure;
                setStatus(a, std.fmt.bufPrint(&buffer, "Slack sign-in failed: {s}", .{detail}) catch "Slack sign-in failed");
            }
            _ = win.SetEvent(task.applied);
            return 0;
        },
        wm_slack_oauth_finished => {
            finishSlackSignIn(a);
            return 0;
        },
        wm_slack_event => {
            const event: *slack_win.Event = @ptrFromInt(@as(usize, @bitCast(lparam)));
            _ = a.slack_event_pending.fetchSub(1, .acq_rel);
            applySlackEvent(a, event);
            return 0;
        },
        wm_slack_reload => {
            a.slack_install_mutex.lockUncancelable(a.io);
            if (a.slack_tokens) |tokens| {
                a.allocator.free(tokens.user);
                a.allocator.free(tokens.app);
                a.slack_tokens = null;
            }
            a.slack_install_mutex.unlock(a.io);
            if (!unifiedHub(a)) loadSlackTokens(a);
            refreshSlackWorkspace(a);
            startSlackSocket(a);
            return 0;
        },
        wm_unfurl_done => {
            const result: *UnfurlResult = @ptrFromInt(@as(usize, @bitCast(lparam)));
            applyUnfurlResult(a, result);
            return 0;
        },
        wm_startup_probe => {
            applyStartupProbe(a, wparam, @bitCast(lparam));
            return 0;
        },
        wm_control => {
            controlOnUi(a, @ptrFromInt(@as(usize, @bitCast(lparam))));
            return 0;
        },
        win.WM_DROPFILES => {
            stageDroppedFiles(a, @ptrFromInt(wparam));
            return 0;
        },
        win.WM_POWERBROADCAST => {
            if (wparam == win.PBT_APMRESUMEAUTOMATIC) startUpdateCheck(hwnd, false);
            return 1;
        },
        win.WM_ACTIVATE => {
            if (loword(wparam) != win.WA_INACTIVE) {
                startUpdateCheck(hwnd, false);
                focusCompose(a);
            } else shortcodeHide(a);
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_ACTIVATEAPP => {
            if (wparam != 0) focusCompose(a);
            return win.DefWindowProcW(hwnd, message, wparam, lparam);
        },
        win.WM_SETFOCUS => {
            focusCompose(a);
            return 0;
        },
        win.WM_CREATE => {
            a.hwnd = hwnd;
            const window_dpi = win.GetDpiForWindow(hwnd);
            a.dpi = if (window_dpi == 0) 96 else window_dpi;
            if (!recreateThemeBrushes(a)) return -1;
            a.search = directwrite_edit.create(a.instance, hwnd, controlId(id_search), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.ES_AUTOHSCROLL, 0, 0, 0, 0);
            if (a.search == null) return -1;
            directwrite_edit.setCentered(a.search.?, true);
            a.chats_hwnd = win.CreateWindowExW(0, lit("LISTBOX"), null, win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.LBS_NOTIFY | win.LBS_OWNERDRAWFIXED | win.LBS_NOINTEGRALHEIGHT, 0, 0, 0, 0, hwnd, controlId(id_chats), a.instance, null);
            if (a.chats_hwnd) |list| a.chats_prev_proc = @bitCast(win.SetWindowLongPtrW(list, win.GWLP_WNDPROC, @intCast(@intFromPtr(&chatsProc))));
            a.canvas = win.CreateWindowExW(0, lit("WacliMessageCanvas"), null, win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP, 0, 0, 0, 0, hwnd, controlId(id_canvas), a.instance, null);
