                refreshMessages(a);
            } else if (wparam == timer_slack_mark) {
                _ = win.KillTimer(hwnd, timer_slack_mark);
                fireSlackMark(a);
            } else if (wparam == timer_update_first_check) {
                _ = win.KillTimer(hwnd, timer_update_first_check);
                removeLeftoverOldExe();
                startUpdateCheck(hwnd, false);
            } else if (wparam == timer_update_check) {
                startUpdateCheck(hwnd, false);
            } else if (wparam == timer_update_card) {
                if (updateCardVisible(a)) {
                    var card_rc = updateCardRect(a);
                    _ = win.InvalidateRect(hwnd, &card_rc, win.FALSE);
                }
                if (!a.update_card_busy and !a.update_install_running.load(.acquire)) _ = win.KillTimer(hwnd, timer_update_card);
            } else if (wparam == timer_update_restart) {
                const composing = if (a.compose) |compose| win.GetWindowTextLengthW(compose) > 0 else false;
                if (composing or a.pending_send_count > 0 or a.send_child != null) {
                    setStatus(a, if (composing) "Update installed - restarting when you finish typing" else "Update installed - restarting after the message is sent");
                    _ = win.SetTimer(hwnd, timer_update_restart, update_restart_delay_ms, null);
                } else {
                    relaunchIntoUpdate(a);
                }
            }
            return 0;
        },
        win.WM_CTLCOLORSTATIC, win.WM_CTLCOLOREDIT, win.WM_CTLCOLORLISTBOX => {
            const hdc: win.HDC = winHandle(win.HDC, wparam);
            _ = win.SetTextColor(hdc, theme.current.on_surface);
            _ = win.SetBkColor(hdc, fieldColor());
            const control_value: usize = @bitCast(lparam);
            for ([_]?win.HWND{ a.thread_list, a.thread_compose }) |control| {
                if (control != null and control_value == @intFromPtr(control.?)) {
                    _ = win.SetBkColor(hdc, theme.current.surface_container_high);
                    return @bitCast(@intFromPtr(a.brush_raised.?));
                }
            }
            for ([_]?win.HWND{ a.compose, a.search }) |control| {
                if (control != null and control_value == @intFromPtr(control.?)) {
                    _ = win.SetBkColor(hdc, theme.current.surface_container_high);
                    return @bitCast(@intFromPtr(a.brush_raised.?));
                }
            }
            if (a.status) |status| {
                if (control_value == @intFromPtr(status)) {
                    _ = win.SetBkColor(hdc, theme.current.surface_container_low);
                    return @bitCast(@intFromPtr(a.brush_panel.?));
                }
            }
            return @bitCast(@intFromPtr(if (theme.choice == .amoled) a.brush_bg.? else a.brush_raised.?));
        },
        win.WM_CLOSE => {
            saveWindowRect(hwnd);
            saveComposerDraft(a);
            persistDrafts(a);
            _ = win.DestroyWindow(hwnd);
            return 0;
        },
        win.WM_DESTROY => {
            a.hub_stop.store(true, .release);
            a.hub_cancel.stop();
            if (a.hub_thread) |thread| thread.join();
            a.hub_thread = null;
            a.slack_oauth_stop.store(true, .release);
            if (a.slack_oauth_task) |task| _ = win.SetEvent(task.applied);
            finishSlackSignIn(a);
            persistDrafts(a);
            a.draft_store.deinit(a.allocator);
            a.thread_rows.deinit(a.allocator);
            wacliShutdown(a);
            closePlayer(a);
            closeImageViewer(a);
            _ = win.KillTimer(hwnd, timer_refresh);
            _ = win.KillTimer(hwnd, timer_search);
            _ = win.KillTimer(hwnd, timer_animation);
            _ = win.KillTimer(hwnd, timer_chat_select);
            for (&a.media_downloads) |*slot| {
                if (slot.child) |*child| child.kill(a.io);
                slot.child = null;
            }
            if (a.send_child) |*child| child.kill(a.io);
            a.send_child = null;
            if (a.archive_child) |*child| child.kill(a.io);
            a.archive_child = null;
            if (a.read_child) |*child| child.kill(a.io);
            a.read_child = null;
            if (!a.read_queue_dead) persistPendingReads(a);
            persistReadState(a);
            a.slack_stop.store(true, .release);
            stopSync(a, "shutdown");
            if (a.sync_job) |job| _ = win.CloseHandle(job);
            a.sync_job = null;
            if (a.audio_player) |player| {
                player.destroy();
                a.audio_player = null;
            }
            if (a.dictation_session) |session| {
                session.destroy();
                a.dictation_session = null;
            }
            if (a.voice_session) |session| {
                session.destroy();
                a.voice_session = null;
            }
            if (a.avatar_session) |session| {
                session.destroy();
                a.avatar_session = null;
            }
            if (a.transcribe_session) |session| {
                session.destroy();
                a.transcribe_session = null;
            }
            if (a.openrouter_session) |session| {
                session.destroy();
                a.openrouter_session = null;
            }
            for (a.avatars[0..a.avatar_count]) |*entry| {
                if (entry.bitmap) |bitmap| _ = win.DeleteObject(bitmap);
            }
            for (a.participant_avatars[0..a.participant_avatar_count]) |*entry| {
                if (entry.bitmap) |bitmap| _ = win.DeleteObject(bitmap);
            }
            for (a.custom_emoji.items) |*entry| {
                if (entry.bitmap) |bitmap| _ = win.DeleteObject(bitmap);
            }
            a.custom_emoji.deinit(a.allocator);
            a.audio_state = .empty;
            clearMessages(a);
            if (a.font) |font| _ = win.DeleteObject(font);
            if (a.font_small) |font| _ = win.DeleteObject(font);
            if (a.font_bold) |font| _ = win.DeleteObject(font);
            if (a.font_underline) |font| _ = win.DeleteObject(font);
            if (a.brush_bg) |brush| _ = win.DeleteObject(brush);
            if (a.brush_panel) |brush| _ = win.DeleteObject(brush);
            if (a.brush_raised) |brush| _ = win.DeleteObject(brush);
            if (a.brush_muted) |brush| _ = win.DeleteObject(brush);
            win.PostQuitMessage(0);
            return 0;
        },
        else => return win.DefWindowProcW(hwnd, message, wparam, lparam),
    }
}

fn playSelectedAudio(a: *App) void {
    if (a.selected_message) |selected| {
        if (selected < a.message_count) {
            const audio_item = &a.messages[selected];
            if (isAudio(audio_item)) {
                if (std.mem.eql(u8, a.audio_playing_id.slice(), audio_item.id.slice()) and a.audio_state != .empty) {
                    toggleAudio(a, audio_item);
                } else if (audio_item.local_path.len > 0) {
                    startAudioPlayback(a, audio_item);
                } else {
                    _ = downloadMedia(a, selected, false);
                }
                return;
            }
        }
    }
    setStatus(a, "Select a voice message with Alt+J/K first");
}

fn toggleSelectedTranscript(a: *App) void {
    if (a.selected_message) |selected| {
        if (selected < a.message_count) {
            const transcript_item = &a.messages[selected];
            if (transcript_item.transcript.len > 0) {
                transcript_item.transcript_expanded = !transcript_item.transcript_expanded;
                scrollToSelectedMessage(a);
                if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
                return;
            }
        }
    }
    setStatus(a, "Select a voice message with Alt+J/K first");
}

fn restoreComposeCaret(a: *App) void {
    const compose = a.compose orelse return;
    if (win.GetFocus() != compose) return;
    var start: usize = 0;
    var end: usize = 0;
    _ = win.SendMessageW(compose, win.EM_GETSEL, @intFromPtr(&start), @bitCast(@intFromPtr(&end)));
    _ = win.SendMessageW(compose, win.WM_KILLFOCUS, 0, 0);
    _ = win.SendMessageW(compose, win.WM_SETFOCUS, 0, 0);
    _ = win.SendMessageW(compose, win.EM_SETSEL, @bitCast(start), @bitCast(end));
}

fn deleteWordBeforeCaret(edit: win.HWND) void {
    var start: usize = 0;
    var end: usize = 0;
    _ = win.SendMessageW(edit, win.EM_GETSEL, @intFromPtr(&start), @bitCast(@intFromPtr(&end)));
    if (start != end) {
        _ = win.SendMessageW(edit, win.EM_REPLACESEL, win.TRUE, @bitCast(@intFromPtr(lit(""))));
        return;
    }
    if (start == 0) return;
    var wide_buffer: [drafts.max_text + 1]u16 = undefined;
    const length: usize = @intCast(win.GetWindowTextW(edit, &wide_buffer, wide_buffer.len));
    if (start > length) return;
    const word_start = edit_contract.wordStart(wide_buffer[0..length], start);
    _ = win.SendMessageW(edit, win.EM_SETSEL, @bitCast(word_start), @bitCast(start));
    _ = win.SendMessageW(edit, win.EM_REPLACESEL, win.TRUE, @bitCast(@intFromPtr(lit(""))));
}

fn handleKeyboard(a: *App, message: *const win.MSG) bool {
    if (message.message != win.WM_KEYDOWN and message.message != win.WM_SYSKEYDOWN) return false;
    const key: u32 = @intCast(message.wParam);
    const focus = win.GetFocus();
    const control = win.GetKeyState(win.VK_CONTROL) < 0;
    const shift = win.GetKeyState(win.VK_SHIFT) < 0;
    const alt = win.GetKeyState(win.VK_MENU) < 0;
    if (directwrite_edit.isComposing(focus)) return false;
    if (a.palette != null and a.palette_views_mode and control and !alt and !shift and (key == win.VK_UP or key == win.VK_DOWN)) {
        moveView(a, key == win.VK_DOWN);
        return true;
    }
    if (alt and key == win.VK_MENU) return true;
    if (a.tg_login_window != null) return false;
    if (a.image_viewer_window != null) return false;
    if (a.shortcut_help != null) return false;
    if (a.voice_active and !a.voice_finishing and (key == win.VK_RETURN or key == win.VK_ESCAPE) and !alt and !control) {
        if (key == win.VK_ESCAPE) cancelVoice(a, "Voice note cancelled") else finishVoice(a);
        return true;
    }
    if (key == win.VK_F1) {
        openShortcutHelp(a);
        return true;
    }
    if (!control and !alt and !shift and (key == win.VK_UP or key == win.VK_DOWN)) {
        if (a.compose) |compose| {
            if (win.GetFocus() == compose and win.GetWindowTextLengthW(compose) == 0 and a.message_count > 0) {
                walkMessageHighlight(a, key);
                return true;
            }
        }
    }
    if (control and !alt and !shift and (key == win.VK_UP or key == win.VK_DOWN) and a.message_count > 0 and (a.thread_compose == null or focus != a.thread_compose.?)) {
        walkMessageHighlight(a, key);
        return true;
    }
    if (alt and !control and !shift and key == 'A') {
        runCommand(a, command_include_archived);
        return true;
    }
    if (alt and !control and !shift and key == 'I') {
        switchChatView(a, .all);
        return true;
    }
    if (alt and !control and !shift and key >= '0' and key <= '9') {
        if (key == '0') switchChatView(a, .all) else if (messenger_view.forNumber(key - '0', a.views.items)) |index| switchAccountView(a, a.views.items[index].key.key());
        return true;
    }
    if (control and !alt and key >= '1' and key <= '9') {
        const target: i32 = @intCast(key - '1');
        if (target < a.chat_count) {
            selectChat(a, target - @as(i32, @intCast(a.selected_chat)), false);
            focusCompose(a);
        }
        return true;
    }
    if (control and shift and !alt and (key == win.VK_HOME or key == win.VK_END)) {
        if (a.chat_count > 0) {
            const target: i32 = if (key == win.VK_HOME) 0 else @intCast(a.chat_count - 1);
            selectChat(a, target - @as(i32, @intCast(a.selected_chat)), false);
            focusCompose(a);
        }
        return true;
    }
    if (control and !shift and !alt and (key == win.VK_PRIOR or key == win.VK_NEXT)) {
        if (a.chats_hwnd) |list| {
            const info = listboxScrollInfo(list);
            selectChat(a, if (key == win.VK_PRIOR) -info.page else info.page, false);
            focusCompose(a);
        }
        return true;
    }
    if (a.canvas != null and !alt and (key == win.VK_PRIOR or key == win.VK_NEXT or
        (control and key == win.VK_END)))
    {
        if (a.canvas) |canvas| {
            var client: win.RECT = undefined;
            _ = win.GetClientRect(canvas, &client);
            const page = @max(px(a, 60), client.bottom - client.top - px(a, 60));
            const step: i32 = switch (key) {
                win.VK_PRIOR => page,
                win.VK_NEXT => -page,
                else => -a.scroll_y,
            };
            a.scroll_y = std.math.clamp(a.scroll_y + step, 0, a.max_scroll);
            _ = win.InvalidateRect(canvas, null, win.FALSE);
            if (key == win.VK_PRIOR and a.scroll_y >= a.max_scroll) requestHubOlder(a);
        }
        return true;
    }
    if (control and key == 'F') {
        if (a.search) |search| {
            _ = win.SetFocus(search);
            _ = win.SendMessageW(search, win.EM_SETSEL, 0, @bitCast(@as(isize, -1)));
        }
        return true;
    }
    if (control and !alt and !shift and key == 'A') {
        const in_compose = a.compose != null and focus == a.compose.?;
        const compose_empty = if (in_compose) win.GetWindowTextLengthW(a.compose.?) == 0 else false;
        if (shortcuts.ctrlASelectsChats(a.chats_hwnd != null and focus == a.chats_hwnd.?, in_compose, compose_empty)) {
            selectAllChats(a);
            return true;
        }
        const in_text_field = (a.compose != null and focus == a.compose.?) or
            (a.thread_compose != null and focus == a.thread_compose.?) or
            (a.search != null and focus == a.search.?) or
            (a.emoji_edit != null and focus == a.emoji_edit.?) or
            (a.palette_edit != null and focus == a.palette_edit.?);
        if (in_text_field) {
            _ = win.SendMessageW(focus.?, win.EM_SETSEL, 0, @bitCast(@as(isize, -1)));
            return true;
        }
    }
    if (control and !alt and key == win.VK_BACK) {
        const in_text_field = (a.compose != null and focus == a.compose.?) or
            (a.thread_compose != null and focus == a.thread_compose.?) or
            (a.search != null and focus == a.search.?) or
            (a.emoji_edit != null and focus == a.emoji_edit.?) or
            (a.palette_edit != null and focus == a.palette_edit.?);
        if (in_text_field) {
            deleteWordBeforeCaret(focus.?);
            return true;
        }
    }
    if (control and key == 'K') {
        openPalette(a);
        return true;
    }
    if (a.palette != null) {
        if (key == win.VK_DOWN) {
            paletteMove(a, 1);
            return true;
        }
        if (key == win.VK_UP) {
            paletteMove(a, -1);
            return true;
        }
        if (a.palette_links_mode and !control and !alt) {
            const filter_empty = if (a.palette_edit) |edit| win.GetWindowTextLengthW(edit) == 0 else true;
            if (filter_empty and key == 'J') {
                paletteMove(a, 1);
                return true;
            }
            if (filter_empty and key == 'K') {
                paletteMove(a, -1);
                return true;
            }
        }
        if (key == win.VK_RETURN) {
            paletteActivate(a);
            return true;
        }
        if (key == win.VK_ESCAPE) {
            closePalette(a);
            return true;
        }
        return false;
    }
    if (a.emoji_wnd != null) {
        if (key == win.VK_DOWN) {
            emojiMove(a, 0, 1);
            return true;
        }
        if (key == win.VK_UP) {
            emojiMove(a, 0, -1);
            return true;
        }
        if (key == win.VK_LEFT) {
            emojiMove(a, -1, 0);
            return true;
        }
        if (key == win.VK_RIGHT) {
            emojiMove(a, 1, 0);
            return true;
        }
        if (key == win.VK_RETURN) {
            emojiActivate(a);
            return true;
        }
        if (key == win.VK_ESCAPE) {
            closeEmojiPicker(a);
            return true;
        }
        return false;
    }
    if (a.thread_parent.len > 0 and !control and !alt) {
        if (key == win.VK_ESCAPE) {
            closeSlackThread(a);
            return true;
        }
        if (a.thread_compose != null and focus == a.thread_compose.? and key == win.VK_RETURN and !shift) {
            sendMessageFrom(a, true);
            return true;
        }
    }
    if (a.thread_compose != null and focus == a.thread_compose.?) return false;
    if (!control and !alt and !shift and key == win.VK_RETURN and a.thread_parent.len == 0 and slackThreadsEnabled(a)) {
        if (a.selected_message) |selected| {
            const empty = if (a.compose) |compose| win.GetWindowTextLengthW(compose) == 0 else true;
            if ((a.search == null or focus != a.search.?) and empty and selected < a.message_count) {
                openSlackThread(a, selected);
                return true;
            }
        }
    }
    if (!control and !alt and (key == win.VK_RETURN or key == 'R')) {
        if (a.selected_message) |selected| {
            if (selected < a.message_count and a.messages[selected].from_me and a.messages[selected].send_state == .failed) {
                const compose_empty = if (a.compose) |compose| win.GetWindowTextLengthW(compose) == 0 else true;
                const in_search = if (a.search) |search| focus == search else false;
                if (compose_empty and !in_search and resendFailedMessage(a, selected)) return true;
            }
        }
    }
    if (!control and !alt and key == win.VK_RETURN) {
        if (a.selected_message) |selected| {
            if (selected < a.message_count and isImage(&a.messages[selected])) {
                const compose_empty = if (a.compose) |compose| win.GetWindowTextLengthW(compose) == 0 else true;
                const in_search = if (a.search) |search| focus == search else false;
                if (compose_empty and a.staged_images.count == 0 and !in_search) {
                    openImageInViewerOrQueue(a, selected, &a.messages[selected]);
                    return true;
                }
            }
        }
    }
    if (key == win.VK_ESCAPE and clearBulkSelection(a)) {
        setStatus(a, "Selection cleared");
        return true;
    }
    if (key == win.VK_ESCAPE) {
        const focused = win.GetFocus();
        if (focused != null) {
            const root = win.GetAncestor(focused, win.GA_ROOT) orelse focused;
            var class_name: [32]u16 = [_]u16{0} ** 32;
            const class_len: usize = @intCast(win.GetClassNameW(root, &class_name, class_name.len));
            const is_palette = std.mem.eql(u16, class_name[0..class_len], std.mem.span(lit("MessagesPalette")));
            const is_emoji_picker = std.mem.eql(u16, class_name[0..class_len], std.mem.span(lit("MessagesEmojiPicker")));
            if (is_palette or is_emoji_picker) {
                _ = win.DestroyWindow(root);
                focusCompose(a);
                return true;
            }
        }
    }
    if (key == win.VK_ESCAPE and !control and !alt and a.chat_count == 0) {
        if (!clearSearch(a) and activeChatView(a) != .all) switchChatView(a, .all);
        focusCompose(a);
        return true;
    }
    if (control and (key == win.VK_OEM_MINUS or key == win.VK_SUBTRACT)) {
        runCommand(a, command_font_smaller);
        return true;
    }
    if (control and (key == win.VK_OEM_PLUS or key == win.VK_ADD)) {
        runCommand(a, command_font_larger);
        return true;
    }
    if (control and key == '0') {
        runCommand(a, command_font_reset);
        return true;
    }
    if (control and key == 'D') {
        runCommand(a, command_dictate);
        return true;
    }
    if (control and !alt and key == 'E') {
        if (shift) return false;
        if (!archiveShortcutAllowed(a, focus, message.lParam, true)) return false;
        archiveSelectedChat(a, false, .shortcut);
        return true;
    }
    if (control and shift and key == 'C') {
        copySelectedText(a);
        return true;
    }
    if (control and key == 'C') {
        const focus_control = win.GetFocus();
        const in_editor = (a.compose != null and focus_control == a.compose.?) or (a.search != null and focus_control == a.search.?);
        if (in_editor) {
            var selection_start: win.DWORD = 0;
            var selection_end: win.DWORD = 0;
            const start_result = win.SendMessageW(focus_control, win.EM_GETSEL, 0, 0);
            selection_start = @as(win.DWORD, @truncate(@as(usize, @bitCast(start_result)) & 0xffff));
            selection_end = @as(win.DWORD, @truncate((@as(usize, @bitCast(start_result)) >> 16) & 0xffff));
            if (selection_start != selection_end) return false;
        }
        copySelectedText(a);
        return true;
    }
    if (control and key == 'R') {
        openReactionPicker(a);
        return true;
    }
    if (control and key == 'P') {
        playSelectedAudio(a);
        return true;
    }
    if (control and key == 'T') {
        toggleSelectedTranscript(a);
        return true;
    }
    if (alt and (key == 'J' or key == 'K')) {
        selectMessage(a, if (key == 'J') 1 else -1);
        restoreComposeCaret(a);
        return true;
    }
    if (alt and key == 'G') {
        const now_ms = win.GetTickCount64();
        if (now_ms - a.last_alt_g_ms <= 900) {
            a.last_alt_g_ms = 0;
            jumpToLatestMessage(a);
            setStatus(a, "Jumped to latest message");
        } else {
            a.last_alt_g_ms = now_ms;
            setStatus(a, "Press Alt+G again to jump to the latest message");
        }
        restoreComposeCaret(a);
        return true;
    }
    if (control and key == 'O') {
        openLinkPalette(a);
        return true;
    }
    if (control and key == win.VK_TAB) {
        selectChat(a, if (shift) -1 else 1, true);
        focusCompose(a);
        return true;
    }
    if (control and shift and key == 'R') {
        startReply(a);
        return true;
    }
    if (a.compose) |compose| {
        if (focus == compose) {
            if (a.sc_count > 0 and !control and !alt) {
                switch (key) {
                    win.VK_UP, win.VK_DOWN => {
                        shortcodeMove(a, key == win.VK_DOWN);
                        return true;
                    },
                    win.VK_RETURN, win.VK_TAB => if (!shift and shortcodeAccept(a)) return true,
                    win.VK_ESCAPE => {
                        shortcodeHide(a);
                        return true;
                    },
                    win.VK_LEFT, win.VK_RIGHT, win.VK_HOME, win.VK_END => shortcodeHide(a),
                    else => {},
                }
            }
            if (handleComposerPaste(a, key, control, shift, alt)) return true;
            if (key == win.VK_RETURN and !shift) {
                sendMessage(a);
                return true;
            }
            if (key == win.VK_ESCAPE) {
                if (a.reply_to.len > 0) {
                    clearReply(a);
                    setStatus(a, "Reply cancelled");
                    return true;
                }
                if (a.staged_images.count > 0) {
                    discardStagedImage(a);
                    layout(a, a.compose_client_width, a.compose_client_height);
                    if (a.hwnd) |main_hwnd| _ = win.InvalidateRect(main_hwnd, null, win.FALSE);
                    setStatus(a, "Pasted image discarded");
                    return true;
                }
                _ = clearSearch(a);
                focusCompose(a);
                return true;
            }
            return false;
        }
    }
    if (a.search) |search| {
        if (focus == search) {
            if (key == win.VK_RETURN) {
                if (a.compose) |compose| _ = win.SetFocus(compose);
                return true;
            }
            if (key == win.VK_ESCAPE) {
                _ = clearSearch(a);
                focusCompose(a);
                return true;
            }
            return false;
        }
    }
    if (key == win.VK_RETURN or key == 'C') {
        if (a.compose) |compose| _ = win.SetFocus(compose);
        return true;
    }
    if (key == win.VK_OEM_2) {
        if (a.search) |search| {
            _ = win.SetFocus(search);
            _ = win.SendMessageW(search, win.EM_SETSEL, 0, @bitCast(@as(isize, -1)));
        }
        return true;
    }
    if (key == 'E') {
        if (control or alt or shift or !archiveShortcutAllowed(a, focus, message.lParam, false)) return false;
        archiveSelectedChat(a, false, .shortcut);
        return true;
    }
    if (key == 'U') {
        runCommand(a, command_unread);
        return true;
    }
    if (key == 'R') {
        runCommand(a, command_refresh);
        return true;
    }
    if (key == 'Q') {
        runCommand(a, command_quit);
        return true;
    }
    return false;
}

fn jumpToLatestMessage(a: *App) void {
    if (a.message_count == 0) return;
    a.selected_message = a.message_count - 1;
    a.scroll_y = 0;
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.FALSE);
}

fn hashStorePath(init: std.process.Init, allocator: std.mem.Allocator, filename: []const u8) []u8 {
    const local = init.environ_map.get("LOCALAPPDATA") orelse return &.{};
    const dir = std.fs.path.join(allocator, &.{ local, "Messages" }) catch return &.{};
    const cwd = std.Io.Dir.cwd();
    cwd.createDirPath(init.io, dir) catch {};
    const path = std.fs.path.join(allocator, &.{ dir, filename }) catch {
        allocator.free(dir);
        return &.{};
    };
    allocator.free(dir);
    return path;
}

fn findPlayedPath(init: std.process.Init, allocator: std.mem.Allocator) []u8 {
    return hashStorePath(init, allocator, "played.txt");
}

fn loadHashSet(a: *App, path: []const u8, set: *played.Set) void {
    if (path.len == 0) return;
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path) catch return;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.GENERIC_READ, win.FILE_SHARE_READ, null, win.OPEN_EXISTING, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var size: win.LARGE_INTEGER = undefined;
    if (win.GetFileSizeEx(handle, &size) == 0 or size.QuadPart <= 0) return;
    const capped: i64 = @min(size.QuadPart, 128 * 1024);
    const distance: win.LARGE_INTEGER = .{ .QuadPart = -capped };
    if (win.SetFilePointerEx(handle, distance, null, win.FILE_END) == 0) return;
    const buffer = a.allocator.alloc(u8, @intCast(capped)) catch return;
    defer a.allocator.free(buffer);
    var total: usize = 0;
    while (total < buffer.len) {
        var got: win.DWORD = 0;
        if (win.ReadFile(handle, buffer[total..].ptr, @intCast(buffer.len - total), &got, null) == 0) break;
        if (got == 0) break;
        total += got;
    }
    set.load(buffer[0..total]);
}

fn appendHashLine(a: *App, path: []const u8, line: []const u8) void {
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path) catch return;
    defer a.allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.FILE_APPEND_DATA, win.FILE_SHARE_READ, null, win.OPEN_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var written: win.DWORD = 0;
    _ = win.WriteFile(handle, line.ptr, @intCast(line.len), &written, null);
}

const launch_log_max_bytes: i64 = 64 * 1024;

fn launchLogShouldRotate(size: i64) bool {
    return size > launch_log_max_bytes;
}

fn appendLaunchLog(a: *App, event: []const u8) void {
    a.launch_log_mutex.lockUncancelable(a.io);
    defer a.launch_log_mutex.unlock(a.io);
    const path = messagesDirPath(a, "launch-log.txt") orelse return;
    defer a.allocator.free(path);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, path) catch return;
    defer a.allocator.free(wide);
    const read_handle = win.CreateFileW(wide.ptr, win.GENERIC_READ, win.FILE_SHARE_READ | win.FILE_SHARE_WRITE, null, win.OPEN_EXISTING, win.FILE_ATTRIBUTE_NORMAL, null);
    var size: i64 = 0;
    if (read_handle != win.INVALID_HANDLE_VALUE and read_handle != null) {
        var large: win.LARGE_INTEGER = undefined;
        if (win.GetFileSizeEx(read_handle, &large) != 0) size = large.QuadPart;
        _ = win.CloseHandle(read_handle);
    }
    if (launchLogShouldRotate(size)) {
        const old_path = messagesDirPath(a, "launch-log.old.txt") orelse return;
        defer a.allocator.free(old_path);
        const old_wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, old_path) catch return;
        defer a.allocator.free(old_wide);
        _ = win.MoveFileExW(wide.ptr, old_wide.ptr, win.MOVEFILE_REPLACE_EXISTING);
    }
    const handle = win.CreateFileW(wide.ptr, win.FILE_APPEND_DATA, win.FILE_SHARE_READ | win.FILE_SHARE_WRITE, null, win.OPEN_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var line_buffer: [512]u8 = undefined;
    const line = std.fmt.bufPrint(&line_buffer, "{d} {s}\n", .{ nowUnixSeconds(), event }) catch return;
    var written: win.DWORD = 0;
    _ = win.WriteFile(handle, line.ptr, @intCast(line.len), &written, null);
}

fn loadPlayed(a: *App) void {
    loadHashSet(a, a.played_path, &a.played_set);
    loadVoicePos(a);
    mic_choice.load();
    loadSentVoice(a);
}

const crash_message_id_max = 48;
var crash_message_id: [crash_message_id_max]u8 = undefined;
var crash_message_id_len: usize = 0;

fn setPaintingMessageId(id: []const u8) void {
    const count = @min(id.len, crash_message_id_max);
    for (id[0..count], 0..) |byte, index| {
        crash_message_id[index] = if (byte >= 0x20 and byte < 0x7F) byte else '?';
    }
    @atomicStore(usize, &crash_message_id_len, count, .release);
}

fn clearPaintingMessageId() void {
    @atomicStore(usize, &crash_message_id_len, 0, .release);
}

fn appendCrashLog(line: []const u8) void {
    var path: [280]u16 = undefined;
    const local_label = std.unicode.utf8ToUtf16LeStringLiteral("LOCALAPPDATA");
    const local_len: usize = @intCast(win.GetEnvironmentVariableW(local_label, &path, path.len - 40));
    if (local_len == 0 or local_len >= path.len - 40) return;
    const suffix = std.unicode.utf8ToUtf16LeStringLiteral("\\Wazig\\crash.log");
    const crash_log_dir_units = suffix.len - "crash.log".len;
    @memcpy(path[local_len..][0..suffix.len], suffix);
    const total = local_len + suffix.len;
    path[total] = 0;
    const after_dir = path[local_len + crash_log_dir_units];
    path[local_len + crash_log_dir_units] = 0;
    _ = win.CreateDirectoryW(path[0 .. local_len + crash_log_dir_units :0].ptr, null);
    path[local_len + crash_log_dir_units] = after_dir;
    const handle = win.CreateFileW(path[0..total :0].ptr, win.FILE_APPEND_DATA, win.FILE_SHARE_READ | win.FILE_SHARE_WRITE, null, win.OPEN_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var size: win.LARGE_INTEGER = undefined;
    if (win.GetFileSizeEx(handle, &size) != 0 and size.QuadPart > crash_log_max_bytes) {
        _ = win.SetFilePointer(handle, 0, null, win.FILE_BEGIN);
        _ = win.SetEndOfFile(handle);
    }
    var written: win.DWORD = 0;
    _ = win.WriteFile(handle, line.ptr, @intCast(line.len), &written, null);
}

const crash_log_max_bytes: i64 = 4 * 1024 * 1024;

fn crashLogModuleName(out: []u8, path_utf16: []const u16) usize {
    var start: usize = 0;
    for (path_utf16, 0..) |unit, index| {
        if (unit == '\\') start = index + 1;
    }
    var count: usize = 0;
    for (path_utf16[start..]) |unit| {
        if (count >= out.len) break;
        out[count] = if (unit >= 0x20 and unit < 0x7F) @intCast(unit) else '?';
        count += 1;
    }
    return count;
}

fn crashFilter(info: ?*win.EXCEPTION_POINTERS) callconv(.winapi) win.LONG {
    var code: win.ULONG = 0;
    var address: usize = 0;
    if (info) |pointers| {
        if (pointers.ExceptionRecord) |record| {
            code = record.*.ExceptionCode;
            address = @intFromPtr(record.*.ExceptionAddress);
        }
    }
    var line_buffer: [512]u8 = undefined;
    var clock = std.mem.zeroes(win.SYSTEMTIME);
    win.GetLocalTime(&clock);
    var module: win.HMODULE = null;
    var module_path: [260]u16 = undefined;
    var name_buffer: [64]u8 = undefined;
    var module_name: []const u8 = "";
    var offset: usize = 0;
    if (address != 0 and win.GetModuleHandleExW(
        win.GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | win.GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
        @ptrFromInt(address),
        &module,
    ) != 0) {
        const path_len: usize = @intCast(win.GetModuleFileNameW(module, &module_path, module_path.len));
        const name_len = crashLogModuleName(&name_buffer, module_path[0..path_len]);
        module_name = name_buffer[0..name_len];
        const base: usize = @intFromPtr(module);
        if (address >= base) offset = address - base;
    }
    var id_storage: [crash_message_id_max]u8 = undefined;
    const id_len = @min(@atomicLoad(usize, &crash_message_id_len, .acquire), crash_message_id_max);
    for (crash_message_id[0..id_len], 0..) |byte, index| {
        id_storage[index] = if (byte >= 0x20 and byte < 0x7F) byte else '?';
    }
    const line = std.fmt.bufPrint(&line_buffer, "{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2} v{s} unhandled exception code 0x{X:0>8} at 0x{X} ({s} + 0x{X}) message-id: {s}\r\n", .{
        clock.wYear,
        clock.wMonth,
        clock.wDay,
        clock.wHour,
        clock.wMinute,
        clock.wSecond,
        build_info.version,
        @as(u32, code),
        address,
        if (module_name.len > 0) module_name else "?",
        offset,
        if (id_len > 0) id_storage[0..id_len] else "none",
    }) catch return 0;
    appendCrashLog(line);
    return win.EXCEPTION_CONTINUE_SEARCH;
}

fn installCrashFilter() void {
    _ = win.SetUnhandledExceptionFilter(crashFilter);
}

fn markPlayed(a: *App, id: []const u8) void {
    if (a.played_path.len == 0) return;
    var line_buffer: [40]u8 = undefined;
    const line = a.played_set.mark(id, &line_buffer) orelse return;
    appendHashLine(a, a.played_path, line);
}

const cache_tag_timeout_ms: win.DWORD = 20000;

const ProbeKind = enum(u2) { failed = 0, unlinked = 1, linked = 2 };
const ProbeResult = struct { kind: ProbeKind, hash: u64 = 0, logged_out: bool = false };

fn probeAccount(gpa: std.mem.Allocator, io: std.Io, wacli_path: []const u8, scratch_dir: []const u8) ProbeResult {
    const failed = ProbeResult{ .kind = .failed };
    const out_path = std.fs.path.join(gpa, &.{ scratch_dir, "auth-status.tmp" }) catch return failed;
    defer gpa.free(out_path);
    const cwd = std.Io.Dir.cwd();
    var out_file = cwd.createFile(io, out_path, .{}) catch return failed;
    const child = child_process.spawn(io, .{
        .argv = &.{ wacli_path, "--json", "--read-only", "auth", "status" },
        .stdin = .ignore,
        .stdout = .{ .file = out_file },
        .stderr = .ignore,
        .create_no_window = true,
    }) catch {
        out_file.close(io);
        return failed;
    };
    out_file.close(io);
    const handle = child.id orelse return failed;
    defer _ = win.CloseHandle(handle);
    if (win.WaitForSingleObject(handle, cache_tag_timeout_ms) != win.WAIT_OBJECT_0) {
        _ = win.TerminateProcess(handle, 1);
        return failed;
    }
    var code: win.DWORD = 0;
    if (win.GetExitCodeProcess(handle, &code) == 0 or code != 0) return failed;
    const data = readFileWin(gpa, out_path, 64 * 1024) orelse return failed;
    defer gpa.free(data);
    deleteFileUtf8(out_path);
    var parsed = std.json.parseFromSlice(std.json.Value, gpa, data, .{}) catch return failed;
    defer parsed.deinit();
    const logged_out = auth_status.unauthenticated(parsed.value) == true;
    const jid = auth_status.linkedJid(parsed.value) orelse return .{ .kind = .unlinked, .logged_out = logged_out };
    if (jid.len == 0) return .{ .kind = .unlinked, .logged_out = logged_out };
    return .{ .kind = .linked, .hash = std.hash.Wyhash.hash(0, jid), .logged_out = logged_out };
}

const ProbeThread = struct { io: std.Io, hwnd: win.HWND, wacli_path: []const u8, scratch_dir: []const u8 };

fn startupProbeMain(ctx: *ProbeThread) void {
    defer std.heap.page_allocator.destroy(ctx);
    const result = probeAccount(std.heap.page_allocator, ctx.io, ctx.wacli_path, ctx.scratch_dir);
    const code: usize = @as(usize, @intFromEnum(result.kind)) | (if (result.logged_out) @as(usize, 4) else 0);
    _ = win.PostMessageW(ctx.hwnd, wm_startup_probe, code, @bitCast(result.hash));
}

const account_tag_file = "account-tag.txt";

fn isHexTag(text: []const u8) bool {
    if (text.len != 16) return false;
    for (text) |c| if (!std.ascii.isHex(c)) return false;
    return true;
}

fn loadPersistedTag(allocator: std.mem.Allocator, messages_dir: []const u8) ?[16]u8 {
    if (std.fs.path.join(allocator, &.{ messages_dir, account_tag_file })) |path| {
        defer allocator.free(path);
        if (readFileWin(allocator, path, 64)) |data| {
            defer allocator.free(data);
            const text = std.mem.trim(u8, data, " \r\n\t");
            if (isHexTag(text)) return text[0..16].*;
        }
    } else |_| {}
    const pattern = std.fs.path.join(allocator, &.{ messages_dir, "chats-*.json" }) catch return null;
    defer allocator.free(pattern);
    const wide = std.unicode.utf8ToUtf16LeAllocZ(allocator, pattern) catch return null;
    defer allocator.free(wide);
    var find: win.WIN32_FIND_DATAW = undefined;
    const handle = win.FindFirstFileW(wide.ptr, &find);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return null;
    defer _ = win.FindClose(handle);
    var found: ?[16]u8 = null;
    while (true) {
        const name_len = std.mem.indexOfScalar(u16, &find.cFileName, 0) orelse find.cFileName.len;
        var name_buffer: [64]u8 = undefined;
        if (name_len <= name_buffer.len) {
            for (find.cFileName[0..name_len], 0..) |wide_char, index| name_buffer[index] = if (wide_char < 128) @intCast(wide_char) else '?';
            const name = name_buffer[0..name_len];
            if (name.len == 27 and std.mem.startsWith(u8, name, "chats-") and std.mem.endsWith(u8, name, ".json") and isHexTag(name[6..22])) {
                if (found != null) return null;
                found = name[6..22].*;
            }
        }
        if (win.FindNextFileW(handle, &find) == 0) break;
    }
    return found;
}

fn persistTag(a: *App, tag: []const u8) void {
    const path = messagesDirPath(a, account_tag_file) orelse return;
    defer a.allocator.free(path);
    if (tag.len == 0) return deleteFileUtf8(path);
    _ = writeCacheFileAtomic(a, path, tag);
}

fn applyStartupProbe(a: *App, code: usize, hash: u64) void {
    a.startup_probe_pending = false;
    const kind: ProbeKind = @enumFromInt(@as(u2, @truncate(code)));
    const logged_out = code & 4 != 0;
    var label_buffer: [48]u8 = undefined;
    logStartupMilestone(a, .auth, std.fmt.bufPrint(&label_buffer, "auth status done ({s})", .{@tagName(kind)}) catch "auth status done");
    if (kind == .failed) {
        appendLaunchLog(a, "startup: auth status failed, keeping saved account tag");
        if (messenger_view.includes(activeChatView(a), .whatsapp)) {
            refreshChats(a);
            refreshMessages(a);
        }
        return;
    }
    var tag_buffer: [16]u8 = undefined;
    const new_tag: []const u8 = if (kind == .linked) (std.fmt.bufPrint(&tag_buffer, "{x:0>16}", .{hash}) catch "") else "";
    const changed = !std.mem.eql(u8, a.cache_tag.slice(), new_tag);
    if (changed) {
        if (a.chats_raw) |raw| a.allocator.free(raw);
        a.chats_raw = null;
    }
    a.cache_tag.set(new_tag);
    bindOutboxAccount(a);
    persistTag(a, new_tag);
    if (kind == .unlinked) appendLaunchLog(a, "startup: no account tag (WhatsApp unlinked)");
    if (logged_out and !a.sync_logged_out) {
        appendLaunchLog(a, "startup: WhatsApp logged out, live sync halted");
        markWhatsAppLoggedOut(a);
    }
    if (changed and messenger_view.includes(activeChatView(a), .whatsapp)) {
        appendLaunchLog(a, "startup: account changed, reloading caches");
        _ = applyChats(a, "{\"data\":[]}", false);
        loadChatsCache(a);
    }
    if (messenger_view.includes(activeChatView(a), .whatsapp)) {
        refreshChats(a);
        refreshMessages(a);
    }
}

