}

var verification_fixture = false;
var verification_text_comparison = false;

fn saveVerificationTextMetrics(a: *App, hdc: win.HDC, message: *const Message, x: i32, y: i32, width: i32, height: i32) void {
    const path = std.fs.path.join(a.allocator, &.{ std.fs.path.dirname(a.avatar_dir) orelse return, "text-metrics.json" }) catch return;
    defer a.allocator.free(path);
    const text = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch return;
    defer a.allocator.free(text);
    var origin = win.POINT{ .x = x, .y = y };
    const canvas_hwnd = a.canvas orelse return;
    _ = win.ClientToScreen(canvas_hwnd, &origin);
    var canvas: win.RECT = undefined;
    _ = win.GetClientRect(canvas_hwnd, &canvas);
    const dpi: i32 = @intCast(a.dpi);
    const data = std.json.Stringify.valueAlloc(a.allocator, .{
        .text = text,
        .dpi = dpi,
        .scale = a.font_scale,
        .directwrite = text_draw.directwrite,
        .body = .{ .px = -scaledFontHeight(17, a.font_scale, dpi), .weight = @import("font_config.zig").body_weight, .line_height = textLineHeight(hdc, a.font.?) },
        .heading = .{ .px = -scaledFontHeight(16, a.font_scale, dpi), .weight = win.FW_SEMIBOLD, .line_height = textLineHeight(hdc, a.font_bold.?) },
        .canvas = .{ .width = canvas.right, .height = canvas.bottom },
        .paragraph = .{ .x = origin.x, .y = origin.y, .width = width, .height = height },
        .foreground = theme.current.on_surface,
        .background = theme.current.surface_container_high,
        .surface = theme.current.surface,
    }, .{}) catch return;
    defer a.allocator.free(data);
    _ = writeCacheFileAtomic(a, path, data);
}

fn verificationEnqueue(a: *App, job: WacliJob) bool {
    if (job.kind != .chats and job.kind != .messages and job.kind != .unread_probe) return false;
    const data = verificationProvider(a, if (job.kind == .chats) .chats else .messages, job.jid.slice()) orelse return false;
    const result = a.allocator.create(WacliResult) catch {
        a.allocator.free(data);
        return false;
    };
    result.* = .{ .kind = job.kind, .provider = job.provider, .account = job.account, .gen = job.gen, .jid = job.jid, .msg_id = job.msg_id, .extra = job.extra, .data = data, .ok = true };
    a.wacli_mutex.lockUncancelable(a.io);
    a.wacli_pending[@intFromEnum(job.kind)] += 1;
    a.wacli_mutex.unlock(a.io);
    wacliPost(a, result);
    return true;
}

fn verificationProvider(a: *App, operation: enum { chats, messages, archive, unarchive }, jid: []const u8) ?[]u8 {
    if (!verification_fixture) return null;
    const path = messagesDirPath(a, "verification-provider.json") orelse return null;
    defer a.allocator.free(path);
    const raw = readFileWin(a.allocator, path, msg_cache_max_bytes) orelse return null;
    defer a.allocator.free(raw);
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, raw, .{}) catch return null;
    defer parsed.deinit();
    const root = switch (parsed.value) {
        .object => |object| object,
        else => return null,
    };
    const rows = switch (root.get("data") orelse return null) {
        .array => |array| array.items,
        else => return null,
    };
    var out: std.Io.Writer.Allocating = .init(a.allocator);
    defer out.deinit();
    switch (operation) {
        .chats => {
            out.writer.writeAll("{\"data\":[") catch return null;
            var count: usize = 0;
            for (rows) |row| {
                const object = switch (row) {
                    .object => |object| object,
                    else => continue,
                };
                if ((a.show_archived or !a.include_archived) and getBool(object, "archived") != a.show_archived) continue;
                if (count > 0) out.writer.writeByte(',') catch return null;
                std.json.Stringify.value(row, .{}, &out.writer) catch return null;
                count += 1;
            }
            out.writer.writeAll("]}") catch return null;
        },
        .messages => {
            const messages = switch (root.get("messages") orelse return null) {
                .object => |object| object,
                else => return null,
            };
            const payload = messages.get(jid) orelse return a.allocator.dupe(u8, "{\"data\":{\"messages\":[]}}") catch null;
            std.json.Stringify.value(payload, .{}, &out.writer) catch return null;
        },
        .archive, .unarchive => {
            var found = false;
            for (rows) |row| {
                const object = switch (row) {
                    .object => |object| object,
                    else => continue,
                };
                if (!std.mem.eql(u8, getString(object, "jid"), jid)) continue;
                const archived = object.getPtr("archived") orelse return null;
                archived.* = .{ .bool = operation == .archive };
                found = true;
            }
            if (!found) return null;
            std.json.Stringify.value(parsed.value, .{}, &out.writer) catch return null;
            if (!writeCacheFileAtomic(a, path, out.written())) return null;
        },
    }
    return a.allocator.dupe(u8, out.written()) catch null;
}

fn prepareVerification(init: std.process.Init) !win.HKEY {
    if (!std.mem.eql(u8, init.environ_map.get("GITHUB_ACTIONS") orelse "", "true")) return error.VerificationRequiresActions;
    const root = init.environ_map.get("WAZIG_VERIFY_ROOT") orelse return error.MissingVerificationRoot;
    const local = try std.fs.path.join(init.gpa, &.{ root, "local" });
    defer init.gpa.free(local);
    const profile = try std.fs.path.join(init.gpa, &.{ root, "profile" });
    defer init.gpa.free(profile);
    if (!std.mem.eql(u8, local, init.environ_map.get("LOCALAPPDATA") orelse "") or
        !std.mem.eql(u8, profile, init.environ_map.get("USERPROFILE") orelse "")) return error.VerificationRequiresIsolatedPaths;
    const id = init.environ_map.get("WAZIG_VERIFY_ID") orelse return error.MissingVerificationId;
    if (id.len != 36) return error.InvalidVerificationId;
    for (id) |c| if (!std.ascii.isHex(c) and c != '-') return error.InvalidVerificationId;
    const path = try std.fmt.allocPrint(init.gpa, "Software\\MessagesVerification\\{s}", .{id});
    defer init.gpa.free(path);
    const wide = try std.unicode.utf8ToUtf16LeAllocZ(init.gpa, path);
    defer init.gpa.free(wide);
    var key: win.HKEY = null;
    var disposition: win.DWORD = 0;
    if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), wide.ptr, 0, null, 0, win.KEY_ALL_ACCESS, null, &key, &disposition) != win.ERROR_SUCCESS) return error.VerificationRegistryFailed;
    errdefer _ = win.RegCloseKey(key);
    if (disposition != win.REG_CREATED_NEW_KEY and !std.mem.eql(u8, init.environ_map.get("WAZIG_VERIFY_RESTART") orelse "", id)) return error.VerificationRegistryAlreadyExists;
    if (win.RegOverridePredefKey(winHandle(win.HKEY, @bitCast(@as(isize, -2147483647))), key) != win.ERROR_SUCCESS) return error.VerificationRegistryOverrideFailed;
    return key;
}

pub fn main(init: std.process.Init) !void {
    process_start_ms = win.GetTickCount64();
    var update_relaunch = false;
    var argument_iterator = try init.minimal.args.iterateAllocator(init.gpa);
    defer argument_iterator.deinit();
    while (argument_iterator.next()) |argument| {
        if (std.mem.eql(u8, argument, "--update-relaunch")) update_relaunch = true;
        if (std.mem.eql(u8, argument, "--verify-fixture")) verification_fixture = true;
        if (std.mem.eql(u8, argument, "--verify-text-comparison")) verification_text_comparison = true;
        if (std.mem.eql(u8, argument, "--tdlib-smoke")) {
            if (!tg.enabled) std.process.exit(2);
            std.process.exit(tdlibSmoke(init.io));
        }
        if (std.mem.eql(u8, argument, "--unfurl-smoke")) {
            std.process.exit(unfurlSmoke(init));
        }
    }
    const verification_key = if (verification_fixture) try prepareVerification(init) else null;
    defer if (verification_key) |key| {
        _ = win.RegOverridePredefKey(winHandle(win.HKEY, @bitCast(@as(isize, -2147483647))), null);
        _ = win.RegCloseKey(key);
    };
    const instance = win.GetModuleHandleW(null) orelse return error.NoModuleHandle;
    installCrashFilter();
    const outbox_store = init.environ_map.get("LOCALAPPDATA") orelse return error.MissingLocalAppData;
    var mutex_name_buffer: [80]u8 = undefined;
    const mutex_name = try std.fmt.bufPrint(&mutex_name_buffer, "Global\\MessagesOutbox-{x}", .{std.hash.Wyhash.hash(0, outbox_store)});
    const mutex_wide = try std.unicode.utf8ToUtf16LeAllocZ(init.gpa, mutex_name);
    defer init.gpa.free(mutex_wide);
    const outbox_mutex = win.CreateMutexW(null, win.FALSE, mutex_wide.ptr) orelse return error.OutboxMutexFailed;
    defer _ = win.CloseHandle(outbox_mutex);
    const outbox_wait = win.WaitForSingleObject(outbox_mutex, if (update_relaunch) 10_000 else 0);
    if (outbox_wait != win.WAIT_OBJECT_0 and outbox_wait != win.WAIT_ABANDONED) {
        _ = win.MessageBoxW(null, lit("Messages is already running. Close that window before starting another instance."), lit("Messages"), win.MB_OK);
        return;
    }
    defer _ = win.ReleaseMutex(outbox_mutex);
    const wacli_path = try findWacli(init, init.gpa);
    defer init.gpa.free(wacli_path);
    const avatar_dir = try createAvatarDirectory(init, init.gpa);
    const messages_dir = std.fs.path.dirname(avatar_dir) orelse return error.MissingMessagesDir;
    const cache_tag = loadPersistedTag(init.gpa, messages_dir);
    const slack_media_dir = try createSlackMediaDirectory(init, init.gpa);
    defer init.gpa.free(slack_media_dir);
    const store_watch_path = try createStoreWatchPath(init, init.gpa);
    defer init.gpa.free(store_watch_path);
    const sync_heartbeat_path = try createSyncHeartbeatPath(init, init.gpa);
    defer init.gpa.free(sync_heartbeat_path);
    const wacli_dir = std.fs.path.dirname(store_watch_path) orelse return error.MissingUserProfile;
    const deepgram = try slack_win.loadDeepgramKey(init.gpa);
    defer init.gpa.free(deepgram.key);
    const deepgram_key = deepgram.key;
    const environment_openrouter = try environment_keys.load(init.gpa, "OPENROUTER_API_KEY", if (verification_fixture) null else init.environ_map.get("OPENROUTER_API_KEY"));
    defer init.gpa.free(environment_openrouter);
    var openrouter_key: []const u8 = environment_openrouter;
    var stored_openrouter: ?slack_win.SecretLoad = null;
    if (openrouter_key.len == 0) {
        stored_openrouter = slack_win.loadSecret(init.gpa, lit("OpenRouterApiKey"));
        if (stored_openrouter) |stored| openrouter_key = stored.value;
    }
    var openrouter_model = init.environ_map.get("OPENROUTER_MODEL") orelse "";
    if (openrouter_model.len == 0) {
        if (loadRegistryString(init.gpa, lit("OpenRouterModel"))) |stored| {
            openrouter_model = stored;
        }
    }
    if (openrouter_model.len == 0) openrouter_model = "openai/gpt-5.6-luna";
