        .style = win.CS_DROPSHADOW,
        .lpfnWndProc = shortcodeProc,
        .cbClsExtra = 0,
        .cbWndExtra = 0,
        .hInstance = instance,
        .hIcon = icon_big,
        .hCursor = cursor,
        .hbrBackground = null,
        .lpszMenuName = null,
        .lpszClassName = lit("MessagesShortcodePopup"),
        .hIconSm = icon_small,
    };
    if (win.RegisterClassExW(&shortcode_class) == 0) return error.RegisterShortcodeClassFailed;

    var viewer_class = win.WNDCLASSEXW{
        .cbSize = @sizeOf(win.WNDCLASSEXW),
        .style = win.CS_HREDRAW | win.CS_VREDRAW | win.CS_DBLCLKS,
        .lpfnWndProc = imageViewerProc,
        .cbClsExtra = 0,
        .cbWndExtra = 0,
        .hInstance = instance,
        .hIcon = icon_big,
        .hCursor = cursor,
        .hbrBackground = null,
        .lpszMenuName = null,
        .lpszClassName = lit("MessagesImageViewer"),
        .hIconSm = icon_small,
    };
    if (win.RegisterClassExW(&viewer_class) == 0) return error.RegisterImageViewerClassFailed;

    var pre_window_buffer: [64]u8 = undefined;
    appendLaunchLog(app, std.fmt.bufPrint(&pre_window_buffer, "startup-timing: pre-window work done {d} ms", .{win.GetTickCount64() -% process_start_ms}) catch "startup-timing: pre-window work done");
    const window_rect = loadWindowRect();
    const hwnd = win.CreateWindowExW(
        win.WS_EX_ACCEPTFILES,
        lit("MessagesZig"),
        lit("Wazig v" ++ app_version),
        win.WS_OVERLAPPEDWINDOW | win.WS_CLIPCHILDREN | win.WS_MAXIMIZE,
        if (window_rect) |rect| rect.left else win.CW_USEDEFAULT,
        if (window_rect) |rect| rect.top else win.CW_USEDEFAULT,
        if (window_rect) |rect| rect.right - rect.left else 1160,
        if (window_rect) |rect| rect.bottom - rect.top else 760,
        null,
        null,
        instance,
        null,
    ) orelse return error.CreateWindowFailed;
    updateWindowTitle(app);
    var dark: win.BOOL = win.TRUE;
    _ = win.DwmSetWindowAttribute(hwnd, 20, &dark, @sizeOf(win.BOOL));
    _ = win.ShowWindow(hwnd, win.SW_SHOWMAXIMIZED);
    if (win.IsZoomed(hwnd) == 0) _ = win.ShowWindow(hwnd, win.SW_MAXIMIZE);
    appendLaunchLog(app, if (win.IsZoomed(hwnd) != 0) "startup: window zoomed=true" else "startup: window zoomed=false");
    _ = win.UpdateWindow(hwnd);
    focusCompose(app);
    logStartupMilestone(app, .window, "window shown");
    if (!verification_fixture and !hubConfigured(app)) {
        if (std.heap.page_allocator.create(ProbeThread)) |probe| {
            probe.* = .{ .io = init.io, .hwnd = hwnd, .wacli_path = wacli_path, .scratch_dir = messages_dir };
            if (std.Thread.spawn(.{ .stack_size = 512 * 1024 }, startupProbeMain, .{probe})) |thread| {
                thread.detach();
            } else |_| {
                std.heap.page_allocator.destroy(probe);
                app.startup_probe_pending = false;
            }
        } else |_| app.startup_probe_pending = false;
    }

    var message: win.MSG = undefined;
    while (win.GetMessageW(&message, null, 0, 0) > 0) {
        if (message.message == win.WM_MOUSEWHEEL and app.canvas != null) {
            const wheel_point = win.POINT{
                .x = @as(i16, @bitCast(loword(@as(usize, @bitCast(message.lParam))))),
                .y = @as(i16, @bitCast(hiword(@as(usize, @bitCast(message.lParam))))),
            };
            var canvas_rect: win.RECT = undefined;
            _ = win.GetWindowRect(app.canvas.?, &canvas_rect);
            if (wheel_point.x >= canvas_rect.left and wheel_point.x <= canvas_rect.right and wheel_point.y >= canvas_rect.top and wheel_point.y <= canvas_rect.bottom) {
                const wheel_delta: i16 = @bitCast(hiword(@as(usize, @bitCast(message.wParam))));
                app.scroll_y = std.math.clamp(app.scroll_y + @divTrunc(@as(i32, wheel_delta), 2), 0, app.max_scroll);
                _ = win.InvalidateRect(app.canvas.?, null, win.TRUE);
                if (wheel_delta > 0 and app.scroll_y >= app.max_scroll) requestHubOlder(app);
                continue;
            }
            if (app.chats_hwnd) |list| {
                var list_rect: win.RECT = undefined;
                _ = win.GetWindowRect(list, &list_rect);
                if (wheel_point.x >= list_rect.left and wheel_point.x <= list_rect.right and wheel_point.y >= list_rect.top and wheel_point.y <= list_rect.bottom) {
                    const wheel_delta: i16 = @bitCast(hiword(@as(usize, @bitCast(message.wParam))));
                    const step = sidebar_nav.wheelRows(app.chat_wheel_accum, @as(i32, wheel_delta), @as(i32, win.WHEEL_DELTA), chat_wheel_lines_per_notch);
                    app.chat_wheel_accum = step.remainder;
                    if (step.rows != 0) {
                        const info = listboxScrollInfo(list);
                        const max_top = @max(0, info.total - info.page);
                        setListboxTop(list, std.math.clamp(info.top - step.rows, 0, max_top));
                        _ = win.InvalidateRect(list, null, win.FALSE);
                    }
                    continue;
                }
            }
        }
        if (app.tg_login_window) |login_wnd| {
            if (win.IsDialogMessageW(login_wnd, &message) != 0) continue;
        }
        if (message.message == win.WM_MOUSEMOVE and app.chats_hwnd != null and message.hwnd == app.chats_hwnd.?) updateChatTooltip(app, message.lParam);
        if (handleKeyboard(app, &message)) continue;
        const clicked_chat_list = message.message == win.WM_LBUTTONDOWN and
            app.chats_hwnd != null and message.hwnd == app.chats_hwnd.?;
        _ = win.TranslateMessage(&message);
        _ = win.DispatchMessageW(&message);
        if (clicked_chat_list) {
            focusCompose(app);
        }
    }
}

const UpdateContext = struct {
    io: std.Io,
    hwnd: win.HWND,
    manual: bool,
    install: bool,
    stage_only: bool = false,
};

const UpdateOutcome = enum { none, blocked, installed, staged };

var update_dl_done: std.atomic.Value(u64) = .init(0);
var update_dl_total: std.atomic.Value(u64) = .init(0);
var update_dl_active: std.atomic.Value(bool) = .init(false);

fn currentVersion() ?update.Version {
    const real = update.parseVersion(app_version) orelse return null;
    var buf: [32]u16 = undefined;
    const len: usize = @intCast(win.GetEnvironmentVariableW(lit("WAZIG_FAKE_VERSION"), &buf, buf.len));
    if (len == 0 or len >= buf.len) return real;
    var text: [32]u8 = undefined;
    for (buf[0..len], 0..) |c, i| text[i] = if (c < 128) @intCast(c) else '?';
    return update.effectiveCurrent(real, text[0..len]);
}

const UpdateAvailable = struct {
    tag: []u8,
    notes: []u8,

    fn deinit(self: *UpdateAvailable, allocator: std.mem.Allocator) void {
        allocator.free(self.tag);
        allocator.free(self.notes);
    }
};

const update_card_restart_delay_ms: u32 = 600;
const UpdateCardHit = enum { none, body, button, close };

fn updateCardVisible(a: *const App) bool {
    const pending = a.update_pending orelse return false;
    if (a.update_installed or a.update_card_busy or a.update_card_error_len > 0) return true;
    const dismissed = a.update_dismissed[0..a.update_dismissed_len];
    return !std.mem.eql(u8, pending.tag[0..@min(pending.tag.len, a.update_dismissed.len)], dismissed);
}

fn updateCardNotesHeight(a: *const App) i32 {
    const pending = a.update_pending orelse return 0;
    const hwnd = a.hwnd orelse return 0;
    const hdc = win.GetDC(hwnd) orelse return 0;
    defer _ = win.ReleaseDC(hwnd, hdc);
    const old_font = win.SelectObject(hdc, @ptrCast(a.font_small orelse return 0));
    defer _ = win.SelectObject(hdc, old_font);
    const notes = utf8ToWide(a.allocator, pending.notes) catch return 0;
    defer a.allocator.free(notes);
    const left_width = std.math.clamp(@divTrunc(a.compose_client_width, 3), px(a, 280), px(a, 390));
    var rect = win.RECT{ .left = 0, .top = 0, .right = left_width - px(a, 48), .bottom = 0 };
    _ = text_draw.drawText(hdc, notes.ptr, @intCast(notes.len), &rect, win.DT_CALCRECT | win.DT_WORDBREAK | win.DT_NOPREFIX);
    return rect.bottom - rect.top;
}

fn updateCardHeight(a: *const App) i32 {
    return update_card_layout.heightForNotes(@intCast(a.dpi), updateCardNotesHeight(a));
}

fn updateCardSpan(a: *const App) i32 {
    if (!updateCardVisible(a)) return 0;
    return updateCardHeight(a) + px(a, 10);
}

fn updateCardRect(a: *const App) win.RECT {
    const left_width = std.math.clamp(@divTrunc(a.compose_client_width, 3), px(a, 280), px(a, 390));
    const bottom = a.compose_client_height - px(a, 26) - px(a, 6);
    return .{ .left = px(a, 12), .top = bottom - updateCardHeight(a), .right = left_width - px(a, 12), .bottom = bottom };
}

fn updateCardLayout(a: *const App, card: win.RECT) update_card_layout.Layout {
    return update_card_layout.compute(.{ .left = card.left, .top = card.top, .right = card.right, .bottom = card.bottom }, @intCast(a.dpi));
}

fn updateCardWinRect(r: update_card_layout.Rect) win.RECT {
    return .{ .left = r.left, .top = r.top, .right = r.right, .bottom = r.bottom };
}

fn updateCardButtonRect(a: *const App, card: win.RECT) win.RECT {
    return updateCardWinRect(updateCardLayout(a, card).button);
}

fn updateCardCloseRect(a: *const App, card: win.RECT) win.RECT {
    return updateCardWinRect(updateCardLayout(a, card).close);
}

fn updateCardPtIn(r: win.RECT, x: i32, y: i32) bool {
    return x >= r.left and x < r.right and y >= r.top and y < r.bottom;
}

fn updateCardHit(a: *const App, x: i32, y: i32) UpdateCardHit {
    if (!updateCardVisible(a)) return .none;
    const card = updateCardRect(a);
    if (!updateCardPtIn(card, x, y)) return .none;
    const idle = !a.update_card_busy and !a.update_installed;
    if (idle and updateCardPtIn(updateCardCloseRect(a, card), x, y)) return .close;
    if (idle and updateCardPtIn(updateCardButtonRect(a, card), x, y)) return .button;
    return .body;
}

fn updateCardRefresh(a: *App) void {
    const hwnd = a.hwnd orelse return;
    layout(a, a.compose_client_width, a.compose_client_height);
    if (a.update_card_busy or a.update_install_running.load(.acquire)) {
        _ = win.SetTimer(hwnd, timer_update_card, 400, null);
    } else {
        _ = win.KillTimer(hwnd, timer_update_card);
    }
}

fn updateCardFail(a: *App, text: []const u8) void {
    a.update_card_busy = false;
    a.update_click_wait = false;
    const n = @min(text.len, a.update_card_error.len);
    @memcpy(a.update_card_error[0..n], text[0..n]);
    a.update_card_error_len = @max(n, 1);
    var log_buf: [160]u8 = undefined;
    appendLaunchLog(a, std.fmt.bufPrint(&log_buf, "update: card install failed: {s}", .{text}) catch "update: card install failed");
    updateCardRefresh(a);
}

fn updateCardClick(a: *App) void {
    if (a.update_pending == null or a.update_installed or a.update_card_busy) return;
    const hwnd = a.hwnd orelse return;
    a.update_card_error_len = 0;
    a.update_install_auto = false;
    a.update_card_busy = true;
    appendLaunchLog(a, "update: card clicked");
    setStatus(a, "Updating Messages...");
    if (a.update_install_running.load(.acquire)) {
        a.update_click_wait = true;
    } else {
        startUpdateInstall(hwnd, false);
    }
    updateCardRefresh(a);
}

fn updateCardDismiss(a: *App) void {
    const pending = a.update_pending orelse return;
    const n = @min(pending.tag.len, a.update_dismissed.len);
    @memcpy(a.update_dismissed[0..n], pending.tag[0..n]);
    a.update_dismissed_len = n;
    updateCardRefresh(a);
}

fn removeLeftoverOldExe() void {
    var buf: [530]u16 = undefined;
    const len: usize = @intCast(win.GetModuleFileNameW(null, &buf, 519));
    if (len == 0 or len >= 519) return;
    for (".old", 0..) |c, i| buf[len + i] = c;
    buf[len + 4] = 0;
    _ = win.DeleteFileW(buf[0 .. len + 4 :0].ptr);
}

fn paintUpdateCard(a: *App, shapes: *const smooth.Context, hdc: win.HDC) void {
    if (!updateCardVisible(a)) return;
    const pending = a.update_pending orelse return;
    const card = updateCardRect(a);
    paintRoundedButton(a, shapes, hdc, card, theme.current.surface_container_high, theme.current.on_surface, a.font.?, if (theme.choice == .amoled) theme.current.outline_variant else theme.current.secondary_container, &[_]u16{});
    _ = win.SetBkMode(hdc, win.TRANSPARENT);

    var title_buf: [64]u8 = undefined;
    const tag = if (pending.tag.len > 0 and pending.tag[0] == 'v') pending.tag[1..] else pending.tag;
    const failed = a.update_card_error_len > 0;
    const title: []const u8 = if (a.update_installed)
        "Restarting..."
    else if (failed)
        "Update failed"
    else if (a.update_card_busy)
        "Updating..."
    else
        std.fmt.bufPrint(&title_buf, "New version v{s}", .{tag}) catch "New version available";
    _ = win.SelectObject(hdc, @ptrCast(a.font_bold.?));
    _ = win.SetTextColor(hdc, theme.current.on_surface);
    const card_layout = updateCardLayout(a, card);
    var title_rc = updateCardWinRect(card_layout.title);
    drawAscii(hdc, &title_rc, title, win.DT_SINGLELINE | win.DT_VCENTER | win.DT_NOPREFIX | win.DT_END_ELLIPSIS);

    _ = win.SelectObject(hdc, @ptrCast(a.font_small.?));
    var line_buf: [112]u8 = undefined;
    const pct: u32 = if (a.update_staged or a.update_installed) 100 else update.percent(update_dl_done.load(.acquire), update_dl_total.load(.acquire));
    const busy = a.update_card_busy or a.update_installed;
    const line: []const u8 = if (failed)
        a.update_card_error[0..a.update_card_error_len]
    else if (busy and pct >= 100)
        "Installing..."
    else if (busy)
        std.fmt.bufPrint(&line_buf, "Downloading {d}%", .{pct}) catch "Downloading..."
    else if (a.update_staged)
        "Ready to install"
    else
        "Downloading in the background...";
    _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
    var line_rc = updateCardWinRect(card_layout.line);
    drawAscii(hdc, &line_rc, line, win.DT_SINGLELINE | win.DT_VCENTER | win.DT_NOPREFIX | win.DT_END_ELLIPSIS);

    if (utf8ToWide(a.allocator, pending.notes)) |notes| {
        defer a.allocator.free(notes);
        var notes_rc = updateCardWinRect(card_layout.notes);
        _ = text_draw.drawText(hdc, notes.ptr, @intCast(notes.len), &notes_rc, win.DT_WORDBREAK | win.DT_NOPREFIX);
    } else |_| {}

    if (busy) {
        const bar = updateCardWinRect(card_layout.bar);
        var track = bar;
        if (win.CreateSolidBrush(theme.current.secondary_container)) |brush| {
            _ = win.FillRect(hdc, &track, brush);
            _ = win.DeleteObject(brush);
        }
        var fill = bar;
        fill.right = bar.left + @divTrunc((bar.right - bar.left) * @as(i32, @intCast(pct)), 100);
        if (win.CreateSolidBrush(theme.current.primary)) |brush| {
            _ = win.FillRect(hdc, &fill, brush);
            _ = win.DeleteObject(brush);
        }
        return;
    }

    var close_rc = updateCardCloseRect(a, card);
    _ = win.SetTextColor(hdc, theme.current.on_surface_variant);
    drawAscii(hdc, &close_rc, "x", win.DT_SINGLELINE | win.DT_VCENTER | win.DT_CENTER | win.DT_NOPREFIX);

    const label: []const u16 = if (failed) std.unicode.utf8ToUtf16LeStringLiteral("Retry") else std.unicode.utf8ToUtf16LeStringLiteral("Update now");
    paintRoundedButton(a, shapes, hdc, updateCardButtonRect(a, card), if (theme.choice == .amoled) theme.amoled_send else theme.current.primary, if (theme.choice == .amoled) theme.amoled_button_text else theme.current.on_primary, a.font_bold.?, if (theme.choice == .amoled) theme.current.outline else null, label);
}

fn startUpdateCheck(hwnd: win.HWND, manual: bool) void {
    if (verification_fixture) return;
    const a = app_ptr orelse return;
    if (a.update_installed) return;
    const now = win.GetTickCount64();
    if (a.update_check_running and now - a.update_last_check_ms < update_check_timeout_ms) return;
    if (!manual and a.update_last_check_ms != 0 and now - a.update_last_check_ms < update_wake_focus_throttle_ms) return;
    a.update_check_manual = manual;
    const ctx = std.heap.page_allocator.create(UpdateContext) catch return;
    ctx.* = .{ .io = a.io, .hwnd = hwnd, .manual = manual, .install = false };
    const thread = std.Thread.spawn(.{}, updateThreadMain, .{ctx}) catch {
        std.heap.page_allocator.destroy(ctx);
        return;
    };
    thread.detach();
    a.update_check_running = true;
    a.update_last_check_ms = now;
}

fn startUpdateInstall(hwnd: win.HWND, stage_only: bool) void {
    const a = app_ptr orelse return;
    if (a.update_install_running.load(.acquire)) {
        if (!stage_only) setStatus(a, "An update install is already running");
        return;
    }
    const ctx = std.heap.page_allocator.create(UpdateContext) catch return;
    ctx.* = .{ .io = a.io, .hwnd = hwnd, .manual = true, .install = true, .stage_only = stage_only };
    a.update_install_running.store(true, .release);
    const thread = std.Thread.spawn(.{}, updateThreadMain, .{ctx}) catch {
        a.update_install_running.store(false, .release);
        std.heap.page_allocator.destroy(ctx);
        return;
    };
    thread.detach();
}

fn postInstallResult(hwnd: win.HWND, code: u32, lparam: usize) void {
    var tries: u32 = 0;
    while (tries < 50) : (tries += 1) {
        if (win.PostMessageW(hwnd, wm_update_ready, code, @bitCast(lparam)) != 0) return;
        win.Sleep(100);
    }
    if (app_ptr) |a| a.update_install_running.store(false, .release);
}

fn postUpdateFailure(hwnd: win.HWND, manual: bool, err: anyerror) void {
    logUpdateFailure(@errorName(err));
    const name: [*:0]const u8 = @errorName(err).ptr;
    _ = win.PostMessageW(hwnd, wm_update_ready, if (manual) 5 else 4, @intCast(@intFromPtr(name)));
}

fn updateThreadMain(ctx: *UpdateContext) void {
    defer std.heap.page_allocator.destroy(ctx);
    const allocator = std.heap.page_allocator;
    if (ctx.install) {
        const outcome = performUpdate(ctx.io, ctx.stage_only) catch |err| {
            logUpdateFailure(@errorName(err));
            const name: [*:0]const u8 = @errorName(err).ptr;
            postInstallResult(ctx.hwnd, 7, @intCast(@intFromPtr(name)));
            return;
        };
        if (outcome == .blocked) logUpdateFailure("update blocked by another running copy");
        postInstallResult(ctx.hwnd, switch (outcome) {
            .installed => @as(u32, 1),
            .blocked => 6,
            .none => 8,
            .staged => 9,
        }, 0);
        return;
    }
    const maybe_update = checkForUpdate(allocator) catch |err| {
        postUpdateFailure(ctx.hwnd, ctx.manual, err);
        return;
    };
    if (maybe_update) |found| {
        const stored = std.heap.page_allocator.create(UpdateAvailable) catch {
            var heap_copy = found;
            heap_copy.deinit(allocator);
            _ = win.PostMessageW(ctx.hwnd, wm_update_ready, 3, 0);
            return;
        };
        stored.* = found;
        if (win.PostMessageW(ctx.hwnd, wm_update_ready, 2, @intCast(@intFromPtr(stored))) == 0) {
            stored.deinit(allocator);
            std.heap.page_allocator.destroy(stored);
        }
    } else {
        _ = win.PostMessageW(ctx.hwnd, wm_update_ready, 3, 0);
    }
}

fn checkForUpdate(allocator: std.mem.Allocator) !?UpdateAvailable {
    const current = currentVersion() orelse return error.UpdateBadVersion;
    const api_headers = try utf8ToWide(allocator, "User-Agent: Messages updater\r\nAccept: application/vnd.github+json\r\n");
    defer allocator.free(api_headers);
    const json = try httpGet(allocator, lit("api.github.com"), lit("/repos/valentinyeo/wazig/releases/latest"), api_headers.ptr, 4 * 1024 * 1024, win.INTERNET_DEFAULT_HTTPS_PORT, true, true);
    defer allocator.free(json);
    var parsed: std.json.Parsed(std.json.Value) = undefined;
    const maybe_asset = try update.pickAsset(allocator, json, &parsed);
    defer parsed.deinit();
    const asset = maybe_asset orelse return null;
    if (!update.isNewer(asset.tag, current)) return null;
    var arena = std.heap.ArenaAllocator.init(allocator);
    defer arena.deinit();
    const history_allocator = arena.allocator();
    var releases: std.ArrayList(update.Release) = .empty;
    try releases.append(history_allocator, .{ .tag = asset.tag, .body = update.releaseBody(parsed.value) });
    var page: usize = 1;
    while (true) : (page += 1) {
        const path = try std.fmt.allocPrint(allocator, "/repos/valentinyeo/wazig/releases?page={d}", .{page});
        defer allocator.free(path);
        const wide_path = try utf8ToWide(allocator, path);
        defer allocator.free(wide_path);
        const history_json = try httpGet(allocator, lit("api.github.com"), wide_path.ptr, api_headers.ptr, 4 * 1024 * 1024, win.INTERNET_DEFAULT_HTTPS_PORT, true, true);
        defer allocator.free(history_json);
        const history = try std.json.parseFromSlice(std.json.Value, allocator, history_json, .{});
        defer history.deinit();
        if (history.value != .array) return error.UpdateBadReleaseHistory;
        if (history.value.array.items.len == 0) break;
        for (history.value.array.items) |value| {
            const release = update.releaseFromValue(value) orelse continue;
            if (!update.isNewer(release.tag, current) or std.mem.eql(u8, release.tag, asset.tag) or update.isNewer(release.tag, asset.version)) continue;
            try releases.append(history_allocator, .{
                .tag = try history_allocator.dupe(u8, release.tag),
                .body = try history_allocator.dupe(u8, release.body),
            });
        }
    }
    const notes = try update.notesForReleases(allocator, releases.items, current, asset.version);
    errdefer allocator.free(notes);
    const tag = try allocator.dupe(u8, asset.tag);
    return .{ .tag = tag, .notes = notes };
}

fn logUpdateFailure(err_name: []const u8) void {
    var clock = std.mem.zeroes(win.SYSTEMTIME);
    win.GetLocalTime(&clock);
    var line_buf: [160]u8 = undefined;
    const line = std.fmt.bufPrint(&line_buf, "{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2} update check failed: {s}\r\n", .{
        clock.wYear, clock.wMonth, clock.wDay, clock.wHour, clock.wMinute, clock.wSecond, err_name,
    }) catch return;
    appendUpdateLogLine(line);
}

fn appendUpdateLogLine(line: []const u8) void {
    const allocator = std.heap.page_allocator;
    var local_buf: [256]u16 = undefined;
    const local_len: usize = @intCast(win.GetEnvironmentVariableW(lit("LOCALAPPDATA"), &local_buf, local_buf.len));
    if (local_len == 0 or local_len >= local_buf.len) return;
    const local_dir = wideToUtf8(allocator, local_buf[0..local_len]) catch return;
    defer allocator.free(local_dir);
    const log_path = std.fmt.allocPrint(allocator, "{s}\\Wazig\\update.log", .{local_dir}) catch return;
    defer allocator.free(log_path);
    const wide = utf8ToWide(allocator, log_path) catch return;
    defer allocator.free(wide);
    const handle = win.CreateFileW(wide.ptr, win.FILE_APPEND_DATA, win.FILE_SHARE_READ | win.FILE_SHARE_WRITE, null, win.OPEN_ALWAYS, win.FILE_ATTRIBUTE_NORMAL, null);
    if (handle == win.INVALID_HANDLE_VALUE or handle == null) return;
    defer _ = win.CloseHandle(handle);
    var written: win.DWORD = 0;
    _ = win.WriteFile(handle, line.ptr, @intCast(line.len), &written, null);
}

fn logUpdateSwapDetail(exe_path: []const u8, pending: []const SwapPending) void {
    const allocator = std.heap.page_allocator;
    var line_buf: [1024]u8 = undefined;
    var fbs: std.Io.Writer = .fixed(&line_buf);
    fbs.print("swap detail: exe_path={s} staged={d}\r\n", .{ exe_path, pending.len }) catch {};
    for (pending, 0..) |p, i| {
        if (i >= 8) {
            fbs.print("swap detail: ...\r\n", .{}) catch {};
            break;
        }
        const dest = wideToUtf8(allocator, p.dest) catch continue;
        defer allocator.free(dest);
        fbs.print("swap detail: dest={s}\r\n", .{dest}) catch {};
    }
    appendUpdateLogLine(fbs.buffered());
}

fn utf8ToWide(allocator: std.mem.Allocator, text: []const u8) ![:0]u16 {
    return std.unicode.utf8ToUtf16LeAllocZ(allocator, text);
}

fn wideToUtf8(allocator: std.mem.Allocator, wide: []const u16) ![]u8 {
    return std.unicode.utf16LeToUtf8Alloc(allocator, wide);
}

fn httpGet(allocator: std.mem.Allocator, host: [*:0]const u16, path: [*:0]const u16, headers: [*:0]const u16, max_bytes: usize, port: u16, secure: bool, redirects: bool) ![]u8 {
    const session = win.WinHttpOpen(lit("Messages updater"), win.WINHTTP_ACCESS_TYPE_DEFAULT_PROXY, null, null, 0) orelse return error.UpdateNetwork;
    defer _ = win.WinHttpCloseHandle(session);
    _ = win.WinHttpSetTimeouts(session, 15000, 15000, 60000, 60000);
    const connection = win.WinHttpConnect(session, host, port, 0) orelse return error.UpdateNetwork;
    defer _ = win.WinHttpCloseHandle(connection);
    const request = win.WinHttpOpenRequest(connection, lit("GET"), path, null, null, null, if (secure) win.WINHTTP_FLAG_SECURE else 0) orelse return error.UpdateNetwork;
    defer _ = win.WinHttpCloseHandle(request);
    var policy: win.DWORD = if (redirects) win.WINHTTP_OPTION_REDIRECT_POLICY_DISALLOW_HTTPS_TO_HTTP else win.WINHTTP_OPTION_REDIRECT_POLICY_NEVER;
    _ = win.WinHttpSetOption(request, win.WINHTTP_OPTION_REDIRECT_POLICY, &policy, @sizeOf(@TypeOf(policy)));
    _ = win.WinHttpAddRequestHeaders(request, headers, std.math.maxInt(win.DWORD), win.WINHTTP_ADDREQ_FLAG_ADD);
    if (win.WinHttpSendRequest(request, null, 0, null, 0, 0, 0) == 0) return error.UpdateNetwork;
    if (win.WinHttpReceiveResponse(request, null) == 0) return error.UpdateNetwork;
    var status: win.DWORD = 0;
    var status_size: win.DWORD = @sizeOf(win.DWORD);
    if (win.WinHttpQueryHeaders(request, win.WINHTTP_QUERY_STATUS_CODE | win.WINHTTP_QUERY_FLAG_NUMBER, null, &status, &status_size, null) == 0 or status != 200) {
        return error.UpdateHttpStatus;
    }
    var body: std.ArrayList(u8) = .empty;
    errdefer body.deinit(allocator);
    var chunk: [16384]u8 = undefined;
    while (true) {
        var read: win.DWORD = 0;
        if (win.WinHttpReadData(request, &chunk, chunk.len, &read) == 0) return error.UpdateNetwork;
        if (read == 0) break;
        if (body.items.len + read > max_bytes) return error.UpdateTooLarge;
        try body.appendSlice(allocator, chunk[0..read]);
        if (update_dl_active.load(.acquire)) update_dl_done.store(body.items.len, .release);
    }
    return body.toOwnedSlice(allocator);
}

fn httpGetUrl(allocator: std.mem.Allocator, url_wide: []const u16, headers: [*:0]const u16, max_bytes: usize) ![]u8 {
    var components: win.URL_COMPONENTSW = std.mem.zeroes(win.URL_COMPONENTSW);
    components.dwStructSize = @sizeOf(win.URL_COMPONENTSW);
    var host_buf: [256]u16 = undefined;
    var path_buf: [2048]u16 = undefined;
    var extra_buf: [512]u16 = undefined;
    components.lpszHostName = &host_buf;
    components.dwHostNameLength = host_buf.len;
    components.lpszUrlPath = &path_buf;
    components.dwUrlPathLength = path_buf.len;
    components.lpszExtraInfo = &extra_buf;
    components.dwExtraInfoLength = extra_buf.len;
    if (win.WinHttpCrackUrl(url_wide.ptr, @intCast(url_wide.len), 0, &components) == 0) return error.UpdateBadUrl;
    if (components.nScheme != win.INTERNET_SCHEME_HTTPS) return error.UpdateBadUrl;
    if (components.dwHostNameLength == 0 or components.dwHostNameLength >= host_buf.len) return error.UpdateBadUrl;
    const host_utf8 = try wideToUtf8(allocator, host_buf[0..components.dwHostNameLength]);
    defer allocator.free(host_utf8);
    const github_suffixes = [_][]const u8{ "api.github.com", "objects.githubusercontent.com", "github.com" };
    var host_allowed = false;
    for (github_suffixes) |allowed| {
        if (std.mem.eql(u8, host_utf8, allowed)) host_allowed = true;
    }
    if (!host_allowed) return error.UpdateBadUrl;
    if (components.dwUrlPathLength >= path_buf.len) return error.UpdateBadUrl;
    if (components.dwUrlPathLength + components.dwExtraInfoLength >= path_buf.len) return error.UpdateBadUrl;
    host_buf[components.dwHostNameLength] = 0;
    std.mem.copyForwards(u16, path_buf[components.dwUrlPathLength..], extra_buf[0..components.dwExtraInfoLength]);
    const path_total = components.dwUrlPathLength + components.dwExtraInfoLength;
    path_buf[path_total] = 0;
    return httpGet(
        allocator,
        host_buf[0..components.dwHostNameLength :0].ptr,
        path_buf[0..path_total :0].ptr,
        headers,
        max_bytes,
        win.INTERNET_DEFAULT_HTTPS_PORT,
        true,
        true,
    );
}

fn clearStaleOrphans() void {
    const self_pid = win.GetCurrentProcessId();
    var exe_buf: [519]u16 = undefined;
    const exe_len: usize = @intCast(win.GetModuleFileNameW(null, &exe_buf, exe_buf.len));
    if (exe_len == 0 or exe_len >= exe_buf.len) return;

    var visible: [1024]win.DWORD = undefined;
    var visible_count: usize = 0;
    var visible_overflow = false;
    const ctx = VisibleWindowScan{ .pids = &visible, .count = &visible_count, .overflow = &visible_overflow };
    _ = win.EnumWindows(visibleWindowProc, @bitCast(@intFromPtr(&ctx)));
    if (visible_overflow) return;

    const TH32CS_SNAPPROCESS = 0x00000002;
    const snapshot = win.CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0) orelse return;
    defer _ = win.CloseHandle(snapshot);
    var entry = std.mem.zeroes(win.PROCESSENTRY32W);
    entry.dwSize = @sizeOf(win.PROCESSENTRY32W);
    if (win.Process32FirstW(snapshot, &entry) == 0) return;
    while (true) {
        const pid = entry.th32ProcessID;
        if (pid != self_pid) {
            const handle = win.OpenProcess(win.PROCESS_QUERY_LIMITED_INFORMATION | win.PROCESS_TERMINATE | win.SYNCHRONIZE, win.FALSE, pid);
            if (handle != null and handle != win.INVALID_HANDLE_VALUE) {
                defer _ = win.CloseHandle(handle);
                var created: win.FILETIME = undefined;
                var exit_time: win.FILETIME = undefined;
                var kernel_time: win.FILETIME = undefined;
                var user_time: win.FILETIME = undefined;
                var path_buf: [519]u16 = undefined;
                var path_len: win.DWORD = path_buf.len;
                var orphan_session: win.DWORD = 0;
                var self_session: win.DWORD = 0;
                const same_session = win.ProcessIdToSessionId(pid, &orphan_session) != 0 and
                    win.ProcessIdToSessionId(self_pid, &self_session) != 0 and
                    orphan_session == self_session;
                if (same_session and
                    win.GetProcessTimes(handle, &created, &exit_time, &kernel_time, &user_time) != 0 and
                    update.isStaleOrphan(self_pid, pid, containsPid(visible[0..visible_count], pid), filetimeAgeSeconds(created)) and
                    win.QueryFullProcessImageNameW(handle, 0, &path_buf, &path_len) != 0 and
                    eqlWideIgnoreCase(path_buf[0..path_len], exe_buf[0..exe_len]))
                {
                    _ = win.TerminateProcess(handle, 1);
                    _ = win.WaitForSingleObject(handle, 5000);
                }
            }
        }
        if (win.Process32NextW(snapshot, &entry) == 0) break;
    }
}

const VisibleWindowScan = struct {
    pids: []win.DWORD,
    count: *usize,
    overflow: *bool,
};

fn visibleWindowProc(hwnd: win.HWND, lparam: win.LPARAM) callconv(.winapi) win.BOOL {
    if (win.IsWindowVisible(hwnd) != 0) {
        const scan: *VisibleWindowScan = @ptrFromInt(@as(usize, @bitCast(lparam)));
        var pid: win.DWORD = 0;
        _ = win.GetWindowThreadProcessId(hwnd, &pid);
        if (scan.count.* >= scan.pids.len) {
            scan.overflow.* = true;
            return 0;
        }
        scan.pids[scan.count.*] = pid;
        scan.count.* += 1;
    }
    return 1;
}

fn containsPid(pids: []const win.DWORD, pid: win.DWORD) bool {
    for (pids) |candidate| {
        if (candidate == pid) return true;
    }
    return false;
}

fn filetimeAgeSeconds(created: win.FILETIME) u64 {
    var now: win.FILETIME = undefined;
    win.GetSystemTimeAsFileTime(&now);
    const created_64 = (@as(u64, created.dwHighDateTime) << 32) | created.dwLowDateTime;
    const now_64 = (@as(u64, now.dwHighDateTime) << 32) | now.dwLowDateTime;
    if (now_64 <= created_64) return 0;
    return (now_64 - created_64) / 10_000_000;
}

fn filePresentLookup(path_wide: [*:0]const u16) ?bool {
    if (win.GetFileAttributesW(path_wide) != win.INVALID_FILE_ATTRIBUTES) return true;
    const err = win.GetLastError();
    if (err == 2 or err == 3) return false;
    return null;
}

fn eqlWideIgnoreCase(a: []const u16, b: []const u16) bool {
    if (a.len != b.len) return false;
    for (a, b) |x, y| {
        const lx: u16 = if (x >= 'A' and x <= 'Z') x + 0x20 else x;
        const ly: u16 = if (y >= 'A' and y <= 'Z') y + 0x20 else y;
        if (lx != ly) return false;
    }
    return true;
}

fn performUpdate(io: std.Io, stage_only: bool) !UpdateOutcome {
    const allocator = std.heap.page_allocator;
    const current = currentVersion() orelse return error.UpdateBadVersion;

    const mutex = win.CreateMutexW(null, win.FALSE, lit("Local\\MessagesUpdateMutex")) orelse return error.UpdateMutexFailed;
    defer _ = win.CloseHandle(mutex);
    var wait = update.classifyMutexWait(win.WaitForSingleObject(mutex, 0));
    if (wait == .busy) {
        clearStaleOrphans();
        wait = update.classifyMutexWait(win.WaitForSingleObject(mutex, 10_000));
    }
    if (wait == .failed) return error.UpdateMutexFailed;
    if (wait != .acquired) return .blocked;
    defer _ = win.ReleaseMutex(mutex);

    var exe_wide_buf: [519]u16 = undefined;
    const exe_len: usize = @intCast(win.GetModuleFileNameW(null, &exe_wide_buf, exe_wide_buf.len));
    if (exe_len == 0 or exe_len >= exe_wide_buf.len) {
        var detail_buf: [96]u8 = undefined;
        appendUpdateLogLine(std.fmt.bufPrint(&detail_buf, "swap detail: exe path unreadable, len={d}\r\n", .{exe_len}) catch return error.UpdateNoExePath);
        return error.UpdateNoExePath;
    }
    const exe_path = try wideToUtf8(allocator, exe_wide_buf[0..exe_len]);
    defer allocator.free(exe_path);
    const exe_dir = std.fs.path.dirname(exe_path) orelse return error.UpdateNoExePath;

    var local_buf: [256]u16 = undefined;
    const local_len: usize = @intCast(win.GetEnvironmentVariableW(lit("LOCALAPPDATA"), &local_buf, local_buf.len));
    if (local_len == 0 or local_len >= local_buf.len) return error.UpdateNoLocalAppData;
    const local_dir = try wideToUtf8(allocator, local_buf[0..local_len]);
    defer allocator.free(local_dir);
    const update_root = try std.fmt.allocPrint(allocator, "{s}\\Wazig\\update", .{local_dir});
    defer allocator.free(update_root);

    const cwd = std.Io.Dir.cwd();
    const root = try cwd.createDirPathOpen(io, update_root, .{});
    defer root.close(io);

    clearStaleOrphans();
    const exe_name = std.fs.path.basename(exe_path);
    {
        const exe_old = try std.fmt.allocPrint(allocator, "{s}\\{s}.old", .{ exe_dir, exe_name });
        defer allocator.free(exe_old);
        const exe_new = try std.fmt.allocPrint(allocator, "{s}\\{s}.new", .{ exe_dir, exe_name });
        defer allocator.free(exe_new);
        const exe_old_wide = try utf8ToWide(allocator, exe_old);
        defer allocator.free(exe_old_wide);
        const exe_new_wide = try utf8ToWide(allocator, exe_new);
        defer allocator.free(exe_new_wide);
        const exe_here_wide = try utf8ToWide(allocator, exe_path);
        defer allocator.free(exe_here_wide);
        const exe_here = filePresentLookup(exe_here_wide.ptr) orelse return error.UpdateSwapStateUnknown;
        if (!exe_here) {
            const new_there = filePresentLookup(exe_new_wide.ptr) orelse return error.UpdateSwapStateUnknown;
            const old_there = filePresentLookup(exe_old_wide.ptr) orelse return error.UpdateSwapStateUnknown;
            const source = update.restoreSource(new_there, old_there) orelse return error.UpdateSwapRestoreFailed;
            const first: [:0]const u16 = switch (source) {
                .replacement => exe_new_wide,
                .backup => exe_old_wide,
            };
            const fallback: ?[:0]const u16 = switch (source) {
                .replacement => if (old_there) exe_old_wide else null,
                .backup => if (new_there) exe_new_wide else null,
            };
            if (!restoreExeFile(first, exe_here_wide) and
                (fallback == null or !restoreExeFile(fallback.?, exe_here_wide)))
            {
                return error.UpdateSwapRestoreFailed;
            }
        }
        const old_there = filePresentLookup(exe_old_wide.ptr) orelse return error.UpdateSwapStateUnknown;
        if (old_there and win.DeleteFileW(exe_old_wide.ptr) == 0) {
            clearStaleOrphans();
            _ = win.DeleteFileW(exe_old_wide.ptr);
            if (filePresentLookup(exe_old_wide.ptr) != false) return error.UpdateOldBackupLocked;
        }
        _ = win.DeleteFileW(exe_new_wide.ptr);
    }

    const marker_text: ?[]u8 = root.readFileAlloc(io, "ready.txt", allocator, .limited(512)) catch null;
    defer if (marker_text) |text| allocator.free(text);
    const marker = if (marker_text) |text| update.parseStageMarker(text) else null;
    const staged = if (marker) |m| update.isNewer(m.tag, current) else false;
    if (staged and !stage_only) {
        const stage = try root.createDirPathOpen(io, "stage", .{ .open_options = .{ .iterate = true } });
        defer stage.close(io);
        return swapStaged(io, allocator, root, stage, update_root, exe_path, exe_dir, exe_name, marker.?.inner_root);
    }

    const api_headers = try utf8ToWide(allocator, "User-Agent: Messages updater\r\nAccept: application/vnd.github+json\r\n");
    defer allocator.free(api_headers);
    const json = try httpGet(allocator, lit("api.github.com"), lit("/repos/valentinyeo/wazig/releases/latest"), api_headers.ptr, 4 * 1024 * 1024, win.INTERNET_DEFAULT_HTTPS_PORT, true, true);
    defer allocator.free(json);

    var parsed: std.json.Parsed(std.json.Value) = undefined;
    const maybe_asset = try update.pickAsset(allocator, json, &parsed);
    defer parsed.deinit();
    const asset = maybe_asset orelse return .none;
    if (!update.isNewer(asset.tag, current)) return .none;
    if (stage_only and staged and std.mem.eql(u8, marker.?.tag, asset.tag)) return .staged;
    root.deleteFile(io, "ready.txt") catch {};
    root.deleteTree(io, "stage") catch {};

    const asset_url = try utf8ToWide(allocator, asset.url);
    defer allocator.free(asset_url);
    const download_headers = try utf8ToWide(allocator, "User-Agent: Messages updater\r\n");
    defer allocator.free(download_headers);
    update_dl_done.store(0, .release);
    update_dl_total.store(asset.size, .release);
    update_dl_active.store(true, .release);
    const body = httpGetUrl(allocator, asset_url, download_headers.ptr, update_max_asset_bytes) catch |err| {
        update_dl_active.store(false, .release);
        return err;
    };
    update_dl_active.store(false, .release);
    defer allocator.free(body);
    if (asset.size != 0 and body.len != asset.size) return error.UpdateSizeMismatch;
    if (!update.digestMatches(body, asset.digest)) return error.UpdateDigestMismatch;

    {
        const zip_file = try root.createFile(io, "Messages.zip", .{});
        defer zip_file.close(io);
        var buffer: [64 * 1024]u8 = undefined;
        var zip_writer = zip_file.writer(io, &buffer);
        try zip_writer.interface.writeAll(body);
        try zip_writer.interface.flush();
    }
    const stage = try root.createDirPathOpen(io, "stage", .{ .open_options = .{ .iterate = true } });
    defer stage.close(io);
    {
        const scan_file = try root.openFile(io, "Messages.zip", .{});
        defer scan_file.close(io);
        var scan_buffer: [64 * 1024]u8 align(16) = undefined;
        var scan_reader = scan_file.reader(io, &scan_buffer);
        var scan = try std.zip.Iterator.init(&scan_reader);
        var entry_count: u64 = 0;
        var total_uncompressed: u64 = 0;
        while (try scan.next()) |entry| {
            entry_count += 1;
            if (entry_count > 4096) return error.UpdateZipTooLarge;
            total_uncompressed += entry.uncompressed_size;
            if (entry.uncompressed_size > 512 * 1024 * 1024 or total_uncompressed > 512 * 1024 * 1024) return error.UpdateZipTooLarge;
        }
    }
    var diagnostics: std.zip.Diagnostics = .{ .allocator = allocator };
    defer diagnostics.deinit();
    {
        const zip_file = try root.openFile(io, "Messages.zip", .{});
        defer zip_file.close(io);
        var buffer: [64 * 1024]u8 align(16) = undefined;
        var zip_reader = zip_file.reader(io, &buffer);
        try std.zip.extract(stage, &zip_reader, .{ .diagnostics = &diagnostics });
    }

    const inner_root = if (diagnostics.root_dir.len > 0) diagnostics.root_dir else "";
    if (stage_only) {
        const marker_line = try std.fmt.allocPrint(allocator, "{s}\n{s}\n", .{ asset.tag, inner_root });
        defer allocator.free(marker_line);
        try root.writeFile(io, .{ .sub_path = "ready.txt", .data = marker_line });
        return .staged;
    }
    return swapStaged(io, allocator, root, stage, update_root, exe_path, exe_dir, exe_name, inner_root);
}

fn swapStaged(
    io: std.Io,
    allocator: std.mem.Allocator,
    root: std.Io.Dir,
    stage: std.Io.Dir,
    update_root: []const u8,
    exe_path: []const u8,
    exe_dir: []const u8,
    exe_name: []const u8,
    inner_root: []const u8,
) !UpdateOutcome {
    const new_exe_rel = if (inner_root.len > 0)
        try std.fmt.allocPrint(allocator, "{s}/{s}", .{ inner_root, exe_name })
    else
        try allocator.dupe(u8, exe_name);
    defer allocator.free(new_exe_rel);
    const staged_exe_size = (try stage.statFile(io, new_exe_rel, .{})).size;

    var pending: std.ArrayList(SwapPending) = .empty;
    defer {
        for (pending.items) |p| {
            allocator.free(p.temp);
            allocator.free(p.dest);
        }
        pending.deinit(allocator);
    }
    const stage_path = try std.fmt.allocPrint(allocator, "{s}\\stage", .{update_root});
    defer allocator.free(stage_path);
    if (!copyStagedFiles(io, allocator, stage, stage_path, inner_root, exe_dir, &pending)) return error.UpdateCopyFailed;

    const exe_wide = try utf8ToWide(allocator, exe_path);
    defer allocator.free(exe_wide);
    var exe_index: ?usize = null;
    for (pending.items, 0..) |p, i| {
        if (eqlWideIgnoreCase(p.dest, exe_wide)) exe_index = i;
    }
    if (exe_index == null) logUpdateSwapDetail(exe_path, pending.items);
    const exe_i = exe_index orelse return error.UpdateNoExePath;
    const exe_temp = pending.items[exe_i].temp;

    if (!update.replacementVerified(staged_exe_size, wideFileSize(exe_temp))) return error.UpdateCopyFailed;

    const exe_old = try std.fmt.allocPrint(allocator, "{s}\\{s}.old", .{ exe_dir, exe_name });
    defer allocator.free(exe_old);
    const exe_old_wide = try utf8ToWide(allocator, exe_old);
    defer allocator.free(exe_old_wide);
    if (win.MoveFileExW(exe_wide.ptr, exe_old_wide.ptr, win.MOVEFILE_REPLACE_EXISTING) == 0) {
        clearStaleOrphans();
        if (win.MoveFileExW(exe_wide.ptr, exe_old_wide.ptr, win.MOVEFILE_REPLACE_EXISTING) == 0) return error.UpdateSwapFailed;
    }
    if (!restoreExeFile(exe_temp, exe_wide)) {
        if (!restoreExeFile(exe_old_wide, exe_wide)) return error.UpdateSwapRestoreFailed;
        return error.UpdateCopyFailed;
    }
    for (pending.items, 0..) |p, i| {
        if (i == exe_i) continue;
        if (!swapFileIntoPlace(p.temp, p.dest)) {
            if (wideToUtf8(allocator, p.dest)) |dest_utf8| {
                defer allocator.free(dest_utf8);
                var detail_buf: [600]u8 = undefined;
                if (std.fmt.bufPrint(&detail_buf, "swap detail: support rename failed: {s}\r\n", .{dest_utf8}) catch null) |line| {
                    appendUpdateLogLine(line);
                }
            } else |_| {}
            for (pending.items, 0..) |q, j| {
                if (j != i and j != exe_i) _ = win.DeleteFileW(q.temp.ptr);
            }
            _ = restoreExeFile(exe_old_wide, exe_wide);
            return error.UpdateCopyFailed;
        }
    }
    _ = win.DeleteFileW(exe_old_wide.ptr);
    root.deleteFile(io, "ready.txt") catch {};
    root.deleteTree(io, "stage") catch {};
    root.deleteFile(io, "Messages.zip") catch {};
    return .installed;
}

const SwapPending = struct { temp: [:0]u16, dest: [:0]u16 };

fn restoreExeFile(source: [:0]const u16, dest: [:0]const u16) bool {
    if (win.MoveFileExW(source.ptr, dest.ptr, win.MOVEFILE_REPLACE_EXISTING) != 0) return true;
    const suffix = ".restore-tmp";
    var tmp_buf: [519 + suffix.len]u16 = undefined;
    if (dest.len + suffix.len >= tmp_buf.len) return false;
    @memcpy(tmp_buf[0..dest.len], dest);
    for (suffix, 0..) |c, i| tmp_buf[dest.len + i] = c;
    tmp_buf[dest.len + suffix.len] = 0;
    const tmp = tmp_buf[0 .. dest.len + suffix.len :0];
    if (win.CopyFileW(source.ptr, tmp.ptr, win.FALSE) == 0) return false;
    if (win.MoveFileExW(tmp.ptr, dest.ptr, win.MOVEFILE_REPLACE_EXISTING) == 0) {
        _ = win.DeleteFileW(tmp.ptr);
        return false;
    }
    return true;
}

fn swapFileIntoPlace(temp: [:0]const u16, dest: [:0]const u16) bool {
    if (win.MoveFileExW(temp.ptr, dest.ptr, win.MOVEFILE_REPLACE_EXISTING) != 0) return true;
    const suffix = ".old";
    var old_buf: [519 + suffix.len]u16 = undefined;
    if (dest.len + suffix.len >= old_buf.len) return false;
    @memcpy(old_buf[0..dest.len], dest[0..dest.len]);
    for (suffix, 0..) |c, i| old_buf[dest.len + i] = c;
    old_buf[dest.len + suffix.len] = 0;
    const old_path = old_buf[0 .. dest.len + suffix.len :0];
    if (win.MoveFileExW(dest.ptr, old_path.ptr, win.MOVEFILE_REPLACE_EXISTING) == 0) return false;
    if (win.MoveFileExW(temp.ptr, dest.ptr, win.MOVEFILE_REPLACE_EXISTING) == 0) {
        _ = win.MoveFileExW(old_path.ptr, dest.ptr, win.MOVEFILE_REPLACE_EXISTING);
        return false;
    }
    _ = win.DeleteFileW(old_path.ptr);
    return true;
}

fn wideFileSize(path_wide: [*:0]const u16) ?u64 {
    var info: win.WIN32_FILE_ATTRIBUTE_DATA = undefined;
    if (win.GetFileAttributesExW(path_wide, win.GetFileExInfoStandard, &info) == 0) return null;
    const high: u64 = info.nFileSizeHigh;
    return (high << 32) | info.nFileSizeLow;
}

fn copyStagedFiles(
    io: std.Io,
    allocator: std.mem.Allocator,
    stage: std.Io.Dir,
    stage_path: []const u8,
    inner_root: []const u8,
    exe_dir: []const u8,
    pending: *std.ArrayList(SwapPending),
) bool {
    var walker = stage.walk(allocator) catch return false;
    defer walker.deinit();
    while (walker.next(io) catch return false) |entry| {
        if (entry.kind != .file) continue;
        const relative = if (inner_root.len > 0 and std.mem.startsWith(u8, entry.path, inner_root))
            entry.path[inner_root.len + 1 ..]
        else
            entry.path;
        var relative_buf: [512]u8 = undefined;
        if (relative.len >= relative_buf.len) return false;
        for (relative, 0..) |c, i| relative_buf[i] = if (c == '\\') '/' else c;
        const normalized = relative_buf[0..relative.len];
        var components = std.mem.splitScalar(u8, normalized, '/');
        while (components.next()) |component| {
            if (std.mem.eql(u8, component, "..")) return false;
        }
        var windows_relative_buf: [512]u8 = undefined;
        for (normalized, 0..) |c, i| windows_relative_buf[i] = if (c == '/') '\\' else c;
        const windows_relative = windows_relative_buf[0..normalized.len];
        const destination = std.fmt.allocPrint(allocator, "{s}\\{s}", .{ exe_dir, windows_relative }) catch return false;
        defer allocator.free(destination);
        if (std.fs.path.dirname(destination)) |parent| {
            var depth: usize = 0;
            while (depth < parent.len) : (depth += 1) {
                if (parent[depth] == '\\') {
                    const prefix_wide = utf8ToWide(allocator, parent[0..depth]) catch return false;
                    defer allocator.free(prefix_wide);
                    _ = win.CreateDirectoryW(prefix_wide.ptr, null);
                }
            }
            const parent_wide = utf8ToWide(allocator, parent) catch return false;
            defer allocator.free(parent_wide);
            _ = win.CreateDirectoryW(parent_wide.ptr, null);
        }
        const source = std.fmt.allocPrint(allocator, "{s}\\{s}", .{ stage_path, entry.path }) catch return false;
        defer allocator.free(source);
        const source_wide = utf8ToWide(allocator, source) catch return false;
        defer allocator.free(source_wide);
        const destination_wide = utf8ToWide(allocator, destination) catch return false;
        const temp = std.fmt.allocPrint(allocator, "{s}.new", .{destination}) catch return false;
        defer allocator.free(temp);
        const temp_wide = utf8ToWide(allocator, temp) catch return false;
        if (win.CopyFileW(source_wide.ptr, temp_wide.ptr, win.FALSE) == 0) return false;
        pending.append(allocator, .{ .temp = temp_wide, .dest = destination_wide }) catch return false;
    }
    return true;
}

fn relaunchIntoUpdate(a: *App) void {
    var exe_buf: [519]u16 = undefined;
    const exe_len: usize = @intCast(win.GetModuleFileNameW(null, &exe_buf, exe_buf.len));
    if (exe_len == 0 or exe_len >= exe_buf.len) {
        setStatus(a, "Update installed - restart the app to finish");
        return;
    }
    exe_buf[exe_len] = 0;
    var startup: win.STARTUPINFOW = std.mem.zeroes(win.STARTUPINFOW);
    startup.cb = @sizeOf(win.STARTUPINFOW);
    var process: win.PROCESS_INFORMATION = std.mem.zeroes(win.PROCESS_INFORMATION);
    appendLaunchLog(a, "update: relaunching");
    var command_template: [600]u16 = [_]u16{0} ** 600;
    command_template[0] = '"';
    @memcpy(command_template[1..][0..exe_len], exe_buf[0..exe_len]);
    const suffix = std.mem.span(lit("\" --update-relaunch"));
    @memcpy(command_template[exe_len + 1 ..][0..suffix.len], suffix);
    if (a.hwnd) |hwnd| saveWindowRect(hwnd);
    saveComposerDraft(a);
    persistDrafts(a);
    var command_line = command_template;
    var launched = win.CreateProcessW(exe_buf[0..exe_len :0].ptr, &command_line, null, null, win.FALSE, 0, null, null, &startup, &process) != 0;
    if (!launched) {
        process = std.mem.zeroes(win.PROCESS_INFORMATION);
        command_line = command_template;
        launched = win.CreateProcessW(exe_buf[0..exe_len :0].ptr, &command_line, null, null, win.FALSE, 0, null, null, &startup, &process) != 0;
    }
    if (launched) {
        _ = win.CloseHandle(process.hProcess);
        _ = win.CloseHandle(process.hThread);
        _ = win.PostQuitMessage(0);
    } else {
        setStatus(a, "Update installed - restart the app to finish");
    }
}

