test "wrapChunkLen breaks long words at punctuation then characters" {
    const Case = struct { word: []const u16, fit: usize, want: usize };
    const cases = [_]Case{
        .{ .word = &[_]u16{ 'a', 'b', 'c', 'd', 'e' }, .fit = 3, .want = 3 },
        .{ .word = &[_]u16{ 'a', 'b', '/', 'c', 'd' }, .fit = 4, .want = 3 },
        .{ .word = &[_]u16{ 'a', '/', 'b', '/', 'c' }, .fit = 5, .want = 4 },
        .{ .word = &[_]u16{ 'h', 't', 't', 'p', 's', ':', '/', '/', 'x' }, .fit = 8, .want = 8 },
        .{ .word = &[_]u16{ 'x', 'y' }, .fit = 0, .want = 1 },
        .{ .word = &[_]u16{}, .fit = 5, .want = 1 },
    };
    for (cases) |case| {
        try std.testing.expectEqual(case.want, wrapChunkLen(case.word, case.fit));
    }
}

test "wrapChunkLen keeps surrogate pairs and joiners whole" {
    const Case = struct { word: []const u16, fit: usize, want: usize };
    const cases = [_]Case{
        .{ .word = &[_]u16{ 'a', 0xD83D, 0xDC69, 'b' }, .fit = 2, .want = 1 },
        .{ .word = &[_]u16{ 'x', 0xD83D, 0xDC69 }, .fit = 2, .want = 1 },
        .{ .word = &[_]u16{ 0xD83D, 0xDC69 }, .fit = 1, .want = 2 },
        .{ .word = &[_]u16{ 0xD83D, 0xDC69, 'a' }, .fit = 0, .want = 2 },
        .{ .word = &[_]u16{ 'a', 'b', 0x200D, 0xD83D, 0xDC69 }, .fit = 2, .want = 1 },
        .{ .word = &[_]u16{ 0xD83D, 0xDC69, 0x200D, 0xD83C, 0xDFA9 }, .fit = 2, .want = 2 },
        .{ .word = &[_]u16{ '1', 0x20E3, 'x' }, .fit = 1, .want = 1 },
        .{ .word = &[_]u16{ 'a', 0xFE0F, 'b' }, .fit = 1, .want = 1 },
        .{ .word = &[_]u16{ 0xD83D, 0xDC69, 0x200D, 0xD83C, 0xDFA9 }, .fit = 5, .want = 5 },
    };
    for (cases) |case| {
        try std.testing.expectEqual(case.want, wrapChunkLen(case.word, case.fit));
    }
    try std.testing.expectEqual(@as(usize, 1), wrapChunkLen(&[_]u16{0xD83D}, 1));
}

test "splitRuns sends surrogate-pair emoji to the colour path" {
    var runs: [8]TextRun = undefined;
    const mixed = [_]u16{ 'h', 'i', ' ', 0xD83D, 0xDE00, ' ', 'o', 'k', ' ', 0x2764 };
    const count = splitRuns(&mixed, &runs);
    try std.testing.expectEqual(@as(usize, 4), count);
    try std.testing.expect(runs[1].emoji);
    try std.testing.expectEqual(@as(usize, 3), runs[1].start);
    try std.testing.expectEqual(@as(usize, 2), runs[1].len);
    try std.testing.expect(runs[3].emoji);
    try std.testing.expect(containsEmoji(&mixed));

    const zwj = [_]u16{ 0xD83D, 0xDC69, 0x200D, 0xD83C, 0xDFA9 };
    try std.testing.expectEqual(@as(usize, 1), splitRuns(&zwj, &runs));
    try std.testing.expect(runs[0].emoji);
    try std.testing.expectEqual(@as(usize, 5), runs[0].len);

    const math = [_]u16{ 0xD835, 0xDC00, 'x' };
    try std.testing.expectEqual(@as(usize, 1), splitRuns(&math, &runs));
    try std.testing.expect(!runs[0].emoji);
    try std.testing.expect(!containsEmoji(&math));
}

fn unifiedHub(a: *const App) bool {
    return a.unified_hub;
}

fn hubConfigured(a: *const App) bool {
    return unifiedHub(a) or (wa_hub.igsh_532_hub_whatsapp and a.hub_client != null);
}

fn hubMediaPath(a: *App, allocator: std.mem.Allocator, key: chat_key.Key, id: []const u8) ![]u8 {
    const cache_key = if (unifiedHub(a)) chat_key.Key{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = key.id } else key;
    const name = try wa_hub.cacheName(allocator, cache_key, id);
    return std.fs.path.join(allocator, &.{ std.fs.path.dirname(a.avatar_dir) orelse return error.MissingMessagesDir, "hub-media", name });
}

fn hubNormalized(a: *App, allocator: std.mem.Allocator, job: *const WacliJob, raw: []const u8, kind: wa_hub.Rows, jid: []const u8) ![]u8 {
    const normalized = if (unifiedHub(a)) try hub.normalize(allocator, raw, kind, jid) else try wa_hub.normalize(allocator, raw, job.hub_account.slice(), kind);
    if (kind != .messages) return normalized;
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, normalized, .{});
    defer parsed.deinit();
    const rows = parsed.value.object.getPtr("data").?.object.getPtr("messages").?;
    if (unifiedHub(a)) cacheSlackEmoji(a, allocator, jid, rows.array.items) catch {};
    for (rows.array.items) |*row| {
        const id = getString(row.object, "MsgID");
        const path = try hubMediaPath(a, allocator, .{ .provider = .whatsapp, .account = job.account.slice(), .id = jid }, id);
        var local_path: []const u8 = if (fileExistsUtf8(path)) path else "";
        if (local_path.len > 0) {
            const extension = wa_hub.mediaExtension(getString(row.object, "Filename"), getString(row.object, "MimeType"), getString(row.object, "MediaType"));
            if (!std.mem.eql(u8, extension, ".bin")) {
                const alias = try std.fmt.allocPrint(allocator, "{s}{s}", .{ path, extension });
                if (!fileExistsUtf8(alias)) {
                    const source = try std.unicode.utf8ToUtf16LeAllocZ(allocator, path);
                    const target = try std.unicode.utf8ToUtf16LeAllocZ(allocator, alias);
                    const copied = win.CreateHardLinkW(target.ptr, source.ptr, null) != 0 or win.CopyFileW(source.ptr, target.ptr, win.TRUE) != 0;
                    if (copied) slack_win.markDownloaded(allocator, alias);
                }
                if (fileExistsUtf8(alias)) local_path = alias;
            }
        }
        try row.object.put(allocator, "LocalPath", .{ .string = local_path });
    }
    return std.json.Stringify.valueAlloc(allocator, parsed.value, .{});
}

fn cacheSlackEmoji(a: *App, allocator: std.mem.Allocator, jid: []const u8, rows: []std.json.Value) !void {
    const scope = hub.workspaceAvatarKey(jid) orelse return;
    const account = scope[6 .. scope.len - 1];
    var needed = false;
    for (rows) |row| {
        for ([_][]const u8{ "Text", "DisplayText", "ReactionEmoji" }) |field| {
            const text = getString(row.object, field);
            var cursor: usize = 0;
            while (slack_emoji.next(text, cursor)) |token| {
                cursor = token.end;
                if (slack_emoji.standard(token.name) == null) needed = true;
            }
        }
    }
    if (!needed) return;
    const client = a.hub_client orelse return;
    const index_path = try hubMediaPath(a, allocator, .{ .provider = .slack, .account = account, .id = scope }, "emoji-index-v1");
    const wide = try std.unicode.utf8ToUtf16LeAllocZ(allocator, index_path);
    const stamp = fileStampSecs(wide.ptr);
    var raw = if (stamp != null and nowUnixSeconds() - stamp.? < 3600) readFileWin(allocator, index_path, 4 * 1024 * 1024) else null;
    if (raw == null) {
        const response = try client.call(allocator, try hub.slackEmoji(allocator, account, null));
        if (response.status != 200 or response.body.len > 4 * 1024 * 1024) return;
        raw = response.body;
        _ = writeCacheFileAtomic(a, index_path, response.body);
    }
    var parsed = try std.json.parseFromSlice(std.json.Value, allocator, raw.?, .{});
    defer parsed.deinit();
    if (parsed.value != .object) return;
    const emoji = parsed.value.object.get("emoji") orelse return;
    if (emoji != .object) return;
    for (rows) |*row| {
        var paths: std.json.ObjectMap = .empty;
        for ([_][]const u8{ "Text", "DisplayText", "ReactionEmoji" }) |field| {
            const text = getString(row.object, field);
            var cursor: usize = 0;
            while (slack_emoji.next(text, cursor)) |token| {
                cursor = token.end;
                if (slack_emoji.standard(token.name) != null or paths.contains(token.name)) continue;
                const name = slack_emoji.customName(emoji.object, token.name) orelse continue;
                const value = getString(emoji.object, name);
                if (slack_emoji.standard(name)) |unicode| {
                    try paths.put(allocator, token.name, .{ .string = unicode });
                    continue;
                }
                if (!std.mem.startsWith(u8, value, "https://") and !std.mem.startsWith(u8, value, "http://")) continue;
                const cache_id = try std.fmt.allocPrint(allocator, "emoji:{s}:{x}", .{ name, std.hash.Wyhash.hash(0, value) });
                const path = try hubMediaPath(a, allocator, .{ .provider = .slack, .account = account, .id = scope }, cache_id);
                if (!fileExistsUtf8(path)) {
                    const response = client.call(allocator, try hub.slackEmoji(allocator, account, name)) catch continue;
                    if (response.status != 200 or response.body.len > 1024 * 1024) continue;
                    if (!writeCacheFileAtomic(a, path, response.body)) continue;
                }
                try paths.put(allocator, token.name, .{ .string = path });
            }
        }
        try row.object.put(allocator, "SlackEmojiPaths", .{ .object = paths });
    }
}

fn hubArg(job: *const WacliJob, name: []const u8, default: []const u8) []const u8 {
    for (job.args[0..job.arg_count], 0..) |*arg, index| {
        if (std.mem.eql(u8, arg.slice(), name) and index + 1 < job.arg_count) return job.args[index + 1].slice();
    }
    return default;
}

fn hubHasArg(job: *const WacliJob, name: []const u8) bool {
    for (job.args[0..job.arg_count]) |*arg| if (std.mem.eql(u8, arg.slice(), name)) return true;
    return false;
}

fn runHubJob(a: *App, job: WacliJob, result: *WacliResult) void {
    var arena = std.heap.ArenaAllocator.init(a.allocator);
    defer arena.deinit();
    const data = executeHubJob(a, arena.allocator(), &job, result) catch |err| {
        if (result.extra.len == 0) result.extra.set(@errorName(err));
        return;
    };
    result.data = a.allocator.dupe(u8, data) catch return;
    result.ok = true;
}

fn executeHubJob(a: *App, allocator: std.mem.Allocator, job: *const WacliJob, result: *WacliResult) ![]const u8 {
    const client = a.hub_client orelse return error.HubNotConfigured;
    if (job.kind != .cache_tag and job.hub_account.len == 0) return error.AccountNotReady;
    const key = chat_key.Key{ .provider = .whatsapp, .account = job.hub_account.slice(), .id = job.jid.slice() };
    if (unifiedHub(a) and job.kind == .cache_tag) return "[{\"account\":\"hub\",\"state\":\"linked\"}]";
    if (unifiedHub(a) and job.kind == .groups) return "{\"success\":true,\"data\":[]}";
    const request: wa_hub.Request = if (unifiedHub(a) and job.kind == .hub_thread)
        try hub.messages(allocator, job.jid.slice(), 80, job.extra.slice())
    else if (unifiedHub(a) and job.kind == .hub_older)
        try hub.messages(allocator, job.jid.slice(), hub.older_limit, try hub.beforeCursor(allocator, job.msg_id.slice(), job.extra.slice()))
    else if (unifiedHub(a))
        try unifiedHubRequest(a, allocator, job)
    else switch (job.kind) {
        .cache_tag => wa_hub.accounts(),
        .chats, .archived_scan, .kept_check, .contacts_index => try wa_hub.chats(allocator, key.account, hubHasArg(job, "--archived"), 500),
        .messages, .background_media => try wa_hub.messages(allocator, key, std.fmt.parseInt(usize, hubArg(job, "--limit", "80"), 10) catch 80, ""),
        .unread_probe => try wa_hub.messages(allocator, key, 20, ""),
        .groups => try wa_hub.list(allocator, key.account, .groups),
        .reaction => try wa_hub.react(allocator, key, job.msg_id.slice(), job.extra.slice(), job.client_id.slice()),
        .hub_send => blk: {
            if (job.args[1].len == 0) break :blk try wa_hub.send(allocator, key, job.args[0].slice(), job.args[2].slice(), job.msg_id.slice());
            const bytes = readFileWin(allocator, job.args[1].slice(), wa_hub.max_file_bytes) orelse return error.FileReadFailed;
            var random: [16]u8 = undefined;
            a.io.random(&random);
            const boundary = std.fmt.bytesToHex(random, .lower);
            break :blk try wa_hub.sendFile(allocator, key, job.args[0].slice(), job.args[2].slice(), job.msg_id.slice(), std.fs.path.basename(job.args[1].slice()), bytes, std.mem.eql(u8, job.args[3].slice(), "true"), &boundary);
        },
        .hub_read => try wa_hub.markRead(allocator, key),
        .hub_archive => try wa_hub.archive(allocator, key, std.mem.eql(u8, job.extra.slice(), "true")),
        .hub_media => try wa_hub.binary(allocator, key, job.msg_id.slice()),
        .hub_avatar => try wa_hub.binary(allocator, key, null),
        else => return error.UnsupportedHubAction,
    };
    const response = try client.call(allocator, request);
    result.http_status = response.status;
    if (job.kind == .hub_media) {
        if (unifiedHub(a) and response.status == 206) return error.PartialMedia;
        switch (try wa_hub.mediaState(response.status)) {
            .pending => return "",
            .unavailable => return error.MediaUnavailable,
            .ready => {
                const path = try hubMediaPath(a, allocator, .{ .provider = .whatsapp, .account = job.account.slice(), .id = key.id }, job.msg_id.slice());
                if (!writeCacheFileAtomic(a, path, response.body)) return error.MediaCacheWriteFailed;
                slack_win.markDownloaded(allocator, path);
                return path;
            },
        }
    }
    if (unifiedHub(a) and job.kind == .hub_send and std.mem.startsWith(u8, job.jid.slice(), "signal:")) {
        if (hub.signalSendFailure(allocator, response.status, response.body)) |reason| {
            result.extra.set(reason);
            return error.SignalSendRejected;
        }
    }
    if (unifiedHub(a) and job.kind == .hub_send and std.mem.startsWith(u8, job.jid.slice(), "telegram:")) {
        if (hub.telegramSendFailure(allocator, response.status, response.body)) |reason| {
            result.extra.set(reason);
            return error.TelegramSendRejected;
        }
    }
    if (response.status < 200 or response.status >= 300) return error.HubHttpFailed;
    if (job.kind == .hub_avatar) {
        if (!writeCacheFileAtomic(a, job.args[0].slice(), response.body)) return error.AvatarCacheWriteFailed;
        return "";
    }
    if (job.kind == .hub_send or job.kind == .reaction) {
        var reply = try wa_hub.parseSend(allocator, response.body);
        defer reply.deinit();
        const client_id = if (job.kind == .hub_send) job.msg_id.slice() else job.client_id.slice();
        if (!std.mem.eql(u8, reply.value.client_id, client_id) or !std.mem.eql(u8, reply.value.status, "sent")) return error.SendNotConfirmed;
        return "";
    }
    if (job.kind == .chats and hubHasArg(job, "--include-archived")) {
        const archived_request = if (unifiedHub(a)) try hub.chats(allocator, true, 500) else try wa_hub.chats(allocator, key.account, true, 500);
        const archived = try client.call(allocator, archived_request);
        if (archived.status != 200) return error.HubHttpFailed;
        const normal_data = try hubNormalized(a, allocator, job, response.body, .chats, "");
        const archived_data = try hubNormalized(a, allocator, job, archived.body, .chats, "");
        return messenger_view.mergeChatData(allocator, normal_data, archived_data);
    }
    if (unifiedHub(a) and job.kind == .chats and hubHasArg(job, "--archived")) {
        const inbox = try client.call(allocator, try hub.chats(allocator, false, 500));
        if (inbox.status != 200) return error.HubHttpFailed;
        return hub.archivedChats(allocator, response.body, inbox.body);
    }
    return switch (job.kind) {
        .chats, .archived_scan, .kept_check, .contacts_index => hubNormalized(a, allocator, job, response.body, .chats, ""),
        .groups => hubNormalized(a, allocator, job, response.body, .groups, ""),
        .messages, .unread_probe, .background_media, .hub_thread, .hub_older => hubNormalized(a, allocator, job, response.body, .messages, key.id),
        else => response.body,
    };
}

fn applyHubAccounts(a: *App, result: *const WacliResult) void {
    a.startup_probe_pending = false;
    if (!result.ok) {
        setStatus(a, if (unifiedHub(a)) "Message hub configuration unavailable" else "Unable to read WhatsApp hub accounts");
        return;
    }
    var hub_accounts = wa_hub.parseAccounts(a.allocator, result.data) catch return;
    defer hub_accounts.deinit();
    const selected = if (unifiedHub(a)) null else wa_hub.pickAccount(hub_accounts.value, a.wa_bridge_account);
    for (hub_accounts.value) |account| {
        if (!std.mem.eql(u8, account.state, "linked") or account.account.len == 0 or account.account.len > 32) continue;
        if (a.hub_account.len > 0 and !std.mem.eql(u8, a.hub_account.slice(), account.account)) continue;
        const first_account = a.hub_account.len == 0;
        if (first_account or unifiedHub(a)) {
            if (selected) |account_name| {
                if (!std.mem.eql(u8, account.account, account_name)) continue;
            }
            const hash = std.hash.Wyhash.hash(std.hash.Wyhash.hash(0, a.wa_bridge_url), account.account);
            var tag_buffer: [16]u8 = undefined;
            const tag = std.fmt.bufPrint(&tag_buffer, "{x:0>16}", .{hash}) catch return;
            a.wacli_mutex.lockUncancelable(a.io);
            a.hub_account.set(account.account);
            a.cache_tag.set(tag);
            a.wacli_mutex.unlock(a.io);
            persistTag(a, tag);
            bindOutboxAccount(a);
            if (first_account) loadChatsCache(a);
        }
        a.sync_logged_out = false;
        refreshGroups(a);
        refreshChats(a);
        refreshContactsIndex(a);
        refreshMessages(a);
        setStatus(a, if (unifiedHub(a)) "Message hub connected" else "WhatsApp hub connected");
        return;
    }
    setStatus(a, "No linked WhatsApp hub account");
}

fn startHubSend(a: *App, pending: *const PendingSend) void {
    if (wacliPendingGet(a, .hub_send) > 0) return;
    var job = WacliJob{ .kind = .hub_send, .provider = pending.provider, .account = pending.account, .jid = pending.jid };
    job.msg_id.set(&pending.id);
    wacliJobArgs(&job, &.{ pending.text.slice(), pending.file.slice(), pending.reply_to.slice(), if (pending.ptt) "true" else "false" });
    _ = wacliEnqueue(a, job, true);
}

fn startHubMarkRead(a: *App) void {
    if (a.hub_account.len == 0 or a.pending_read_count == 0 or wacliPendingGet(a, .hub_read) > 0 or a.read_backoff_until[0] > win.GetTickCount64()) return;
    const jid = a.pending_reads[0].slice();
    if (unifiedHub(a) and (std.mem.startsWith(u8, jid, "signal:") or std.mem.startsWith(u8, jid, "telegram:"))) {
        const key = chat_key.Key{ .provider = if (std.mem.startsWith(u8, jid, "telegram:")) .telegram else .signal, .account = a.cache_tag.slice(), .id = jid };
        const disk = if (msgCacheGet(a, key) == null) loadMsgCacheDisk(a, jid) else null;
        defer if (disk) |data| a.allocator.free(data);
        const raw = msgCacheGet(a, key) orelse disk orelse return;
        const message_id = hub.readMessageId(a.allocator, raw) catch |err| {
            if (err == error.NoIncomingMessage) removeFirstPendingRead(a);
            return;
        };
        defer a.allocator.free(message_id);
        hubTransport(a).markRead(jid, message_id);
    } else hubTransport(a).markRead(jid, "");
}

fn startHubArchive(a: *App) void {
    if (a.hub_account.len == 0 or a.pending_archive_count == 0 or wacliPendingGet(a, .hub_archive) > 0 or a.pending_archives[0].retry_at_ms > win.GetTickCount64()) return;
    _ = hubTransport(a).archive(a.pending_archives[0].jid.slice(), !a.pending_archives[0].should_unarchive);
}

fn enqueueHubMedia(a: *App, slot: *MediaDownload) bool {
    const job = WacliJob{ .kind = .hub_media, .account = a.cache_tag, .jid = slot.jid, .msg_id = slot.id };
    if (!wacliEnqueue(a, job, false)) return false;
    slot.hub_pending = true;
    slot.hub_retry_ms = 0;
    return true;
}

fn startHubMedia(a: *App, jid: []const u8, id: []const u8) bool {
    if (a.hub_account.len == 0 or mediaDownloading(a, jid, id)) return false;
    const slot = freeMediaSlot(a) orelse return false;
    slot.jid.set(jid);
    slot.id.set(id);
    slot.started_ms = win.GetTickCount64();
    return enqueueHubMedia(a, slot);
}

fn startHubAvatar(a: *App, target: AvatarTarget) bool {
    if (a.hub_account.len == 0 or wacliPendingGet(a, .hub_avatar) > 0) return false;
    const entry = switch (target) {
        .chat => |index| if (index < a.avatar_count) &a.avatars[index] else return false,
        .participant => |index| if (index < a.participant_avatar_count) &a.participant_avatars[index] else return false,
    };
    entry.refresh = false;
    const destination = std.unicode.utf16LeToUtf8Alloc(a.allocator, entry.path.slice()) catch return false;
    defer a.allocator.free(destination);
    var job = WacliJob{ .kind = .hub_avatar, .account = a.cache_tag, .jid = entry.jid };
    wacliJobArgs(&job, &.{destination});
    if (entry.workspace_icon) job.extra.set("workspace-icon");
    if (!wacliEnqueue(a, job, false)) return false;
    a.avatar_active_index = target;
    if (entry.status == .unknown) entry.status = .loading;
    a.avatar_batch_fetched += 1;
    return true;
}

fn applyHubResult(a: *App, result: *const WacliResult) void {
    switch (result.kind) {
        .hub_thread => applyHubThreadPage(a, result),
        .hub_older => applyHubOlderPage(a, result),
        .hub_send => {
            if (a.pending_send_count == 0 or !std.mem.eql(u8, &a.pending_sends[0].id, result.msg_id.slice())) return;
            if (result.ok) {
                removeFirstPendingSend(a, true);
                refreshChats(a);
                refreshMessages(a);
                setStatus(a, "Sent");
            } else if ((a.pending_sends[0].provider == .signal and (result.http_status == 429 or result.http_status == 403)) or (a.pending_sends[0].provider == .telegram and result.http_status == 429)) {
                const reason = if (result.extra.len > 0 and !std.mem.eql(u8, result.extra.slice(), "HubHttpFailed")) result.extra.slice() else if (a.pending_sends[0].provider == .telegram) "Telegram send rejected" else "Signal send rejected";
                a.pending_sends[0].failure_reason.set(reason);
                const failed = a.pending_sends[0];
                markPendingSendFailed(a, &failed);
                rememberFailedSend(a, &failed);
                removeFirstPendingSend(a, false);
                restoreFailedSendText(a, &failed);
                setStatus(a, reason);
                if (a.pending_send_count > 0) startNextSend(a);
            } else if (result.http_status == 409) {
                failHeadPendingSend(a, 409, true, "delivery unknown", false);
                _ = persistOutbox(a);
            } else if (result.http_status >= 500 or result.http_status == 200 or
                (result.http_status == 0 and std.mem.eql(u8, result.extra.slice(), "NetworkFailed")))
            {
                const pending = &a.pending_sends[0];
                pending.retries +|= 1;
                pending.ambiguous = true;
                pending.not_before_ms = win.GetTickCount64() + (sendRetryDelayMs(pending.retries) orelse 60_000);
                _ = persistOutbox(a);
                markPendingSendRetrying(a, pending);
                setStatus(a, "Hub unavailable; queued message will retry");
            } else {
                failHeadPendingSend(a, result.http_status, false, "hub send rejected", result.http_status == 401 or result.http_status == 403);
            }
        },
        .hub_read => {
            if (a.pending_read_count == 0 or !chat_key.Key.eql(.{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = a.pending_reads[0].slice() }, chat_key.of(result))) return;
            if (result.ok) removeFirstPendingRead(a) else requeueFailedRead(a);
            refreshChats(a);
        },
        .hub_archive => {
            if (a.pending_archive_count == 0 or !chat_key.Key.eql(.{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = a.pending_archives[0].jid.slice() }, chat_key.of(result))) return;
            if (result.ok) {
                removeFirstPendingArchive(a);
                refreshChats(a);
                setStatus(a, "Archive operation completed");
            } else {
                if (result.http_status == 502 and (std.mem.startsWith(u8, result.jid.slice(), "signal:") or std.mem.startsWith(u8, result.jid.slice(), "telegram:"))) {
                    removeFirstPendingArchive(a);
                    refreshChats(a);
                    setStatus(a, "Chat archive is managed locally in Wazig");
                } else {
                    a.pending_archives[0].retry_at_ms = win.GetTickCount64() + 3_000;
                    setStatus(a, "Archive operation failed; retrying");
                }
            }
        },
        .hub_media => {
            for (&a.media_downloads) |*slot| {
                if (!slot.hub_pending or !chat_key.Key.eql(.{ .provider = .whatsapp, .account = a.cache_tag.slice(), .id = slot.jid.slice() }, chat_key.of(result)) or !std.mem.eql(u8, slot.id.slice(), result.msg_id.slice())) continue;
                if (result.ok and result.http_status == 202 and win.GetTickCount64() -| slot.started_ms < 120_000) {
                    slot.hub_retry_ms = win.GetTickCount64() + 1000;
                    return;
                }
                slot.hub_pending = false;
                const ok = result.ok and result.http_status != 202;
                if (ok) {
                    markMediaAttempted(a, slot.jid.slice(), slot.id.slice());
                    clearMediaFailure(a, slot.jid.slice(), slot.id.slice());
                } else {
                    noteMediaFailure(a, slot.jid.slice(), slot.id.slice());
                    setStatus(a, if (result.http_status == 202) "Media download timed out" else "Media download failed");
                    if (std.mem.eql(u8, slot.id.slice(), a.audio_chain_id.slice())) a.audio_chain_waiting = false;
                }
                image_viewer.downloadFinished(a, slot.jid.slice(), slot.id.slice(), ok);
                refreshMessages(a);
                slot.* = .{};
                break;
            }
        },
        .hub_avatar => {
            if (a.avatar_active_index) |target| {
                const entry = switch (target) {
                    .chat => |index| if (index < a.avatar_count) &a.avatars[index] else return,
                    .participant => |index| if (index < a.participant_avatar_count) &a.participant_avatars[index] else return,
                };
                applyAvatarResult(a, entry, if (result.ok) .ready else if (result.http_status == 404) .unavailable else .failed);
            }
            a.avatar_active_index = null;
            if (a.avatar_batch_active) endAvatarBatch(a);
            if (a.chats_hwnd) |list| _ = win.InvalidateRect(list, null, win.FALSE);
        },
        else => {},
    }
}

fn readHubChats(a: *App, archived: bool) ?[]u8 {
    var arena = std.heap.ArenaAllocator.init(a.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();
    a.wacli_mutex.lockUncancelable(a.io);
    const account = a.hub_account;
    a.wacli_mutex.unlock(a.io);
    const request = if (unifiedHub(a)) hub.chats(allocator, archived, 250) catch return null else wa_hub.chats(allocator, account.slice(), archived, 250) catch return null;
    const client = a.hub_client orelse return null;
    var response = client.call(allocator, request) catch return null;
    defer response.deinit(allocator);
    if (response.status != 200) return null;
    const normalized = if (unifiedHub(a) and archived) blk: {
        const inbox = client.call(allocator, hub.chats(allocator, false, 250) catch return null) catch return null;
        if (inbox.status != 200) return null;
        break :blk hub.archivedChats(allocator, response.body, inbox.body) catch return null;
    } else if (unifiedHub(a)) hub.normalize(allocator, response.body, .chats, "") catch return null else wa_hub.normalize(allocator, response.body, account.slice(), .chats) catch return null;
    return a.allocator.dupe(u8, normalized) catch null;
}

fn startHubEvents(a: *App) void {
    if (a.hub_thread != null or a.hub_stop.load(.acquire)) return;
    a.hub_thread = std.Thread.spawn(.{ .stack_size = 256 * 1024 }, hubEventsMain, .{a}) catch null;
}

fn hubEventsMain(a: *App) void {
    const allocator = std.heap.page_allocator;
    var sse = wa_hub.Sse{};
    while (!a.hub_stop.load(.acquire)) {
        hubEventSession(a, allocator, &sse) catch {};
        var wait: usize = 0;
        while (wait < 10 and !a.hub_stop.load(.acquire)) : (wait += 1) win.Sleep(100);
    }
}

fn postHubEvent(a: *App, reset: bool) void {
    if (reset) a.hub_reset_pending.store(true, .release);
    if (!a.hub_event_pending.swap(true, .acq_rel)) {
        const posted = if (a.hwnd) |hwnd| win.PostMessageW(hwnd, wm_hub_event, 0, 0) != 0 else false;
        if (!posted) a.hub_event_pending.store(false, .release);
    }
}

fn hubEventSession(a: *App, allocator: std.mem.Allocator, sse: *wa_hub.Sse) !void {
    const client = a.hub_client orelse return error.HubNotConfigured;
    const stream = try client.open(allocator, if (unifiedHub(a)) hub.events(sse.lastId()) else wa_hub.events(sse.lastId()), &a.hub_cancel);
    defer stream.deinit();
    if (stream.status != 200) return error.HubHttpFailed;
    postHubEvent(a, true);
    sse.len = 0;
    var buffer: [4096]u8 = undefined;
    while (!a.hub_stop.load(.acquire)) {
        const count = try stream.read(&buffer);
        if (count == 0) return;
        for (buffer[0..count]) |byte| {
            if (try sse.push(byte)) |frame| {
                var event = (try sse.parse(allocator, frame)) orelse continue;
                defer event.deinit();
                postHubEvent(a, std.mem.eql(u8, event.value.kind, "reset"));
            }
        }
    }
}

fn loadWaBridgeKey(init: std.process.Init) ?[]u8 {
    const allocator = init.gpa;
    const stored = slack_win.loadSecret(allocator, lit("WaBridgeKey"));
    defer if (stored) |secret| allocator.free(secret.value);
    const path = if (init.environ_map.get("USERPROFILE")) |profile| std.fs.path.join(allocator, &.{ profile, ".wacli", "bridge-send.key" }) catch null else null;
    defer if (path) |p| allocator.free(p);
    const file_key = if (path) |p| readFileWin(allocator, p, 4096) else null;
    defer if (file_key) |bytes| allocator.free(bytes);
    const environment = slack_win.loadUserEnvironment(allocator, lit("WA_BRIDGE_KEY"));
    defer if (environment) |value| allocator.free(value);
    const plain = std.mem.trim(u8, environment orelse file_key orelse "", " \t\r\n");
    if (plain.len > 0) {
        if (!slack_win.saveSecret(lit("WaBridgeKey"), plain)) return null;
        const key = allocator.dupe(u8, plain) catch return null;
        if (file_key != null) deleteFileUtf8(path.?);
        var user_environment: win.HKEY = null;
        if (win.RegOpenKeyExW(winHandle(win.HKEY, 0x80000001), lit("Environment"), 0, win.KEY_SET_VALUE, &user_environment) == win.ERROR_SUCCESS) {
            defer _ = win.RegCloseKey(user_environment);
            _ = win.RegDeleteValueW(user_environment, lit("WA_BRIDGE_KEY"));
        }
        _ = win.SetEnvironmentVariableW(lit("WA_BRIDGE_KEY"), null);
        return key;
    }
    if (stored) |secret| {
        if (secret.outcome == .migration_failed) return null;
        return allocator.dupe(u8, secret.value) catch null;
    }
    return null;
}

fn providerStatePath(a: *App, name: []const u8) ?[]u8 {
    if (!unifiedHub(a)) return messagesDirPath(a, name);
    const scoped = std.fmt.allocPrint(a.allocator, "hub-{s}-{s}", .{ a.cache_tag.slice(), name }) catch return null;
    defer a.allocator.free(scoped);
    return messagesDirPath(a, scoped);
}

fn configureHub(a: *App, init: std.process.Init) void {
    const allocator = a.allocator;
    const url = environment_keys.load(allocator, "WAZIG_HUB_URL", init.environ_map.get("WAZIG_HUB_URL")) catch return;
    if (!hub.selected(url)) {
        allocator.free(url);
        return;
    }
    a.unified_hub = true;
    a.wa_bridge_url = url;
    const seed = environment_keys.load(allocator, "WAZIG_HUB_TOKEN", init.environ_map.get("WAZIG_HUB_TOKEN")) catch return;
    defer allocator.free(seed);
    if (seed.len > 0) {
        if (!slack_win.saveSecret(lit("HubToken"), seed)) return;
        a.wa_bridge_key = allocator.dupe(u8, seed) catch return;
    } else {
        const stored = slack_win.loadSecret(allocator, lit("HubToken")) orelse return;
        if (stored.outcome == .migration_failed) {
            allocator.free(stored.value);
            return;
        }
        a.wa_bridge_key = stored.value;
    }
    if (a.wa_bridge_key.len == 0 or std.mem.indexOfAny(u8, a.wa_bridge_key, "\r\n") != null) return;
    const endpoint = wa_hub.Endpoint.parse(url, verification_fixture) catch return;
    a.hub_client = .{ .endpoint = endpoint, .key = a.wa_bridge_key };
    appendLaunchLog(a, "message backend: hub");
    if (messagesDirPath(a, "hub-media")) |dir| {
        defer allocator.free(dir);
        std.Io.Dir.cwd().createDirPath(a.io, dir) catch {};
    }
}

fn unifiedHubRequest(a: *App, allocator: std.mem.Allocator, job: *const WacliJob) !hub.Request {
    const jid = job.jid.slice();
    return switch (job.kind) {
        .chats, .archived_scan, .kept_check, .contacts_index => hub.chats(allocator, hubHasArg(job, "--archived"), 500),
        .messages, .background_media => hub.messages(allocator, jid, std.fmt.parseInt(usize, hubArg(job, "--limit", "80"), 10) catch 80, ""),
        .unread_probe => hub.messages(allocator, jid, 20, ""),
        .reaction => hub.react(allocator, jid, job.msg_id.slice(), job.extra.slice(), job.client_id.slice()),
        .hub_read => hub.markRead(allocator, jid, job.msg_id.slice()),
        .hub_archive => hub.archive(allocator, jid, std.mem.eql(u8, job.extra.slice(), "true")),
        .hub_media => hub.binary(allocator, jid, job.msg_id.slice()),
        .hub_avatar => if (std.mem.eql(u8, job.extra.slice(), "workspace-icon")) hub.workspaceIcon(allocator, jid[6 .. jid.len - 1]) else hub.binary(allocator, jid, null),
        .hub_send => blk: {
            if (job.args[1].len == 0) break :blk hub.send(allocator, jid, job.args[0].slice(), job.args[2].slice(), job.msg_id.slice());
            const bytes = readFileWin(allocator, job.args[1].slice(), wa_hub.max_file_bytes) orelse return error.FileReadFailed;
            defer allocator.free(bytes);
            var random: [16]u8 = undefined;
            a.io.random(&random);
            const boundary = std.fmt.bytesToHex(random, .lower);
            break :blk hub.sendFile(allocator, jid, job.args[0].slice(), job.args[2].slice(), job.msg_id.slice(), std.fs.path.basename(job.args[1].slice()), bytes, std.mem.eql(u8, job.args[3].slice(), "true"), &boundary);
        },
        else => error.UnsupportedHubAction,
    };
}

fn configureWaHub(a: *App, init: std.process.Init) void {
    if (verification_fixture) {
        if (init.environ_map.get("WAZIG_VERIFY_HUB_URL")) |url| {
            if (init.environ_map.get("WAZIG_VERIFY_HUB_KEY")) |seed| {
                if (!slack_win.saveSecret(lit("WaBridgeKey"), seed)) return;
            }
            const wide = std.unicode.utf8ToUtf16LeAllocZ(a.allocator, url) catch return;
            defer a.allocator.free(wide);
            var key: win.HKEY = null;
            if (win.RegCreateKeyExW(winHandle(win.HKEY, 0x80000001), lit("Software\\Messages"), 0, null, 0, win.KEY_SET_VALUE, null, &key, null) == win.ERROR_SUCCESS) {
                defer _ = win.RegCloseKey(key);
                _ = win.RegSetValueExW(key, lit("WaBridgeUrl"), 0, win.REG_SZ, @ptrCast(wide.ptr), @intCast((wide.len + 1) * 2));
            }
        }
    }
    a.wa_bridge_url = loadRegistryString(a.allocator, lit("WaBridgeUrl")) orelse "";
    a.wa_bridge_account = loadRegistryString(a.allocator, lit("WaBridgeAccount")) orelse "";
    a.wa_bridge_key = loadWaBridgeKey(init) orelse "";
    const reason: []const u8 = if (!wa_hub.igsh_532_hub_whatsapp) "disabled" else if (a.wa_bridge_url.len == 0) "URL not configured" else if (a.wa_bridge_key.len == 0) "key not configured" else blk: {
        const endpoint = wa_hub.Endpoint.parse(a.wa_bridge_url, verification_fixture) catch break :blk "invalid URL";
        a.hub_client = .{ .endpoint = endpoint, .key = a.wa_bridge_key };
        break :blk "";
    };
    if (hubConfigured(a)) {
        appendLaunchLog(a, "whatsapp backend: hub");
        if (messagesDirPath(a, "hub-media")) |dir| {
            defer a.allocator.free(dir);
            std.Io.Dir.cwd().createDirPath(a.io, dir) catch {};
        }
    } else {
        var buffer: [96]u8 = undefined;
        appendLaunchLog(a, std.fmt.bufPrint(&buffer, "whatsapp backend: wacli ({s})", .{reason}) catch "whatsapp backend: wacli (configuration failed)");
    }
}

const hub_transport_vtable = transport.Transport.VTable{
    .refreshChats = hubRefreshChats,
    .refreshMessages = hubRefreshMessages,
    .sendText = hubSendText,
    .markRead = hubMarkRead,
    .downloadMedia = hubDownloadMedia,
    .archive = hubArchive,
    .react = hubReact,
};

fn hubTransport(a: *App) transport.Transport {
    return .{ .context = a, .vtable = &hub_transport_vtable };
}

fn hubRefreshChats(context: *anyopaque) void {
    refreshChats(@ptrCast(@alignCast(context)));
}

fn hubRefreshMessages(context: *anyopaque, jid: []const u8) void {
    const a: *App = @ptrCast(@alignCast(context));
    if (a.selected_chat < a.chat_count and (unifiedHub(a) or a.chats[a.selected_chat].provider == .whatsapp) and
        (unifiedHub(a) or std.mem.eql(u8, a.chats[a.selected_chat].account.slice(), a.cache_tag.slice())) and std.mem.eql(u8, a.chats[a.selected_chat].jid.slice(), jid)) refreshMessages(a);
}

fn hubSendText(context: *anyopaque, jid: []const u8, text: []const u8, client_id: []const u8) bool {
    const a: *App = @ptrCast(@alignCast(context));
    var job = WacliJob{ .kind = .hub_send, .account = a.cache_tag };
    job.jid.set(jid);
    job.msg_id.set(client_id);
    wacliJobArgs(&job, &.{ text, "", "", "false" });
    return wacliEnqueue(a, job, true);
}

fn hubMarkRead(context: *anyopaque, jid: []const u8, message_id: []const u8) void {
    const a: *App = @ptrCast(@alignCast(context));
    var job = WacliJob{ .kind = .hub_read, .account = a.cache_tag };
    job.jid.set(jid);
    job.msg_id.set(message_id);
    _ = wacliEnqueue(a, job, true);
}

fn hubDownloadMedia(context: *anyopaque, jid: []const u8, id: []const u8) void {
    _ = startHubMedia(@ptrCast(@alignCast(context)), jid, id);
}

fn hubArchive(context: *anyopaque, jid: []const u8, archived: bool) bool {
    const a: *App = @ptrCast(@alignCast(context));
    var job = WacliJob{ .kind = .hub_archive, .account = a.cache_tag };
    job.jid.set(jid);
    job.extra.set(if (archived) "true" else "false");
    return wacliEnqueue(a, job, true);
}

fn hubReact(context: *anyopaque, jid: []const u8, msg: []const u8, emoji: []const u8, client_id: []const u8) bool {
    const a: *App = @ptrCast(@alignCast(context));
    var job = WacliJob{ .kind = .reaction, .account = a.cache_tag };
    job.jid.set(jid);
    job.msg_id.set(msg);
    job.extra.set(emoji);
    job.client_id.set(client_id);
    return wacliEnqueue(a, job, true);
}

fn enqueueHubReaction(a: *App, entry: *PendingReaction) void {
    if (entry.client_id.len == 0) {
        var id: [outbox.id_len]u8 = undefined;
        mintSendId(a, &id);
        entry.client_id.set(&id);
    }
    if (!hubTransport(a).react(entry.jid.slice(), entry.msg_id.slice(), entry.emoji.slice(), entry.client_id.slice())) entry.retry_at_ms = win.GetTickCount64() + 3_000;
}

fn hubJobReady(a: *const App, job: WacliJob) bool {
    return job.kind == .cache_tag or a.hub_account.len > 0;
}

test "hub send conflict schedules bounded ambiguous recovery without blocking later sends" {
    const a = try std.testing.allocator.create(App);
    defer std.testing.allocator.destroy(a);
    a.* = .{
        .allocator = std.testing.allocator,
        .people = people_index.Index.init(std.testing.allocator),
        .io = std.testing.io,
        .instance = null,
        .wacli_path = &.{},
        .avatar_dir = &.{},
        .hub_client = .{ .endpoint = .{ .host = "", .port = 443, .secure = true }, .key = "" },
    };
    a.hub_stop.store(true, .release);
    a.pending_send_count = 2;
    a.pending_sends[1].id = @splat('1');
    var result = WacliResult{ .kind = .hub_send, .http_status = 409 };
    result.msg_id.set(&a.pending_sends[0].id);
    const before = win.GetTickCount64();
    applyHubResult(a, &result);
    try std.testing.expectEqual(@as(usize, 2), a.pending_send_count);
    try std.testing.expect(a.pending_sends[0].ambiguous);
    try std.testing.expectEqual(@as(u8, 1), a.pending_sends[0].retries);
    try std.testing.expect(a.pending_sends[0].not_before_ms >= before + 3_000);
    try std.testing.expect(a.pending_sends[0].not_before_ms <= win.GetTickCount64() + 3_000);
    try std.testing.expectEqual(@as(u8, '1'), a.pending_sends[1].id[0]);
}

test "IGSH-575 uncached timestamped hub selection clears the pane and applies its result" {
    const a = try std.testing.allocator.create(App);
    defer std.testing.allocator.destroy(a);
    a.* = .{
        .allocator = std.testing.allocator,
        .people = people_index.Index.init(std.testing.allocator),
        .io = std.testing.io,
        .instance = null,
        .wacli_path = &.{},
        .avatar_dir = &.{},
        .hub_client = .{ .endpoint = .{ .host = "", .port = 443, .secure = true }, .key = "" },
    };
    a.chats = try a.allocator.alloc(Chat, 1);
    defer a.allocator.free(a.chats);
    a.chats[0] = .{};
    a.cache_tag.set("aaaaaaaaaaaaaaaa");
    a.chats[0].account = a.cache_tag;
    a.chats[0].jid.set("fixture-beta@g.us");
    a.chats[0].timestamp.set("2026-01-01T00:00:00Z");
    a.chat_count = 1;
    a.displayed_account = a.cache_tag;
    a.displayed_jid.set("fixture-alpha@g.us");
    a.message_count = 1;
    a.messages[0].id.set("ALPHA");

    refreshMessages(a);
    try std.testing.expectEqual(@as(usize, 0), a.message_count);
    try std.testing.expect(chat_key.Key.eql(chat_key.of(&a.chats[0]), chat_key.displayed(a)));

    a.hub_account.set("personal");
    const result = try a.allocator.create(WacliResult);
    result.* = .{ .kind = .messages, .account = a.cache_tag, .jid = a.chats[0].jid, .gen = a.messages_gen, .ok = true };
    result.data = try a.allocator.dupe(u8, "{\"data\":{\"messages\":[{\"MsgID\":\"BETA\",\"Text\":\"Fixture Beta\"}]}}");
    const previous = app_ptr;
    defer app_ptr = previous;
    app_ptr = a;
    _ = mainProc(@ptrFromInt(1), wm_wacli_done, 0, @bitCast(@intFromPtr(result)));
    defer for (a.msg_cache[0..a.msg_cache_len]) |entry| {
        if (entry.data) |data| a.allocator.free(data);
    };
    try std.testing.expectEqual(@as(usize, 1), a.message_count);
    try std.testing.expectEqualStrings("BETA", a.messages[0].id.slice());
    try std.testing.expect(chat_key.Key.eql(chat_key.of(&a.chats[0]), chat_key.displayed(a)));
}

test "hub stream open reset survives event coalescing without a reset frame" {
    const a = try std.testing.allocator.create(App);
    defer std.testing.allocator.destroy(a);
    a.hub_reset_pending = .init(false);
    a.hub_event_pending = .init(true);
    postHubEvent(a, true);
    try std.testing.expect(a.hub_reset_pending.load(.acquire));
    try std.testing.expect(a.hub_event_pending.load(.acquire));
    a.hub_event_pending.store(false, .release);
    a.hub_reset_pending.store(false, .release);
    a.hwnd = null;
    postHubEvent(a, true);
    try std.testing.expect(a.hub_reset_pending.load(.acquire));
    try std.testing.expect(!a.hub_event_pending.load(.acquire));
}

fn slackThreadsAccount(a: *const App) []const u8 {
    if (a.selected_chat >= a.chat_count or a.chats[a.selected_chat].provider != .slack) return "";
    const chat = &a.chats[a.selected_chat];
    return if (chat.view_account.len > 0) chat.view_account.slice() else chat.account.slice();
}

fn slackThreadsEnabled(a: *App) bool {
    const account = slackThreadsAccount(a);
    if (account.len == 0) return false;
    if (!std.mem.eql(u8, account, a.threads_account.slice())) {
        const key = slack.threadsSettingKey(a.allocator, account) catch return true;
        defer a.allocator.free(key);
        const wide = utf8ToWide(a.allocator, key) catch return true;
        defer a.allocator.free(wide);
        const value = loadRegistryString(a.allocator, wide.ptr);
        defer if (value) |text| a.allocator.free(text);
        a.threads_enabled = slack.threadsSetting(value);
        a.threads_account.set(account);
    }
    return a.threads_enabled;
}

fn toggleSlackThreads(a: *App) void {
    if (slackThreadsAccount(a).len == 0) return;
    const enabled = !slackThreadsEnabled(a);
    const key = slack.threadsSettingKey(a.allocator, slackThreadsAccount(a)) catch return;
    defer a.allocator.free(key);
    const wide = utf8ToWide(a.allocator, key) catch return;
    defer a.allocator.free(wide);
    if (!saveRegistryString(a.allocator, wide.ptr, slack.threadsSettingValue(enabled))) return setStatus(a, "Could not save Slack threads preference");
    a.threads_enabled = enabled;
    closeSlackThread(a);
    a.selected_message = null;
    a.scroll_y = 0;
    a.slack_history_hash = 0;
    a.msg_applied_hash = 0;
    refreshMessages(a);
    if (a.canvas) |canvas| _ = win.InvalidateRect(canvas, null, win.TRUE);
}

fn channelMessageVisible(a: *App, message: *const Message) bool {
    return !slackThreadsEnabled(a) or !slack.isThreadReply(message.id.slice(), message.thread_ts.slice());
}

fn threadReplyCount(a: *const App, parent: *const Message) usize {
    var loaded: usize = 0;
    for (a.thread_rows.items) |*message| {
        if (slack.isThreadReply(message.id.slice(), message.thread_ts.slice()) and std.mem.eql(u8, parent.id.slice(), message.thread_ts.slice())) loaded += 1;
    }
    return @max(parent.reply_count, loaded);
}

fn threadLatestReply(a: *const App, parent: *const Message) []const u8 {
    var latest = parent.latest_reply.slice();
    for (a.thread_rows.items) |*message| {
        if (std.mem.eql(u8, parent.id.slice(), message.thread_ts.slice()) and slack.compareTs(message.id.slice(), latest) == .gt) latest = message.id.slice();
    }
    return latest;
}

fn threadSummaryHeight(a: *App, message: *const Message) i32 {
    return if (slackThreadsEnabled(a) and !slack.isThreadReply(message.id.slice(), message.thread_ts.slice()) and threadReplyCount(a, message) > 0) @max(px(a, 40), @as(i32, @intCast(@abs(scaledFontHeight(13, a.font_scale, @intCast(a.dpi))))) * 2 + px(a, 8)) else 0;
}

fn threadPanelWidth(a: *const App, width: i32, left_width: i32) i32 {
    return if (a.thread_parent.len > 0) @divTrunc(width - left_width - 1, 2) else 0;
}

fn closeSlackThread(a: *App) void {
    if (a.thread_parent.len == 0) return;
    a.thread_parent.set("");
    if (a.thread_list) |hwnd| _ = win.DestroyWindow(hwnd);
    if (a.thread_compose) |hwnd| _ = win.DestroyWindow(hwnd);
    a.thread_list = null;
    a.thread_compose = null;
    a.thread_panel_hash = 0;
    a.thread_panel_replies = 0;
    layout(a, a.compose_client_width, a.compose_client_height);
    focusCompose(a);
}

fn openSlackThread(a: *App, selected: usize) void {
    if (!slackThreadsEnabled(a) or selected >= a.message_count or a.hwnd == null) return;
    const message = &a.messages[selected];
    var parent = Utf8Text(191){};
    parent.set(if (slack.isThreadReply(message.id.slice(), message.thread_ts.slice())) message.thread_ts.slice() else message.id.slice());
    closeSlackThread(a);
    a.thread_origin = drafts.Identity.init(chat_key.of(&a.chats[a.selected_chat]));
    a.thread_parent = parent;
    rememberSlackThreadRow(a, message);
    a.thread_list = directwrite_edit.create(a.instance, a.hwnd.?, controlId(id_thread_list), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.ES_MULTILINE | win.ES_READONLY | win.ES_AUTOVSCROLL | win.WS_VSCROLL, 0, 0, 0, 0);
    a.thread_compose = directwrite_edit.create(a.instance, a.hwnd.?, controlId(id_thread_compose), win.WS_CHILD | win.WS_VISIBLE | win.WS_TABSTOP | win.ES_MULTILINE | win.ES_AUTOVSCROLL, 0, 0, 0, 0);
    if (a.thread_list == null or a.thread_compose == null) {
        closeSlackThread(a);
        return;
    }
    setFont(a.thread_list, a.font);
    setFont(a.thread_compose, a.font);
    _ = win.SendMessageW(a.thread_compose.?, win.EM_SETLIMITTEXT, drafts.max_text, 0);
    layout(a, a.compose_client_width, a.compose_client_height);
    refreshSlackThreadPanel(a);
    if (unifiedHub(a)) requestHubThreadPage(a, "") else requestSlackThread(a, parent.slice(), "");
    _ = win.SetFocus(a.thread_compose.?);
}

fn requestSlackThread(a: *App, parent: []const u8, cursor: []const u8) void {
    if (!selectedChatIsSlack(a) or unifiedHub(a)) return;
    const chat = &a.chats[a.selected_chat];
    var job = WacliJob{ .provider = .slack, .kind = .slack_replies, .gen = a.messages_gen, .account = chat.account, .jid = chat.jid };
    job.msg_id.set(parent);
    wacliJobArgs(&job, &.{ chat.jid.slice(), parent, cursor });
    _ = wacliEnqueue(a, job, false);
}

fn refreshSlackThreadPanel(a: *App) void {
    const list = a.thread_list orelse return;
    if (a.selected_chat >= a.chat_count or !chat_key.Key.eql(a.thread_origin.key(), chat_key.of(&a.chats[a.selected_chat]))) {
        closeSlackThread(a);
        return;
    }
    var text = std.Io.Writer.Allocating.init(a.allocator);
    defer text.deinit();
    var replies: usize = 0;
    for ([_]bool{ true, false }) |parent_pass| {
        for (a.thread_rows.items) |*message| {
            const is_parent = std.mem.eql(u8, message.id.slice(), a.thread_parent.slice());
            if (parent_pass != is_parent or !slack.inThread(message.id.slice(), message.thread_ts.slice(), a.thread_parent.slice())) continue;
            if (!is_parent) replies += 1;
            const sender = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.sender.slice()) catch return;
            defer a.allocator.free(sender);
            const body = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.text.slice()) catch return;
            defer a.allocator.free(body);
            const time = std.unicode.utf16LeToUtf8Alloc(a.allocator, message.time.slice()) catch return;
            defer a.allocator.free(time);
            text.writer.print("{s}  {s}\r\n{s}\r\n\r\n", .{ sender, time, body }) catch return;
        }
    }
    const hash = std.hash.Wyhash.hash(0, text.written());
    if (hash == a.thread_panel_hash) return;
    const wide = utf8ToWide(a.allocator, text.written()) catch return;
    defer a.allocator.free(wide);
    if (win.SetWindowTextW(list, wide.ptr) == 0) return;
    a.thread_panel_hash = hash;
    a.thread_panel_replies = replies;
}

fn controlSlackThreads(a: *App, w: *std.Io.Writer) !void {
    if (slackThreadsAccount(a).len == 0) return;
    const enabled = slackThreadsEnabled(a);
    var parent: ?*const Message = null;
    var inline_replies: usize = 0;
    for (a.messages[0..a.message_count]) |*message| {
        if (slack.isThreadReply(message.id.slice(), message.thread_ts.slice())) {
            if (channelMessageVisible(a, message)) inline_replies += 1;
        } else if (threadReplyCount(a, message) > 0 and (parent == null or std.mem.eql(u8, message.id.slice(), a.thread_parent.slice()))) parent = message;
    }
    var line_buffer: [64]u8 = undefined;
    try w.writeAll(",\"slack_threads\":{\"parent_id\":");
    try control_api.writeString(w, if (parent) |message| message.id.slice() else "");
    try w.writeAll(",\"parent_reply_line\":");
    try control_api.writeString(w, if (enabled and parent != null) slack.repliesLine(&line_buffer, threadReplyCount(a, parent.?)) else "");
    try w.print(",\"inline_replies\":{d},\"replies\":{d},\"open\":{},\"threads_option\":\"{s}\"}}", .{ inline_replies, a.thread_panel_replies, a.thread_list != null, slack.threadsSettingValue(enabled) });
}

fn rememberSlackThreadRow(a: *App, message: *const Message) void {
    if (message.send_state != .none or a.selected_chat >= a.chat_count) return;
    const key = chat_key.of(&a.chats[a.selected_chat]);
    if (!chat_key.Key.eql(a.thread_rows_origin.key(), key)) {
        a.thread_rows.clearRetainingCapacity();
        a.thread_rows_origin = drafts.Identity.init(key);
    }
    if (message.thread_ts.len == 0 and message.reply_count == 0 and !std.mem.eql(u8, message.id.slice(), a.thread_parent.slice())) return;
    const row = SlackThreadRow{ .id = message.id, .thread_ts = message.thread_ts, .sender = message.sender, .text = message.text, .time = message.time, .timestamp = message.timestamp };
    for (a.thread_rows.items) |*existing| {
        if (std.mem.eql(u8, existing.id.slice(), row.id.slice())) {
            existing.* = row;
            return;
        }
    }
    a.thread_rows.append(a.allocator, row) catch return;
    var index = a.thread_rows.items.len - 1;
    while (index > 0 and slack.compareTs(a.thread_rows.items[index - 1].id.slice(), row.id.slice()) == .gt) : (index -= 1) {
        a.thread_rows.items[index] = a.thread_rows.items[index - 1];
    }
    a.thread_rows.items[index] = row;
}

fn requestHubThreadPage(a: *App, before: []const u8) void {
    if (!unifiedHub(a) or a.thread_parent.len == 0 or a.selected_chat >= a.chat_count or wacliPendingGet(a, .hub_thread) > 0) return;
    var loaded: usize = 0;
    for (a.thread_rows.items) |*row| {
        if (slack.isThreadReply(row.id.slice(), row.thread_ts.slice()) and std.mem.eql(u8, row.thread_ts.slice(), a.thread_parent.slice())) loaded += 1;
    }
    for (a.messages[0..a.message_count]) |*message| {
        if (std.mem.eql(u8, message.id.slice(), a.thread_parent.slice()) and loaded >= message.reply_count) return;
    }
    const chat = &a.chats[a.selected_chat];
    var job = WacliJob{ .kind = .hub_thread, .provider = .slack, .account = chat.account, .jid = chat.jid, .gen = a.messages_gen, .msg_id = a.thread_parent };
    job.extra.set(before);
    _ = wacliEnqueue(a, job, false);
}

fn applyHubThreadPage(a: *App, result: *const WacliResult) void {
    if (!result.ok or a.thread_parent.len == 0) return;
    if (!std.mem.eql(u8, a.thread_parent.slice(), result.msg_id.slice()) or !chat_key.Key.eql(a.thread_origin.key(), chat_key.of(result))) {
        requestHubThreadPage(a, "");
        return;
    }
    var parsed = std.json.parseFromSlice(std.json.Value, a.allocator, result.data, .{}) catch return;
    defer parsed.deinit();
    const data = parsed.value.object.get("data") orelse return;
    const messages = data.object.get("messages") orelse return;
    var oldest: []const u8 = "";
    for (messages.array.items) |item| {
        if (item != .object) continue;
        const object = item.object;
        const stamp = getString(object, "Timestamp");
        if (stamp.len > 0 and (oldest.len == 0 or std.mem.order(u8, stamp, oldest) == .lt)) oldest = stamp;
        var message = Message{};
        message.id.set(getString(object, "MsgID"));
        message.thread_ts.set(getString(object, "thread_ts"));
        message.sender.set(a.allocator, if (getBool(object, "FromMe")) "You" else getString(object, "SenderName"));
        var text = getString(object, "DisplayText");
        if (text.len == 0) text = getString(object, "Text");
        if (slack.isThreadReply(message.id.slice(), message.thread_ts.slice())) {
            if (splitQuote(text, getString(object, "Text"))) |parts| text = parts.body;
        }
        const lookup = if (slackInstallation(a, result.account.slice())) |installation| slackUserLookup(installation) else null;
        importCustomEmoji(a, result.jid.slice(), object);
        setSlackMessageText(a, &message, text, lookup);
        message.timestamp.set(stamp);
        formatTime(&message.time, a.allocator, stamp);
        rememberSlackThreadRow(a, &message);
    }
    refreshSlackThreadPanel(a);
    if (oldest.len > 0 and (result.extra.len == 0 or std.mem.order(u8, oldest, result.extra.slice()) == .lt)) requestHubThreadPage(a, oldest);
}

fn hubOlderFor(a: *App, key: chat_key.Key) *HubOlder {
    const older = &a.hub_older;
    if (!chat_key.Key.eql(older.origin.key(), key)) {
        if (older.rows) |rows| a.allocator.free(rows);
        older.* = .{};
        older.origin.set(key);
    }
    return older;
}

fn storeHubOlder(a: *App, key: chat_key.Key, rows: []const std.json.Value) void {
    const text = std.json.Stringify.valueAlloc(a.allocator, rows, .{}) catch return;
    const older = hubOlderFor(a, key);
    if (older.rows) |previous| a.allocator.free(previous);
    older.rows = text;
}

fn requestHubOlder(a: *App) void {
    if (!unifiedHub(a) or a.message_count == 0 or a.message_count >= max_messages or a.selected_chat >= a.chat_count or wacliPendingGet(a, .hub_older) > 0) return;
    const chat = &a.chats[a.selected_chat];
    const key = chat_key.of(chat);
    if (chat.provider != .whatsapp or !chat_key.Key.eql(chat_key.displayed(a), key)) return;
    if (hubOlderFor(a, key).exhausted) return;
    var oldest: ?*const Message = null;
    for (a.messages[0..a.message_count]) |*message| {
        if (message.send_state != .none or message.id.len == 0 or message.timestamp.len == 0) continue;
        if (oldest == null or std.mem.order(u8, message.timestamp.slice(), oldest.?.timestamp.slice()) == .lt) oldest = message;
    }
    const first = oldest orelse return;
    var job = WacliJob{ .kind = .hub_older, .provider = .whatsapp, .account = chat.account, .jid = chat.jid, .gen = a.messages_gen, .msg_id = first.id };
    job.extra.set(first.timestamp.slice());
    _ = wacliEnqueue(a, job, false);
}

fn applyHubOlderPage(a: *App, result: *const WacliResult) void {
    if (!unifiedHub(a) or !result.ok or a.selected_chat >= a.chat_count) return;
    const key = chat_key.of(&a.chats[a.selected_chat]);
    if (!chat_key.Key.eql(key, chat_key.of(result)) or !chat_key.Key.eql(key, chat_key.displayed(a))) return;
    var arena = std.heap.ArenaAllocator.init(a.allocator);
    defer arena.deinit();
    const allocator = arena.allocator();
    const older = hubOlderFor(a, key);
    const page = std.json.parseFromSlice(std.json.Value, allocator, result.data, .{ .allocate = .alloc_always }) catch return;
    const page_rows = hub.messageRows(page.value) orelse return;
    var current: []const std.json.Value = &.{};
    if (older.rows) |kept_text| {
        const kept = std.json.parseFromSlice(std.json.Value, allocator, kept_text, .{ .allocate = .alloc_always }) catch return;
        if (kept.value != .array) return;
        current = kept.value.array.items;
    } else {
        const cached = msgCacheGet(a, key) orelse return;
        const base = std.json.parseFromSlice(std.json.Value, allocator, cached, .{ .allocate = .alloc_always }) catch return;
        current = hub.messageRows(base.value) orelse return;
    }
    var united: std.ArrayList(std.json.Value) = .empty;
    const added = hub.unite(allocator, current, page_rows, &united) catch return;
    if (added == 0) {
        older.exhausted = true;
        return;
    }
    storeHubOlder(a, key, united.items);
    const stored_text = older.rows orelse return;
    const raw = std.fmt.allocPrint(a.allocator, "{{\"data\":{{\"messages\":{s}}}}}", .{stored_text}) catch return;
    defer a.allocator.free(raw);
    _ = applyMessageData(a, raw, false);
    a.msg_applied_hash = 0;
}
